class Stop(Exception):
    pass


class Silent(Stop):
    """A required PR reviewer posted nothing within the settle after the pipeline went green: a refusal of its own,
    exit 3, which the lane escalates to the lead rather than waiting again."""


SILENT_EXIT = 3
PR_REVIEW_BLOCK = "pr-review"  # the --blocked label a lane hands off with when a reviewer is silent


class Transient(Stop):
    """An adapter's transient failure: it exited 75 (EX_TEMPFAIL) for a timeout, a connection error, or an HTTP 5xx or
    429. A PR-review wait's loop tries it again; everywhere else it refuses at once, as any Stop does."""


class Terminated(SystemExit):
    """A stop by SIGTERM or SIGHUP. It exits as SystemExit does, and code that takes a module's own exit as a failed
    load re-raises it, so a stop that lands while a module loads is never lost."""


def _terminate(signum, _frame):
    # A kill from the agent's tool timeout becomes an exception, so `finally` blocks stop processes and leases.
    raise Terminated(128 + signum)





# Hosted publishing has its own process and private credential handoff. Generic
# subprocesses inherit no publishing token, including bootstrap git/node calls.
HOSTED_CLOSE_SECONDS = 30
HOSTED_TOKENS: dict[tuple[str, str, str], str] = {}
HOSTED_MODULES = {}
HOSTED_BOOTSTRAPPING = True
# Before the binding shelf has named its credential, discovery git receives
# only its OS/session baseline. Arbitrary caller variables cannot cross that
# boundary, including a tokenEnv introduced by a newer remote shelf.
HOSTED_BOOTSTRAP_ENV = frozenset(('PATH HOME TMPDIR TMP TEMP LANG LC_ALL LC_CTYPE TZ USER LOGNAME '
                                'SYSTEMROOT WINDIR SSH_AUTH_SOCK SSH_AGENT_PID GIT_CONFIG_GLOBAL '
                                'GIT_CONFIG_SYSTEM GIT_CONFIG_NOSYSTEM GIT_TERMINAL_PROMPT').split())


def remember_hosted(raw):
    member=raw.get('hosted') if isinstance(raw,dict) else None
    if not isinstance(member,dict):return
    name=member.get('tokenEnv')
    if not isinstance(name,str) or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',name):return
    value=os.environ.pop(name,None)
    if value is not None:
        HOSTED_TOKENS[(name,str(member.get('origin','')).rstrip('/'),str(member.get('repositoryId','')))]=value


def quarantine_hosted_checkout(cwd=None):
    here=Path(cwd or os.getcwd()).resolve()
    root=next((p for p in (here,*here.parents) if (p/'.git').exists()),None)
    path=root/'.agents/delivery-views.json' if root else None
    if path and path.is_file() and path.stat().st_size<=1024*1024:
        try:remember_hosted(json.loads(path.read_text()))
        except (ValueError,OSError):pass


def hosted_module(release):
    path=Path(release)/'skills/delivery-views/scripts/hosted.py'
    key=str(path.resolve())
    if key not in HOSTED_MODULES:
        # The hosted script owns its imports and is run as a child for I/O. Its
        # pure sidecar helpers are used here without starting a publisher.
        spec=importlib.util.spec_from_file_location('flow_hosted_'+hashlib.sha256(key.encode()).hexdigest()[:16],path)
        module=importlib.util.module_from_spec(spec);sys.modules[spec.name]=module;spec.loader.exec_module(module)
        HOSTED_MODULES[key]=module
    return HOSTED_MODULES[key]


def hosted_settings(c):
    raw=c.shelf.json('.agents/delivery-views.json') or {}
    remember_hosted(raw)
    if raw.get('hosted') is None:return None
    try:
        module=hosted_module(c.release)
        validated=module.views.validate_config(raw)
    except (ValueError,OSError,ImportError):raise Stop('hosted: configuration_invalid') from None
    return raw,validated['hosted']


def hosted_files(c,folder):
    """The publisher's configuration and binding, written into the record folder it publishes."""
    settings=hosted_settings(c)
    if settings is None:return None
    raw,member=settings;module=hosted_module(c.release)
    folder.mkdir(parents=True,exist_ok=True)
    config=folder/'hosted-view-config.json';binding=folder/'hosted-view-binding.json'
    module.atomic(config,raw)
    module.atomic(binding,{'state':{'directory':str(folder)}})
    return module,member,config,binding


def hosted_call(c,operation,folder,key,*,archive=True,resume=False,timeout=5):
    """Run the publisher's `operation` on the record in `folder`, published under `key`: a delivery's record, with its
    archive root, or a plan preview's, which has none."""
    files=hosted_files(c,folder)
    if files is None:return {'state':'disabled'}
    module,member,config,binding=files
    environment=dict(os.environ)
    token=HOSTED_TOKENS.get((member['tokenEnv'],member['origin'],member['repositoryId']))
    if token is not None:environment[member['tokenEnv']]=token
    pointer=c.root/'.agent-skills/current'
    watched=pointer if pointer.exists() and pointer.resolve()==c.release.resolve() else c.release
    command=[sys.executable,'-B',str(c.release/'skills/delivery-views/scripts/hosted.py'),operation,
             '--config',str(config),'--binding',str(binding),'--state-dir',str(folder),'--key',key,
             '--generation',str(watched),'--generation-target',str(c.release.resolve()),
             *(['--archive-root',str(archive_root(c))] if archive else []),'--record-root',str(folder)]
    if resume:command.append('--resume')
    done=run(command,cwd=c.root,check=False,timeout=timeout,env=environment,_publishing=True)
    try:answer=json.loads(done.stdout)
    except ValueError:return {'state':'failed','code':'publisher_unavailable'}
    if done.returncode or not isinstance(answer,dict):return {'state':'failed','code':'publisher_unavailable'}
    return answer


def start_hosted(c,*,resume=False,timeout=5):
    # On a shared record only the seat holding delivery publishes, once it has taken what the seat before it carried.
    if not delivery_publishes(c):return {'state':'held_elsewhere'}
    try:return hosted_call(c,'start',c.state,c.delivery,resume=resume,timeout=timeout)
    except (Stop,OSError,ValueError,subprocess.SubprocessError):return {'state':'failed','code':'publisher_unavailable'}


def delivery_publishes(c,folder=None):
    """Whether this machine's publishers run for the record: always on an unshared one; on a shared one, only where
    this seat holds delivery and has taken what the seat that passed it here carried."""
    state=getattr(c,'state',None)
    if folder is None and state is None:return True
    if not (json_object(Path(folder or state)/'state.json').get('meta') or {}).get('collab'):return True
    tool=_validator(c.release)
    try:return tool._collab().delivery_taken(Path(folder or state)) is not False
    except (OSError,ValueError,tool.StateError):return True


def hosted_pending(c,folder):
    """What hosted publication of the record in `folder` is still pending, or None."""
    identity=json_object(Path(folder)/hosted_module(c.release).IDENTITY)
    pending=identity.get('pending')
    return f"hosted snapshot {pending.get('sequence')} is pending" if isinstance(pending,dict) else None


def carried_identity(c,folder):
    """The hosted identity a seat passing delivery on carries: its sidecar as kept, nothing pending, or None."""
    identity=json_object(Path(folder)/hosted_module(c.release).IDENTITY)
    return {**identity,'pending':None,'sessionRequest':None} if identity.get('publicId') else None


def take_hosted(c,identity):
    """Write a carried identity as this machine's own, before its first publish: the owner, status and retry files
    are its own publisher's to rebuild."""
    module=hosted_module(c.release)
    for name in (module.STATUS,module.RETRY):(c.state/name).unlink(missing_ok=True)
    module.atomic(c.state/module.IDENTITY,identity)


def hosted_info(c,*,archive=None):
    try:
        if archive is not None:return hosted_module(GENERATION).archive_status(Path(archive))
        settings=hosted_settings(c)
        if settings is None:return {'state':'disabled'}
        if c.delivery is None:return {'state':'configured-no-delivery'}
        module=hosted_module(c.release)
        # This is read-only and needs no environment credential.
        info=module.status(c.state,settings[1],c.delivery)
        intent=module.read_terminal(c.state,archive_root(c))
        if intent:
            accepted=module.read_json(c.state/module.IDENTITY,optional=True)
            receipt=(accepted or {}).get('receipt')
            done=(intent['state']=='published' and receipt and receipt['digest']==intent['digest']
                  and receipt['sourceFingerprint']==intent['sourceFingerprint']
                  and module.finished_entry(module.record_document(c.state))==intent['entry'])
            info['state']='final-published' if done else 'final-publication-pending'
        elif (c.state/'state.json').exists() and module.finished_entry(module.record_document(c.state)) is not None:
            info['state']='final-publication-pending'
        if info.get('state')=='final-publication-pending' and 'receipt' not in info:
            identity=module.read_json(c.state/module.IDENTITY,optional=True)
            if identity and identity.get('receipt') is not None:info['receipt']=module.receipt(identity['receipt'])
        return info
    except (ValueError,OSError,RuntimeError,Stop):return {'state':'failed','code':'hosted_status_unavailable'}


def hosted_line(c,*,archive=None):
    info=hosted_info(c,archive=archive)
    if info.get('state')=='configured-no-delivery':return 'hosted: configured; no delivery selected'
    if info.get('state') in ('disabled','unpublished') and not info.get('url'):return None
    # Called only by explicit status/view/doctor output, never supervisor logs.
    return 'hosted: '+str(info.get('state','unavailable'))+(' '+info['url'] if info.get('url') else '')


def copy_hosted(c,target):
    if not any((c.state/name).exists() for name in ('hosted-identity.json','hosted-terminal.json')):return
    try:hosted_module(c.release).mirror_hosted(c.state,target,timeout=0)
    except (OSError,ValueError,RuntimeError,ImportError,Stop):
        # Core archives remain usable; corrupt optional sidecars never become
        # trusted recovery material. Doctor/status reports the source failure.
        return


def owned_hosted_processes(c):
    """Protect the recorded independent owner and its descendants from close's sweep."""
    try:
        module=hosted_module(c.release)
        owner=module.read_json(c.state/module.OWNER,optional=True)
        if not module.process_matches(owner):return set()
        kept={owner['pid']}
        result=run(['ps','-axo','pid=,ppid='],cwd=c.root,check=False)
        pairs=[tuple(map(int,line.split())) for line in result.stdout.splitlines() if len(line.split())==2]
        while True:
            extra={pid for pid,parent in pairs if parent in kept}
            if extra<=kept:return kept
            kept|=extra
    except (ValueError,OSError,RuntimeError,Stop):return set()


def hosted_retry(args):
    if not args.archive:
        c=cfg()
        print(json.dumps(hosted_call(c,'retry',c.state,c.delivery,resume=args.resume)))
        return
    # The current checkout supplies trusted collection configuration. An archive
    # supplies only its bounded record and identity, never executable commands.
    c=Config(repo(),need_delivery=False,pick=False)
    record=archived_record(args.archive).resolve()
    module=hosted_module(c.release)
    owner=module.read_json(record/module.OWNER,optional=True)
    if module.process_matches(owner) and not module.locked(record/module.LOCK):
        raise Stop('hosted: owner_elsewhere; retry after the recorded watcher exits')
    identity=module.read_json(record/module.IDENTITY)
    settings=hosted_settings(c)
    if settings is None:raise Stop('hosted: not_configured')
    module.Publisher(record,settings[1],identity['deliveryKey'])
    intent=module.read_terminal(record,record)
    if intent is None:
        document=module.record_document(record);entry=module.finished_entry(document)
        if entry is None:raise Stop('hosted: archive has no finished terminal cut')
        # Close can exhaust its budget waiting for the live control lock. The
        # already-finished archived core and its existing identity are the cut;
        # materialize the request here without inventing a replacement identity.
        intent=module.request_terminal(record,record,record,entry,document,timeout=5)
    if intent['state']=='published':
        print(json.dumps(module.archive_status(record)));return
    at=int(time.time()*1000)
    intent.update(requestedAt=at,retryUntil=at+module.FINAL_RETRY_SECONDS*1000,state='publication-pending' if intent['digest'] else 'capture-pending')
    module.atomic(record/module.TERMINAL,intent)
    from types import SimpleNamespace
    proxy=SimpleNamespace(root=c.root,state=record,release=c.release,shelf=c.shelf,
                          delivery=identity['deliveryKey'],flow_raw={'cleanup':{'archive':str(record)}},main=c.main)
    print(json.dumps(hosted_call(proxy,'retry',proxy.state,proxy.delivery,resume=args.resume)))


def finalize_hosted(c,archive,closed,*,seconds=HOSTED_CLOSE_SECONDS):
    began=time.monotonic();deadline=began+min(HOSTED_CLOSE_SECONDS,max(0,seconds))
    try:
        settings=hosted_settings(c)
        if settings is None:return {'state':'disabled'}
        module=hosted_module(c.release);record=Path(archive)/c.state.name
        document=module.record_document(record)
        module.request_terminal(c.state,record,archive_root(c),closed['id'],document,
                                timeout=max(0,deadline-time.monotonic()))
        if time.monotonic()<deadline:start_hosted(c,timeout=min(5,deadline-time.monotonic()))
        while time.monotonic()<deadline:
            info=hosted_info(c)
            if info.get('state')=='final-published':return info
            if info.get('code') in ('credential_invalid','writer_fenced','unauthorized'):break
            time.sleep(min(.1,max(0,deadline-time.monotonic())))
        return {'state':'final-publication-pending'}
    except (OSError,ValueError,RuntimeError,ImportError,Stop):return {'state':'final-publication-pending'}


def hosted_credentials_pipe(c):
    settings=hosted_settings(c)
    if settings is None:return None
    _,member=settings
    token=HOSTED_TOKENS.get((member['tokenEnv'],member['origin'],member['repositoryId']))
    if token is None:return None
    if not re.fullmatch(r'[A-Za-z0-9_-]{43,128}',token):return None
    read,write=os.pipe()
    data=json.dumps({'name':member['tokenEnv'],'origin':member['origin'],'repositoryId':member['repositoryId'],'token':token}).encode()
    try:os.write(write,data)
    finally:os.close(write)
    return read


def receive_hosted_credentials():
    given=os.environ.pop('RUN_DELIVERY_HOSTED_FD',None)
    if given is None:return
    try:
        descriptor=int(given)
        if descriptor<=2:raise ValueError()
        os.set_blocking(descriptor,False)
        try:data=os.read(descriptor,4097)
        finally:os.close(descriptor)
        value=json.loads(data)
        if (len(data)>4096 or set(value)!={'name','origin','repositoryId','token'}
            or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',value['name'])
            or not re.fullmatch(r'[A-Za-z0-9_-]{43,128}',value['token'])):raise ValueError()
        HOSTED_TOKENS[(value['name'],value['origin'],value['repositoryId'])]=value['token']
    except (OSError,ValueError,TypeError,KeyError):raise Stop('hosted: credential_handoff_invalid') from None



# -- process and git ----------------------------------------------------------------------

def now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def run(argv: list[str], cwd: Path | None = None, check: bool = True, **kw) -> subprocess.CompletedProcess:
    publishing=kw.pop('_publishing',False)
    quarantine_hosted_checkout(cwd)
    if not publishing:
        environment=dict(kw.pop('env',os.environ))
        for name,_,_ in HOSTED_TOKENS:environment.pop(name,None)
        if HOSTED_BOOTSTRAPPING and argv and str(argv[0])=='git':
            environment={name:value for name,value in environment.items() if name in HOSTED_BOOTSTRAP_ENV
                         and not re.fullmatch(r'[A-Za-z0-9_-]{43,128}',value)}
        kw['env']=environment
    done = subprocess.run(argv, cwd=cwd, text=True, capture_output=True, **kw)
    if check and done.returncode != 0:
        raise Stop(f"{' '.join(map(str, argv[:4]))} ... failed: {(done.stderr or done.stdout).strip()[-600:]}")
    return done


def git(*args: str, cwd: Path | None = None, check: bool = True) -> str:
    return run(["git", *args], cwd=cwd, check=check).stdout.strip()


def tool_commit(*args: str, cwd: Path | None = None, check: bool = True) -> subprocess.CompletedProcess:
    """A git command that makes a commit of the tool's own, run with no repository hook: `core.hooksPath` names an empty
    folder under the git common directory's run-delivery folder, as the merge queue's bypass does, whatever the
    binding's `hooks` says. The tool wrote what it commits, and a merge brings in commits that passed their own hooks."""
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir", cwd=cwd))
    empty = common / "run-delivery" / "empty-hooks"
    empty.mkdir(parents=True, exist_ok=True)
    for leftover in empty.iterdir():  # it stays empty: nothing put there ever runs
        if leftover.is_dir() and not leftover.is_symlink():
            shutil.rmtree(leftover)
        else:
            leftover.unlink()
    return run(["git", "-c", f"core.hooksPath={empty}", *args], cwd=cwd, check=check)


def repo() -> Path:
    return Path(git("rev-parse", "--show-toplevel"))


def main_checkout(cwd: Path | None = None) -> Path:
    """The main checkout of the repository at `cwd`, or at the working directory when no folder is given."""
    return Path(git("rev-parse", "--path-format=absolute", "--git-common-dir", cwd=cwd)).parent


def clean_head(cwd: Path | None = None) -> str:
    """HEAD, refusing uncommitted or untracked files: an untracked file would be tested but never reviewed."""
    dirty = git("status", "--porcelain", "--untracked-files=all", cwd=cwd)
    if dirty:
        raise Stop("the checkout has uncommitted or untracked files; commit or remove them first:\n" + dirty[:800])
    return git("rev-parse", "HEAD", cwd=cwd)


def expand(value: str, **values: str) -> str:
    """`{name}` placeholders and a leading `~`."""
    out = re.sub(r"\{(\w+)\}", lambda m: str(values.get(m.group(1), m.group(0))), value)
    return os.path.expanduser(out)


def expand_argv(argv: list[str], **values) -> list[str]:
    result = []
    for item in argv:
        if item == "{args}":
            result += list(values.get("args", []))
        else:
            result.append(expand(item, **{k: v for k, v in values.items() if k != "args"}))
    return result


def setting(name: str) -> str | None:
    """An environment setting by its name, or by its earlier name when the new one is unset."""
    old = next(o for o, n in LEGACY_NAMES if n == name)
    if os.environ.get(name):
        return os.environ[name]
    if os.environ.get(old):
        if (old, name) not in LEGACY_USED:
            LEGACY_USED.append((old, name))
        return os.environ[old]
    return None


def config_rel(shelf: "Shelf") -> str:
    """The repository's configuration file: .agents/run-delivery.json, or the earlier .agents/flow.json without it."""
    if shelf.text(CONFIG) is None and shelf.text(LEGACY_NAMES[0][0]) is not None:
        if LEGACY_NAMES[0] not in LEGACY_USED:
            LEGACY_USED.append(LEGACY_NAMES[0])
        return LEGACY_NAMES[0][0]
    return CONFIG


def stop_group(proc: subprocess.Popen | None) -> None:
    """Stop a process started with start_new_session=True, and wait until it has exited (SIGKILL after 10s)."""
    if not proc:
        return
    if proc.poll() is not None:  # the leader has gone, but its group may not have: signal what's left
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except (ProcessLookupError, PermissionError):
            pass
        return
    for sig, wait in ((signal.SIGTERM, 10), (signal.SIGKILL, 5)):
        try:
            os.killpg(proc.pid, sig)
        except ProcessLookupError:
            return
        try:
            proc.wait(timeout=wait)
            return
        except subprocess.TimeoutExpired:
            continue


def run_group(argv: list[str], cwd: Path, timeout: int, capture: bool = True,
              started: Callable[[int], None] | None = None) -> tuple[int, str]:
    """Run a command in its own process group; on timeout or interruption the whole group is stopped. `started` is
    told the group's pid once it runs."""
    proc = subprocess.Popen(argv, cwd=cwd, text=True, start_new_session=True,
                            stdout=subprocess.PIPE if capture else None, stderr=subprocess.STDOUT if capture else None)
    try:
        if started:
            started(proc.pid)
        out, _ = proc.communicate(timeout=timeout)
        return proc.returncode, out or ""
    except subprocess.TimeoutExpired:
        raise Stop(f"{' '.join(argv[:3])} ... took longer than {timeout}s and was stopped")
    finally:
        stop_group(proc)


# -- configuration ------------------------------------------------------------------------

def load_json(path: Path) -> dict | None:
    return json.loads(path.read_text()) if path.exists() else None


# Where a refusal of a base the binding doesn't serve sends the reader.
BASE_MISMATCH = "the adoption guide, references/adopting.md#base-mismatch"
# Where a lane's checkout records the base it was started on, inside its own git directory.
LANE_BASE = "run-delivery/lane.json"


def serves(binding: dict, base: str) -> bool:
    """Whether the binding serves `base`: its base.ref, or a name or `*` pattern in its bases, where `*` matches any
    run of characters within one segment of the branch name, never a `/`. The merge queue applies the same rule."""
    names = [binding.get("base", {}).get("ref"), *binding.get("bases", [])]
    return any(name and re.fullmatch("[^/]*".join(map(re.escape, name.split("*"))), base) for name in names)


def unserved(binding: dict, base: str) -> Stop:
    """The refusal of a base the binding doesn't serve."""
    names = ", ".join(filter(None, [binding.get("base", {}).get("ref"), *binding.get("bases", [])]))
    return Stop(f"the binding doesn't serve the base {base}: it serves {names}; add {base} to the binding's bases, "
                f"or deliver to a base it serves (see {BASE_MISMATCH})")


def lane_base_file(root: Path) -> Path:
    return root / git("rev-parse", "--git-path", LANE_BASE, cwd=root)


def record_lane_base(root: Path, base: str) -> None:
    """Record in a lane's checkout the base it was started on, which its settings are then read from."""
    path = lane_base_file(root)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps({"base": base}, indent=2) + "\n")


def lane_base(root: Path) -> str | None:
    """The base a lane names: RUN_DELIVERY_BASE, or the one its checkout recorded when it was started."""
    return os.environ.get("RUN_DELIVERY_BASE") or (load_json(lane_base_file(root)) or {}).get("base")


class Shelf:
    """Where the delivery's shared files are read from: the own config, the binding, delivery-views.json, the delivery
    file, the plan and the brief notes. The lead's checkout, on the delivery base, reads its own working tree. A lane
    reads them from the base on the remote, so what the lead pushes reaches every lane without a merge, and a lane
    never has to move its reviewed head to pick up a tooling change."""

    def __init__(self, root: Path, ref: str | None = None, base: str | None = None, named: bool = False):
        # base: the branch ref is on; named: the lane named it, rather than taking the binding's base.ref.
        self.root, self.ref, self.base, self.named = root, ref, base, named

    def text(self, rel: str | Path) -> str | None:
        if self.ref:
            done = run(["git", "show", f"{self.ref}:{Path(rel).as_posix()}"], cwd=self.root, check=False)
            return done.stdout if done.returncode == 0 else None
        path = self.root / rel
        return path.read_text() if path.exists() else None

    def json(self, rel: str | Path) -> dict | None:
        text = self.text(rel)
        return json.loads(text) if text is not None else None

    def names(self, folder: str | Path, suffix: str) -> list[str]:
        if self.ref:
            done = run(["git", "ls-tree", "--name-only", f"{self.ref}:{Path(folder).as_posix()}"], cwd=self.root, check=False)
            found = done.stdout.split() if done.returncode == 0 else []
        else:
            path = self.root / folder
            found = [f.name for f in path.iterdir()] if path.is_dir() else []
        return sorted(n for n in found if n.endswith(suffix))

    def where(self, rel: str | Path) -> str:
        return f"{self.ref}:{Path(rel).as_posix()}" if self.ref else str(self.root / rel)


def shelf_for(root: Path) -> Shelf:
    """The lead (on a base the binding serves) and explicit overrides read the working tree; a lane reads its base
    on the remote: the one it names (lane_base), checked against the binding, or else the binding's base.ref."""
    binding = load_json(root / ".agents/orchestration.json") or {}
    own = load_json(root / config_rel(Shelf(root))) or {}
    base = binding.get("base", {}).get("ref")
    remote = binding.get("base", {}).get("remote") or own.get("remote") or "origin"
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=root, check=False)
    if not base or setting("RUN_DELIVERY_LOCAL") == "1":
        return Shelf(root)
    named = lane_base(root)
    if named and not serves(binding, named):
        raise unserved(binding, named)
    if branch == base or (binding.get("bases") and serves(binding, branch)):
        return Shelf(root)
    base = named or base
    ref = f"{remote}/{base}"
    if not OFFLINE:
        run(["git", "fetch", "-q", remote, base], cwd=root, check=False)
    if run(["git", "rev-parse", "--verify", "--quiet", ref], cwd=root, check=False).returncode != 0:
        return Shelf(root)  # no such ref yet (a fresh repository): nothing shared to read
    return Shelf(root, ref, base, bool(named))


def meets(version: tuple[int, ...], minimum: tuple[int, ...]) -> bool:
    """Whether a version meets a minimum, compared number by number, a missing number counting as 0: the one
    comparison doctor and every Node and Python refusal use, so 100.0.0 meets 9.0.0."""
    width = max(len(version), len(minimum))
    return tuple(version) + (0,) * (width - len(version)) >= tuple(minimum) + (0,) * (width - len(minimum))


def numbers(text: str) -> tuple[int, ...] | None:
    """The dotted version a program printed or a descriptor names (`v22.6.0`, `Python 3.11.4`, `22.6.0`), or None."""
    found = re.search(r"(\d+(?:\.\d+)*)", text or "")
    return tuple(int(n) for n in found.group(1).split(".")) if found else None


def dotted(version: tuple[int, ...] | None) -> str:
    return ".".join(map(str, version)) if version else "of no readable version"


def node_version(node: str) -> tuple[int, ...] | None:
    """What `node --version` says, as numbers; None when it says nothing a version reads from."""
    try:
        done = subprocess.run([node, "--version"], text=True, capture_output=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return None
    return numbers(done.stdout.strip()) if re.match(r"v\d", done.stdout.strip()) else None


def node_versions() -> list[tuple[str, tuple[int, ...]]]:
    """Each Node the tool may run itself, with its version: the one on PATH, then nvm's, newest first."""
    candidates = [shutil.which("node")] + nvm_nodes()
    found = []
    for node in filter(None, candidates):
        version = node_version(node)
        if version:
            found.append((node, version))
    return found


def nvm_nodes() -> list[str]:
    """nvm's Nodes, newest first by number."""
    nodes = [str(p) for p in Path.home().glob(".nvm/versions/node/v*/bin/node")]
    return sorted(nodes, key=lambda node: numbers(Path(node).parents[1].name) or (), reverse=True)


def find_node(minimum: tuple[int, ...]) -> str | None:
    return next((node for node, version in node_versions() if meets(version, minimum)), None)


def find_node22() -> str | None:
    return find_node((22, 6))


def node_on_path() -> tuple[str, tuple[int, ...] | None] | None:
    """The Node a process here uses, and every child it starts: the first `node` on its PATH, with its version (None
    when it prints none). None when PATH holds no `node`. An nvm Node further down doesn't count."""
    node = shutil.which("node")
    return (node, node_version(node)) if node else None


def node_minimum(release: Path) -> str | None:
    """The runtime's nodeMinimum; None for a generation without a runtime, which asks for no Node."""
    return (load_json(release / "runtime/runtime.json") or {}).get("nodeMinimum") or None


# The nvm Node this process put first on its PATH, as adopt_node found it: {"path", "version", "replaced"}, where
# `replaced` names the first node on PATH before it, or None when there was none. None when nothing was adopted.
ADOPTED_NODE: dict | None = None


def adopt_node(release: Path) -> dict | None:
    """When the first node on PATH is missing or below the runtime's nodeMinimum and an nvm Node meets it, put that
    Node's bin folder first on this process's PATH, so the tool and every process it starts, the supervisor, its
    queue and their checks, the gates and the lanes' commands among them, run it; and say so once, on stderr. The
    newest nvm Node that meets the minimum is the one adopted. Returns what was adopted, or None."""
    global ADOPTED_NODE
    wanted = node_minimum(release)
    if not wanted:
        return ADOPTED_NODE
    minimum = numbers(wanted) or ()
    found = node_on_path()
    if found and found[1] and meets(found[1], minimum):
        return ADOPTED_NODE
    for node in nvm_nodes():
        version = node_version(node)
        if version and meets(version, minimum):
            break
    else:
        return None
    folder = str(Path(node).parent)
    os.environ["PATH"] = os.pathsep.join([folder, *[p for p in os.environ.get("PATH", "").split(os.pathsep) if p]])
    replaced = ({"path": found[0], "version": dotted(found[1]) if found[1] else None} if found else None)
    ADOPTED_NODE = {"path": node, "version": dotted(version), "replaced": replaced}
    print(f"run-delivery: using nvm's Node {dotted(version)} at {node}, put first on PATH for this command and every "
          f"process it starts: {replaced_words(ADOPTED_NODE, wanted)}", file=sys.stderr, flush=True)
    return ADOPTED_NODE


def replaced_words(adopted: dict, wanted: str) -> str:
    """Why a Node was adopted: what the first node on PATH was before it."""
    replaced = adopted.get("replaced")
    if not replaced:
        return f"there was no node on PATH, and the runtime needs Node {wanted}"
    if not replaced.get("version"):
        return f"the first node on PATH, {replaced['path']}, prints no version to compare with nodeMinimum {wanted}"
    return f"the first node on PATH, {replaced['path']}, is Node {replaced['version']}, below nodeMinimum {wanted}"


def node_problem(release: Path) -> tuple[str, str] | None:
    """Why no Node this process can run meets the runtime's nodeMinimum, as (status, detail), or None. A first node on
    PATH below the minimum, or none, is put right first by adopting an nvm Node that meets it; only with no such Node
    is it a problem: `missing` with no `node` on PATH, `wrong` below the minimum or of no readable version."""
    wanted = node_minimum(release)
    if not wanted:
        return None
    adopt_node(release)
    minimum = numbers(wanted) or ()
    found = node_on_path()
    if found and found[1] and meets(found[1], minimum):
        return None
    fix = (f"fix: install Node {wanted} or newer, through nvm (the tool finds nvm's Nodes and puts one that meets it "
           f"first on PATH itself) or with its bin folder first on PATH")
    if not found:
        return "missing", f"no node on PATH or in nvm, and the runtime needs Node {wanted}; {fix}"
    node, version = found
    where = f"{node}, the first node on PATH, from the PATH entry {Path(node).parent}"
    if not version:
        return "wrong", (f"{where}, prints no version to compare with the runtime's nodeMinimum {wanted}, and no nvm "
                         f"Node meets it; {fix}")
    return "wrong", (f"Node {dotted(version)} is below the runtime's nodeMinimum {wanted}: it is {where}, and no nvm "
                     f"Node meets it; {fix}")


def require_node(release: Path, command: str) -> None:
    """Refuse a command whose processes would run a Node below the runtime's minimum, before it writes or starts
    anything: only when neither the first node on PATH nor any nvm Node meets it."""
    problem = node_problem(release)
    if problem:
        raise Stop(f"{command} refuses: {problem[1]}")


# The Python a lane's tools and the repository's sensors need, the minimum doctor holds.
PYTHON_MINIMUM = (3, 11)


def interpreter_version() -> tuple[int, ...]:
    """The version of the Python running this tool. Read only through here, so a test can stand in another."""
    return tuple(sys.version_info[:3])


def python_problems() -> list[str]:
    """Each Python a lane runs that is below PYTHON_MINIMUM, each with its fix: the interpreter running this tool, and
    the first `python3` on PATH, which the lane's gates and sensors run."""
    wanted = dotted(PYTHON_MINIMUM)
    problems = []
    running = interpreter_version()
    if not meets(running, PYTHON_MINIMUM):
        problems.append(f"the Python running this tool, {sys.executable}, is {dotted(running)}, below {wanted}; fix: "
                        f"run it with Python {wanted} or newer")
    python = shutil.which("python3")
    if not python:
        problems.append(f"no python3 on PATH; fix: put Python {wanted} or newer's bin folder first on PATH")
    else:
        # Python before 3.4 says its version on stderr.
        done = run([python, "--version"], check=False)
        version = numbers(done.stdout + done.stderr) if done.returncode == 0 else None
        if not version or not meets(version, PYTHON_MINIMUM):
            problems.append(f"python3 first on PATH, {python}, from the PATH entry {Path(python).parent}, is Python "
                            f"{dotted(version)}, below {wanted}; fix: put Python {wanted} or newer's bin folder first "
                            "on PATH")
    return problems


def load_harness(root: Path, release: Path) -> tuple[dict | None, str]:
    """harness.config.ts, loaded the way the installed runtime loads it: (settings, how) or (None, why not)."""
    path = root / "harness.config.ts"
    if not path.exists():
        return None, "no harness.config.ts"
    node = find_node22()
    if not node:
        return None, "harness.config.ts not read: it needs Node >= 22.6"
    hook = (release / "runtime/loader.mjs").resolve()
    script = ("import(require('node:url').pathToFileURL(process.argv[1]).href).then(m => { const c = m.default; "
              "console.log(JSON.stringify({baseRef: c.baseRef, preparationCommands: c.preparationCommands || [], "
              "additionalReviewLenses: c.additionalReviewLenses || []})) })")
    register = ('data:text/javascript,import {register} from "node:module"; import {pathToFileURL} from "node:url"; '
                f'register(pathToFileURL({json.dumps(str(hook))}));')
    # Node before 22.18 and 23.6 strips types only behind this flag; later ones accept it unchanged.
    done = subprocess.run([node, "--no-warnings", "--experimental-strip-types", "--import", register, "-e", script, str(path)],
                          text=True, capture_output=True, cwd=root)
    if done.returncode != 0:
        return None, f"harness.config.ts not read: {done.stderr.strip()[-200:]}"
    return json.loads(done.stdout.strip().splitlines()[-1]), "harness.config.ts"


class Config:
    """Settings resolved from what the repository already declares, in this order of precedence:
    the orchestrate-work binding (.agents/orchestration.json: what the merge queue runs), the delivery-views config
    (.agents/delivery-views.json), the harness config (harness.config.ts), then .agents/run-delivery.json for what
    none of them declares, then defaults. One delivery's settings come from .agents/deliveries/<key>.json."""

    def __init__(self, root: Path, delivery: str | None = None, need_delivery: bool = True, tolerant: bool = False,
                 pick: bool = True):
        global HOSTED_BOOTSTRAPPING
        HOSTED_BOOTSTRAPPING=True
        # Its main checkout and, below, its branch are the root's own, never the working directory's: a configuration
        # built for one repository from inside another resolves that repository's deliveries, and no other's.
        self.root, self.main = root, main_checkout(root)
        self.sources: dict[str, str] = {}
        self.conflicts: list[str] = []
        self.shelf = shelf_for(root)
        explicit = setting("RUN_DELIVERY_CONFIG")
        if explicit:
            self.path = Path(explicit)
            f = load_json(self.path) or {}
        else:
            rel = config_rel(self.shelf)
            self.path = self.shelf.where(rel)
            f = self.shelf.json(rel) or {}
        own = self.name = Path(self.path).name
        # How a brief names it: the path given explicitly, or the repository-relative file that was read.
        self.config_named = explicit or rel
        if f and f.get("schemaVersion") != "delivery-flow/1":
            raise Stop(f"{self.path}: schemaVersion must be delivery-flow/1")
        self.flow_raw = f
        self.binding_path = root / ".agents/orchestration.json"
        b = self.shelf.json(".agents/orchestration.json") or {}
        views = self.shelf.json(".agents/delivery-views.json") or {}
        remember_hosted(views)
        HOSTED_BOOTSTRAPPING=False
        self.release = root / os.path.expanduser(f["release"]) if f.get("release") else GENERATION
        self.release_override = f.get("release")
        if f.get("harness") == "ignore":
            h, how = None, f"harness.config.ts ignored ({own} says so)"
        else:
            h, how = load_harness(root, self.release)
            if h is None and (root / "harness.config.ts").exists() and not tolerant:
                # Skipping it would drop its lenses and its cross-check without anyone noticing.
                raise Stop(f"{how}; fix that, or set \"harness\": \"ignore\" in {self.path}")
        self.harness_note = how

        def take(name, *options, flow=None, default=None, default_source="default", same=lambda a, b: a == b):
            """The first declared value; a different own-config value under a higher source is a conflict."""
            for value, source in options:
                if value not in (None, [], {}):
                    self.sources[name] = source
                    if flow not in (None, [], {}) and not same(flow, value):
                        self.conflicts.append(f"{own} sets {name} to {flow!r}, but {source} declares {value!r}")
                    return value
            if flow not in (None, [], {}):
                self.sources[name] = own
                return flow
            self.sources[name] = default_source
            return default

        self.remote = take("remote", (b.get("base", {}).get("remote"), "orchestration binding"), flow=f.get("remote"),
                           default="origin")
        self.binding_base = b.get("base", {}).get("ref")
        self.binding, self.bases = b, b.get("bases", [])
        work_root = b.get("workRoot")
        self.work = take("workDirectory", (str(Path(work_root).parent) if work_root else None,
                                           "orchestration binding (workRoot's folder)"),
                         flow=f.get("workDirectory"), default=".orchestration")
        self.state_rel = take("stateDirectory", (b.get("state", {}).get("directory"), "orchestration binding"),
                              default=".orchestration/state")
        self.branch_pattern = take("branchPattern", flow=f.get("branchPattern"), default="feature/{key}")
        self.lane_pattern = take("laneCheckout", flow=f.get("laneCheckout"), default=".orchestration/lanes/{key}")
        self.lane_checkout = lambda key: self.main / expand(self.lane_pattern, key=key)
        self.deliveries_rel = take("deliveries", flow=f.get("deliveries"), default=".agents/deliveries")
        self.deliveries = root / self.deliveries_rel
        self.issue_url = take("tracker.issueUrl", (views.get("tracker", {}).get("issueUrl"), "delivery-views.json"),
                              flow=f.get("tracker", {}).get("issueUrl"), default="{key}")
        derived: dict = {}
        if views.get("forges"):
            first = views["forges"][0]
            derived = {"adapter": first.get("name", "").lower(), "repository": first.get("repository", "")}
            snapshot = b.get("state", {}).get("forgeSnapshot", {}).get("argv", [])
            if "--token-env" in snapshot:
                derived["tokenEnv"] = snapshot[snapshot.index("--token-env") + 1]
        flow_forge = dict(f.get("forge") or {})
        for field in ("adapter", "repository", "tokenEnv"):
            if field in flow_forge and field in derived and flow_forge[field] != derived[field]:
                self.conflicts.append(f"{own} sets forge.{field} to {flow_forge[field]!r}, but delivery-views.json "
                                      f"or the binding declares {derived[field]!r}")
        # The own config may add what nothing else declares (a custom adapter's argv, say) but not contradict.
        self.forge = {**flow_forge, **derived}
        self.sources["forge"] = ("delivery-views.json (forges[0])" + (", token from the binding's forgeSnapshot"
                                 if "tokenEnv" in derived else "") if derived else "") + \
            (f" + {own}" if flow_forge else "") or "none declared"
        review = f.get("review", {})
        self.bound = take("review.bound", flow=review.get("bound"), default=4, default_source="review-work's default")
        # (short name, charter file): the workflow's lenses' charters are the release's personas; extra lenses name a
        # charter file in the repository.
        lenses = {"lens.outcome-correctness": ("outcome-correctness", self.release / "personas/outcome-correctness.md"),
                  "lens.adversarial-testing": ("adversarial-testing", self.release / "personas/testing-policy.md")}
        self.sources["review.lenses"] = "the delivery workflow's two lenses"
        for extra in (h or {}).get("additionalReviewLenses", []):
            lenses[extra["lensId"]] = (extra["lensId"].split(".", 1)[-1], root / extra["charterPath"])
            self.sources["review.lenses"] += f" + {extra['lensId']} (harness.config.ts)"
        for lens, spec in review.get("lenses", {}).items():
            if lens in lenses:
                self.conflicts.append(f"{own} review.lenses redefines {lens}, which is already declared")
            lenses[lens] = (spec["short"], root / spec["charter"])
            self.sources["review.lenses"] += f" + {lens} ({own})"
        for lens, (_, charter) in lenses.items():
            if not charter.exists():
                self.conflicts.append(f"lens {lens}'s charter {charter} doesn't exist")
        self.lenses = lenses
        # Each lens's use, plan review, a story's review or both, and where it was declared. A harness.config.ts lens
        # takes its use from review.use, since the runtime closes that file's entries.
        self.lens_origin = {lens: "the delivery workflow" for lens in MANDATED_LENSES}
        for extra in (h or {}).get("additionalReviewLenses", []):
            self.lens_origin[extra["lensId"]] = "harness.config.ts"
        declared_use: dict[str, tuple[object, str]] = {}
        for lens, spec in review.get("lenses", {}).items():
            self.lens_origin.setdefault(lens, self.config_named)
            if "use" in spec:
                declared_use[lens] = (spec["use"], f"{own} review.lenses.{lens}.use")
        mapped = review.get("use", {})
        if not isinstance(mapped, dict):
            self.conflicts.append(f"{own} review.use must map lens ids to their use, not {mapped!r}")
            mapped = {}
        for lens, use in mapped.items():
            if lens not in lenses:
                self.conflicts.append(f"{own} review.use names {lens}, which isn't a declared lens")
            elif lens in declared_use and declared_use[lens][0] != use:
                self.conflicts.append(f"{own} review.use gives {lens} the use {use!r}, but review.lenses gives it "
                                      f"{declared_use[lens][0]!r}")
            else:
                declared_use[lens] = (use, f"{own} review.use.{lens}")
        self.lens_use: dict[str, tuple[str, ...]] = {}
        for lens in lenses:
            use, where = declared_use.get(lens, (list(LENS_USES), ""))
            if where and (not isinstance(use, list) or not use or len(set(map(str, use))) != len(use)
                          or any(u not in LENS_USES for u in use)):
                self.conflicts.append(f"{where} must list plan, story or both, once each, not {use!r}")
                use = list(LENS_USES)
            elif where and lens in MANDATED_LENSES and set(use) != set(LENS_USES):
                self.conflicts.append(f"{where} narrows {lens}, a mandated lens, whose use is plan and story")
            self.lens_use[lens] = tuple(u for u in LENS_USES if u in use)
        self.story_lenses = [lens for lens in lenses if "story" in self.lens_use[lens]]
        # A story lens on request: `"default": false` in its review.lenses entry, or review.default for a
        # harness.config.ts lens, as review.use gives one its use. It runs only when --lenses or the brief names it.
        declared_default: dict[str, tuple[object, str]] = {}
        for lens, spec in review.get("lenses", {}).items():
            if "default" in spec:
                declared_default[lens] = (spec["default"], f"{own} review.lenses.{lens}.default")
        defaults = review.get("default", {})
        if not isinstance(defaults, dict):
            self.conflicts.append(f"{own} review.default must map lens ids to true or false, not {defaults!r}")
            defaults = {}
        for lens, default in defaults.items():
            if lens not in lenses:
                self.conflicts.append(f"{own} review.default names {lens}, which isn't a declared lens")
            elif lens in declared_default and declared_default[lens][0] != default:
                self.conflicts.append(f"{own} review.default gives {lens} the default {default!r}, but review.lenses "
                                      f"gives it {declared_default[lens][0]!r}")
            else:
                declared_default[lens] = (default, f"{own} review.default.{lens}")
        self.on_request: list[str] = []
        for lens in lenses:
            default, where = declared_default.get(lens, (True, ""))
            if not isinstance(default, bool):
                self.conflicts.append(f"{where} must be true or false, not {default!r}")
            elif default is False and lens in MANDATED_LENSES:
                self.conflicts.append(f"{where} puts {lens}, a mandated lens, on request; it runs in every round")
            elif default is False and "story" not in self.lens_use[lens]:
                self.conflicts.append(f"{where} puts {lens} on request, but its use is plan only: only a story lens "
                                      "can be on request")
            elif default is False:
                self.on_request.append(lens)
        self.plan_lenses_declared = [lens for lens in lenses if "plan" in self.lens_use[lens]]
        self.prepare = take("review.prepare", (b.get("prepare"), "orchestration binding"), flow=review.get("prepare"),
                            default=[])
        if b.get("provider") or b.get("alwaysRun") or b.get("profiles"):
            # The merge queue may select checks beyond the fallback list; lanes need them spelled out.
            if not f.get("gates"):
                self.conflicts.append("the binding selects checks with a provider, alwaysRun or profiles; list the "
                                      f"lane gates in {own} `gates`")
            gates = []
        else:
            timeout = b.get("checkTimeoutSeconds", 1800)
            gates = [{"id": g["id"], "argv": [("{base}" if a == "{baseHead}" else a) for a in g["argv"]],
                      "cwd": g.get("cwd", "."), "timeoutSeconds": g.get("timeoutSeconds", timeout)}
                     for g in b.get("fallback", [])]
        flow_gates = f.get("gates")
        if isinstance(flow_gates, list):
            flow_gates = [named_gate(g, b) if isinstance(g, str) else g for g in flow_gates]
        if flow_gates == "none" and (b.get("fallback") or b.get("provider") or b.get("alwaysRun") or b.get("profiles")):
            self.conflicts.append(f"{own} says \"gates\": \"none\", but the binding declares checks the merge queue runs")
        if flow_gates == "none":
            self.gates, self.sources["gates"] = [], f"{own} (\"none\": no gates)"
        else:
            self.gates = take("gates", (gates, "orchestration binding (fallback checks: what the merge queue runs)"),
                              flow=flow_gates, default=[],
                              same=lambda a, b: [(g["id"], g["argv"]) for g in a] == [(g["id"], g["argv"]) for g in b])
            if (isinstance(flow_gates, list) and any(isinstance(g, dict) and g.get("check") for g in flow_gates)
                    and [(g["id"], g["argv"]) for g in flow_gates] == [(g["id"], g["argv"]) for g in self.gates]):
                # The own config names the binding's fallback checks by id: those run through run-checks, as named.
                self.gates = [ours if ours.get("check") else theirs for ours, theirs in zip(flow_gates, self.gates)]
        self.harness_settings = h
        if not self.bases:  # one base: check the harness config against it now; else against the delivery's base
            self.conflicts += self.harness_conflicts(self.binding_base, "the binding's base")
        self.never_touch = take("neverTouch", flow=f.get("neverTouch"), default=[])
        self.in_app = f.get("inApp")
        self.sources["inApp"] = own if self.in_app else "none declared"
        leases = {lease["id"] for lease in b.get("leases", [])}
        if self.in_app and leases and self.in_app.get("lease") not in leases:
            self.conflicts.append(f"inApp.lease {self.in_app.get('lease')!r} isn't one of the binding's leases {sorted(leases)}")
        self.test_files = (self.in_app or {}).get("testFilePattern", DEFAULT_TEST_FILES)
        if self.conflicts:
            raise Stop("the repository's configs disagree:\n  " + "\n  ".join(self.conflicts))
        self.delivery, self.planning = None, False
        key = delivery or setting("RUN_DELIVERY_DELIVERY") or (self.pick_delivery(need_delivery) if pick else None)
        if key:
            self.load_delivery(key)

    def harness_conflicts(self, base: str | None, whose: str) -> list[str]:
        """Where harness.config.ts disagrees with the lane gates or the base: its baseRef and preparationCommands."""
        h, found = self.harness_settings, []
        if not h or not base:
            return found
        base_ref = f"{self.remote}/{base}"
        if h.get("preparationCommands") and self.gates:
            ours = [[base_ref if a == "{base}" else a for a in g["argv"]] for g in self.gates]
            theirs = [list(cmd["command"]) for cmd in h["preparationCommands"]]
            if ours != theirs:
                found.append(f"the lane gates {ours} and harness.config.ts preparationCommands {theirs} disagree")
        if h.get("baseRef") and h["baseRef"] != base_ref:
            found.append(f"harness.config.ts baseRef {h['baseRef']} isn't {whose} {base_ref}")
        return found

    def base_hint(self) -> str:
        """For a lane that read the binding's base.ref by default although the binding serves several bases."""
        if self.bases and self.shelf.ref and not self.shelf.named:
            return (f"; this checkout read {self.shelf.ref}, the binding's base.ref: a lane of a delivery to another "
                    "base names it with RUN_DELIVERY_BASE")
        return ""

    def delivery_keys(self) -> list[str]:
        return [name[:-len(".json")] for name in self.shelf.names(self.deliveries_rel, ".json")]

    def delivery_files(self) -> dict[str, dict]:
        return {key: self.shelf.json(f"{self.deliveries_rel}/{key}.json") or {} for key in self.delivery_keys()}

    def state_of(self, key: str, d: dict) -> Path:
        """Where a delivery's record is kept on this machine, as load_delivery finds it.

        By default it is in the lead's checkout, the lane checkout named by the delivery key. When that key is also a
        story's, that folder is the story's own lane checkout, so the record goes under the work directory's
        `deliveries/<key>/` instead. A record already at either default path stays there; one at both is refused."""
        if os.environ.get("DELIVERY_STATE"):
            return Path(os.environ["DELIVERY_STATE"])
        if d.get("stateDirectory"):
            return self.main / d["stateDirectory"]
        # The binding's state.directory is the folder's name inside either default path, never a place of its own,
        # unless it is absolute: then both paths are that one.
        lead, apart = self.lane_checkout(key) / self.state_rel, self.record_apart(key)
        if lead == apart:
            return lead
        held = [path for path in (lead, apart) if (path / "state.json").is_file()]
        if len(held) == 2:
            raise Stop(f"delivery {key} has a record at both {lead} and {apart}; keep the one it runs on, and move "
                       "the other away")
        if held:
            return held[0]
        return apart if key in (d.get("stories") or {}) else lead

    def record_apart(self, key: str) -> Path:
        """The default record folder of a delivery whose key is also a story's: beside the lanes, under the work
        directory."""
        return self.main / self.work / "deliveries" / key / self.state_rel

    def record_apart_note(self) -> str | None:
        """What doctor --delivery warns and lead-init prints when this delivery's record is kept apart: its key is
        also a story's."""
        if self.state != self.record_apart(self.delivery) or self.delivery not in self.stories:
            return None
        return (f"{self.delivery} is also a story's key, so its record is kept in {self.state}, beside the lane "
                f"checkouts rather than in {self.lane_checkout(self.delivery)}, the story's own; to keep it elsewhere, "
                f"set stateDirectory in {self.delivery_where}")

    def closed_here(self, key: str, d: dict) -> bool:
        """Whether this machine's flow log for the delivery holds the closed.json lead-close writes; on a shared record
        also whether the delivery holder's machine archived the close that closes it now (D21)."""
        folder = self.state_of(key, d)
        if (folder.parent / "flow-log" / f"{key}.closed.json").exists():
            return True
        return closed_by_holder(types.SimpleNamespace(state=folder, release=self.release))

    def open_here(self, key: str, d: dict) -> bool:
        """Whether the delivery's record is open in this checkout: it is kept under it, and not in a checkout nested
        inside it (a lead's under the lanes folder, say), holds state.json, and isn't closed. A record that names its
        tracker parent must name this delivery."""
        state, root = self.state_of(key, d).resolve(), self.root.resolve()
        try:
            state.relative_to(root)
        except ValueError:
            return False
        if any((folder / ".git").exists() for folder in [state, *state.parents] if folder != root and
               folder.is_relative_to(root)):
            return False
        if not (state / "state.json").is_file() or self.closed_here(key, d):
            return False
        parent = ((load_json(state / "state.json") or {}).get("meta") or {}).get("trackerParent")
        return parent in (None, key)

    def tracker_closed(self, key: str, d: dict) -> bool:
        """Whether the binding's tracker snapshot, run for the delivery's own key, shows its parent completed or
        canceled. Without a tracker snapshot, or when it fails or doesn't say, the delivery isn't known to be closed."""
        asked = self.__dict__.setdefault("tracker_answers", {})  # each delivery's tracker is asked once per command
        if key not in asked:
            asked[key] = self.ask_tracker(key, d)
        return asked[key]

    def ask_tracker(self, key: str, d: dict) -> bool:
        spec = (self.binding.get("state") or {}).get("trackerSnapshot")
        if not spec:
            return False
        argv = expand_argv(spec["argv"], stateDirectory=str(self.state_of(key, d)), parent=key)
        try:
            taken = run(argv, cwd=self.root, check=False, timeout=int(spec.get("timeoutSeconds", 60)))
            parent = json.loads(taken.stdout).get("parent") if taken.returncode == 0 else None
        except (subprocess.TimeoutExpired, OSError, ValueError, AttributeError):
            return False
        return (isinstance(parent, dict) and parent.get("subject") == key
                and parent.get("state") in ("completed", "canceled"))

    def not_known_closed(self, files: dict[str, dict]) -> list[str]:
        """The deliveries not known to be closed: no closed.json here, and no tracker snapshot showing the parent
        closed. The tracker is asked whenever there is more than one delivery file."""
        left = [key for key, d in files.items() if not self.closed_here(key, d)]
        if len(files) > 1:
            left = [key for key in left if not self.tracker_closed(key, files[key])]
        return left

    def pick_delivery(self, required: bool) -> str | None:
        """The delivery a command without --delivery is for: the only delivery file; else the one whose record is
        open in this checkout; else the one whose story branch this checkout is on; else the only one not known to be
        closed. Otherwise it refuses, naming each delivery not known to be closed."""
        files = self.delivery_files()
        if len(files) == 1:
            return next(iter(files))
        here = [key for key, d in files.items() if self.open_here(key, d)]
        if len(here) == 1:
            return here[0]
        branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=self.root, check=False)
        matches = [key for key, d in files.items()
                   if any(branch == self.branch_pattern.format(key=k) for k in d.get("stories", {}))]
        if len(matches) == 1:
            return matches[0]
        left = self.not_known_closed(files)
        if len(left) == 1:
            return left[0]
        if required:
            named = (f"{', '.join(left)} aren't known to be closed, and no record of theirs is open here" if left
                     else f"deliveries {', '.join(files) or 'none'}, none of them open")
            raise Stop(f"can't tell which delivery this is (branch {branch}; {named}); pass --delivery KEY"
                       f"{self.base_hint()}")
        return None

    def missing_delivery(self, key: str) -> str:
        """For a delivery file that is missing: whether the key is a story of a delivery, and which delivery is open."""
        files = self.delivery_files()
        owners = [other for other, d in files.items() if key in (d.get("stories") or {})]
        said = (f"; {key} looks like a story key: it is a story of {', '.join(owners)}" if owners
                else f"; {key} is no story of any delivery here either")
        try:
            default = self.pick_delivery(False)
        except Stop:
            default = None
        if default:
            said += f"; the open delivery is {default}: pass --delivery {default}"
        else:
            left = self.not_known_closed(files)
            said += (f"; the deliveries not known to be closed are {', '.join(left)}" if left
                     else "; no delivery here is open")
        return said

    def planning_delivery(self, key: str) -> dict | None:
        """The planning record plan-open opened for `key`, read as a delivery with no stories yet, until lead-setup
        writes its delivery file: its plan, its headline, no lanes. None when there is no such record."""
        folder = self.record_apart(key)
        meta = json_object(folder / "state.json").get("meta") or {}
        if (meta.get("collab") or {}).get("key") != key or meta.get("phase") != "planning" \
                or not isinstance(meta.get("planFile"), str):
            return None
        # Its base is the one its record started on, as plan-open named it.
        with contextlib.suppress(OSError, ValueError, IndexError, KeyError, TypeError):
            started = json.loads((folder / "journal.jsonl").read_text(encoding="utf-8").splitlines()[0])
            base = started["data"]["base"]["ref"].removeprefix(f"{self.remote}/")
        return {"schemaVersion": "delivery-flow-delivery/1", "delivery": key, "headline": meta.get("headline") or key,
                "plan": meta["planFile"], "lanes": {}, "stories": {},
                **({"baseBranch": base} if "base" in locals() else {})}

    def load_delivery(self, key: str) -> None:
        path = self.deliveries / f"{key}.json"
        d = self.shelf.json(f"{self.deliveries_rel}/{key}.json")
        planned = self.planning_delivery(key) if d is None else None
        self.planning = planned is not None
        d = d if planned is None else planned
        if d is None:
            raise Stop(f"{self.shelf.where(f'{self.deliveries_rel}/{key}.json')} is missing (lead-setup writes it)"
                       f"{self.missing_delivery(key)}{self.base_hint()}")
        if d.get("schemaVersion") != "delivery-flow-delivery/1":
            raise Stop(f"{path}: schemaVersion must be delivery-flow-delivery/1")
        self.raw, self.delivery_path = d, path
        self.delivery_where = (f"the planning record {self.record_apart(key)}" if self.planning
                               else self.shelf.where(f"{self.deliveries_rel}/{key}.json"))
        self.delivery = d["delivery"]
        base = d.get("baseBranch")
        if base and self.binding_base and not serves(self.binding, base):
            raise Stop(f"{path} names base {base}, but the binding here serves "
                       f"{', '.join([self.binding_base, *self.bases])}; add {base} to the binding's bases, or deliver "
                       f"to a base it serves (see {BASE_MISMATCH})")
        self.base_branch = base or self.binding_base
        if not self.base_branch:
            raise Stop(f"no delivery base: the binding has no base.ref and {path} names no baseBranch")
        if self.shelf.base and self.shelf.base != self.base_branch:
            raise Stop(f"{self.delivery_where} names base {self.base_branch}, but this checkout read it from "
                       f"{self.shelf.ref}; name the delivery's base with RUN_DELIVERY_BASE")
        conflicts = self.harness_conflicts(self.base_branch, "the delivery's base") if self.bases else []
        if conflicts:
            raise Stop("the repository's configs disagree:\n  " + "\n  ".join(conflicts))
        self.sources["baseBranch"] = f"{path.name}" if base else "orchestration binding (base.ref)"
        self.base_ref = f"{self.remote}/{self.base_branch}"
        self.state = self.state_of(key, d)
        if os.environ.get("DELIVERY_STATE"):
            self.sources["state"] = "DELIVERY_STATE"
        elif d.get("stateDirectory"):
            self.sources["state"] = path.name
        elif self.state == self.record_apart(key):
            self.sources["state"] = ("the work directory's deliveries/<key>/, " + (
                "since the key is also a story's" if key in d["stories"] else "where the record already is"))
        else:
            self.sources["state"] = "the lead's checkout (laneCheckout with the delivery key) + the binding's state.directory"
        self.flow_log = self.state.parent / "flow-log"
        self.plan = Path(d["plan"])
        self.lane_brief = Path(d.get("laneBrief", f"docs/{key}.lane-brief.md"))
        self.context_sections = d.get("context", {}).get("sections", [])
        self.lanes = d["lanes"]
        self.stories = d["stories"]
        self.finish = d.get("finish", [])
        # A delivery that takes no deferrals: a finding still deferred when its story merges is a blocker, not a follow-up.
        self.no_deferrals = d.get("noDeferrals") is True
        self.ship = d.get("ship")
        self.brief_notes = d.get("brief", {}).get("notes")
        for k in self.stories:
            self.requirements(k)  # validated on load
            brief_lenses(self, k)

    def effective_ownership(self, state: dict) -> dict[str, list[str]]:
        return state.get("laneOwnership", {lane: entry["owns"] for lane, entry in self.lanes.items()})

    def record_state(self) -> dict:
        # State is replaced atomically. Read only state.json here, without taking the journal lock.
        return load_json(self.state / "state.json") or {}

    def check_lanes(self, state: dict | None = None) -> None:
        state = self.record_state() if state is None else state
        ownership = self.effective_ownership(state)
        for key in self.stories:
            lane = self.lane_of(key, state)
            if lane not in ownership:
                raise Stop(f"{self.delivery_where}: story {key} has lane {lane!r}, which isn't in `lanes`")

    def branch(self, key: str) -> str:
        return self.branch_pattern.format(key=key)

    def lane_of(self, key: str, state: dict | None = None) -> str:
        state = self.record_state() if state is None else state
        if "laneOwnership" in state:
            for entry in (*state.get("planned", []), *state.get("queue", [])):
                if entry["subject"] == key:
                    return entry.get("assignedLane", entry["lane"])
        return self.stories[key]["lane"]

    def label(self, key: str) -> str:
        return self.stories[key].get("label", key)

    def require(self, key: str) -> str:
        if key not in self.stories:
            raise Stop(f"{key} is not a story of {self.delivery} ({self.delivery_where})")
        self.check_lanes()
        return key

    def requirements(self, key: str) -> list[dict]:
        """The in-app checks a story's hand-off needs: [{mode, pattern?, args?}], mode any|hold|fail|loaded."""
        if not self.in_app:
            return []
        story = self.stories[key]
        pinned = story.get("pinned", [])
        need = story.get("inApp", "checks" if pinned else "none")
        if need == "none":
            return []
        if need == "loaded":
            return [{"mode": "loaded"}]
        if need == "checks":
            return [{"mode": "hold"}, {"mode": "fail"}] + [{"mode": "any", "pattern": p} for p in pinned]
        if not isinstance(need, list):
            raise Stop(f"story {key}: inApp must be none, loaded, checks or a list of requirements")
        for req in need:
            if not isinstance(req, dict) or req.get("mode") not in ("hold", "fail", "loaded", "any"):
                raise Stop(f"story {key}: requirement {req!r} needs mode hold, fail, loaded or any")
            if req.get("pattern") is not None and req["pattern"] not in pinned:
                raise Stop(f"story {key}: requirement pattern {req['pattern']!r} isn't one the story pins")
            if "args" in req and (not isinstance(req["args"], list) or not all(isinstance(a, str) for a in req["args"])):
                raise Stop(f"story {key}: requirement args must be a list of strings")
        return need


def requirement_label(req: dict) -> str:
    label = f"needs-{req['mode']}"
    if req.get("pattern"):
        label += f" {req['pattern']}"
    if "args" in req:
        label += " args " + json.dumps(req["args"])
    return label


CFG: Config | None = None
DELIVERY_ARG: str | None = None


def cfg() -> Config:
    global CFG
    if CFG is None:
        CFG = Config(repo(), DELIVERY_ARG)
    return CFG


STATE_TOOL = "skills/orchestrate-work/scripts/delivery_state.py"


def state_script() -> Path:
    script = cfg().release / STATE_TOOL
    if not script.exists():
        raise Stop(f"no agent-skills release at {cfg().release} (its delivery_state.py is missing)")
    return script


def state_tool(*args: str, check: bool = True) -> subprocess.CompletedProcess:
    return run([sys.executable, "-B", str(state_script()), "--dir", str(cfg().state), *args], check=check)


# What a read takes from the state tool as a module: the three calls its `show` command makes, and its refusal.
STATE_READER_NAMES = ("show", "publication", "emitted", "StateError")
STATE_READERS: dict[str, object] = {}


def state_reader(script: Path):
    """The state tool at `script` as a module of this process, loaded once, or None when it can't be read with here.

    Started as a command, the tool is compiled from source every time, and most of what a command asks of it is a
    read. A tool that doesn't load, or lacks what a read takes, as another release's may, is run as a command instead,
    which says what is wrong with it."""
    key = str(script)
    if key not in STATE_READERS:
        name = f"delivery_state_reader_{hashlib.sha256(key.encode()).hexdigest()[:12]}"
        tool = None
        try:
            spec = importlib.util.spec_from_file_location(name, script)
            tool = importlib.util.module_from_spec(spec)
            sys.modules[name] = tool  # where the tool's own classes look their module up
            sys.dont_write_bytecode = True  # the release's modules leave no bytecode in the installed generation
            spec.loader.exec_module(tool)
        except BaseException as error:
            sys.modules.pop(name, None)
            # A tool that exits as it loads is run as a command; a stop that lands while it loads is still a stop.
            if isinstance(error, (KeyboardInterrupt, Terminated)):
                raise
            tool = None
        if tool is not None and not all(callable(getattr(tool, wanted, None)) for wanted in STATE_READER_NAMES):
            sys.modules.pop(name, None)
            tool = None
        STATE_READERS[key] = tool
    return STATE_READERS[key]


def shown_record(release: Path, state: Path) -> dict:
    """What the release's state tool prints for `show` on the record at `state`: read in this process, through the
    calls the command itself makes, and refused in the words a failed command is."""
    script = release / STATE_TOOL
    argv = [sys.executable, "-B", str(script), "--dir", str(state), "show"]
    tool = state_reader(script)
    if tool is None:
        return json.loads(run(argv).stdout)
    try:
        return json.loads(tool.emitted({**tool.show(Path(state)), "publication": tool.publication(Path(state))}))
    except tool.StateError as error:
        refused = tool.emitted({"ok": False, "code": error.code, "error": str(error)})
    except Exception:
        refused = traceback.format_exc()
    raise Stop(f"{' '.join(map(str, argv[:4]))} ... failed: {refused.strip()[-600:]}")


def load_state() -> dict:
    state_script()
    return shown_record(cfg().release, cfg().state)


def sibling_story_keys(state: Path | None) -> set[str]:
    """The stories a same-epic sibling delivery holds in the last kept read of it by the record in ``state``: an `after`
    key may name one. Empty without a record, or one that names no sibling."""
    try:
        record = json.loads((Path(state) / "state.json").read_text(encoding="utf-8")) if state else {}
    except (OSError, ValueError):
        return set()
    rows = record.get("siblings") if isinstance(record, dict) else None
    return {story["subject"] for row in (rows if isinstance(rows, list) else [])
            if isinstance(row, dict) and row.get("lastOutcome") != "other-epic"
            for story in (row.get("stories") if isinstance(row.get("stories"), list) else [])
            if isinstance(story, dict) and isinstance(story.get("subject"), str)}


def journal_entries(kind: str, subject: str) -> list[dict]:
    return [e for e in load_state()["journal"] if e.get("kind") == kind and e.get("subject") == subject]


def review_dir(key: str, root: Path | None = None) -> Path:
    path = (root or repo()) / cfg().work / "review" / key
    path.mkdir(parents=True, exist_ok=True)
    return path


def receipt_path(c: Config) -> Path:
    """The repository's receipt; a release named by the `release` key that lives in another installation is
    identified by that installation's receipt, beside its generations."""
    own = c.root / RECEIPT
    if own.exists() or not c.release_override:
        return own
    return c.release.resolve().parent.parent / "active.json"


def generation_problem(c: Config) -> str | None:
    """Why the running generation's release identity can't be read from the receipt, as the setup check says it."""
    return generation_problem_at(receipt_path(c), c.release.resolve().name)


def generation_problem_at(path: Path, generation: str) -> str | None:
    if not path.exists():
        return (f"wrong: no receipt at {path}, so the running generation {generation} has no release identity; "
                f"fix: install the release into the repository and run {TOOL_PATH} from it")
    try:
        receipt = json.loads(path.read_text())
    except ValueError as error:
        return f"wrong: the receipt {path} isn't JSON ({error}); fix: reinstall the release into the repository"
    if not isinstance(receipt, dict):
        return f"wrong: the receipt {path} isn't JSON describing a release; fix: reinstall the release into the repository"
    entries = [receipt] + ([receipt["previous"]] if isinstance(receipt.get("previous"), dict) else [])
    if not any(entry.get("generation") == generation for entry in entries):
        return (f"wrong: the running generation {generation} is neither the current nor the previous generation in "
                f"{path}; fix: run the tool as {TOOL_PATH}, from the repository's installed generation")
    return None


def release_tuple() -> dict:
    """The binding tuple of the generation that is running, from its own entry in the receipt: the current one, or
    `previous` while an older generation is still running after an update. Never another generation's."""
    c = cfg()
    problem = generation_problem(c)
    if problem:
        raise Stop(problem)
    receipt = json.loads(receipt_path(c).read_text())
    generation = c.release.resolve().name
    entry = next(e for e in [receipt, receipt.get("previous") or {}] if e.get("generation") == generation)
    return {k: entry["release"][k] for k in ("releaseId", "profile", "archiveSha256", "metadataSha256")}


def graph_digest() -> str:
    return hashlib.sha256((cfg().release / "workflows/delivery-v1.json").read_bytes()).hexdigest()


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


# -- plan context ---------------------------------------------------------------------------

def plan_sections(text: str) -> list[tuple[int, str, str]]:
    """(level, heading text, section text including the heading) for every Markdown heading."""
    heads = [(m.start(), len(m.group(1)), m.group(2).strip()) for m in re.finditer(r"^(#{1,6}) (.+)$", text, re.M)]
    sections = []
    for i, (start, level, title) in enumerate(heads):
        end = next((s for s, lv, _ in heads[i + 1:] if lv <= level), len(text))
        sections.append((level, title, text[start:end].strip()))
    return sections


def story_section(sections: list[tuple[int, str, str]], key: str) -> str | None:
    """The first section whose heading names the story's key."""
    return next((body for _, title, body in sections if re.search(rf"(?<![\w-]){re.escape(key)}(?![\w-])", title)), None)


def context_section(sections: list[tuple[int, str, str]], name: str) -> str | None:
    return next((body for _, title, body in sections if title == name or title.startswith(name)), None)


def plan_context(key: str, text: str | None = None) -> str:
    """The plan's part for one story: its section, the table rows naming it and the delivery's context sections. From
    `text` when given (the plan at a named commit), else as the settings shelf reads it."""
    c = cfg()
    if text is None:
        text = c.shelf.text(c.plan)
    if text is None:
        raise Stop(f"the plan {c.shelf.where(c.plan)} is missing")
    sections = plan_sections(text)
    own = story_section(sections, key)
    if own is None:
        raise Stop(f"no heading in {c.plan} names {key}")
    names = {key, c.label(key)}
    rows = [line for line in text.splitlines() if line.startswith("|")
            and any(re.search(rf"(?<![\w-]){re.escape(n)}(?![\w-])", line) for n in names)]
    parts = [own]
    if rows:
        parts += ["", "Table rows naming this story:", *rows]
    for name in c.context_sections:
        body = context_section(sections, name)
        parts += ["", body if body else f"(no '{name}' section in the plan)"]
    return "\n".join(parts)


# -- lane: review rounds -------------------------------------------------------------------

def lens_checkout(key: str, short: str) -> Path:
    """A lens's one checkout for a story's review, kept across its rounds."""
    return repo() / cfg().work / "lens" / f"{key}-{short}"


def prepared_stamp(checkout: Path) -> Path:
    """Beside the checkout, not in it: what the checkout was last prepared for."""
    return checkout.with_name(checkout.name + ".prepared.json")


# Files that decide what the prepare commands install, by name at any depth, besides the files those commands name.
DEPENDENCY_FILES = {"package.json", "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml",
                    "bun.lockb", "pyproject.toml", "setup.py", "setup.cfg", "uv.lock", "poetry.lock", "Pipfile",
                    "Pipfile.lock", "Gemfile", "Gemfile.lock", "go.mod", "go.sum", "Cargo.toml", "Cargo.lock",
                    ".python-version", ".nvmrc", ".node-version", ".tool-versions"}


def dependency_fingerprint(candidate: str, commands: list[list[str]]) -> str:
    """The prepare commands and the candidate's blobs of every dependency file: a change in either re-prepares."""
    named = {a.removeprefix("./") for argv in commands for a in argv}
    picked = []
    for line in filter(None, git("ls-tree", "-r", "-z", "--full-tree", candidate).split("\0")):
        path = line.split("\t", 1)[1]
        name = path.rsplit("/", 1)[-1]
        if name in DEPENDENCY_FILES or re.fullmatch(r"requirements.*\.txt", name) or path in named:
            picked.append(line)
    return hashlib.sha256(json.dumps([commands, picked]).encode()).hexdigest()


def ready_lens_checkout(checkout: Path, candidate: str) -> None:
    """Bring a lens's checkout to exactly this round's candidate. One kept from an earlier round is reset: tracked
    changes and untracked files go, while ignored files (the prepared environment) stay unless a dependency changed, in
    which case they go too and the prepare commands run again. A missing or broken checkout is made afresh."""
    commands = prepare_commands()
    fingerprint = dependency_fingerprint(candidate, commands)
    stamp = prepared_stamp(checkout)
    top = run(["git", "rev-parse", "--show-toplevel"], cwd=checkout, check=False) if checkout.is_dir() else None
    if top is not None and top.returncode == 0 and Path(top.stdout.strip()).resolve() == checkout.resolve():
        git("checkout", "-q", "--force", "--detach", candidate, cwd=checkout)
        git("clean", "-q", "-ffd", cwd=checkout)
        prepared = json.loads(stamp.read_text()).get("dependencies") if stamp.exists() else None
        if prepared == fingerprint:
            return
        git("clean", "-q", "-ffdx", cwd=checkout)
    else:
        remove_checkout(checkout)
        checkout.parent.mkdir(parents=True, exist_ok=True)
        git("worktree", "add", "--detach", "-q", str(checkout), candidate)
    stamp.unlink(missing_ok=True)
    for argv in commands:
        run(argv, cwd=checkout)
    stamp.write_text(json.dumps({"candidate": candidate, "dependencies": fingerprint}, indent=2) + "\n")


def remove_lens_checkout(checkout: Path) -> None:
    remove_checkout(checkout)
    prepared_stamp(checkout).unlink(missing_ok=True)


def remove_checkout(path: Path) -> None:
    if path.exists() or path.is_symlink():
        git("worktree", "remove", "--force", str(path), check=False)
        shutil.rmtree(path, ignore_errors=True)
    git("worktree", "prune", check=False)


def prepare_commands() -> list[list[str]]:
    c = cfg()
    if c.prepare is not None:
        return c.prepare
    return (c.shelf.json(".agents/orchestration.json") or {}).get("prepare", [])


EVIDENCE_HEADING = "## Evidence so far"


def seed_context(key: str) -> Path:
    """The review context: the plan's part, read from the delivery base as it stands now, and the lane's own evidence.
    Every round seeds the plan's part again, so a lens never reviews against a plan the lead has since changed; the
    lane's "Evidence so far" is kept as written. A context without that heading is the lane's own, left as it is."""
    path = review_dir(key) / "context.md"
    c = cfg()
    sha = git("rev-parse", "--verify", "--quiet", c.base_ref, check=False)
    # The plan as the base has it now: a lane's own checkout, and so a shelf reading it, holds the copy its branch forked with.
    shown = run(["git", "show", f"{sha}:{c.plan}"], check=False) if sha else None
    plan = shown.stdout if shown is not None and shown.returncode == 0 else None
    sha = sha if plan is not None else None
    where = (f"Delivery base `{c.base_ref}` at `{sha}`; the plan is `{c.plan}` there (approved, binding). Read it as "
             f"`git show {sha}:{c.plan}`, not your checkout's copy, which is only as new as your candidate's fork."
             if sha else f"Delivery base `{c.base_ref}`; the plan is `{c.plan}` (approved, binding).")
    head = (f"# Review context: {key} ({c.label(key)}), part of {c.delivery}\n\n"
            f"Repository: your private checkout; read its root instruction file. {where} Reference stories, once the "
            "lead names them, are in the assignment.\n\n"
            f"## Ticket contract and plan unit\n\n{plan_context(key, plan)}\n\n")
    if path.exists():
        text = path.read_text()
        # The lane's heading is a line of its own, and the last such line: the plan's part may mention it too.
        found = list(re.finditer(rf"^{re.escape(EVIDENCE_HEADING)}[ \t]*$", text, re.M))
        if found:
            path.write_text(head + text[found[-1].start():])
        return path
    path.write_text(head + f"{EVIDENCE_HEADING}\n\n"
                    f"{CONTEXT_TODO}: the test-first or characterization runs (red then green), the gate results "
                    "(run_delivery.py gate), mutants tried, and known limits. The in-app check records are attached to each brief.\n")
    return path


def flow_log(name: str, key: str) -> Path:
    """The lead-side, append-only logs beside the record (lanes write them through this tool, never by hand)."""
    folder = cfg().flow_log
    folder.mkdir(parents=True, exist_ok=True)
    return folder / f"{key}.{name}.jsonl"


def read_log(name: str, key: str) -> list[dict]:
    path = flow_log(name, key)
    entries = [json.loads(line) for line in path.read_text().splitlines() if line.strip()] if path.exists() else []
    return carried_with_peers(path.parent, key, name, entries)


def append_log(name: str, key: str, entry: dict) -> None:
    stamp = carried_stamp(cfg(), name, key)
    with open(flow_log(name, key), "a") as log:
        log.write(json.dumps({**entry, **stamp, "at": now()}) + "\n")


def carried_with_peers(folder: Path, key: str, name: str, entries: list[dict]) -> list[dict]:
    """A flow log's entries, with a shared record's peers' carried ones in their carried order (D21)."""
    if name not in tracker_publisher.CARRIED_LOGS:
        return entries
    theirs = tracker_publisher.peers_file(folder, key, name)
    return tracker_publisher.carried_order(name, [*entries, *tracker_publisher.read_lines(theirs)]) \
        if theirs.exists() else entries


def shared_seat(c) -> tuple | None:
    """On a shared record: the state tool, the record's journal and this checkout's seat; None on an unshared one or a
    record that can't be read."""
    if getattr(c, "state", None) is None or not (json_object(Path(c.state) / "state.json").get("meta") or {}).get("collab"):
        return None
    tool = _validator(c.release)
    try:
        collab = tool.collab_of(tool.read_state(c.state))
        journal = tool.read_journal(c.state)
    except (tool.StateError, OSError, ValueError):
        return None
    seat = tool.local_seat(c.state, collab["key"]) if collab else None
    return (tool, journal, seat) if seat else None


def carried_stamp(c, name: str, key: str) -> dict:
    """What a carried flow-log entry written on a shared record records (D21): its seat, and the local id of the
    transfer that began the writer's tenure of the log's scope, null for a tenure from the record's start or a scope it
    doesn't hold. Nothing on an unshared record, or for a log that isn't carried."""
    rule = tracker_publisher.CARRIED_LOGS.get(name)
    found = shared_seat(c) if rule is not None else None
    if found is None:
        return {}
    tool, journal, seat = found
    scope = rule["scope"]
    if scope == "lane":
        state = json_object(Path(c.state) / "state.json")
        lane = next((item.get("lane") for part in ("queue", "planned") for item in state.get(part, [])
                     if item.get("subject") == key and item.get("lane")), None)
        scope = f"lane:{lane}" if lane else None
    tenure = next((entry["id"] for entry in reversed(journal) if entry["kind"] == "scope.transferred"
                   and entry["data"]["scope"] == scope and entry["data"]["to"] == seat), None) \
        if scope and tool.holds(journal, seat, scope) else None
    return {"by": seat, "tenureId": tenure}


def carried_logs(c, tool, journal: list[dict], seat: str) -> dict:
    """This seat's own entries of each carried flow log, by log and file key, with their journal ids as origins:
    what its partition carries. An entry naming a journal id with no origin waits for a later carry."""
    origin_of = tool.journal_origins(journal)
    logs: dict = {}
    for name, rule in tracker_publisher.CARRIED_LOGS.items():
        for key in [c.delivery, *sorted(set(c.stories) - {c.delivery})]:
            carried = []
            for entry in tracker_publisher.read_flow(c.flow_log, key, name, peers=False):
                if entry.get("by") != seat or (rule.get("only") and rule["only"] not in entry):
                    continue
                out = {field: value for field, value in entry.items() if field != "tenureId"}
                out["tenure"] = origin_of.get(entry.get("tenureId"))
                if any(entry.get(field) is not None and entry[field] not in origin_of for field in rule["journal"]):
                    continue
                out.update({field: origin_of[entry[field]] for field in rule["journal"] if entry.get(field) is not None})
                carried.append(out)
            if carried:
                logs.setdefault(name, {})[key] = carried
    return logs


def peer_logs(c, tool, journal: list[dict], seat: str, peers: dict) -> None:
    """Every peer's carried flow-log entries written beside this machine's logs, translated to its own journal ids, in
    each peer's carried order; a file a peer no longer carries anything for is emptied. ``peers``: each peer seat's
    carried inputs."""
    local_of = {(origin["seat"], origin["seq"]): number for number, origin in tool.journal_origins(journal).items()}
    later = max(local_of.values(), default=0) + 1  # a tenure not yet ingested here sorts after every known one
    wanted: dict[tuple[str, str], list[dict]] = {}
    for peer in sorted(peers):
        for name, files in ((peers[peer] or {}).get("logs") or {}).items():
            rule = tracker_publisher.CARRIED_LOGS.get(name)
            if rule is None or not isinstance(files, dict):
                continue
            for key, entries in files.items():
                for entry in entries if isinstance(entries, list) else []:
                    named = [entry.get(field) for field in rule["journal"] if entry.get(field) is not None]
                    if any(not isinstance(origin, dict) or (origin.get("seat"), origin.get("seq")) not in local_of
                           for origin in named):
                        continue
                    tenure = entry.get("tenure")
                    taken = {field: value for field, value in entry.items() if field != "tenure"}
                    taken["by"] = peer
                    taken["tenureId"] = None if not isinstance(tenure, dict) else \
                        local_of.get((tenure.get("seat"), tenure.get("seq")), later)
                    taken.update({field: local_of[(entry[field]["seat"], entry[field]["seq"])]
                                  for field in rule["journal"] if entry.get(field) is not None})
                    wanted.setdefault((name, key), []).append(taken)
    existing = {(path.name[len(f"{key}."):-len(tracker_publisher.PEERS + ".jsonl")], key)
                for key in [c.delivery, *c.stories] for path in Path(c.flow_log).glob(f"{key}.*{tracker_publisher.PEERS}.jsonl")}
    for name, key in sorted(set(wanted) | {(name, key) for name, key in existing if name in tracker_publisher.CARRIED_LOGS}):
        path = tracker_publisher.peers_file(Path(c.flow_log), key, name)
        text = "".join(json.dumps(entry, sort_keys=True) + "\n" for entry in wanted.get((name, key), []))
        if not path.exists() or path.read_text(encoding="utf-8") != text:
            path.parent.mkdir(parents=True, exist_ok=True)
            replace_file(path, text)


def peers_inputs(c, tool, journal: list[dict], seat: str) -> dict:
    """What each admitted peer's fetched partition carries of its machine-local inputs, by seat; a partition that
    can't be read yet is left out."""
    link, seats, peers = tool._collab(), tool.derived_seats(journal), {}
    for peer in sorted(seats):
        if peer != seat and seats[peer].get("admitted"):
            got = link.peer_inputs(Path(c.state), peer)
            if got is not None:
                peers[peer] = got
    return peers


def closed_entry(c, tool, journal: list[dict]) -> dict | None:
    """The origin of the delivery.closed whose close this machine archived: closed.json names it once the archive
    landed."""
    kept = load_json(lead_file(c, "closed.json")) or {}
    return tool.journal_origins(journal).get(kept.get("entry")) if kept.get("archive") else None


def carry_close(c) -> str | None:
    """On a shared record, once closed.json is written: this seat's inputs kept, so its partition carries the archived
    close's origin, and pushed at once, since the supervisor and its sync loop stop with the close. A push that fails is
    said; the next sync loop to run pushes it."""
    found = shared_seat(c)
    if found is None:
        return None
    inputs_step(c)
    try:
        found[0]._collab().push(Path(c.state), remote=c.remote)
    except (found[0].StateError, OSError, subprocess.SubprocessError) as error:
        return f"the archived close isn't pushed yet ({error}); the sync loop pushes it when it next runs"
    return "pushed the archived close to the peers"


def closed_by_holder(c) -> bool:
    """On a shared record, whether the delivery holder's machine archived the close that closes the delivery now: its
    partition carries that close's origin. A close in progress, or one reopened before its archive, isn't."""
    found = shared_seat(c)
    if found is None:
        return False
    tool, journal, seat = found
    closing = latest_close(journal)
    if closing is None or "origin" not in closing:
        return False
    origin = {"seat": closing["origin"]["seat"], "seq": closing["origin"]["seq"]}
    return any((inputs or {}).get("closedEntry") == origin for inputs in peers_inputs(c, tool, journal, seat).values())


def peer_checkouts_left(c) -> list[str]:
    """On a shared record, the merged or settled stories each peer's machine still has a checkout of."""
    found = shared_seat(c)
    if found is None:
        return []
    return sorted({key for inputs in peers_inputs(c, *found).values() for key in (inputs or {}).get("checkoutsLeft") or []})


def inputs_step(c) -> str:
    """On a shared record, every machine's pass: what this seat carries kept for its partition, and what its peers
    carry taken in (D21)."""
    found = shared_seat(c)
    if found is None:
        return "unshared"
    tool, journal, seat = found
    link = tool._collab()
    logs = carried_logs(c, tool, journal, seat)
    holds = tool.holds(journal, seat, "delivery")
    state = json_object(Path(c.state) / "state.json")
    held = sorted({item["lane"] for part in ("queue", "planned") for item in state.get(part, [])
                   if item.get("lane") and tool.holds(journal, seat, f"lane:{item['lane']}")})
    inputs = {"logs": logs,
              "checkoutsLeft": sorted({key for lane in held for key in lane_checkouts_left(c, Path(c.state), lane)}),
              "closedEntry": closed_entry(c, tool, journal) if holds else None,
              "plan": load_json(Path(c.state) / PLAN_FILE) if holds else None}
    link.keep_inputs(Path(c.state), inputs)
    peers = peers_inputs(c, tool, journal, seat)
    peer_logs(c, tool, journal, seat, peers)
    if not holds:
        # The delivery holder's built plan is shown here instead of one built from this machine's inputs.
        plan = (peers.get(tool.holder(journal, "delivery")) or {}).get("plan")
        path = Path(c.state) / PLAN_FILE
        if isinstance(plan, dict) and load_json(path) != plan:
            replace_file(path, json.dumps(plan, indent=2) + "\n")
    return f"carried {sum(len(entries) for files in logs.values() for entries in files.values())} entr(ies); " \
           f"took {len(peers)} peer(s)'"


def tracker_conf(c) -> dict:
    """How the tracker's updates are made: by the tracker publisher, through the host, or by hand (tracker-adapter/1)."""
    return tracker_publisher.settings(c.root, c.flow_raw, c.shelf.json(".agents/orchestration.json") or {})


@contextlib.contextmanager
def marked_decision(c, followup: dict | None = None):
    """Journal a decision the tracker publisher posts: the ledger's lock is held, waiting for it, across the journal
    write and its mark, so no publisher run sees the entry unmarked. Yields a list the journalled entry's id goes in."""
    written: list[int] = []
    with tracker_publisher.ledger_lock(c.state, wait=True):
        yield written
        for journal_id in written:
            tracker_publisher.mark(c.flow_log, c.delivery, journal_id, followup,
                                   carried_stamp(c, tracker_publisher.MARKS, c.delivery))


def journal_id(done: subprocess.CompletedProcess) -> int:
    return json.loads(done.stdout)["entry"]["id"]


def spec_digest(spec: dict, passthrough: list[str]) -> str:
    return hashlib.sha256(json.dumps([spec, passthrough], sort_keys=True).encode()).hexdigest()[:16]


def check_history(key: str, records: list[dict]) -> list[str]:
    """Checks whose current record passes under a spec that differs from an earlier failing run of the same name, and
    runs whose records were removed: what a lens or the lead must see to judge whether an eval was weakened."""
    runs = read_log("app-checks", key)
    notes = []
    names = {r["name"] for r in records}
    current = {r["name"]: spec_digest(r["spec"], r.get("passthrough", [])) for r in records}
    for name in sorted({e["name"] for e in runs}):
        failed_specs = {e["spec"]: e for e in runs if e["name"] == name and not e["pass"]}
        if name not in names:
            notes.append(f"`{name}`: its record was removed after {len([e for e in runs if e['name'] == name])} run(s)")
        else:
            changed = [e for d, e in failed_specs.items() if d != current[name]]
            if changed:
                notes.append(f"`{name}`: passes now, but failed earlier with a different spec: "
                             + "; ".join(f"`{json.dumps(e['specValue'], separators=(',', ':'))}`" for e in changed))
    return notes


def in_app_summary(key: str) -> str:
    """The story's in-app check records, so the testing lens can judge the evals, not just the verdicts."""
    folder = review_dir(key) / "app-checks"
    records = [json.loads(p.read_text()) for p in sorted(folder.glob("*.json"))] if folder.exists() else []
    if not records:
        return "None recorded yet."
    lines = []
    for r in records:
        failing = [rule for rule, ok in r["rules"].items() if not ok]
        results = [f"`{str(e.get('expr'))[:120]}` -> `{json.dumps(e.get('result', e.get('error')))[:80]}`"
                   for e in [*r["report"].get("evals", []), *r["report"].get("afterEvals", [])]]
        lines.append(f"- `{r['name']}` ({r['mode']}{', baseline' if r.get('baseline') else ''}, "
                     f"{'PASS' if r['pass'] else 'FAIL: ' + '; '.join(failing)}, head {str(r.get('head'))[:10]}): "
                     f"spec `{json.dumps(r['spec'], separators=(',', ':'))}`"
                     + (f", adapter args `{' '.join(r['passthrough'])}`" if r.get("passthrough") else "")
                     + (f"; results: {', '.join(results)}" if results else ""))
    history = check_history(key, records)
    if history:
        lines += ["", "History:", *[f"- {h}" for h in history]]
    return "\n".join(lines) + ("\n\nEverything you need from the records is above; you don't need to read them. Judge "
                               "whether each eval actually proves its acceptance criterion.")


# Under noDeferrals: an evidence string holding one of these, compared without regard to case, marks something a lens
# left unfixed, and the brief asks a lens that left nothing so to say it in words that hold none of them.
EVIDENCE_NOTE_WORDS = ("declined", "not filed", "surviving mutant")
NO_DEFERRALS_EVIDENCE = ('This delivery takes no deferrals: when you declined nothing, left nothing unfiled and left no '
                         'mutant alive, say so in `evidence` in the words "nothing left unfixed". Write "Declined", '
                         '"not filed" or "surviving mutant" in `evidence` only for something you left unfixed: the '
                         "hand-off refuses a round whose evidence carries one.")


def evidence_notes(outcome: dict) -> list[tuple[str, str]]:
    """A round's evidence notes, (lens, note), in its entries' order: each evidence string that holds a note word."""
    return [(entry["lens"], text) for entry in outcome.get("entries", [])
            for text in (entry.get("result") or {}).get("evidence", [])
            if isinstance(text, str) and any(word in text.lower() for word in EVIDENCE_NOTE_WORDS)]


def scoped_checks(span: str) -> str:
    """The brief's two per-round fills: the sensors to run, and the files the round's span changes."""
    changed = git("diff", "--name-only", span).splitlines()
    return ("- scoped sensor commands: the sensors the plan unit names, in the context refs below.\n"
            f"- test files in scope for this round: the tests among the files `git diff {span}` changes, and the "
            "tests that cover the rest: " + (", ".join(f"`{path}`" for path in changed) or "none") + ".")


def finding_ledger(prior: list[dict], closed: tuple[str, ...], legacy: bool) -> dict[str, list[str]]:
    """One lens's earlier findings by where its rounds left them, each in the order first raised: `open` is exactly
    what the next reduce carries and requires in `resolvedFindings`, `closed` what a state in `closed` closed, and
    `deferred` what was deferred and not since found fixed. `legacy` reads a story's older `resolutions` key, which a
    plan review's reduce never reads."""
    status: dict[str, str] = {}
    for entry in prior:
        result = entry.get("result") or {}
        for f in result.get("findings", []):
            status[f["id"]] = "deferred" if f.get("state") == "deferred" else "open"
        for x in result.get("resolvedFindings", result.get("resolutions", []) if legacy else []):
            if x.get("id") in status and x.get("state") == "deferred":
                status[x["id"]] = "deferred"
            elif x.get("id") in status and x.get("state") in closed:
                status[x["id"]] = "closed"
    return {kind: [i for i, s in status.items() if s == kind] for kind in ("open", "closed", "deferred")}


def id_list(ids: list[str]) -> str:
    return ", ".join(f"`{i}`" for i in ids) or "none"


def brief(key: str, round_no: int, lens: str, candidate: str, tree: str, merge_base: str,
          checkout: Path, prior: list[dict], prior_candidate: str | None) -> str:
    c = cfg()
    short, charter_file = c.lenses[lens]
    charter = Path(charter_file).read_text().strip()
    rel = release_tuple()
    context = (review_dir(key) / "context.md").read_text().strip()
    template = (TOOL / "templates/round-brief.md").read_text()
    if round_no == 1:
        kind = (f"`assessment round`: this lens's first result-carrying round; review the whole subject, the "
                f"delivered diff `git diff {merge_base}..{candidate}` in your checkout, and carry no prior entries "
                "or candidate resolution pairs.")
        carry = "None: this is an assessment round, which carries no prior entries."
        resolutions = "None: an assessment round spans no delta and needs no resolution pair."
        later = "- `lateFindings`: none on an assessment round; omit it."
    else:
        kind = ("`verification round`: re-check every carried finding and its approval condition against the delta "
                f"you derive yourself (`git diff {prior_candidate}..{candidate}`), then review that delta. A change "
                "adopted differently from its approval condition, or declined, is re-checked like any carried finding.")
        carry = "\n".join(
            f"- round {e['binding']['round']}: `{json.dumps({'binding': e['binding'], 'state': e['state'], 'result': e.get('result')}, separators=(',', ':'))}`"
            for e in prior)
        resolutions = (f"- `{prior_candidate}` resolves to git commit `{prior_candidate}`\n"
                       f"- `{candidate}` resolves to git commit `{candidate}`")
        later = ("- `lateFindings`: ids of this result's own findings you raised late (against lines unchanged since "
                 "your previous round); omit when none.\n"
                 "- `resolvedFindings`: required. One entry per finding, "
                 '`{"id", "state": "closed|fixed|withdrawn|deferred|open", "resolution": "..."}`. Every finding this '
                 "lens raised in an earlier round that is still open must appear; one closed in an earlier round may be "
                 "listed again or left out. Re-check each finding this lens deferred in an earlier round, and list each "
                 "one you find fixed as `closed`, `fixed` or `withdrawn`: only that listing records a deferral as fixed, "
                 "and one listed as `deferred` or `open`, or not listed, stays deferred and is filed as a follow-up at "
                 "close. A deferral (P2/P3 only) also carries `deferredIssue`.")
        ledger = finding_ledger(prior, tuple(s for s in CLOSED if s != "deferred"), legacy=True)
        later += ("\n- Still open for this lens, so each listed in `resolvedFindings` exactly once: "
                  f"{id_list(ledger['open'])}.\n"
                  f"- Closed in an earlier round, so `resolvedFindings` may leave them out: {id_list(ledger['closed'])}.\n"
                  f"- Deferred in an earlier round, to re-check as above: {id_list(ledger['deferred'])}.")
    if getattr(c, "no_deferrals", False):
        later += f"\n- {NO_DEFERRALS_EVIDENCE}"
    span = f"{merge_base}..{candidate}" if round_no == 1 else f"{prior_candidate}..{candidate}"
    if round_no <= c.bound:
        bound_text = f"`ordinary counted`: round {round_no} of {c.bound}, counted against the declared bound."
    else:
        bound_text = f"`grace`: round {round_no} with declared bound {c.bound}, outside the count."
    values = {
        "lens": lens, "short": short, "key": key, "round": str(round_no), "candidate": candidate, "tree": tree,
        "releaseId": rel["releaseId"], "profile": str(rel["profile"]), "archiveSha256": rel["archiveSha256"],
        "metadataSha256": rel["metadataSha256"], "graph": graph_digest(), "bound_text": bound_text, "kind": kind,
        "carry": carry, "resolutions": resolutions, "charter": charter, "later": later, "checkout": str(checkout),
        "context": context, "in_app": in_app_summary(key), "severities": STORY_SEVERITIES, "checks": scoped_checks(span),
        "flow": flow_command(), "machine": machine_command(), "delivery_option": delivery_option(c),
        "result": str(result_path(review_dir(key), round_no, short)),
    }
    return re.sub(r"\{\{(\w+)\}\}", lambda m: values[m.group(1)], template)


LEGACY_LENSES = "none recorded: the story's review began before lenses were chosen, so every declared lens runs"


NOT_ON_REQUEST = "every story lens not on request"


def brief_lenses(c, key: str) -> list[str]:
    """The lenses a story's delivery-file entry asks for, its brief lenses, in declaration order. Each must be a
    declared story lens: any other is refused, naming it."""
    return story_brief_lenses(c.story_lenses, key, c.stories[key])


def story_brief_lenses(story_lenses: list[str], key: str, story: dict) -> list[str]:
    named = story.get("lenses", [])
    if (not isinstance(named, list) or not all(isinstance(lens, str) for lens in named)
            or len(set(named)) != len(named)):
        raise Stop(f"story {key}: lenses must list story lens ids, each once, not {named!r}")
    for lens in named:
        if lens not in story_lenses:
            raise Stop(f"story {key}: lenses names {lens}, which isn't a declared story lens; the declared story "
                       f"lenses are {', '.join(story_lenses)}")
    return [lens for lens in story_lenses if lens in named]


def plan_lenses(c) -> dict:
    """Each story's brief lenses, for the stories that name any."""
    return {key: story["lenses"] for key, story in c.stories.items() if story.get("lenses")}


def lenses_words(lenses: list[str]) -> str:
    """A story's brief lenses as a plan change's before or after reads them."""
    return f"lenses: {', '.join(lenses)}" if lenses else "no lenses"


def on_request_line(c) -> str:
    """The lane brief's line for the lenses on request: each with its purpose and the stories whose brief asks for it."""
    def item(lens: str) -> str:
        asking = [key for key in c.stories if lens in c.stories[key].get("lenses", [])]
        origin = f" (the brief of {', '.join(asking)} asks for it)" if asking else ""
        return f"`{lens}`{origin}: {charter_purpose(c.lenses[lens][1]) or '(its charter states no purpose)'}"
    return ("- On request, run only when `--lenses` or the story's brief names it: "
            + "; ".join(item(lens) for lens in c.on_request))


def accepted_brief(c, key: str, lenses: list[str], meta: dict | None) -> tuple[str, list[str]]:
    """At acceptance: where each lens on request in the story's set came from, as its lens line shows it, and each
    brief lens the set lacks, as a problem naming its removal."""
    if not (meta or {}).get("lensesReason"):
        return "", []
    # Round 1's own record, as handed: no lookup that a lens since withdrawn could stop.
    requested = (meta or {}).get("requested") or {}
    return (requested_text({lens: who for lens, who in requested.items() if lens in lenses}),
            unrun_brief_lenses(c, key, lenses))


def latest_lenses(c, folder: Path) -> tuple[list[str], str | None, dict[str, str]]:
    """The story's review lenses, why, and where each lens on request in them came from, fixed by round 1's meta, as
    obtain-review fixes a review's lens set before its first round. A round 1 meta with no reason was prepared before
    lenses were chosen: its story runs every declared lens, as it did then, plan-only lenses included."""
    first = load_json(folder / "round-1.meta.json") or {}
    if not first.get("lensesReason"):
        return list(c.lenses), None, {}
    gone = [lens for lens in first["lenses"] if lens not in c.lenses]
    if gone:
        raise Stop(f"the story's review lenses include {', '.join(gone)}, which this repository no longer declares; "
                   "declare it again, or restart round 1 with --restart and other --lenses")
    return list(first["lenses"]), first["lensesReason"], dict(first.get("requested", {}))


def story_lens_set(c, folder: Path) -> tuple[list[str], str | None]:
    """The story's review lenses and why, fixed by round 1's meta (see `latest_lenses`)."""
    lenses, reason, _ = latest_lenses(c, folder)
    return lenses, reason


def default_lenses(c, key: str) -> tuple[list[str], str]:
    """Round 1's set without --lenses: the mandated pair, every story lens not on request, and the brief's lenses."""
    brief = brief_lenses(c, key)
    lenses = [lens for lens in c.story_lenses if lens not in c.on_request or lens in brief]
    if not c.on_request and not brief:
        return lenses, EVERY_STORY_LENS
    return lenses, NOT_ON_REQUEST + (f", and the brief's {', '.join(brief)}" if brief else "")


def requested_lenses(c, key: str, lenses: list[str]) -> dict[str, str]:
    """Where each lens on request in a round 1 set came from: the story's brief, or else the lane's --lenses."""
    brief = brief_lenses(c, key)
    return {lens: "brief" if lens in brief else "lane" for lens in lenses if lens in c.on_request}


def unrun_brief_lenses(c, key: str, lenses: list[str]) -> list[str]:
    """Each brief lens the story's set lacks, which only a hand edit after round 1 leaves: the set is fixed there, so
    the lens comes out of the entry, and a review it missed belongs in a follow-up."""
    return [f"{key}'s brief asks for {lens}, but its review's lens set, fixed at round 1, lacks it: take it out of the "
            f"story's entry with lead-plan change --kind lenses --subjects {key} --lenses <the others> --why <why>"
            for lens in brief_lenses(c, key) if lens not in lenses]


def chosen_lenses(c, args) -> tuple[list[str], str] | None:
    """`--lenses` and `--lenses-reason`, checked: the set in declaration order and its reason, or None without them."""
    given, reason = getattr(args, "lenses", None), getattr(args, "lenses_reason", None)
    if given is None:
        if reason is not None:
            raise Stop("--lenses-reason goes with --lenses: name the lenses it gives the reason for")
        return None
    if reason is None or not reason.strip():
        raise Stop("--lenses needs --lenses-reason: say why the story's review takes these lenses")
    if len(reason.strip()) > LENSES_REASON:
        raise Stop(f"--lenses-reason is {len(reason.strip())} characters; keep it to {LENSES_REASON}")
    named = [lens.strip() for lens in given.split(",")]
    story = f"the declared story lenses are {', '.join(c.story_lenses)}"
    unknown = [lens or "an empty id" for lens in named if lens not in c.story_lenses]
    if unknown:
        raise Stop(f"--lenses names {', '.join(unknown)}, which this repository doesn't declare as a story lens; {story}")
    repeated = sorted({lens for lens in named if named.count(lens) > 1})
    if repeated:
        raise Stop(f"--lenses names {', '.join(repeated)} more than once; {story}")
    missing = [lens for lens in MANDATED_LENSES if lens not in named]
    if missing:
        raise Stop(f"--lenses leaves out {', '.join(missing)}: every story round runs the mandated lenses "
                   f"{', '.join(MANDATED_LENSES)}; {story}")
    return [lens for lens in c.story_lenses if lens in named], reason.strip()


def requested_text(requested: dict[str, str] | None) -> str:
    """Where each lens on request came from, as the lens lines show it after the reason; nothing when none ran."""
    return (f"; on request: {', '.join(f'{lens} (asked for by the {who})' for lens, who in requested.items())}"
            if requested else "")


def lenses_text(lenses: list[str], reason: str | None, requested: dict[str, str] | None = None) -> str:
    return f"{', '.join(lenses)}; reason: {reason or LEGACY_LENSES}{requested_text(requested)}"


def on_request_text(c) -> str:
    """The lenses on request, each with its charter's purpose, as doctor and config list them."""
    def purpose(lens: str) -> str:
        charter = Path(c.lenses[lens][1])
        return (charter.exists() and charter_purpose(charter)) or "(its charter states no purpose)"
    return "; ".join(f"{lens}: {purpose(lens)}" for lens in c.on_request)


def charter_purpose(path: Path) -> str:
    """A charter's purpose: its first line after the title that isn't blank or a heading, cut to LENS_PURPOSE."""
    lines = Path(path).read_text().splitlines()
    start = next((i + 1 for i, line in enumerate(lines) if line.lstrip().startswith("#")), 0)
    found = next((line.strip() for line in lines[start:] if line.strip() and not line.lstrip().startswith("#")), "")
    return found[:LENS_PURPOSE]


def round_files(folder: Path) -> list[Path]:
    files = [p for p in folder.glob("round-*.json") if re.fullmatch(r"round-\d+\.json", p.name)]
    return sorted(files, key=lambda p: int(p.stem.split("-")[1]))


def result_path(folder: Path, n: int, short: str) -> Path:
    return folder / f"result-r{n}-{short}.json"


def review_prepare(args) -> None:
    c = cfg()
    key = c.require(args.key)
    release_tuple()  # refuse an unidentified generation before anything is discarded, checked out or written
    n = args.round
    why = getattr(args, "why", None)
    if why is not None and not why.strip():
        raise Stop("--why is empty: give the round's reason, or leave --why out")
    folder = review_dir(key)
    if n < 1 or n > c.bound + 1:
        raise Stop(f"round {n} is outside 1..{c.bound} (plus one grace round)")
    if n == c.bound + 1 and not args.grace:
        raise Stop(f"round {n} is past the bound of {c.bound}: stop and report the blocker to the lead "
                   "(a grace round needs the lead's say-so, then --grace)")
    if (folder / f"round-{n}.json").exists():
        raise Stop(f"round {n} is already reduced; prepare round {n + 1}")
    for k in range(1, n):
        if not (folder / f"round-{k}.json").exists():
            raise Stop(f"round {k} has no round file; reduce it before preparing round {n}")
    meta_path = folder / f"round-{n}.meta.json"
    previous = json.loads(meta_path.read_text()) if meta_path.exists() else None
    if previous and not args.restart:
        raise Stop(f"round {n} is already prepared (at {previous['candidate'][:10]}). Reduce it, or pass --restart to "
                   "discard it; a restart is recorded and the lead has to accept it")
    # The story's lenses, fixed at round 1: chosen there with --lenses, else the default set.
    chosen = chosen_lenses(c, args)
    if n == 1:
        if chosen:
            left = [lens for lens in brief_lenses(c, key) if lens not in chosen[0]]
            if left:
                raise Stop(f"--lenses leaves out {', '.join(left)}: the story's brief asks for "
                           f"{'it' if len(left) == 1 else 'them'}, so every round of it runs "
                           f"{'it' if len(left) == 1 else 'them'}; name {'it' if len(left) == 1 else 'them'} too")
        lenses, reason = chosen or default_lenses(c, key)
        requested = requested_lenses(c, key, lenses)
    else:
        lenses, reason, requested = latest_lenses(c, folder)
        if chosen and chosen[0] != lenses:
            raise Stop(f"--lenses names {', '.join(chosen[0])}, but the story's lenses, fixed at round 1, are "
                       f"{', '.join(lenses)}: leave --lenses out to keep them")
    git("fetch", "-q", c.remote, c.base_branch)  # before the context, which reads the plan from the base
    context = seed_context(key)
    if CONTEXT_TODO in context.read_text():
        raise Stop(f"fill in 'Evidence so far' in {context} first (the rest is seeded from the plan)")
    candidate = clean_head()
    tree = git("rev-parse", "HEAD^{tree}")
    merge_base = git("merge-base", c.base_ref, "HEAD")
    lane = check_candidate_ownership(c, key, merge_base, candidate)
    prior_rounds = [json.loads(p.read_text()) for p in round_files(folder)]
    prior_candidate = prior_rounds[-1]["entries"][0]["binding"]["candidateRef"] if prior_rounds else None
    if prior_candidate == candidate:
        raise Stop("HEAD is the candidate of the previous round; commit the fixes first. When the round's findings were "
                   "settled without a change here (a ruling, or a fix on the base, which a lane doesn't merge), record "
                   f'that as its own commit, `git commit --allow-empty -m "{key}: <the ruling>"`, and note the ruling in '
                   "context.md's Evidence so far, so each round still has its own candidate")
    restarts = list(previous.get("restarts", [])) if previous else []
    attempts = previous.get("attempts", 0) if previous else 0
    if previous:
        # The previous preparation's lenses, and this one's: no result left from an earlier set is ever reduced.
        discarded = {}
        for lens in dict.fromkeys([*previous["lenses"], *lenses]):
            if lens not in c.lenses:
                continue
            short = c.lenses[lens][0]
            path = result_path(folder, n, short)
            if path.exists():
                discarded[lens] = digest(path)
                path.rename(folder / f"result-r{n}-{short}.discarded{len(restarts) + 1}.json")
        restarts.append({"at": now(), "previousCandidate": previous["candidate"], "discardedResults": discarded,
                         "previousLenses": previous["lenses"],
                         **({"previousLensesReason": previous["lensesReason"]} if previous.get("lensesReason") else {})})
    briefs = []
    for lens in lenses:
        short = c.lenses[lens][0]
        checkout = lens_checkout(key, short)
        ready_lens_checkout(checkout, candidate)
        if git("status", "--porcelain", cwd=checkout):
            raise Stop(f"preparing {checkout} left it dirty; the repository's prepare commands must not touch tracked files")
        prior = [next(e for e in r["entries"] if e["lens"] == lens) for r in prior_rounds]
        path = folder / f"brief-r{n}-{short}.md"
        path.write_text(brief(key, n, lens, candidate, tree, merge_base, checkout, prior, prior_candidate))
        briefs.append((lens, path, result_path(folder, n, short)))
    # The round in flight, journaled before its meta: a failed write leaves the round unprepared, to prepare again.
    started = {"round": n, "head": candidate, "lenses": lenses, "restart": bool(previous),
               **({"moved": int(git("rev-list", "--count", f"{prior_candidate}..{candidate}"))} if prior_candidate else {}),
               **({"why": why.strip()} if why is not None else {})}
    # An older generation still running here may not write the record, which another generation now writes: the round
    # goes on unjournalled, as rounds did before their start was, and the views show none under way.
    done = state_tool("journal", "--writer", "lane", "--kind", "review.started", "--subject", key, "--lane", lane,
                      "--data", json.dumps(started), check=False)
    if done.returncode != 0:
        if '"writer_generation_mismatch"' not in (done.stdout or "") + (done.stderr or ""):
            raise Stop(f"journal review.started failed: {(done.stderr or done.stdout).strip()[-600:]}")
        print(f"{key} round {n}: the record's writer is another generation, so this round's start isn't journalled: "
              "the views won't show it as under way")
    meta_path.write_text(json.dumps({"round": n, "candidate": candidate, "tree": tree, "startedAt": now(),
                                     "lenses": lenses, **({"lensesReason": reason, "requested": requested}
                                                          if reason else {}),
                                     "attempts": attempts, "restarts": restarts}, indent=2))
    append_log("prepares", key, {"round": n, "candidate": candidate, "restart": bool(previous)})
    state_tool("focus", "--lane", lane, "--text", f"{key} review round {n}", "--state", "reviewing", check=False)
    print(f"{key} round {n}: candidate {candidate[:10]}, tree {tree[:10]}" + (f" (restart {len(restarts)})" if restarts else ""))
    print(f"lenses: {lenses_text(lenses, reason, requested)}")
    for line in guard_lines(key, repo(), candidate):  # shown, never run here
        print(line)
    print()
    if n == 1 and not restarts:
        print("Start one reviewer per lens, in parallel, each with exactly this prompt. Keep track of each reviewer: "
              "later rounds resume the same one.")
    else:
        print("Resume the same reviewer for each lens, in parallel, with exactly this message. Only if a reviewer "
              "can't be resumed, start a fresh one with the same prompt and say so in the hand-off.")
    print("Each reviewer writes its final JSON to its result path as its last step. Wait for them in the foreground, "
          f"inside your turn: {flow_command()} review-wait {key} --round {n} returns once every result is in, and exits "
          "4 naming the lenses still out when its time runs out, so run it again. A reviewer that returned without "
          "writing its result: save its final JSON message, exactly as returned, to its result path. Never edit a "
          "result.\n")
    for lens, path, result in briefs:
        print(f"- {lens}\n  prompt: Read {path} and follow it exactly. As your last step, write your final JSON to "
              f"{result}, then reply with only that same JSON.\n"
              f"  result path: {result}")
    print(f"\nThen: {flow_command()} review-reduce {key} --round {n}, once {flow_command()} review-wait {key} --round {n} "
          "returns 0")


# review-wait's default deadline, inside a host's ten-minute command limit, and how often it looks.
REVIEW_WAIT_SECONDS, REVIEW_WAIT_POLL = 540, 5


def parsed_json(path: Path) -> bool:
    """Whether `path` holds JSON that parses: a result still being written, or not written, doesn't."""
    try:
        json.loads(path.read_text())
    except (OSError, ValueError):
        return False
    return True


def review_wait(args) -> None:
    """`review-wait <key> --round N [--seconds S]`: wait in the foreground until every lens's result path in the
    round's meta holds JSON that parses, then exit 0; exit 4 naming the lenses still out once S seconds run out."""
    c = cfg()
    key = c.require(args.key)
    n = args.round
    folder = review_dir(key)
    meta = load_json(folder / f"round-{n}.meta.json")
    if meta is None:
        raise Stop(f"round {n} isn't prepared: {flow_command()} review-prepare {key} --round {n} prepares it")
    if args.seconds < 0:
        raise Stop(f"--seconds is {args.seconds:g}: give zero or more")
    paths = {lens: result_path(folder, n, c.lenses[lens][0]) for lens in meta["lenses"] if lens in c.lenses}
    watch = clock()
    deadline = watch.time() + args.seconds
    while True:
        out = [lens for lens, path in paths.items() if not parsed_json(path)]
        if not out:
            print(f"{key} round {n}: every lens's result is in. Then: {flow_command()} review-reduce {key} --round {n}")
            return
        left = deadline - watch.time()
        if left <= 0:
            print(f"{key} round {n}: still out after {args.seconds:g}s: {', '.join(out)}. Wait again: "
                  f"{flow_command()} review-wait {key} --round {n}")
            sys.exit(4)
        watch.sleep(min(watch.poll(REVIEW_WAIT_POLL), left))


def flow_command() -> str:
    """The command briefs and messages name: the stable installed path, never a generation or projection path, or
    the configured release's own copy when the `release` key names one."""
    c = CFG
    if c is not None and c.release_override:
        return f"python3 -B {Path(c.release_override) / 'skills/run-delivery/scripts/run_delivery.py'}"
    return f"python3 -B {TOOL_PATH}"


def delivery_option(c) -> str:
    """` --delivery KEY` for a command a lens runs in its checkout, which is detached, so its branch names no delivery;
    nothing for a plan review with no delivery."""
    return f" --delivery {c.delivery}" if getattr(c, "delivery", None) else ""


def machine_command() -> str:
    """The machine ledger's command, as briefs name it: beside the run-delivery command `flow_command` names."""
    return flow_command().replace("skills/run-delivery/scripts/run_delivery.py", "skills/orchestrate-work/scripts/machine.py")


def _merge_queue():
    """The installed release's merge queue, for the rules a hand-off must judge as the queue will."""
    _validator()  # puts the release's orchestration scripts on the path
    import merge_queue  # noqa: E402
    return merge_queue


def _validator(release: Path | None = None):
    path = str((release or cfg().release) / "skills/orchestrate-work/scripts")
    if path not in sys.path:
        sys.path.insert(0, path)
    sys.dont_write_bytecode = True  # the release's modules leave no bytecode in the installed generation
    import delivery_state  # noqa: E402  (the installed release's own validator)
    return delivery_state


def _region_ownership():
    _validator()  # Use the installed orchestration scripts, as with the state tool.
    import region_ownership
    return region_ownership


def check_result(result: object, *, key: str, lens: str, short: str, n: int, meta: dict,
                 carried: set[str]) -> list[str]:
    """What's wrong with one lens result, as messages; empty when it matches its brief."""
    if not isinstance(result, dict):
        return ["is not a JSON object"]
    problems = []
    expect = {"schemaVersion": "review-lens-result/1", "lensId": lens, "subjectRef": key,
              "candidateRef": meta["candidate"], "round": n}
    for field, value in expect.items():
        if result.get(field) != value:
            problems.append(f"{field} is {result.get(field)!r}, expected {value!r}")
    if result.get("outcome") not in ("aligned", "changes-requested"):
        problems.append(f"outcome is {result.get('outcome')!r}")
    evidence = result.get("evidence")
    if not isinstance(evidence, list) or not evidence or not all(isinstance(e, str) for e in evidence):
        problems.append("evidence must be a non-empty list of strings")
    elif not any(meta["tree"] in e for e in evidence):
        problems.append(f"evidence doesn't name the reviewed tree {meta['tree']}")
    findings = result.get("findings")
    if not isinstance(findings, list):
        return problems + ["findings must be a list"]
    open_blocking = False
    ids = set()
    late_ids = result.get("lateFindings", [])
    late_ids = set(late_ids) if isinstance(late_ids, list) and all(isinstance(x, str) for x in late_ids) else set()
    for f in findings:
        if not isinstance(f, dict) or not isinstance(f.get("id"), str) or not isinstance(f.get("summary"), str):
            problems.append(f"finding {f!r} lacks id or summary")
            continue
        ids.add(f["id"])
        if not f["id"].startswith(f"{short}-r{n}-"):
            problems.append(f"finding id {f['id']} doesn't start with {short}-r{n}-")
        if f.get("severity") not in SEVERITIES:
            problems.append(f"finding {f['id']} has severity {f.get('severity')!r}")
        elif f["severity"] in ("P0", "P1"):
            if f.get("state") != "deferred":
                open_blocking = True
            elif f["severity"] == "P0":
                problems.append(f"finding {f['id']} is P0 and can't be deferred")
            # The out-of-delta rule's one deferral: a verification round's new P1 against lines unchanged since the
            # lens's last round, marked late, with what its follow-up item must say.
            elif n == 1:
                problems.append(f"finding {f['id']} is P1 and can't be deferred in an assessment round")
            elif f["id"] not in late_ids:
                problems.append(f"finding {f['id']} is a deferred P1 not listed in lateFindings: only a P1 outside "
                                "the delta is deferred")
            elif not str(f.get("deferredIssue", "")).strip():
                problems.append(f"finding {f['id']} is a deferred P1 with no deferredIssue: say what its follow-up "
                                "item must say")
        elif f.get("state") != "deferred" or not str(f.get("deferredIssue", "")).strip():
            problems.append(f"finding {f['id']} is {f['severity']}: file it with state deferred and a deferredIssue")
    if result.get("outcome") == "aligned" and open_blocking:
        problems.append("outcome is aligned but it raises an open P0/P1 finding")
    late = result.get("lateFindings", [])
    if not isinstance(late, list) or any(x not in ids for x in late):
        problems.append("lateFindings must list ids of this result's own findings")
    closures = result.get("resolvedFindings", result.get("resolutions", []))
    if not isinstance(closures, list):
        problems.append("resolvedFindings must be a list")
        closures = []
    missing = carried - {x.get("id") for x in closures if isinstance(x, dict)}
    if missing:
        problems.append(f"resolvedFindings leaves out carried finding(s) {sorted(missing)}")
    return problems


def round_counts(outcome: dict) -> tuple[dict, dict]:
    verdicts = {e["lens"]: ("approve" if e["result"]["outcome"] == "aligned" else "changes") for e in outcome["entries"]}
    counts = {p: sum(1 for e in outcome["entries"] for f in e["result"].get("findings", []) if f.get("severity") == p)
              for p in SEVERITIES}
    return verdicts, counts


def ensure_recorded(key: str, outcome: dict, lane: str, folder: Path) -> None:
    """The round in the record as the lane's own: its review.round, then the rounds so far captured at the round's
    candidate, so the live view shows the round's card and notes before hand-off. Each write is skipped once made,
    so a re-run finishes what a failure left; a story with a product run is reviewed through its run instead."""
    doc = load_state()
    ensure_journaled(key, outcome, lane, doc)
    item = next((i for i in [*doc["state"]["queue"], *doc["state"].get("planned", [])] if i["subject"] == key), None)
    if item is None or item.get("runId"):
        return
    rounds = [folder / f"round-{k}.json" for k in range(1, outcome["round"] + 1)]
    state_tool("capture-review", "--subject", key, "--candidate", outcome["entries"][0]["binding"]["candidateRef"],
               *[x for p in rounds for x in ("--outcome", str(p))])


def ensure_journaled(key: str, outcome: dict, lane: str, doc: dict) -> None:
    n = outcome["round"]
    if any(e.get("kind") == "review.round" and e.get("subject") == key and e["data"]["round"] == n
           for e in doc["journal"]):
        return
    verdicts, counts = round_counts(outcome)
    # The facts are the round and its history.
    facts = {"round": n, "startedAt": outcome["startedAt"], "finishedAt": outcome["finishedAt"],
             "verdicts": verdicts, "findings": counts,
             **({"refused": outcome["attempts"]} if outcome.get("attempts") else {}),
             **({"restarts": len(outcome["restarts"])} if outcome.get("restarts") else {})}
    start = latest_start(doc, key, n)
    state_tool("journal", "--writer", "lane", "--kind", "review.round", "--subject", key, "--lane", lane,
               "--data", json.dumps(facts), *(("--answers", str(start["id"])) if start else ()))


def latest_start(doc: dict, key: str, n: int | None = None) -> dict | None:
    """The story's latest review.started, when it is for round `n` (any round when `n` is None)."""
    start = next((e for e in reversed(doc["journal"]) if e.get("kind") == "review.started" and e.get("subject") == key), None)
    return start if start is not None and (n is None or start["data"]["round"] == n) else None


def carried_findings(prior: list[dict], lens: str) -> set[str]:
    """The lens's findings still open from earlier rounds: each round's result must say what became of them."""
    carried: set[str] = set()
    for r in prior:
        for e in r["entries"]:
            if e["lens"] == lens:
                carried |= {f["id"] for f in e["result"].get("findings", []) if f.get("state") != "deferred"}
                carried -= {x["id"] for x in e["result"].get("resolvedFindings", e["result"].get("resolutions", []))
                            if x.get("state") in CLOSED}
    return carried


def read_result(path: Path) -> object:
    """A lens's saved final message as JSON, a fenced block included; raises ValueError when it isn't JSON."""
    return json.loads(re.sub(r"^\s*```(?:json)?\s*|\s*```\s*$", "", path.read_bytes().decode()))


def journal_returns(key: str, folder: Path, doc: dict) -> list[str]:
    """Each lens result of the story's round in flight that matches its brief, journaled once as review.lens.returned.

    The round in flight is the latest review.started, until a review.round answers it or names its round, or the
    story is handed off or picked up again. A result that doesn't match its brief is never journaled, so the lens's
    next result for the same brief is; a restart's new start journals its lenses afresh. Both the supervisor's pass
    and review-reduce call it, so whichever sees a result first journals it."""
    start = latest_start(doc, key)
    if start is None or any(e.get("subject") == key and e["id"] > start["id"] and (
            e.get("kind") in ("candidate.handed", "lane.assigned")
            or (e.get("kind") == "review.round" and (start["id"] in e.get("answers", []) or e["data"]["round"] == start["data"]["round"])))
            for e in doc["journal"]):
        return []
    n = start["data"]["round"]
    meta_path = folder / f"round-{n}.meta.json"
    if not meta_path.exists() or (folder / f"round-{n}.json").exists():
        return []
    meta = json.loads(meta_path.read_text())
    if meta.get("candidate") != start["data"]["head"]:
        return []
    back = {e["data"]["lens"] for e in doc["journal"] if e.get("kind") == "review.lens.returned"
            and e.get("subject") == key and e["id"] > start["id"]}
    prior = [json.loads(p.read_text()) for p in round_files(folder) if int(p.stem.split("-")[1]) < n]
    journaled = []
    declared = cfg().lenses
    for lens in meta.get("lenses", []):
        if lens not in declared:
            continue
        short = declared[lens][0]
        path = result_path(folder, n, short)
        if lens in back or lens not in start["data"]["lenses"] or not path.exists():
            continue
        try:
            result = read_result(path)
        except (ValueError, UnicodeDecodeError):
            continue
        if check_result(result, key=key, lens=lens, short=short, n=n, meta=meta, carried=carried_findings(prior, lens)):
            continue
        findings = {p: sum(1 for f in result["findings"] if f.get("severity") == p) for p in SEVERITIES}
        facts = {"round": n, "lens": lens, "verdict": "approve" if result["outcome"] == "aligned" else "changes",
                 "findings": findings}
        state_tool("journal", "--writer", "lane", "--kind", "review.lens.returned", "--subject", key,
                   "--lane", start["lane"], "--data", json.dumps(facts))
        journaled.append(f"{key} {lens}")
    return journaled


def journal_lens_returns(c) -> list[str]:
    """The supervisor's pass: each running round's new lens results, read from its lane's checkout. On a shared record,
    only the rounds of the lanes this seat holds, whose checkouts are on its machine."""
    doc = load_state()
    roles = seat_roles(c)
    journaled = []
    for key in sorted({e["subject"] for e in doc["journal"] if e.get("kind") == "review.started" and e.get("subject")}):
        if roles is not None and not lane_held(roles, c.lane_of(key, doc["state"])):
            continue
        folder = c.lane_checkout(key) / c.work / "review" / key
        if folder.is_dir():
            journaled += journal_returns(key, folder, doc)
    return journaled


def round_history_text(outcome: dict) -> str:
    parts = []
    if outcome.get("attempts"):
        parts.append(f"{outcome['attempts']} refused attempt(s)")
    if outcome.get("restarts"):
        parts.append(f"{len(outcome['restarts'])} restart(s) discarding results")
    return ", ".join(parts)


def summarize(key: str, outcome: dict) -> None:
    n = outcome["round"]
    verdicts, counts = round_counts(outcome)
    history = round_history_text(outcome)
    print(f"{key} round {n}: {outcome['outcome']} ({', '.join(f'{k}: {v}' for k, v in verdicts.items())}); "
          f"findings P0 {counts['P0']}, P1 {counts['P1']}, P2 {counts['P2']}, P3 {counts['P3']}"
          + (f"; {history}" if history else ""))
    for b in outcome["blockers"]:
        print(f"  open {b['severity']} {b['id']} ({b['lens']}): {b['summary']}")
    for e in outcome["entries"]:
        for f in e["result"].get("findings", []):
            if f.get("state") == "deferred":
                print(f"  deferred {f['severity']} {f['id']} ({e['lens']}): {f['summary']} -> follow-up: {f['deferredIssue']}")
    print(f"  {outcome['action']}")
    blockers = "; ".join(f"{b['id']}: {b['summary']}" for b in outcome["blockers"])
    print(f"  Tracker post (your story): round {n}: {', '.join(f'{k} {v}' for k, v in verdicts.items())}; findings "
          f"P0 {counts['P0']}, P1 {counts['P1']}, P2 {counts['P2']}, P3 {counts['P3']}"
          + (f"; {blockers}" if blockers else "") + (f"; {history}" if history else ""))


def review_reduce(args) -> None:
    c = cfg()
    key = c.require(args.key)
    n = args.round
    folder = review_dir(key)
    done_path = folder / f"round-{n}.json"
    if done_path.exists():  # reduced already: never rewrite it, only finish the journaling if that failed
        outcome = json.loads(done_path.read_text())
        candidate = outcome["entries"][0]["binding"]["candidateRef"]
        lane = check_candidate_ownership(c, key, git("merge-base", c.base_ref, candidate), candidate)
        ensure_recorded(key, outcome, lane, folder)
        summarize(key, outcome)
        return
    meta_path = folder / f"round-{n}.meta.json"
    if not meta_path.exists():
        raise Stop(f"round {n} was never prepared: run review-prepare {key} --round {n} first")
    meta = json.loads(meta_path.read_text())
    candidate = meta["candidate"]
    lane = check_candidate_ownership(c, key, git("merge-base", c.base_ref, candidate), candidate)
    expected, _ = story_lens_set(c, folder)
    if meta["lenses"] != expected:
        raise Stop(f"round {n} was prepared for {meta['lenses']}, not the story's lenses {expected}")
    lenses = expected
    prior = [json.loads(p.read_text()) for p in round_files(folder)]
    if [r["round"] for r in prior] != list(range(1, n)):
        raise Stop(f"rounds before {n} are missing or out of order: {[r['round'] for r in prior]}")
    rel, graph = release_tuple(), graph_digest()
    entries, lens_rounds, digests, problems, bad = [], [], {}, [], set()
    for lens in lenses:
        short = c.lenses[lens][0]
        path = result_path(folder, n, short)
        if not path.exists():
            problems.append(f"{lens}: missing {path}; save its subagent's final JSON there")
            continue
        digests[lens] = hashlib.sha256(path.read_bytes()).hexdigest()
        try:
            result = read_result(path)
        except json.JSONDecodeError as error:
            problems.append(f"{lens}: {path.name} is not JSON ({error})")
            bad.add(lens)
            continue
        own = check_result(result, key=key, lens=lens, short=short, n=n, meta=meta, carried=carried_findings(prior, lens))
        if own:
            bad.add(lens)
            problems += [f"{lens}: {p}" for p in own]
        entries.append({
            "lens": lens,
            "binding": {"subjectRef": key, "candidateRef": meta["candidate"], "round": n, "release": rel,
                        "graphSha256": graph, "candidateTree": meta["tree"]},
            "state": "obtained", "independence": {"status": "unverified"}, "result": result})
        lens_rounds.append({"lens": lens, "outcome": result.get("outcome"), "findings": result.get("findings", []),
                            "evidence": result.get("evidence"), "failure": None,
                            "late_findings": result.get("lateFindings", [])})

    def refuse(lenses_at_fault: set[str], message: str) -> None:
        meta["attempts"] = meta.get("attempts", 0) + 1
        meta_path.write_text(json.dumps(meta, indent=2))
        for lens in lenses_at_fault:
            short = c.lenses[lens][0]
            path = result_path(folder, n, short)
            if path.exists():
                path.rename(folder / f"result-r{n}-{short}.attempt{meta['attempts']}.json")
        raise Stop(message + f"\n(kept as attempt {meta['attempts']}; re-run only "
                   f"{', '.join(sorted(lenses_at_fault))} with the same brief; the other results stand)")

    if problems and not bad:  # only missing files: nothing was refused, so it isn't an attempt
        raise Stop("\n".join(problems))
    if problems:
        refuse(bad, "results that don't match their briefs:\n  " + "\n  ".join(problems))
    open_findings: dict[str, dict] = {}
    for e in [x for r in prior for x in r["entries"]] + entries:
        res = e["result"]
        for f in res.get("findings", []):
            if f.get("state") != "deferred":
                open_findings[f["id"]] = {"id": f["id"], "lens": e["lens"], "severity": f["severity"], "summary": f["summary"]}
        for x in res.get("resolvedFindings", res.get("resolutions", [])):
            if x.get("state") in CLOSED:
                open_findings.pop(x["id"], None)
    blockers = [f for f in open_findings.values() if f["severity"] in ("P0", "P1")]
    aligned = all(e["result"]["outcome"] == "aligned" for e in entries) and not blockers
    if aligned:
        status, action = "aligned", "Continue with the caller-owned delivery workflow."
    elif n >= c.bound:
        status, action = "blocked", "Bound reached (review.loop-bound-reached): stop and report the open findings to the lead."
        blockers = blockers + [{"id": "review.loop-bound-reached", "lens": None, "severity": "P1",
                                "summary": f"round {n} of {c.bound} ended without alignment"}]
    else:
        status, action = "unresolved", "Fix the open P0/P1 findings, commit, then run the next round."
    candidate_ref = {"schemaVersion": "workflow-candidate-ref/1", "opaque": meta["candidate"]}
    subject_ref = {"schemaVersion": "workflow-subject-ref/1", "opaque": key}
    outcome = {
        "round": n, "outcome": status, "boundRounds": c.bound, "action": action, "blockers": blockers,
        "startedAt": meta["startedAt"], "finishedAt": now(), "resultDigests": digests,
        "attempts": meta.get("attempts", 0), "restarts": meta.get("restarts", []),
        "acquisitionEnvelope": {
            "schemaVersion": "review-acquisition-envelope/1", "release": rel, "graphSha256": graph,
            "subjectRef": subject_ref, "candidateRef": candidate_ref, "round": n, "requestedLenses": meta["lenses"],
            "entries": [{"release": rel, "graphSha256": graph, "subjectRef": subject_ref, "candidateRef": candidate_ref,
                         "round": n, "lens": e["lens"], "state": e["state"], "independence": e["independence"],
                         "result": e["result"]} for e in entries]},
        "entries": entries,
        "reviewWorkReturn": {
            "status": status,
            "rounds": [*[r["reviewWorkReturn"]["rounds"][-1] for r in prior], lens_rounds],
            "dissent": [], "failures": [], "blockers": blockers, "action": action,
            "late_findings": [x for lr in lens_rounds for x in lr["late_findings"]],
            "grace_verification": None, "round_history": [], "base_move_reopenings": [],
            "counted_rounds": min(n, c.bound)},
    }
    try:
        _validator().validate_review_outcomes([*prior, outcome], key, meta["candidate"])
    except Exception as error:
        refuse(set(lenses), f"the release's validator refuses the round: {error}")
    journal_returns(key, folder, load_state())  # any result the supervisor's pass hasn't journaled yet
    done_path.write_text(json.dumps(outcome, indent=1) + "\n")
    if status != "unresolved":  # another round reuses each lens's checkout; an aligned or bounded review is done with it
        for lens in lenses:
            remove_lens_checkout(lens_checkout(key, c.lenses[lens][0]))
    ensure_recorded(key, outcome, lane, folder)
    summarize(key, outcome)


# -- the plan's review -------------------------------------------------------------------------
# A plan review runs like a story's review, with no bound: one clean checkout and one brief per lens, carried findings,
# and a reduction per round. Its store, .orchestration/review/<delivery>/plan/ without checkouts/, keeps every round in
# full; build_plan reads it, and fits what the plan file holds of it to the plan contract's caps. A plan that isn't a
# delivery yet is reviewed with --plan: its store is .orchestration/plan-review/<reviewSlug>/, keyed by the slug in the
# plan's front matter so a renamed plan keeps its review, and lead-setup or lead-init moves it into the delivery's.

PLAN_REVIEW_ID = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
PLAN_REVIEW_REASON = 600
PLAN_REVIEW_CLOSED = ("closed", "fixed", "withdrawn", "dropped")
REVIEW_SLUG = re.compile(r"^[a-z0-9][a-z0-9-]{0,63}$")


def plan_review_dir(c) -> Path:
    return getattr(c, "plan_store", None) or c.main / c.work / "review" / c.delivery / "plan"


def plan_review_subject(c) -> str:
    """The store's own subject, kept when a delivery adopts it; a delivery's own review is `<delivery>.plan`."""
    own = load_json(plan_review_dir(c) / "store.json")
    return own["subject"] if own else f"{c.delivery}.plan"


def plan_review_name(c) -> str:
    """Who the review belongs to, as its messages name it."""
    return f"plan {c.plan}" if getattr(c, "plan_store", None) else c.delivery


def plan_review_command(c, action: str) -> str:
    return f"{flow_command()} plan-review {action}" + (f" --plan {shlex.quote(str(c.plan))}"
                                                       if getattr(c, "plan_store", None) else "")


def plan_review_lenses(c) -> list[str]:
    """The lenses the delivery file names for its plan review, or --lenses (round 1's when omitted) for a plan's own
    review: declared lenses, each with a charter."""
    if getattr(c, "plan_store", None):
        where = "--lenses"
        lenses = c.plan_lenses
        if lenses is None:
            rounds = plan_review_rounds(c)
            if rounds:
                return rounds[0]["lenses"]
            raise Stop(f"name the plan review's lenses with --lenses, such as --lenses {','.join(c.plan_lenses_declared)}")
    else:
        where = f"{c.delivery_where} planReview.lenses"
        lenses = (c.raw.get("planReview") or {}).get("lenses")
        if not isinstance(lenses, list) or not lenses:
            raise Stop(f"{c.delivery_where} names no plan review lenses: set planReview.lenses, such as "
                       f"{c.plan_lenses_declared}")
    if not lenses or len(lenses) > 12 or len(set(lenses)) != len(lenses):
        raise Stop(f"{where} must be 1 to 12 different lenses")
    unknown = [lens for lens in lenses if lens not in c.lenses or not PLAN_REVIEW_ID.fullmatch(lens)]
    if unknown:
        raise Stop(f"{where} names {', '.join(map(str, unknown))}, which this repository doesn't declare; its lenses "
                   f"are {', '.join(c.lenses)}")
    story_only = [lens for lens in lenses if lens not in c.plan_lenses_declared]
    if story_only:
        raise Stop(f"{where} names {', '.join(story_only)}, whose use excludes plan review; the declared plan lenses "
                   f"are {', '.join(c.plan_lenses_declared)}")
    return lenses


def front_matter(text: str) -> dict[str, str]:
    """A plan's leading `---` block, as its `key: value` lines."""
    block = re.match(r"---\n(.*?)\n---(?:\n|$)", text, re.S)
    if not block:
        return {}
    pairs = (line.partition(":") for line in block.group(1).splitlines())
    return {key.strip(): value.strip().strip("'\"") for key, colon, value in pairs if colon}


def review_slug(plan: Path, text: str) -> str | None:
    """The plan's `reviewSlug`, or None when its front matter has none."""
    slug = front_matter(text).get("reviewSlug")
    if slug is not None and not REVIEW_SLUG.fullmatch(slug):
        raise Stop(f"{plan}: reviewSlug {slug!r} must be 1 to 64 lowercase letters, digits and hyphens, starting with a "
                   "letter or digit")
    return slug


def needed_review_slug(plan: Path, text: str) -> str:
    """The plan's `reviewSlug`, refused with the front matter to add when it has none."""
    slug = review_slug(plan, text)
    if slug is None:
        suggested = re.sub(r"[^a-z0-9]+", "-", plan.stem.lower()).strip("-")[:64] or "plan"
        raise Stop(f"{plan} has no review slug, which keeps its review when the plan is renamed. Add this front matter "
                   f"at its top and commit it before round 1:\n---\nreviewSlug: {suggested}\n---")
    return slug


def with_preview(command):
    """A plan-review command that, with --plan, ends by rebuilding the plan's preview and printing its links. A
    preview that can't be built is said, and never changes the command's outcome."""
    def run_then_preview(args) -> None:
        command(args)
        if getattr(args, "plan", None):
            sys.stdout.flush()
            preview_quietly(args.plan)
    run_then_preview.__name__ = command.__name__
    return run_then_preview


def plan_review_config(args):
    """The config a plan-review command runs under: the delivery's, or with --plan the plan's own store, which needs no
    delivery file, binding or record."""
    if not getattr(args, "plan", None):
        return cfg()
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    plan = Path(args.plan)
    path = c.root / plan
    if not path.is_file():
        raise Stop(f"no plan at {path}")
    slug = needed_review_slug(plan, path.read_text())
    c.plan, c.plan_store = plan, c.main / c.work / "plan-review" / slug
    adopted = load_json(c.plan_store / "adopted.json")
    if adopted:
        raise Stop(f"the review of {plan} was adopted by delivery {adopted['delivery']} ({adopted['store']}); run "
                   f"{flow_command()} plan-review {args.action} without --plan")
    given = getattr(args, "lenses", None)
    c.plan_lenses = [lens.strip() for lens in given.split(",") if lens.strip()] if given is not None else None
    return c


def adoptable_plan_review(c, plan: Path) -> Path | None:
    """The plan's own review store, when it holds rounds no delivery has adopted; refused while a round is prepared,
    since its checkouts live in the store."""
    path = c.root / plan
    slug = review_slug(plan, path.read_text()) if path.is_file() else None
    source = c.main / c.work / "plan-review" / slug if slug else None
    if not source or not source.is_dir() or (source / "adopted.json").exists():
        return None
    n = len(round_files(source)) + 1
    if (source / f"round-{n}.meta.json").exists():
        raise Stop(f"the plan's review round {n} is prepared in {source}; reduce it ({flow_command()} plan-review reduce "
                   f"--plan {shlex.quote(str(plan))}) before a delivery adopts the review")
    return source if n > 1 else None


def preview_handed_quietly(c, slug: str, delivery: str) -> None:
    """After an adoption: the preview's handed finish, best effort and silent. It starts only where a preview folder
    exists for the slug, and nothing it does or fails at reaches the adoption's output or exit code."""
    try:
        folder = preview_folder(c, slug)
        facts = load_json(folder / PREVIEW_FILE) if folder.is_dir() else None
        if not facts or (folder / PREVIEW_HANDED).exists():
            return
        with open(os.devnull, "w") as quiet, contextlib.redirect_stdout(quiet):
            preview_handed_finish(c, folder, Path(facts["plan"]), {"delivery": delivery})
    except Exception:  # noqa: BLE001  (best effort: the adoption stands whatever happens here)
        return


def adopt_plan_review(c, source: Path, delivery: str) -> str:
    """Move the plan's own review store into the delivery's, leaving a pointer behind, so the plan chapter shows it."""
    target = c.main / c.work / "review" / delivery / "plan"
    if target.exists() and any(target.iterdir()):
        raise Stop(f"delivery {delivery} already has a plan review in {target}, so it can't adopt the one in {source}; "
                   "keep one of them and remove the other")
    checkouts = source / "checkouts"
    if checkouts.exists():
        if any(checkouts.iterdir()):
            raise Stop(f"{checkouts} still holds lens checkouts; reduce the round, or remove them, before adopting")
        checkouts.rmdir()
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        target.rmdir()
    rounds = len(round_files(source))
    shutil.move(str(source), str(target))
    source.mkdir()
    (source / "adopted.json").write_text(json.dumps({"delivery": delivery, "store": str(target), "at": now()},
                                                    indent=2) + "\n")
    preview_handed_quietly(c, source.name, delivery)
    return f"adopted the plan review ({rounds} round{'' if rounds == 1 else 's'}) from {source} into {target}"


def plan_review_rounds(c) -> list[dict]:
    """Every reduced round, in order."""
    return [json.loads(p.read_text()) for p in round_files(plan_review_dir(c))] if plan_review_dir(c).exists() else []


def plan_review_ended(c) -> dict | None:
    return load_json(plan_review_dir(c) / "ended.json")


def plan_review_open(rounds: list[dict]) -> dict[str, dict]:
    """The findings still open after the given rounds, by id."""
    found: dict[str, dict] = {}
    for outcome in rounds:
        for entry in outcome["entries"]:
            result = entry["result"]
            for f in result.get("findings", []):
                found[f["id"]] = {"id": f["id"], "lens": entry["lens"], "severity": f["severity"], "summary": f["summary"]}
            for x in result.get("resolvedFindings", []):
                if x.get("state") in PLAN_REVIEW_CLOSED:
                    found.pop(x["id"], None)
    return found


def plan_review_state(c, rounds: list[dict]) -> str:
    if plan_review_ended(c):
        return "ended"
    return "aligned" if rounds and rounds[-1]["outcome"] == "aligned" else "open"


def plan_review_of(c=None) -> dict | None:
    """The plan file's `planReview`: the store's rounds through the shared projection, fitted to the plan's caps; None
    with no reduced round."""
    c = c or cfg()
    rounds = plan_review_rounds(c)
    if not rounds:
        return None
    plan_validator(c)  # puts the release's delivery-views scripts first on the path
    import review_projection  # noqa: E402  (the installed release's own projection)
    detail = review_projection.round_detail(rounds, {r["round"]: r["candidate"] for r in rounds})
    ended = plan_review_ended(c)
    return review_projection.fit_plan_review(detail, rounds[0]["lenses"], plan_review_state(c, rounds),
                                             ended["reason"] if ended else None)


def plan_review_words(review: dict | None) -> str | None:
    """The approval line's fixed words, without its date or reason: "after 3 review rounds · every lens aligned"."""
    if not review:
        return None
    count = review["rounds"][-1]["round"]
    ending = {"aligned": "every lens aligned", "ended": "ended without alignment", "open": "still open"}[review["state"]]
    return f"after {count} review round{'' if count == 1 else 's'} · {ending}"


def plan_checkout_problem(path: Path, candidate: str, tree: str) -> str | None:
    """Why a lens's checkout fails its identity check, or None: at the candidate, with its tree, and clean."""
    if not path.exists():
        return "is missing"
    head = git("rev-parse", "HEAD", cwd=path, check=False)
    if head != candidate:
        return f"is at {head[:10] or 'no commit'}, not the candidate {candidate[:10]}"
    if git("rev-parse", "HEAD^{tree}", cwd=path, check=False) != tree:
        return "holds another tree"
    if git("status", "--porcelain", "--untracked-files=all", cwd=path, check=False):
        return "has changes"
    return None


def plan_brief(c, n: int, lens: str, candidate: str, tree: str, checkout: Path, prior: list[dict],
               prior_candidate: str | None) -> str:
    short, charter_file = c.lenses[lens]
    rel = release_tuple()
    subject = plan_review_subject(c)
    if n == 1:
        kind = (f"`assessment round`: this lens's first result-carrying round; review the whole plan, `{c.plan}` in your "
                "checkout, and carry no prior entries or candidate resolution pairs.")
        carry = "None: this is an assessment round, which carries no prior entries."
        resolutions = "None: an assessment round spans no delta and needs no resolution pair."
        later = "- `lateFindings`: none on an assessment round; omit it."
    else:
        kind = ("`verification round`: re-check every carried finding and its approval condition against the plan's "
                f"revision, the delta you derive yourself (`git diff {prior_candidate}..{candidate}`), then review that "
                "delta. A change adopted differently from its approval condition, or declined, is re-checked like any "
                "carried finding.")
        carry = "\n".join(
            f"- round {e['binding']['round']}: `{json.dumps({'binding': e['binding'], 'state': e['state'], 'result': e.get('result')}, separators=(',', ':'))}`"
            for e in prior) or "None: this lens has carried nothing."
        resolutions = (f"- `{prior_candidate}` resolves to git commit `{prior_candidate}`\n"
                       f"- `{candidate}` resolves to git commit `{candidate}`")
        later = ("- `lateFindings`: ids of this result's own findings you raised late (against lines unchanged since "
                 "your previous round); omit when none.\n"
                 "- `resolvedFindings`: required. One entry for every finding this lens raised in an earlier round and "
                 'has not closed, `{"id", "state": "closed|fixed|withdrawn|open", "resolution": "..."}`. Every carried '
                 "finding must appear; a plan review defers none.")
        ledger = finding_ledger(prior, PLAN_REVIEW_CLOSED, legacy=False)
        later += ("\n- Still open for this lens, so each listed in `resolvedFindings` exactly once: "
                  f"{id_list(ledger['open'])}.\n"
                  f"- Closed in an earlier round, so never listed in `resolvedFindings`: {id_list(ledger['closed'])}. "
                  "The reduce refuses a result that lists one, or that leaves out one still open.")
    whose = "" if getattr(c, "plan_store", None) else f", the plan of delivery {c.delivery}"
    context = (f"The plan under review is `{c.plan}` in your checkout{whose}. Judge whether it is ready to approve: its outcome, scope, contract decisions, units, sensors and finish line. The plan "
               "is the whole subject; there is no ticket or code diff to review beyond it.")
    values = {
        "lens": lens, "short": short, "key": subject, "round": str(n), "candidate": candidate, "tree": tree,
        "releaseId": rel["releaseId"], "profile": str(rel["profile"]), "archiveSha256": rel["archiveSha256"],
        "metadataSha256": rel["metadataSha256"], "graph": graph_digest(),
        "bound_text": f"`unbounded`: unbounded round {n}, with no bound supplied or invented.", "kind": kind,
        "carry": carry, "resolutions": resolutions, "charter": Path(charter_file).read_text().strip(), "later": later,
        "checkout": str(checkout), "context": context, "in_app": "None: a plan review has no in-app evidence.",
        "severities": PLAN_SEVERITIES, "flow": flow_command(), "machine": machine_command(),
        "delivery_option": delivery_option(c),
        "checks": ("- scoped sensor commands: none; a plan review runs no checks, since the plan is the whole subject.\n"
                   "- test files in scope for this round: none."),
        "result": str(result_path(plan_review_dir(c), n, short)),
    }
    template = (TOOL / "templates/round-brief.md").read_text()
    return re.sub(r"\{\{(\w+)\}\}", lambda m: values[m.group(1)], template)


def plan_review_prepare(args) -> None:
    c = plan_review_config(args)
    release_tuple()  # refuse an unidentified generation before anything is checked out or written
    folder = plan_review_dir(c)
    lenses = plan_review_lenses(c)
    if plan_review_ended(c):
        raise Stop(f"the plan review was ended ({folder / 'ended.json'}); a new review needs a new store")
    rounds = plan_review_rounds(c)
    if rounds and rounds[0]["lenses"] != lenses:
        where = "--lenses" if getattr(c, "plan_store", None) else c.delivery_where
        raise Stop(f"the plan review's lenses were fixed at round 1 as {rounds[0]['lenses']}; {where} now "
                   f"names {lenses}. An amendment is judged by the lenses that reviewed the plan")
    n = len(rounds) + 1
    meta_path = folder / f"round-{n}.meta.json"
    previous = load_json(meta_path)
    if previous and not args.restart:
        raise Stop(f"plan review round {n} is already prepared (at {previous['candidate'][:10]}). Reduce it, or pass "
                   "--restart to discard it")
    root = repo()
    candidate = clean_head(root)
    if run(["git", "cat-file", "-e", f"{candidate}:{c.plan.as_posix()}"], cwd=root, check=False).returncode != 0:
        raise Stop(f"the plan {c.plan} isn't committed at {candidate[:10]}; commit it first")
    tree = git("rev-parse", "HEAD^{tree}", cwd=root)
    prior_candidate = rounds[-1]["candidate"] if rounds else None
    if prior_candidate == candidate:
        raise Stop(f"HEAD {candidate[:10]} is the candidate of round {n - 1}; commit the plan's revision first")
    folder.mkdir(parents=True, exist_ok=True)
    if getattr(c, "plan_store", None) and not (folder / "store.json").exists():
        slug = folder.name
        (folder / "store.json").write_text(json.dumps({"slug": slug, "plan": c.plan.as_posix(),
                                                       "subject": f"{slug}.plan"}, indent=2) + "\n")
    if previous:
        for lens in lenses:
            path = result_path(folder, n, c.lenses[lens][0])
            if path.exists():
                path.rename(path.with_suffix(f".discarded-{now().replace(':', '')}.json"))
    briefs, checks = [], {}
    for lens in lenses:
        short = c.lenses[lens][0]
        checkout = folder / "checkouts" / lens
        remove_checkout(checkout)
        checkout.parent.mkdir(parents=True, exist_ok=True)
        git("worktree", "add", "--detach", "-q", str(checkout), candidate, cwd=root)
        for argv in prepare_commands():
            run(argv, cwd=checkout)
        problem = plan_checkout_problem(checkout, candidate, tree)
        if problem:
            raise Stop(f"{lens}: its checkout {checkout} {problem} before its brief was written")
        checks[lens] = "passed"
        prior = [e for r in rounds for e in r["entries"] if e["lens"] == lens]
        path = folder / f"brief-r{n}-{short}.md"
        path.write_text(plan_brief(c, n, lens, candidate, tree, checkout, prior, prior_candidate))
        briefs.append((lens, path, result_path(folder, n, short)))
    meta_path.write_text(json.dumps({"round": n, "candidate": candidate, "tree": tree, "startedAt": now(),
                                     "lenses": lenses, "startChecks": checks}, indent=2) + "\n")
    print(f"{plan_review_name(c)} plan review round {n}: candidate {candidate[:10]}, tree {tree[:10]}; no round bound")
    print()
    print("Start one reviewer per lens, in parallel, each with exactly this prompt" if n == 1 and not previous else
          "Resume the same reviewer for each lens, in parallel, with exactly this message; only if one can't be resumed, "
          "start a fresh one with the same prompt")
    print("Save each final JSON message, exactly as returned, to its result path. Never write or edit a result.\n")
    for lens, path, result in briefs:
        print(f"- {lens}\n  prompt: Read {path} and follow it exactly. Your final message is only the JSON it asks for.\n"
              f"  save to: {result}")
    print(f"\nThen: {plan_review_command(c, 'reduce')}")


def plan_check_result(result: object, *, subject: str, lens: str, short: str, n: int, meta: dict, carried: set[str],
                      known: dict[str, str]) -> list[str]:
    """What's wrong with one plan-review lens result, as messages; empty when it matches its brief."""
    if not isinstance(result, dict):
        return ["is not a JSON object"]
    problems = []
    expect = {"schemaVersion": "review-lens-result/1", "lensId": lens, "subjectRef": subject,
              "candidateRef": meta["candidate"], "round": n}
    for field, value in expect.items():
        if result.get(field) != value:
            problems.append(f"{field} is {result.get(field)!r}, expected {value!r}")
    if result.get("outcome") not in ("aligned", "changes-requested"):
        problems.append(f"outcome is {result.get('outcome')!r}")
    evidence = result.get("evidence")
    if not isinstance(evidence, list) or not evidence or not all(isinstance(e, str) for e in evidence):
        problems.append("evidence must be a non-empty list of strings")
    elif not any(meta["tree"] in e for e in evidence):
        problems.append(f"evidence doesn't name the reviewed tree {meta['tree']}")
    findings = result.get("findings")
    if not isinstance(findings, list):
        return problems + ["findings must be a list"]
    open_blocking = False
    for f in findings:
        if not isinstance(f, dict) or not isinstance(f.get("id"), str) or not isinstance(f.get("summary"), str) or not f["summary"].strip():
            problems.append(f"finding {f!r} lacks id or summary")
            continue
        if not PLAN_REVIEW_ID.fullmatch(f["id"]) or not f["id"].startswith(f"{short}-r{n}-"):
            problems.append(f"finding id {f['id']} must start with {short}-r{n}- and hold only letters, digits, dots, "
                            "dashes or underscores, at most 64")
        elif f["id"] in known:
            problems.append(f"finding id {f['id']} was already raised")
        if f.get("severity") not in SEVERITIES:
            problems.append(f"finding {f['id']} has severity {f.get('severity')!r}")
        elif f["severity"] in ("P2", "P3"):
            problems.append(f"finding {f['id']} is {f['severity']}: a plan review files P2 and P3 notes in evidence")
        else:
            open_blocking = True
        if "state" in f or "deferredIssue" in f:
            problems.append(f"finding {f['id']} carries a state or deferredIssue: a plan review defers nothing")
    closures = result.get("resolvedFindings", [])
    if not isinstance(closures, list) or not all(isinstance(x, dict) for x in closures):
        problems.append("resolvedFindings must be a list of objects")
        closures = []
    for x in closures:
        if x.get("state") not in (*PLAN_REVIEW_CLOSED, "open"):
            problems.append(f"resolvedFindings entry {x.get('id')!r} has state {x.get('state')!r}: closed, fixed, "
                            "withdrawn or open")
        if x.get("id") not in carried:
            problems.append(f"resolvedFindings entry {x.get('id')!r} isn't an open finding this lens raised earlier")
        if not isinstance(x.get("resolution"), str) or not x["resolution"].strip():
            problems.append(f"resolvedFindings entry {x.get('id')!r} needs a resolution")
        if x.get("state") == "open":
            open_blocking = True
    missing = carried - {x.get("id") for x in closures}
    if missing:
        problems.append(f"resolvedFindings leaves out carried finding(s) {sorted(missing)}")
    if result.get("outcome") == "aligned" and open_blocking:
        problems.append("outcome is aligned but it raises an open P0/P1 finding")
    return problems


def plan_review_reduce(args) -> None:
    c = plan_review_config(args)
    folder = plan_review_dir(c)
    rounds = plan_review_rounds(c)
    n = len(rounds) + 1
    meta = load_json(folder / f"round-{n}.meta.json")
    if meta is None:
        if rounds:
            plan_review_summary(c, rounds)
            return
        raise Stop(f"no plan review round is prepared: run {plan_review_command(c, 'prepare')} first")
    subject = plan_review_subject(c)
    opened = plan_review_open(rounds)
    known = {f["id"]: e["lens"] for r in rounds for e in r["entries"] for f in e["result"].get("findings", [])}
    rel, graph = release_tuple(), graph_digest()
    entries, digests, problems = [], {}, []
    for lens in meta["lenses"]:
        short = c.lenses[lens][0]
        path = result_path(folder, n, short)
        if not path.exists():
            problems.append(f"{lens}: missing {path}; save its reviewer's final JSON there")
            continue
        raw = path.read_bytes()
        digests[lens] = hashlib.sha256(raw).hexdigest()
        try:
            result = json.loads(re.sub(r"^\s*```(?:json)?\s*|\s*```\s*$", "", raw.decode()))
        except (json.JSONDecodeError, UnicodeDecodeError) as error:
            problems.append(f"{lens}: {path.name} is not JSON ({error})")
            continue
        carried = {f["id"] for f in opened.values() if f["lens"] == lens}
        problems += [f"{lens}: {p}" for p in plan_check_result(result, subject=subject, lens=lens, short=short, n=n,
                                                                meta=meta, carried=carried, known=known)]
        entries.append({"lens": lens, "binding": {"subjectRef": subject, "candidateRef": meta["candidate"], "round": n,
                                                  "release": rel, "graphSha256": graph, "candidateTree": meta["tree"]},
                        "state": "obtained", "independence": {"status": "unverified"}, "result": result})
    if problems:
        raise Stop("results that don't match their briefs:\n  " + "\n  ".join(problems)
                   + "\n(re-run only those lenses with the same brief, saving over their results)")
    failed = []
    for lens in meta["lenses"]:
        checkout = folder / "checkouts" / lens
        problem = plan_checkout_problem(checkout, meta["candidate"], meta["tree"])
        if problem:
            failed.append(f"{lens}: its checkout {checkout} failed the end identity check: it {problem}")
    if failed:
        raise Stop("the round fails; its checkouts are kept for inspection:\n  " + "\n  ".join(failed)
                   + f"\nPrepare it again with {plan_review_command(c, 'prepare')} --restart")
    after = plan_review_open([*rounds, {"entries": entries}])
    aligned = all(e["result"]["outcome"] == "aligned" for e in entries) and not after
    outcome = {"round": n, "outcome": "aligned" if aligned else "unresolved", "candidate": meta["candidate"],
               "tree": meta["tree"], "lenses": meta["lenses"], "startedAt": meta["startedAt"], "finishedAt": now(),
               "startChecks": meta.get("startChecks", {}), "resultDigests": digests,
               "open": list(after.values()), "entries": entries}
    (folder / f"round-{n}.json").write_text(json.dumps(outcome, indent=1) + "\n")
    for lens in meta["lenses"]:
        remove_checkout(folder / "checkouts" / lens)
    plan_review_summary(c, [*rounds, outcome])
    if getattr(c, "plan_store", None):
        if aligned:
            print(f"  {write_plan_review_record(c, [*rounds, outcome])}")
    elif (c.state / "state.json").exists():
        print(f"  {rebuild_plan_quietly(c)}")


def plan_review_summary(c, rounds: list[dict]) -> None:
    outcome = rounds[-1]
    n = outcome["round"]
    if outcome["outcome"] == "aligned":
        print(f"{plan_review_name(c)} plan review round {n}: every lens aligned; the plan is ready for the operator's "
              "approval")
        return
    count = len(outcome["open"])
    print(f"{plan_review_name(c)} plan review round {n}: changes requested; {count} open finding"
          f"{'' if count == 1 else 's'}")
    for f in outcome["open"]:
        print(f"  open {f['severity']} {f['id']} ({f['lens']}): {f['summary']}")
    if n > 1:
        before = len(rounds[-2]["open"])
        raised = any(e["result"].get("findings") for e in outcome["entries"])
        if raised and count >= before:
            print(f"The plan review isn't converging: round {n} raised a new finding and leaves {count} open, no fewer "
                  f"than round {n - 1}'s {before}. The operator may end it: {plan_review_command(c, 'end')} --reason "
                  "TEXT. Nothing ends it on its own.")
    print(f"  Revise the plan for the open findings, commit, then: {plan_review_command(c, 'prepare')}")


def plan_review_end(args) -> None:
    c = plan_review_config(args)
    reason = args.reason.strip()
    if not reason or len(reason) > PLAN_REVIEW_REASON or re.search(r"[\x00-\x1f\x7f-\x9f  ]", reason):
        raise Stop(f"--reason must be one line of 1 to {PLAN_REVIEW_REASON} characters")
    folder = plan_review_dir(c)
    rounds = plan_review_rounds(c)
    if not rounds:
        raise Stop("the plan review has no reduced round to end")
    if plan_review_ended(c):
        raise Stop(f"the plan review was already ended ({folder / 'ended.json'})")
    if rounds[-1]["outcome"] == "aligned":
        raise Stop(f"round {rounds[-1]['round']} ended with every lens aligned; there is no open review to end")
    if (folder / f"round-{len(rounds) + 1}.meta.json").exists():
        raise Stop(f"round {len(rounds) + 1} is prepared; reduce it first, then end the review")
    (folder / "ended.json").write_text(json.dumps({"at": now(), "round": rounds[-1]["round"], "reason": reason},
                                                  indent=2) + "\n")
    print(f"{plan_review_name(c)} plan review ended after round {rounds[-1]['round']}: {reason}")
    if getattr(c, "plan_store", None):
        print(f"  {write_plan_review_record(c, rounds)}")
    elif (c.state / "state.json").exists():
        print(f"  {rebuild_plan_quietly(c)}")


# A standalone plan's review record, `<plan stem>.review.json` beside the plan: the shape the hand-written records in a
# repository's plans already have, with what the store adds. One validator checks both.

PLAN_REVIEW_RECORD = "plan-review-evidence/1"
PLAN_REVIEW_RECORD_WRITER = "run-delivery plan-review"
PLAN_REVIEW_OUTCOMES = {"aligned": "unanimous-alignment", "ended": "ended-without-alignment"}


def plan_review_record_path(c) -> Path:
    return c.root / c.plan.with_name(c.plan.stem + ".review.json")


def plan_review_record(c, rounds: list[dict]) -> dict:
    """The record of a review that aligned or was ended, from its store alone."""
    last = rounds[-1]
    ended = plan_review_ended(c)
    plan = c.plan.as_posix()
    reviewed = subprocess.run(["git", "show", f"{last['candidate']}:{plan}"], cwd=c.root, capture_output=True,
                              check=True).stdout  # the blob's own bytes, with no newline translation
    folder = plan_review_dir(c)
    reviews = []
    for lens in last["lenses"]:
        n, entry = next((r["round"], e) for r in reversed(rounds) for e in r["entries"] if e["lens"] == lens)
        raw = result_path(folder, n, c.lenses[lens][0]).read_bytes()
        reviews.append({"lens": lens, "round": n, "findings": entry["result"].get("findings", []),
                        "result": entry["result"], "resultSha256": hashlib.sha256(raw).hexdigest()})
    count = len(rounds)
    risks = [f"{count} review round{'' if count == 1 else 's'}; findings open after each round: "
             f"{', '.join(str(len(r['open'])) for r in rounds)}."]
    if ended:
        risks.append(f"Ended without alignment after round {ended['round']}: {ended['reason']}")
        risks += [f"Open {f['severity']} {f['id']} ({f['lens']}): {f['summary']}" for f in last["open"]]
    current = c.root / c.plan
    if not current.is_file() or current.read_bytes() != reviewed:
        risks.append(f"The plan's current text differs from round {last['round']}'s candidate {last['candidate'][:12]}; "
                     "this record covers the reviewed text.")
    record = {"schemaVersion": PLAN_REVIEW_RECORD, "writtenBy": PLAN_REVIEW_RECORD_WRITER, "plan": plan,
              "planSha256": hashlib.sha256(reviewed).hexdigest(), "planCommit": last["candidate"],
              "outcome": PLAN_REVIEW_OUTCOMES["ended" if ended else "aligned"], "requiredLenses": last["lenses"],
              "rounds": [{"round": r["round"], "candidate": r["candidate"], "outcome": r["outcome"],
                          "startedAt": r["startedAt"], "finishedAt": r["finishedAt"],
                          "open": [f["id"] for f in r["open"]]} for r in rounds],
              "reviews": reviews, "residualRisks": risks}
    if ended:
        record["ended"] = {"round": ended["round"], "reason": ended["reason"], "at": ended["at"]}
    return record


def write_plan_review_record(c, rounds: list[dict]) -> str:
    """Write the review's record beside the plan, unless a hand-written one is there; says which."""
    path = plan_review_record_path(c)
    shown = path.relative_to(c.root).as_posix()
    existing = load_json(path) if path.is_file() else None
    if path.exists() and not (isinstance(existing, dict) and existing.get("writtenBy") == PLAN_REVIEW_RECORD_WRITER):
        return f"kept the hand-written review record {shown}; the store's record wasn't written"
    record = plan_review_record(c, rounds)
    problems = plan_review_record_problems(record)
    if problems:
        raise Stop(f"the review record for {shown} fails its own check:\n  " + "\n  ".join(problems))
    path.write_text(json.dumps(record, indent=2) + "\n")
    return f"wrote the review record {shown}; commit it with the plan"


def plan_review_record_problems(record: object) -> list[str]:
    """What's wrong with a `plan-review-evidence/1` record, hand-written or generated, as messages; empty when valid."""
    if not isinstance(record, dict):
        return ["the record must be a JSON object"]
    problems = []
    if record.get("schemaVersion") != PLAN_REVIEW_RECORD:
        problems.append(f"schemaVersion must be {PLAN_REVIEW_RECORD}")
    plan = record.get("plan")
    if (not isinstance(plan, str) or not plan.strip() or plan.startswith("/") or "\\" in plan
            or ".." in plan.split("/")):
        problems.append("plan must be the plan's path inside the repository, with / separators")
    if not isinstance(record.get("planSha256"), str) or not re.fullmatch(r"[0-9a-f]{64}", record["planSha256"]):
        problems.append("planSha256 must be 64 lowercase hex digits")
    outcome = record.get("outcome")
    if outcome not in PLAN_REVIEW_OUTCOMES.values():
        problems.append(f"outcome must be one of {', '.join(PLAN_REVIEW_OUTCOMES.values())}")
    lenses = record.get("requiredLenses")
    if (not isinstance(lenses, list) or not 1 <= len(lenses) <= 12 or len(set(map(str, lenses))) != len(lenses)
            or not all(isinstance(lens, str) and lens.strip() for lens in lenses)):
        problems.append("requiredLenses must be 1 to 12 different lens names")
        lenses = None
    reviews = record.get("reviews")
    if not isinstance(reviews, list) or not all(isinstance(r, dict) for r in reviews):
        problems.append("reviews must be a list of objects, one per required lens")
        reviews = []
    elif lenses is not None and sorted(map(str, (r.get("lens") for r in reviews))) != sorted(lenses):
        problems.append("reviews must hold exactly one review for each required lens")
    risks = record.get("residualRisks")
    if not isinstance(risks, list) or not all(isinstance(r, str) and r.strip() for r in risks):
        problems.append("residualRisks must be a list of non-empty strings")
    for review in reviews:
        lens = review.get("lens")
        findings = review.get("findings")
        if not isinstance(findings, list) or not all(isinstance(f, dict) for f in findings):
            problems.append(f"{lens}: findings must be a list of objects")
            continue
        if findings and outcome == PLAN_REVIEW_OUTCOMES["aligned"]:
            problems.append(f"{lens}: a review with findings contradicts outcome unanimous-alignment")
    ended = record.get("ended")
    if outcome == PLAN_REVIEW_OUTCOMES["ended"]:
        if not isinstance(ended, dict) or not isinstance(ended.get("reason"), str) or not ended["reason"].strip():
            problems.append("ended must give the operator's reason when the outcome is ended-without-alignment")
    elif ended is not None:
        problems.append("ended belongs only to outcome ended-without-alignment")
    rounds = record.get("rounds")
    if rounds is None:  # a hand-written record names no rounds; what follows is the store's part
        return problems
    if (not isinstance(rounds, list) or not rounds or not all(isinstance(r, dict) for r in rounds)
            or [r.get("round") for r in rounds] != list(range(1, len(rounds) + 1))):
        return problems + ["rounds must be the review's rounds, numbered from 1 with none skipped"]
    outcomes = [r.get("outcome") for r in rounds]
    # An amendment reviews on after an aligned round, so an earlier round may be aligned; the last decides the outcome.
    if any(o not in ("unresolved", "aligned") for o in outcomes[:-1]) or outcomes[-1] != (
            "aligned" if outcome == PLAN_REVIEW_OUTCOMES["aligned"] else "unresolved"):
        problems.append("rounds: each round is aligned or unresolved, and the last must agree with outcome")
    if not all(isinstance(r.get("candidate"), str) and re.fullmatch(r"[0-9a-f]{40,64}", r["candidate"]) for r in rounds):
        problems.append("rounds: each round's candidate must be a full commit id")
    if record.get("planCommit") != rounds[-1].get("candidate"):
        problems.append("planCommit must be the last round's candidate")
    if isinstance(ended, dict) and ended.get("round") != len(rounds):
        problems.append("ended.round must be the last round")
    for review in reviews:
        lens, result, n = review.get("lens"), review.get("result"), review.get("round")
        if not isinstance(n, int) or isinstance(n, bool) or not 1 <= n <= len(rounds):
            problems.append(f"{lens}: round must be one of the review's rounds")
        if not isinstance(result, dict) or result.get("lensId") != lens or result.get("round") != n:
            problems.append(f"{lens}: result must be this lens's own result from its round (lensId and round)")
        elif result.get("findings", []) != review.get("findings"):
            problems.append(f"{lens}: findings must be its result's findings")
        if not isinstance(review.get("resultSha256"), str) or not re.fullmatch(r"[0-9a-f]{64}", review["resultSha256"]):
            problems.append(f"{lens}: resultSha256 must be 64 lowercase hex digits")
    return problems


def plan_review_check(args) -> None:
    """Validate review records; prints one line per record and refuses when any fails."""
    failed = False
    for given in args.records:
        path = Path(given)
        try:
            record = json.loads(path.read_text())
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            print(f"{path}: can't be read as JSON ({error})")
            failed = True
            continue
        problems = plan_review_record_problems(record)
        if problems:
            failed = True
            print(f"{path}: not a valid {PLAN_REVIEW_RECORD} record:\n  " + "\n  ".join(problems))
        else:
            print(f"{path}: a valid {PLAN_REVIEW_RECORD} record")
    if failed:
        raise Stop("some review records aren't valid")


# -- lane: gates, build and in-app checks -------------------------------------------------

def write_stamp(artifact: Path, head: str, tree: str) -> None:
    artifact.mkdir(parents=True, exist_ok=True)
    (artifact / STAMP).write_text(json.dumps({"head": head, "tree": tree, "builtAt": now()}))


def binding_checks(binding: dict | None) -> dict[str, dict]:
    """The checks a binding defines, by id: its catalogue's, then alwaysRun's and fallback's, as run-checks reads them."""
    b = binding or {}
    found = [*((b.get("selection") or {}).get("catalogue") or []), *(b.get("alwaysRun") or []), *(b.get("fallback") or [])]
    return {check["id"]: check for check in found if isinstance(check, dict) and isinstance(check.get("id"), str)}


def named_gate(name: str, binding: dict | None) -> dict:
    """A `gates` entry that names a check by id: it runs through run-checks from that definition. Its argv is the
    definition's, for what shows or lends the gate; an id the binding doesn't define has none, which doctor reports."""
    check = binding_checks(binding).get(name)
    if check is None:
        return {"id": name, "check": name, "argv": [], "cwd": ".", "unknown": True}
    return {"id": name, "check": name, "argv": [("{base}" if a == "{baseHead}" else a) for a in check.get("argv") or []],
            "cwd": check.get("cwd", "."),
            "timeoutSeconds": check.get("timeoutSeconds", (binding or {}).get("checkTimeoutSeconds", 1800))}


def check_runs(c, head: str, ids: list[str], now_why: str | None = None) -> tuple[list[dict], float]:
    """Run checks at `head` through the release's `merge_queue.py run-checks`, the way the queue runs them, and return
    the records it prints with the run's whole time. Its refusal stops here with its own reason. Each check claims
    machine slots there and waits while the machine is full, unless `now_why` steps off that default: what run-checks
    says on stderr, its waiting lines among it, reaches this command's stderr as it arrives, while its stdout is read
    as one JSON document. It inherits this process's environment, so a claim this command runs under is its too."""
    argv = [sys.executable, "-B", str(c.release / "skills/orchestrate-work/scripts/merge_queue.py"), "--repo", str(repo()),
            "--remote", c.remote, "--base", c.base_branch, "run-checks", "--head", head, "--checks", ",".join(ids),
            *(["--now", "--why", now_why] if now_why is not None else [])]
    started = time.time()
    proc = subprocess.Popen(argv, cwd=repo(), text=True, start_new_session=True, stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE)
    said_on_stderr: list[str] = []

    def copy_stderr() -> None:
        for line in proc.stderr:
            said_on_stderr.append(line)
            sys.stderr.write(line)
            sys.stderr.flush()
    copier = threading.Thread(target=copy_stderr, daemon=True)
    copier.start()
    try:
        out = proc.stdout.read()  # each check and prepare step is bounded by the queue's own timeouts
        proc.wait()
        copier.join()
    finally:
        stop_group(proc)
    err = "".join(said_on_stderr)
    seconds = time.time() - started
    if proc.returncode == MACHINE_GAVE_UP:
        raise Stop(f"run-checks gave up waiting for the machine: {err.strip()[-800:]}")
    try:
        said = json.loads(out)
    except json.JSONDecodeError:
        raise Stop(f"run-checks printed no records ({proc.returncode}): {(out + err).strip()[-800:]}") from None
    if isinstance(said, dict):
        raise Stop(f"run-checks refused: {said.get('reason')}: {said.get('detail')}")
    return said, seconds


# -- the machine: claims for heavy runs ------------------------------------------------------

# The exit of a capped wait for the machine that ended unadmitted (EX_TEMPFAIL), as machine.py says it.
MACHINE_GAVE_UP = 75


def machine_module():
    """The installed release's machine ledger module, beside its merge queue."""
    _validator()  # puts the release's orchestration scripts on the path
    import machine  # noqa: E402
    return machine


def machine_ledger():
    """This machine's ledger, which every repository on it shares."""
    return machine_module().Ledger()


def heavy_claim(kind: str, subject: str, *, label: str, slots: int = 1, exclusive: bool = False,
                now_why: str | None = None, wait_seconds: float | None = None, repository: str | None = None,
                delivery: str | None = None, story: str | None = None,
                enqueued: Callable[[object], None] | None = None):
    """Claim machine slots for a heavy run and wait, uncapped unless `wait_seconds` caps it, until admitted. `enqueued`
    is told the claim once it is in the ledger, before any wait. A capped wait that ends unadmitted raises the
    module's GaveUp; a ledger that can't be used gives an unclaimed stand-in, and the run goes on."""
    machine = machine_module()
    ledger = machine_ledger()
    claim = ledger.request(kind, subject, label=label, slots=slots, exclusive=exclusive, repository=repository,
                           delivery=delivery, story=story, now_why=now_why)
    try:
        if enqueued is not None:
            enqueued(claim)
        claim.wait(wait_seconds)
    except machine.LedgerUnavailable as error:
        claim.release()
        return ledger._unclaimed(error)
    except BaseException:
        claim.release()
        raise
    return claim


def stepped_off(claim) -> bool:
    """Whether a claim was admitted by its own --now: one run under an ancestor's claim, or unclaimed, stepped off
    nothing."""
    return claim.record is not None and claim.record.get("admittedBy") == "now"


@contextlib.contextmanager
def claimed_environment(claim):
    """This process's environment names `claim` while the run it is for goes on, so every process the run starts runs
    under it and never waits behind it."""
    names = claim.child_environment()
    before = {name: os.environ.get(name) for name in names}
    os.environ.update(names)
    try:
        yield
    finally:
        for name, value in before.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value


def children_cpu_seconds() -> float:
    """The CPU time of every child this process has waited for, and of their waited-for descendants."""
    import resource
    usage = resource.getrusage(resource.RUSAGE_CHILDREN)
    return usage.ru_utime + usage.ru_stime


def measured_since(machine, code: int, began: float, cpu_before: float | None, passed: bool):
    """A finished run's cost, for the machine's cost record: its wall seconds, and the CPU its waited-for children
    took, which is None where the platform can't say."""
    cpu = None
    if cpu_before is not None:
        with contextlib.suppress(ImportError, OSError, ValueError):
            cpu = round(children_cpu_seconds() - cpu_before, 3)
    return machine.Measured(code, round(time.monotonic() - began, 3), cpu, "passed" if passed else "failed")


def cpu_mark() -> float | None:
    try:
        return children_cpu_seconds()
    except (ImportError, OSError, ValueError):
        return None


def machine_repository() -> str | None:
    with contextlib.suppress(Stop, OSError):
        return machine_module().repository_identity(repo())
    return None


def now_and_why(args, skip: bool = False) -> str | None:
    """The reason --now steps off the machine's wait with, or None without --now. --now needs --why; --why goes with
    --now, or with --skip-guards for a command that takes it, and one --why gives the reason for both."""
    why = (getattr(args, "why", None) or "").strip()
    if args.now and not why:
        raise Stop("--now needs --why, the reason the run steps off waiting for the machine, which is recorded")
    if getattr(args, "why", None) and not args.now and not skip:
        raise Stop("--why goes with --skip-guards or --now" if hasattr(args, "skip_guards") else "--why goes with --now")
    return why if args.now else None


def journal_override(c, subject: str | None, text: str, why: str) -> None:
    """Journal a run that stepped off the machine's wait as decision.recorded, inside a delivery with a record. One
    attempt: a refusal is said, and the run goes on."""
    if not (c.state / "state.json").is_file():
        return
    done = state_tool("journal", "--kind", "decision.recorded", *(["--subject", subject] if subject else []),
                      "--text", text, "--why", why, check=False)
    if done.returncode != 0:
        print(f"the override wasn't journaled: {(done.stderr or done.stdout).strip()[-300:]}", file=sys.stderr)


def claim_story(c) -> str | None:
    """The story a claim from this checkout is for: the story whose branch it is on, or None (the lead's checkout, a
    lens checkout, or any other)."""
    with contextlib.suppress(Stop, OSError):
        branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=c.root, check=False)
        return next((key for key in c.stories if c.branch(key) == branch), None)
    return None


def claim(args) -> None:
    """Claim machine slots for argv, waiting while the machine is full unless --now steps off with --why, then run it
    under the claim, measure it into the machine's cost record and release the claim, whatever happens to the run.
    The claim names this delivery and the story whose checkout it runs in."""
    c = cfg()
    argv = args.argv[1:] if args.argv[:1] == ["--"] else list(args.argv)
    if not argv:
        raise Stop("give the command to run after --")
    if args.slots < 1:
        raise Stop("--slots must be at least 1")
    if args.wait_seconds is not None and args.wait_seconds < 0:
        raise Stop("--wait-seconds must be zero or greater")
    why = now_and_why(args)
    machine = machine_module()
    label = args.label or Path(argv[0]).name
    # An unlabelled run is measured by a digest of its whole command line, as machine.py measures one, so no argument,
    # a secret included, reaches the shared ledger.
    subject = args.label or f"{Path(argv[0]).name} {hashlib.sha256(shlex.join(argv).encode('utf-8')).hexdigest()[:16]}"
    story = claim_story(c)
    try:
        held = heavy_claim("run", subject, label=label, slots=args.slots, exclusive=args.exclusive, now_why=why,
                           wait_seconds=args.wait_seconds, repository=machine_repository(), delivery=c.delivery,
                           story=story)
    except machine.GaveUp as error:
        print(str(error), file=sys.stderr)
        raise SystemExit(MACHINE_GAVE_UP) from None
    with held:
        if why is not None and stepped_off(held):
            journal_override(c, story or c.delivery, f"ran {label} at once, stepping off the machine's wait", why)
        measured = machine.measured_run(argv, env={**os.environ, **held.child_environment()})
        held.record_cost(measured)
    code = measured.returncode
    raise SystemExit(128 - code if code < 0 else code)


def check_median(c, name: str) -> str:
    """A check's measured median from the record's check history, as the queue keeps it."""
    try:
        seconds = (((c.record_state().get("meta") or {}).get("checkHistory") or {}).get("checks") or {}).get(name, {})
        median = _validator().median_seconds(list(seconds.get("seconds") or []))
    except (OSError, ValueError, AttributeError, TypeError):
        median = None
    return f"median {median}s" if median is not None else "no median yet"


def record_line(record: dict) -> str:
    seconds = f" in {record['seconds']}s" if "seconds" in record else ""
    log = f"; its output: {record['log']}" if record.get("log") else ""
    return f"{record['check']} {record['result']}{seconds} at {record['head'][:10]} ({record.get('where')}){log}"


CHECK_RECORDS = "checks.jsonl"


def check(args) -> None:
    """Run checks by id at HEAD the way the queue does, and keep each record in the story's review folder."""
    c = cfg()
    key = c.require(args.key)
    ids = [name.strip() for text in args.ids for name in text.split(",") if name.strip()]
    if not ids:
        raise Stop("name the checks to run, by id")
    why = now_and_why(args)
    head = clean_head()
    records, seconds = check_runs(c, head, ids, now_why=why)
    with (review_dir(key) / CHECK_RECORDS).open("a", encoding="utf-8") as kept:
        for record in records:
            kept.write(json.dumps(record, sort_keys=True) + "\n")
    for record in records:
        print(f"check {record_line(record)}; {check_median(c, record['check'])}")
    ran = sum(record.get("seconds", 0) for record in records)
    print(f"prepare and checkout: {max(0, round(seconds - ran))}s of the run's {round(seconds)}s")
    print(f"kept {len(records)} record(s) in {review_dir(key) / CHECK_RECORDS}")
    if any(record["result"] != "passed" for record in records):
        sys.exit(1)


def handoff_records(key: str, head: str) -> dict[str, dict]:
    """For each check the binding defines and doesn't exclude from reuse, the latest record the lane keeps at `head` or
    its nearest ancestor, whatever its result, so a later failure replaces an earlier pass. A record from `check` or
    from a gate counts alike; one at a commit `head` doesn't hold is left out, and so is a latest one that was skipped,
    which no evidence entry can carry. Whether a record applies is the queue's to answer."""
    c = cfg()
    records = kept_records(review_dir(key))
    excluded = {entry.get("check") for entry in ((c.binding or {}).get("reuse") or {}).get("exclude") or []
                if isinstance(entry, dict)}
    known = set(binding_checks(c.binding)) - excluded
    distance: dict[str, int | None] = {}

    def behind(commit: str) -> int | None:
        if commit not in distance:
            held = run(["git", "merge-base", "--is-ancestor", commit, head], cwd=repo(), check=False).returncode == 0
            distance[commit] = int(git("rev-list", "--count", f"{commit}..{head}")) if held else None
        return distance[commit]

    latest: dict[str, tuple[int, float, dict]] = {}
    for record in records:
        name = record.get("check")
        if name not in known or not isinstance(record.get("head"), str) or behind(record["head"]) is None:
            continue
        rank = (-behind(record["head"]), recorded_at(record))
        if name not in latest or rank >= latest[name][:2]:
            latest[name] = (*rank, record)
    fields = (*_validator().EVIDENCE_FIELDS, *_validator().EVIDENCE_OPTIONAL)
    return {name: {field: record[field] for field in fields if field in record}
            for name, (_, _, record) in sorted(latest.items()) if record.get("result") in ("passed", "failed")}


def recorded_at(record: dict) -> float:
    """When a record was made, as a number: records carry times to the second or finer, which don't sort as text."""
    try:
        return datetime.datetime.fromisoformat(str(record.get("at")).replace("Z", "+00:00")).timestamp()
    except ValueError:
        return 0.0


def records_shown(records: dict[str, dict]) -> str:
    return "; ".join(f"{name} {r['result']} at {r['head'][:10]} ({r.get('where', 'unsaid')})"
                     for name, r in records.items()) or "none"


def checkout_record(c, g: dict, head: str, tree: str, code: int, seconds: float) -> dict:
    """An inline gate's run record: run in the lane's own checkout, with its session's environment, so it carries
    neither environment nor host facts. Its definition is the binding's check of that id, if it has one."""
    binding = {"checkTimeoutSeconds": 1800, "profiles": {}, "environment": {}, "prepare": [], "hooks": "inherit",
               **(c.binding or {})}
    check = {"cwd": ".", "prerequisites": [], **(binding_checks(c.binding).get(g["id"]) or {
        "id": g["id"], "argv": g["argv"], "cwd": g.get("cwd", "."), "timeoutSeconds": g.get("timeoutSeconds", 1800)})}
    return {"check": g["id"], "definition": _validator().check_definition(check, binding), "head": head, "tree": tree,
            "result": "passed" if code == 0 else "failed", "seconds": round(seconds, 3), "at": now(),
            "where": "checkout"}


def guard_ids(binding: dict | None) -> list[str]:
    """The binding's guards: the catalogue checks every candidate runs, which a lane meets first at `gate`."""
    guards = ((binding or {}).get("selection") or {}).get("guards") or []
    return [name for name in guards if isinstance(name, str)]


def kept_records(folder: Path) -> list[dict]:
    """Every run record a story's review folder keeps: `check`'s, and the last gate run's, its guards' included."""
    kept = folder / CHECK_RECORDS
    records = [json.loads(line) for line in kept.read_text(encoding="utf-8").splitlines() if line.strip()] if kept.exists() else []
    gates = load_json(folder / "gates.json") or {}
    records += [r["record"] for r in gates.get("results", []) if isinstance(r.get("record"), dict)]
    records += [r for r in (gates.get("guards") or {}).get("records", []) if isinstance(r, dict)]
    return records


@contextlib.contextmanager
def queue_reader(c):
    """The release's merge queue runner over this checkout, for `applies` and the binding it reads at a commit: never
    run, only asked."""
    merge_queue = _merge_queue()
    runner = merge_queue.Runner(repo(), repo(), remote=c.remote, base=c.base_branch)
    try:
        yield runner
    except merge_queue.Stop as error:
        raise Stop(f"the merge queue can't answer: {error.reason}: {error.detail}") from None
    finally:
        shutil.rmtree(runner._bootstrap_hooks, ignore_errors=True)


def record_reasons(runner, record: dict, name: str, tree: str, binding: dict, own: set[str] | None = None) -> list[str]:
    """Why a record doesn't stand for a run of `name` at `tree`, as the queue's `applies` answers, or nothing. The
    environment and host facts are the queue's to compare, at its own run."""
    check = binding_checks(binding).get(name)
    if check is None:
        return [f"the binding has no check {name}"]
    return runner.applies(record, check, tree, binding, None, own=own)


def gate_guards(c, key: str, head: str, tree: str, now_why: str | None = None) -> tuple[dict, bool]:
    """Run the binding's guards at HEAD through run-checks, before the repository's gates, reusing a guard's latest
    record at this tree when it applies. Prints each guard's result and median, and the prepare time."""
    ids = guard_ids(c.binding)
    kept = kept_records(review_dir(key))
    reused, run_ids = {}, []
    with queue_reader(c) as runner:
        binding = runner.read_binding(head)
        for name in ids:
            at_tree = [r for r in kept if r.get("check") == name and r.get("tree") == tree]
            latest = max(at_tree, key=recorded_at) if at_tree else None
            if latest is not None and not record_reasons(runner, latest, name, tree, binding):
                reused[name] = latest
            else:
                run_ids.append(name)
    records, seconds = check_runs(c, head, run_ids, now_why=now_why) if run_ids else ([], 0.0)
    ran = {record["check"]: record for record in records}
    for name in ids:
        record = reused.get(name) or ran[name]
        how = f"reused the pass from {record['at']}" if name in reused else record_line(record)
        print(f"guard {name}: {how}; {check_median(c, name)}")
    if run_ids:
        took = sum(record.get("seconds", 0) for record in records)
        print(f"  prepare and checkout: {max(0, round(seconds - took))}s of the run's {round(seconds)}s")
    passed = all((reused.get(name) or ran[name])["result"] == "passed" for name in ids)
    return {"ids": ids, "reused": sorted(reused), "records": [*reused.values(), *records]}, passed


def guard_lines(key: str, root: Path, head: str) -> list[str]:
    """Each guard's record at `head` from the lane's last gate run, or its recorded skip, as a lead or lane reads it."""
    c = cfg()
    ids = guard_ids(c.binding)
    if not ids:
        return []
    record = load_json(root / c.work / "review" / key / "gates.json") or {}
    if record.get("head") != head:
        return [f"guards: no gate run at {head[:10]}"]
    guards = record.get("guards") or {}
    if guards.get("skipped"):
        return [f"guards skipped at {head[:10]}: {guards.get('why')}"]
    found = {r.get("check"): r for r in guards.get("records", [])}
    return ["guards: " + "; ".join(
        f"{name} {found[name]['result']} at {found[name]['head'][:10]}"
        + (" (reused)" if name in guards.get("reused", []) else "") if name in found else f"{name} not recorded"
        for name in ids)]


def gate(args) -> None:
    c = cfg()
    key = c.require(args.key)
    if args.skip_guards and not (args.why or "").strip():
        raise Stop("--skip-guards needs --why, the reason the guards don't run, which the hand-off shows")
    now_why = now_and_why(args, skip=args.skip_guards)
    if not c.gates:
        raise Stop(f"{c.path} declares no gates")
    unknown = [g["id"] for g in c.gates if g.get("unknown")]
    if unknown:
        raise Stop(f"the gates name checks the binding doesn't define: {', '.join(unknown)}; run {flow_command()} doctor")
    head = clean_head()
    tree = git("rev-parse", "HEAD^{tree}")
    git("fetch", "-q", c.remote, c.base_branch)
    results, passed, built = [], True, False
    build_argv = (c.in_app or {}).get("build", {}).get("argv")
    guards = None
    if args.skip_guards:
        guards = {"ids": guard_ids(c.binding), "skipped": True, "why": args.why.strip()}
        print(f"guards skipped: {guards['why']}")
    elif guard_ids(c.binding):
        guards, passed = gate_guards(c, key, head, tree, now_why)
        if not passed:
            failed = [r["check"] for r in guards["records"] if r["check"] in guards["ids"] and r["result"] != "passed"]
            print(f"the guard(s) {', '.join(failed)} didn't pass: the repository's gates don't run")
    gates = list(c.gates) if passed else []
    while gates and passed:
        if gates[0].get("check"):
            # Gates named by id, one after another, run in one run-checks call: one prepared checkout for them all.
            group = []
            while gates and gates[0].get("check"):
                group.append(gates.pop(0))
            print(f"gate {', '.join(g['id'] for g in group)}: run-checks at {head[:10]}", flush=True)
            records, _ = check_runs(c, head, [g["check"] for g in group], now_why=now_why)
            by_id = {record["check"]: record for record in records}
            for g in group:
                record = by_id[g["check"]]
                code = 0 if record["result"] == "passed" else 1
                tail = [f"its output: {record['log']}"] if record.get("log") else []
                results.append({"id": g["id"], "argv": g["argv"], "exit": code, "seconds": round(record.get("seconds", 0)),
                                "tail": tail, "record": record})
                print(f"  {g['id']}: {'ok' if code == 0 else 'FAILED'} in {round(record.get('seconds', 0))}s"
                      + ("" if code == 0 else f" ({record['result']})" + "".join(f"\n    {t}" for t in tail)))
                if code != 0:
                    passed = False
            continue
        g = gates.pop(0)
        argv = expand_argv(g["argv"], base=c.base_ref, key=key, delivery=c.delivery)
        started = time.time()
        print(f"gate {g['id']}: {' '.join(shlex.quote(a) for a in argv)}", flush=True)
        code, out = run_group(argv, repo() / g.get("cwd", "."), g.get("timeoutSeconds", 1800))
        elapsed = time.time() - started
        seconds = round(elapsed)
        tail = out.strip().splitlines()[-15:]
        results.append({"id": g["id"], "argv": argv, "exit": code, "seconds": seconds, "tail": tail,
                        "record": checkout_record(c, g, head, tree, code, elapsed)})
        print(f"  {'ok' if code == 0 else 'FAILED'} in {seconds}s" + ("" if code == 0 else "\n    " + "\n    ".join(tail)))
        if code != 0:
            passed = False
            break
        # Only the in-app build itself, run from the repository root, writes the artifact the stamp belongs to.
        built = built or (build_argv is not None and g["argv"] == build_argv and g.get("cwd", ".") in (".", ""))
    if clean_head() != head:
        raise Stop("HEAD moved, or a gate left files behind; run the gates again")
    if passed and built:  # the gate built the in-app artifact from this clean head: stamp it, saving a rebuild
        write_stamp(repo() / c.in_app["build"]["artifact"], head, tree)
    (review_dir(key) / "gates.json").write_text(json.dumps(
        {"head": head, "at": now(), "passed": passed, "results": results, **({"guards": guards} if guards else {})},
        indent=2) + "\n")
    print(f"gates {'passed' if passed else 'FAILED'} at {head[:10]}" + (" (in-app build stamped)" if passed and built else ""))
    if not passed:
        sys.exit(1)


def gates_summary(key: str, root: Path, head: str) -> tuple[str, list[str]]:
    c = cfg()
    if not c.gates:
        if c.flow_raw.get("gates") == "none":
            return f"no gates ({c.name} says none)", []
        return "", ["no gates are declared (the binding's fallback checks are empty); declare them, or set "
                    f"'gates': 'none' in {c.name} if the repository truly has none"]
    path = root / c.work / "review" / key / "gates.json"
    if not path.exists():
        return "", [f"no gate run recorded: run {flow_command()} gate {key}"]
    record = json.loads(path.read_text())
    if record["head"] != head:
        return "", [f"the gates ran at {record['head'][:10]}, not {head[:10]}: run them again"]
    if not record["passed"] or [r["id"] for r in record["results"]] != [g["id"] for g in c.gates]:
        return "", ["the recorded gate run didn't pass every gate"]
    return "gates at " + head[:10] + ": " + ", ".join(f"{r['id']} ok ({r['seconds']}s)" for r in record["results"]), []


def need_in_app() -> dict:
    if not cfg().in_app:
        raise Stop(f"{cfg().path} declares no inApp adapter")
    return cfg().in_app


def build(args) -> None:
    """Build HEAD for the in-app checks: a story's build, or with no key the delivery's integration build."""
    c = cfg()
    # The integration build of the whole delivery goes by the delivery's own key, as the lead's checkout does.
    key = c.require(args.key) if args.key is not None else c.delivery
    spec = need_in_app()["build"]
    head = clean_head()
    tree = git("rev-parse", "HEAD^{tree}")
    artifact = repo() / spec["artifact"]
    (artifact / STAMP).unlink(missing_ok=True)
    code, out = run_group(expand_argv(spec["argv"], key=key), repo(), spec.get("timeoutSeconds", 1800))
    if code != 0:
        raise Stop("the build failed:\n" + "\n".join(out.strip().splitlines()[-20:]))
    if clean_head() != head:
        raise Stop("HEAD moved or the build left files behind; build again")
    write_stamp(artifact, head, tree)
    print(f"built {head[:10]} into {artifact}")


def port_open(port: int) -> bool:
    for family, host in ((socket.AF_INET, "127.0.0.1"), (socket.AF_INET6, "::1")):
        try:
            with socket.socket(family) as s:
                s.settimeout(0.5)
                if s.connect_ex((host, port)) == 0:
                    return True
        except OSError:
            continue
    return False


def port_holders(port: int) -> list[tuple[int, str]]:
    """The processes listening on `port`, as (pid, command line); empty when none can be seen (or lsof is missing)."""
    try:
        listing = run(["lsof", "-nP", f"-iTCP:{port}", "-sTCP:LISTEN", "-t"], check=False).stdout
    except OSError:
        return []
    holders = []
    for pid in sorted({int(line) for line in listing.split() if line.isdigit()}):
        try:
            command = run(["ps", "-o", "command=", "-p", str(pid)], check=False).stdout.strip()
        except OSError:
            command = ""
        holders.append((pid, command or "command unknown"))
    return holders


def short_command(command: str) -> str:
    """A long command keeps its head (the program) and its tail (the arguments, which tell one server from another)."""
    return command if len(command) <= 160 else f"{command[:40]} ... {command[-110:]}"


def port_busy(port: int) -> str:
    """Why the in-app port can't be used: who listens on it, outside the lease, and how to release it."""
    holders = port_holders(port)
    if not holders:
        return f"something else is listening on {port}, outside the in-app lease (its process isn't visible here); stop it first"
    named = ", ".join(f"pid {pid} ({short_command(command)})" for pid, command in holders)
    pids = " ".join(str(pid) for pid, _ in holders)
    return (f"something else is listening on {port}, outside the in-app lease: {named}. A build served by hand doesn't "
            f"hold the lease, so app-check can't use the port: stop it (kill {pids}) and run again")


# How long the serve has to start listening.
SERVE_READY_SECONDS = 20
# How long a serve that lost its port to another listener is given to exit, so its refusal can name the exit, or to
# take the port once that listener lets it go.
SERVE_SETTLE_SECONDS = 5
# Where the host can't name a port's listeners, how long the serve must stay running once the port answers to be taken
# as the listener: a serve that lost the bind dies of it well within this.
SERVE_UNNAMED_SECONDS = 2


def serve_log(ia: dict) -> Path:
    """Where the serve's output goes: beside the lease's lock, written by one holder at a time, as the check's spec is."""
    lock = Path(expand(ia["lock"]))
    return lock.with_name(lock.name + ".serve.log")


def start_serve(ia: dict, dist: Path, port: int, lease: "Lease") -> subprocess.Popen:
    """Start the serve adapter on `dist` under `lease` and wait until `port` answers from it. Refuses, having stopped
    what it started, unless the listener is this serve's: a serve that loses the port to another listener (another run
    on the same port, under a lease of its own) exits or never listens, and the port's answer is then someone else's."""
    log = serve_log(ia)
    with open(log, "w") as out:
        server = subprocess.Popen(expand_argv(ia["serve"]["argv"], dir=str(dist), port=str(port)),
                                  stdout=out, stderr=subprocess.STDOUT, start_new_session=True)
    try:
        lease.track(server.pid)
        ready = time.monotonic() + SERVE_READY_SECONDS
        while time.monotonic() < ready:
            if port_open(port) or server.poll() is not None:
                break
            time.sleep(0.2)
        problem = serve_problem(server, port, log)
    except BaseException:
        stop_group(server)
        raise
    if problem:
        stop_group(server)
        raise Stop(problem)
    return server


def serve_problem(server: subprocess.Popen, port: int, log: Path) -> str | None:
    """Why the listener on `port` isn't `server`'s, or None when it is: a listener in the serve's own process group
    (its child, for a serve that runs its server as one), or, where the host can't name listeners, a serve that stays
    running a moment after the port answers."""
    def group(pid: int) -> int | None:
        try:
            return os.getpgid(pid)
        except (ProcessLookupError, PermissionError):
            return None

    def output() -> str:
        try:
            tail = log.read_text(errors="replace").strip()[-600:]
        except OSError:
            tail = ""
        return f"; its output is in {log}" + (f", ending:\n{tail}" if tail else "")

    if not port_open(port):
        if server.poll() is not None:
            return f"the serve command exited with code {server.returncode} before it listened on port {port}" + output()
        return f"the serve command didn't start listening on port {port}" + output()
    holders = port_holders(port)
    if any(group(pid) == server.pid for pid, _ in holders):
        return None
    if not holders:
        settled = time.monotonic() + SERVE_UNNAMED_SECONDS
        while server.poll() is None and time.monotonic() < settled:
            time.sleep(0.1)
        if server.poll() is None:
            return None
    # Give the serve a moment: it exits of the lost bind, so its refusal can name the exit, or it takes the port once
    # the other listener lets it go, and is then this run's after all.
    deadline = time.monotonic() + SERVE_SETTLE_SECONDS
    while server.poll() is None and time.monotonic() < deadline:
        holders = port_holders(port) or holders
        if any(group(pid) == server.pid for pid, _ in holders):
            return None
        time.sleep(0.2)
    named = ", ".join(f"pid {pid} ({short_command(command)})" for pid, command in holders) or "a process this host can't name"
    state = (f"exited with code {server.returncode}" if server.poll() is not None
             else f"is still running (pid {server.pid}) and isn't listening")
    return (f"port {port} answered, but not from this run's serve: {named} took the port while the serve was starting, "
            f"so the check would have run against that server. This run's serve {state}" + output() + ". Another run "
            "using the same port under a lease of its own does this: give each its own port, or have them share one lock")


class Lease:
    """An in-app lease: an OS lock held for the whole check (released if we die). It records the process groups it
    starts, so the next holder can stop a server or browser that a killed holder left behind."""

    def __init__(self, lock: Path, port: int, owner: str, wait: int):
        lock.parent.mkdir(parents=True, exist_ok=True)
        self.file = open(lock, "a+")
        deadline = time.time() + wait
        while True:
            try:
                fcntl.flock(self.file, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.time() > deadline:
                    self.file.seek(0)
                    holder = self.file.read().strip() or "unknown holder"
                    self.file.close()  # a lease given up holds nothing, not even its file
                    raise Stop(f"the in-app lease is held ({holder}); gave up after {wait}s")
                time.sleep(min(3, max(0.1, wait / 10)))
        self.file.seek(0)
        for group in re.findall(r"pgid (\d+)", self.file.read()):  # we hold the lock, so their owner is gone
            try:
                os.killpg(int(group), signal.SIGTERM)
            except (ProcessLookupError, PermissionError):
                pass
        if port_open(port):
            time.sleep(1)
        self.owner = f"{owner} pid {os.getpid()} since {now()}"
        self.groups: list[int] = []
        self.write()

    def track(self, pid: int) -> None:
        self.groups.append(pid)
        self.write()

    def write(self, extra: str = "") -> None:
        self.file.seek(0)
        self.file.truncate()
        self.file.write(self.owner + "".join(f" pgid {g}" for g in self.groups) + (f" {extra}" if extra else "") + "\n")
        self.file.flush()

    def close(self) -> None:
        self.groups = []
        self.write("released")
        fcntl.flock(self.file, fcntl.LOCK_UN)
        self.file.close()


def rules(report: dict, *, mode: str, spec: dict, pinned: list[str], build_head: str | None,
          allowed_errors: set[str], error_pattern: str) -> dict[str, bool]:
    """The in-app rules for one check. Pure, so the self-test can feed it fixtures."""
    holds, fails = spec.get("holds", []), spec.get("fails", [])
    evals, after = report.get("evals", []), report.get("afterEvals", [])
    served = (report.get("build") or {}).get("head")
    r = {
        "the app was ready (signed in, page rendered)": report.get("ready") is True,
        "served the stamped build": bool(build_head) and served == build_head,
        "no page errors": not report.get("pageErrors"),
        "no new console errors": not [e for e in report.get("consoleErrors", [])
                                      if re.search(error_pattern, e) and e not in allowed_errors],
        "at least one eval": bool(evals),
        "every eval returned true": all(e.get("result") is True for e in [*evals, *after]),
    }
    if report.get("afterForFound") is False:
        r["after-for found"] = False
    first_eval = min((e["evalAt"] for e in evals), default=None)
    if mode == "hold":
        held = [e for e in report.get("held", []) if not e.get("afterRelease")]  # later re-fetches aren't held
        r["hold mode: holds given, no fails"] = bool(holds) and not fails
        r["every hold is a pinned pattern"] = all(h in pinned for h in holds)
        r["every hold held a request before the evals"] = bool(first_eval) and all(
            any(e.get("regex") == h and e["heldAt"] <= first_eval for e in held) for h in holds)
        r["at least one after-eval"] = bool(after)
        held_at = max((e["heldAt"] for e in held), default=None)
        released = min((e["releasedAt"] for e in held if e.get("releasedAt")), default=None)
        r["evals ran while held"] = bool(held_at and released) and all(held_at <= e["evalAt"] <= released for e in evals)
        r["no alert appeared during the hold (alertsSeen reported and empty)"] = (
            isinstance(report.get("alertsSeen"), list) and not report["alertsSeen"])
    elif mode == "fail":
        failed = report.get("failed", [])
        r["fail mode: fails given, no holds"] = bool(fails) and not holds
        r["every fail is a pinned pattern"] = all(f in pinned for f in fails)
        r["every fail failed a request before the evals"] = bool(first_eval) and all(
            any(e.get("regex") == f and e.get("at") and e["at"] <= first_eval for e in failed) for f in fails)
        r["failures were error statuses"] = all(int(e.get("status", 0)) >= 400 for e in failed)
    elif mode == "loaded":
        r["loaded mode: no holds or fails"] = not holds and not fails
    else:
        r[f"known mode ({mode})"] = False
    return r


def refuse_secrets(passthrough: list[str]) -> None:
    """Sign-in values never travel as adapter arguments: those are recorded in logs, records and evidence."""
    for arg in passthrough:
        name = arg.lstrip("-").split("=", 1)[0] if arg.startswith("-") else (arg.split("=", 1)[0] if "=" in arg else "")
        if name and SECRET_ARGUMENT.search(name):
            raise Stop(f"adapter argument {name!r} looks like a sign-in value: sign-in values come only from the "
                       "environment or the adapter itself, never from arguments, which are recorded")


def run_in_app(dist: Path, spec: dict, passthrough: list[str], owner: str, lock_wait: int | None) -> dict:
    """Serve `dist` and run one check spec against it, under the in-app lease. Returns the check's report."""
    ia = need_in_app()
    port = ia["port"]
    lock = Path(expand(ia["lock"]))
    lease = Lease(lock, port, owner, lock_wait or ia.get("lockWaitSeconds", 480))
    server = check = None
    # Beside the lease's lock, under the lease: one holder at a time writes it, so a holder that is killed before it
    # can remove it leaves one file the next holder overwrites, never a file per check in the system's temp folder.
    spec_file = lock.with_name(lock.name + ".spec.json")
    try:
        spec_file.write_text(json.dumps(spec))
        if port_open(port):
            raise Stop(port_busy(port))
        server = start_serve(ia, dist, port, lease)
        check = subprocess.Popen(expand_argv(ia["check"]["argv"], spec=str(spec_file), port=str(port), args=passthrough),
                                 stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, start_new_session=True)
        lease.track(check.pid)
        timeout = ia.get("checkTimeoutSeconds", 300)
        try:
            out, err = check.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            raise Stop(f"the check took longer than {timeout}s and was stopped")
        if check.returncode != 0:
            raise Stop(f"the check failed: {(err or out).strip()[-500:]}")
        try:
            report = json.loads(out)
        except json.JSONDecodeError:
            raise Stop(f"the check printed no JSON report: {out.strip()[-300:]}")
    finally:
        for proc in (check, server):  # wait for both to exit before the lease is released
            stop_group(proc)
        spec_file.unlink(missing_ok=True)  # still under the lease: once it is released, the path is the next holder's
        lease.close()
    return report


def app_check(args) -> None:
    c = cfg()
    key = c.require(args.key)
    ia = need_in_app()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]*", args.name) or args.name.endswith("-baseline"):
        raise Stop("name the check with lowercase letters, digits and dashes (no -baseline suffix)")
    if args.baseline and args.probe:
        raise Stop("--baseline and --probe don't combine")
    if args.probe and (args.mode != "loaded" or args.hold or args.fail):
        raise Stop("a probe is a plain load (--mode loaded, no --hold or --fail): it looks things up, it isn't a check")
    passthrough = list(args.passthrough)
    smuggled = [a for a in passthrough if a.split("=")[0] in SPEC_FLAGS]
    if smuggled:
        raise Stop(f"{smuggled} belong to the check spec: pass them to app-check itself, not after --")
    refuse_secrets(passthrough)
    spec = {"path": args.path, "holds": args.hold, "fails": args.fail, "clicks": args.click, "evals": args.eval,
            "afterEvals": args.after_eval, "for": args.for_, "wait": args.wait, "afterFor": args.after_for}
    if args.baseline:
        if not ia.get("baseline"):
            raise Stop(f"{c.path} declares no inApp.baseline build")
        dist, head, tree = Path(expand(ia["baseline"])), None, None
    else:
        dist = repo() / ia["build"]["artifact"]
        head = clean_head() if not args.probe else git("rev-parse", "HEAD")
        tree = git("rev-parse", "HEAD^{tree}")
    stamp = dist / STAMP
    built = json.loads(stamp.read_text()) if stamp.exists() else {}
    if not args.baseline and not args.probe and built.get("head") != head:
        raise Stop(f"the build in {dist} isn't from HEAD {head[:10]} (built: {str(built.get('head'))[:10]}); "
                   f"run {flow_command()} build {key} first")
    if not built.get("head"):
        raise Stop(f"{dist} has no {STAMP}; build it with {flow_command()} build (or stamp the baseline)")
    pinned = c.stories[key].get("pinned", [])
    out_dir = review_dir(key) / ("probes" if args.probe else "app-checks")
    out_dir.mkdir(exist_ok=True)
    name = args.name + ("-baseline" if args.baseline else "")
    pattern = ia.get("consoleErrorPattern", ".")
    allowed: set[str] = set()
    baseline_record = out_dir / f"{args.name}-baseline.json"
    if not args.baseline and args.mode != "fail" and baseline_record.exists():
        base = json.loads(baseline_record.read_text())
        # Only a plain load of the same page can excuse an error: never a hold or fail run, which provoke them.
        if base["mode"] == "loaded" and base["spec"].get("path") == args.path and base.get("passthrough") == passthrough:
            allowed = {e for e in base["report"].get("consoleErrors", []) if re.search(pattern, e)}
    report = run_in_app(dist, spec, passthrough, f"{key} {name}", args.lock_wait)
    if args.probe:
        path = out_dir / f"{name}.json"
        path.write_text(json.dumps({"story": key, "name": name, "at": now(), "spec": spec, "report": report}, indent=2) + "\n")
        print(f"probe {key} {name} (not evidence) -> {path}")
        for e in [*report.get("evals", []), *report.get("afterEvals", [])]:
            print(f"  {str(e.get('expr'))[:70]} -> {json.dumps(e.get('result', e.get('error')))[:300]}")
        return
    verdict = rules(report, mode=args.mode, spec=spec, pinned=pinned, build_head=built.get("head"),
                    allowed_errors=allowed, error_pattern=pattern)
    passed = all(verdict.values())
    record = {"story": key, "name": name, "mode": args.mode, "baseline": args.baseline, "head": head, "tree": tree,
              "at": now(), "dist": str(dist), "spec": spec, "passthrough": passthrough, "pinned": pinned,
              "rules": verdict, "pass": passed, "report": report}
    path = out_dir / f"{name}.json"
    path.write_text(json.dumps(record, indent=2) + "\n")
    # Every run, lead-side, so a removed record or an eval changed after failing is visible to the lens and the lead.
    append_log("app-checks", key, {"name": name, "mode": args.mode, "pass": passed, "head": head, "record": digest(path),
                                   "spec": spec_digest(spec, passthrough), "specValue": spec, "passthrough": passthrough})
    print(f"{'PASS' if passed else 'FAIL'} {key} {name} ({args.mode}) -> {path}")
    for rule, ok in verdict.items():
        print(f"  {'ok ' if ok else 'NO '} {rule}")
    for e in [*report.get("evals", []), *report.get("afterEvals", [])]:
        extra = f" (first {json.dumps(e.get('firstResult'))}, {e['polls']} polls)" if "polls" in e else ""
        print(f"  eval {json.dumps(e.get('result', e.get('error')))[:100]}{extra} <- {str(e.get('expr'))[:80]}")
    if not report.get("ready"):
        print("  the app wasn't ready (signed out, or the page never rendered): if signed out, ask the lead")
    if not passed:
        sys.exit(1)


def needs_video(key: str) -> bool:
    return cfg().stories[key].get("evidence") == "video"


def stamped(dist: Path) -> dict:
    stamp = dist / STAMP
    built = json.loads(stamp.read_text()) if stamp.exists() else {}
    if not built.get("head"):
        raise Stop(f"{dist} has no {STAMP}; build it with {flow_command()} build (or stamp it)")
    return built


def page_crop(clip: Path) -> str:
    """A crop to the page's area. A browser's recording can be taller than what it painted, padded with flat grey
    rows at the bottom; find them on the last second (grey to black, everything else to white, then cropdetect)."""
    probe = run(["ffmpeg", "-hide_banner", "-sseof", "-1", "-i", str(clip), "-vf",
                 "lutyuv=y='if(between(val,118,138),0,255)':u=128:v=128,cropdetect=limit=16:round=2:reset=0",
                 "-f", "null", "-"], check=False)
    found = re.findall(r"crop=(\d+):(\d+):(\d+):(\d+)", probe.stderr)
    size = run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height",
                "-of", "csv=p=0", str(clip)]).stdout.strip().split(",")
    if not found:
        return ""
    w, h, x, y = map(int, found[-1])
    if (w, h) == (int(size[0]), int(size[1])) or h < int(size[1]) // 3:
        return ""
    return f"crop={w}:{h}:{x}:{y},"


def common_crop(clips: list[Path]) -> tuple[str, ...]:
    """The same crop for every clip (the shortest painted area), so they stack side by side at one height."""
    found = []
    for clip in clips:
        crop = page_crop(clip)
        size = run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height",
                    "-of", "csv=p=0", str(clip)]).stdout.strip().split(",")
        found.append(int(crop.split(":")[1]) if crop else int(size[1]))
        width = int(size[0])
    height = min(found) // 2 * 2
    return tuple(f"crop={width}:{height}:0:0," for _ in clips)


def side_by_side(before: Path, after: Path, out: Path, labels: tuple[str, str], caption: str,
                 crops: tuple[str, str] = ("", "")) -> None:
    """One clip: before on the left, after on the right, each labelled, both held on their last frame until the
    longer one ends."""
    if not shutil.which("ffmpeg"):
        raise Stop("ffmpeg isn't installed; it stitches the before and after recordings")
    # Labels are burned in only where ffmpeg has drawtext (it needs freetype); the evidence page labels them anyway.
    texts = "drawtext" in run(["ffmpeg", "-hide_banner", "-filters"], check=False).stdout
    esc = lambda t: t.replace("\\", "\\\\").replace(":", "\\:").replace("'", "\u2019")
    label = lambda t: (f",drawtext=text='{esc(t)}':x=16:y=16:fontsize=24:fontcolor=white:box=1:boxcolor=black@0.6:"
                       "boxborderw=8") if texts else ""
    top = (f",pad=iw:ih+56:0:56:color=0x111111,drawtext=text='{esc(caption)}':x=16:y=16:fontsize=24:fontcolor=white"
           if texts else "")
    graph = (f"[0:v]{crops[0]}scale=960:-2,tpad=stop_mode=clone:stop_duration=30{label(labels[0])},pad=iw+8:ih:0:0:color=0x111111[a];"
             f"[1:v]{crops[1]}scale=960:-2,tpad=stop_mode=clone:stop_duration=30{label(labels[1])}[b];"
             f"[a][b]hstack=inputs=2{top}[v]")
    longest = max(float(run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(f)]).stdout
                        or 0) for f in (before, after))
    run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(before), "-i", str(after), "-filter_complex", graph,
         "-map", "[v]", "-t", f"{longest + 0.5:.2f}", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "28",
         "-movflags", "+faststart", str(out)])


def app_video(args) -> None:
    """Record the same scripted run on the baseline build (before) and on this build (after), and stitch them."""
    c = cfg()
    key = c.require(args.key)
    problem = video_tools_problem()
    if problem:
        raise Stop(problem)
    ia = need_in_app()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]*", args.name):
        raise Stop("name the video with lowercase letters, digits and dashes")
    if not ia.get("baseline"):
        raise Stop(f"{c.path} declares no inApp.baseline build to record the 'before' on")
    if args.mode == "hold" and not args.hold or args.mode == "fail" and not args.fail:
        raise Stop(f"a {args.mode} video needs at least one --{args.mode} pattern")
    passthrough = list(args.passthrough)
    smuggled = [a for a in passthrough if a.split("=")[0] in SPEC_FLAGS]
    if smuggled:
        raise Stop(f"{smuggled} belong to the spec: pass them to app-video itself, not after --")
    refuse_secrets(passthrough)
    before_dist = Path(expand(ia["baseline"]))
    after_dist = Path(expand(args.after_build)) if args.after_build else repo() / ia["build"]["artifact"]
    before_built, after_built = stamped(before_dist), stamped(after_dist)
    if args.after_build:
        head = after_built["head"]
    else:
        head = clean_head()
        if after_built["head"] != head:
            raise Stop(f"the build in {after_dist} isn't from HEAD {head[:10]}; run {flow_command()} build {key} first")
    folder = review_dir(key) / "videos"
    folder.mkdir(exist_ok=True)
    clips, reports = {}, {}
    work = Path(tempfile.mkdtemp(prefix="flow-video-"))
    try:
        for side, dist in (("before", before_dist), ("after", after_dist)):
            # A held request is released after the last step; when the steps end in a click, keep it held for the
            # wait after the click too, so the state the click opens stays on screen long enough to see.
            dwell = [f"new Promise(r => setTimeout(() => r(true), {args.wait}))"] if args.mode == "hold" and args.click else []
            spec = {"path": args.path, "holds": args.hold if args.mode == "hold" else [],
                    "fails": args.fail if args.mode == "fail" else [], "clicks": args.click, "evals": dwell,
                    "afterEvals": [], "for": args.for_, "wait": 800 if dwell else args.wait, "afterFor": args.after_for,
                    "video": str(work / side), "settle": args.settle}
            report = run_in_app(dist, spec, passthrough, f"{key} video {args.name} {side}", args.lock_wait)
            problems = []
            # Not `ready`: a page that shows nothing while it loads is exactly what a "before" clip may need to show.
            if not report.get("signedIn", report.get("ready")):
                problems.append("the app wasn't signed in")
            if args.mode == "hold" and not report.get("held"):
                problems.append("no request matched --hold, so the loading state was never shown")
            if args.mode == "fail" and not report.get("failed"):
                problems.append("no request matched --fail, so the failure was never shown")
            if not report.get("video") or not Path(report["video"]).exists():
                problems.append("the check recorded no video (does the adapter support the spec's `video`?)")
            if problems:
                raise Stop(f"the {side} recording isn't evidence: " + "; ".join(problems))
            clips[side], reports[side] = Path(report["video"]), report
        out = folder / f"{args.name}.mp4"
        caption = args.caption or f"{key}: {args.mode} {args.path}"
        side_by_side(clips["before"], clips["after"], out,
                     (f"Before ({before_built['head'][:8]})", f"After ({head[:8]})"), caption,
                     common_crop([clips["before"], clips["after"]]))
    finally:
        shutil.rmtree(work, ignore_errors=True)
    record = {"story": key, "name": args.name, "mode": args.mode, "path": args.path, "caption": caption,
              "head": head, "before": before_built["head"], "after": after_built["head"], "at": now(),
              "file": out.name, "digest": digest(out), "held": [h["regex"] for h in reports["after"].get("held", [])],
              "failed": [f["regex"] for f in reports["after"].get("failed", [])]}
    (folder / f"{args.name}.json").write_text(json.dumps(record, indent=2) + "\n")
    append_log("videos", key, {"name": args.name, "head": head, "digest": record["digest"]})
    print(f"recorded {key} {args.name}: before {before_built['head'][:10]} | after {head[:10]} -> {out}")


def lane_review_folders(key: str) -> list[Path]:
    """Every folder a story's review rounds may be in, on any record: its checkout's, the copy kept after cleanup, the
    lead's."""
    c = cfg()
    return [c.lane_checkout(key) / c.work / "review" / key, evidence_dir(key), repo() / c.work / "review" / key]


def story_folders(key: str) -> list[Path]:
    """Where a story's lane evidence lives: its checkout's review folder, the copy kept after cleanup, the lead's. On a
    shared record only the delivery holder's merged-base folder counts: a lane's clips never do (D22)."""
    c = cfg()
    if shared_seat(c) is not None:
        return [repo() / c.work / "review" / key]
    return lane_review_folders(key)


def carried_check(key: str, mode: str) -> dict | None:
    """D22's recording spec on a shared record: of the carried app-checks log, in its causal order, the last entry of
    this mode that passed and is neither a baseline nor a passthrough run, as a record whose spec is the one it ran."""
    eligible = [entry for entry in read_log("app-checks", key) if entry.get("mode") == mode and entry.get("pass")
                and entry.get("head") is not None and not entry.get("passthrough") and isinstance(entry.get("specValue"), dict)]
    return {"mode": mode, "spec": eligible[-1]["specValue"]} if eligible else None


def html_escape(text: object) -> str:
    return (str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;"))


def latest_clips(key: str) -> dict[str, tuple[dict, Path]]:
    """A story's clips by name, intact ones only; later folders win (the lead's recordings on the merged base)."""
    clips = {}
    for folder in story_folders(key):
        for rec_path in sorted((folder / "videos").glob("*.json")):
            rec = json.loads(rec_path.read_text())
            clip = rec_path.with_name(rec["file"])
            if clip.exists() and digest(clip) == rec["digest"]:
                clips[rec["name"]] = (rec, clip)
    return clips


EVIDENCE_PAGE = "evidence-page.json"
EVIDENCE_NOTES = "evidence-notes.json"


def evidence_taken(c) -> None:
    """Before any evidence is read on a seat just given delivery: what was carried taken first, so a page or recording
    from before the handover is never judged (D22)."""
    roles = seat_roles(c)
    if roles is not None and roles["delivery"]:
        with contextlib.suppress(Stop, OSError, ValueError, subprocess.SubprocessError):
            take_delivery(c)


def evidence_status(keys: list[str]) -> tuple[list[str], list[str]]:
    """Whether the published evidence page carries a clip for every merged story marked for video."""
    c = cfg()
    evidence_taken(c)
    merged = {q["subject"] for q in load_state()["state"]["queue"] if q.get("stage") == "merged"}
    saved = c.state.parent / EVIDENCE_PAGE
    page = json.loads(saved.read_text()) if saved.exists() else None
    current, problems = [], []
    if page is None:
        problems.append("no evidence page is published yet: lead-evidence page, publish it, then lead-evidence published --url")
    for key in keys:
        if key not in merged:
            current.append(f"{key}: not merged yet, so not expected on the page")
            continue
        clips = latest_clips(key)
        if not clips:
            problems.append(f"{key}: no clip; record one (lead-evidence record {key} --after-build ...)")
            continue
        published = set((page or {}).get("clips", {}).values())
        missing = [name for name, (_, clip) in clips.items() if digest(clip) not in published]
        if page is not None and missing:
            problems.append(f"{key}: clip(s) {missing} aren't on the published page; rebuild and republish it")
        elif page is not None:
            current.append(f"{key}: {len(clips)} clip(s) on the page")
    return current, problems


def evidence_inputs(c, args, keys: list[str]) -> dict:
    """The evidence page's words, its title, intro and per-story notes, kept in the record beside the published page's
    record, so a page rebuilt after the lead's context is gone says what it said. A flag given now replaces what's
    kept; `--note KEY=` with no text removes that story's note."""
    path = c.state.parent / EVIDENCE_NOTES
    kept = json.loads(path.read_text()) if path.exists() else {}
    notes = dict(kept.get("notes") or {})
    given = {}
    for note in args.note or []:
        key, sep, text = note.partition("=")
        key = key.strip()
        if not sep or not key:
            raise Stop(f"--note takes KEY=TEXT, not {note!r}")
        if key not in c.stories:
            raise Stop(f"--note names {key}, which isn't a story of {c.delivery}")
        given[key] = text.strip()
    for key, text in given.items():
        if text:
            notes[key] = text
        else:
            notes.pop(key, None)
    inputs = {"title": args.title if args.title is not None else kept.get("title"),
              "intro": args.intro if args.intro is not None else kept.get("intro"), "notes": notes}
    if inputs != {k: kept.get(k, {} if k == "notes" else None) for k in ("title", "intro", "notes")}:
        path.write_text(json.dumps({**inputs, "at": now()}, indent=2) + "\n")
        print(f"recorded the page's words in {path}")
    reused = sorted(k for k in keys if k in notes and k not in given)
    if reused:
        print(f"reused the recorded note(s) for {', '.join(reused)}")
    return inputs


def lead_evidence(args) -> None:
    c = cfg()
    keys = [c.require(k) for k in args.keys] if args.keys else [k for k in c.stories if needs_video(k)]
    if args.action != "status":
        require_scope(c, "delivery", f"records and publishes the evidence page (lead-evidence {args.action})")
    evidence_taken(c)
    shared = shared_seat(c) is not None
    if args.action == "record":
        if not args.after_build:
            raise Stop("record needs --after-build: a stamped build of the merged delivery base")
        head = stamped(Path(expand(args.after_build)))["head"]
        for key in keys:
            have = {json.loads(p.read_text())["mode"] for p in (review_dir(key) / "videos").glob("*.json")
                    if json.loads(p.read_text())["head"] == head}
            records = []
            for folder in story_folders(key):
                records += [json.loads(p.read_text()) for p in sorted((folder / "app-checks").glob("*.json"))]
            for mode in ("hold", "fail"):
                if mode in have:
                    continue
                rec = carried_check(key, mode) if shared else next(
                    (r for r in records if r.get("mode") == mode and r.get("pass") and not r.get("baseline")
                     and not r.get("passthrough")), None)
                if not rec:
                    print(f"{key}: no passing {mode} check to record from; skipped")
                    continue
                sp = rec["spec"]
                ns = argparse.Namespace(key=key, name=f"{c.label(key).lower()}-{'loading' if mode == 'hold' else 'failed-load'}",
                                        mode=mode, path=sp["path"], hold=sp.get("holds", []), fail=sp.get("fails", []),
                                        click=sp.get("clicks", []), for_=sp.get("for") if sp.get("clicks") else None,
                                        wait=2500 if mode == "hold" else max(int(sp.get("wait") or 0), 1500),
                                        after_for=None, settle=2500, lock_wait=None, passthrough=[],
                                        after_build=args.after_build,
                                        caption=f"{key} {c.stories[key]['title']}: "
                                                + ("while it loads" if mode == "hold" else "when the load fails"))
                try:
                    app_video(ns)
                except Stop as error:
                    print(f"{key} {mode}: not recorded: {error}")
        return
    if args.action == "published":
        if not args.url:
            raise Stop("published needs --url: the page's address")
        out = Path(expand(args.out))
        clips = {f.name: digest(f) for f in sorted((out / "videos").glob("*.mp4"))}
        if not (out / "index.html").exists() or not clips:
            raise Stop(f"{out} has no built page with clips: run lead-evidence page first")
        words = out / "evidence-notes.json"  # the words this folder's page was built with, not the latest kept ones
        kept = json.loads(words.read_text()) if words.exists() else {}
        record = {"url": args.url, "at": now(), "clips": clips,
                  **{k: kept.get(k, {} if k == "notes" else None) for k in ("title", "intro", "notes")}}
        (c.state.parent / EVIDENCE_PAGE).write_text(json.dumps(record, indent=2) + "\n")
        state_tool("journal", "--kind", "evidence.published", "--data",
                   json.dumps({"url": args.url, "clips": [{"name": name, "digest": sha} for name, sha in clips.items()]}),
                   check=False)
        print(f"recorded the evidence page {args.url} ({len(clips)} clips); link it from the epic and each story")
        return
    if args.action == "status":
        current, problems = evidence_status(keys)
        for line in current:
            print(f"  ok: {line}")
        for line in problems:
            print(f"  NO: {line}")
        if problems:
            sys.exit(1)
        print("the evidence page is current")
        return
    words = evidence_inputs(c, args, keys)
    out = Path(expand(args.out))
    (out / "videos").mkdir(parents=True, exist_ok=True)
    doc = load_state()
    prs = {q["subject"]: q.get("changeRequest") for q in doc["state"]["queue"]}
    sections, befores, afters, count = [], set(), set(), 0
    for key in keys:
        clips = latest_clips(key)
        figures = []
        for name, (rec, clip) in sorted(clips.items(), key=lambda kv: (kv[1][0]["mode"] != "hold", kv[0])):
            target = f"videos/{key}-{name}.mp4"
            shutil.copy2(clip, out / target)
            befores.add(rec["before"][:8]); afters.add(rec["head"][:8]); count += 1
            figures.append(f"""    <figure>
      <div class="sides"><span>Before</span><span>After</span></div>
      <video src="{target}" controls muted loop playsinline preload="metadata" aria-label="{html_escape(rec['caption'])}"></video>
      <figcaption><span class="chip">{'Loading' if rec['mode'] == 'hold' else 'Failed load' if rec['mode'] == 'fail' else 'Loaded'}</span>{html_escape(rec['caption'])} · <code>{html_escape(rec['path'])}</code></figcaption>
    </figure>""")
        links = [f'<a href="{html_escape(c.issue_url.format(key=key))}">Ticket</a>']
        if prs.get(key):
            links.append(f'<a href="{html_escape(prs[key])}">Pull request</a>')
        notes = words["notes"]
        body = "\n".join(figures) or (f'    <p class="none">{html_escape(notes[key])}</p>' if key in notes else
                                       '    <p class="none">No recording: this story has no visible loading or failure state to show.</p>')
        sections.append(f"""  <section class="story" id="{key.lower()}">
    <div class="story-head"><span class="key">{key} · {html_escape(c.label(key))}</span><h2>{html_escape(c.stories[key]['title'])}</h2><span class="links">{' '.join(links)}</span></div>
{body}
  </section>""")
    values = {
        "title": html_escape(words["title"] or f"{c.delivery} Evidence"),
        "eyebrow": html_escape(f"{c.delivery} · delivery evidence"),
        "heading": html_escape(c.raw.get("headline", c.delivery)),
        "intro": html_escape(words["intro"] or "Each clip runs the same steps twice: on the base before this delivery (left) and "
                             "on the delivered code (right). Loading clips hold the page's request for a few seconds; "
                             "failure clips make it fail."),
        "before": html_escape(", ".join(sorted(befores)) or "-"), "after": html_escape(", ".join(sorted(afters)) or "-"),
        "stories": "\n".join(sections),
        "footer": html_escape(f"{count} clip(s) across {len(keys)} stories. Recorded with run-delivery app-video."),
    }
    page = re.sub(r"\{\{(\w+)\}\}", lambda m: values[m.group(1)], (TOOL / "templates/evidence.html").read_text())
    (out / "index.html").write_text(page)
    (out / "evidence-notes.json").write_text(json.dumps(words, indent=2) + "\n")
    print(f"wrote {out / 'index.html'} with {count} clip(s); publish the folder (index.html plus videos/)")


def video_evidence(key: str, root: Path, head: str) -> tuple[list[str], list[str]]:
    """The story's before/after videos, when its delivery entry asks for them: (lines, problems)."""
    if not needs_video(key):
        return [], []
    folder = root / cfg().work / "review" / key / "videos"
    records = [json.loads(p.read_text()) for p in sorted(folder.glob("*.json"))] if folder.exists() else []
    current = []
    for rec in records:
        ok, _ = record_is_current(rec, head, root)
        clip = folder / rec["file"]
        if ok and clip.exists() and digest(clip) == rec["digest"]:
            current.append(rec)
    if not current:
        return [], [f"{key} needs before/after video evidence: run {flow_command()} app-video {key} <name> ..."]
    return [f"video {r['name']}: {r['mode']} {r['path']} ({r['before'][:8]} -> {r['head'][:8]})" for r in current], []


def record_is_current(rec: dict, head: str, root: Path) -> tuple[bool, str]:
    if rec["head"] == head:
        return True, ""
    done = run(["git", "diff", "--name-only", rec["head"], head, "--", *((cfg().ship or {}).get("paths") or ["."])],
               cwd=root, check=False)
    if done.returncode != 0:
        return False, f"ran at {rec['head'][:10]}, which can't be compared"
    changed = [f for f in done.stdout.splitlines() if f and not re.search(cfg().test_files, f)]
    return (not changed), (f"ran at {rec['head'][:10]}; {len(changed)} shipped file(s) changed since" if changed else "")


def in_app_evidence(key: str, root: Path, head: str, blocked: dict[str, str]) -> tuple[list[str], list[str]]:
    """(lines describing the evidence, problems) for a story's in-app checks at `head`."""
    c = cfg()
    review = root / c.work / "review" / key
    folder = review / "app-checks"
    records = [json.loads(p.read_text()) for p in sorted(folder.glob("*.json"))] if folder.exists() else []
    current, lines, problems = [], [], []
    for rec in records:
        if rec.get("baseline"):
            lines.append(f"{rec['name']}: baseline {rec['mode']}, {'PASS' if rec['pass'] else 'FAIL'}")
            continue
        fresh, why = record_is_current(rec, head, root)
        state = ("PASS" if rec["pass"] else "FAIL") + ("" if fresh else f", STALE ({why})")
        lines.append(f"{rec['name']}: {rec['mode']}, {state}")
        if (not rec["pass"] or not fresh) and rec["name"] not in blocked:
            problems.append(f"in-app check {rec['name']} is {state}; re-run it or pass --blocked {rec['name']}=<reason>")
        if rec["pass"] and fresh:
            current.append(rec)
    lines += [f"history: {h}" for h in check_history(key, records)]
    reqs = c.requirements(key)
    met = satisfied_requirements(reqs, current)
    # Mode requirements first, then pattern coverage, as each is matched.
    for qi, req in sorted(enumerate(reqs), key=lambda pair: pair[1]["mode"] == "any"):
        label = requirement_label(req)
        if qi not in met and label not in blocked:
            problems.append(f"missing a passing check for {label}; run it or pass --blocked '{label}=<reason>'")
    for label, reason in blocked.items():
        lines.append(f"BLOCKED {label}: {reason}")
    return lines, problems


# -- forge -----------------------------------------------------------------------------------

TRANSIENT_EXIT = 75  # EX_TEMPFAIL: an adapter's transient failure, which a PR-review wait retries


def call_adapter(kind: str, prefix: list[str], args: tuple[str, ...], env: dict[str, str]) -> dict:
    """Run a forge or tracker adapter and read the one JSON object it prints. An adapter that prints nothing has
    failed, whatever its exit code: the refusal names the adapter it ran. Exit 75 is a transient failure (Transient),
    which only a PR-review wait's loop retries."""
    argv = [*map(os.path.expanduser, prefix), *args]
    done = subprocess.run(argv, text=True, capture_output=True, env=env, cwd=repo())
    ran = shlex.join(prefix)
    if done.returncode == TRANSIENT_EXIT:
        said = (done.stderr or done.stdout).strip()[-400:] or "it printed nothing"
        raise Transient(f"{kind} {args[0]} failed transiently (exit {TRANSIENT_EXIT}): {said}; the adapter it ran: {ran}")
    if done.returncode != 0:
        said = (done.stderr or done.stdout).strip()[-400:] or "it printed nothing"
        raise Stop(f"{kind} {args[0]} failed: {said}; the adapter it ran: {ran}")
    if not done.stdout.strip():
        raise Stop(f"{kind} {args[0]} printed nothing; the adapter it ran: {ran}")
    try:
        return json.loads(done.stdout)
    except json.JSONDecodeError:
        raise Stop(f"{kind} {args[0]} printed no JSON: {done.stdout.strip()[-200:]}; the adapter it ran: {ran}")


def forge(*args: str) -> dict:
    f = cfg().forge
    prefix = f.get("argv") or [sys.executable, "-B", str(TOOL / "adapters" / f"forge_{f['adapter']}.py")]
    env = {**os.environ, "FLOW_FORGE_REPOSITORY": f.get("repository", ""), "FLOW_FORGE_TOKEN_ENV": f.get("tokenEnv", "")}
    return call_adapter("forge", prefix, args, env)


def forge_answers(command: str) -> bool:
    f = cfg().forge
    return bool(f.get("argv")) or command in ADAPTER_COMMANDS.get(f.get("adapter", ""), ())


def same_commit(reported: object, full: str) -> bool:
    """Forges may report abbreviated hashes (Bitbucket gives 12 characters)."""
    return isinstance(reported, str) and len(reported) >= 7 and full.startswith(reported)


def remote_head(branch: str) -> str:
    line = git("ls-remote", cfg().remote, f"refs/heads/{branch}")
    return line.split("\t")[0] if line else ""


def pushed(key: str, head: str) -> None:
    branch = cfg().branch(key)
    remote = remote_head(branch)
    if remote != head:
        raise Stop(f"{cfg().remote}/{branch} is at {remote[:10] or 'nothing'}, not HEAD {head[:10]}; "
                   f"push first: git push -u {cfg().remote} HEAD:{branch}")


def authority() -> dict:
    """What the operator let lanes do on the forge: {push, draftPullRequests, grantedBy, grantedOn}. Absent: nothing."""
    granted = cfg().raw.get("authority") or {}
    if granted and not (granted.get("grantedBy") and granted.get("grantedOn")):
        raise Stop(f"{cfg().delivery_where}: `authority` must say who granted it and when (grantedBy, grantedOn)")
    return granted


def require_authority(what: str) -> dict:
    granted = authority()
    if not granted.get(what):
        raise Stop(f"this delivery grants lanes no `{what}` authority ({cfg().delivery_where} `authority`); "
                   "hand your branch to the lead instead")
    return granted


def authority_text() -> str:
    c, granted = cfg(), authority()
    if not granted.get("push"):
        return ("Lanes have no authority to push, open pull requests or mark one ready in this delivery. Commit on "
                "your branch and tell the lead it is ready; the lead pushes it.")
    what = f"push your own `{c.branch_pattern.replace('{key}', '<key>')}` branch, with `{flow_command()} push <key>`"
    if granted.get("draftPullRequests"):
        what += f", and open its draft pull request into `{c.base_branch}`, with `{flow_command()} open-pr`"
    return (f"{granted['grantedBy']} gave lanes authority on {granted['grantedOn']} to {what}. That is all: never push "
            f"any other branch, never force-push, and never merge, mark ready or approve a pull request. "
            "The lead's merge queue merges.")


def transitions_text() -> str:
    """The lane's status moves, from the own config's `tracker.transitions`, and which command makes each."""
    conf = tracker_conf(cfg())
    if conf["problems"]:
        raise Stop(f"{cfg().name}: {'; '.join(conf['problems'])}")
    moves = conf["transitions"]
    if not moves.get("start") and not moves.get("review"):
        return "Don't move your story's status: this repository gives lanes no status moves."
    said = lambda names: ", then ".join(f'"{n}"' for n in names)
    publishes = conf["mode"] == "publisher"
    lines = []
    if moves.get("start"):
        lines.append(f"- The start move, {said(moves['start'])}: "
                     + ("the tracker publisher makes it once `lane-start` records your start." if publishes else
                        "`lane-start` prints it; make it with your tracker tools."))
    if moves.get("review"):
        when = moves.get("reviewWhen")
        made = {"gates-passed": "`open-pr` makes it once the PR is open and the gates pass at its head",
                "pr-open": "`open-pr` makes it as the PR opens",
                "pipeline-green": "`pr-review` makes it once the pipeline's review is current and its checks green"}
        lines.append(f"- The review move, {said(moves['review'])}: "
                     + (made[when] + ("" if publishes else ", by printing it for you to make with your tracker tools")
                        if when else "`open-pr` prints it once the PR is open; make it then with your tracker tools")
                     + ".")
    lines.append("Nothing else: later moves (after merge, after a deploy) aren't yours. A move the commands couldn't make "
                 "is retried by running the command again; `handoff` retries a review move that is still owed."
                 + (f" The workflow: {moves['source']}" if moves.get("source") else ""))
    return "\n".join(lines)


def said_moves(names: list[str]) -> str:
    return ", then ".join(f'"{n}"' for n in names)


def review_move_made(c, key: str, names: list[str]) -> bool:
    """Whether this record's ledger holds the story's whole review move: every step made or made by someone else, or
    the move found made or not offered. A move a refusal stopped partway isn't made: the next run resumes it."""
    init = tracker_publisher.init_id(sorted(load_state()["journal"], key=lambda e: e["id"]))
    lines = [line for line in tracker_publisher.read_ledger(c.state) if line.get("init") == init
             and line.get("ticket") == key and line.get("move") == "review"]
    if any(line["outcome"] == "handled" or str(line.get("action", "")).endswith(":made") for line in lines):
        return True
    done = {line.get("transition") for line in lines if line["outcome"] in ("transition", "skip")}
    return all(name in done for name in names)


def start_owed(c, doc: dict, key: str) -> bool:
    """Whether the story's latest assignment has no ledger line yet under this record: its start isn't posted."""
    journal = sorted(doc["journal"], key=lambda e: e["id"])
    assigned = [e for e in journal if e["kind"] == "lane.assigned" and e.get("subject") == key]
    if not assigned:
        return False
    init = tracker_publisher.init_id(journal)
    return not any(line["journal"] == assigned[-1]["id"] and line.get("init") == init
                   for line in tracker_publisher.read_ledger(c.state))


def append_owed(c, doc: dict, key: str, names: list[str], why: str, locked: bool = False) -> None:
    """A review move the hand-off couldn't make, left in the ledger as `failed`, where Needs you shows it. `locked`:
    the caller already holds the ledger's lock (a second lock from this process would wait on itself)."""
    init = tracker_publisher.init_id(sorted(doc["journal"], key=lambda e: e["id"]))
    with tracker_publisher.ledger_lock(c.state, wait=True) if not locked else contextlib.nullcontext():
        tracker_publisher.append_ledger(c.state, {
            "journal": tracker_publisher.LANE_MOVE, "init": init, "outcome": "failed", "writer": "lane",
            "kind": "lane.review", "ticket": key, "move": "review", "transitions": names, "error": why[:500]})


def review_move(c, key: str, when: str, last: bool = False) -> None:
    """The story's review move, at the moment `when` names. With the tracker publisher and that reviewWhen, the
    command makes it through the ledger; otherwise it prints it for the lane, as the brief did. A move the tracker
    refuses writes no line and doesn't fail the command: running the command again, or `handoff`, retries it."""
    conf = tracker_conf(c)
    names = conf["transitions"].get("review") or []
    configured = conf["transitions"].get("reviewWhen")
    if not names or conf["problems"]:
        return
    if configured is None:
        # Opt-in: with no reviewWhen nothing moves by itself, and open-pr prints the move as the brief did.
        if when == "pr-open":
            print(f"Tracker move (your story {key}): {said_moves(names)}, with your tracker tools.")
        return
    if configured != when:
        return
    if conf["mode"] != "publisher":
        print(f"Tracker move (your story {key}): {said_moves(names)}, with your tracker tools.")
        return
    if review_move_made(c, key, names):
        print(f"{key}'s review move is already made.")
        return
    doc = load_state()
    if start_owed(c, doc, key):
        # A review move before the start is posted would leave the start skipped and the ticket behind.
        if last:
            append_owed(c, doc, key, names, "the story's start hadn't been posted yet")
            print(f"{key}'s review move waits for its start to be posted; the lead's Needs you shows it, to make by hand")
        else:
            print(f"{key}'s review move waits for its start to be posted; run this command again, or hand off, later")
        return
    with tracker_publisher.ledger_lock(c.state, wait=True):
        publisher = tracker_publisher.Publisher(doc, c.state, conf, tracker_publisher.Adapter(conf, c.root),
                                                c.delivery, c.flow_log, writer="lane")
        publisher.ticket = key
        entry = {"id": tracker_publisher.LANE_MOVE, "kind": "lane.review", "subject": key}
        notes: list[str] = []
        try:
            markers = publisher.adapter.markers(key)
            earlier = [m for m in markers if m.startswith(f"agent-delivery:{c.delivery}:")
                       and not m.startswith(f"agent-delivery:{c.delivery}:{publisher.init}:")
                       and m.endswith(f":transition:{names[-1]}")]
            if earlier:
                # Made under an earlier record of this delivery, before a --replace: not made again.
                publisher.write(entry, "skip", move="review", ticket=key, action=f"transition:{names[-1]}:made",
                                reason="made under an earlier record")
                print(f"{key}'s review move was made under an earlier record of this delivery.")
                return
            publisher.move(entry, key, "review", names, markers, notes)
        except (tracker_publisher.AdapterFailure, tracker_publisher.Transient, tracker_publisher.Stop) as failure:
            if not last:
                print(f"{key}'s review move wasn't made ({failure}); run this command again, or hand off, to retry it")
                return
            # The hand-off is the lane's last chance: the owed move is left in the ledger, where Needs you shows it.
            append_owed(c, doc, key, names, str(failure), locked=True)
            print(f"{key}'s review move wasn't made ({failure}); the lead's Needs you shows it, to make by hand")
            return
    print(f"Tracker move (your story {key}): " + (" ".join(notes) or "made."))


def handoff_and_post(c, key: str, lane: str, head: str, pr: str, rounds: int, post: str,
                     checks: list[str] | None = None, base_merge: dict | None = None,
                     evidence: list[dict] | None = None) -> str | None:
    """Hand off to the record and, with the tracker publisher, post the hand-off update under the entry it journals,
    holding the ledger's lock across the journal write, the post and its line. Returns what was posted, or None when the
    lane posts it (no publisher) or the publisher will (the call failed, so no line was written)."""
    conf = tracker_conf(c)
    lead_moves = ((conf["transitions"].get("lead") or {}).get("candidate.handed")) if not conf["problems"] else None
    handed = ["handoff", "--lane", lane, "--subject", key, "--head", head, "--change-request", pr, "--rounds",
              str(rounds), *(["--checks", ",".join(checks)] if checks else []),
              *(["--base-merge", json.dumps(base_merge)] if base_merge else []),
              *[part for entry in evidence or [] for part in ("--evidence", json.dumps(entry, sort_keys=True))]]
    if conf["mode"] != "publisher" or conf["problems"] or lead_moves:
        # With lead moves for a hand-off, the publisher makes them and posts the update with what they did.
        state_tool(*handed)
        return ("Tracker post: the tracker publisher posts the hand-off update, with its moves." if lead_moves
                and conf["mode"] == "publisher" else None)
    with tracker_publisher.ledger_lock(c.state, wait=True):
        state_tool(*handed)
        doc = load_state()
        journal = sorted(doc["journal"], key=lambda e: e["id"])
        entry = [e for e in journal if e["kind"] == "candidate.handed" and e.get("subject") == key][-1]
        init = tracker_publisher.init_id(journal)
        stamp = tracker_publisher.marker(c.delivery, init, tracker_publisher.entry_ref(entry), "comment")
        adapter = tracker_publisher.Adapter(conf, c.root)
        try:
            found = stamp in adapter.markers(key)
            if not found:
                limit = adapter.status(key).get("commentLimit")
                text = tracker_publisher.body_of(entry, "Handed off and queued", [post[0].upper() + post[1:]], c.delivery,
                                                 limit if isinstance(limit, int) else None)
                with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False, encoding="utf-8") as body:
                    body.write(text)
                try:
                    adapter.call("comment", "--ticket", key, "--marker", stamp, "--body-file", body.name)
                finally:
                    os.unlink(body.name)
        except (tracker_publisher.AdapterFailure, tracker_publisher.Transient) as failure:
            return (f"Tracker post: not posted ({failure}); the tracker publisher posts it on its next run. "
                    "The hand-off stands.")
        tracker_publisher.append_ledger(c.state, {"journal": entry["id"], "init": init, "outcome": "comment",
                                                  "writer": "lane", "kind": entry["kind"], "ticket": key,
                                                  "action": "comment", **({"found": True} if found else {})})
    return f"Tracker post: posted the hand-off update on {key}."


def last_assignment(journal: list[dict], key: str) -> dict | None:
    return next((e for e in reversed(journal) if e["kind"] == "lane.assigned" and e.get("subject") == key), None)


def recorded_starts(c, key: str, journal: list[dict]) -> list[dict]:
    """The starts recorded since the story's last assignment. On a shared record a start names the assignment it
    follows, by its journal id, so no clocks are compared."""
    assigned = last_assignment(journal, key)
    since = assigned["at"] if assigned else None
    shared = bool(assigned and assigned.get("origin"))
    return [s for s in tracker_publisher.read_flow(c.flow_log, c.delivery, tracker_publisher.LANE_STARTS)
            if s.get("subject") == key and (s.get("assigned") == assigned["id"] if shared
                                            else since is None or s.get("at", "") >= since)]


def record_start(c, key: str, lane: str, journal: list[dict]) -> dict:
    """The story's start, naming on a shared record the assignment it follows."""
    assigned = last_assignment(journal, key)
    return tracker_publisher.record_lane_start(c.flow_log, c.delivery, key, lane,
                                               assigned["id"] if assigned and assigned.get("origin") else None,
                                               carried_stamp(c, tracker_publisher.LANE_STARTS, key))


def lane_start(args) -> None:
    """Begin a story: its checkout from the base, the prepare step, the lane's focus, and the story's start in the flow
    log, which the tracker publisher's start move and update wait for. Run again, it changes nothing."""
    c = cfg()
    key = c.require(args.key)
    lane = c.lane_of(key)
    base = args.base or c.base_branch
    # Without a binding base, the delivery's own base is the one it serves.
    served = c.binding if c.binding_base else {"base": {"ref": c.base_branch}}
    if not serves(served, base):
        raise unserved(served, base)
    # Before the checkout or the start: the lane's gates and sensors run the node and python3 first on its PATH.
    node = node_problem(c.release)
    problems = [node[1]] if node else []
    problems += python_problems()
    if problems:
        raise Stop(f"lane-start refuses {key} until each of these is fixed:" + "".join(f"\n  - {p}" for p in problems))
    path, branch = c.lane_checkout(key), c.branch(key)
    did = []
    if path.exists():
        current = git("rev-parse", "--abbrev-ref", "HEAD", cwd=path, check=False)
        if current != branch:
            raise Stop(f"{path} exists on {current or 'no branch'}, not {branch}: move it aside, or start from it by hand")
        recorded = (load_json(lane_base_file(path)) or {}).get("base")
        if recorded and recorded != base:
            raise Stop(f"{path} was started on {recorded}, not {base}: finish it on {recorded}, or move it aside")
    else:
        git("fetch", "-q", c.remote, base, cwd=c.main)
        if run(["git", "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}"], cwd=c.main, check=False).returncode == 0:
            if run(["git", "merge-base", branch, f"{c.remote}/{base}"], cwd=c.main, check=False).returncode != 0:
                raise Stop(f"the branch {branch} shares no history with {c.remote}/{base}: delete it, or start it by hand")
            git("worktree", "add", "-q", str(path), branch, cwd=c.main)
            did.append(f"made {path} on the existing branch {branch}")
        else:
            git("worktree", "add", "-q", "--no-track", "-b", branch, str(path), f"{c.remote}/{base}", cwd=c.main)
            did.append(f"made {path} on {branch} from {c.remote}/{base}")
        record_lane_base(path, base)
    prepared = lane_base_file(path).with_name("prepared")
    if not prepared.exists():
        # Marked only once every prepare step passed, so a failed one runs again on the next lane-start.
        for argv in prepare_commands():
            run(argv, cwd=path)
        prepared.write_text(now() + "\n")
        did.append("prepared it")
    starts = recorded_starts(c, key, load_state()["journal"])
    # On every run, so a start recorded without its stage move gets it on the next one; a story past planned is left as
    # it is. It comes first, so the stage is moved before the start is recorded.
    if mark_building(c, key, lane):
        did.append(f"{lane} started it: now building")
    # On every run, so a session that takes the story over is seated as its lane too.
    record_session(c, "lane", key)
    if not starts:
        # The focus is set only with the start, so running it again never resets what the lane has said since.
        state_tool("focus", "--lane", lane, "--text", f"{key}: started", "--state", "working", "--waiting-on", "")
        did.append(f"set {lane}'s focus")
        record_start(c, key, lane, load_state()["journal"])
        did.append("recorded the start")
        conf = tracker_conf(c)
        # Made by hand, with the lane's own tracker tools: the publisher makes it in publisher mode.
        if conf["mode"] == "manual":
            moves = conf["transitions"].get("start") or []
            update = f"Started ({lane}): {c.label(key)}: {c.stories[key]['title']}"
            if moves:
                print(f"Tracker move (your story {key}): {said_moves(moves)}, with your tracker tools.")
            print(f"Tracker post (your story {key}): {update}")
    print(f"{key}: " + ("; ".join(did) if did else "already started; nothing to do") + f". Work in {path}.")


def mark_building(c, key: str, lane: str) -> bool:
    """Move a story still planned to building in the record, as its lane: the one stage a lane writes. A story already
    past planned is left as it is. Returns whether it moved."""
    def compute(doc: dict):
        entry = next((e for e in doc["state"].get("planned", []) if e["subject"] == key), None)
        if entry is None or entry.get("stage") != "planned" or entry.get("lane") != lane:
            return None
        return ["--lane", lane, "--element", f"planned[subject={key}]", "--patch", json.dumps({"stage": "building"})]
    return patch_from(compute, f"{key}'s start", writer="lane") is not None


def push(args) -> None:
    c = cfg()
    key = c.require(args.key)
    require_authority("push")
    head = clean_head()
    branch = c.branch(key)
    current = git("rev-parse", "--abbrev-ref", "HEAD")
    if current != branch:
        raise Stop(f"this checkout is on {current}, not {branch}: push from the story's own checkout")
    done = run(["git", "push", "-u", c.remote, f"HEAD:refs/heads/{branch}"], check=False)  # never forced
    if done.returncode != 0:
        raise Stop(f"the push was refused (it is never forced): {done.stderr.strip()[-400:]}")
    print(f"pushed {branch} at {head[:10]}")


def open_pr(args) -> None:
    c = cfg()
    key = c.require(args.key)
    require_authority("draftPullRequests")
    if not args.title.startswith(f"{key}: "):
        raise Stop(f"the title must start with '{key}: '")
    head = clean_head()
    pushed(key, head)
    body = Path(args.body_file).read_text()
    issue = c.issue_url.format(key=key)
    if issue not in body:
        body += f"\n\nTracker: {issue}\n"
    found = forge("find", "--source", c.branch(key))
    if found.get("url"):
        print(found["url"])
    else:
        with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False) as handle:
            handle.write(body)
        try:
            print(forge("open", "--source", c.branch(key), "--destination", c.base_branch, "--title", args.title,
                        "--body-file", handle.name)["url"])
        finally:
            os.unlink(handle.name)
    review_move(c, key, "pr-open")
    if tracker_conf(c)["transitions"].get("reviewWhen") == "gates-passed":
        _, problems = gates_summary(key, repo(), head)
        if problems:
            print(f"{key}'s review move waits for the gates to pass at {head[:10]}: run the gates, then open-pr again")
        else:
            review_move(c, key, "gates-passed")


def parse_blocked(items: list[str]) -> dict[str, str]:
    blocked = {}
    for item in items or []:
        label, _, reason = item.partition("=")
        if not label.strip() or not reason.strip():
            raise Stop(f"--blocked needs LABEL=REASON, got {item!r}")
        blocked[label.strip()] = reason.strip()
    return blocked


LEGACY_REVIEWER = "review"  # the legacy {author, waitSeconds}'s one reviewer, and an old-shape record's
REVIEWER_MEMBERS = ("id", "account", "author", "signature", "required", "gate", "report")
REVIEW_GATES = ("approval", "verdict")
WAIT_SECONDS, SETTLE_SECONDS = 1800, 300
RECORD_SCHEMA = "pr-review/2"
# A wait's retry of a transient adapter failure: the first sleep, and the most any one sleeps.
BACKOFF_FIRST, BACKOFF_MOST = 5, 60


class Clock:
    """The time, the sleeps and the poll interval of every PR-review wait, read through one place. RUN_DELIVERY_CLOCK
    names a JSON file, {"now": seconds since the epoch, "poll"?: seconds}, that stands in for them: each sleep moves
    its `now` on and is added to its `sleeps`, so a wait runs through without waiting."""

    def __init__(self, path: str | None):
        self.path = Path(path) if path else None

    def read(self) -> dict:
        return json.loads(self.path.read_text())

    def time(self) -> float:
        return float(self.read()["now"]) if self.path else time.time()

    def sleep(self, seconds: float) -> None:
        if not self.path:
            time.sleep(seconds)
            return
        doc = self.read()
        doc["now"] = float(doc["now"]) + seconds
        doc.setdefault("sleeps", []).append(seconds)
        self.path.write_text(json.dumps(doc))

    def poll(self, seconds: float) -> float:
        return float(self.read().get("poll", seconds)) if self.path else seconds


def clock() -> Clock:
    return Clock(os.environ.get("RUN_DELIVERY_CLOCK"))


def pr_review_config() -> dict | None:
    """review.pr, read one way by every reader: None when the repository declares no PR review.

    The legacy {author, waitSeconds} is read as it always was (`author` required, other members ignored, waitSeconds
    read with int()), as one required reviewer, `review`, with no settle. {waitSeconds?, settleSeconds?, reviewers}
    is the list: each reviewer {id, account?, author?, signature?, required?, gate?, report?}. Anything else in the
    list's shape is refused, naming the reviewer and the member."""
    c = cfg()
    conf = (c.flow_raw.get("review") or {}).get("pr")
    if not conf:
        return None
    if "reviewers" not in conf:
        if not conf.get("author"):
            raise Stop(f"{c.name} review.pr needs `author`: the name the pipeline's review comment is posted as")
        return {"legacy": True, "raw": conf, "settleSeconds": None,
                "reviewers": [{"id": LEGACY_REVIEWER, "author": conf["author"], "required": True}]}
    where = f"{c.name} review.pr"
    unknown = sorted(set(conf) - {"waitSeconds", "settleSeconds", "reviewers"})
    if unknown:
        raise Stop(f"{where}: `{unknown[0]}` is not a member of review.pr (it takes waitSeconds, settleSeconds and "
                   "reviewers)")
    for member, default in (("waitSeconds", WAIT_SECONDS), ("settleSeconds", SETTLE_SECONDS)):
        value = conf.get(member, default)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise Stop(f"{where}: `{member}` must be a whole number of seconds, 0 or more, not {value!r}")
    listed = conf["reviewers"]
    if not isinstance(listed, list) or not listed:
        raise Stop(f"{where}: `reviewers` must be a list of one reviewer or more, not {listed!r}")
    reviewers: list[dict] = []
    for n, entry in enumerate(listed, 1):
        rid = entry.get("id") if isinstance(entry, dict) else None
        name = f"reviewer {rid!r}" if isinstance(rid, str) and rid else f"reviewer {n}"

        def bad(member: str, why: str) -> Stop:
            return Stop(f"{where}, {name}: `{member}` {why}")
        if not isinstance(entry, dict):
            raise Stop(f"{where}, {name}: a reviewer is an object, {{id, account?, author?, ...}}, not {entry!r}")
        extra = sorted(set(entry) - set(REVIEWER_MEMBERS))
        if extra:
            raise bad(extra[0], f"is not a reviewer member (a reviewer takes {', '.join(REVIEWER_MEMBERS)})")
        if not isinstance(rid, str) or not re.fullmatch(r"[a-z][a-z0-9-]*", rid):
            raise bad("id", "must be lowercase letters, digits and hyphens, starting with a letter")
        if any(r["id"] == rid for r in reviewers):
            raise bad("id", "is another reviewer's too: each reviewer's id is its own")
        for member in ("account", "author", "signature", "report"):
            if member in entry and not (isinstance(entry[member], str) and entry[member]):
                raise bad(member, "must be a non-empty string")
        if not entry.get("account") and not entry.get("author"):
            raise bad("account", "or `author` is needed: the forge account id, or the display name, it posts as")
        if "required" in entry and not isinstance(entry["required"], bool):
            raise bad("required", f"must be true or false, not {entry['required']!r}")
        if "gate" in entry and entry["gate"] not in REVIEW_GATES:
            raise bad("gate", f"must be \"approval\" or \"verdict\", not {entry['gate']!r}")
        if entry.get("gate") == "approval" and not entry.get("account"):
            raise bad("account", "is needed for gate \"approval\": an approval is matched by account, never by name")
        reviewers.append({**entry, "required": entry.get("required", True)})
    return {"legacy": False, "raw": conf, "waitSeconds": conf.get("waitSeconds", WAIT_SECONDS),
            "settleSeconds": conf.get("settleSeconds", SETTLE_SECONDS), "reviewers": reviewers}


def wait_seconds(conf: dict) -> int:
    return int(conf["raw"].get("waitSeconds", WAIT_SECONDS)) if conf["legacy"] else conf["waitSeconds"]


def instant(stamp: object) -> float:
    """An ISO 8601 time from the forge as seconds since the epoch; one without a zone is UTC."""
    try:
        parsed = datetime.datetime.fromisoformat(str(stamp).replace("Z", "+00:00"))
    except ValueError:
        raise Stop(f"the forge adapter's `reviews` gave a time that isn't ISO 8601: {stamp!r}") from None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=datetime.timezone.utc)
    return parsed.timestamp()


def reviewer_matches(reviewer: dict, found: dict, legacy: bool) -> bool:
    """By account when the reviewer names one, else by author; and by signature, as plain text, when set.
    The list never matches an empty body, which a bodiless approval has; the legacy shape matches as it always did."""
    body = found.get("body") or ""
    if not legacy and not body:
        return False
    if reviewer.get("account"):
        if found.get("account") != reviewer["account"]:
            return False
    elif found.get("author") != reviewer.get("author"):
        return False
    return reviewer.get("signature", "") in body


def missing_members(found: dict, conf: dict) -> list[str]:
    """What the list's reviewers need of `reviews` that the adapter didn't return. Present but empty is
    not missing."""
    needed = []
    if any(r.get("account") for r in conf["reviewers"]) and any("account" not in r for r in found.get("reviews", [])):
        needed.append("`account` on each review comment (a reviewer is matched by account)")
    approving = [r for r in conf["reviewers"] if r.get("gate") == "approval" and not r.get("report")]  # a report stands in
    if approving and "approvals" not in found:
        needed.append("`approvals` (a reviewer has gate \"approval\")")
    if any(r.get("report") for r in conf["reviewers"]) and "reports" not in found:
        needed.append("`reports` (a reviewer has `report`)")
    return needed


def classify_reviews(found: dict, conf: dict, now: float) -> dict:
    """One read of `reviews` at the head, classified: {status, checks, reviewers: {id: {state, review}}}.

    status is `failed` when a check at the head failed, `pending` while a check or a reviewer is, and `done` otherwise.
    A reviewer is `current` once every check passed and its latest matching review is no earlier than the latest
    check. In the list, once the settle has passed, a reviewer with none is `absent` when optional and `silent` when
    required: the settle starts when the last check finished (its doneAt, else its at) and runs settleSeconds by `now`,
    its end belonging to it. The legacy shape has no settle: its reviewer is pending until current."""
    checks = found.get("checks", [])
    out = {"checks": checks, "reviewers": {}}
    if any(ch["state"] == "failed" for ch in checks):
        out["status"] = "failed"
        return out
    passed = bool(checks) and all(ch["state"] == "passed" for ch in checks)
    if conf["legacy"]:
        started = max((ch["at"] for ch in checks), default=None)
        reviewer = conf["reviewers"][0]
        mine = [r for r in found.get("reviews", []) if r["author"] == reviewer["author"]]
        review = max(mine, key=lambda r: r["at"], default=None)
        current = passed and review is not None and review["at"] >= started
        out["reviewers"][reviewer["id"]] = {"state": "current" if current else "pending", "review": review}
    else:
        missing = missing_members(found, conf)
        if missing:
            raise Stop("the forge adapter's `reviews` returned no " + "; no ".join(missing) + ": use an adapter that "
                       "returns it, or configure review.pr without it")
        # Only once every check passed, when each carries its time: a pending one may have none yet.
        latest = max((instant(ch["at"]) for ch in checks), default=None) if passed else None
        settled = passed and now > max(instant(ch.get("doneAt") or ch["at"]) for ch in checks) + conf["settleSeconds"]
        for reviewer in conf["reviewers"]:
            mine = [r for r in found.get("reviews", []) if reviewer_matches(reviewer, r, False)]
            if reviewer.get("report"):  # read from its Code Insights report at the head, not from timestamps
                reading = pr_review_gates.report_reading(reviewer, mine, found, checks, settled, instant)
                if "refusal" in reading:
                    raise Stop(reading["refusal"])
                out["reviewers"][reviewer["id"]] = reading
                continue
            review = max(mine, key=lambda r: instant(r["at"]), default=None)
            if passed and review is not None and instant(review["at"]) >= latest:
                state = "current"
            elif settled:
                state = "silent" if reviewer["required"] else "absent"
            else:
                state = "pending"
            out["reviewers"][reviewer["id"]] = {"state": state, "review": review}
    waiting = not passed or any(r["state"] == "pending" for r in out["reviewers"].values())
    out["status"] = "pending" if waiting and not pr_review_gates.stops_at_once(out["reviewers"]) else "done"
    return out


def silent_refusal(read: dict, head: str, reviewers: list[dict]) -> Silent | None:
    """The refusal for required reviewers silent after the settle, or None. Its line starts `silent reviewer`. A gate
    another current review leaves unmet is a refusal of its own, so it is named here too rather than hidden."""
    silent = [rid for rid, r in read["reviewers"].items() if r["state"] == "silent"]
    if not silent:
        return None
    states = ", ".join(f"{rid} {r['state']}" for rid, r in read["reviewers"].items())
    unmet = pr_review_gates.live_refusals(reviewers, read["reviewers"], head)
    said = (pr_review_gates.silent_reasons(read)  # a report's own reason, such as FAILED, when one has it
            or f"the pipeline is green at {head[:10]} but {', '.join(silent)} posted nothing since")
    return Silent(f"silent reviewer: {said}; re-run its step or ask the lead (reviewers: {states})"
                  + "".join(f"; and {refusal}" for refusal in unmet))


def retried(call: Callable[[], dict], deadline: float) -> dict:
    """A forge call inside a wait's loop: a transient failure (exit 75) is tried again after 5 seconds, doubling to at
    most 60, never sleeping past the deadline. At the deadline the refusal carries the last transient message."""
    clk, delay = clock(), BACKOFF_FIRST
    while True:
        try:
            return call()
        except Transient as error:
            left = deadline - clk.time()
            if left <= 0:
                raise Stop(f"{error} (a transient failure, retried until the wait's deadline)") from None
            clk.sleep(min(delay, left))
            delay = min(delay * 2, BACKOFF_MOST)


def read_pr_reviews(url: str, head: str, conf: dict, deadline: float | None) -> dict:
    """`reviews` at the head, classified now. With a deadline, inside a wait, a transient failure is retried."""
    def ask() -> dict:
        return forge("reviews", "--url", url, "--head", head)
    found = retried(ask, deadline) if deadline is not None else ask()
    read = classify_reviews(found, conf, clock().time())
    refused = pr_review_gates.attach(read, found, conf, head)  # each current review's gate, beside it
    if refused:
        raise Stop(refused)
    return read


def pr_review_state(url: str, head: str, conf: dict) -> tuple[str, dict | None, list[dict]]:
    """The legacy reviewer's (status, review, the head's checks), status current, pending or failed: one read."""
    read = read_pr_reviews(url, head, conf, None)
    if read["status"] == "failed":
        return "failed", None, read["checks"]
    one = read["reviewers"][LEGACY_REVIEWER]
    return ("current" if read["status"] == "done" else "pending"), one["review"], read["checks"]


def check_states(checks: list[dict]) -> str:
    return ", ".join(f"{ch['name']} {ch['state']}" for ch in checks) or "no checks"


def record_reviewers(recorded: dict) -> dict[str, dict]:
    """A saved pr-review.json's reviewers by id: the list's own, or an old-shape record as reviewer `review`."""
    if recorded.get("schema") == RECORD_SCHEMA:
        return recorded.get("reviewers") or {}
    if "author" in recorded:
        return {LEGACY_REVIEWER: {"state": "current", "required": True,
                                  **{k: recorded[k] for k in ("author", "at", "body", "triage") if k in recorded}}}
    return {}


def triage_by_reviewer(given: list[str], entries: dict[str, dict]) -> tuple[dict[str, str], list[str]]:
    """Each --pr-review-triage, ID=TEXT for a reviewer or a bare TEXT when exactly one review is current,
    matched to the current reviews. Returns ({id: text}, problems): every current review needs one; an absent or
    unknown reviewer takes none."""
    current = [rid for rid, e in entries.items() if e.get("state") == "current"]
    named: dict[str, str] = {}
    bare: list[str] = []
    problems: list[str] = []
    for item in given:
        rid, sep, text = item.partition("=")
        if sep and re.fullmatch(r"[a-z][a-z0-9-]*", rid.strip()) and text.strip():
            rid = rid.strip()
            if rid not in entries:
                problems.append(f"--pr-review-triage names {rid}, which is no reviewer of the PR review recorded "
                                f"(they are {', '.join(entries) or 'none'})")
            elif entries[rid].get("state") != "current":
                state = entries[rid].get("state")
                problems.append(f"--pr-review-triage names {rid}, which was {state}: {'an' if state == 'absent' else 'a'} "
                                f"{state} reviewer takes no triage")
            elif rid in named:
                problems.append(f"--pr-review-triage names {rid} twice")
            else:
                named[rid] = text.strip()
        elif item.strip():
            bare.append(item.strip())
    if bare:
        if len(bare) > 1 or len(current) != 1 or named:
            problems.append(f"a bare --pr-review-triage TEXT is accepted only alone, with exactly one current review; "
                            f"{len(current)} are current ({', '.join(current) or 'none'}): give each "
                            "--pr-review-triage ID=TEXT")
        else:
            named[current[0]] = bare[0]
    problems += [f"say how {rid}'s review was handled: --pr-review-triage {rid}=TEXT"
                 for rid in current if rid not in named]
    return named, problems


def pr_review_text() -> str:
    conf = pr_review_config()
    if not conf:
        return ""
    if conf["legacy"]:
        return (f"   **The PR review.** The forge's pipeline reviews every PR and posts as \"{conf['raw']['author']}\". "
                "Open the draft PR as soon as the gates first pass, so that review runs alongside your lens rounds; "
                f"each push re-runs it. Before you hand off, at your final head: `{flow_command()} pr-review <key> "
                "--wait` waits for the pipeline and its review, saves it and prints it. Triage its findings as you "
                "would a lens's: fix anything that should be fixed in the lane (then the gates, a lens round and this "
                "review again at the new head), and fix or defer the rest, deferring only with a follow-up. Pass "
                "`--pr-review-triage \"<what you fixed, deferred and why>\"` to `handoff`. The lead's acceptance "
                "re-checks that the review is current at your head.\n")
    named = "; ".join(f"`{r['id']}` ({'required' if r['required'] else 'optional'})" for r in conf["reviewers"])
    return ("   **The PR reviews.** The forge's pipeline reviews every PR with several reviewers, each under its id: "
            f"{named}. Open the draft PR as soon as the gates first pass, so they run alongside your lens rounds; each "
            f"push re-runs them. Before you hand off, at your final head: `{flow_command()} pr-review <key> --wait` "
            "waits for the pipeline and every reviewer, saves them and prints each under its id. A required "
            "reviewer is waited for; an optional one that posts nothing within the settle after the pipeline goes "
            "green is recorded absent. Triage each current review's findings as you would a lens's: fix anything "
            "that should be fixed in the lane (then the gates, a lens round and these reviews again at the new head), "
            "and fix or defer the rest, deferring only with a follow-up. Pass one `--pr-review-triage <id>=\"<what "
            "you fixed, deferred and why>\"` to `handoff` for each current review (a bare text only when exactly one "
            "is current). The lead's acceptance re-checks that each is still current and unchanged at your head, and "
            "sends you back to read an optional review recorded absent that has since arrived. If `pr-review` "
            "exits 3 with a `silent reviewer` line, a required reviewer posted nothing after the pipeline went green: "
            "don't run the wait again. Hand off blocked on it, `--blocked pr-review=\"<that line>\"`, still "
            "triaging each current review, and the lead decides.\n"
            + pr_review_gates.brief_text(conf["reviewers"]))


def pr_review_record(key: str, head: str, url: str, conf: dict, read: dict) -> dict[str, dict]:
    """Write the list's pr-review.json from a classified read: each reviewer current (its review, and its gate),
    absent, or silent, or pending when an errored report stopped the read before it was in. Returns its entries by
    id."""
    entries: dict[str, dict] = {}
    for reviewer in conf["reviewers"]:
        state = read["reviewers"][reviewer["id"]]
        entry: dict = {"state": state["state"], "required": reviewer["required"]}
        if state["state"] == "current":
            review = state["review"]
            entry.update(author=review["author"], **({"account": review["account"]} if "account" in review else {}),
                         at=review["at"], body=review["body"])
            if state.get("gate"):
                entry["gate"] = state["gate"]
        if pr_review_gates.recorded_report(state):
            entry["report"] = pr_review_gates.recorded_report(state)
        entries[reviewer["id"]] = entry
    record = {"schema": RECORD_SCHEMA, "head": head, "url": url, "reviewers": entries}
    (review_dir(key) / "pr-review.json").write_text(json.dumps(record, indent=2))
    return entries


def pr_review(args) -> None:
    c = cfg()
    key = c.require(args.key)
    conf = pr_review_config()
    if not conf:
        raise Stop(f"this repository declares no PR review ({c.name} review.pr)")
    if not forge_answers("reviews"):
        raise Stop(f"PR reviews are unsupported by this forge adapter ({c.forge.get('adapter')} has no `reviews` "
                   f"command): remove review.pr from {c.name}, or use an adapter that answers `reviews`")
    head = clean_head()
    pushed(key, head)
    url = forge("find", "--source", c.branch(key)).get("url")
    if not url:
        raise Stop(f"no open PR for {c.branch(key)}: open the draft PR first")
    clk = clock()
    deadline = clk.time() + (wait_seconds(conf) if args.wait else 0)
    while True:
        read = read_pr_reviews(url, head, conf, deadline if args.wait else None)
        left = deadline - clk.time()
        if read["status"] != "pending" or left <= 0:
            break
        clk.sleep(min(clk.poll(30), left))
    checks = read["checks"]
    if read["status"] == "failed":
        raise Stop(f"the pipeline failed at {head[:10]}: " + ", ".join(f"{ch['name']} {ch['state']}" for ch in checks))
    if conf["legacy"]:
        review = read["reviewers"][LEGACY_REVIEWER]["review"]
        author = conf["raw"]["author"]
        if read["status"] == "pending":
            raise Stop(f"no {author} review after the pipeline for {head[:10]} yet"
                       + ("" if args.wait else "; run with --wait") + ": " + (", ".join(f"{ch['name']} {ch['state']}" for ch in checks) or "no checks"))
        record = {"head": head, "url": url, "author": review["author"], "at": review["at"], "body": review["body"]}
        (review_dir(key) / "pr-review.json").write_text(json.dumps(record, indent=2))
        review_move(c, key, "pipeline-green")
        print(f"{author} review of {head[:10]} ({review['at']}), saved for the hand-off:\n")
        print(review["body"])
        print("\nTriage every finding like a lens finding: fix what blocks in the lane (then gates, a lens round and this "
              "review again at the new head), and fix or defer the rest. Hand off with --pr-review-triage saying which.")
        return
    silent = silent_refusal(read, head, conf["reviewers"])
    if silent:
        # Recorded first: a hand-off blocked on the silent reviewer still triages every current review.
        pr_review_record(key, head, url, conf, read)
        raise silent
    if read["status"] == "pending":
        waiting = [rid for rid, r in read["reviewers"].items() if r["state"] == "pending"]
        said = (f"no current review from {', '.join(waiting)} after the pipeline for {head[:10]} yet" if waiting
                else f"the pipeline for {head[:10]} hasn't finished yet")
        raise Stop(said + ("" if args.wait else "; run with --wait") + ": " + check_states(checks))
    entries = pr_review_record(key, head, url, conf, read)
    # Every required reviewer is current here (none is pending), so the pipeline's review move is due.
    review_move(c, key, "pipeline-green")
    print(f"PR reviews of {head[:10]}, saved for the hand-off:")
    for rid, entry in entries.items():
        kind = "required" if entry["required"] else "optional"
        if entry["state"] == "current":
            gate_line = f"\n{pr_review_gates.shown(entry['gate'])}" if entry.get("gate") else ""
            print(f"\n## {rid} ({kind}): {entry['author']} at {entry['at']}{gate_line}\n\n{entry['body']}")
        else:
            print(f"\n## {rid} ({kind}): absent, no review within {conf['settleSeconds']}s after the pipeline went "
                  "green")
    print("\nTriage every finding like a lens finding: fix what blocks in the lane (then gates, a lens round and these "
          "reviews again at the new head), and fix or defer the rest. Hand off with one --pr-review-triage ID=TEXT for "
          "each current review saying which.")


def pr_review_current(args) -> None:
    """The merge queue's reviewGate: exit 0 only when review.pr's review is current and passing at --head.

    It runs in the queue's checkout of the base, where no delivery is named, so it reads only the repository's own
    configuration. Every refusal is one line on stderr, an adapter's own included, for the queue's log."""
    try:
        review_gate(args)
    except Stop as error:
        raise type(error)(" ".join(str(error).split())) from None


def review_gate(args) -> None:
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    conf = pr_review_config()
    if not conf:
        raise Stop(f"this repository declares no PR review ({c.name} review.pr), so there is no review to gate on")
    if not forge_answers("reviews"):
        raise Stop(f"PR reviews are unsupported by this forge adapter ({c.forge.get('adapter')} has no `reviews` "
                   f"command): remove review.pr from {c.name}, or use an adapter that answers `reviews`")
    url = forge("find", "--source", args.branch).get("url")
    if not url:
        raise Stop(f"no open PR for {args.branch}")
    wait = wait_seconds(conf) if args.wait else 0
    clk = clock()
    deadline = clk.time() + wait
    within = deadline if args.wait else None
    while True:
        # Read each time: a forge can show the PR at its old head for a while after the queue pushes the synced one.
        def get() -> dict:
            return forge("get", "--url", url)
        reported = (retried(get, within) if within is not None else get()).get("head")
        moved = not same_commit(reported, args.head)
        read = ({"status": "pending", "checks": [], "reviewers": {}} if moved
                else read_pr_reviews(url, args.head, conf, within))
        left = deadline - clk.time()
        if read["status"] != "pending" or left <= 0:
            break
        clk.sleep(min(clk.poll(10), left))  # a merge waits on it, so it looks again sooner than a lane's pr-review
    if moved:
        raise Stop(f"the PR is at {str(reported)[:10]}, not {args.head[:10]}: its review is of another head"
                   + (f" (waited {wait}s)" if args.wait else ""))
    states = check_states(read["checks"])
    if read["status"] == "failed":
        raise Stop(f"the pipeline failed at {args.head[:10]}: {states}")
    if conf["legacy"]:
        author = conf["raw"]["author"]
        if read["status"] == "pending":
            raise Stop(f"no current {author} review at {args.head[:10]}"
                       + (f" (waited {wait}s)" if args.wait else "") + f": {states}")
        review = read["reviewers"][LEGACY_REVIEWER]["review"]
        print(f"{author} review of {args.head[:10]} at {review['at']} is current: {states}")
        return
    # Only required reviewers block: an optional one absent, or not yet in, never does (triage is lead-accept's).
    silent = silent_refusal(read, args.head, conf["reviewers"])
    if silent:
        raise silent
    required = [r["id"] for r in conf["reviewers"] if r["required"]]
    missing = [rid for rid in required if read["reviewers"][rid]["state"] != "current"]
    if missing or any(ch["state"] != "passed" for ch in read["checks"]) or not read["checks"]:
        raise Stop(f"no current review at {args.head[:10]} from {', '.join(missing) or 'the pipeline'}"
                   + (f" (waited {wait}s)" if args.wait else "") + f": {states}")
    unmet = pr_review_gates.live_refusals(conf["reviewers"], read["reviewers"], args.head)
    if unmet:
        raise Stop("; ".join(unmet))
    said = [f"{rid} at {r['review']['at']}" if r["state"] == "current" else f"{rid} {r['state']}"
            for rid, r in read["reviewers"].items()]
    print(f"PR reviews of {args.head[:10]} are current ({', '.join(said)}): {states}")


def no_change_handoff(c, key: str, lane: str, args) -> None:
    """A story whose criteria already hold on the base: handed off with the lane's evidence and the base head it ran
    at, with no branch, change request or review round. It never enters the merge queue, and nothing is committed."""
    if args.pr or args.findings or args.blocked or args.pr_review_triage:
        raise Stop("--no-change hands off no change: it takes --evidence alone, no --pr, --findings, --blocked or "
                   "--pr-review-triage")
    if not args.evidence:
        raise Stop("--no-change needs --evidence: the tests or commands, run at the base head, that show the story's "
                   "criteria already hold (text, or @FILE)")
    evidence = args.evidence
    if evidence.startswith("@"):
        try:
            evidence = Path(evidence[1:]).read_text()
        except OSError as error:
            raise Stop(f"can't read the evidence file {evidence[1:]}: {error}")
    evidence = evidence.strip()
    head = clean_head()
    git("fetch", "-q", c.remote, c.base_branch)
    if not is_ancestor(head, c.base_ref):
        raise Stop(f"{head[:10]} isn't on {c.base_ref}: this checkout holds a change, so hand it off with --pr, or run "
                   f"the evidence on the base")
    state_tool("handoff", "--no-change", "--lane", lane, "--subject", key, "--base-head", head,
               "--evidence-text", evidence)
    post = f"hand-off: no change needed, its evidence run at {c.base_branch} {head[:10]}: {evidence}"
    print("\n".join([
        f"**Hand-off: {key}** ({c.label(key)}, {lane})",
        "- candidate: none, no change needed (it never enters the merge queue)",
        f"- base head the evidence ran at: `{head}`",
        f"- evidence: {evidence}",
        "- review rounds: none",
        "- lead inputs: none",
    ]))
    print(f"\nTracker post (your story): {post}")


def selection_of(c) -> dict:
    selection = (c.binding or {}).get("selection")
    return selection if isinstance(selection, dict) else {}


def lead_selects(c) -> bool:
    """Whether the binding lets the lead choose a candidate's checks: then one accepted without a choice checks on the
    fallback."""
    return selection_of(c).get("lead") is True


def catalogue_ids(c) -> list[str]:
    return [entry["id"] for entry in selection_of(c).get("catalogue") or []
            if isinstance(entry, dict) and isinstance(entry.get("id"), str)]


def catalogue_additions(c, ref: str, cwd: Path | None = None) -> dict[str, dict]:
    """The catalogue entries a candidate adds, by id, in its binding's order: each entry of selection.catalogue in
    the binding committed at `ref` whose id the base's catalogue lacks and no binding check of the base's uses. Read
    with git, never from a working tree, so an uncommitted edit adds nothing; a binding missing at `ref`, or one that
    doesn't parse, adds nothing either."""
    shown = run(["git", "show", f"{ref}:.agents/orchestration.json"], cwd=cwd, check=False)
    try:
        head = json.loads(shown.stdout) if shown.returncode == 0 else {}
    except ValueError:
        head = {}
    selection = head.get("selection") if isinstance(head, dict) else None
    entries = selection.get("catalogue") if isinstance(selection, dict) else None
    taken = set(catalogue_ids(c)) | {str(check.get("id")) for name in ("alwaysRun", "fallback")
                                     for check in (c.binding or {}).get(name) or [] if isinstance(check, dict)}
    added: dict[str, dict] = {}
    for entry in entries if isinstance(entries, list) else []:
        if isinstance(entry, dict) and isinstance(entry.get("id"), str) and entry["id"] not in taken:
            added.setdefault(entry["id"], entry)
    return added


def handed_additions(c, key: str, head: str, cwd: Path | None = None) -> dict[str, dict]:
    """The entries the handed head's committed binding adds to the catalogue, read in the checkout at `cwd` once the
    head's objects are there: the story's branch is fetched when they aren't."""
    if run(["git", "cat-file", "-e", f"{head}^{{commit}}"], cwd=cwd, check=False).returncode != 0:
        run(["git", "fetch", "-q", c.remote, c.branch(key)], cwd=cwd, check=False)
    return catalogue_additions(c, head, cwd=cwd)


def check_ids(c, text: str, what: str, added: dict[str, dict] | None = None) -> list[str]:
    """A comma-separated list of catalogue ids, each once, in the order given: the base's catalogue ids and the
    entries the candidate adds (`catalogue_additions`); refused naming any other, and both catalogues."""
    known, added = catalogue_ids(c), added or {}
    if not known and not added:
        raise Stop(f"{what} takes catalogue ids, and the binding declares no selection.catalogue")
    names = [name.strip() for name in text.split(",")]
    if not all(names) or len(set(names)) != len(names):
        raise Stop(f"{what} is a comma-separated list of catalogue ids, each once: {text!r}")
    unknown = [name for name in names if name not in known and name not in added]
    if unknown:
        raise Stop(f"{what} names checks in neither the base's catalogue nor the one at the candidate's head: "
                   f"{', '.join(unknown)} (the base's has {', '.join(known) or 'none'}; the head adds "
                   f"{', '.join(added) or 'none'})")
    return names


def checks_shown(names: list[str], added: dict[str, dict]) -> str:
    """The checks as a hand-off shows them: each id the candidate's own diff adds to the catalogue marked so."""
    return ", ".join(f"{name} (added by this story)" if name in added else name for name in names)


def checks_recorded(names: list[str], records: dict[str, dict]) -> str:
    """Each named check as the lane's records show it: recorded, with its head and result, or named only."""
    return "; ".join(f"{name} recorded at {records[name]['head'][:10]}: {records[name]['result']}" if name in records
                     else f"{name} named only" for name in names)


def provider_selects(c) -> bool:
    """Whether the binding names a provider: then a candidate with no lead selection runs the provider's answer, and
    the fallback only when it can't be had."""
    return (c.binding or {}).get("provider") is not None


def fallback_ids(c) -> list[str]:
    return [str(entry.get("id")) for entry in (c.binding or {}).get("fallback") or [] if isinstance(entry, dict)]


def proposed_checks(c, changed: list[str], named: list[str], added: dict[str, dict] | None = None) -> list[str]:
    """What lead-accept proposes when the lead chose nothing: the catalogue ids of the test modules the diff changes,
    then the checks the lane named at hand-off, each once, from the base's catalogue and the entries the candidate
    adds. select adds the guards and the readers' checks."""
    known = set(catalogue_ids(c)) | set(added or {})
    ids = [f"tests.{match.group(1)}" for path in changed
           for match in [re.fullmatch(r"tests/(test_\w+)\.py", path)] if match]
    ids += list(named)
    return [name for index, name in enumerate(ids) if name in known and name not in ids[:index]]


def pr_review_handoff(key: str, conf: dict, recorded: dict, given: list[str],
                      on_silent: bool) -> tuple[str | None, list[str]]:
    """The list's PR review at hand-off, from the record at the head: every configured reviewer recorded, and each
    current review triaged; a reviewer recorded silent only on a hand-off blocked on it. Writes each triage into
    `recorded`. Returns (the hand-off's PR review line, problems)."""
    entries = record_reviewers(recorded)
    unrecorded = [r["id"] for r in conf["reviewers"] if r["id"] not in entries]
    if unrecorded:
        return None, [f"the PR review recorded at {recorded['head'][:10]} has no entry for {', '.join(unrecorded)}: run "
                      f"{flow_command()} pr-review {key} --wait again"]
    silent = [rid for rid, e in entries.items() if e.get("state") == "silent"]
    triage, problems = triage_by_reviewer(given, entries)
    if silent and not on_silent:
        problems.append(f"{', '.join(silent)} was silent at {recorded['head'][:10]}: hand off blocked on it, "
                        f"--blocked {PR_REVIEW_BLOCK}=\"<pr-review's silent reviewer line>\", and the lead decides")
    if problems:
        return None, problems
    shown = []
    for rid, entry in entries.items():
        if entry.get("state") == "current":
            entry["triage"] = triage[rid]
            shown.append(f"{rid}: {entry.get('author')} at {str(entry.get('at'))[:16]}, triage: {triage[rid]}")
        else:
            shown.append(f"{rid}: {entry.get('state')}")
    if recorded.get("schema") != RECORD_SCHEMA and LEGACY_REVIEWER in triage:
        recorded["triage"] = triage[LEGACY_REVIEWER]  # an old-shape record keeps its own shape
    return "; ".join(shown), []


def lead_authorize_base_merge(args) -> None:
    c = cfg()
    require_lead_checkout(c)
    key = c.require(args.key)
    lane = c.lane_of(key)
    git("fetch", "-q", c.remote, c.base_branch)
    reviewed = git("rev-parse", "--verify", "--end-of-options", f"{args.reviewed}^{{commit}}")
    checkout = c.lane_checkout(key)
    if checkout.is_dir() and git("rev-parse", "HEAD", cwd=checkout) != reviewed:
        raise Stop(f"{key}'s checkout must still be at the reviewed head to authorize its base merge")
    bases = list(dict.fromkeys(git("rev-parse", "--verify", "--end-of-options", f"{ref}^{{commit}}")
                               for ref in args.base))
    for base in bases:
        if not is_ancestor(base, c.base_ref) or is_ancestor(base, reviewed):
            raise Stop(f"{base} must be on {c.base_ref} and outside the reviewed head's history")
    authorization = {"reviewed": reviewed, "baseCommits": bases}
    recorded = state_tool("journal", "--writer", "lead", "--kind", "base.merge.authorized", "--subject", key, "--lane", lane,
                          "--data", json.dumps(authorization))
    token = json.loads(recorded.stdout)["entry"]["data"]["token"]
    print(f"{key}: authorized base merges from {reviewed}. Run in the lane checkout, in this order:")
    print_base_merge(key, token, bases)


def print_base_merge(key: str, token: str, bases: list[str]) -> None:
    """The authorized merge commands, in order, then how to finish one that stops on a conflict."""
    for base in bases:
        print(shlex.join(["git", "merge", "--no-ff", "--no-log", *base_merge_message(key, token), base]))
    print("If a merge stops on a conflict, resolve it, `git add` the files, then finish it with:")
    print(shlex.join(["git", "commit", *base_merge_message(key, token)]))


def base_merge(args) -> None:
    """Decision 3: the lane authorizes its own merge of the base head, before hand-off, and gets its commands."""
    c = cfg()
    key = c.require(args.key)
    lane = c.lane_of(key)
    head = clean_head()
    git("fetch", "-q", c.remote, c.base_branch)
    doc = load_state()
    item = next((row for row in doc["state"]["queue"] if row["subject"] == key), None)
    if item is not None and item["stage"] != "stopped":
        raise Stop(f"{key} is {item['stage']}: the queue holds it, so a base merge is the lead's, through "
                   f"lead-authorize-base-merge")
    base = git("rev-parse", "--verify", "--end-of-options", f"{c.base_ref}^{{commit}}")
    if is_ancestor(base, head):
        raise Stop(f"{c.base_ref} at {base[:10]} is already in HEAD's history: there is nothing to merge")
    rounds = round_files(review_dir(key))
    last = json.loads(rounds[-1].read_text()) if rounds else None
    if last is None or last["outcome"] != "aligned":
        raise Stop(f"{key} has no aligned review round to carry across the merge: review first")
    reviewed = last["entries"][0]["binding"]["candidateRef"]
    if head != reviewed:
        try:
            verify_base_merge(c, key, lane, reviewed, head, doc)
        except Stop as error:
            raise Stop(f"HEAD {head[:10]} is neither the last aligned round's head {reviewed[:10]} nor a head carried "
                       f"from it ({error}): a merge from here would need a new review") from error
    recorded = state_tool("journal", "--writer", "lane", "--kind", "base.merge.authorized", "--subject", key,
                          "--lane", lane, "--data", json.dumps({"reviewed": reviewed, "baseCommits": [base], "by": "lane"}))
    token = json.loads(recorded.stdout)["entry"]["data"]["token"]
    print(f"{key}: you authorized your merge of {c.base_ref} at {base} from {reviewed}. Run in this checkout:")
    print_base_merge(key, token, [base])
    print("Then rerun the gates and any required in-app and PR checks at the new head, push, and hand off.")


def listing_reader(c, key: str, head: str):
    """The merge queue's runner for this binding, and the values its sync step gives a listing, so a listing read at
    hand-off, one that names `{head}` included, reads as the queue will read it."""
    _validator()
    import merge_queue  # noqa: E402  (the installed release's own queue)
    queue = merge_queue.Runner(main_checkout(), c.state, remote=c.remote, base=c.base_branch)
    # A listing read at hand-off has run under the binding's check timeout, or 600 seconds without one.
    queue.binding = {"checkTimeoutSeconds": 600, **c.binding}
    root = Path(c.binding.get("workRoot", ".orchestration/work"))
    queue.work_root = (root if root.is_absolute() else main_checkout() / root).resolve()
    values = queue.context(key, git("rev-parse", c.base_ref)).with_values(branch=c.branch(key), head=head)
    return merge_queue, queue, values


def check_base_conflict(c, key: str, head: str) -> None:
    """Decision 2: refuse a head that doesn't merge cleanly into the current base, outside the regenerable paths, so
    the lane merges it before the queue finds the conflict. A conflicted path with a listing is judged as the queue
    judges it: refused only when both sides changed what it lists. A clean move is left to the queue's sync."""
    base = git("rev-parse", "--verify", "--end-of-options", f"{c.base_ref}^{{commit}}")
    merged = run(["git", "merge-tree", "--write-tree", "--name-only", "--no-messages", "-z", base, head], check=False)
    if merged.returncode == 0:
        return
    if merged.returncode != 1:
        raise Stop(f"git merge-tree couldn't merge HEAD into {c.base_ref}: {(merged.stderr or merged.stdout).strip()[-400:]}")
    conflicts = sorted({path for path in merged.stdout.split("\0")[1:] if path})
    queue = _merge_queue()
    regenerable = (c.binding or {}).get("regenerable") or {}
    merge_hint = (f"merge the base before you hand off: run `{flow_command()} base-merge {key}`, then the merge it "
                  "prints, rerun the gates and checks, push, and hand off again")
    outside = [path for path in conflicts if not queue.matches_any(path, regenerable.get("paths") or [])]
    if outside:
        raise Stop(f"HEAD conflicts with {c.base_ref} at {base[:10]} in {', '.join(outside)}: {merge_hint}")
    listings = {entry["path"]: entry["argv"] for entry in regenerable.get("listings") or []}
    conflicted = [path for path in conflicts if path in listings]
    if not conflicted:
        return
    merge_base = git("merge-base", base, head)
    merge_queue, reader, values = listing_reader(c, key, head)
    for path in conflicted:
        try:
            before, at_base, after = (set(reader.listed_outputs(repo(), path, listings[path], commit, which, values))
                                      for commit, which in ((merge_base, "merge base"), (base, "base"), (head, "candidate")))
        except merge_queue.Stop as error:
            raise Stop(f"{error.detail}, so the queue would stop on it: merge the base before you hand off, with "
                       f"`{flow_command()} base-merge {key}`") from error
        if after != before and at_base != before:
            raise Stop(f"HEAD conflicts with {c.base_ref} at {base[:10]} in {path}, and both this story and the base "
                       f"changed the outputs it lists (this story {queue.listing_change(before, after)}; the base "
                       f"{queue.listing_change(before, at_base)}): {merge_hint}, keeping both sides' outputs")


BASE_MERGE_TRAILER = "Delivery-Base-Merge"


def base_merge_message(key: str, token: str) -> list[str]:
    """An authorized base merge's message, as `-m` arguments: the subject, then the authorization trailer."""
    return ["-m", f"{key}: Merge delivery base", "-m", f"{BASE_MERGE_TRAILER}: {token}"]


def base_merge_tokens(merge: str) -> list[str]:
    """The Delivery-Base-Merge trailer values in a merge's message. Lines starting with `#` are dropped first, whatever
    the comment character or cleanup the merge was committed with, so git's `# Conflicts:` lines never hide the
    trailer, then `git interpret-trailers --parse` reads the rest."""
    message = git("show", "-s", "--format=%B", merge)
    kept = "".join(line + "\n" for line in message.splitlines() if not line.startswith("#"))
    parsed = run(["git", "-c", "trailer.separators=:", "interpret-trailers", "--parse"], input=kept).stdout
    values = []
    for line in parsed.splitlines():
        name, separator, value = line.partition(":")
        if separator and name.strip().lower() == BASE_MERGE_TRAILER.lower():
            values.append(value.strip())
    return values


SEPARATOR_APPENDED = "(separator appended to the preceding line)"


def delta_entries(helper, root: Path, before: str, after: str) -> dict[bytes, tuple[bytes, bytes, bytes]]:
    """Each path the diff changes, with its (old mode, new mode, status). Blob ids are left out: a file both sides
    changed has a different post-image either way."""
    data = helper.git(root, "diff", "--raw", "-z", "--no-renames", "--no-abbrev",
                      "--ignore-submodules=none", before, after).stdout
    tokens = data.split(b"\0")[:-1]
    entries = {}
    for meta, path in zip(tokens[::2], tokens[1::2], strict=True):
        old_mode, new_mode, _, _, status = meta.lstrip(b":").split(b" ")
        entries[path] = (old_mode, new_mode, status)
    return entries


def delta_hunks(helper, root: Path, before: str, after: str, path: bytes) -> list[list[bytes]]:
    """A path's `--unified=0` hunks from before to after, each as its removed and added lines, without line numbers or
    context. Within a hunk, a removed line that comes back added with only a trailing `,` is the separator an append
    adds to the line before it: the pair, matched in order of appearance, reads as one marker."""
    data = helper.git(root, "-c", "core.quotePath=false", "diff", "--unified=0", "--no-renames", "--no-color",
                      "--no-ext-diff", "--no-textconv", "--binary", "--diff-algorithm=myers",
                      "--ignore-submodules=none", before, after, "--",
                      os.fsdecode(path)).stdout  # the helper reads pathspecs literally
    hunks: list[list[bytes]] = []
    body = False
    for line in data.split(b"\n"):
        if line.startswith(b"@@") or line == b"GIT binary patch":
            hunks.append([])
            body = True
            if line.startswith(b"@@"):
                continue
        if body and line:
            hunks[-1].append(line)
    return [separator_marked(hunk) for hunk in hunks]


def separator_marked(hunk: list) -> list:
    """One hunk's removed and added lines, bytes or str, with each removed line that comes back added with only a
    trailing `,` (before the carriage return, in a CRLF file) read as one marker: the separator an append adds to the line
    before it. Removed lines are paired in order of appearance, each with the first added line still unpaired."""
    if not hunk:
        return []
    same = (lambda text: text) if isinstance(hunk[0], str) else (lambda text: text.encode())
    minus, plus, comma, cr = same("-"), same("+"), same(","), same("\r")
    marked = list(hunk)
    taken: set[int] = set()
    for index, line in enumerate(hunk):
        if not line.startswith(minus):
            continue
        content = line[1:]
        separated = plus + (content[:-1] + comma + cr if content.endswith(cr) else content + comma)
        match = next((other for other, added in enumerate(hunk) if other not in taken and added == separated), None)
        if match is not None:
            taken.add(match)
            marked[index] = same(SEPARATOR_APPENDED)
    return [line for index, line in enumerate(marked) if index not in taken]


def shown_lines(lines: list[bytes], limit: int = 10) -> list[str]:
    text = [line.decode("utf-8", "replace") for line in lines[:limit]]
    if len(lines) > limit:
        text.append(f"... {len(lines) - limit} more")
    return text or ["(nothing)"]


def check_base_merge_delta(c, state: dict, lane: str, prior: str, head: str, old_base: str, new_base: str) -> None:
    """Decision 1's carry: the story's own change, `old_base..prior`, reads the same as `new_base..head`. The same
    paths, each with the same status and modes and the same hunks in order, compared both ways. Who owns what the base
    touched doesn't matter; a region claim must still map from the old base to the new one, for ownership."""
    helper = _region_ownership()
    regions = [claim for claim in state.get("laneRegions", []) if claim["lane"] == lane]
    differing = []
    first = None
    try:
        for claim in regions:
            start, end = helper.mapped(c.root, claim, old_base)
            # Verify the transition itself even when the claim was originally
            # anchored before both bases.
            helper.mapped(c.root, {**claim, "baseHead": old_base, "start": start, "end": end}, new_base)
        before, after = (delta_entries(helper, c.root, base, tip)
                         for base, tip in ((old_base, prior), (new_base, head)))
        for raw_path in sorted(before.keys() | after.keys()):
            path = os.fsdecode(raw_path)
            old = (before.get(raw_path),
                   delta_hunks(helper, c.root, old_base, prior, raw_path) if raw_path in before else [])
            new = (after.get(raw_path),
                   delta_hunks(helper, c.root, new_base, head, raw_path) if raw_path in after else [])
            if old == new:
                continue
            differing.append(path)
            if first is None:
                first = (path, old, new)
    except helper.RegionError as error:
        raise Stop(str(error)) from error
    if not differing:
        return
    path, (old_meta, old_hunks), (new_meta, new_hunks) = first
    lines = [f"the base merge {head} changes the story delta for {', '.join(differing)}"]
    if old_meta != new_meta:
        def meta(entry):
            if entry is None:
                return "unchanged by the story"
            old_mode, new_mode, status = (part.decode() for part in entry)
            return f"status {status}, mode {old_mode} -> {new_mode}"
        lines.append(f"{path}: before the merge {meta(old_meta)}; after it {meta(new_meta)}")
    index = next((n for n in range(max(len(old_hunks), len(new_hunks)))
                  if old_hunks[n:n + 1] != new_hunks[n:n + 1]), None)
    if index is not None:
        lines.append(f"{path}, the first hunk that differs, before the merge:")
        lines += ["  " + line for line in shown_lines((old_hunks[index:index + 1] or [[]])[0])]
        lines.append("after it:")
        lines += ["  " + line for line in shown_lines((new_hunks[index:index + 1] or [[]])[0])]
    raise Stop("\n".join(lines))


def verify_base_merge(c, key: str, lane: str, reviewed: str, head: str, doc: dict) -> dict:
    history = git("rev-list", "--first-parent", "--reverse", f"{reviewed}..{head}").splitlines()
    if not history:
        raise Stop("the handed head has no base merge after review")
    grants = [entry for entry in doc["journal"] if entry["subject"] == key and entry["lane"] == lane
              and entry["kind"] == "base.merge.authorized" and entry["data"].get("reviewed") == reviewed]
    prior = reviewed
    base_commits = []
    for merge in history:
        _, *parents = git("rev-list", "--parents", "-n", "1", merge).split()
        if len(parents) != 2 or parents[0] != prior:
            raise Stop("the first-parent history after review must contain only two-parent base merges")
        base = parents[1]
        if not is_ancestor(base, c.base_ref):
            raise Stop(f"{base} is outside the history of {c.base_ref}")
        # The authorization's unpredictable token must already be in the
        # immutable merge commit. A caller-controlled commit date proves no ordering.
        covering = [entry for entry in grants if base in entry["data"]["baseCommits"]]
        if not covering:
            raise Stop(f"the lead did not authorize {key} to merge {base} from {reviewed} before the merge")
        trailers = base_merge_tokens(merge)
        if not any(trailers == [entry["data"]["token"]] for entry in covering):
            problem = (f"the base merge {merge} has no {BASE_MERGE_TRAILER} trailer from {key}'s authorization to merge "
                       f"{base}")
            if merge != history[-1]:
                raise Stop(f"{problem}. It is not the last merge, so no amend fixes it: merge again from {prior}, "
                           "with the authorized commands")
            fix = shlex.join(["git", "commit", "--amend", *base_merge_message(key, covering[-1]["data"]["token"])])
            raise Stop(f"{problem}. Fix its message with:\n  {fix}\nA merge already pushed is replaced only by a "
                       "forced push, which a lane never makes: ask the lead")
        old_base = git("merge-base", c.base_ref, prior)
        new_base = git("merge-base", c.base_ref, merge)
        if new_base != base or old_base == new_base or not is_ancestor(old_base, new_base):
            raise Stop(f"{base} does not advance the candidate's delivery-base ancestor")
        check_base_merge_delta(c, doc["state"], lane, prior, merge, old_base, new_base)
        base_commits.append(base)
        prior = merge
    return {"reviewed": reviewed, "baseCommits": base_commits}


def handoff(args) -> None:
    c = cfg()
    key = c.require(args.key)
    lane = c.lane_of(key)
    if args.no_change:
        no_change_handoff(c, key, lane, args)
        return
    if not args.pr:
        raise Stop("a hand-off needs --pr, the story's open PR; a story that needs no change hands off with "
                   "--no-change --evidence")
    review_conf = pr_review_config()  # refused here, before anything else, when review.pr is malformed
    added = catalogue_additions(c, "HEAD")
    ran = check_ids(c, args.checks, "--checks", added) if args.checks is not None else []
    folder = review_dir(key)
    head = clean_head()
    git("fetch", "-q", c.remote, c.base_branch)
    check_base_conflict(c, key, head)
    lane = c.lane_of(key)
    pushed(key, head)
    pr = forge("get", "--url", args.pr)
    if (pr.get("state") != "open" or pr.get("source") != c.branch(key) or pr.get("destination") != c.base_branch
            or not same_commit(pr.get("head"), head)):
        raise Stop(f"{args.pr} isn't an open PR from {c.branch(key)} into {c.base_branch}: {pr}")
    rounds = round_files(folder)
    if not rounds:
        raise Stop("no review rounds yet: run review-prepare and review-reduce")
    outcomes = [json.loads(p.read_text()) for p in rounds]
    last = outcomes[-1]
    if last["outcome"] != "aligned":
        raise Stop(f"round {last['round']} is {last['outcome']}; the lenses have not all approved")
    story_lenses, lenses_reason, requested = latest_lenses(c, folder)
    unrun = unrun_brief_lenses(c, key, story_lenses) if lenses_reason else []
    if unrun:
        raise Stop("\n  ".join(unrun))
    if {e["lens"] for e in last["entries"]} != set(story_lenses):
        raise Stop(f"round {last['round']} doesn't carry every lens of the story's set, {', '.join(story_lenses)}")
    notes = evidence_notes(last) if c.no_deferrals else []
    if notes:
        raise Stop(f"round {last['round']}'s evidence holds notes, and this delivery takes no deferrals: fix each, then "
                   "review again, where each lens says \"nothing left unfixed\":\n  "
                   + "\n  ".join(f"{lens}: {note}" for lens, note in notes))
    reviewed = last["entries"][0]["binding"]["candidateRef"]
    base_merge = None
    if reviewed != head:
        try:
            base_merge = verify_base_merge(c, key, lane, reviewed, head, load_state())
        except Stop as error:
            raise Stop(f"the approved round reviewed {reviewed[:10]}, but HEAD is {head[:10]}; "
                       f"review the new head: {error}") from error
    lane = check_candidate_ownership(c, key, git("merge-base", c.base_ref, head), head)
    if (c.binding.get("regenerable") or {}).get("listings"):
        # The merge queue stops a candidate that changes what a regenerable listing lists when its lane doesn't own
        # the listing. Its own check, asked here, says so before the lead accepts rather than after.
        merge_queue, queue, values = listing_reader(c, key, head)
        try:
            moved = list(queue.unowned_listing_changes(lane, repo(), c.base_ref, head, values))
        except merge_queue.Stop as error:
            raise Stop(f"the merge queue's listing check can't run at {head[:10]}: {error.detail}") from error
        if moved:
            said = lambda added, removed: "; ".join(filter(None, [added and f"added {', '.join(added)}",
                                                                   removed and f"removed {', '.join(removed)}"]))

            def ask(path: str, owners: list[str]) -> str:
                # A listing no lane holds is granted; one another lane holds, even beside this one, is moved from it.
                others = [owner for owner in owners if owner != lane]
                if not others:
                    return f"ask the lead to grant it, with {flow_command()} lead-own --lane {lane} --grant {path}"
                held = "shared with" if lane in owners else "held by"
                claims = c.record_state().get("laneOwnership", {})
                return (f"it is {held} {', '.join(others)}, so ask the lead to make it {lane}'s alone, with "
                        + " and ".join(f"{flow_command()} lead-own --lane {lane} --move {claim} --from {other}"
                                       for other in others for claim in claims.get(other, [])
                                       if fnmatch.fnmatchcase(path, claim)))
            raise Stop("\n  ".join([f"{key} changes the outputs a listing names, in files {lane} doesn't own alone, and "
                                    "the merge queue would stop it after acceptance:",
                                    *(f"{path} ({said(added, removed)}): {ask(path, owners)}"
                                      for path, owners, added, removed in moved),
                                    "then hand off again. Refreshing a listing's digests alone needs no grant."]))
    validation, gate_problems = gates_summary(key, repo(), head)
    pr_line = None
    # A lane stopped by a silent reviewer hands off blocked on it, and the lead decides that reviewer. The block holds
    # only while a required reviewer is silent at the head, and the record pr-review wrote is still required, with
    # every current review triaged. The legacy shape has no settle, and no such block.
    on_silent = bool(review_conf) and not review_conf["legacy"] and PR_REVIEW_BLOCK in parse_blocked(args.blocked)
    if on_silent:
        live = read_pr_reviews(args.pr, head, review_conf, None)
        if silent_refusal(live, head, review_conf["reviewers"]) is None:
            gate_problems.append(f"--blocked {PR_REVIEW_BLOCK} is for a required reviewer silent after the settle, and "
                                 f"none is silent at {head[:10]}: run {flow_command()} pr-review {key} --wait, and "
                                 "triage what it shows")
    if review_conf:
        saved = folder / "pr-review.json"
        recorded = json.loads(saved.read_text()) if saved.exists() else {}
        if recorded.get("head") != head:
            gate_problems.append(f"no PR review recorded at {head[:10]}: run {flow_command()} pr-review {key} --wait")
        elif review_conf["legacy"]:
            # As it always was: one text, the last given, whatever it says.
            text = (args.pr_review_triage or [""])[-1].strip()
            if not text:
                gate_problems.append("say how the PR review's findings were handled: --pr-review-triage TEXT")
            else:
                recorded["triage"] = text
                saved.write_text(json.dumps(recorded, indent=2))
                pr_line = f"{recorded['author']} at {recorded['at'][:16]}; triage: {recorded['triage']}"
        else:
            pr_line, problems_ = pr_review_handoff(key, review_conf, recorded, args.pr_review_triage or [], on_silent)
            problems_ += pr_review_gates.recorded_refusals(review_conf["reviewers"], record_reviewers(recorded), head)
            if problems_:
                gate_problems += problems_
            else:
                saved.write_text(json.dumps(recorded, indent=2))
    blocked = parse_blocked(args.blocked)
    (folder / "blocked.json").write_text(json.dumps({"head": head, "blocked": blocked}, indent=2))
    lines, problems = in_app_evidence(key, repo(), head, blocked)
    video_lines, video_problems = video_evidence(key, repo(), head)
    lines += video_lines
    problems = gate_problems + problems + video_problems
    if problems:
        raise Stop("the hand-off isn't complete:\n  " + "\n  ".join(problems))
    state_tool("capture-review", "--subject", key, "--candidate", reviewed,
               *[x for p in rounds for x in ("--outcome", str(p))])
    conf = tracker_conf(c)
    when = conf["transitions"].get("reviewWhen")
    if when and when != "pipeline-green" or when == "pipeline-green" and pr_line:
        # A review move a refused call left owed is retried here, at the latest.
        review_move(c, key, when, last=True)
    guarded = guard_lines(key, repo(), head)
    post = f"hand-off: {args.pr}, head {head[:10]}, {len(rounds)} review round(s); {validation}." + "".join(
        f" {line[0].upper() + line[1:]}." for line in guarded if line.startswith("guards skipped"))
    if base_merge:
        post += f" Review carried from {reviewed} across base commits {', '.join(base_merge['baseCommits'])}."
    records = handoff_records(key, head)
    posted = handoff_and_post(c, key, lane, head, args.pr, len(rounds), post, ran, base_merge, list(records.values()))
    histories = [f"r{o['round']}: {round_history_text(o)}" for o in outcomes if round_history_text(o)]
    print("\n".join([
        f"**Hand-off: {key}** ({c.label(key)}, {lane})",
        f"- candidate: {args.pr}",
        f"- reviewed head: `{reviewed}`",
        *([f"- handed head: `{head}`", f"- authorized base commits: {', '.join(base_merge['baseCommits'])}"]
          if base_merge else []),
        "- review rounds: " + "; ".join(f"r{o['round']} {o['outcome']}" for o in outcomes) + " (review evidence captured)"
        + (f"; history: {'; '.join(histories)}" if histories else ""),
        f"- review lenses: {lenses_text(story_lenses, lenses_reason, requested)}",
        f"- validation: {validation}",
        *(f"- {line}" for line in guarded),
        *([f"- checks run: {checks_shown(ran, added)}", f"- checks run, as recorded: {checks_recorded(ran, records)}"]
          if ran else []),
        f"- check records: {records_shown(records)}",
        *([f"- PR review: {pr_line}"] if pr_line else []),
        "- in-app checks: " + ("; ".join(lines) or "none required"),
        "- run: none",
        "- lead inputs: none",
        f"- expensive non-blocking findings: {args.findings or 'none'}",
    ]))
    if posted:
        print(f"\n{posted}")
    else:
        print(f"\nTracker post (your story): {post}")


# -- the delivery posture ---------------------------------------------------------------------
# One declaration on the delivery's base says whether its close-out runs fullHealth. It is read fresh on every use,
# through git, from the tip of the remote's branch: never from the shelf, a working tree or a merge base, and never
# held between passes. The vectors in tests/fixtures/delivery-posture-vectors.json keep this reader and the harness's
# exported resolver giving the same answer for the same bytes.

POSTURE_FILE = ".agents/delivery-posture.json"
POSTURE_SCHEMA = "delivery-posture/1"
POSTURE_LIMIT_BYTES = 64 * 1024
POSTURE_SECONDS = 15
# Arrays and objects open at once, the top-level object being 1. Measured on the text before it is parsed, as the
# harness's reader measures it, so no decoder's own limit, which differs by Python version, is what decides.
POSTURE_MAX_DEPTH = 64
# What Python's strip and JavaScript's trim remove, together: the two disagree, and both readers must not.
POSTURE_BLANK = re.compile("[\t-\r\x1c-\x20\x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]*")
# delivery-plan/1's caps and refusals, so what the record shows of a declaration can always go in the plan.
POSTURE_SOURCE_SHOWN, POSTURE_REASON_SHOWN = 200, 600
POSTURE_UNSHOWABLE = re.compile("[\u0000-\u001f\u007f-\u009f\u2028\u2029]+")


def posture_git(root: Path, args: list[str], seconds: int) -> subprocess.CompletedProcess | None:
    """One bounded git command, as bytes: None when it can't start or outruns its bound. In its own group, so a stopped
    fetch takes its transport with it and nothing is left holding the output open."""
    env = {**os.environ, "GIT_TERMINAL_PROMPT": "0"}
    try:
        proc = subprocess.Popen(["git", *args], cwd=root, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, start_new_session=True)
    except OSError:
        return None
    try:
        out, err = proc.communicate(timeout=seconds)
        return subprocess.CompletedProcess(proc.args, proc.returncode, out, err)
    except subprocess.TimeoutExpired:
        with contextlib.suppress(ProcessLookupError, PermissionError):
            os.killpg(proc.pid, signal.SIGKILL)
        with contextlib.suppress(subprocess.TimeoutExpired):
            proc.communicate(timeout=seconds)
        return None


def posture_nests_too_deep(text: str) -> bool:
    """Whether more than POSTURE_MAX_DEPTH arrays and objects are open at once anywhere in ``text``, outside strings.
    A string runs from an unescaped quote to the next, and inside one a backslash escapes exactly the next character."""
    depth, in_string, escaped = 0, False, False
    for char in text:
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            in_string = True
        elif char in "[{":
            depth += 1
            if depth > POSTURE_MAX_DEPTH:
                return True
        elif char in "]}":
            depth -= 1
    return False


def posture_of_bytes(raw: bytes) -> tuple[dict | None, str]:
    """A declaration's posture and reason, or None and what is wrong with it."""
    def constant(name: str) -> None:
        raise ValueError(f"{name} isn't JSON")
    try:
        text = raw.decode("utf-8")
    except ValueError:
        return None, "it isn't valid UTF-8 JSON"
    if posture_nests_too_deep(text):
        return None, f"it nests deeper than {POSTURE_MAX_DEPTH} levels"
    try:
        # Numbers as floats: a member is ignored whatever its size, as JSON.parse ignores it.
        value = json.loads(text, parse_constant=constant, parse_int=float)
    except (ValueError, RecursionError):
        return None, "it isn't valid UTF-8 JSON"
    if not isinstance(value, dict):
        return None, "it isn't an object"
    if value.get("schemaVersion") != POSTURE_SCHEMA:
        return None, f"its schemaVersion isn't {POSTURE_SCHEMA}"
    if not isinstance(value.get("posture"), str) or value["posture"] not in ("gate", "focused"):
        return None, "its posture is neither gate nor focused"
    reason = value.get("reason")
    if not isinstance(reason, str) or POSTURE_BLANK.fullmatch(reason):
        return None, "its reason is missing or blank"
    return {"posture": value["posture"], "reason": reason}, ""


def resolve_delivery_posture(root: Path, remote: str, branch: str, seconds: int = POSTURE_SECONDS) -> dict:
    """The posture the tip of `<remote>/<branch>` declares: {posture, reason, source, baseTipSha, code}. Anything but a
    valid declaration is `gate`, with the code that says why. Offline, the last fetched tip decides."""
    base = f"{remote}/{branch}"
    ref = f"refs/remotes/{remote}/{branch}"

    def gate(code: str, reason: str, tip: str | None, source: str = base) -> dict:
        return {"posture": "gate", "reason": f"{POSTURE_FILE} on {base}: {reason}; the posture is gate.", "source": source,
                "baseTipSha": tip, "code": code}

    def unreadable(what: str) -> dict:
        return gate("posture_unreadable", what, None, "fallback")

    posture_git(root, ["fetch", "-q", "--no-tags", remote, f"+refs/heads/{branch}:{ref}"], seconds)  # best effort
    found = posture_git(root, ["rev-parse", "--verify", "-q", f"{ref}^{{commit}}"], seconds)
    if found is None or found.returncode != 0:
        return unreadable(f"{ref} can't be resolved")
    tip = found.stdout.decode("ascii", "replace").strip()
    listed = posture_git(root, ["ls-tree", "--full-tree", "-z", "-l", tip, "--", POSTURE_FILE], seconds)
    if listed is None or listed.returncode != 0:
        return unreadable(f"the tree of {tip[:10]} can't be read")
    if not listed.stdout:
        return gate("posture_undeclared", "no file at the tip", tip)
    try:
        mode, kind, blob, size = listed.stdout.split(b"\t", 1)[0].decode("ascii", "replace").split()
    except ValueError:
        return unreadable(f"the tree of {tip[:10]} can't be read")
    if kind != "blob" or mode == "120000":
        return gate("posture_malformed", "a symlink, tree or submodule is at the path, not a file", tip)
    if not size.isdigit():
        return unreadable(f"the tree of {tip[:10]} can't be read")
    if int(size) > POSTURE_LIMIT_BYTES:
        return gate("posture_malformed", f"the file holds over {POSTURE_LIMIT_BYTES} bytes", tip)
    shown = posture_git(root, ["show", blob], seconds)
    if shown is None or shown.returncode != 0:
        return unreadable(f"the file at {tip[:10]} can't be read")
    declared, wrong = posture_of_bytes(shown.stdout)
    if declared is None:
        return gate("posture_malformed", wrong, tip)
    return {**declared, "source": base, "baseTipSha": tip, "code": None}


def delivery_posture(c) -> dict:
    """The delivery's own base decides, not the binding's: an integration base is the lead's own."""
    return resolve_delivery_posture(c.root, c.remote, c.base_branch)


def posture_said(posture: dict) -> dict:
    """{posture, source, reason} as the record shows them: within delivery-plan/1's caps and free of what it refuses
    or an argument can't carry, whatever the declaration held."""
    def shown(text: str, cap: int) -> str:
        clean = POSTURE_UNSHOWABLE.sub(" ", text.encode("utf-8", "replace").decode("utf-8")).strip()
        return clean[:cap].strip() or "(the declaration's text can't be shown)"
    return {"posture": posture["posture"], "source": shown(posture["source"], POSTURE_SOURCE_SHOWN),
            "reason": shown(posture["reason"], POSTURE_REASON_SHOWN)}


# -- the plan chapter's producer -------------------------------------------------------------------
# plan.json, the delivery-views input `delivery-plan/1`, is a pure function of the delivery file at the base, the
# append-only plan-changes.jsonl beside the lead's flow logs, the app-check and video flow logs, the acceptance log and
# the full-health log. Only lead-side commands and the reconcile sweep rebuild it, under one lock; lanes only append their flow logs,
# and the file is never read back as a source.

PLAN_FILE = "plan.json"
PLAN_CHANGES = "plan-changes.jsonl"
PLAN_RECORD_KINDS = [{"id": "review", "label": "Review", "source": "record"},
                     {"id": "handed", "label": "Handed off", "source": "record"},
                     {"id": "merged", "label": "Merged", "source": "record"}]
# One producer kind per in-app mode, in this order, and one for before/after clips.
PLAN_IN_APP_KINDS = {"hold": "In-app: loading state", "fail": "In-app: failure state", "loaded": "In-app: page loads",
                     "any": "In-app: pinned requests"}
PLAN_CLIP_KIND = {"id": "clip", "label": "Before/after clip", "source": "producer"}
LATE_SNAPSHOT = "taken after the delivery started"
PLAN_DEPTH = [0]


def plan_declared(c) -> bool:
    """The plan chapter is on once any story declares criteria."""
    return any(story.get("criteria") for story in c.stories.values())


def plan_log_path(c) -> Path:
    return c.flow_log / PLAN_CHANGES


def read_plan_log(c) -> list[dict]:
    path = plan_log_path(c)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()] if path.exists() else []


def append_plan_log(c, entry: dict) -> dict:
    c.flow_log.mkdir(parents=True, exist_ok=True)
    entry = {**entry, "at": entry.get("at") or now()}
    with open(plan_log_path(c), "a") as log:
        log.write(json.dumps(entry) + "\n")
    return entry


class plan_lock:
    """The one writer's lock: the changes log, plan.json and its journal entry change only under it. Re-entered by
    the same process, so a command that records a change and then rebuilds holds it throughout."""

    def __init__(self, c):
        self.path = c.flow_log / "plan.lock"

    def __enter__(self):
        PLAN_DEPTH[0] += 1
        if PLAN_DEPTH[0] == 1:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self.file = open(self.path, "a+")
            fcntl.flock(self.file, fcntl.LOCK_EX)
            PLAN_DEPTH.append(self.file)
        return self

    def __exit__(self, *_):
        PLAN_DEPTH[0] -= 1
        if PLAN_DEPTH[0] == 0:
            held = PLAN_DEPTH.pop()
            fcntl.flock(held, fcntl.LOCK_UN)
            held.close()


def plan_proofs(c, key: str) -> list[str]:
    """The proofs a story owes: the record's three, one per in-app mode its hand-off needs, and a clip if marked."""
    modes = {req["mode"] for req in c.requirements(key)}
    owed = [kind["id"] for kind in PLAN_RECORD_KINDS] + [f"in-app-{mode}" for mode in PLAN_IN_APP_KINDS if mode in modes]
    return owed + (["clip"] if c.stories[key].get("evidence") == "video" else [])


def plan_unit(c, key: str) -> dict:
    story = c.stories[key]
    return {"subject": key, **({"label": story["label"]} if story.get("label") else {}), "title": story["title"],
            "criteria": [{"id": item["id"], "text": item["text"]} for item in story.get("criteria", [])],
            "proofs": plan_proofs(c, key)}


def plan_covers(line: dict) -> dict:
    """A finish line's covers; a line that declares none covers every criterion, by every proof its units owe. One
    declared empty, `{}` or null, covers no criteria and names no proofs, so the line is the lead's to check."""
    if "covers" not in line:
        return {"criteria": "all", "proofs": []}
    return {"criteria": [], "proofs": []} if line["covers"] in (None, {}) else line["covers"]


def leads_line(line: dict) -> bool:
    """A finish line that names no criteria and no proofs: nothing the record proves, so only the lead marks it."""
    covers = plan_covers(line)
    return not isinstance(covers, dict) or not (covers.get("criteria") or covers.get("proofs"))


def plan_finish(c, at: str) -> list[dict]:
    return [{"id": line["id"], "label": line.get("label", line["id"]), "text": line["text"], "at": line.get("at", at),
             "covers": plan_covers(line)} for line in c.finish]


def plan_view(c) -> dict:
    """What drift detection compares: each story's criteria, each finish line's covers, and, when any story names
    some, each story's brief lenses (left out otherwise, so a plan with none compares as it always did)."""
    return {"criteria": {key: {item["id"]: item["text"] for item in story.get("criteria", [])}
                         for key, story in c.stories.items()},
            "covers": {line["id"]: plan_covers(line) for line in c.finish},
            **({"lenses": lenses} if (lenses := plan_lenses(c)) else {})}


def view_of_snapshot(snapshot: dict) -> dict:
    return {"criteria": {unit["subject"]: {item["id"]: item["text"] for item in unit["criteria"]} for unit in snapshot["units"]},
            "covers": {line["id"]: line["covers"] for line in snapshot["finish"]},
            **({"lenses": snapshot["lenses"]} if snapshot.get("lenses") else {})}


def view_digest(view: dict) -> str:
    return hashlib.sha256(json.dumps(view, sort_keys=True).encode()).hexdigest()


def snapshot_entry(c, late: bool) -> dict:
    at = now()
    return {"type": "snapshot", "at": at, "late": late, "units": [plan_unit(c, key) for key in c.stories],
            "finish": plan_finish(c, at), **({"lenses": lenses} if (lenses := plan_lenses(c)) else {})}


def write_snapshot(c, late: bool) -> dict:
    """The approved plan, frozen once: the changes log's first entry. Checked before it is frozen, since no later
    correction of the delivery file could repair a snapshot the view can't read."""
    entry = snapshot_entry(c, late)
    check_plan(build_plan(c, [entry]), c)
    return append_plan_log(c, entry)


def record_plan_change(c, change: dict) -> dict:
    """Append one change, numbered after every change before it."""
    with plan_lock(c):
        count = sum(1 for entry in read_plan_log(c) if entry["type"] == "change")
        return append_plan_log(c, {"type": "change", "id": f"c{count + 1}", **change})


def plan_drift(c, log: list[dict]) -> list[dict]:
    """The entries a rebuild appends when the delivery file moved since the last baseline: one `unrecorded` change per
    difference no recorded change explains, then the new baseline. Nothing when it has not moved."""
    view = plan_view(c)
    digest_now = view_digest(view)
    last_index = max((i for i, entry in enumerate(log) if entry["type"] in ("snapshot", "baseline")), default=None)
    if last_index is None:
        return []
    last = log[last_index]
    before = last["view"] if last["type"] == "baseline" else view_of_snapshot(last)
    if view_digest(before) == digest_now:
        return []
    recorded = [entry for entry in log[last_index + 1:] if entry["type"] == "change" and entry["by"] != "unrecorded"]

    def explained(kind: str, key: str | None = None, criterion: str | None = None, after=None, finish: str | None = None) -> bool:
        for change in recorded:
            if kind == "story-added" and change["kind"] == "added" and key in change["subjects"] and not change.get("criteria"):
                return True
            if kind == "story-removed" and change["kind"] == "removed" and key in change["subjects"] and not change.get("criteria"):
                return True
            if kind == "criterion" and criterion in change.get("criteria", []) and change.get("after") == after:
                return True
            if kind == "finish" and change["kind"] == "finish" and change.get("finish") == finish and change.get("after") == after:
                return True
            if kind == "lenses" and "lenses" in change and key in change["subjects"] and change["lenses"] == after:
                return True
        return False

    found = []
    for key in before["criteria"]:
        if key not in view["criteria"] and not explained("story-removed", key):
            found.append({"kind": "removed", "subjects": [key]})
    for key, criteria in view["criteria"].items():
        old = before["criteria"].get(key)
        if old is None and explained("story-added", key):
            continue
        old = old or {}
        for ident, text in criteria.items():
            if old.get(ident) != text and not explained("criterion", key, ident, text):
                found.append({"kind": "added" if ident not in old else "changed", "subjects": [key], "criteria": [ident],
                              **({"before": old[ident]} if ident in old else {}), "after": text})
        for ident, text in old.items():
            if ident not in criteria and not explained("criterion", key, ident, None):
                found.append({"kind": "changed", "subjects": [key], "criteria": [ident], "before": text})
    # A story's brief lenses, recorded as a `changed` change carrying the lenses it leaves, since the plan's change
    # kinds are the view's.
    for key in view["criteria"]:
        old, new = before.get("lenses", {}).get(key, []), view.get("lenses", {}).get(key, [])
        if old != new and not explained("lenses", key, after=new):
            found.append({"kind": "changed", "subjects": [key], "lenses": new, "before": lenses_words(old),
                          "after": lenses_words(new)})
    for ident, covers in view["covers"].items():
        if before["covers"].get(ident) != covers and not explained("finish", finish=ident, after=covers):
            found.append({"kind": "finish", "subjects": [], "finish": ident,
                          **({"before": before["covers"][ident]} if ident in before["covers"] else {}), "after": covers})
    count = sum(1 for entry in log if entry["type"] == "change")
    entries = [{"type": "change", "id": f"c{count + i + 1}", "by": "unrecorded", "source": "drift", **change}
               for i, change in enumerate(found)]
    return [*entries, {"type": "baseline", "digest": digest_now, "view": view}]


def satisfied_requirements(reqs: list[dict], runs: list[dict]) -> set[int]:
    """The requirements a set of passing runs meets: each mode requirement by a run of its own (a bipartite matching,
    so one run never stands in for two checks), each pattern requirement by any run that used its pattern."""
    def satisfies(req, r):
        if req["mode"] != "any" and r["mode"] != req["mode"]:
            return False
        if req.get("pattern") and req["pattern"] not in r["spec"].get("holds", []) + r["spec"].get("fails", []):
            return False
        args = req.get("args")
        if args is None:
            return True
        if r.get("passthrough") is None:
            return False
        if not args:  # "args": [] means a run with no adapter arguments
            return not r["passthrough"]
        return any(r["passthrough"][i:i + len(args)] == args for i in range(len(r["passthrough"])))

    modal = [(qi, q) for qi, q in enumerate(reqs) if q["mode"] != "any"]
    owner: dict[int, int] = {}  # run index -> requirement index

    def assign(qi: int, req: dict, seen: set[int]) -> bool:
        for ri, run_ in enumerate(runs):
            if ri in seen or not satisfies(req, run_):
                continue
            seen.add(ri)
            if ri not in owner or assign(owner[ri], reqs[owner[ri]], seen):
                owner[ri] = qi
                return True
        return False

    met = {qi for qi, req in modal if assign(qi, req, set())}
    return met | {qi for qi, req in enumerate(reqs) if req["mode"] == "any" and any(satisfies(req, r) for r in runs)}


def plan_flow_log(c, name: str, key: str) -> list[dict]:
    path = c.flow_log / f"{key}.{name}.jsonl"
    entries = [json.loads(line) for line in path.read_text().splitlines() if line.strip()] if path.exists() else []
    return carried_with_peers(Path(c.flow_log), key, name, entries)


def plan_current(c, at: str, head: str) -> bool:
    """Whether a run at `at` still stands at `head`: the same commit, or no shipped file changed between them."""
    if at == head:
        return True
    done = run(["git", "diff", "--name-only", at, head, "--", *((c.ship or {}).get("paths") or ["."])], cwd=c.root,
               check=False)
    return done.returncode == 0 and not [f for f in done.stdout.splitlines() if f and not re.search(c.test_files, f)]


def plan_evidence(c, key: str) -> dict:
    """The story's producer proofs. The head they are judged at is the one the lead last accepted, or before any
    acceptance, the latest head with a passing check. A kind is done when every required item passed at a head current
    with it, and waived when every missing item was accepted with --accept-blocked there."""
    runs = [entry for entry in plan_flow_log(c, "app-checks", key) if entry.get("head")]
    accepted = (plan_flow_log(c, "acceptance", key) or [None])[-1]
    passing = [entry for entry in runs if entry["pass"]]
    head = accepted["head"] if accepted else (passing[-1]["head"] if passing else None)
    current = lambda at: head is not None and plan_current(c, at, head)
    fresh = [{"mode": e["mode"], "spec": e.get("specValue") or {}, "passthrough": e.get("passthrough"), "at": e["at"]}
             for e in passing if current(e["head"])]
    reqs = c.requirements(key)
    met = satisfied_requirements(reqs, fresh)
    evidence = {}
    for mode in PLAN_IN_APP_KINDS:
        mine = [(qi, req) for qi, req in enumerate(reqs) if req["mode"] == mode]
        if not mine:
            continue
        items = [requirement_label(req) for _, req in mine]
        missing = [requirement_label(req) for qi, req in mine if qi not in met]
        blocked = (accepted or {}).get("blocked", {})
        if not missing:
            evidence[f"in-app-{mode}"] = {"state": "done", "head": head, "at": max(e["at"] for e in fresh), "items": items}
        elif accepted and all(label in blocked for label in missing):
            evidence[f"in-app-{mode}"] = {"state": "waived", "head": head, "at": accepted["at"], "items": items,
                                          "reason": "; ".join(f"{label}: {blocked[label]}" for label in missing)}
        else:
            evidence[f"in-app-{mode}"] = {"state": "todo", "items": items}
    if c.stories[key].get("evidence") == "video":
        clips = [entry for entry in plan_flow_log(c, "videos", key) if current(entry["head"])]
        evidence["clip"] = ({"state": "done", "head": head, "at": clips[-1]["at"], "items": [e["name"] for e in clips]}
                            if clips else {"state": "todo"})
    return evidence


def build_plan(c, log: list[dict]) -> dict:
    """The plan document, from the delivery file and the changes log."""
    snapshot = next(entry for entry in log if entry["type"] == "snapshot")
    units = [plan_unit(c, key) for key in c.stories]
    held = {unit["subject"] for unit in units}
    last_seen = {unit["subject"]: unit for unit in snapshot["units"]}
    for entry in log:
        for unit in entry.get("units", []) if entry["type"] == "change" else []:
            last_seen[unit["subject"]] = unit
        if entry["type"] == "change" and entry["kind"] == "added":
            for key in entry["subjects"]:
                last_seen.setdefault(key, {"subject": key, "title": entry.get("title", key), "criteria": []})
    for key, unit in last_seen.items():
        if key not in held:
            units.append({**unit, "removed": True, "proofs": [kind["id"] for kind in PLAN_RECORD_KINDS]})
    owed = {kind for unit in [*units, *snapshot["units"]] for kind in unit["proofs"]}
    kinds = [*PLAN_RECORD_KINDS, *({"id": f"in-app-{mode}", "label": label, "source": "producer"}
                                    for mode, label in PLAN_IN_APP_KINDS.items() if f"in-app-{mode}" in owed),
             *([PLAN_CLIP_KIND] if "clip" in owed else [])]
    whys = {entry["change"]: entry["why"] for entry in log if entry["type"] == "why"}
    changes = []
    for entry in (e for e in log if e["type"] == "change"):
        change = {key: entry[key] for key in ("id", "at", "kind", "subjects", "criteria", "by", "why", "title", "source",
                                              "ref", "before", "after") if key in entry}
        if entry["id"] in whys:
            change["why"] = whys[entry["id"]]
        changes.append(change)
    outcome = c.raw.get("outcome") or {"summary": c.raw.get("headline", c.delivery), "text": c.raw.get("headline", c.delivery)}
    review = plan_review_of(c)
    said = " · ".join(words for words in (LATE_SNAPSHOT if snapshot.get("late") else None, plan_review_words(review))
                      if words)
    plan = {
        "schemaVersion": "delivery-plan/1", "updated": now(), "outcome": outcome,
        # None: the view then needs every journaled verdict of a story's round to approve, whatever set it chose.
        "requiredLenses": c.raw.get("requiredLenses", []), "proofKinds": kinds, "units": units,
        "finish": plan_finish(c, snapshot["at"]),
        "approved": {"at": snapshot["at"], **({"review": said} if said else {}),
                     "snapshot": {"units": snapshot["units"], "finish": snapshot["finish"]}},
        "changes": changes,
        "evidence": {key: found for key in c.stories if (found := plan_evidence(c, key))},
    }
    for key in ("approvals", "outOfScope"):
        if key in c.raw:
            plan[key] = c.raw[key]
    if review:
        plan["planReview"] = review
    skip = full_health_skip(c)
    if skip:
        plan["closeOut"] = {"fullHealth": "skipped", **{key: skip[key] for key in ("posture", "source", "reason")}}
    return plan


def plan_validator(c):
    """The release's own delivery-plan/1 validator, so the producer and the view never drift apart."""
    path = str(c.release / "skills/delivery-views/scripts")
    if path not in sys.path:
        sys.path.insert(0, path)
    sys.dont_write_bytecode = True
    import views_common  # noqa: E402  (the installed release's own validator)
    return views_common


def check_plan(plan: dict, c, what: str = "the plan this delivery file makes", planning: bool | None = None) -> None:
    views = plan_validator(c)
    try:
        views.validate_plan(json.loads(json.dumps(plan)), **({} if planning is None else {"planning": planning}))
    except views.ConfigError as error:
        raise Stop(f"{what} isn't a valid delivery-plan/1: {error}")
    # Measured as rebuild_plan writes it, so the view never meets a file it refuses unread.
    size = len((json.dumps(plan, indent=2) + "\n").encode("utf-8"))
    if size > views.PLAN_LIMIT_BYTES:
        raise Stop(f"{what} holds {size} bytes, over the 1 MiB a plan may hold")


def rebuild_plan(c) -> str | None:
    """Rebuild plan.json under the lock. Writes it, atomically, only when its content apart from `updated` changed,
    then journals the write as plan.updated so the live view re-renders. Returns what changed, or None when nothing
    did."""
    if not (c.state / "state.json").exists():
        return None
    found = shared_seat(c)
    if found is not None and not found[0].holds(found[1], found[2], "delivery"):
        return None  # a shared record's plan is the delivery holder's, carried here (D21)
    with plan_lock(c):
        # The delivery file as it stands now, under the lock: a long-running sweep must not build from the one it
        # read when it started. A story added to it is registered first, so its `added` change explains it.
        c.load_delivery(c.delivery)
        register_stories(c)
        log = read_plan_log(c)
        if not any(entry["type"] == "snapshot" for entry in log):
            if not plan_declared(c):
                return None
            log.append(write_snapshot(c, late=True))
        for entry in plan_drift(c, log):
            log.append(append_plan_log(c, entry))
        plan = build_plan(c, log)
        check_plan(plan, c)
        path = c.state / PLAN_FILE
        old = json.loads(path.read_text()) if path.exists() else None
        same = lambda a, b: {k: v for k, v in a.items() if k != "updated"} == {k: v for k, v in b.items() if k != "updated"}
        if old is not None and same(old, plan):
            return None
        changed = [] if old is None else [
            key for key in sorted({*plan, *old}) if key != "updated" and old.get(key) != plan.get(key)]
        temporary = path.with_name(f".{PLAN_FILE}.{os.getpid()}.tmp")
        temporary.write_text(json.dumps(plan, indent=2) + "\n")
        os.replace(temporary, path)
        state_tool("journal", "--kind", "plan.updated", "--data", json.dumps({"updated": plan["updated"], "changed": changed}))
        return "changed " + ", ".join(changed) if changed else "first build"


def rebuild_plan_quietly(c) -> str:
    """For the sweep: one line, and a plan that won't build never stops the sweep."""
    try:
        moved = rebuild_plan(c)
    except (Stop, ValueError) as error:  # a refusal, or a delivery file saved mid-edit that isn't JSON
        return f"plan: not rebuilt: {error}"
    return f"plan: {moved}" if moved else "plan: unchanged"


# -- plan preview -------------------------------------------------------------------------------
# A plan under agent review, shown on the line map before any delivery exists: `plan-view --plan` reads the plan as
# committed at HEAD and its plan-review store, and keeps a record of its own per reviewSlug, beside the review store,
# at <main>/<work>/plan-preview/<slug>/. The folder is made once and never replaced: a rebuild replaces only its files,
# so whatever follows the folder keeps following it.

PREVIEW_PREFIX = "Plan preview (agent review only): "
PREVIEW_FOLDER = "plan-preview"
PREVIEW_LOCK = "preview.lock"
PREVIEW_FILE = "preview.json"
# The contract's caps a preview cuts its lists to, keeping the first items, and the words it names each by.
PREVIEW_CAPS = {"units": (200, "story", "stories"), "finish": (30, "finish line", "finish lines"),
                "approvals": (100, "approval", "approvals"), "outOfScope": (100, "out-of-scope item", "out-of-scope items"),
                "decisions": (100, "decision", "decisions")}
PREVIEW_CRITERIA = 1000  # every unit's criteria together
PREVIEW_OUTCOME_TEXT = 2000


def preview_folder(c, slug: str) -> Path:
    return c.main / c.work / PREVIEW_FOLDER / slug


def plan_labelled_list(section: str, label: str) -> list[str]:
    """The items of the list a story section opens with `label` (`Scenarios:`, `Done when`), each with its deeper lines
    joined to one line as plan_list_items joins them: the items nested under a bullet that opens with the label, or the
    list right after a paragraph line that does. A `Done when` bullet with nothing nested under it is its own one item.
    Only the first such list counts; none gives no items."""
    lines = section.splitlines()
    opening = re.compile(rf"^(?P<indent>[ \t]*)(?P<bullet>(?:[-*+]|\d+[.)])[ \t]+)?{re.escape(label)}(?P<rest>.*)$")
    marker = re.compile(r"^[ \t]*(?:[-*+]|\d+[.)])[ \t]+(?P<text>.*)$")
    width = lambda line: len(line) - len(line.lstrip(" \t"))
    for at, line in enumerate(lines):
        found = opening.match(line)
        if not found:
            continue
        indent, bulleted = len(found.group("indent")), bool(found.group("bullet"))
        own, items, level = label + found.group("rest"), [], None
        for below in lines[at + 1:]:
            if not below.strip():
                continue
            here, item = width(below), marker.match(below)
            if below.lstrip().startswith("#") or (here <= indent if bulleted else here < indent):
                break
            if item and level is None:
                level = here
            if level is None:
                own += " " + below.strip()  # the opening line's own continuation
            elif item and here == level:
                items.append(item.group("text"))
            elif here > level and items:
                items[-1] += " " + below.strip()
            else:
                break
        if not items and bulleted and label == "Done when" and found.group("rest").strip(" :"):
            items = [own]
        return [plan_line(text) for text in items if text.strip()]
    return []


def preview_out_of_scope(sections: list[tuple[int, str, str]]) -> list[str]:
    """The items of a heading named `Out of scope`, else of the list after an `Out of scope:` line inside `## Scope`."""
    own = next((body for _, title, body in sections if title.strip().rstrip(":") == "Out of scope"), None)
    if own is not None:
        return plan_list_all(own)
    scope = next((body for level, title, body in sections if level == 2 and title == "Scope"), None)
    found = re.search(r"^Out of scope:[ \t]*$", scope or "", re.M)
    if found is None:
        return []
    items: list[str] = []
    for line in ("\n" + scope[found.end():]).splitlines()[1:]:
        if line.strip() and not re.match(r"^(?:[-*+]|\d+[.)])\s", line) and line[:1] not in (" ", "\t"):
            break  # the list ends at the next paragraph
        items.append(line)
    return plan_list_all("\n" + "\n".join(items))


def plan_at_head(c, plan: Path) -> tuple[str, str, str]:
    """The plan's text as committed at HEAD, the last commit at HEAD that changed it, and that commit's committer time
    in UTC: never the working tree, so edits not yet committed wait for their commit."""
    shown = run(["git", "show", f"HEAD:{plan.as_posix()}"], cwd=c.root, check=False)
    if shown.returncode != 0:
        raise Stop(f"{plan} isn't committed at HEAD here; commit it, then run {flow_command()} plan-view --plan "
                   f"{shlex.quote(str(plan))}")
    commit, stamp = git("log", "-1", "--format=%H %ct", "HEAD", "--", plan.as_posix(), cwd=c.root).split()
    at = datetime.datetime.fromtimestamp(int(stamp), datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    return shown.stdout, commit, at


def preview_store(c, slug: str) -> tuple[Path, dict | None]:
    """The plan's review store and, once a delivery adopted it, the adoption: then the store is the delivery's, which
    holds every round. Never through plan_review_config, which refuses an adopted store."""
    own = c.main / c.work / "plan-review" / slug
    adopted = load_json(own / "adopted.json")
    return (Path(adopted["store"]) if adopted and adopted.get("store") else own), adopted


def build_preview(c, plan: Path, text: str, commit: str, at: str, store: Path, adopted: dict | None) -> tuple[dict, dict]:
    """The preview's delivery-plan/1 and the record's seed (headline, planned, finish), from the plan's text."""
    sections = plan_sections(text)
    meta = front_matter(text)
    heading = re.search(r"^# (.+)$", text, re.M)
    title = " ".join((meta.get("title") or (heading.group(1) if heading else "") or plan.stem).split())
    room = 600 - len(PREVIEW_PREFIX)
    summary = PREVIEW_PREFIX + (title if len(title) <= room else title[:room - 1] + "…")
    goal = next((body for level, name, body in sections if level == 2 and name == "Goal"), None)
    paragraph = next((" ".join(part.split()) for part in re.split(r"\n\s*\n", goal.split("\n", 1)[1] if goal and "\n" in goal
                      else "") if part.strip() and not part.lstrip().startswith("#")), None)
    stories = next((body for level, name, body in sections if level == 2 and name == "Stories"), None)
    table, _ = units_table(text)
    lane_of = {key: row["lane"] for row in table or [] for key in row["items"]}
    units, planned, seen = [], [], set()
    for level, name, body in plan_sections(stories or ""):
        found = re.match(STORY_HEADING, f"### {name}") if level == 3 else None
        if found is None or found.group("key") in seen:
            continue
        key = found.group("key")
        seen.add(key)
        criteria = [*plan_labelled_list(body, "Scenarios:"), *plan_labelled_list(body, "Done when")]
        unit_title = plan_line(found.group("title"))
        units.append({"subject": key, "title": unit_title,
                      "criteria": [{"id": f"{key.lower()}-{n}", "text": item} for n, item in enumerate(criteria, 1)],
                      "proofs": [kind["id"] for kind in PLAN_RECORD_KINDS]})
        order = story_plan(body) or {}
        files = section_files(body)
        planned.append({"subject": key, "title": unit_title, "lane": order.get("lane") or lane_of.get(key),
                        "stage": "planned", **({"after": order["after"]} if order.get("after") else {}),
                        **({"files": files} if files else {})})
    finish_body = next((body for level, name, body in sections if level == 2 and name == "Finish line"), "")
    approvals_body = next((body for level, name, body in sections if level == 2 and name == "Approval handoffs"), "")
    decisions_body = next((body for level, name, body in sections if level == 2 and name.startswith("Decisions")), "")
    lists = {"units": units, "finish": plan_list_all(finish_body), "approvals": plan_list_all(approvals_body),
             "outOfScope": preview_out_of_scope(sections), "decisions": plan_list_all(decisions_body)}
    dropped = []
    for member, (cap, one, many) in PREVIEW_CAPS.items():
        over = len(lists[member]) - cap
        if over > 0:
            lists[member] = lists[member][:cap]
            dropped.append(f"{over} {one if over == 1 else many}")
    planned = planned[:len(lists["units"])]
    left = PREVIEW_CRITERIA
    for unit in lists["units"]:
        kept = unit["criteria"][:max(left, 0)]
        left -= len(unit["criteria"])
        unit["criteria"] = kept
    if left < 0:
        dropped.append(f"{-left} criteri{'on' if left == -1 else 'a'}")
    said = (f" This preview leaves out what is over the plan's caps: {', '.join(dropped)}." if dropped else "")
    body_text = paragraph or title
    keep = PREVIEW_OUTCOME_TEXT - len(said)
    body_text = (body_text if len(body_text) <= keep else body_text[:keep - 1] + "…") + said
    finish = [{"id": f"finish-{n}", "label": f"Finish {n}", "text": line, "at": at,
               "covers": {"criteria": [], "proofs": []}} for n, line in enumerate(lists["finish"], 1)]
    preview = {"plan": plan.as_posix()[:600], "commit": commit,
               "approval": "handed" if adopted else "agents-only",
               **({"delivery": adopted["delivery"]} if adopted else {}),
               "layout": "delivery" if units else "other", "decisions": lists["decisions"]}
    built = {
        "schemaVersion": "delivery-plan/1", "updated": now(), "outcome": {"summary": summary, "text": body_text},
        "requiredLenses": [], "proofKinds": PLAN_RECORD_KINDS, "units": lists["units"], "finish": finish,
        "approved": {"at": at, "snapshot": {"units": lists["units"], "finish": finish}},
        "changes": [], "evidence": {},
        **({"approvals": [{"text": item, "state": "waiting"} for item in lists["approvals"]]} if lists["approvals"] else {}),
        **({"outOfScope": lists["outOfScope"]} if lists["outOfScope"] else {}),
        "preview": preview,
    }
    c.plan_store = store
    review = plan_review_of(c)
    if review:
        built["planReview"] = review
    seed = {"headline": summary, "planned": planned,
            "finish": [{"id": line["id"], "text": line["text"], "met": False} for line in finish]}
    return built, seed


def replace_file(path: Path, text: str) -> None:
    """Write a file by replacing it with a temporary file in its own folder."""
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    temporary.write_text(text)
    os.replace(temporary, path)


def rebuild_preview(c, plan: Path) -> tuple[Path, str | None]:
    """Build the plan's preview and write what changed, under the folder's lock. Returns the folder and what changed,
    None when nothing did."""
    text, commit, at = plan_at_head(c, plan)
    slug = needed_review_slug(plan, text)
    folder = preview_folder(c, slug)
    folder.mkdir(parents=True, exist_ok=True)
    c.state = folder
    with open(folder / PREVIEW_LOCK, "a+") as held:
        fcntl.flock(held, fcntl.LOCK_EX)
        store, adopted = preview_store(c, slug)
        # Handed to a planning record, which takes the plan over before any delivery adopts its review.
        adopted = adopted or load_json(folder / PREVIEW_HANDED)
        built, seed = build_preview(c, plan, text, commit, at, store, adopted)
        check_plan(built, c, f"the preview of {plan}", planning=False)
        said = []
        if not (folder / "state.json").exists():
            state_tool("init", "--headline", seed["headline"], "--seed",
                       json.dumps({"planned": seed["planned"], "finish": seed["finish"]}))
            said.append("record")
        else:
            def compute(doc):
                state = doc["state"]
                body = {**({"meta": {"headline": seed["headline"]}} if state["meta"].get("headline") != seed["headline"]
                           else {}),
                        **{key: seed[key] for key in ("planned", "finish") if state.get(key, []) != seed[key]}}
                return body or None
            if patch_from(compute, f"the preview record of {plan}"):
                said.append("record")
        path = folder / PLAN_FILE
        old = load_json(path)
        same = lambda a, b: {k: v for k, v in a.items() if k != "updated"} == {k: v for k, v in b.items() if k != "updated"}
        if old is None or not same(old, built):
            changed = [] if old is None else [
                key for key in sorted({*built, *old}) if key != "updated" and old.get(key) != built.get(key)]
            before = path.read_bytes() if old is not None else None
            replace_file(path, json.dumps(built, indent=2) + "\n")
            try:
                state_tool("journal", "--kind", "plan.updated",
                           "--data", json.dumps({"updated": built["updated"], "changed": changed}))
            except Stop:
                # Put the plan back, so the next build finds the change again and journals it, rather than finding
                # nothing to do and the journal never saying the plan moved.
                if before is None:
                    path.unlink()
                else:
                    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
                    temporary.write_bytes(before)
                    os.replace(temporary, path)
                raise
            said.append("plan " + ("(" + ", ".join(changed) + ")" if changed else "(first build)"))
        kept = load_json(folder / PREVIEW_FILE) or {}
        facts = {**kept, "slug": slug, "plan": plan.as_posix(), "title": built["outcome"]["summary"][len(PREVIEW_PREFIX):],
                 "commit": commit}
        if facts != kept:
            replace_file(folder / PREVIEW_FILE, json.dumps(facts, indent=2) + "\n")
    return folder, ", ".join(said) or None


# A planning record's plan names at most this many endorsements, as delivery-plan/1 caps them.
PLAN_ENDORSEMENTS = 20


def planning_endorsements(journal: list[dict], seats: dict) -> list[dict]:
    """The endorsements a planning record's plan shows: each seat's latest, capped as delivery-plan/1 caps them."""
    return [{**item, "label": item["label"][:200]} for item in
            plan_sync.latest_endorsements(journal, seats)][:PLAN_ENDORSEMENTS]


def planning_plan_step(c) -> str:
    """The supervisor's pass on a planning record: its plan.json rebuilt when the endorsements or approval its journal
    gives differ from those it shows, as an endorsement ingested from a peer changes them with no command run here."""
    plan = ((load_json(Path(c.state) / "state.json") or {}).get("meta") or {}).get("planFile")
    if not isinstance(plan, str):
        return "no plan file"
    tool = _validator(c.release)
    journal = tool.read_journal(c.state)
    seats = tool.derived_seats(journal)
    shown = (load_json(Path(c.state) / PLAN_FILE) or {}).get("preview") or {}
    _, commit, _ = plan_at_head(c, Path(plan))
    if shown.get("endorsements") == planning_endorsements(journal, seats) \
            and shown.get("approval") == plan_sync.preview_approval(journal, seats, commit):
        return "current"
    return rebuild_planning_plan(c, Path(plan), c.delivery, Path(c.state)) or "current"


def auto_grant_step(c) -> str:
    """With `collab.autoGrant` on, the delivery holder answers each open request for a plan section nobody holds."""
    if shared_seat(c) is None:
        return "unshared"
    given = _validator(c.release)._collab().auto_grants(Path(c.state), enabled=collab_settings(c)["autoGrant"])
    return f"gave {len(given)} plan section(s)" if given else "none asked"


def rebuild_planning_plan(c, plan: Path, key: str, folder: Path) -> str | None:
    """The planning record's plan.json, from the plan at HEAD and its review store by the preview builder, with its
    endorsements and approval from the record's journal: written, and journalled as plan.updated, when it changed.
    Returns what changed, None when nothing did."""
    text, commit, at = plan_at_head(c, plan)
    slug = needed_review_slug(plan, text)
    with open(folder / PREVIEW_LOCK, "a+") as held:
        fcntl.flock(held, fcntl.LOCK_EX)
        store, _ = preview_store(c, slug)
        built, _ = build_preview(c, plan, text, commit, at, store, None)
        tool = _validator()
        journal = tool.read_journal(folder)
        seats = tool.derived_seats(journal)
        built["preview"].update(approval=plan_sync.preview_approval(journal, seats, commit),
                                endorsements=planning_endorsements(journal, seats))
        check_plan(built, c, f"the planning record's plan of {plan}", planning=True)
        path = folder / PLAN_FILE
        old = load_json(path)
        if old is not None and {k: v for k, v in old.items() if k != "updated"} == \
                {k: v for k, v in built.items() if k != "updated"}:
            return None
        changed = [] if old is None else [name for name in sorted({*built, *old})
                                          if name != "updated" and old.get(name) != built.get(name)]
        before = path.read_bytes() if old is not None else None
        replace_file(path, json.dumps(built, indent=2) + "\n")
        try:
            state_tool_at(c, folder, "journal", "--kind", "plan.updated",
                          "--data", json.dumps({"updated": built["updated"], "changed": changed}))
        except Stop:
            # As the preview's: the plan goes back, so the next build finds the change again and journals it.
            if before is None:
                path.unlink()
            else:
                replace_file(path, before.decode("utf-8"))
            raise
        return "plan " + ("(" + ", ".join(changed) + ")" if changed else "(first build)")


def planning_plan_lines(c, plan: Path, key: str, folder: Path) -> list[str]:
    """Once a planning record holds the plan: its plan.json rebuilt, never a preview, and the record's own links."""
    rebuild_planning_plan(c, plan, key, folder)
    shown = Config(repo(), key)
    held, running = read_lock(supervisor_lock_path(shown))
    live = running.get("address") if held else None
    return [f"plan: the planning record of {key}: " + (live or f"its supervisor isn't running; {flow_command()} "
                                                        f"--delivery {key} lead-run --resume starts it"),
            *([line] if (line := hosted_line(shown)) else [])]


def rebuild_plan_view(c, plan: Path) -> str | None:
    """After plan-sync lands: the planning record's plan.json when one holds the plan, else the preview's when it is
    still the plan's own; what was rebuilt, or None."""
    planning = open_planning_record(c, plan)
    if planning:
        said = rebuild_planning_plan(c, plan, *planning)
        return f"the planning record of {planning[0]}: {said}" if said else None
    text, _, _ = plan_at_head(c, plan)
    folder = preview_folder(c, needed_review_slug(plan, text))
    if not (folder / PREVIEW_FILE).is_file() or (folder / PREVIEW_HANDED).exists():
        return None
    _, said = rebuild_preview(c, plan)
    return f"the preview: {said}" if said else None


PREVIEW_HANDED = "handed.json"
PREVIEW_LOG = "live.log"
PREVIEW_FINISH_LOG = "finish.log"
# How long the handed finish waits for the hosted page to hold the handed cut before it stops the processes anyway.
PREVIEW_HANDED_SECONDS = 120


def preview_key(slug: str) -> str:
    """The preview's key: its hosted publisher's, and the one its live port is derived from."""
    return f"plan-{slug}"


def preview_live_config(c, folder: Path) -> dict | None:
    """The live view's state configuration for a preview, derived from the binding: its folder, the one renderer
    `state.liveHome` names, and `liveHome`; no publishers, snapshots, runs page or other renderers. None when the
    binding names no liveHome, or one that isn't an argv renderer."""
    state = binding_state(c) or {}
    home = state.get("liveHome")
    renderer = next((entry for entry in state.get("renderers") or [] if isinstance(entry, dict)
                     and entry.get("id") == home and entry.get("argv")), None)
    if not isinstance(home, str) or renderer is None:
        return None
    return {"directory": str(folder), "renderers": [renderer], "liveHome": home}


def preview_hosted_on(c) -> bool:
    try:
        return hosted_settings(c) is not None
    except Stop:
        return True  # configured, if not validly: the publisher's own answer says why


def start_preview_live(c, folder: Path, slug: str, config: dict) -> str:
    """The preview's live view: the one `live.json` names, while it serves from this generation's render_state.py;
    otherwise one started detached, a running one of another generation stopped by its recorded pid first, on the
    recorded port, else the one derived from the main checkout and the preview's key, else a free one. Its address."""
    script = str((c.release / "skills/orchestrate-work/scripts/render_state.py").resolve())
    live = recorded_live(folder)
    if live and pid_runs(live["pid"]) and listens(live["pid"], live["port"]):
        if live.get("renderState") == script:
            return live_address(live["port"])
        stop_view(folder)
        free = time.monotonic() + 10
        while port_open(live["port"]) and time.monotonic() < free:
            time.sleep(0.1)
    wanted = (live.get("port") or 0) if live_port_setting() == 0 else wanted_live_port(folder, live_top(c),
                                                                                         preview_key(slug))
    holders = port_takers(wanted) if wanted else []
    argv = [sys.executable, "-B", script, "live", "--dir", str(folder), "--repo", str(c.root), "--state-config",
            json.dumps(config), "--preview"]
    log = folder / PREVIEW_LOG
    started = spawn_live_view([*argv, "--port", str(0 if holders else wanted)], log, c.root, 0 if holders else wanted)
    if started is None:  # the port was taken between the look and the bind
        holders = port_takers(wanted)
        started = spawn_live_view([*argv, "--port", "0"], log, c.root, 0)
    proc, bound = started
    record = {"port": bound, "pid": proc.pid, "renderState": script, "startedAt": now(), "address": live_address(bound)}
    if holders:
        record["fallback"] = {"wanted": wanted, "heldBy": [{"pid": pid, "command": command} for pid, command in holders]}
    replace_file(folder / LIVE_FILE, json.dumps(record, indent=2) + "\n")
    return record["address"]


def start_preview_hosted(c, folder: Path, slug: str) -> str:
    """The hosted line for a preview: its link once the publisher has one, or why it wasn't published."""
    try:
        member = hosted_settings(c)[1]
    except Stop as error:
        return f"not published: {error}"
    if HOSTED_TOKENS.get((member["tokenEnv"], member["origin"], member["repositoryId"])) is None:
        return f"not published: {member['tokenEnv']} is unset"
    try:
        answer = hosted_call(c, "start", folder, preview_key(slug), archive=False)
        deadline = time.monotonic() + 15
        while not answer.get("url") and not answer.get("error") and time.monotonic() < deadline:
            time.sleep(0.2)
            answer = hosted_call(c, "status", folder, preview_key(slug), archive=False)
    except (Stop, OSError, ValueError, subprocess.SubprocessError):
        return "not published: publisher_unavailable"
    if answer.get("url"):
        return answer["url"]
    return f"not published: {answer.get('error') or answer.get('code') or answer.get('state') or 'no answer'}"


def preview_lines(c, plan: Path) -> list[str]:
    """Build the plan's preview, serve and publish it, and say where: nothing at all where the repository has no
    live view and no hosted configuration. After a delivery adopted the review, the handed finish instead."""
    planning = open_planning_record(c, plan)
    if planning:
        return planning_plan_lines(c, plan, *planning)
    live_on = preview_live_config(c, Path(".")) is not None
    if not live_on and not preview_hosted_on(c):
        return []
    text, _, _ = plan_at_head(c, plan)
    slug = needed_review_slug(plan, text)
    folder = preview_folder(c, slug)
    _, adopted = preview_store(c, slug)
    if adopted:
        if (folder / PREVIEW_HANDED).exists() or not folder.is_dir():
            return [f"plan preview: the review of {plan} was adopted by delivery {adopted['delivery']}; its plan shows "
                    "on that delivery's own views"]
        return [preview_handed_finish(c, folder, plan, adopted)]
    rebuild_preview(c, plan)
    links = {}
    if live_on:
        links["live"] = start_preview_live(c, folder, slug, preview_live_config(c, folder))
    hosted = start_preview_hosted(c, folder, slug) if preview_hosted_on(c) else None
    if hosted and hosted.startswith("https://"):
        links["hosted"] = hosted
    kept = load_json(folder / PREVIEW_FILE) or {}
    if {**kept, **links} != kept:
        replace_file(folder / PREVIEW_FILE, json.dumps({**kept, **links}, indent=2) + "\n")
    return [*([f"plan preview: {links['live']}"] if live_on else []),
            *([f"plan preview (hosted): {hosted}"] if hosted else [])]


def preview_handed_finish(c, folder: Path, plan: Path, adopted: dict) -> str:
    """Once a delivery adopts the review: mark the preview handed and start one detached finisher, which rebuilds it as
    handed, waits for the hosted page to hold that cut, then stops the preview's processes. Returns at once."""
    with open(folder / PREVIEW_FINISH_LOG, "a") as out:
        finisher = subprocess.Popen([sys.executable, "-B", str(Path(__file__).resolve()), "plan-view", "--plan",
                                     plan.as_posix(), "--finish-handed"], cwd=c.root, stdin=subprocess.DEVNULL,
                                    stdout=out, stderr=subprocess.STDOUT, start_new_session=True)
    # Marked once its finisher runs, so a finish that couldn't start is started again by the next plan-view. The
    # finisher's pid says when the finish is over: once it has gone, nothing more is written in the folder.
    replace_file(folder / PREVIEW_HANDED, json.dumps({"delivery": adopted["delivery"], "at": now(),
                                                       "finisher": finisher.pid}, indent=2) + "\n")
    return f"plan preview: handed to delivery {adopted['delivery']}; its preview stops once the hosted page shows that"


def preview_publisher_runs(c, folder: Path) -> bool:
    """Whether the hosted publisher the preview's folder records runs, as the publisher itself identifies it."""
    try:
        module = hosted_module(c.release)
        return bool(module.process_matches(module.read_json(folder / module.OWNER, optional=True)))
    except (OSError, ValueError, RuntimeError, ImportError):
        return False


def preview_publisher_sequence(c, folder: Path) -> int:
    """The highest sequence the preview's publisher holds: its accepted cut's, or a pending one's."""
    module = hosted_module(c.release)
    identity = module.read_json(folder / module.IDENTITY, optional=True) or {}
    return max([identity.get("sequence") or 0,
                *((part or {}).get("sequence") or 0 for part in (identity.get("receipt"), identity.get("pending")))])


def finish_handed(c, plan: Path) -> None:
    """The detached finisher: rebuild the preview as handed, wait up to PREVIEW_HANDED_SECONDS for the hosted page to
    hold a cut published after that rebuild, then stop the hosted publisher and the live view by their recorded pids.
    The live view stops last, and its log line is written before it is signalled: once the publisher and the view have
    both gone, the finish writes nothing more in the preview's folder."""
    text, _, _ = plan_at_head(c, plan)
    slug = needed_review_slug(plan, text)
    folder = preview_folder(c, slug)
    key = preview_key(slug)
    hosted = preview_hosted_on(c) and preview_publisher_runs(c, folder)
    # The mark names who the preview is handed to, and is written just after this finisher starts.
    marked = time.monotonic() + 10
    while not (folder / PREVIEW_HANDED).exists() and time.monotonic() < marked:
        time.sleep(0.05)
    try:
        rebuild_preview(c, plan)
    finally:
        if hosted:
            # A cut the publisher holds now, accepted or on its way, was collected before the handed rebuild: the
            # handed cut is the first one numbered after all of them.
            held = preview_publisher_sequence(c, folder)
            deadline = time.time() + PREVIEW_HANDED_SECONDS
            print(f"{now()} hosted: waiting for a cut after sequence {held} until {deadline}", flush=True)
            while time.time() < deadline:
                status = hosted_call(c, "status", folder, key, archive=False)
                if status.get("state") == "current" and (status.get("receipt") or {}).get("sequence", 0) > held:
                    break
                time.sleep(0.5)
            print(f"{now()} hosted: {json.dumps(hosted_call(c, 'stop', folder, key, archive=False))}", flush=True)
        live = recorded_live(folder)
        if not live or not pid_runs(live["pid"]):
            print(f"{now()} live: not running", flush=True)
        elif not is_view(live["pid"]):
            print(f"{now()} live: left pid {live['pid']} alone: live.json names it, but it no longer runs the live "
                  "view", flush=True)
        else:
            print(f"{now()} live: stopping the live view (pid {live['pid']}) on port {live['port']}", flush=True)
            stop_view_process(live["pid"], live["port"])


def stop_preview(c, plan: Path) -> list[str]:
    """Stop the preview's hosted publisher and live view, each by the pid its folder records, and nothing else."""
    text, _, _ = plan_at_head(c, plan)
    folder = preview_folder(c, needed_review_slug(plan, text))
    if not folder.is_dir():
        return [f"plan preview: {plan} has no preview"]
    lines = []
    if preview_hosted_on(c) and (folder / "hosted-view-config.json").exists():
        answer = hosted_call(c, "stop", folder, preview_key(folder.name), archive=False)
        lines.append(f"plan preview (hosted): {answer.get('state') or answer.get('error') or 'no answer'}")
    lines.append(f"plan preview: {stop_view(folder) or 'not running'}")
    return lines


def preview_quietly(plan: str) -> None:
    """After a plan-review command: the preview's links, or why it wasn't built; never the command's own outcome."""
    global CFG
    try:
        c = CFG = preview_config(plan)
        for line in preview_lines(c, Path(plan)):
            print(line)
    except (Stop, OSError, ValueError, subprocess.SubprocessError) as error:
        print(f"plan preview: not built: {error}")


def preview_config(given: str):
    c = Config(repo(), need_delivery=False, pick=False)
    plan = Path(given)
    if plan.is_absolute():
        try:
            plan = plan.resolve().relative_to(c.root.resolve())
        except ValueError:
            raise Stop(f"{given} isn't inside this checkout, {c.root}")
    c.preview_plan = plan
    return c


def plan_view_command(args) -> None:
    """`plan-view --plan PATH`: build or rebuild the plan's preview from the plan at HEAD and its review store, serve it
    on its own live view and publish it where the repository configures those, and print its links. Needs no
    delivery file, record, tracker or forge. `--stop` stops what the preview runs."""
    global CFG
    c = CFG = preview_config(args.plan)
    if args.finish_handed:
        finish_handed(c, c.preview_plan)
        return
    for line in (stop_preview if args.stop else preview_lines)(c, c.preview_plan):
        print(line)


def lead_plan_checkout(c) -> Path:
    """The lead's checkout a plan change or approval commits in: on the base branch, as before, or a lead's own
    worktree on its own branch (several deliveries on one machine, the operator's checkout holding the base), whose
    HEAD is the base's tip or ahead of it with this delivery's own delivery file and plan commits only. Either is
    clean and holds the base; a story branch is a lane's. A lead worktree then reads its own working tree."""
    root = c.root
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=root)
    refuse_story_branch(c, branch, "lead-plan")
    if git("status", "--porcelain", cwd=root):
        raise Stop(f"{root} has uncommitted changes; commit or remove them first, so the plan change commits alone")
    git("fetch", "-q", c.remote, c.base_branch, cwd=root)
    if not is_ancestor(c.base_ref, "HEAD"):
        if is_ancestor("HEAD", c.base_ref):
            raise Stop(f"{root} is behind {c.base_ref}; bring it up to date first: git merge --ff-only {c.base_ref}")
        raise Stop(f"{root} has diverged from {c.base_ref}; bring it up to date first")
    if branch == c.base_branch:
        return root
    check_lead_plan_commits(c, c.base_ref, "HEAD")
    # What the base holds, plus this delivery's own unpushed plan commits: the working tree is the plan to change.
    # Read it again through that shelf, so the stories a change names (a removal's units, say) are the worktree's.
    c.shelf = Shelf(root)
    c.load_delivery(c.delivery)
    return root


def refuse_story_branch(c, branch: str, command: str) -> None:
    stories = {key for delivery in c.delivery_files().values() for key in delivery.get("stories", {})}
    if any(branch == c.branch(key) for key in stories):
        raise Stop(f"run {command} in the lead's checkout of {c.base_branch}, or in a lead worktree of its own; "
                   f"{branch} is a story branch")


def check_lead_plan_commits(c, base: str, head: str) -> None:
    root = c.root
    own = {f"{c.deliveries_rel}/{c.delivery}.json", Path(c.plan).as_posix()}
    for sha in git("rev-list", "--reverse", f"{base}..{head}", cwd=root).split():
        # --cc lists what a merge itself adds beyond its parents, nothing for a clean one; -z keeps any path whole.
        changed = run(["git", "diff-tree", "--no-commit-id", "--name-only", "-r", "-z", "--cc", sha], cwd=root).stdout
        foreign = [name for name in changed.split("\0") if name and name not in own]
        if foreign:
            subject = git("log", "-1", "--format=%s", sha, cwd=root)
            raise Stop(f"{root} is ahead of {c.base_ref} with {sha[:12]} ({subject}), which changes "
                       f"{', '.join(foreign)}: a lead worktree off {c.base_branch} may be ahead with only "
                       f"{c.delivery}'s own delivery file and plan; push that commit or drop it first")


def plan_publish_command(c) -> str:
    if (c.state / "state.json").is_file():
        return f"{flow_command()} --delivery {shlex.quote(c.delivery)} lead-push"
    return shlex.join(["git", "push", c.remote, f"HEAD:{c.base_branch}"])


def lead_plan(args) -> None:
    """Record a change to the approved plan in the delivery file, or a reason for one already recorded."""
    c = cfg()
    if args.action == "change":
        # A flag the kind doesn't read is refused rather than ignored: --criterion on a story's removal once removed
        # the whole story. --lane and --after are for a story --kind added brings into the delivery.
        takes = {"subjects": ("added", "removed", "relaxed", "changed", "lenses"),
                 "criterion": ("added", "removed", "relaxed", "changed"),
                 "text": ("added", "relaxed", "changed", "finish"), "lane": ("added",), "after": ("added",),
                 "finish": ("finish",), "covers": ("finish",), "label": ("finish",), "lenses": ("lenses",)}
        for flag, kinds in takes.items():
            given = getattr(args, flag) != [] if flag == "subjects" else getattr(args, flag) is not None  # --subjects defaults to []
            if given and args.kind not in kinds:
                raise Stop(f"--kind {args.kind} doesn't use --{flag}; it is for --kind {' or '.join(kinds)}")
    dropping = args.action == "change" and args.kind == "removed" and args.criterion is not None
    log = read_plan_log(c)
    if not plan_declared(c) and not any(entry["type"] == "snapshot" for entry in log):
        raise Stop(f"{c.delivery_where} declares no criteria, so the plan chapter is off; add criteria to its stories first")
    # Its rebuild registers any story added since, so a story registration would refuse is refused before anything
    # is written; one this change removes needs no reason.
    if (c.state / "state.json").exists():
        removing = set(args.subjects or []) if args.action == "change" and args.kind == "removed" and not dropping else set()
        problems = unreasoned_problems(c, [key for key in unregistered(c, load_state()["state"]) if key not in removing])
        if problems:
            raise unreasoned_refusal(c, problems)
    if args.action == "why":
        with plan_lock(c):
            log = read_plan_log(c)
            if not any(entry["type"] == "change" and entry["id"] == args.change for entry in log):
                raise Stop(f"no recorded change {args.change}; the changes are in {plan_log_path(c)}")
            append_plan_log(c, {"type": "why", "change": args.change, "why": args.why})
            rebuild_plan(c)
        print(f"recorded the reason for {args.change}")
        return
    root = lead_plan_checkout(c)
    raw = json.loads(c.delivery_path.read_text())
    if args.action == "approval":
        plan_approval(c, raw, args)
        return
    stories = raw["stories"]
    change: dict = {"kind": args.kind, "subjects": args.subjects or [], "by": args.by, "why": args.why, "source": "lead-plan"}
    for key in ("title", "ref"):
        if getattr(args, key):
            change[key] = getattr(args, key)
    new_story = args.kind == "added" and len(change["subjects"]) == 1 and change["subjects"][0] not in stories
    unknown = [key for key in change["subjects"] if key not in stories]
    if unknown and not new_story:
        raise Stop(f"{', '.join(unknown)} isn't a story of {c.delivery}")
    planned_after = None
    record_finish = None
    reword_finish = None
    wording = None  # a finish line's (before, after) wording, recorded as its own change when its covers change too
    plan_text = None
    if new_story:
        # The whole story in one change: its plan heading, its delivery-file story carrying the reason its `added`
        # change gives, and its planned entry, so registration has nothing left to refuse.
        key = change["subjects"][0]
        if not args.title or not args.text or not args.lane:
            raise Stop(f"{key} isn't a story of {c.delivery} yet: --kind added adds it whole with --title, --text (its "
                       "first criterion) and --lane, with --after for the stories it comes after")
        if args.lane not in c.lanes:
            raise Stop(f"--lane {args.lane} isn't a lane of {c.delivery}: {', '.join(c.lanes)}; add it first with "
                       f"lead-add-lane --lane {args.lane}")
        after = args.after or []
        held = sibling_story_keys(getattr(c, "state", None))
        strangers = [other for other in after if other not in stories and other not in held]
        if strangers:
            raise Stop(f"--after {', '.join(strangers)} isn't a story of {c.delivery} or of a sibling delivery it has "
                       "read")
        problem = why_problem(c, args.why)
        if problem:
            raise Stop(f"{key} {problem}: --why is one line saying why it joins the delivery")
        ident = args.criterion or f"{key.lower()}-1"
        if ident in [item["id"] for story in stories.values() for item in story.get("criteria", [])]:
            raise Stop(f"criterion {ident} already exists")
        stories[key] = {"title": args.title, "lane": args.lane, "why": args.why,
                        "criteria": [{"id": ident, "text": args.text}], **({"after": after} if after else {})}
        current = (c.root / c.plan).read_text()
        if story_section(plan_sections(current), key) is None:
            plan_text = plan_with_story(current, key, args.title, args.lane, after, args.why)
    elif args.kind in ("added", "changed", "relaxed"):
        if len(change["subjects"]) != 1 or not args.criterion or args.text is None:
            raise Stop(f"--kind {args.kind} takes one story in --subjects, --criterion and --text")
        for flag in ("lane", "after"):
            if getattr(args, flag) is not None:
                raise Stop(f"{change['subjects'][0]} is already a story of {c.delivery}, so --kind added doesn't use "
                           f"--{flag}; it is for a story not yet in the delivery")
        criteria = stories[change["subjects"][0]].setdefault("criteria", [])
        existing = next((item for item in criteria if item["id"] == args.criterion), None)
        taken = [item["id"] for story in stories.values() for item in story.get("criteria", [])]
        if args.kind == "added":
            if args.criterion in taken:
                raise Stop(f"criterion {args.criterion} already exists")
            criteria.append({"id": args.criterion, "text": args.text})
        else:
            if existing is None:
                raise Stop(f"{change['subjects'][0]} has no criterion {args.criterion}")
            change["before"] = existing["text"]
            existing["text"] = args.text
        change.update(criteria=[args.criterion], after=args.text)
    elif args.kind == "lenses":
        # The story's brief lenses, recorded as a `changed` change carrying the lenses it leaves; '' removes them.
        if len(change["subjects"]) != 1 or args.lenses is None:
            raise Stop("--kind lenses takes one story in --subjects and --lenses, the lens ids its brief asks for "
                       "('' for none)")
        key = change["subjects"][0]
        named = [lens.strip() for lens in args.lenses.split(",") if lens.strip()]
        story = f"the declared story lenses are {', '.join(c.story_lenses)}"
        for lens in named:
            if lens not in c.story_lenses:
                raise Stop(f"--lenses names {lens}, which isn't a declared story lens; {story}")
        if len(set(named)) != len(named):
            raise Stop(f"--lenses names a lens more than once; {story}")
        before = stories[key].get("lenses", [])
        after = [lens for lens in c.story_lenses if lens in named]
        added = [lens for lens in after if lens not in before]
        started = (c.state / "state.json").exists() and any(
            e.get("kind") == "review.started" and e.get("subject") == key and e["data"].get("round") == 1
            for e in load_state()["journal"])
        if added and started:
            raise Stop(f"{key}'s review has begun, and its lens set is fixed at round 1, so its brief can't add "
                       f"{', '.join(added)}; a review the story missed belongs in a follow-up. Removing a brief lens "
                       "is accepted")
        if after == before:
            raise Stop(f"{key}'s brief lenses are already {', '.join(after) or 'none'}: nothing to change")
        if after:
            stories[key]["lenses"] = after
        else:
            stories[key].pop("lenses", None)
        change.update(kind="changed", lenses=after, before=lenses_words(before), after=lenses_words(after))
    elif dropping:
        # One criterion leaves the story, which stays; the change keeps its wording, and no `after` says it is gone.
        if len(change["subjects"]) != 1:
            raise Stop("--kind removed with --criterion drops that criterion from one story in --subjects")
        key = change["subjects"][0]
        criteria = stories[key].get("criteria", [])
        existing = next((item for item in criteria if item["id"] == args.criterion), None)
        if existing is None:
            raise Stop(f"{key} has no criterion {args.criterion}")
        if len(criteria) == 1:
            raise Stop(f"{args.criterion} is {key}'s last criterion; a story keeps at least one, so remove the story "
                       f"instead, with --kind removed --subjects {key}")
        naming = [line["id"] for line in raw.get("finish", [])
                  if isinstance(plan_covers(line).get("criteria"), list) and args.criterion in plan_covers(line)["criteria"]]
        if naming:
            raise Stop(f"finish line {', '.join(naming)} covers {args.criterion}; take it out of its --covers first, with "
                       f"--kind finish")
        criteria.remove(existing)
        change.update(criteria=[args.criterion], before=existing["text"])
    elif args.kind == "removed":
        if not change["subjects"]:
            raise Stop("--kind removed names the stories it removes in --subjects")
        doc = load_state()
        queued = [q["subject"] for q in doc["state"]["queue"] if q["subject"] in change["subjects"]]
        if queued:
            raise Stop(f"{', '.join(queued)} is already in the queue; it can't be removed from the plan")
        change["units"] = [plan_unit(c, key) for key in change["subjects"]]
        for key in change["subjects"]:
            del stories[key]
        planned_after = True
    elif args.kind == "finish":
        lines = raw.setdefault("finish", [])
        line = next((item for item in lines if item["id"] == args.finish), None) if args.finish else None
        # An existing line's wording alone may change: --text without --covers keeps what it covers.
        if not args.finish or (args.covers is None and (line is None or args.text is None)):
            raise Stop("--kind finish takes --finish <id> and --covers <JSON>; an existing line's --text alone "
                       "rewords it")
        try:
            covers = json.loads(args.covers) if args.covers is not None else plan_covers(line)
        except ValueError:
            raise Stop("--covers must be JSON, such as {\"criteria\": \"all\", \"proofs\": [\"merged\"]}")
        if line is None:
            if not args.text:
                raise Stop(f"finish line {args.finish} is new: give its --text")
            line = {"id": args.finish, "text": args.text, **({"label": args.label} if args.label else {})}
            lines.append(line)
            record_finish = {"id": args.finish, "text": args.text, "met": False}
            change.update(after=covers)
        else:
            if args.label is not None:
                raise Stop(f"finish line {args.finish} already exists, so --kind finish doesn't use --label; it is for a "
                           "new line")
            reworded = args.text is not None and args.text != line["text"]
            if not reworded and covers == plan_covers(line):
                raise Stop(f"finish line {args.finish} already reads so and covers that: nothing to change")
            # What changed is recorded: what it covers, and its wording when that moved, as a change of its own.
            if covers != plan_covers(line):
                change.update(before=plan_covers(line), after=covers)
                if reworded:
                    wording = (line["text"], args.text)
            else:
                change.update(before=line["text"], after=args.text)
            if reworded:
                reword_finish = (args.finish, args.text)
                line["text"] = args.text
        line.update(covers=covers, at=now())
        change.update(finish=args.finish)
    with plan_lock(c):
        # A delivery started before its criteria has no snapshot yet: it is taken of the plan before this change.
        if (c.state / "state.json").exists() and not any(entry["type"] == "snapshot" for entry in read_plan_log(c)):
            write_snapshot(c, late=True)
        original = c.delivery_path.read_text()
        plan_path = c.root / c.plan
        plan_original = plan_path.read_text() if plan_text is not None else None
        c.delivery_path.write_text(json.dumps(raw, indent=2) + "\n")
        if plan_text is not None:
            plan_path.write_text(plan_text)
        try:
            c.load_delivery(c.delivery)
            check_plan(build_plan(c, read_plan_log(c) or [snapshot_entry(c, late=True)]), c)
        except Stop:
            c.delivery_path.write_text(original)
            if plan_original is not None:
                plan_path.write_text(plan_original)
            c.load_delivery(c.delivery)
            raise
        git("add", str(c.delivery_path), *([str(plan_path)] if plan_text is not None else []), cwd=root)
        entry = record_plan_change(c, change)
        ids = entry["id"]
        if wording is not None:
            ids += f" and {record_plan_change(c, {**change, 'before': wording[0], 'after': wording[1]})['id']}"
        said = f"{'added story' if new_story else args.kind} {', '.join(change['subjects']) or change.get('finish', '')}".rstrip()
        if dropping:
            said = f"removed {args.criterion} from {change['subjects'][0]}"
        tool_commit("commit", "-q", "-m", f"{c.delivery}: plan change {ids} ({said})", cwd=root)
        if planned_after is not None:  # as it stands now: a story registered since the check above stays planned
            patch_from(lambda doc: {"planned": [p for p in doc["state"].get("planned", [])
                                                if p["subject"] not in change["subjects"]]}, "the plan change's planned work")
        if record_finish is not None:
            patch_from(lambda doc: {"finish": [*doc["state"]["finish"], record_finish]}, "the new finish line")
        if reword_finish is not None and (c.state / "state.json").exists():  # the record's line reads as the plan's
            ident, text = reword_finish
            patch_from(lambda doc: None if all(line["id"] != ident or line["text"] == text for line in doc["state"]["finish"])
                       else {"finish": [{**line, "text": text} if line["id"] == ident else line
                                        for line in doc["state"]["finish"]]}, "the reworded finish line")
        if new_story and (c.state / "state.json").exists():
            # Planned here, so the rebuild's registration finds it held and records no second `added` change.
            key = change["subjects"][0]
            patched = patch_from(lambda doc: None if any(item["subject"] == key for item in
                                                        [*doc["state"]["queue"], *doc["state"].get("planned", [])])
                                 else {"planned": [*doc["state"].get("planned", []), planned_entry(c, key)],
                                       "followups": [f for f in doc["state"]["followups"]
                                                     if key not in (f["id"], f.get("reference"))]},
                                 "the added story's planned work")
            if patched is not None:
                state_tool("journal", "--kind", "story.added", "--subject", key, "--data", json.dumps(story_added(c, key, change.get("why"))))
                if (approved := story_approved(c, key)) is not None:
                    state_tool("journal", "--kind", "story.approved", "--subject", key, "--data", json.dumps(approved))
        rebuild_plan(c)
    print(f"recorded {ids}: {said}" if dropping else
          f"recorded {ids}: {args.kind} {', '.join(change['subjects']) or change.get('finish', '')}".rstrip())
    print(f"committed the delivery file{' and the plan' if plan_text is not None else ''}; push it so lanes see it: "
          f"{plan_publish_command(c)}")


def plan_approval(c, raw: dict, args) -> None:
    """Mark one approval done or waiting, with lead-plan change's discipline: one commit, never a push."""
    entry = next((item for item in raw.get("approvals") or [] if item.get("id") == args.id), None)
    if entry is None:
        raise Stop(f"no approval {args.id} in {c.delivery_where}; an approval without an id is changed by hand")
    entry["state"] = args.state
    if args.who:
        entry["who"] = args.who
    with plan_lock(c):
        original = c.delivery_path.read_text()
        c.delivery_path.write_text(json.dumps(raw, indent=2) + "\n")
        try:
            c.load_delivery(c.delivery)
            check_plan(build_plan(c, read_plan_log(c) or [snapshot_entry(c, late=True)]), c)
        except Stop:
            c.delivery_path.write_text(original)
            c.load_delivery(c.delivery)
            raise
        git("add", str(c.delivery_path), cwd=c.root)
        tool_commit("commit", "-q", "-m", f"{c.delivery}: approval {args.id} {args.state}", cwd=c.root)
        rebuild_plan(c)
    print(f"approval {args.id}: {args.state}")
    print(f"committed the delivery file; push it so lanes see it: "
          f"{plan_publish_command(c)}")


def archive_plan_review(archive: Path) -> Path | None:
    """The plan review's store, without its checkouts, copied into a delivery's archive."""
    c = cfg()
    source = plan_review_dir(c)
    if not source.exists():
        return None
    target = archive / "plan-review"
    shutil.copytree(source, target, ignore=lambda folder, names: ["checkouts"] if Path(folder) == source else [])
    return target


# -- setup refusals ------------------------------------------------------------------------

def supervisor_lock_path(c) -> Path:
    """The lock the delivery's supervisor holds while it runs. It records {pid, startedAt, children}."""
    return c.flow_log / f"{c.delivery}.supervisor.lock"


def read_lock(path: Path) -> tuple[bool, dict]:
    """(whether a process holds the lock, what the lock file records)."""
    if not path.exists():
        return False, {}
    with open(path, "a+") as probe:
        try:
            fcntl.flock(probe, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fcntl.flock(probe, fcntl.LOCK_UN)
            held = False
        except BlockingIOError:
            held = True
    try:
        recorded = json.loads(path.read_text() or "{}")
    except ValueError:
        recorded = {}
    return held, recorded if isinstance(recorded, dict) else {}


def record_started(c, journal: list[dict]) -> str:
    if journal:
        return journal[0]["at"]
    stamp = (c.state / "state.json").stat().st_mtime
    return datetime.datetime.fromtimestamp(stamp, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def record_base(journal: list[dict]) -> str | None:
    """The base ref a record started on: its record.started's base."""
    for entry in journal:
        if entry.get("kind") == "record.started":
            return entry["data"]["base"]["ref"]
    return None


def stale_record(c) -> str | None:
    """What an earlier lead-init left where this one would start: a record, a supervisor's lock, or a plan snapshot.
    A lead-plan change made before lead-init, and plan.lock, are this delivery's own and don't count."""
    fix = ("fix: run lead-init --replace, which stops its supervisor and archives the record and the flow log, "
           "carrying nothing over; or give this delivery its own stateDirectory, in a folder of its own, since the "
           "flow log sits beside it")
    if (c.state / "state.json").exists():
        try:
            doc = load_state()
        except Stop as unreadable:
            return f"{c.state} already holds a record the state tool can't read ({unreadable}); {fix}"
        meta, journal = doc["state"]["meta"], doc["journal"]
        name = meta.get("trackerParent") or meta.get("headline") or "with no name"
        base = record_base(journal) or (c.base_ref if name == c.delivery else "an unrecorded base")
        return f"{c.state} already holds a record: delivery {name} on {base}, started {record_started(c, journal)}; {fix}"
    lock = supervisor_lock_path(c)
    if lock.exists():
        held, recorded = read_lock(lock)
        who = f"held by pid {recorded.get('pid')}" if held else "which no process holds"
        return (f"{lock} holds the supervisor lock of delivery {c.delivery} on {c.base_ref}, {who}, started "
                f"{recorded.get('startedAt', 'at an unrecorded time')}; {fix}")
    snapshot = next((entry for entry in read_plan_log(c) if entry["type"] == "snapshot"), None)
    if snapshot:
        return (f"{c.flow_log} already holds the plan snapshot of delivery {c.delivery} on {c.base_ref}, taken "
                f"{snapshot['at']}; {fix}")
    return None


def process_gone(pid: int) -> bool:
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return True
    except PermissionError:
        return False
    return False


def stop_supervisor(c) -> str | None:
    """Stop the process holding the supervisor lock, by the pid it recorded, and confirm it is gone."""
    lock = supervisor_lock_path(c)
    held, recorded = read_lock(lock)
    if not held:
        return None
    pid = recorded.get("pid")
    if not isinstance(pid, int) or isinstance(pid, bool) or pid <= 1:
        raise Stop(f"{lock} is held, but records no pid to stop; fix: stop the delivery's supervisor yourself, then "
                   "run lead-init --replace again")
    for sig, wait in ((signal.SIGTERM, 10), (signal.SIGKILL, 5)):
        try:
            os.killpg(pid, sig)  # the supervisor leads its own session, so its children go with it
        except ProcessLookupError:
            try:
                os.kill(pid, sig)
            except ProcessLookupError:
                pass
        except PermissionError:
            raise Stop(f"the supervisor in {lock} (pid {pid}) can't be stopped from here; fix: stop it as its own user, "
                       "then run lead-init --replace again")
        deadline = time.monotonic() + wait
        while time.monotonic() < deadline:
            if process_gone(pid) and not read_lock(lock)[0]:
                return f"stopped the supervisor (pid {pid})"
            time.sleep(0.1)
    raise Stop(f"the supervisor in {lock} (pid {pid}) is still running after SIGKILL; fix: stop it, then run lead-init "
               "--replace again")


def archive_root(c) -> Path:
    return Path(expand((c.flow_raw.get("cleanup") or {}).get("archive", DEFAULT_ARCHIVE), repo=c.main.name,
                       delivery=c.delivery))


def replace_record(c) -> list[str]:
    """lead-init --replace: stop any supervisor, then move the record and the flow log into the archive. Nothing
    carries over: every flow-log file names entries of the archived journal, whose ids the fresh one reuses."""
    held, recorded = read_lock(supervisor_lock_path(c))
    if held:
        # Before the signal, so the supervisor's own handler finds it and the archived record keeps it.
        write_supervisor_status(c.state, recorded.get("pid"), False, "replaced")
    said = [line for line in [stop_supervisor(c), stop_view(c.state), stop_full_health_run(c)] if line]
    present = [path for path in (c.state, c.flow_log) if path.exists()]
    if present:
        archive = archive_root(c) / (datetime.datetime.now().strftime("%Y%m%dT%H%M%S.%f") + "-replaced")
        archive.mkdir(parents=True)
        for source in present:
            shutil.move(str(source), str(archive / source.name))
        said.append(f"archived the record and the flow log in {archive}")
    return said


def plan_problems(c, keys: list[str]) -> list[str]:
    """Each story with no section in the plan, which its lane's review context is drawn from."""
    text = c.shelf.text(c.plan)
    if text is None:
        return [f"no plan at {c.shelf.where(c.plan)}; fix: commit the plan there, or correct `plan` in {c.delivery_where}"]
    sections = plan_sections(text)
    missing = [key for key in keys if story_section(sections, key) is None]
    if not missing:
        return []
    return [f"stories with no plan section: {', '.join(missing)}; fix: add a heading naming each to {c.plan}, or "
            f"correct its key in {c.delivery_where}"]


# Ownership comes from the record, or from the delivery file for a legacy record. These helpers warn
# before a lane starts of the files its story will need: the ones its plan names, and (for lead-assign) the ones that
# have tended to change with them.

PATH_TOKEN = re.compile(r"[A-Za-z0-9._*?\[\]-][A-Za-z0-9._/*?\[\]-]*")
CO_CHANGE = {"commits": 200, "sweep": 40, "support": 3, "share": 0.25, "shown": 5}


def shared_outputs(c) -> set[str]:
    regenerable = c.binding.get("regenerable") or {}
    if not regenerable.get("regenerators"):
        return set()
    return {entry["path"] for entry in regenerable.get("listings", [])}


def owners_of(ownership: dict, path: str) -> list[str]:
    return [lane for lane, patterns in ownership.items() if any(fnmatch.fnmatchcase(path, g) for g in patterns)]


def owner_of(c, path: str) -> str | None:
    return next(iter(owners_of(c.effective_ownership(c.record_state()), path)), None)


def owned_by(c, lane: str, path: str) -> bool:
    state = c.record_state()
    claims = [claim for claim in state.get("laneRegions", []) if claim["path"] == path]
    if claims:
        helper = _region_ownership()
        base = git("rev-parse", files_ref(c))
        mine = [claim for claim in claims if claim["lane"] == lane]
        try:
            for claim in mine:
                helper.mapped(c.root, claim, base)
        except helper.RegionError:
            return False
        return bool(mine)
    return path in shared_outputs(c) or owners_of(c.effective_ownership(state), path) == [lane]


def ownership_overlaps(ownership: dict, files: list[str], shared: set[str]) -> list[str]:
    # Check real paths and claim patterns. A new path not on the base is checked for a unique owner at admission.
    paths = set(files) | {pattern for patterns in ownership.values() for pattern in patterns}
    return [f"{' and '.join(lanes)} both own {path}" for path in sorted(paths - shared)
            if len(lanes := owners_of(ownership, path)) > 1]


def candidate_ownership(c, lane: str, base: str, head: str, state: dict) -> tuple[list[str], list[str]]:
    regions = state.get("laneRegions", [])
    if regions:
        helper = _region_ownership()
        try:
            changed = helper.changed_paths(c.root, base, head)
            outside = helper.problems(c.root, lane, base, head, changed, regions)
        except helper.RegionError as error:
            raise Stop(f"writer_not_owned: {error}") from error
        regional_paths = {claim["path"] for claim in regions}
    else:
        changed = list(filter(None, run(["git", "diff", "--no-renames", "--name-only", "-z", base, head]).stdout.split("\0")))
        outside, regional_paths = {}, set()
    ownership = c.effective_ownership(state)
    if "laneOwnership" not in state:
        return changed, [path for path in changed if lane not in owners_of(ownership, path)]
    shared = shared_outputs(c)
    return changed, [f"{path}: {outside[path]}" if path in outside else path for path in changed
                     if path in outside or (path not in regional_paths and path not in shared
                                            and owners_of(ownership, path) != [lane])]


def claims_report(c, helper, lane: str, key: str, base: str, head: str, state: dict) -> tuple[list[str], list[str]]:
    """Decision 7: the committed change from ``base`` to ``head`` against ``lane``'s claims, as (held, needed): what
    a whole-file claim, a span or a shared output holds, and each hunk, creation, deletion, mode or binary change the
    lane still needs a claim for, with the lead's request for it. ``head`` may be a tree."""
    regions = state.get("laneRegions", [])
    ownership = c.effective_ownership(state)
    shared = shared_outputs(c)
    command = flow_command()
    held, needed = [], []
    for path in helper.changed_paths(c.root, base, head):
        on_path = [claim for claim in regions if claim["path"] == path]
        if path in shared:
            held.append(f"{path}: a declared shared output")
            continue
        if not on_path:
            owners = owners_of(ownership, path)
            if owners == [lane]:
                held.append(f"{path}: {lane}'s whole file")
            else:
                holder = f" ({' and '.join(owners)} hold{'s' if len(owners) == 1 else ''} it)" if owners else ""
                needed.append(f"{path}: needs a whole-file claim{holder}\n    {command} lead-own --grant {shlex.quote(path)} "
                              f"--lane {lane}")
            continue
        mine = [claim for claim in on_path if claim["lane"] == lane]
        try:
            spans, rows = helper.change_report(c.root, path, base, head, mine,
                                               others=[claim for claim in on_path if claim["lane"] != lane])
        except helper.RegionError as error:
            needed.append(f"{path}: {error}; lanes share it by lines ({', '.join(described_claim(claim) for claim in on_path)})")
            continue
        size = len(helper.lines(c.root, helper.entry(c.root, base, path)[1]))
        want: set[int] = set()
        edges: set[int] = set()  # the lines an insertion at the edge of one of the lane's spans needs
        for row in rows:
            if row["claim"] is not None:
                held.append(f"{path} {row['where']}: inside {described_claim(row['claim'], row['span'], base)}")
                continue
            needed.append(f"{path} {row['where']}: outside {lane}'s spans")
            first, removed = row["first"], row["removed"]
            lines_ = range(first, first + removed) if removed else range(first - 1, first + 1)
            if not removed and (first - 1 < 1 or first > size):
                needed[-1] += " (an insertion at the file's edge needs a whole-file claim)"
                continue
            missing = {line for line in lines_ if not any(start <= line < end for start, end in spans)}
            want.update(missing)
            if not removed and len(missing) == 1:
                edges.update(missing)
        others = []
        for claim in on_path:
            if claim["lane"] != lane:
                with contextlib.suppress(helper.RegionError):  # one that no longer maps holds no line here
                    others.append((helper.mapped(c.root, claim, base), claim))
        text = helper.text_lines(c.root, base, path)
        claimed = [*spans, *(span for span, _ in others)]
        for start, end in runs_of(sorted(want)):
            touching = next((claim for (first, last), claim in zip(spans, mine) if first <= end and start <= last), None)
            story = touching.get("story") if touching else key
            # Decision 13: the request names the lines by a line's text, with --insert for one past a block's edge.
            found = ((edges & set(range(start, end))) and helper.anchor_for(path, text, start, end, claimed, True)) \
                or helper.anchor_for(path, text, start, end, claimed)
            if found is None:
                needed.append(f"  lines {start}-{end - 1} of {path}: no line's text names a block that holds them; "
                              "ask the lead for a carve that gives them")
                continue
            words, insert, span = found
            clash = [described_claim(claim, other, base) for other, claim in others if helper.overlapping(other, span)]
            needed.append(f"  {command} lead-own --region {shlex.quote(path)} --lane {lane} --base {base} "
                          f"--around={shlex.quote(words)}" + (f" --insert {insert}" if insert else "")
                          + (f" --story {story}" if story else "")
                          + (f"   (overlaps {', '.join(clash)}: a carve gives it)" if clash else ""))
    return held, needed


def runs_of(numbers: list[int]) -> list[tuple[int, int]]:
    """Sorted line numbers as half-open runs."""
    runs: list[list[int]] = []
    for number in numbers:
        if runs and runs[-1][1] == number:
            runs[-1][1] = number + 1
        else:
            runs.append([number, number + 1])
    return [(start, end) for start, end in runs]


def claims_check(args) -> None:
    """Decision 7, a lane command: what the story's committed change needs claimed, and the lead's request for each.
    Writes nothing and journals nothing; exits 1 when anything is needed."""
    c = cfg()
    key = c.require(args.key)
    helper = _region_ownership()
    git("fetch", "-q", c.remote, c.base_branch)
    head = git("rev-parse", "HEAD")
    base = git("merge-base", c.base_ref, head)
    state = c.record_state()
    lane = c.lane_of(key, state)
    try:
        held, needed = claims_report(c, helper, lane, key, base, head, state)
    except helper.RegionError as error:
        raise Stop(str(error)) from error
    print(f"{key} on {lane}, {head[:12]} against its merge base {base[:12]} with {c.base_ref}:")
    for line in held:
        print(f"  holds {line}")
    if not needed:
        print("  nothing more to claim")
        return
    print("Needs a claim (ask the lead to run each request):")
    for line in needed:
        print(f"  {line}" if not line.startswith("  ") else line)
    sys.exit(1)


def lead_claims(args) -> None:
    """Decision 8: whether the queue would accept each story's ownership, on the tree it would sync with the base."""
    c = cfg()
    require_lead_checkout(c)
    helper = _region_ownership()
    git("fetch", "-q", c.remote, c.base_branch)
    base = git("rev-parse", c.base_ref)
    state = c.record_state()
    queued = {item["subject"]: item for item in state.get("queue", []) if item["stage"] != "merged"}
    keys = [c.require(key) for key in args.keys] if args.keys else list(c.stories)
    shown = 0
    for key in keys:
        item = queued.get(key)
        if item is not None:
            head, where = item["head"], "its handed head"
        else:
            fetched = run(["git", "fetch", "-q", c.remote, c.branch(key)], check=False).returncode == 0
            ref = f"refs/remotes/{c.remote}/{c.branch(key)}"
            if not fetched or run(["git", "rev-parse", "--verify", "--quiet", ref], check=False).returncode:
                if args.keys:
                    print(f"{key}: no hand-off and no pushed branch")
                continue
            head, where = git("rev-parse", ref), f"its pushed branch {c.branch(key)}"
        shown += 1
        lane = c.lane_of(key, state)
        merged = run(["git", "merge-tree", "--write-tree", base, head], check=False)
        if merged.returncode:
            print(f"{key} ({lane}), {where} {head[:12]}: conflicts with {c.base_ref} at {base[:12]}, so no ownership verdict")
            continue
        tree = merged.stdout.split()[0]
        try:
            outside = helper.queue_problems(c.root, state, lane, (item or {}).get("acceptedRegionPaths", []), base, tree)
            held, needed = claims_report(c, helper, lane, key, base, tree, state)
        except helper.RegionError as error:
            print(f"{key} ({lane}), {where} {head[:12]}: the queue could not check region ownership: {error}")
            continue
        verdict = ("the queue would refuse it: region ownership refused " + f"{lane}'s changes: "
                   + "; ".join(f"{path}: {reason}" for path, reason in outside.items())) if outside \
            else "the queue would accept its ownership"
        print(f"{key} ({lane}), {where} {head[:12]} merged with {c.base_ref} at {base[:12]}: {verdict}")
        for line in held:
            print(f"  holds {line}")
        for line in needed:
            print(f"  {line}" if not line.startswith("  ") else line)
    if not shown and not args.keys:
        print("no story has a hand-off or a pushed branch")


def owner_words(c, path: str) -> str:
    regions = [claim for claim in c.record_state().get("laneRegions", []) if claim["path"] == path]
    if regions:
        helper = _region_ownership()
        base = git("rev-parse", files_ref(c))
        descriptions = []
        for claim in regions:
            try:
                start, end = helper.mapped(c.root, claim, base)
                descriptions.append(f"{claim['lane']} [{start}, {end}) at {base[:12]}")
            except helper.RegionError as error:
                descriptions.append(f"{claim['lane']} needs a regrant: {error}")
        return ", ".join(descriptions)
    owner = owner_of(c, path)
    return f"{owner}'s" if owner else "no lane's"


def files_ref(c) -> str:
    return c.base_ref if run(["git", "rev-parse", "--verify", "--quiet", c.base_ref], check=False).returncode == 0 else "HEAD"


def tracked_at_base(c) -> list[str]:
    """The base's files a story can change: not the installed release, which no lane edits."""
    installed = Path(RECEIPT).parent.as_posix() + "/"
    return [f for f in git("ls-tree", "-r", "--name-only", files_ref(c), check=False).splitlines()
            if not f.startswith(installed)]


def check_candidate_ownership(c, key: str, base: str, head: str) -> str:
    state = c.record_state()
    lane = c.lane_of(key, state)
    if "laneOwnership" in state:
        queued = next((item for item in state["queue"] if item["subject"] == key), None)
        if queued and queued.get("assignedLane", queued["lane"]) != queued["lane"] and queued["stage"] != "stopped":
            raise Stop(f"{key} has a hand-off from {queued['lane']}; the lead must settle or return it first")
        _, outside = candidate_ownership(c, lane, base, head, state)
        if outside:
            raise Stop(f"writer_not_owned: {key} changes files outside {lane}'s: {outside}")
    return lane


def story_named_files(c, key: str, tracked: list[str]) -> list[str]:
    """The files a story's plan section, and the table rows naming it, name in backticks: a full path, a directory
    (trailing /), a glob, or a bare file name, resolved against the base's files. A bare name that matches several takes
    the lane's own match when there is one; a path not tracked yet is the new file it names. A row names the story when
    a cell with no backticked text does, and its files come from its other cells, so a passing mention in a files cell
    (such as "after" another story's key) doesn't hand that row's files to the story."""
    text = c.shelf.text(c.plan) or ""
    own = story_section(plan_sections(text), key) or ""
    names = {key, c.label(key)}
    naming = lambda cell: "`" not in cell and any(re.search(rf"(?<![\w-]){re.escape(n)}(?![\w-])", cell) for n in names)
    rows = []
    for line in text.splitlines():
        cells = line.strip().strip("|").split("|") if line.startswith("|") else []
        if any(naming(cell) for cell in cells):
            rows += [cell for cell in cells if not naming(cell)]
    lane = c.lane_of(key)
    found: set[str] = set()
    for token in re.findall(r"`([^`\n]+)`", "\n".join([own, *rows])):
        token = token.strip().removeprefix("./")
        if not PATH_TOKEN.fullmatch(token) or not ("/" in token or re.search(r"\.[A-Za-z0-9]{1,8}$", token)):
            continue
        if token.endswith("/"):
            found |= {f for f in tracked if f.startswith(token)}
        elif "/" not in token:
            matches = [f for f in tracked if fnmatch.fnmatch(f.rsplit("/", 1)[-1], token)]
            mine = [f for f in matches if owned_by(c, lane, f)]
            found |= set(mine or matches)
        elif re.search(r"[*?\[]", token):
            found |= {f for f in tracked if fnmatch.fnmatch(f, token)}
        elif token in tracked or not (tail := [f for f in tracked if f.endswith("/" + token)]):
            found.add(token)  # a tracked path, or the new file it names
        else:  # the end of a tracked path, such as references/adopting.md
            mine = [f for f in tail if owned_by(c, lane, f)]
            found |= set(mine or tail)
    return sorted(found)


def outside_lane(c, key: str, tracked: list[str]) -> list[str]:
    """The files a story names that its lane doesn't own."""
    lane = c.lane_of(key)
    return [f for f in story_named_files(c, key, tracked) if not owned_by(c, lane, f)]


def named_outside(c, key: str, outside: list[str], shown: int | None = None) -> str:
    """"FX-2 names a (lane-2's), b (no lane's)", to `shown` files and a count of the rest."""
    listed = ", ".join(f"{f} ({owner_words(c, f)})" for f in outside[:shown])
    rest = len(outside) - len(outside[:shown])
    return f"{key} names {listed}" + (f" and {rest} more" if rest else "")


def story_file_problems(c, keys: list[str], tracked: list[str]) -> list[str]:
    """One phrase per story that names a file outside its lane, as doctor's one line has room for: three files a
    story, five stories, and how many more."""
    found = [(key, outside) for key in keys if (outside := outside_lane(c, key, tracked))]
    phrases = [named_outside(c, f"{key} ({c.lane_of(key)})", outside, 3) for key, outside in found[:5]]
    if len(found) > 5:
        phrases.append(f"and {len(found) - 5} more stories (lead-assign lists each one's)")
    return phrases


def co_changed(c, path: str, ref: str) -> tuple[int, collections.Counter]:
    """How many of the recent changes to `path` on `ref` count, and how often each other file changed with it. A
    sweeping change (more than CO_CHANGE['sweep'] files) says nothing about coupling, so it isn't counted."""
    out = git("log", "--no-merges", "--full-diff", f"-n{CO_CHANGE['commits']}", "--format=tformat:@", "--name-only", ref, "--",
              path, check=False)
    count, together = 0, collections.Counter()
    for change in out.split("@")[1:]:
        files = set(change.split())
        if not files or len(files) > CO_CHANGE["sweep"]:
            continue
        count += 1
        together.update(files - {path})
    return count, together


def co_change_warning(c, key: str, tracked: list[str]) -> str | None:
    """The warning of a story's co-changed files (co_change_files), each with the named file it changes with most."""
    often = co_change_files(c, key, tracked)
    if not often:
        return None
    return (f"{key}'s files often change with "
            + ", ".join(f"{f} ({owner_words(c, f)}; with {path} in {n} of {count} changes)" for f, n, count, path in often))


def co_change_files(c, key: str, tracked: list[str]) -> list[tuple[str, int, int, str]]:
    """The files outside a story's lane that changed with a file it names in at least CO_CHANGE['support'] and
    CO_CHANGE['share'] of that file's changes: the CO_CHANGE['shown'] most coupled, each as (file, changes together,
    the named file's changes, the named file it changes with most)."""
    lane = c.lane_of(key)
    named = story_named_files(c, key, tracked)
    ref, present = files_ref(c), set(tracked)
    best: dict[str, tuple[float, int, int, str]] = {}
    for path in named:
        if path not in present:
            continue
        count, together = co_changed(c, path, ref)
        for f, n in together.items():
            if (n >= CO_CHANGE["support"] and n >= CO_CHANGE["share"] * count and f in present and f not in named
                    and not owned_by(c, lane, f) and (n / count, n) > best.get(f, (0, 0))[:2]):
                best[f] = (n / count, n, count, path)
    often = sorted(best.items(), key=lambda item: (-item[1][0], -item[1][1], item[0]))[:CO_CHANGE["shown"]]
    return [(f, n, count, path) for f, (_, n, count, path) in often]


def context_problems(c) -> list[str]:
    """Each context.sections heading the plan lacks, which every lane's review context would go without."""
    text = c.shelf.text(c.plan)
    if text is None:
        return plan_problems(c, [])
    sections = plan_sections(text)
    lacking = [name for name in c.context_sections if context_section(sections, name) is None]
    if not lacking:
        return []
    return [f"context.sections the plan lacks: {', '.join(map(repr, lacking))}; fix: add the heading to {c.plan}, or "
            f"remove it from context.sections in {c.delivery_where}"]


def publishing_problems(c, binding: dict) -> list[str]:
    """A forge or tracker the repository configures, with nothing in the binding that reads or posts to it."""
    state = binding.get("state") or {}
    problems = []
    if (c.forge.get("adapter") or c.forge.get("argv")) and not state.get("forgeSnapshot"):
        problems.append("the forge is configured, but the binding has no state.forgeSnapshot, so the record never sees "
                        "the delivery's pull requests; fix: add state.forgeSnapshot to the binding (delivery-views' "
                        "snapshot.py prints one for GitHub and Bitbucket)")
    # The one tracker check (tracker-adapter/1): a tracker whose updates nothing posts, unless tracker.updates is manual.
    tracker = tracker_publisher.refusal(tracker_publisher.settings(c.root, c.flow_raw, binding))
    if tracker:
        problems.append(tracker)
    return problems


def remote_base_problem(c) -> str | None:
    """Lanes read the configuration and the delivery file from the remote base. A local setup, whose lanes read
    their own working tree, says so with RUN_DELIVERY_LOCAL=1."""
    if setting("RUN_DELIVERY_LOCAL") == "1" or setting("RUN_DELIVERY_CONFIG"):
        return None
    fix = (f"fix: commit them on {c.base_branch} and push it, or set RUN_DELIVERY_LOCAL=1 for a local setup, whose "
           "lanes read their own working tree")
    if not OFFLINE:
        run(["git", "fetch", "-q", c.remote, c.base_branch], cwd=c.root, check=False)
    if run(["git", "rev-parse", "--verify", "--quiet", c.base_ref], cwd=c.root, check=False).returncode != 0:
        return f"{c.base_ref} has no configuration for lanes: the branch isn't on the remote; {fix}"
    shelf = Shelf(c.root, c.base_ref)
    lacking = [CONFIG] if shelf.text(CONFIG) is None and shelf.text(LEGACY_NAMES[0][0]) is None else []
    lacking += [rel for rel in [f"{c.deliveries_rel}/{c.delivery}.json"] if shelf.text(rel) is None]
    if lacking:
        return f"{c.base_ref} has no configuration for lanes: it lacks {' and '.join(lacking)}; {fix}"
    return None


def ready_problem(c) -> str | None:
    """A merge step that refuses drafts, with no grant for the lead to mark them ready at acceptance."""
    if c.forge.get("mergeNeedsReady") and not (c.raw.get("authority") or {}).get("readyPullRequests"):
        return (f"forge.mergeNeedsReady says the merge step refuses a draft, but the delivery grants no "
                f"readyPullRequests; fix: add \"readyPullRequests\": true to `authority` in {c.delivery_where} (lead-setup "
                "--force --authority push,draftPullRequests,readyPullRequests writes it), so lead-accept marks each draft "
                "ready, or remove forge.mergeNeedsReady")
    return None


def setup_problems(c) -> list[str]:
    """Every duty the workflow can't do for this delivery here, each with its fix: what doctor --delivery reports and
    lead-init refuses on."""
    problems = plan_problems(c, list(c.stories)) + context_problems(c)
    ready = ready_problem(c)
    if ready:
        problems.append(ready)
    binding = c.shelf.json(".agents/orchestration.json")
    if binding is not None:
        problems += publishing_problems(c, binding)
    node = node_problem(c.release)
    if node:
        problems.append(node[1])
    remote = remote_base_problem(c)
    if remote:
        problems.append(remote)
    return list(dict.fromkeys(problems))


# -- lead ----------------------------------------------------------------------------------

# How many times a write computed from a read is tried before it gives up: each try reads the record afresh.
PATCH_ATTEMPTS = 5


def patch_from(compute, what: str, writer: str = "lead", attempts: int = PATCH_ATTEMPTS):
    """Read the record, compute a patch from that read, and write it pinned to the version read. When another writer
    (the supervisor, the queue, a lane) moved the record in between, the state tool refuses it as version_stale. Then
    read again and compute again, so no patch is ever written from a stale read, up to `attempts` times. `compute`
    takes the record and returns the patch body, a list of the state tool's own patch arguments (an element patch),
    or None for nothing to write; it may raise Stop when the fresh record no longer allows the write. Returns what was
    written, or None."""
    for _ in range(attempts):
        doc = load_state()
        body = compute(doc)
        if body is None:
            return None
        given = body if isinstance(body, list) else ["--patch", json.dumps(body)]
        done = state_tool("patch", "--writer", writer, "--version", str(doc["state"]["version"]), *given, check=False)
        if done.returncode == 0:
            return body
        try:  # the state tool answers with one JSON document, pretty-printed
            answer = json.loads(done.stdout)
        except ValueError:
            answer = {}
        answer = answer if isinstance(answer, dict) else {}
        if answer.get("code") != "version_stale":
            raise Stop(f"the state tool refused {what}: {(answer.get('error') or done.stderr or done.stdout).strip()[-600:]}")
    raise Stop(f"version_stale: the record kept changing while {what} was written; tried {attempts} times, reading "
               "it afresh each time. Run it again once the other writer settles")


LANE_GRANTS = ("push", "draftPullRequests")
# The lead's own grant, beside the lanes': lead-accept marks a draft ready under it. No lane reads it.
LEAD_GRANTS = ("readyPullRequests",)


def lanes_grant(args, existing: dict | None) -> dict | None:
    """The operator's grant, as lead-setup is told it: the lanes' push and draft pull requests, and the lead's
    readyPullRequests. None when there is none. A file drafted again keeps the grant it holds unless told otherwise."""
    if args.authority and args.no_authority:
        raise Stop("pass --authority or --no-authority, not both")
    if args.no_authority:
        return None
    if not args.authority:
        if (existing or {}).get("authority"):
            return existing["authority"]
        raise Stop("lead-setup needs the lanes' authority grant: ask the operator what lanes may do on the forge, then "
                   "pass --authority push,draftPullRequests --granted-by WHO (either or both grants; add "
                   "readyPullRequests, the lead's, when lead-accept marks drafts ready), or --no-authority "
                   "when lanes get none and hand their branches to the lead")
    names = [name.strip() for name in args.authority.split(",") if name.strip()]
    unknown = [name for name in names if name not in (*LANE_GRANTS, *LEAD_GRANTS)]
    if unknown or not names:
        raise Stop(f"--authority takes {', '.join(LANE_GRANTS)} (the lanes') and {', '.join(LEAD_GRANTS)} (the lead's, "
                   f"to mark a draft ready at acceptance), comma-separated, not {', '.join(unknown) or 'nothing'}")
    if "draftPullRequests" in names and "push" not in names:
        raise Stop("draftPullRequests needs push: a lane opens its draft pull request from the branch it pushed")
    if not args.granted_by:
        raise Stop("--authority needs --granted-by: who granted it")
    return {**{name: True for name in (*LANE_GRANTS, *LEAD_GRANTS) if name in names}, "grantedBy": args.granted_by,
            "grantedOn": args.granted_on or datetime.date.today().isoformat()}


def integration_matches(delivery: dict, binding: dict, key: str, base: str, target: str) -> bool:
    return (delivery.get("delivery") == key and delivery.get("baseBranch") == base
            and delivery.get("integrationTarget") == target and binding.get("base", {}).get("ref") == base)


def verify_integration_checkout(c, root: Path, key: str, base: str, target: str) -> None:
    listed = git("worktree", "list", "--porcelain").splitlines()
    if f"worktree {root}" in listed and git("branch", "--show-current", cwd=root) == base:
        delivery = load_json(root / c.deliveries_rel / f"{key}.json") or {}
        binding = load_json(root / ".agents/orchestration.json") or {}
        if integration_matches(delivery, binding, key, base, target):
            return
        # Setup writes the delivery first. Complete an interrupted first draft
        # only on the original standing tree with a matching declaration.
        start = git("rev-parse", "HEAD", cwd=root)
        on_standing_history = is_ancestor(start, f"refs/heads/{target}")
        if (binding.get("base", {}).get("ref") == target
                and integration_matches(delivery, {**binding, "base": {**binding["base"], "ref": base}}, key, base, target)
                and on_standing_history and not git("diff", "HEAD", "--", ".agents/orchestration.json", cwd=root)):
            add_tracker_publisher(Config(root, need_delivery=False, pick=False), base=base)
            return
        # A draft can fail before either file is written. Only resume that
        # checkout if it still holds the unmodified starting tree.
        if not delivery and binding.get("base", {}).get("ref") == target and on_standing_history:
            clean_head(root)
            return
    raise Stop(f"{root} already exists and does not hold the integration setup for {key} on {base}")


def integration_checkout(c, key: str, base: str, plan: str) -> tuple[Path, str]:
    """Find or create the lead checkout, keeping the standing binding on its own branch."""
    if not c.binding_base or git("check-ref-format", "--branch", base, check=False) != base:
        raise Stop("--integration needs a standing base and a valid integration branch name")
    if not re.fullmatch(PLAN_KEY, key):
        raise Stop("--integration needs a delivery key such as WORK-123")
    root = c.lane_checkout(key).resolve()
    if c.root.resolve() == root:
        existing = c.shelf.json(f"{c.deliveries_rel}/{key}.json") or {}
        target = existing.get("integrationTarget")
        if target and integration_matches(existing, c.binding, key, base, target) and git("branch", "--show-current") == base:
            return root, target
        if c.binding_base != base and serves(c.binding, base):
            verify_integration_checkout(c, root, key, base, c.binding_base)
            return root, c.binding_base
        raise Stop(f"{root} is not the lead checkout of {key} on {base}")
    target = c.binding_base
    if base == target or not serves(c.binding, base):
        raise Stop(f"integration branch {base} must differ from {target} and match a served base in the binding")
    if root.exists():
        verify_integration_checkout(c, root, key, base, target)
        return root, target
    existing_branch = git("rev-parse", "--verify", "--quiet", f"refs/heads/{base}", check=False)
    published = git("ls-remote", "--heads", c.remote, f"refs/heads/{base}").split()
    remote_tip = published[0] if published else ""
    if remote_tip:
        git("fetch", "-q", c.remote, f"refs/heads/{base}:refs/remotes/{c.remote}/{base}")
        if git("rev-parse", f"{c.remote}/{base}") != remote_tip:
            raise Stop(f"{c.remote}/{base} moved while resuming; retry")
    if git("branch", "--show-current") != target:
        raise Stop(f"start integration setup on {target}, the standing binding's base")
    if Path(plan).is_absolute() or ".." in Path(plan).parts:
        raise Stop("name a committed repository-relative plan")
    if existing_branch or remote_tip:
        if existing_branch and remote_tip and not is_ancestor(remote_tip, existing_branch):
            raise Stop(f"local {base} does not contain its remote tip; reconcile the branch before resuming")
        tip = existing_branch or remote_tip
        delivery = Shelf(c.root, tip).json(f"{c.deliveries_rel}/{key}.json") or {}
        binding = Shelf(c.root, tip).json(".agents/orchestration.json") or {}
        if not integration_matches(delivery, binding, key, base, target):
            raise Stop(f"{base} already exists without a matching integration setup for {key}")
        if existing_branch:
            git("worktree", "add", "-q", str(root), base)
        else:
            git("worktree", "add", "-q", "--track", "-b", base, str(root), f"{c.remote}/{base}")
    else:
        head = clean_head()
        if Shelf(c.root, head).text(plan) is None:
            raise Stop("name a committed repository-relative plan")
        if Shelf(c.root, head).json(f"{c.deliveries_rel}/{key}.json") is not None:
            raise Stop(f"{key} already has a delivery file on {target}; use a new delivery key")
        git("worktree", "add", "-q", "--no-track", "-b", base, str(root), head)
    return root, target


def lead_setup(args) -> None:
    """Draft a delivery from its plan and optional tracker snapshot."""
    c = Config(repo(), need_delivery=False, pick=False)
    if not args.integration:
        draft_delivery(c, args)
        return
    # Validate the grant and heading pattern before creating a checkout.
    if not args.force:
        lanes_grant(args, None)
    pattern = re.compile(args.pattern or STORY_HEADING, re.M)
    if not {"key", "title"} <= pattern.groupindex.keys():
        raise Stop("the pattern must name groups `key` and `title`")
    root, target = integration_checkout(c, args.key, args.integration, args.plan)
    args.base = args.integration
    existing = root / c.deliveries_rel / f"{args.key}.json"
    if existing.is_file() and not args.force:
        print(f"resume {args.key} in the lead checkout {root} on {args.base}; integration target {target}")
        return
    integration = Config(root, need_delivery=False, pick=False)
    # Draft against the standing config first. Its served-base patterns are
    # the authority for this branch, including while the remote has no ref.
    draft_delivery(integration, args, integration_target=target)
    print(f"lead checkout: {root}; review the draft, commit the binding and delivery file there, then push {args.base} "
          f"to {c.remote}. Run these commands there:")
    for command in ("lead-init", "lead-brief"):
        print(f"  {flow_command()} --delivery {args.key} {command}")
    print(f"Integrate into {target} at close-out.")


def draft_delivery(c, args, integration_target: str | None = None) -> None:
    if c.bases and not args.base:
        raise Stop(f"the binding serves several bases ({', '.join([c.binding_base, *c.bases])}): pass --base to name "
                   "the one this delivery lands on, or --integration to set up a separate base")
    if args.base and c.binding_base and not serves(c.binding, args.base):
        raise unserved(c.binding, args.base)
    if tracker_conf(c)["unrunnable"]:
        # Refused before anything is drafted: a binding naming a publisher that runs nothing no longer validates.
        raise Stop(tracker_publisher.refusal(tracker_conf(c)))
    key = args.key
    path = c.deliveries / f"{key}.json"
    if path.exists() and not args.force:
        raise Stop(f"{path} exists; edit it, or pass --force to draft it again")
    existing = json.loads(path.read_text()) if path.exists() else None
    grant = lanes_grant(args, existing)
    plan = c.root / args.plan
    text = plan.read_text()
    planning = planning_record_of(c, Path(args.plan))
    if planning and planning[0] != key:
        raise Stop(f"collab.key_differs: {args.plan} has the planning record {planning[0]} at {planning[1]}, which "
                   f"keeps its key through approval; draft the delivery as {planning[0]}")
    pattern = re.compile(args.pattern or STORY_HEADING, re.M)
    if "key" not in pattern.groupindex or "title" not in pattern.groupindex:
        raise Stop("the pattern must name groups `key` and `title` (and may name `label` and `pinned`)")
    sections = plan_sections(text)
    # The plan format's headings are read under its `## Stories`; a pattern of the lead's own reads the whole plan.
    scope = next((body for level, title, body in sections if level == 2 and title == "Stories"), None) \
        if args.pattern is None else None
    stories, read = {}, {}
    notes = []
    for m in pattern.finditer(scope if scope is not None else text):
        g = m.groupdict()
        story = {"title": g["title"].strip(), "lane": "unassigned"}
        heading = m.group(0).strip()
        section = next((body for _, _, body in sections if body.startswith(heading)), "")
        found = story_plan(section)
        if found is None:
            notes.append(f"plan story {g['key']}'s section doesn't open with its lane sentence (\"Lane N, tier T, not "
                         "blocked.\" or \"Lane N, tier T, after KEY.\"): left it unassigned")
        else:
            story["lane"] = found["lane"]
            if found["after"]:
                story["after"] = found["after"]
            read[g["key"]] = found
        # A `Lenses:` sentence asks for lenses on the story's brief, as `Files:` names its files.
        asked = plan_sentence(section_body(section), "Lenses:")
        named = re.findall(r"`([^`\n]+)`", asked) if asked is not None else []
        for lens in named:
            if lens not in c.story_lenses:
                notes.append(f"plan story {g['key']}'s Lenses sentence names {lens}, which isn't a declared story lens: "
                             "drafted it without")
        if any(lens in c.story_lenses for lens in named):
            story["lenses"] = [lens for lens in c.story_lenses if lens in named]
        if g.get("label"):
            story["label"] = g["label"]
        if g.get("pinned"):
            story["pinned"] = re.findall(r"`([^`]+)`", g["pinned"])
            if c.in_app:
                # The rule for "when relevant": a story whose in-app checks hold or fail a request changes what the
                # page shows while it loads or fails, so it gets a before/after clip. The lead removes it if not.
                story["evidence"] = "video"
        stories[g["key"]] = story
    if not stories:
        raise Stop(f"the pattern matched no heading in {args.plan}")
    try:
        # A delivery drafted again may already keep a record that has read its siblings; a new one has none.
        sibling_keys = sibling_story_keys(c.state_of(args.key, json.loads(path.read_text()) if path.exists() else {}))
    except (OSError, ValueError, Stop):
        sibling_keys = set()
    for subject, found in read.items():
        unknown = [after for after in found["after"] if after not in stories and after not in sibling_keys]
        if unknown:
            notes.append(f"plan story {subject} comes after {', '.join(unknown)}, which neither the plan nor a known "
                         "sibling delivery has a story for")
    lanes, missing = units_owns(text)
    if missing:
        notes.append(missing)
    for lane in sorted({story["lane"] for story in stories.values() if story["lane"] != "unassigned"} - set(lanes)):
        notes.append(f"{lane} has stories but no row in the plan's '{UNITS_SECTION}' table: drafted it owning nothing")
        lanes[lane] = []
    snapshot, said = setup_tracker_snapshot(c, args, key)
    if said:
        notes.append(said)
    if snapshot is not None:
        tracked = {i["subject"]: i for i in snapshot if i["subject"] != key and i.get("state") != "canceled"}
        for subject, item in tracked.items():
            if subject not in stories:
                notes.append(f"tracker item {subject} ({item.get('title')}) has no plan heading; add it or cancel it")
        for subject, story in stories.items():
            if subject not in tracked:
                notes.append(f"plan story {subject} has no tracker item")
            elif tracked[subject].get("criteria"):
                story["criteria"] = [{"id": f"{subject.lower()}-{n}", "text": criterion}
                                     for n, criterion in enumerate(tracked[subject]["criteria"], start=1)]
            else:
                notes.append(f"plan story {subject}'s tracker item has no Acceptance Criteria section: drafted no "
                             "criteria for it")
            if subject in tracked and not tracked[subject].get("summary"):
                notes.append(no_summary(subject))
    drafted = {}
    for field, name, noun in (("approvals", args.approvals_section, "approvals"),
                            ("outOfScope", args.out_of_scope_section, "out-of-scope items")):
        if not name:
            continue
        body = next((b for _, title, b in sections if title == name), None)
        items = plan_list_items(body) if body is not None else []
        if body is None:
            notes.append(f"the plan has no '{name}' section: drafted no {noun}")
        elif not items:
            notes.append(f"the plan's '{name}' section holds no list: drafted no {noun}")
        else:
            drafted[field] = ([{"id": f"approval-{i + 1}", "text": text, "state": "waiting"} for i, text in enumerate(items)]
                            if field == "approvals" else items)
            print(f"drafted {len(items)} {noun} from '{name}'")
    if existing:
        drafted.update({name: existing[name] for name in ("approvals", "outOfScope", "planReview") if name in existing})
        if existing.get("integrationTarget") and not integration_target:
            raise Stop("redraft a delivery with an integration target using --integration on its lead checkout")
    adoptable = adoptable_plan_review(c, Path(args.plan))
    if adoptable:
        drafted.setdefault("planReview", {"lenses": json.loads(round_files(adoptable)[0].read_text())["lenses"]})
        target = c.main / c.work / "review" / key / "plan"
        if target.exists() and any(target.iterdir()):
            raise Stop(f"delivery {key} already has a plan review in {target}, so it can't adopt the one in {adoptable}; "
                       "keep one of them and remove the other")
    git("fetch", "-q", c.remote, cwd=c.root)
    base = args.base or c.binding_base
    if not base:
        raise Stop("no delivery base: the binding names none here; pass --base")
    base_ref = f"{c.remote}/{base}"
    tooling = None
    if args.ship_from:
        first = git("rev-list", "--reverse", f"{args.ship_from}..{base_ref}", check=False).splitlines()
        tooling = first[0][:12] if first else None
        if not tooling:
            notes.append(f"no commit on {base_ref} after {args.ship_from}: set ship.toolingCommit once the tooling is committed")
    delivery = {
        "schemaVersion": "delivery-flow-delivery/1",
        "delivery": key,
        "headline": args.headline or key,
        **({"baseBranch": args.base} if args.base and (integration_target or args.base != c.binding_base) else {}),
        **({"integrationTarget": integration_target} if integration_target else {}),
        "plan": args.plan,
        "laneBrief": str(Path(args.plan).with_suffix("")) + ".lane-brief.md",
        "brief": {"notes": None},
        "context": {"sections": args.context_section or []},
        "lanes": {lane: {"owns": owns} for lane, owns in lanes.items()},
        "stories": stories,
        "finish": [EVIDENCE_FINISH] if any(st.get("evidence") == "video" for st in stories.values()) else [],
        **({"authority": grant} if grant else {}),
        **drafted,
    }
    if args.ship_from:
        delivery["ship"] = {"from": args.ship_from, "toolingCommit": tooling, "paths": args.ship_path or ["src/"],
                            "branch": "ship/{delivery}"}
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(delivery, indent=2) + "\n")
    print(f"drafted {path}: {len(stories)} stories")
    added = add_tracker_publisher(c, base=base if integration_target else None)
    if added:
        print(f"added the tracker publisher ({added}) to {c.binding_path.name}'s state.publishers: commit it with the "
              "delivery file")
    review_when_note(c, args.review_when, notes)
    loose = tracker_publisher.untargeted(tracker_conf(c)) if tracker_conf(c)["mode"] == "publisher" else []
    if loose:
        notes.append(f"name the status each of these moves leads to in tracker.transitions.targets, so one a person "
                     f"already made reads as made: {', '.join(loose)}")
    if adoptable:
        print(adopt_plan_review(c, adoptable, key))
    if planning:
        print(f"adopting the planning record of {key} at {planning[1]} in place: lead-init takes it over once "
              f"every approver seat has endorsed the plan, and the plan now syncs on lead/{key}")
    print("next: check each story's lane, criteria and order and the lanes' owns against the approved plan, fill in "
          "what the notes below name, set inApp requirements, the finish lines and the brief notes, then lead-init and "
          "lead-brief")
    for n in notes:
        print(f"  note: {n}")


def lead_hints(args) -> None:
    """Print the delivery's work-hints/1 for orchestrate-work's `next`: each story's files, from its plan section's
    `Files:` sentence, and its blockers, the `after` keys its delivery-file story holds. A binding names this command
    as its state.workHints, so `next` reads the plan's order without the tracker."""
    c = cfg()
    sections = plan_sections(c.shelf.text(c.plan) or "")
    items = {}
    for key, story in c.stories.items():
        section = story_section(sections, key) or ""
        hint = {}
        files = section_files(section)
        if files:
            hint["files"] = files
        if story.get("after"):
            hint["blockers"] = list(story["after"])
        items[key] = hint
    print(json.dumps({"items": items}, indent=2))


def setup_tracker_snapshot(c, args, key: str) -> tuple[list[dict] | None, str | None]:
    """The tracker snapshot lead-setup drafts criteria from, as its items: the --tracker-snapshot file, else the
    binding's trackerSnapshot command run for the delivery's own key. None, with why, when there is neither or the
    command fails."""
    if args.tracker_snapshot:
        return json.loads(Path(args.tracker_snapshot).read_text()).get("items", []), None
    spec = (c.binding.get("state") or {}).get("trackerSnapshot")
    if not spec:
        return None, ("no tracker snapshot (pass --tracker-snapshot, or declare the binding's state.trackerSnapshot): "
                      "drafted no story's criteria")
    argv = expand_argv(spec["argv"], stateDirectory=str(c.main / c.state_rel), parent=key)
    try:
        taken = run(argv, cwd=c.root, check=False, timeout=int(spec.get("timeoutSeconds", 60)))
    except subprocess.TimeoutExpired:
        return None, "the binding's tracker snapshot timed out: drafted no story's criteria"
    if taken.returncode != 0:
        return None, (f"the binding's tracker snapshot failed ({taken.returncode}: "
                      f"{(taken.stderr or taken.stdout).strip()[-200:]}): drafted no story's criteria")
    try:
        items = json.loads(taken.stdout).get("items", [])
    except (ValueError, AttributeError):
        return None, "the binding's tracker snapshot printed no snapshot: drafted no story's criteria"
    return items, None


def review_when_note(c, answer: str | None, notes: list[str]) -> None:
    """Record lead-setup's answer for when the review move is made, or ask for it: never inferred from review.pr."""
    tracker = c.flow_raw.get("tracker") or {}
    if answer:
        raw = json.loads(Path(c.path).read_text()) if Path(c.path).exists() else {"schemaVersion": "delivery-flow/1"}
        raw.setdefault("tracker", {}).setdefault("transitions", {})["reviewWhen"] = answer
        Path(c.path).write_text(json.dumps(raw, indent=2) + "\n")
        c.flow_raw = raw
        print(f"recorded tracker.transitions.reviewWhen: {answer} in {c.name}: commit it with the delivery file")
    elif (tracker.get("transitions") or {}).get("review") and not tracker["transitions"].get("reviewWhen"):
        notes.append("tracker.transitions.reviewWhen is unset, so lanes make the review move by hand when open-pr prints "
                     "it; to have the commands make it, run lead-setup again with --force and --review-when "
                     f"{'|'.join(tracker_publisher.REVIEW_WHEN)}")


def add_tracker_publisher(c, *, base: str | None = None) -> str | None:
    """Update the binding for setup, adding the tracker publisher when it is configured and missing."""
    conf = tracker_conf(c)
    add = conf["mode"] == "publisher" and not conf["publisher"] and not conf["problems"]
    if not c.binding_path.exists() or not (add or base):
        return None
    binding = json.loads(c.binding_path.read_text())
    entry = None
    if add:
        publishers = binding.setdefault("state", {}).setdefault("publishers", [])
        entry = tracker_publisher.publisher_entry(TOOL_PATH.replace("run_delivery.py", "tracker_publisher.py"))
        taken = {item.get("id") for item in publishers if isinstance(item, dict)}
        entry["id"] = next(name for name in ("tracker", *(f"tracker-{n}" for n in range(2, len(taken) + 3)))
                           if name not in taken)
        publishers.append(entry)
    if base:
        binding["base"]["ref"] = base
        # Stage in this worktree's Git metadata, so a stopped setup cannot
        # leave an untracked file beside the binding.
        directory = lane_base_file(c.root).parent
        directory.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix="integration-setup-", dir=directory) as folder:
            staging = Path(folder) / c.binding_path.name
            staging.write_text(json.dumps(binding, indent=2) + "\n")
            os.replace(staging, c.binding_path)
    else:
        c.binding_path.write_text(json.dumps(binding, indent=2) + "\n")
    return entry["id"] if entry else None


# The plan format lead-setup reads (plan-work's SKILL.md documents it, with an example): a story is a `### KEY. Title`
# heading under `## Stories`, whose section opens with its lane sentence and may hold a `Files:` sentence, and the
# `## Units and order` table gives each lane's files.
PLAN_KEY = r"[A-Z][A-Z0-9]*-[0-9]+"
STORY_HEADING = rf"^### (?P<key>{PLAN_KEY})\. (?P<title>.+)$"
LANE_SENTENCE = re.compile(rf"Lane ([0-9]+), tier ([0-9]+), (?:not blocked|after ({PLAN_KEY}(?:, {PLAN_KEY})*"
                           rf"(?: and {PLAN_KEY})?))\.(?=\s|$)")
UNITS_SECTION = "Units and order"
UNITS_COLUMNS = ("Tier", "Lane", "Items, in order", "Owns")


def plan_paths(text: str) -> list[str]:
    """The backticked repository paths in a plan's `Files:` sentence or `Owns` cell, in order, each once; a folder
    (ending in /) becomes the glob of everything under it."""
    paths = []
    for token in re.findall(r"`([^`\n]+)`", text):
        token = token.strip()
        path = token + "*" if token.endswith("/") else token
        if path not in paths:
            paths.append(path)
    return paths


def plan_sentence(text: str, opening: str) -> str | None:
    """The sentence of `text` (one line, whitespace folded) that starts with `opening`, without it and its full stop;
    a full stop inside backticks, as in a file name, ends no sentence."""
    found = re.search(rf"(?:^|(?<=[.:] )){re.escape(opening)}", text)
    if found is None:
        return None
    rest = text[found.end():]
    masked = re.sub(r"`[^`]*`", lambda m: "x" * len(m.group()), rest)
    end = re.search(r"\.(?=\s|$)", masked)
    return rest[:end.start()] if end else rest


def section_body(section: str) -> str:
    """A plan section's text after its heading, as one line with its whitespace folded."""
    return " ".join(section.split("\n", 1)[1].split()) if "\n" in section else ""


def section_files(section: str) -> list[str]:
    """The paths a story's plan section lists in its `Files:` sentence; none without one."""
    files = plan_sentence(section_body(section), "Files:")
    return plan_paths(files) if files is not None else []


def story_plan(section: str) -> dict | None:
    """A story's lane, tier and `after` keys from its plan section (heading included); None when the section doesn't
    open with its lane sentence."""
    found = LANE_SENTENCE.match(section_body(section))
    if found is None:
        return None
    lane, tier, keys = found.groups()
    return {"lane": f"lane-{int(lane)}", "tier": int(tier), "after": re.findall(PLAN_KEY, keys or "")}


def units_rows(text: str) -> tuple[list[tuple[int, str, list[str]]] | None, str | None]:
    """The plan's `Units and order` table as (tier, lane, owns) rows, or None with what's missing."""
    rows, missing = units_table(text)
    return (None if rows is None else [(row["tier"], row["lane"], row["owns"]) for row in rows]), missing


def units_table(text: str) -> tuple[list[dict] | None, str | None]:
    """The plan's `Units and order` table as rows of tier, lane, the story keys its items cell names in order, and
    owns; or None with what's missing."""
    body = next((b for level, title, b in plan_sections(text) if level == 2 and title == UNITS_SECTION), None)
    if body is None:
        return None, f"the plan has no '{UNITS_SECTION}' section"
    rows = [[cell.strip() for cell in line.strip().strip("|").split("|")] for line in body.splitlines()
            if line.strip().startswith("|")]
    if not rows or any(name not in rows[0] for name in UNITS_COLUMNS):
        return None, f"the plan's '{UNITS_SECTION}' section holds no table with the columns {', '.join(UNITS_COLUMNS)}"
    at = {name: rows[0].index(name) for name in UNITS_COLUMNS}
    found = []
    for row in rows[1:]:
        if len(row) < len(rows[0]) or set("".join(row)) <= set("-: "):
            continue
        tier, lane = re.fullmatch(r"[0-9]+", row[at["Tier"]]), re.fullmatch(r"(?:Lane )?([0-9]+)", row[at["Lane"]])
        if tier is not None and lane is not None:
            found.append({"tier": int(tier.group()), "lane": f"lane-{int(lane.group(1))}",
                          "items": re.findall(PLAN_KEY, row[at["Items, in order"]]), "owns": plan_paths(row[at["Owns"]])})
    return found, None


def units_owns(text: str) -> tuple[dict[str, list[str]], str | None]:
    """Each lane's `owns` from the plan's `Units and order` table, read from its lowest-tier row; a later row lists
    only what the lane gains when an earlier item merges, which the lead applies then. With what's missing, if any."""
    rows, missing = units_rows(text)
    if rows is None:
        return {}, f"{missing}: drafted no lane's owns"
    lowest: dict[str, tuple[int, list[str]]] = {}
    for tier, lane, owns in rows:
        if lane not in lowest or tier < lowest[lane][0]:
            lowest[lane] = (tier, owns)
    return {name: owns for name, (_, owns) in sorted(lowest.items())}, None


def plan_with_story(text: str, key: str, title: str, lane: str, after: list[str], why: str) -> str:
    """The plan with a story added mid-delivery: its `### KEY. Title` heading at the end of `## Stories` (or of the
    plan, without one), its lane sentence in plan-work's format at the lane's latest tier, and its reason."""
    rows, _ = units_rows(text)
    tier = max((row_tier for row_tier, row_lane, _ in rows or [] if row_lane == lane), default=1)
    number = re.fullmatch(r"lane-([0-9]+)", lane)
    order = ("not blocked" if not after else "after " + (after[0] if len(after) == 1 else
                                                         ", ".join(after[:-1]) + " and " + after[-1]))
    opening = f"Lane {number.group(1)}, tier {tier}, {order}. " if number else ""
    section = f"### {key}. {title}\n\n{opening}Added mid-delivery: {why}\n"
    body = next((body for level, heading, body in plan_sections(text) if level == 2 and heading == "Stories"), None)
    if body is None:
        return text.rstrip("\n") + "\n\n" + section
    end = text.index(body) + len(body)
    rest = text[end:].lstrip("\n")
    return text[:end] + "\n\n" + section + ("\n" + rest if rest else "")


def plan_list_items(body: str) -> list[str]:
    """Each top-level list item of a plan section, before its first subheading, as one line of at most 600
    characters; an item's indented continuation lines join it. At most the first 100."""
    return plan_list_all(body)[:100]


def plan_list_all(body: str) -> list[str]:
    """plan_list_items without its cap on the count, so a reader that cuts the list can say how many it dropped."""
    items: list[str] = []
    for line in body.splitlines()[1:]:
        if line.startswith("#"):
            break
        item = re.match(r"^(?:[-*+]|\d+[.)])\s+(.*)$", line)
        if item:
            items.append(item.group(1).strip())
        elif items and line[:1] in (" ", "\t") and line.strip():
            items[-1] += " " + line.strip()
    return [plan_line(text) for text in items if text.strip()]


def plan_line(text: str) -> str:
    """A plan list item as one line, its whitespace folded, of at most 600 characters."""
    text = re.sub(r"\s+", " ", text).strip()
    return text if len(text) <= 600 else text[:599] + "\u2026"


def lead_carry_review(args) -> None:
    """Carry a story's captured review across commits the lead judged need no new round, showing them first.

    The state tool's carry-review does the carry and every check on it; this shows from..to, the diff the judgement
    rests on, before that write, and passes the state tool's refusal through unchanged."""
    c = cfg()
    key = c.require(args.key)
    heads = []
    for given in (args.from_head, args.to_head):
        found = git("rev-parse", "--verify", "--quiet", f"{given}^{{commit}}", check=False)
        if not found:
            git("fetch", "-q", c.remote, c.branch(key), check=False)
            found = git("rev-parse", "--verify", "--quiet", f"{given}^{{commit}}", check=False)
        if not found:
            raise Stop(f"no commit {given} here or on {c.remote}/{c.branch(key)}: name the heads the record holds")
        heads.append(found)
    from_head, to_head = heads
    changed = git("diff", "--name-status", "--no-renames", f"{from_head}..{to_head}").splitlines()
    summary = git("diff", "--shortstat", f"{from_head}..{to_head}") or "no changes"
    print(f"{key}'s review carries from {from_head[:10]} to {to_head[:10]} across: {summary.strip()}")
    for line in changed:
        status, _, path = line.partition("\t")
        print(f"  {status:<2} {path}")
    sys.stdout.flush()  # shown before the write, and before a refusal on stderr when both go to one pipe
    done = state_tool("carry-review", "--writer", "lead", "--subject", key, "--from", from_head, "--to", to_head,
                      "--reason", args.reason, check=False)
    try:
        answer = json.loads(done.stdout)
    except ValueError:
        answer = {}
    answer = answer if isinstance(answer, dict) else {}
    if done.returncode != 0:
        said = f"{answer['code']}: {answer.get('error', '')}" if answer.get("code") else (done.stderr or done.stdout).strip()
        raise Stop(f"the state tool refused the carry: {said}")
    print(f"carried: {tracker_publisher.said(answer['entry'])}" if isinstance(answer.get("entry"), dict) else "carried")


def lead_init(args) -> None:
    c = cfg()
    # Before anything is written, a plan review adopted included: the supervisor it starts runs the Node on this PATH.
    require_node(c.release, "lead-init")
    c.check_lanes({})
    if c.ship and not c.ship.get("toolingCommit"):
        raise Stop(f"{c.delivery_where}: ship.toolingCommit isn't set")
    adoptable = adoptable_plan_review(c, c.plan)
    # A planning record plan-open made for this delivery is taken over in place, once its plan is jointly approved.
    planning = planning_record(c)
    if planning is not None:
        if args.replace:
            raise Stop(f"collab.record_shared: {c.state} is {c.delivery}'s planning record, shared with its seats; "
                       "lead-init takes it over in place, so run it without --replace")
        tool, journal, seat = record_seat(c, c.delivery, c.state)
        if not tool.holds(journal, seat, "delivery"):
            # Before anything stops: this seat's planning supervisor keeps syncing.
            raise Stop(f"scope.not_held: only the holder of delivery, seat {tool.holder(journal, 'delivery')}, takes "
                       "the planning record over; scope request --scope delivery asks for it")
        joint_approval(c, adoptable)
    if adoptable:
        print(adopt_plan_review(c, adoptable, c.delivery))
    if plan_declared(c):
        rounds = plan_review_rounds(c)
        if rounds and plan_review_state(c, rounds) == "open" and (args.replace or not any(
                entry["type"] == "snapshot" for entry in read_plan_log(c))):
            raise Stop(f"the plan review is still open after round {rounds[-1]['round']}: align it with another round, "
                       f"or have the operator end it ({flow_command()} plan-review end --reason TEXT), before freezing "
                       "the plan")
        # Refused before the record starts, so a criterion the view can't read is corrected before anything is kept.
        check_plan(build_plan(c, [snapshot_entry(c, late=False)]), c)
    problems = setup_problems(c)
    stale = None if args.replace or planning is not None else stale_record(c)
    if stale:
        problems.insert(0, stale)
    if problems:
        raise Stop(f"lead-init refuses until each of these is fixed (doctor --delivery {c.delivery} reports them too):"
                   + "".join(f"\n  - {problem}" for problem in problems))
    sections = plan_sections(c.shelf.text(c.plan) or "")
    planned = [planned_entry(c, key, sections) for key in c.stories]
    # The record's finish items take no other keys: covers, label and at are the plan's.
    finish = [{"id": f["id"], "text": f["text"], "met": False} for f in c.finish]
    ownership = c.effective_ownership({})
    overlaps = ownership_overlaps(ownership, tracked_at_base(c), shared_outputs(c))
    if overlaps:
        raise Stop(f"lanes own the same files: {'; '.join(overlaps)}")
    # The integration step's facts are read against this: written only when the delivery rejoins a target.
    target = c.raw.get("integrationTarget")
    integration = {"integration": {"base": c.base_branch, "target": target, "remote": c.remote}} if target else {}
    seed = {"meta": {"trackerParent": c.delivery, "handoffsNeedAcceptance": True, **integration}, "planned": planned,
            "finish": finish, "laneOwnership": ownership, "regionsSettled": 0}
    for line in replace_record(c) if args.replace else []:
        print(line)
    if planning is not None:
        # Its journal, partitions and hosted identity carry on: the delivery's entries follow the planning ones.
        # The planning record's supervisor gives way to the delivery's, which lead-init starts below.
        if (said := ask_supervisor_to_stop(c, why="held")):
            print(said)
        state_tool("patch", "--writer", "lead", "--version", str(json_object(c.state / "state.json")["version"]),
                   "--patch", json.dumps({**seed, "meta": {**seed["meta"], "phase": "delivery"}}))
    else:
        state_tool("init", "--headline", c.raw.get("headline", c.delivery), "--seed", json.dumps(seed))
        state_tool("journal", "--kind", "record.started",
                   "--data", json.dumps({"base": {"ref": c.base_ref, "head": git("rev-parse", c.base_ref)}}))
    for item in planned:  # in plan order: the plan's approval refines each story, when the tracker refines
        if (approved := story_approved(c, item["subject"])) is not None:
            state_tool("journal", "--kind", "story.approved", "--subject", item["subject"], "--data", json.dumps(approved))
    if plan_declared(c):
        with plan_lock(c):
            if not any(entry["type"] == "snapshot" for entry in read_plan_log(c)):
                write_snapshot(c, late=False)
            rebuild_plan(c)
    print(f"initialized {c.state} with {len(planned)} planned stories across {len(c.lanes)} lanes"
          + (f"; wrote {c.state / PLAN_FILE}" if (c.state / PLAN_FILE).exists() else ""))
    if (apart := c.record_apart_note()):
        print(apart)
    record_session(c, "lead")
    for item in planned:
        if (outcome := refine_outcome(c, item["subject"])) is not None:
            print(f"  refine: {outcome}")
    start_hosted(c)
    if (line:=hosted_line(c)):print(line)
    if args.no_supervisor or supervisor_off():
        register_delivery(c, None)
        print(f"supervisor: not started; start it with {flow_command()} lead-run --resume")
    else:
        print(f"supervisor: running; live view {start_supervisor(c)}{live_fallback(c.state)}")

# The deliveries on one machine's checkouts of a repository, beside its git common directory, where the merge slots
# are: one entry a delivery, <git-common-dir>/agent-skills/deliveries/<key>.json, holding its key, base, lead
# checkout, record folder and supervisor's pid, null while it was started with none. Every checkout and linked
# worktree of the repository names the same folder.
def registry_folder(root: Path) -> Path:
    common = Path(git("rev-parse", "--git-common-dir", cwd=root))
    return (common if common.is_absolute() else Path(root) / common).resolve() / "agent-skills" / "deliveries"


def registry_path(root: Path, key: str) -> Path:
    return registry_folder(root) / f"{key.replace('%', '%25').replace('/', '%2F')}.json"


def register_delivery(c, pid: int | None) -> None:
    """Write or refresh this delivery's registry entry: lead-init's with no pid when it starts no supervisor, and a
    supervisor's each time it takes its lock, which registers a delivery initialized before the registry existed too."""
    path = registry_path(c.root, c.delivery)
    path.parent.mkdir(parents=True, exist_ok=True)
    entry = {"key": c.delivery, "base": c.base_branch, "lead": str(c.root.resolve()), "state": str(c.state.resolve()),
             "pid": pid}
    staging = path.with_name(f".{path.name}.{os.getpid()}")
    staging.write_text(json.dumps(entry, indent=2) + "\n")
    os.replace(staging, path)


def unregister_delivery(c) -> str | None:
    path = registry_path(c.root, c.delivery)
    if not path.exists():
        return None
    path.unlink(missing_ok=True)
    return f"removed {c.delivery} from the deliveries registered beside the repository ({path})"


def peer_deliveries(c) -> list[dict]:
    """The other deliveries registered on this delivery's base, each with its `status`: `live` while its supervisor's
    pid runs, `stale` once it doesn't, `none` when it was started with no supervisor. An entry that can't be read is
    listed whatever its base, as `{file, status: unreadable}`, and stops nothing."""
    folder = registry_folder(c.root)
    peers = []
    for path in sorted(folder.glob("*.json")) if folder.is_dir() else []:
        try:
            entry = json.loads(path.read_text())
        except (OSError, ValueError):
            entry = None
        if not (isinstance(entry, dict) and all(isinstance(entry.get(name), str) and entry[name]
                                                for name in ("key", "base", "state"))
                and (entry.get("pid") is None or valid_pid(entry["pid"]))):
            peers.append({"file": path.name, "status": "unreadable"})
            continue
        if entry["key"] == c.delivery or entry["base"] != c.base_branch:
            continue
        pid = entry.get("pid")
        peers.append({**entry, "status": "none" if pid is None else "live" if pid_runs(pid) else "stale"})
    return peers


def peer_status_words(peer: dict) -> str:
    if peer["status"] == "live":
        return f"live, pid {peer['pid']}"
    if peer["status"] == "stale":
        return f"stale: its supervisor, pid {peer['pid']}, isn't running"
    return "no supervisor"


def peer_line(peer: dict) -> str:
    """A peer as doctor --delivery lists it: its supervisor, its lead checkout, and what its queue is checking and
    has queued, read from its record through its entry."""
    if peer["status"] == "unreadable":
        return f"{peer['file']}: unreadable"
    said = f"{peer['key']} ({peer_status_words(peer)}; led from {peer.get('lead')})"
    state = json_object(Path(peer["state"]) / "state.json")
    if not state:
        return f"{said}: its record {peer['state']} can't be read"
    current = ((state.get("meta") or {}).get("checking") or {}).get("now")
    checking = current.get("subject") if isinstance(current, dict) else None
    queued = [item.get("subject") for item in state.get("queue") or [] if isinstance(item, dict)
              and item.get("stage") in ("queued", "syncing", "synced", "checked") and item.get("subject") != checking]
    return f"{said}: checking {checking or 'nothing'}; queued {', '.join(queued) or 'nothing'}"


def slot_line(c) -> str:
    """Who holds this delivery's base's merge slot, and since when, from the holder file beside it: shown only while
    the pid it names runs, since the file of a holder that died stays behind."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    holder = delivery_state.slot_holder(delivery_state.merge_slot_path(c.root, c.base_branch))
    if holder and valid_pid(holder.get("pid")) and pid_runs(holder["pid"]):
        return (f"{c.base_branch}'s merge slot is held by {holder.get('delivery') or 'an unnamed delivery'} "
                f"(pid {holder['pid']}, since {holder.get('since') or 'an unrecorded time'})")
    return f"{c.base_branch}'s merge slot is free"


def planned_entry(c, key: str, sections: list | None = None) -> dict:
    s = c.stories[key]
    return {"subject": key, "title": f"{c.label(key)}: {s['title']}" if s.get("label") else s["title"],
            "lane": s["lane"], "stage": "planned", **plan_members(c, key, sections)}


def plan_members(c, key: str, sections: list | None = None) -> dict:
    """What the record's waits are derived from, for one story: `after`, the keys its delivery-file story is ordered
    after, and `files`, the paths its plan section's `Files:` sentence names. Each is left out when it has none."""
    if sections is None:
        sections = plan_sections(c.shelf.text(c.plan) or "")
    after = list(c.stories[key].get("after") or [])
    files = section_files(story_section(sections, key) or "")
    return {**({"after": after} if after else {}), **({"files": files} if files else {})}


def with_plan_members(c, planned: list[dict]) -> list[dict] | None:
    """The planned work with each delivery-file story's missing `after` and `files` filled in, or None when none lacks
    what the plan gives it. A member already there is kept as it stands."""
    sections = plan_sections(c.shelf.text(c.plan) or "")
    filled, changed = [], False
    for entry in planned:
        if entry["subject"] in c.stories:
            missing = {name: value for name, value in plan_members(c, entry["subject"], sections).items()
                       if name not in entry}
            if missing:
                entry, changed = {**entry, **missing}, True
        filled.append(entry)
    return filled if changed else None


class Unreasoned(Stop):
    """Registration refused: a story added after the plan froze, with no `why` for its `added` change."""


def unregistered(c, state: dict) -> list[str]:
    """The delivery file's stories the record doesn't hold yet. A record holding no work at all is lead-init's to
    fill, so it has none."""
    if not state.get("planned") and not state.get("queue"):
        return []
    held = {item["subject"] for item in [*state["queue"], *state.get("planned", [])]}
    return [key for key in c.stories if key not in held]


def records_changes(c) -> bool:
    """Registration records an `added` change once the plan chapter is on or its snapshot is kept."""
    return plan_declared(c) or any(entry["type"] == "snapshot" for entry in read_plan_log(c))


def story_why_problem(c, key: str) -> str | None:
    """What is wrong with a story's `why`, as its `added` change would carry it; None when it can carry it."""
    return why_problem(c, c.stories[key].get("why"))


def why_problem(c, why: object) -> str | None:
    """What is wrong with a `why` as an `added` change would carry it; None when the plan can carry it."""
    if why is None:
        return "has no `why`"
    views = plan_validator(c)
    try:
        views._text(why, "why", views.PLAN_TEXT)
    except views.ConfigError as error:
        return f"has a `why` the plan can't carry ({str(error).removeprefix('why: ')})"
    return None


def unreasoned_problems(c, keys: list[str]) -> list[str]:
    if not keys or not records_changes(c):
        return []
    return [f"{key} {problem}" for key in keys if (problem := story_why_problem(c, key))]


def unreasoned_refusal(c, problems: list[str]) -> Unreasoned:
    return Unreasoned(
        f"{'; '.join(problems)}: a story added to {c.delivery_where} after the plan froze at lead-init is registered "
        "only with its reason; fix: give it a `why` there, one line saying why it joins the delivery, which its "
        "`added` change carries, commit and push the delivery file, then run this again. Nothing was registered")


def check_registrable(c) -> None:
    """Refuse, before anything is written, while registration would refuse a story added without its reason."""
    if not (c.state / "state.json").exists():
        return
    problems = unreasoned_problems(c, unregistered(c, load_state()["state"]))
    if problems:
        raise unreasoned_refusal(c, problems)


def register_stories(c) -> list[str]:
    """Stories added to the delivery after lead-init join the record as planned work, so the live view shows them
    before they're assigned. One the tracker reconcile already filed as a follow-up moves out of the follow-ups.
    Each one's `added` change carries the `why` its story gives in the delivery file; a story with none is refused,
    with nothing registered. Returns the keys added; a delivery not yet initialized is left to lead-init."""
    if not (c.state / "state.json").exists():
        return []
    # Under the plan's lock: lead-plan's whole-story add writes the delivery file before it plans the story, and a
    # sweep registering it in between would record its `added` change a second time.
    with plan_lock(c):
        return _register_stories(c)


def _register_stories(c) -> list[str]:
    added: list[str] = []

    def compute(doc: dict) -> dict | None:
        state = doc["state"]
        added.clear()
        added.extend(unregistered(c, state))
        # A planned entry found without the plan's order or files, as an older release wrote it, gains them here.
        planned = with_plan_members(c, state.get("planned", [])) or state.get("planned", [])
        if not added:
            return None if planned is state.get("planned", []) else {"planned": planned}
        problems = unreasoned_problems(c, added)
        if problems:
            raise unreasoned_refusal(c, problems)
        followups = [f for f in state["followups"] if f["id"] not in added and f.get("reference") not in added]
        return {"planned": [*planned, *(planned_entry(c, key) for key in added)], "followups": followups}
    if patch_from(compute, "the stories added to the delivery") is None or not added:
        return []
    for key in added:
        state_tool("journal", "--kind", "story.added", "--subject", key, "--data", json.dumps(story_added(c, key)))
        if (approved := story_approved(c, key)) is not None:
            state_tool("journal", "--kind", "story.approved", "--subject", key, "--data", json.dumps(approved))
    if records_changes(c):
        for key in added:
            change = {"kind": "added", "subjects": [key], "by": "lead", "title": c.stories[key]["title"],
                      "source": "registration"}
            if "why" in c.stories[key]:
                change["why"] = c.stories[key]["why"]
            record_plan_change(c, change)
    return added


def lead_brief(args) -> None:
    c = cfg()
    c.check_lanes()
    for key in register_stories(c):
        print(f"registered {key} in the record as planned work")
    moved = rebuild_plan(c)
    if moved:
        print(f"rebuilt {c.state / PLAN_FILE}: {moved}")
    template = (TOOL / "templates/lane-brief.md").read_text()
    in_app = (TOOL / "templates/lane-brief.in-app.md").read_text() if c.in_app else ""
    notes = (c.shelf.text(c.brief_notes) or "").strip() if c.brief_notes else ""
    state = c.record_state()
    lane_rows = "\n".join(f"| {lane} | {', '.join(k for k in c.stories if c.lane_of(k, state) == lane)} | "
                          f"{', '.join(f'`{g}`' for g in owns)} |" for lane, owns in c.effective_ownership(state).items())
    story_rows = "\n".join(
        f"| {k} | {c.label(k)} | {', '.join(f'`{p}`' for p in s.get('pinned', [])) or '-'} | "
        f"{'; '.join([requirement_label(r) for r in c.requirements(k)] + (['video'] if s.get('evidence') == 'video' else [])) or 'none'} |"
        for k, s in c.stories.items())
    values = {
        "delivery": c.delivery, "headline": c.raw.get("headline", c.delivery), "plan": str(c.plan),
        "flow": flow_command(), "machine": machine_command(), "config": c.config_named, "base_branch": c.base_branch, "base_ref": c.base_ref, "remote": c.remote,
        "branch": c.branch_pattern.replace("{key}", "<key>"),
        "lane_checkout": c.lane_pattern.replace("{key}", "<key>"),
        "state": str(c.state.resolve()), "lead_checkout": str(c.root.resolve()), "bound": str(c.bound), "work": c.work,
        "lenses": "\n".join([f"- {', '.join(f'`{lens}`' for lens in MANDATED_LENSES)}: mandated, in every round.",
                              *(f"- `{lens}`: {charter_purpose(c.lenses[lens][1]) or '(its charter states no purpose)'}"
                                for lens in c.story_lenses if lens not in MANDATED_LENSES and lens not in c.on_request),
                              *([on_request_line(c)] if c.on_request else [])]),
        "gates": "\n".join(f"   - `{g['id']}`, the binding's check, run through `run-checks`" if g.get("check") else
                           f"   - `{' '.join(expand_argv(g['argv'], base=c.base_ref, key='<key>', delivery=c.delivery))}`"
                           for g in c.gates) or "   - (none declared)",
        "never_touch": ", ".join(f"`{p}`" for p in c.never_touch) or "(nothing listed)",
        "listings": "".join(f" Adding or removing an output {' or '.join(f'`{p}`' for p in listed)} lists needs that file's "
                            "owner: ask the lead to grant it before you hand off. Refreshing its digests alone needs no grant."
                            for listed in [[e["path"] for e in (c.binding.get("regenerable") or {}).get("listings", [])
                                            if e["path"] in shared_outputs(c)]] if listed),
        "lanes": lane_rows, "stories": story_rows, "in_app": in_app, "notes": notes or "(none)",
        "lease": (c.in_app or {}).get("lease", "in-app"), "port": str((c.in_app or {}).get("port", "")),
        "tracker": c.issue_url.replace("{key}", "<key>"), "authority": authority_text(),
        "transitions": transitions_text(),
        "pr_review": pr_review_text(),
    }
    fill = lambda t: re.sub(r"\{\{(\w+)\}\}", lambda m: values.get(m.group(1), m.group(0)), t)
    values["in_app"] = fill(values["in_app"])  # the in-app part has its own placeholders; notes are left as written
    out = c.root / c.lane_brief
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(fill(template))
    print(f"wrote {out}")


# Where the tracker snapshot is kept: serve's refresh, under the record, and lead-reconcile's, beside it.
TRACKER_SNAPSHOTS = ("snapshots/tracker.json", "../snapshots/trackerSnapshot.json")


def tracker_snapshot_items(c) -> dict | None:
    """The newest tracker snapshot kept for the delivery, as its items by subject; None when none is kept."""
    newest = None
    for rel in TRACKER_SNAPSHOTS:
        try:
            snapshot = json.loads((c.state / rel).read_text())
        except (OSError, ValueError):
            continue
        if not isinstance(snapshot, dict) or snapshot.get("source") != "tracker" or not isinstance(snapshot.get("items"), list):
            continue
        if newest is None or str(snapshot.get("takenAt", "")) > str(newest.get("takenAt", "")):
            newest = snapshot
    if newest is None:
        return None
    return {item["subject"]: item for item in newest["items"] if isinstance(item, dict) and "subject" in item}


def no_summary(key: str) -> str:
    """The note for a story whose tracker item carries no summary: the live view's card reads one only from the
    first paragraph under the ticket's `## Summary` heading, so it would show none."""
    return f"{key}'s ticket has no `## Summary`; its card will show none"


def story_readiness(c, key: str) -> tuple[str, str | None]:
    """Whether a story's tracker item offers the first start move not yet made, from the tracker snapshot: ("ready",
    None), ("not-ready", why), or ("not-checked", why) when the snapshot can't say. It walks the start moves as the
    publisher's move does: a move whose `targets` entry is the item's status is made, the whole start is made when the
    last move's is, and a backlog item with every move made is ready. Under `refine`, an item offering its first refine
    move not yet made is ready too, since the plan's approval makes it. An item with a status and no offered moves is on
    a tracker that restricts no move, so its next move reads as offered. Nothing to check with no start move, or for an item already under way. It reads; it never
    moves anything."""
    transitions = tracker_conf(c)["transitions"]
    moves = transitions.get("start") or []
    targets = transitions.get("targets") or {}
    if not moves:
        return "ready", None
    items = tracker_snapshot_items(c)
    if items is None:
        return "not-checked", f"{key}: readiness wasn't checked: there is no tracker snapshot"
    item = items.get(key)
    if item is None:
        return "not-checked", f"{key}: readiness wasn't checked: the tracker snapshot doesn't list it"
    if item.get("state") != "backlog":
        return "ready", None
    status = item.get("status")
    offered = item.get("offeredTransitions")
    if not isinstance(offered, list) and not status:
        return "not-checked", f"{key}: readiness wasn't checked: the tracker snapshot doesn't list its offered moves"
    # Under refine, an item is also ready when it offers its first refine move not yet made, since the plan's approval
    # makes it; one that offers neither that nor its next start move is refused, naming the refine move.
    refining = next_move(transitions.get("refine") or [], status, targets)
    if refining is not None and (not isinstance(offered, list) or refining in offered):
        return "ready", None
    following = next_move(moves, status, targets)
    if following is None or not isinstance(offered, list) or following in offered:
        return "ready", None
    if refining is not None:
        return "not-ready", (f"{key} is in {status or 'a status the snapshot does not name'}: "
                             f"\"{refining}\" isn't offered; refine it first")
    return "not-ready", (f"{key} is in {status or 'a status the snapshot does not name'}: "
                         f"\"{following}\" isn't offered; refine it first")


def next_move(moves: list[str], status: str | None, targets: dict) -> str | None:
    """The first of `moves` not yet made, as the publisher's move reads them, or None when every move is made: an item
    at the last move's target has had them all made, and otherwise a move is made when its own target is the status."""
    if not moves or (status and targets.get(moves[-1]) == status):
        return None
    return next((move for move in moves if not status or targets.get(move) != status), None)


def refine_outcome(c, key: str) -> str | None:
    """What the plan's approval will do to a story's tracker item, from the tracker snapshot, as one line: refine it,
    find it refined already, or find it can't be moved; None when the tracker refines nothing."""
    transitions = tracker_conf(c)["transitions"]
    moves = transitions.get("refine") or []
    if not moves:
        return None
    item = (tracker_snapshot_items(c) or {}).get(key)
    status = (item or {}).get("status")
    offered = (item or {}).get("offeredTransitions")
    if not status and not isinstance(offered, list):
        return f"{key}: whether the plan's approval refines it wasn't checked: the tracker snapshot doesn't say"
    move = next_move(moves, status, transitions.get("targets") or {})
    if move is None:
        return f"{key}: refined already ({status})"
    if not isinstance(offered, list) or move in offered:
        return f"{key}: the plan's approval will refine it (\"{move}\" from {status or 'its status'})"
    return f"{key}: the plan's approval can't refine it: \"{move}\" isn't offered from {status or 'its status'}"


def is_lead_checkout(c, branch: str) -> bool:
    return branch in (c.base_branch, f"lead/{c.delivery}") or c.root.resolve() == c.lane_checkout(c.delivery).resolve()


def require_lead_checkout(c) -> None:
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=c.root, check=False)
    if not is_lead_checkout(c, branch):
        raise Stop(f"run this in the lead checkout on {c.base_branch} or in {c.lane_checkout(c.delivery)}")


def base_move_path(c) -> Path:
    common = (c.root / git("rev-parse", "--git-common-dir", cwd=c.root)).resolve()
    return common / "run-delivery" / f"base-move-{c.delivery}.json"


def save_base_move(path: Path, intent: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(f".{os.getpid()}.tmp")
    with temporary.open("w", encoding="utf-8") as stream:
        stream.write(json.dumps(intent, indent=2) + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def require_no_base_move(c) -> None:
    if base_move_path(c).exists():
        raise Stop(f"base move pending at {base_move_path(c)}; keep the supervisor parked and resume with "
                   f"{flow_command()} lead-sync --merge --resume")


def restore_move_installation(c, intent: dict) -> None:
    """Let the supported lifecycle update the prior installation, including its host projections."""
    for path in intent["installationPaths"]:
        if git("ls-tree", intent["oldHead"], "--", path):
            git("restore", f"--source={intent['oldHead']}", "--staged", "--worktree", "--", path)
        else:
            git("rm", "-r", "-q", "--ignore-unmatch", "--", path)


def managed_installation_paths() -> set[str]:
    """Use the lifecycle's fixed projection definitions rather than duplicating host paths."""
    generation = str(GENERATION)
    if generation not in sys.path:
        sys.path.insert(0, generation)
    from agent_skills.hosts import exposure_records
    from agent_skills.receipt import SETTINGS_FILE
    return {".agent-skills", SETTINGS_FILE, *[entry["root"] for entry in exposure_records()]}


def installation_paths(*receipts: dict) -> list[str]:
    paths = {".agent-skills"}
    for receipt in receipts:
        paths.update(entry["root"] for entry in receipt.get("exposures", []))
        if receipt.get("hooks", {}).get("file"):
            paths.add(receipt["hooks"]["file"])
    managed = managed_installation_paths()
    if not paths <= managed:
        raise Stop("an installation receipt names a path outside the supported managed projections")
    return sorted(paths)


def resolve_move_provenance(c, intent: dict) -> None:
    """Regenerate digest-only conflicts. Changed output listings on both sides need an operator merge."""
    path = "provenance.lock.json"
    if path not in git("diff", "--name-only", "--diff-filter=U").splitlines():
        return
    ancestor = git("merge-base", intent["oldHead"], intent["defaultHead"])
    versions = []
    try:
        for ref in (ancestor, intent["oldHead"], intent["defaultHead"]):
            raw = git("show", f"{ref}:{path}")
            document = json.loads(raw)
            listing = sorted((entry["id"], output["path"]) for entry in document["entries"] for output in entry["outputs"])
            versions.append(listing)
    except (Stop, ValueError, KeyError, TypeError):
        return  # A malformed or newly introduced lock needs the operator's listing decision.
    base, ours, theirs = versions
    if ours != base and theirs != base and ours != theirs:
        return
    take = intent["defaultHead"] if theirs != base else intent["oldHead"]
    git("restore", f"--source={take}", "--staged", "--worktree", "--", path)


def check_base_move_reader(archive: Path, directory: Path) -> None:
    """Read the existing record with the verified target archive before changing the installation."""
    with tempfile.TemporaryDirectory(prefix="run-delivery-base-reader-") as folder:
        root = Path(folder)
        with zipfile.ZipFile(archive) as release:
            release.extractall(root)
        scripts = ((root / "skills/run-delivery/scripts/run_delivery.py", "lead-sync"),
                   (root / "skills/orchestrate-work/scripts/delivery_state.py", "base-move"))
        for script, command in scripts:
            help_text = run([sys.executable, "-B", str(script), "--help"]).stdout
            commands = re.search(r"\{([a-z,-]+)\}", help_text)
            if commands is None or command not in commands.group(1).split(","):
                raise Stop("the default branch's archive must support lead-sync and the base-move writer transition")
        run([sys.executable, "-B", str(scripts[1][0]), "--dir", str(directory), "show"])


def read_base_move(path: Path) -> dict | None:
    if not path.exists():
        return None
    try:
        intent = json.loads(path.read_text())
        strings = ("checkout", "recordDirectory", "remote", "branch", "target", "oldHead", "defaultHead",
                   "expectedWriter", "archive", "metadata", "phase", "reason")
        if not isinstance(intent, dict) or intent.get("schemaVersion") != "delivery-base-move/1":
            raise ValueError()
        if any(not isinstance(intent.get(key), str) or not intent[key] or "\0" in intent[key] for key in strings):
            raise ValueError()
        commit = lambda value: isinstance(value, str) and re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", value)
        if not commit(intent["oldHead"]) or not commit(intent["defaultHead"]):
            raise ValueError()
        if intent.get("recordHead") is not None and not commit(intent["recordHead"]):
            raise ValueError()
        if "recordHead" not in intent or (intent["expectedWriter"] != "unpinned"
                                            and not re.fullmatch(r"[0-9a-f]{64}", intent["expectedWriter"])):
            raise ValueError()
        if any(not Path(intent[key]).is_absolute() for key in ("checkout", "recordDirectory", "archive", "metadata")):
            raise ValueError()
        release = intent.get("release")
        if not isinstance(release, dict) or any(not isinstance(release.get(key), str) or not release[key]
                                               for key in ("releaseId", "profile", "archiveSha256", "metadataSha256")):
            raise ValueError()
        if any(not re.fullmatch(r"[0-9a-f]{64}", release[key]) for key in ("archiveSha256", "metadataSha256")):
            raise ValueError()
        for key in ("installationPaths", "provenanceWriter"):
            if not isinstance(intent.get(key), list) or not intent[key] or any(not isinstance(item, str) or not item
                                                                            for item in intent[key]):
                raise ValueError()
        if not set(intent["installationPaths"]) <= managed_installation_paths():
            raise ValueError()
        phase = intent["phase"]
        if phase not in ("merging", "applying", "applied", "committing", "prepared", "published"):
            raise ValueError()
        if phase in ("committing", "prepared", "published"):
            if not commit(intent.get("preparedTree")) or not isinstance(intent.get("parents"), list) or not intent["parents"]:
                raise ValueError()
            if any(not commit(parent) for parent in intent["parents"]):
                raise ValueError()
        if phase in ("prepared", "published") and not commit(intent.get("preparedHead")):
            raise ValueError()
    except (OSError, ValueError, KeyError, TypeError):
        raise Stop(f"the pending base move at {path} is malformed or unreadable; inspect it before resuming") from None
    return intent


def check_moved_configuration(c, intent: dict) -> None:
    """Resolve the prepared checkout with its applied generation, before it can become authoritative."""
    actual = (load_json(c.root / RECEIPT) or {}).get("release")
    if actual != intent["release"]:
        raise Stop("the applied generation differs from the pending move's verified release; "
                   "restore that archive through the supported lifecycle, then run lead-sync --merge --resume")
    binding = load_json(c.root / ".agents/orchestration.json") or {}
    if not serves(binding, intent["branch"]):
        raise Stop("the merged .agents/orchestration.json must serve the integration base; resolve and stage it, then --resume")
    script = c.root / TOOL_PATH
    probe = """import importlib.util, json, os, sys
from pathlib import Path
spec = importlib.util.spec_from_file_location("prepared_move_config", sys.argv[1])
tool = importlib.util.module_from_spec(spec)
spec.loader.exec_module(tool)
os.environ["RUN_DELIVERY_LOCAL"] = "1"
config = tool.Config(Path.cwd(), sys.argv[2])
print(json.dumps({"state": str(config.state.resolve()), "release": str(config.release.resolve()),
                  "remote": config.remote, "base": config.base_branch, "target": config.raw.get("integrationTarget")}))
"""
    configured = json.loads(run([sys.executable, "-B", "-c", probe, str(script), c.delivery], cwd=c.root).stdout)
    expected = {"state": intent["recordDirectory"], "release": str((c.root / ".agent-skills/current").resolve()),
                "remote": intent["remote"], "base": intent["branch"], "target": intent["target"]}
    changed = [key for key in expected if configured.get(key) != expected[key]]
    if changed:
        raise Stop(f"merged configuration changes {', '.join(changed)}. Resolve .agents/orchestration.json, "
                   f".agents/run-delivery.json or {c.delivery_path} to retain record {intent['recordDirectory']} "
                   "and the applied .agent-skills/current writer. Stage the resolution and run lead-sync --merge --resume")



def finish_base_move(c, intent: dict) -> dict:
    """Use the newly applied generation's reader and writer while our caller owns the queue lock."""
    import importlib.util

    generation = (c.root / ".agent-skills/current").resolve()
    script = generation / "skills/orchestrate-work/scripts/delivery_state.py"
    spec = importlib.util.spec_from_file_location("delivery_state_base_move", script)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    try:
        return module.complete_base_move_locked(c.state, from_head=intent["oldHead"], to_head=intent["preparedHead"],
            default_head=intent["defaultHead"], expected_base=intent["recordHead"],
            expected_writer=intent["expectedWriter"], reason=intent["reason"])
    except module.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    except OSError as error:
        raise Stop(f"base record reconciliation stopped: {error}; resume with lead-sync --merge --resume") from None


def lead_sync(args) -> None:
    """Merge the default branch into an integration base, publishing before reconciling its record."""
    c = cfg()
    require_lead_checkout(c)
    target = c.raw.get("integrationTarget")
    if not target or target == c.base_branch:
        raise Stop("lead-sync --merge requires a declared integrationTarget different from the delivery base")
    path = base_move_path(c)
    intent = read_base_move(path)
    if not intent and args.resume:
        completed = load_state()["state"]["meta"].get("baseMove") or {}
        head = clean_head()
        if completed.get("to") == head == remote_head(c.base_branch):
            print(f"base move to {head} is already reconciled; lanes start from {c.remote}/{c.base_branch}")
            return
    if bool(intent) != bool(args.resume):
        raise Stop(f"{'an interrupted base move exists; use' if intent else 'no interrupted base move exists; omit'} --resume")
    if intent:
        if intent["checkout"] != str(c.root.resolve()):
            raise Stop(f"resume the pending base move from its lead checkout {intent['checkout']}")
        c.state = Path(intent["recordDirectory"])
        c.flow_log = c.state.parent / "flow-log"
        c.remote, c.base_branch, target = intent["remote"], intent["branch"], intent["target"]
        archive, metadata = Path(intent["archive"]), Path(intent["metadata"])
    else:
        if not args.archive or not args.metadata:
            raise Stop("give the default branch's verified --archive and --metadata")
        archive, metadata = args.archive.resolve(), args.metadata.resolve()
    if not archive.is_file() or not metadata.is_file():
        raise Stop("the base move needs its verified archive and metadata files to be present")
    if args.wait_seconds < 0:
        raise Stop("--wait-seconds must be zero or greater")
    git("fetch", "-q", c.remote, c.base_branch, target)
    if not intent:
        old = clean_head()
        if remote_head(c.base_branch) != old:
            raise Stop("the lead checkout must equal the published integration base before moving it")
        default = git("rev-parse", f"{c.remote}/{target}")
        target_receipt = json.loads(git("show", f"{default}:.agent-skills/active.json"))
        release = target_receipt["release"]
        current_receipt = json.loads((c.root / RECEIPT).read_text())
        if digest(archive) != release["archiveSha256"] or digest(metadata) != release["metadataSha256"]:
            raise Stop("the supplied archive and metadata must match the default branch's applied release digests")
        run([sys.executable, "-B", str(archive), "validate", "--archive", str(archive), "--metadata", str(metadata)])
        check_base_move_reader(archive, c.state)
        if is_ancestor(default, old) and current_receipt["release"] == release:
            print(f"{c.base_branch} already contains {target} and its applied archive; lanes start from {c.base_branch}")
            return
        writer = (c.flow_raw.get("baseMove") or {}).get("provenanceWriter")
        if not isinstance(writer, list) or not writer or not all(isinstance(word, str) and word for word in writer):
            raise Stop("configure baseMove.provenanceWriter as the repository's provenance writer argv")
        state = load_state()["state"]
        intent = {"schemaVersion": "delivery-base-move/1", "checkout": str(c.root.resolve()),
                  "recordDirectory": str(c.state.resolve()), "remote": c.remote,
                  "branch": c.base_branch, "target": target, "oldHead": old, "defaultHead": default,
                  "recordHead": state["meta"]["baseHead"],
                  "expectedWriter": (state["meta"].get("writerGeneration") or {}).get("archiveSha256", "unpinned"),
                  "archive": str(archive), "metadata": str(metadata), "release": release,
                  "installationPaths": installation_paths(current_receipt, target_receipt),
                  "provenanceWriter": writer, "phase": "merging", "reason": f"Merge {target} into {c.base_branch}"}
    if digest(archive) != intent["release"]["archiveSha256"] or digest(metadata) != intent["release"]["metadataSha256"]:
        raise Stop("the pending move's archive or metadata bytes changed; restore its verified files before resuming")
    said = ask_supervisor_to_stop(c, why="integration base move")
    if said:
        print(said)
    for line in stop_orphans(c):
        print(line)
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state

    c.flow_log.mkdir(parents=True, exist_ok=True)
    try:
        # The base's merge slot first, which every delivery on this machine shares, then this delivery's queue lock.
        with delivery_state.file_lock(supervisor_lock_path(c)), \
                delivery_state.merge_slot(c.root, c.base_branch, delivery=c.delivery, timeout=args.wait_seconds,
                                          doing={"what": "sync"},
                                          on_wait=lambda taken: say_peer_waits(c, 0 if taken else args.wait_seconds)), \
                delivery_state.file_lock(c.state / delivery_state.QUEUE_LOCK, timeout=args.wait_seconds):
            published = remote_head(c.base_branch)
            if published not in (intent["oldHead"], intent.get("preparedHead")):
                raise Stop("the integration base moved outside this operation; inspect the pending move before resuming")
            if not path.exists():
                if clean_head() != intent["oldHead"]:
                    raise Stop("the lead checkout changed while waiting for the queue lock")
                save_base_move(path, intent)
            if intent["phase"] in ("merging", "applying", "applied", "committing"):
                if intent["phase"] != "committing" and git("rev-parse", "HEAD") != intent["oldHead"]:
                    raise Stop("the pending merge's checkout head changed; leave conflict resolutions staged for --resume")
                if intent["phase"] == "merging":
                    merge_head = git("rev-parse", "-q", "--verify", "MERGE_HEAD", check=False)
                    if merge_head and merge_head != intent["defaultHead"]:
                        raise Stop("the checkout holds another merge; inspect it before resuming")
                    if not merge_head:
                        result = tool_commit("merge", "--no-ff", "--no-commit", intent["defaultHead"], check=False)
                        if result.returncode and not git("rev-parse", "-q", "--verify", "MERGE_HEAD", check=False):
                            raise Stop(result.stderr or result.stdout)
                    restore_move_installation(c, intent)
                    resolve_move_provenance(c, intent)
                    conflicts = git("diff", "--name-only", "--diff-filter=U").splitlines()
                    if conflicts:
                        raise Stop(f"resolve and stage these conflicts: {', '.join(conflicts)}. Keep the merge open and "
                                   f"resume with {flow_command()} lead-sync --merge --resume")
                    intent["phase"] = "applying"
                    save_base_move(path, intent)
                if intent["phase"] == "applying":
                    run([sys.executable, "-B", str(archive), "--root", str(c.root), "recover", "--maintenance"])
                    run([sys.executable, "-B", str(archive), "--root", str(c.root), "--product", "apply", "--archive",
                         str(archive), "--metadata", str(metadata), "--maintenance"])
                    actual = json.loads((c.root / RECEIPT).read_text())["release"]
                    if actual != intent["release"]:
                        raise Stop("the applied generation differs from the default branch's verified release")
                    intent["phase"] = "applied"
                    save_base_move(path, intent)
                if intent["phase"] == "applied":
                    require_node((c.root / ".agent-skills/current").resolve(), "lead-sync --merge")
                    check_moved_configuration(c, intent)
                    run(intent["provenanceWriter"], cwd=c.root)
                    new_state = c.root / ".agent-skills/current/skills/orchestrate-work/scripts/delivery_state.py"
                    run([sys.executable, "-B", str(new_state), "--dir", str(c.state), "show"])
                    git("add", "-A")
                    intent["preparedTree"] = git("write-tree")
                    intent["parents"] = [intent["oldHead"]]
                    merge_head = git("rev-parse", "-q", "--verify", "MERGE_HEAD", check=False)
                    if merge_head:
                        intent["parents"].append(merge_head)
                    intent["phase"] = "committing"
                    save_base_move(path, intent)
                if git("rev-parse", "HEAD") == intent["oldHead"]:
                    if git("write-tree") != intent["preparedTree"]:
                        raise Stop("the prepared merge tree changed before commit; inspect it before resuming")
                    tool_commit("commit", "-m", intent["reason"])
                if (git("rev-parse", "HEAD^{tree}") != intent["preparedTree"]
                      or git("show", "-s", "--format=%P", "HEAD").split() != intent["parents"]
                      or git("show", "-s", "--format=%B", "HEAD") != intent["reason"]):
                    raise Stop("the checkout's new commit does not match the prepared base move")
                intent["preparedHead"] = clean_head()
                intent["phase"] = "prepared"
                save_base_move(path, intent)
            if clean_head() != intent["preparedHead"]:
                raise Stop("the prepared base move changed; inspect it before resuming")
            check_moved_configuration(c, intent)
            for head in [intent["oldHead"], intent["defaultHead"],
                         *[q.get("syncedHead") or q["head"] for q in load_state()["state"]["queue"] if q["stage"] == "merged"]]:
                if not is_ancestor(head, intent["preparedHead"]):
                    raise Stop(f"merged commit {head} is not reachable from the prepared base")
            if published != intent["preparedHead"]:
                pushed = run(["git", "push", c.remote, f"{intent['preparedHead']}:refs/heads/{c.base_branch}"], check=False)
                if remote_head(c.base_branch) != intent["preparedHead"]:
                    raise Stop(f"base publication did not finish: {pushed.stderr or pushed.stdout}; retry with --resume")
            intent["phase"] = "published"
            save_base_move(path, intent)
            finish_base_move(c, intent)
            path.unlink()
    except delivery_state.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    print(f"moved {c.base_branch} to {intent['preparedHead']}; lanes start from {c.remote}/{c.base_branch}")
    resume = [sys.executable, "-B", str(c.root / TOOL_PATH), "--delivery", c.delivery, "lead-run", "--resume"]
    if not args.no_supervisor and not supervisor_off():
        print(run(resume).stdout.strip())
    else:
        print(f"supervisor: parked; resume with {shlex.join(resume)}")


def lead_upgrade_writer(args) -> None:
    """Park the lead's supervisor, transition under the queue lock, then resume the applied generation."""
    c = cfg()
    require_lead_checkout(c)
    release_tuple()  # Refuse an unidentified installation before parking anything.
    require_node(c.release, "lead-upgrade-writer")
    said = ask_supervisor_to_stop(c, why="writer generation transition")
    if said:
        print(said)
    for line in stop_orphans(c):
        print(line)
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    sys.dont_write_bytecode = True
    import delivery_state

    c.flow_log.mkdir(parents=True, exist_ok=True)
    try:
        # Prevent another supervisor from starting between the parked check and transition, and hold the base's merge
        # slot, as the queue does, within the binding's check timeout, around the transition's queue lock.
        with delivery_state.file_lock(supervisor_lock_path(c)), \
                delivery_state.merge_slot(c.root, c.base_branch, delivery=c.delivery,
                                          timeout=float(c.binding.get("checkTimeoutSeconds", 0)),
                                          doing={"what": "upgrade"},
                                          on_wait=lambda taken: say_peer_waits(
                                              c, 0 if taken else float(c.binding.get("checkTimeoutSeconds", 0)))):
            result = state_tool("writer-upgrade", "--writer", "lead", "--expected", args.expected,
                                "--reason", args.reason)
            pinned = json.loads(result.stdout)["state"]["meta"]["writerGeneration"]
    except delivery_state.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    print(f"record writer is {pinned['releaseId']} ({pinned['archiveSha256']})")
    if args.no_supervisor or supervisor_off():
        print(f"supervisor: parked; resume this generation with {flow_command()} lead-run --resume")
    else:
        print(f"supervisor: running from this generation; live view {start_supervisor(c)}")


def lead_push(args) -> None:
    c = cfg()
    branch = git("rev-parse", "--abbrev-ref", "HEAD")
    refuse_story_branch(c, branch, "lead-push")
    if branch == "HEAD":
        raise Stop("publish from the lead's branch")
    if not (c.state / "state.json").is_file():
        raise Stop("initialize the delivery record before publishing the base")
    if args.wait_seconds < 0:
        raise Stop("--wait-seconds must be zero or greater")
    if args.skip_guards and not (args.why or "").strip():
        raise Stop("--skip-guards needs --why, the reason the guards don't run, which is journaled")
    now_and_why(args, skip=args.skip_guards)
    head = clean_head()
    before = remote_head(c.base_branch)
    if not before:
        raise Stop(f"{c.remote} has no base branch {c.base_branch}")
    skipped = None
    if before != head:
        skipped = push_guards(c, head, args)

    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    sys.dont_write_bytecode = True
    import delivery_state  # the same lock implementation and path as the queue

    print(f"Waiting for the merge queue's lock to publish {c.base_branch}.", flush=True)
    try:
        with delivery_state.merge_slot(c.root, c.base_branch, delivery=c.delivery, timeout=args.wait_seconds,
                                       doing={"what": "push"}), \
                delivery_state.file_lock(c.state / delivery_state.QUEUE_LOCK, timeout=args.wait_seconds):
            git("fetch", "-q", c.remote, c.base_branch)
            current = remote_head(c.base_branch)
            if current != before:
                raise Stop(f"{c.base_branch}: base moved while waiting ({before[:12]} to {current[:12] or 'missing'}); "
                           f"bring the lead checkout up to date and retry {flow_command()} lead-push")
            if clean_head() != head or git("rev-parse", "--abbrev-ref", "HEAD") != branch:
                raise Stop("the lead checkout changed while waiting; inspect it and retry")
            if not is_ancestor(current, head):
                raise Stop(f"{head[:12]} cannot fast-forward {c.remote}/{c.base_branch} at {current[:12]}; "
                           "bring the lead checkout up to date and retry")
            if current == head:
                print(f"{c.remote}/{c.base_branch} already holds {head[:12]}")
                return
            if not is_lead_checkout(c, branch):
                # Older plan worktrees may have any branch name. Keep their plan-only scope.
                check_lead_plan_commits(c, current, head)
            git("push", c.remote, f"{head}:refs/heads/{c.base_branch}")
            state_tool("journal", "--kind", "base.published", "--data", json.dumps({"base": {"ref": c.base_ref, "head": head}, "from": current}))
            if skipped:
                state_tool("journal", "--kind", "decision.recorded", "--text",
                           f"published {head[:12]} to {c.base_branch} without running the guards {', '.join(skipped)}",
                           "--why", args.why.strip())
    except delivery_state.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    print(f"published {c.remote}/{c.base_branch} at {head[:12]}")


def push_guards(c, head: str, args) -> list[str] | None:
    """Run the guards of the binding at `head` through run-checks at the commit `lead-push` would publish, since the
    lead's own checkout isn't assumed prepared, refusing on a failure, which protects the shared base. With
    --skip-guards, run none and return their ids, for the decision the push journals."""
    shown = run(["git", "show", f"{head}:.agents/orchestration.json"], cwd=repo(), check=False)
    try:
        ids = guard_ids(json.loads(shown.stdout)) if shown.returncode == 0 else []
    except json.JSONDecodeError:
        ids = []  # an unreadable binding is the queue's to refuse
    if not ids:
        return None
    if args.skip_guards:
        print(f"guards skipped: {', '.join(ids)}: {args.why.strip()}")
        return ids
    print(f"Running the guards {', '.join(ids)} at {head[:12]} before publishing.", flush=True)
    # The guards claim their own slots in run-checks, before the merge slot is taken: lead-push claims none itself.
    records, _ = check_runs(c, head, ids, now_why=now_and_why(args, skip=args.skip_guards))
    for record in records:
        print(f"  guard {record_line(record)}; {check_median(c, record['check'])}")
    failed = [record for record in records if record["check"] in ids and record["result"] != "passed"]
    if failed:
        raise Stop(f"the guard(s) {', '.join(r['check'] for r in failed)} didn't pass at {head[:12]}, so nothing was "
                   f"published; fix the base, or publish with --skip-guards --why <reason>")
    return None


def story_added(c, key: str, why: str | None = None) -> dict:
    """A story.added's facts: the story's title, and why it joins, from the change or the delivery file."""
    why = why or c.stories[key].get("why") or f"planned work for {c.lane_of(key)}"
    return {"title": c.stories[key]["title"], "why": why}


def story_approved(c, key: str) -> dict | None:
    """A story.approved's facts, when the tracker refines a delivery's stories at its plan's approval: the story's
    title, the plan's path and its review record's, when it has one. None when no refine move is configured, so
    nothing journals it."""
    if not tracker_conf(c)["transitions"].get("refine"):
        return None
    review = c.plan.with_name(c.plan.stem + ".review.json")
    return {"title": c.stories[key]["title"], "plan": c.plan.as_posix(),
            **({"review": review.as_posix()} if (c.root / review).is_file() else {})}


def lead_flake(args) -> None:
    c = cfg()
    require_lead_checkout(c)
    base = remote_head(c.base_branch)
    if not base:
        raise Stop(f"{c.remote} has no base branch {c.base_branch}")
    flake = {"baseHead": base, "check": args.check, "ref": args.ref}
    if args.test:
        flake["tests"] = args.test

    def declare(doc: dict) -> dict:
        if remote_head(c.base_branch) != base:
            raise Stop(f"{c.base_branch} moved while declaring the flake; retry on its current head")
        current = [entry for entry in doc["state"].get("liveFlakes", [])
                   if entry["baseHead"] == base and entry["check"] != args.check]
        return {"liveFlakes": [*current, flake]}

    patch_from(declare, f"the live flake for {args.check}")
    summary = f"Declared live flake {args.ref} for {args.check} at {base}"
    state_tool("journal", "--kind", "flake.declared", "--data", json.dumps({"flake": args.ref, "check": args.check, "head": base}))
    print(summary)


def seed_ownership(c, state: dict) -> dict:
    ownership = c.effective_ownership(state)
    if "laneOwnership" in state:
        raise Stop("lane ownership is already in the record")
    overlaps = ownership_overlaps(ownership, tracked_at_base(c), shared_outputs(c))
    if overlaps:
        raise Stop(f"lanes own the same files: {'; '.join(overlaps)}")
    return {"laneOwnership": ownership}


@contextlib.contextmanager
def ownership_lock(c):
    """Keep lead ownership writes out of the interval between checking a hand-off and accepting it."""
    with (c.state / "lane-ownership.lock").open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        yield


def lead_own(args) -> None:
    c = cfg()
    require_lead_checkout(c)
    if not (c.state / "state.json").is_file():
        raise Stop("initialize the delivery record before changing lane ownership")
    require_scope(c, "delivery", "arbitrates files between lanes")
    with ownership_lock(c):
        change_ownership(c, args)


def region_story(c, args, state: dict, lane: str, key: str | None) -> str | None:
    """Decision 1: a claim's story, a key of this delivery assigned to the claim's lane, or None for the lane's own."""
    if key is None:
        return None
    if key not in c.stories or not any(entry.get("subject") == key for name in ("planned", "queue")
                                       for entry in state.get(name, [])):
        raise Stop(f"{key} is not a story this delivery's record holds")
    if c.lane_of(key, state) != lane:
        raise Stop(f"{key} is {c.lane_of(key, state)}'s story, not {lane}'s")
    return key


def described_claim(claim: dict, span: tuple[int, int] | None = None, base: str | None = None) -> str:
    start, end = span or (claim["start"], claim["end"])
    story = f" for {claim['story']}" if claim.get("story") else ""
    return f"{claim['lane']}'s{story} [{start}, {end}) at {(base or claim['baseHead'])[:12]}"


def regrant_words(helper, c, claims: list[dict], base: str) -> list[str]:
    """The claims on a path that don't map to ``base``, each with why: they need a regrant, and refuse nothing."""
    said = []
    for claim in claims:
        try:
            helper.mapped(c.root, claim, base)
        except helper.RegionError as error:
            said.append(f"{described_claim(claim)} needs a regrant: {error}")
    return said


def change_regions(c, args) -> None:
    helper = _region_ownership()
    path = args.region or args.revoke_region
    if not helper.valid_path(path):
        raise Stop("name a repository-relative file")
    numbered = args.start is not None or args.end is not None
    paired = args.anchor is not None or args.through is not None
    if args.revoke_region and (args.around is not None or args.insert or paired):
        raise Stop("a revocation matches the claim by its coordinates: --base, --start and --end")
    if paired and (args.anchor is None or args.through is None):
        raise Stop("--anchor TEXT and --through TEXT name a span together: give both")
    if paired and (numbered or args.around is not None):
        raise Stop("name the lines by --anchor and --through alone, not with --start, --end or --around")
    if not args.base or (args.around is None and not paired and (args.start is None or args.end is None)):
        raise Stop("a region claim needs --base COMMIT and --anchor TEXT --through TEXT, --around TEXT, "
                   "or --start LINE --end LINE")
    if args.around is not None and numbered:
        raise Stop("name the lines by --around TEXT or by --start and --end, not both")
    if args.revoke_region and args.story:
        raise Stop("--story names a grant's story; a revocation matches the claim by its coordinates")
    base_head = git("rev-parse", "--verify", "--end-of-options", f"{args.base}^{{commit}}")
    asked = None
    if args.region:
        try:
            args.start, args.end, asked = resolve_lines(helper, c, path, base_head, args.start, args.end, args.around,
                                                        args.insert, c.record_state().get("laneRegions", []),
                                                        pair=(args.anchor, args.through) if paired else None)
        except helper.RegionError as error:
            raise Stop(str(error)) from error
    claim = {"lane": args.lane, "path": path, "baseHead": base_head, "start": args.start, "end": args.end}
    if args.region:
        git("fetch", "-q", c.remote, c.base_branch)
        base = git("rev-parse", c.base_ref)
    said: dict = {}

    def compute(doc: dict) -> list[str]:
        state = doc["state"]
        ownership = state.get("laneOwnership")
        if ownership is None:
            raise Stop("seed this record with lead-own --seed first")
        if args.lane not in ownership:
            raise Stop("name a lane recorded for this delivery")
        regions = list(state.get("laneRegions", []))
        said.clear()
        if args.revoke_region:
            found = next((other for other in regions if helper.same_claim(other, claim)), None)
            if found is None:
                raise Stop(f"{args.lane} has no matching region claim for {path}")
            regions.remove(found)
            return ["--set", json.dumps({"/laneRegions": regions})]
        story = region_story(c, args, state, args.lane, args.story)
        granted = {**claim, "story": story} if story else dict(claim)
        if any(helper.same_claim(other, claim) and other.get("story") == story for other in regions):
            return None
        if owners_of(ownership, path):
            raise Stop(f"{path} already has a whole-file claim")
        if path in shared_outputs(c):
            raise Stop(f"{path} is a declared shared output")
        on_path = [other for other in regions if other["path"] == path]
        # A regrant: this lane's claims on the path, of this story, that a landing left needing one, give way to it.
        replaced = [other for other in on_path if other.get("regrant") and other["lane"] == args.lane
                    and other.get("story") == story]
        try:
            start, end = helper.mapped(c.root, granted, base)
            for other in on_path:
                if any(other is gone for gone in replaced):
                    continue
                if other["lane"] == args.lane and other.get("story") == story:
                    continue  # Decision 5: one lane's claims of one story are made one below, overlapping or touching
                try:
                    first, last = helper.mapped(c.root, other, base)
                except helper.RegionError:
                    continue  # Decision 3: a claim that no longer maps refuses no grant; it is named below
                if start < last and first < end:
                    raise Stop(f"{path} [{start}, {end}) overlaps {other['lane']}'s [{first}, {last}) at {base[:12]}")
            kept = [other for other in on_path if not any(other is gone for gone in replaced)]
            joined, runs = helper.coalesce(c.root, [*kept, granted], base_head)
            for claim_now in joined:
                if not any(claim_now is other for other in kept):
                    helper.mapped(c.root, claim_now, base)
            merged = [other for other in regions if other["path"] != path] + joined
        except helper.RegionError as error:
            raise Stop(str(error)) from error
        said.update(replaced=replaced, runs=runs, stale=regrant_words(
            helper, c, [other for other in on_path if not any(other is gone for gone in replaced)], base),
            written=[claim_now for claim_now in joined if not any(claim_now is other for other in kept)])
        return ["--set", json.dumps({"/laneRegions": merged})]

    if patch_from(compute, f"region ownership of {path}") is None and not args.revoke_region:
        print(f"{args.lane} already holds {path} [{args.start}, {args.end}) at {base_head}")
        return
    action = "revoked" if args.revoke_region else "granted"
    change = f"{action} {args.lane}'s {path} [{args.start}, {args.end}) at {base_head}"
    if args.story:
        change += f" for {args.story}"
    state_tool("journal", "--kind", f"ownership.{action}", "--lane", args.lane,
               *(["--subject", args.story] if args.story else []), "--data", json.dumps(
        {"path": path, "span": {"first": args.start, "after": args.end}, "base": {"ref": args.base, "head": base_head}}))
    print(change)
    for line in asked or []:
        print(f"  {line}")
    for written in said.get("written", []):
        print(f"  {written_lines(helper, c, written)}")
    for gone in said.get("replaced", []):
        print(f"  replaces {described_claim(gone)}, which needed a regrant")
    for run_ in said.get("runs", []):
        print(f"  made one claim at {base_head[:12]} of {', '.join(described_claim(other) for other in run_)}, "
              "which touch")
    for line in said.get("stale", []):
        print(f"  {line}")


GIVE = re.compile(r"(?P<lane>[^:+\s]+)(?:\+(?P<insert>before|after))?:"
                  r"(?:(?P<start>[0-9]+)-(?P<end>[0-9]+)|anchor=(?P<anchor>.+?)\.\.through=(?P<through>.+?)"
                  r"|around=(?P<around>.+?))(?:@(?P<key>[A-Za-z][A-Za-z0-9]*-[0-9]+))?")


def carve_gives(values: list[str]) -> list[dict]:
    """Each --give as {lane, start, end}, {lane, anchor, through} or {lane, around}, with its story and --insert side
    when it names them."""
    gives = []
    for value in values:
        found = GIVE.fullmatch(value)
        if not found:
            raise Stop(f"--give {value!r}: name it as LANE[+before|+after]:START-END[@KEY], "
                       "LANE[+before|+after]:anchor=TEXT..through=TEXT[@KEY] or LANE[+before|+after]:around=TEXT[@KEY]")
        give = {"lane": found["lane"], **({"story": found["key"]} if found["key"] else {}),
                **({"insert": found["insert"]} if found["insert"] else {})}
        if found["anchor"] is not None:
            give["pair"] = (found["anchor"], found["through"])
        elif found["around"] is not None:
            give["around"] = found["around"]
        else:
            start, end = int(found["start"]), int(found["end"])
            if start < 1 or end <= start:
                raise Stop(f"--give {value!r}: END must be greater than START, from line 1")
            give.update(start=start, end=end)
        gives.append(give)
    return gives


def resolve_lines(helper, c, path: str, base: str, start: int | None, end: int | None, around: str | None,
                  insert: str | None, regions: list[dict], taken: list[tuple[int, int]] = (),
                  pair: tuple[str, str] | None = None) -> tuple[int, int, list[str]]:
    """The span a grant or a give names at ``base``: by --anchor and --through (Decision 3), by --around's block
    (Decision 10) or its numbers, each edge at a statement's start in a Python file (Decision 11), widened by --insert
    past an edge into an unclaimed line (Decision 12). Returns it, and what to print of how it was read."""
    said = []
    if pair is not None:
        start, end = helper.anchor_pair(c.root, base, path, *pair)
        said.append(f"--anchor {pair[0]!r} --through {pair[1]!r} names [{start}, {end}) at {base[:12]}")
    elif around is not None:
        start, end = helper.anchored(c.root, base, path, around)
        said.append(f"--around {around!r} names [{start}, {end}) at {base[:12]}")
    helper.check_statements(c.root, base, path, start, end)
    if insert:
        held = list(taken)
        for claim in regions:
            if claim["path"] == path:
                with contextlib.suppress(helper.RegionError):
                    held.append(helper.mapped(c.root, claim, base))
        size = len(helper.text_lines(c.root, base, path))
        wider = helper.widened(start, end, insert, size, held)
        said.append(f"--insert {insert} widens [{start}, {end}) to [{wider[0]}, {wider[1]}), so an insertion "
                    f"{insert} its {'first' if insert == 'before' else 'last'} line falls inside")
        start, end = wider
    return start, end, said


def written_lines(helper, c, claim: dict) -> str:
    """Decision 9: a span written, with its first and last line as text at its base."""
    try:
        words = helper.span_lines(c.root, claim["baseHead"], claim["path"], claim["start"], claim["end"])
    except (helper.RegionError, IndexError) as error:
        words = f"its lines can't be read: {error}"
    return f"{described_claim(claim)}: {words}"


def change_carve(c, args) -> None:
    """Decision 4: a path's claims recomputed in one write, or nothing written."""
    helper = _region_ownership()
    path = args.carve
    if not helper.valid_path(path):
        raise Stop("name a repository-relative file")
    if not args.give:
        raise Stop("a carve gives lines: --give LANE:START-END[@KEY], as many as it needs")
    if args.start is not None or args.end is not None or args.lane or args.story:
        raise Stop("a carve names its lines in each --give, not with --lane, --start, --end or --story")
    if args.around is not None or args.insert or args.anchor is not None or args.through is not None:
        raise Stop("a carve names each give's lines in its --give: LANE[+before|+after]:around=TEXT[@KEY] or "
                   "LANE[+before|+after]:anchor=TEXT..through=TEXT[@KEY]")
    gives = carve_gives(args.give)
    git("fetch", "-q", c.remote, c.base_branch)
    base = git("rev-parse", c.base_ref)
    carve_base = git("rev-parse", "--verify", "--end-of-options", f"{args.base or base}^{{commit}}")
    asked: list[str] = []
    try:
        taken: list[tuple[int, int]] = []
        for give in gives:
            give["start"], give["end"], words = resolve_lines(
                helper, c, path, carve_base, give.get("start"), give.get("end"), give.pop("around", None),
                give.pop("insert", None), c.record_state().get("laneRegions", []), taken, give.pop("pair", None))
            taken.append((give["start"], give["end"]))
            asked += [f"{give['lane']}: {line}" for line in words]
    except helper.RegionError as error:
        raise Stop(f"the carve of {path} changes nothing: {error}") from error
    said: dict = {}

    def compute(doc: dict) -> list[str]:
        state = doc["state"]
        ownership = state.get("laneOwnership")
        if ownership is None:
            raise Stop("seed this record with lead-own --seed first")
        for give in gives:
            if give["lane"] not in ownership:
                raise Stop(f"--give names {give['lane']}, which isn't a lane recorded for this delivery")
            region_story(c, args, state, give["lane"], give.get("story"))
        if owners_of(ownership, path):
            raise Stop(f"{path} already has a whole-file claim")
        if path in shared_outputs(c):
            raise Stop(f"{path} is a declared shared output")
        try:
            result = helper.carve(c.root, list(state.get("laneRegions", [])), path, carve_base, gives)
            spans = []
            for claim in result["claims"]:
                if claim["path"] == path:
                    spans.append((helper.mapped(c.root, claim, base), claim))
            for i, (one, first) in enumerate(spans):
                for other, second in spans[i + 1:]:
                    if helper.overlapping(one, other):
                        raise Stop(f"the carve leaves {described_claim(first, one, base)} overlapping "
                                   f"{described_claim(second, other, base)}")
        except helper.RegionError as error:
            raise Stop(f"the carve of {path} changes nothing: {error}") from error
        said.clear()
        said.update(result)
        return ["--set", json.dumps({"/laneRegions": result["claims"]})]

    patch_from(compute, f"the carve of {path}")
    shown = lambda claim: {name: claim[name] for name in ("lane", "baseHead", "start", "end", "story") if name in claim}
    state_tool("journal", "--kind", "ownership.carved", "--data", json.dumps(
        {"path": path, "base": {"ref": c.base_branch, "head": carve_base},
         "removed": [shown(claim) for claim in said["removed"]], "added": [shown(claim) for claim in said["added"]]}))
    print(f"carved {path} at {carve_base}")
    for line in asked:
        print(f"  {line}")
    for claim in said["removed"]:
        print(f"  removed {described_claim(claim)}")
    for claim in said["added"]:
        print(f"  added {written_lines(helper, c, claim)}")


def change_carry(c, args) -> None:
    """Decision 5: the lane's claims on a path, of --story when it names one, carried to the current base when every
    base hunk since each claim's base lies wholly outside its lines; all of them, or nothing written."""
    helper = _region_ownership()
    path = args.carry
    if not helper.valid_path(path):
        raise Stop("name a repository-relative file")
    if not args.lane:
        raise Stop("name the lane whose claims to carry with --lane")
    if args.source or args.insert or any(value is not None for value in (
            args.base, args.start, args.end, args.around, args.anchor, args.through)):
        raise Stop("a carry maps the lane's claims as they stand to the current base: it takes --lane and --story only")
    git("fetch", "-q", c.remote, c.base_branch)
    base = git("rev-parse", c.base_ref)
    said: dict = {}

    def compute(doc: dict) -> list[str] | None:
        state = doc["state"]
        ownership = state.get("laneOwnership")
        if ownership is None:
            raise Stop("seed this record with lead-own --seed first")
        if args.lane not in ownership:
            raise Stop("name a lane recorded for this delivery")
        region_story(c, args, state, args.lane, args.story)
        regions = list(state.get("laneRegions", []))
        chosen = [claim for claim in regions if claim["path"] == path and claim["lane"] == args.lane
                  and (args.story is None or claim.get("story") == args.story)]
        if not chosen:
            raise Stop(f"{args.lane} has no region claim on {path}" + (f" for {args.story}" if args.story else ""))
        moved, refused = [], []
        for claim in chosen:
            try:
                moved.append((claim, helper.claim_at(claim, base, *helper.carry_span(c.root, claim, base))))
            except helper.RegionError as error:
                refused.append(f"{described_claim(claim)}: {error}")
        if refused:
            raise Stop(f"the carry of {path} writes nothing: " + "; ".join(refused))
        for old, new in moved:
            for other in regions:
                if other["path"] != path or any(other is gone for gone, _ in moved):
                    continue
                with contextlib.suppress(helper.RegionError):
                    held = helper.mapped(c.root, other, base)
                    if helper.overlapping((new["start"], new["end"]), held):
                        raise Stop(f"the carry of {path} writes nothing: {described_claim(new)} would overlap "
                                   f"{described_claim(other, held, base)}")
        moved = [(old, new) for old, new in moved if old != new]
        said.clear()
        said["moved"] = moved
        if not moved:
            return None
        swapped = {id(old): new for old, new in moved}
        return ["--set", json.dumps({"/laneRegions": [swapped.get(id(claim), claim) for claim in regions]})]

    patch_from(compute, f"the carry of {path}")
    if not said["moved"]:
        print(f"{args.lane}'s claims on {path} are already at {base[:12]}")
        return
    for old, new in said["moved"]:
        state_tool("journal", "--kind", "ownership.carried", "--lane", new["lane"],
                   *(["--subject", new["story"]] if new.get("story") else []), "--data", json.dumps(
            {"path": path, "from": {"first": old["start"], "after": old["end"]},
             "to": {"first": new["start"], "after": new["end"]}, "was": old["baseHead"],
             "base": {"ref": c.base_branch, "head": base}, **({"story": new["story"]} if new.get("story") else {}),
             "by": "lead"}))
        print(f"carried {described_claim(old)} to {written_lines(helper, c, new)}")


def in_flight_before(c, state: dict, lane: str, landed: str, merge: str, story: str | None) -> list[str]:
    """The lane's other stories still in flight on a branch that began before ``merge``: a claim carried to the merge
    maps for each only once it merges the base. With ``story``, that story alone, if it is one of them."""
    found = []
    pieces = [*state.get("planned", []), *state.get("queue", [])]
    for piece in pieces:
        key = piece.get("subject")
        if key == landed or key in found or c.lane_of(key, state) != lane or (story and key != story):
            continue
        if piece.get("stage") in ("merged", "settled"):
            continue
        heads = [ref for ref in (f"refs/remotes/{c.remote}/{c.branch(key)}", f"refs/heads/{c.branch(key)}")
                 if run(["git", "rev-parse", "--verify", "--quiet", ref], check=False).returncode == 0]
        if heads and any(run(["git", "merge-base", "--is-ancestor", merge, ref], check=False).returncode for ref in heads):
            found.append(key)
    return found


def settle_landings(c) -> str:
    """Decision 2, a supervisor step: each `candidate.merged` not settled yet, in journal order, one versioned patch
    under the ownership lock, then its entries. A record that settled none, from an earlier release, starts at its
    latest merge, or at 0 with none."""
    helper = _region_ownership()
    said = []
    with ownership_lock(c):
        # What to settle is read here; each write is computed again from the record it is pinned to.
        merges = [entry for entry in load_state()["journal"] if entry["kind"] == "candidate.merged"]
        state = c.record_state()
        if "regionsSettled" not in state:
            seed = merges[-1]["id"] if merges else 0
            patch_from(lambda fresh: None if "regionsSettled" in fresh["state"] else {"regionsSettled": seed},
                       "the first settled merge")
            return f"settled from journal entry {seed}"
        fetched = False
        for merge in merges:
            if merge["id"] <= state["regionsSettled"]:
                continue
            if not fetched:
                git("fetch", "-q", c.remote, c.base_branch)
                fetched = True
            try:
                landed = helper.merge_commit(c.root, c.base_ref, merge["data"]["head"])
            except helper.RegionError as error:
                raise Stop(f"can't find where {merge['subject']} landed on {c.base_ref}: {error}") from error
            outcome: dict = {}

            def compute(fresh: dict) -> dict | None:
                state = fresh["state"]
                if state.get("regionsSettled", 0) >= merge["id"]:
                    return None
                outcome.clear()
                regions = state.get("laneRegions", [])
                if not regions:
                    return {"regionsSettled": merge["id"]}
                if landed is None:
                    return None  # a pass after the base holds it settles it
                lane = c.lane_of(merge["subject"], state)
                result = helper.settle(c.root, regions, merge["subject"], lane, landed)
                outcome.update(result, lane=lane, inFlight={
                    id(new): in_flight_before(c, state, lane, merge["subject"], landed, new.get("story"))
                    for _, new in result["carried"]})
                return {"laneRegions": result["regions"], "regionsSettled": merge["id"]}

            try:
                written = patch_from(compute, f"the claims {merge['subject']}'s landing settles")
            except helper.RegionError as error:
                raise Stop(f"settling {merge['subject']}'s landing: {error}") from error
            if written is None and landed is None:
                later = [entry for entry in merges if entry["id"] > merge["id"]]
                if any(helper.merge_commit(c.root, c.base_ref, entry["data"]["head"]) for entry in later):
                    raise Stop(f"can't find where {merge['subject']} (journal entry {merge['id']}) landed on "
                               f"{c.base_ref}, though a later merge is there: its claims wait, and so does every later "
                               "landing's settle, until the lead settles its claims by hand and sets regionsSettled")
                said.append(f"{merge['subject']}'s merge isn't on {c.base_ref} yet")
                break
            subject = merge["subject"]
            for claim in outcome.get("released", []):
                state_tool("journal", "--kind", "ownership.released", "--lane", claim["lane"], "--subject", subject,
                           "--data", json.dumps({"path": claim["path"], "span": {"first": claim["start"], "after": claim["end"]},
                                                 "base": {"ref": c.base_branch, "head": claim["baseHead"]}, "merge": landed}))
            for old, new in outcome.get("carried", []):
                waiting = outcome["inFlight"][id(new)]
                state_tool("journal", "--kind", "ownership.carried", "--lane", new["lane"], "--subject", subject,
                           "--data", json.dumps({"path": new["path"], "from": {"first": old["start"], "after": old["end"]},
                                                 "to": {"first": new["start"], "after": new["end"]}, "was": old["baseHead"],
                                                 "base": {"ref": c.base_branch, "head": landed},
                                                 **({"story": new["story"]} if new.get("story") else {}),
                                                 **({"inFlight": waiting} if waiting else {})}))
            if outcome:
                said.append(f"{subject}: {len(outcome['released'])} released, {len(outcome['carried'])} carried, "
                            f"{len(outcome['regrant'])} to regrant")
                said += [f"carried {written_lines(helper, c, new)}" for _, new in outcome["carried"]]
            state = c.record_state()
    return "; ".join(said) or "nothing to settle"


def regrant_needs(state: dict) -> list[dict]:
    """Decision 2's "Needs you" items: each claim a landing left needing a regrant. None holds the close."""
    items = []
    for claim in state.get("laneRegions", []):
        mark = claim.get("regrant")
        if not isinstance(mark, dict):
            continue
        where = f"{claim['path']} [{claim['start']}, {claim['end']}) at {claim['baseHead'][:12]}"
        items.append({"holding": False, "source": "the record's region claims",
                      "text": f"{claim['lane']}'s claim on {where} needs a regrant after the merge {mark['merge'][:12]}: "
                      f"{mark['reason'][:300]}",
                      "clears": f"{flow_command()} lead-own --region {claim['path']} --lane {claim['lane']} ... "
                      "regranting it, or --revoke-region revoking it", "kind": "regrant", "who": "lead",
                      "lane": claim["lane"], **({"subject": claim["story"]} if claim.get("story") else {}),
                      "fields": {"path": claim["path"], "detail": mark["reason"][:300]}})
    return items


def change_ownership(c, args) -> None:
    if args.carve:
        change_carve(c, args)
        return
    if args.give:
        raise Stop("--give belongs to a carve: --carve PATH --give LANE:START-END[@KEY]")
    if args.carry:
        change_carry(c, args)
        return
    if (args.anchor is not None or args.through is not None) and not args.region:
        raise Stop("--anchor and --through name a grant's lines: use them with --region")
    if not (args.region or args.revoke_region or args.claim) and any(
            value is not None for value in (args.base, args.start, args.end)):
        raise Stop("--base, --start and --end require --region or --revoke-region")
    if args.story and not args.region:
        raise Stop("--story names a region grant's story: use it with --region")
    if args.claim:
        change_claims(c, args)
        return
    if args.seed:
        if args.lane or args.source:
            raise Stop("--seed takes neither --lane nor --from")
        patch_from(lambda doc: seed_ownership(c, doc["state"]), "the initial lane ownership")
        print("seeded lane ownership from the delivery configuration")
        return
    if not args.lane:
        raise Stop("name the receiving lane with --lane")
    if bool(args.move) != bool(args.source) or args.source == args.lane:
        raise Stop("--move requires --from naming a different lane")
    if args.region or args.revoke_region:
        change_regions(c, args)
        return
    pattern = args.move or args.grant or args.revoke
    if not pattern or Path(pattern).is_absolute() or any(part in ("", ".", "..") for part in pattern.split("/")):
        raise Stop("name a repository-relative file or pattern")
    files = tracked_at_base(c)
    shared = shared_outputs(c)

    def compute(doc: dict) -> list[str]:
        state = doc["state"]
        ownership = copy.deepcopy(state.get("laneOwnership"))
        if ownership is None:
            raise Stop("seed this record with lead-own --seed first")
        if args.lane not in ownership or args.source and args.source not in ownership:
            raise Stop("name lanes recorded for this delivery; add a new one with lead-add-lane --lane L")
        if args.source:
            if pattern not in ownership[args.source]:
                raise Stop(f"{args.source} has no claim for {pattern}")
            ownership[args.source].remove(pattern)
        if args.revoke:
            if pattern not in ownership[args.lane]:
                raise Stop(f"{args.lane} has no claim for {pattern}")
            ownership[args.lane].remove(pattern)
        elif pattern not in ownership[args.lane]:
            conflicts = sorted({claim["path"] for claim in state.get("laneRegions", [])
                                if fnmatch.fnmatchcase(claim["path"], pattern)})
            if conflicts:
                raise Stop(f"whole-file claim conflicts with region claims for {', '.join(conflicts)}")
            ownership[args.lane].append(pattern)
        overlaps = ownership_overlaps(ownership, files, shared)
        if overlaps:
            raise Stop(f"lanes own the same files: {'; '.join(overlaps)}")
        return ["--set", json.dumps({"/laneOwnership": ownership})]

    patch_from(compute, f"ownership of {pattern}")
    change = f"{args.lane} owns {pattern}" + (f", moved from {args.source}" if args.source else "")
    if args.revoke:
        change = f"revoked {args.lane}'s claim for {pattern}"
    facts = {"path": pattern, **({"movedFrom": args.source} if args.source and not args.revoke else {})}
    state_tool("journal", "--kind", "ownership.revoked" if args.revoke else "ownership.granted", "--lane", args.lane,
               "--data", json.dumps(facts))
    print(change)


# The plan's Units table and its lane sentences read only numbered lanes.
LANE_NAME = re.compile(r"lane-[1-9][0-9]*")


def lead_add_lane(args) -> None:
    """Add a lane to a running delivery: to the delivery file's `lanes` and the plan's Units table in one commit in the
    lead's checkout, and its ownership and `lanes[]` row in one state-tool patch. Each grant takes lead-own --grant's
    checks, and any refusal writes nothing."""
    c = cfg()
    lane = args.lane
    if not LANE_NAME.fullmatch(lane):
        raise Stop(f"name the lane lane-N, such as lane-{len(c.lanes) + 1}, not {lane!r}: the plan's Units table and "
                   "its lane sentences read only numbered lanes")
    require_lead_checkout(c)
    if not (c.state / "state.json").is_file():
        raise Stop("initialize the delivery record before adding a lane")
    require_scope(c, "delivery", "adds lanes")
    grants = list(dict.fromkeys(args.grant or []))
    for pattern in grants:
        if Path(pattern).is_absolute() or any(part in ("", ".", "..") for part in pattern.split("/")):
            raise Stop(f"name a repository-relative file or pattern, not {pattern!r}")
    with ownership_lock(c), plan_lock(c):
        root = lead_plan_checkout(c)
        raw = json.loads(c.delivery_path.read_text())
        if lane in raw["lanes"] or lane in c.effective_ownership(c.record_state()):
            raise Stop(f"{lane} is already a lane of {c.delivery}; give it files with lead-own --lane {lane} --grant "
                       "PATTERN")
        plan_path = root / c.plan
        plan_text = plan_with_lane(plan_path.read_text(), lane, grants)
        files, shared = tracked_at_base(c), shared_outputs(c)
        for pattern in grants:
            outputs = sorted(path for path in shared if fnmatch.fnmatchcase(path, pattern))
            if outputs:
                raise Stop(f"{', '.join(outputs)} is a shared output, which every lane refreshes and none owns; "
                           f"leave it out of {lane}'s grants")
        row = {"id": lane, "title": lane, "focus": "", "state": "idle", "waitingOn": None}

        def compute(doc: dict) -> list[str]:
            state = doc["state"]
            ownership = copy.deepcopy(state.get("laneOwnership"))
            if ownership is None:
                raise Stop("seed this record with lead-own --seed first")
            if lane in ownership or any(entry["id"] == lane for entry in state["lanes"]):
                raise Stop(f"{lane} is already a lane of {c.delivery}")
            conflicts = sorted({claim["path"] for claim in state.get("laneRegions", [])
                                if any(fnmatch.fnmatchcase(claim["path"], pattern) for pattern in grants)})
            if conflicts:
                raise Stop(f"whole-file claim conflicts with region claims for {', '.join(conflicts)}")
            ownership[lane] = grants
            overlaps = ownership_overlaps(ownership, files, shared)
            if overlaps:
                raise Stop(f"lanes own the same files: {'; '.join(overlaps)}")
            return ["--set", json.dumps({"/laneOwnership": ownership,
                                         "/lanes": [*state["lanes"], {**row, "since": now()}]})]

        patch_from(compute, f"{lane}'s addition")
        raw["lanes"][lane] = {"owns": grants}
        c.delivery_path.write_text(json.dumps(raw, indent=2) + "\n")
        plan_path.write_text(plan_text)
        git("add", str(c.delivery_path), str(plan_path), cwd=root)
        tool_commit("commit", "-q", "-m", f"{c.delivery}: add lane {lane}", *(["-m", args.why] if args.why else []),
                    cwd=root)
    print(f"added {lane} to {c.delivery}" + (f", owning {', '.join(grants)}" if grants else ", owning nothing yet"))
    print(f"committed the delivery file and the plan; push it so lanes see it: {plan_publish_command(c)}")


def plan_with_lane(text: str, lane: str, grants: list[str]) -> str:
    """The plan with the lane's row added to the end of its Units table, at the highest tier, with no items."""
    rows, missing = units_rows(text)
    if rows is None:
        raise Stop(f"{missing}, so there is no row to add the lane to")
    body = next(b for level, title, b in plan_sections(text) if level == 2 and title == UNITS_SECTION)
    lines = body.splitlines(keepends=True)
    first = next(index for index, line in enumerate(lines) if line.strip().startswith("|"))
    last = first
    while last + 1 < len(lines) and lines[last + 1].strip().startswith("|"):
        last += 1
    header = [cell.strip() for cell in lines[first].strip().strip("|").split("|")]
    values = {"Tier": str(max((tier for tier, _, _ in rows), default=1)), "Lane": lane[len("lane-"):],
              "Owns": ", ".join(f"`{pattern}`" for pattern in grants)}
    added = "| " + " | ".join(values.get(name, "") for name in header) + " |"
    # After the table's last row, keeping whatever follows it as it was: a last row the section ends on has no newline.
    added = added + "\n" if lines[last].endswith("\n") else "\n" + added
    start = text.index(body)
    return text[:start] + "".join(lines[:last + 1]) + added + "".join(lines[last + 1:]) + text[start + len(body):]


def lead_assign(args) -> None:
    c = cfg()
    keys = [c.require(k) for k in args.keys]
    require_lead_checkout(c)
    require_scope(c, "delivery", "assigns stories to lanes")
    problems = plan_problems(c, keys)
    if problems:
        raise Stop("; ".join(problems))
    # Before anything is written: a story its tracker isn't ready to start is refused unless the lead forces it.
    readiness = {key: story_readiness(c, key) for key in keys}
    unready = [line for state, line in readiness.values() if state == "not-ready"]
    if unready and not args.force:
        raise Stop("; ".join(unready) + "; nothing was assigned. Have the item made ready, or assign it anyway with --force")
    # Decision 6: the co-changed files' claims commit the delivery file as lead-plan does, so its checkout is checked
    # before anything is written.
    if args.own_co_changed and "laneOwnership" not in c.record_state():
        raise Stop("--own-co-changed claims files in the record: seed this record with lead-own --seed first")
    plan_root = lead_plan_checkout(c) if args.own_co_changed else None
    register_stories(c)
    row = {"id": args.lane, "title": args.title, "focus": f"assigned {', '.join(keys)}", "state": "assigned",
           "waitingOn": None, "since": now()}

    def assign(doc: dict) -> dict:
        state = doc["state"]
        if args.lane not in c.effective_ownership(state):
            raise Stop(f"{args.lane} is not a lane of {c.delivery}; add it first with lead-add-lane --lane {args.lane}")
        # The row is replaced where it stands: an assignment never reorders the lanes.
        rows = state["lanes"]
        changes = {"lanes": [row if entry["id"] == args.lane else entry for entry in rows]
                   if any(entry["id"] == args.lane for entry in rows) else [*rows, row]}
        if "laneOwnership" not in state:
            for key in keys:
                if c.lane_of(key, state) != args.lane:
                    raise Stop(f"{key} is planned for {c.lane_of(key, state)}, not {args.lane}; seed ownership first")
            return changes
        planned, queue = state.get("planned", []), state["queue"]
        moving = [entry for entry in planned if entry["subject"] in keys and entry["lane"] != args.lane]
        for entry in moving:
            if entry.get("noChange"):
                raise Stop(f"{entry['subject']} has a no-change hand-off; settle it before changing its lane")
        changes["planned"] = [
            {**entry, "lane": args.lane} if entry in moving else entry for entry in planned
        ]
        changes["queue"] = [
            {**item, "assignedLane": args.lane}
            if item["subject"] in keys and c.lane_of(item["subject"], state) != args.lane else item
            for item in queue
        ]
        # A reassignment alone doesn't give the receiving lane work on a candidate already in the queue.
        if not any(entry["subject"] in keys and entry["stage"] != "settled" for entry in planned):
            rows = state["lanes"]
            changes["lanes"] = rows if any(entry["id"] == args.lane for entry in rows) else [
                *rows, {**row, "state": "idle", "focus": ""}
            ]
        previous = {entry["lane"] for entry in moving}
        busy = {entry["lane"] for entry in changes["planned"] if entry["stage"] != "settled"}
        busy.update(item["lane"] for item in queue if item["stage"] != "merged")
        changes["lanes"] = [
            {**entry, "state": "idle", "focus": "", "waitingOn": None, "since": now()}
            if entry["id"] in previous - busy and entry["state"] != "idle" else entry
            for entry in changes["lanes"]
        ]
        return changes

    if c.record_state().get("laneRegions"):
        git("fetch", "-q", c.remote, c.base_branch)
    patch_from(assign, f"{args.lane}'s assignment")
    rebuild_plan(c)
    tracked = tracked_at_base(c)
    regions = c.record_state().get("laneRegions", [])
    if regions:
        regional_paths = {claim["path"] for claim in regions}
        for key in keys:
            for path in story_named_files(c, key, tracked):
                if path in regional_paths:
                    print(f"{key} names a region-owned file {path} ({owner_words(c, path)}). "
                          f"{args.lane} may change only its mapped spans.")
    co_changes = [line for key in keys if (line := co_change_warning(c, key, tracked))]
    warnings = [*(named_outside(c, key, outside) for key in keys if (outside := outside_lane(c, key, tracked))),
                *co_changes]
    if warnings:
        print(f"Files outside {args.lane}'s owns, before it starts (lead-accept refuses a change to any of them):")
        for line in warnings:
            print(f"  {line}")
        if args.own_co_changed:
            with ownership_lock(c):
                own_co_changed(c, args.lane, keys, tracked, plan_root)
            print()
        elif co_changes:
            print(f"Grant a named file with lead-own, or plan the story on the lane that owns it; claim the co-changed "
                  f"files for {args.lane} by assigning with --own-co-changed.\n")
        else:
            print(f"Move each to {args.lane}'s owns now, or plan the story on the lane that owns it.\n")
    print_peer_claims(c, [path for key in keys for path in story_named_files(c, key, tracked)])
    # One entry per story, so each ticket's start is its own, made when its lane begins it.
    for key in keys:
        state_tool("journal", "--kind", "lane.assigned", "--lane", args.lane, "--subject", key, "--data", json.dumps({"title": c.stories[key]["title"], **({"note": args.note} if args.note else {})}))
    said = [line + ("; assigned anyway (--force)" if state == "not-ready" else "")
            for state, line in readiness.values() if line]
    if said:
        print("Readiness, from the tracker snapshot:")
        for line in said:
            print(f"  {line}")
        print()
    print(f"Assignment message for {args.lane} ({args.title}):\n")
    print(f"You are {args.lane} in the {c.delivery} delivery. Read the lane brief first: {c.root / c.lane_brief}\n")
    seat = lane_seat_words(c, args.lane)
    if seat:
        print(f"{seat}\n")
    print("Your stories, in order (one branch, one review and one hand-off each):")
    for key in keys:
        print(f"- {key} {c.issue_url.format(key=key)} ({c.label(key)}: {c.stories[key]['title']})")
    print(f"\nBegin each story from the lead checkout {c.root.resolve()}, with:")
    for key in keys:
        print(f"  {flow_command()} lane-start {key} --base {c.base_branch}")
    if args.note:
        print(f"\nNote from the lead: {args.note}")
    print(f"\nRecord: {c.state}")
    print("\nWhen you hand off a story, or are blocked, end your turn with a short report that opens with the story "
          "key and the outcome (handed off, or blocked and on what): the lead sees its first lines. Then the branch, "
          "PR, reviewed head, review rounds and verdicts, gates, in-app checks, and any decision you need from the "
          "lead. The lead checks the hand-off and tells you when to start your next story.")

def grant_args(path: str, lane: str) -> argparse.Namespace:
    """lead-own --grant PATH --lane LANE's arguments, for a command that grants through change_ownership's checks."""
    return argparse.Namespace(
        grant=path, lane=lane, carve=None, give=None, carry=None, anchor=None, through=None, region=None,
        revoke_region=None, claim=None, base=None, start=None, end=None, story=None, seed=False, source=None,
        move=None, revoke=None, around=None, insert=None)


def own_co_changed(c, lane: str, keys: list[str], tracked: list[str], root: Path) -> list[str]:
    """Decision 6: each file the stories' co-change warnings name, claimed for ``lane`` in the record through
    lead-own --grant's checks and added to its owns in the delivery file, in one commit as lead-plan makes. A file
    another lane holds is named with the --move that would take it, and one shared by lines is named and left; neither
    is added. The warning never names a declared shared output, which every lane may change. Returns the files added."""
    state = c.record_state()
    ownership = c.effective_ownership(state)
    regional = {claim["path"] for claim in state.get("laneRegions", [])}
    added = []
    for path in dict.fromkeys(f for key in keys for f, *_ in co_change_files(c, key, tracked)):
        held = [(other, pattern) for other in owners_of(ownership, path) if other != lane
                for pattern in ownership[other] if fnmatch.fnmatchcase(path, pattern)]
        if held:
            for other, pattern in held:
                print(f"  {path} is {other}'s, so it isn't added; to take it: {flow_command()} lead-own --lane {lane} "
                      f"--move {shlex.quote(pattern)} --from {other}")
        elif path in regional:
            print(f"  {path} is shared by lines, so it isn't added; ask for a span: {flow_command()} lead-own --region "
                  f"{shlex.quote(path)} --lane {lane} ...")
        else:
            change_ownership(c, grant_args(path, lane))
            added.append(path)
    if not added:
        return added
    raw = json.loads(c.delivery_path.read_text())
    owns = raw["lanes"][lane].setdefault("owns", [])
    owns += [path for path in added if path not in owns]
    c.delivery_path.write_text(json.dumps(raw, indent=2) + "\n")
    git("add", str(c.delivery_path), cwd=root)
    tool_commit("commit", "-q", "-m", f"{c.delivery}: {lane} owns {', '.join(added)} (lead-assign --own-co-changed)",
                cwd=root)
    print(f"committed the delivery file with {lane}'s owns; push it so lanes see it: {plan_publish_command(c)}")
    return added


# A delivery's claims on its base, kept in its own record's extensions for its peers to read (Decision 29).
def change_claims(c, args) -> None:
    """lead-own --claim PATTERN: whole files this delivery claims on its base. A peer's lead-assign and lead-accept
    warn of a story or candidate that touches one; a claim refuses nothing and orders no delivery before another."""
    pattern = args.claim
    if (any(value is not None for value in (args.base, args.start, args.end))
            or re.search(r"(?::\d+(?:-\d+)?|#L\d+(?:-L?\d+)?)$", pattern)):
        raise Stop("a claim is of whole files: name a file or a pattern, not a region or a line range")
    if args.lane or args.source:
        raise Stop("--claim takes neither --lane nor --from: a claim is the delivery's, not a lane's")
    if Path(pattern).is_absolute() or any(part in ("", ".", "..") for part in pattern.split("/")):
        raise Stop("name a repository-relative file or pattern")

    def compute(doc: dict) -> list[str]:
        extensions = doc["state"].get("extensions")
        claims = list((extensions or {}).get("claims") or [])
        if pattern in claims:
            raise Stop(f"{c.delivery} already claims {pattern}")
        if extensions is None:
            return ["--set", json.dumps({"/extensions": {"claims": [pattern]}})]
        return ["--set", json.dumps({"/extensions/claims": [*claims, pattern]})]

    patch_from(compute, f"{c.delivery}'s claim of {pattern}")
    change = f"{c.delivery} claims {pattern} on {c.base_branch}: a peer's lead-assign and lead-accept warn of it"
    state_tool("journal", "--kind", "ownership.claimed", "--data", json.dumps(
        {"path": pattern, "base": {"ref": c.base_ref, "head": git("rev-parse", c.base_ref)}}))
    print(change)


def peer_stories_on(state: dict, path: str) -> str:
    """A peer's stories on a file, from its record: those of the lanes whose claims or regions cover it, each with
    its stage, its queue stage once it is queued."""
    ownership = state.get("laneOwnership") if isinstance(state.get("laneOwnership"), dict) else {}
    lanes = {lane for lane, patterns in ownership.items() if isinstance(patterns, list)
             and any(isinstance(p, str) and fnmatch.fnmatchcase(path, p) for p in patterns)}
    lanes |= {claim.get("lane") for claim in state.get("laneRegions") or [] if isinstance(claim, dict)
              and claim.get("path") == path}
    stages: dict[str, str] = {}
    for kind in ("planned", "queue"):
        for item in state.get(kind) or []:
            if isinstance(item, dict) and isinstance(item.get("subject"), str) and (
                    item.get("lane") in lanes or item.get("assignedLane") in lanes):
                stages[item["subject"]] = str(item.get("stage"))
    return ", ".join(f"{key} ({stage})" for key, stage in sorted(stages.items())) or "none"


def peer_claim_lines(c, files: list[str]) -> list[str]:
    """For each file a peer on this base claims, the claim, the peer's stories on the file and their stages, and
    whether the peer is stale or has no supervisor; and each registry entry that can't be read."""
    lines = []
    for peer in peer_deliveries(c):
        if peer["status"] == "unreadable":
            lines.append(f"{peer['file']}, a delivery registered beside this repository, is unreadable: its claims, "
                         "if any, aren't known")
            continue
        state = json_object(Path(peer["state"]) / "state.json")
        extensions = state.get("extensions") if isinstance(state.get("extensions"), dict) else {}
        claims = [p for p in extensions.get("claims") or [] if isinstance(p, str)]
        note = {"stale": f"; {peer['key']} is {peer_status_words(peer)}",
                "none": f"; {peer['key']} has no supervisor"}.get(peer["status"], "")
        for path in sorted(set(files)):
            pattern = next((p for p in claims if fnmatch.fnmatchcase(path, p)), None)
            if pattern:
                lines.append(f"{path} is claimed by {peer['key']} ({pattern}{note}); its stories on it: "
                             f"{peer_stories_on(state, path)}")
    return lines


def print_peer_claims(c, files: list[str]) -> None:
    lines = peer_claim_lines(c, files)
    if lines:
        print(f"Files another delivery on {c.base_branch} claims (a warning; nothing is refused):")
        for line in lines:
            print(f"  {line}")
        print()


def handed_entry(doc: dict, key: str) -> int:
    """The journal id of the story's latest hand-off, which its check names as its cause; its merge when it was
    merged with no hand-off journaled."""
    for kind in ("candidate.handed", "candidate.merged"):
        found = [e["id"] for e in doc["journal"] if e["kind"] == kind and e.get("subject") == key]
        if found:
            return found[-1]
    raise Stop(f"{key} has no hand-off or merge in the journal for its check to name")


def accept_no_change(c, key: str, entry: dict) -> None:
    """Accept a no-change hand-off: its evidence ran at a head the base still holds, and names every one of the story's
    criteria. The record then holds the story settled: never queued, never removed, counted as done."""
    if entry["stage"] == "settled":
        raise Stop(f"{key} is already settled with no change")
    criteria = [item["id"] for item in c.stories[key].get("criteria", [])]
    if not criteria:
        raise Stop(f"{key} has no criteria, so its evidence can't be checked against them; fix: record its criteria "
                   f"first (lead-plan change --kind added --subjects {key} --criterion ID --text TEXT --why W), then "
                   "accept it")
    base_head = entry["noChange"]["baseHead"]
    git("fetch", "-q", c.remote, c.base_branch)
    problems = []
    if not is_ancestor(base_head, c.base_ref):
        problems.append(f"the evidence ran at {base_head[:10]}, which {c.base_ref} doesn't hold")
    evidence = entry["noChange"]["evidence"]
    missing = [ident for ident in criteria if not re.search(rf"(?<![\w.-]){re.escape(ident)}(?![\w-]|\.[\w-])", evidence)]
    if missing:
        problems.append(f"the evidence names no proof of criterion {', '.join(missing)}; the lane hands it off again "
                        "with evidence naming every criterion by id")
    if problems:
        print(f"NOT accepted: {key}")
        for problem in problems:
            print(f"  - {problem}")
        sys.exit(1)
    # The check is journaled first, naming the hand-off, so the acceptance after it can name the check.
    state_tool("journal", "--kind", "handoff.checked", "--subject", key, "--because", str(handed_entry(load_state(), key)), "--data", json.dumps(
                   {"head": base_head, "rounds": 0, "afterMerge": False, "noChange": True,
                    "notes": [f"its evidence names each of its criteria: {', '.join(criteria)}"]}))
    state_tool("handoff", "--accept", key)
    append_log("acceptance", key, {"head": base_head, "noChange": True, "ready": False, "blocked": {}})
    rebuild_plan(c)
    print(f"accepted {key}: settled with no change needed")


def pr_review_acceptance(conf: dict, url: str, head: str, recorded: dict,
                         on_silent: bool = False) -> tuple[list[str], list[str]]:
    """The list's PR review re-checked at acceptance, one read of the forge at the handed head: every reviewer the lane
    recorded current is still current, triaged and unchanged; a required one was never recorded absent; and an
    optional one recorded absent hasn't posted since. An old-shape record is reviewer `review`. Returns (problems,
    decisions)."""
    read = read_pr_reviews(url, head, conf, None)
    if read["status"] == "failed":
        return [f"the PR's pipeline failed at {head[:10]}: {check_states(read['checks'])}"], []
    if recorded.get("head") != head:
        return [f"the lane recorded no PR review at the handed head {head[:10]}"], []
    entries = record_reviewers(recorded)
    problems, decisions = [], []
    for reviewer in conf["reviewers"]:
        rid = reviewer["id"]
        entry, live = entries.get(rid), read["reviewers"][rid]
        if entry is None:
            problems.append(f"the lane's PR review record at {head[:10]} has no entry for {rid}")
        elif entry.get("state") == "silent":
            # On a hand-off blocked on it, the block is the lead's decision, and lead_accept has checked it is still
            # silent. Otherwise the lane recorded it silent and handed off as if it weren't.
            if not on_silent:
                problems.append(f"the lane recorded {rid} silent at {head[:10]} but didn't hand off blocked on it")
        elif on_silent and pr_review_gates.unread_when_stopped(entry) and live["state"] != "current":
            pass  # not yet in when an errored report stopped the read, nor since: the block is the lead's decision
        elif entry.get("state") != "current":
            if reviewer["required"]:
                problems.append(f"{rid} is required, but the lane recorded it {entry.get('state')}")
            elif live["state"] == "current":
                problems.append(f"{rid} was recorded absent, but its review is now current at {head[:10]} "
                                f"({live['review']['at']}): send the lane back to read and triage it")
        elif live["state"] != "current":
            problems.append(f"{rid}'s PR review isn't current at {head[:10]} ({live['state']})")
        elif not entry.get("triage"):
            problems.append(f"the lane recorded no triage of {rid}'s PR review at the handed head")
        elif (live["review"]["at"], live["review"]["body"]) != (entry.get("at"), entry.get("body")):
            problems.append(f"{rid}'s PR review changed after the lane read it ({entry.get('at')} -> "
                            f"{live['review']['at']}); the lane must read and triage it again")
        else:
            decisions.append(f"PR review {rid} by {live['review']['author']} at {live['review']['at'][:16]} triaged: "
                             f"{entry['triage']}")
    problems += pr_review_gates.live_refusals(conf["reviewers"], read["reviewers"], head)
    return problems, decisions


def print_evidence_notes(key: str, n: int) -> None:
    """Under noDeferrals, the story's round n's evidence notes, each with its lens, in plain text for the lead."""
    path = next((folder / f"round-{n}.json" for folder in lane_review_folders(key) if (folder / f"round-{n}.json").is_file()),
                None)
    if path is None:
        print(f"round {n}'s evidence notes: its round file isn't in the story's review folders, so they can't be read")
        return
    notes = evidence_notes(json.loads(path.read_text()))
    print(f"round {n}'s evidence notes, under noDeferrals:"
          + ("".join(f"\n  {lens}: {note}" for lens, note in notes) if notes else " none"))


def handed_round_one_meta(c, key: str) -> dict | None:
    """Round 1's meta where the hand-off left it: the lane's checkout, else the lane evidence kept once it went."""
    for folder in (c.lane_checkout(key) / c.work / "review" / key, evidence_dir(key)):
        meta = load_json(folder / "round-1.meta.json")
        if meta is not None:
            return meta
    return None


def accepted_lenses(declared: list[str], journal: list[dict], key: str, meta: dict | None) -> list[str]:
    """The lenses a story's last round must carry at acceptance: those of its latest round 1 start, when round 1's
    meta says they were chosen; otherwise, for a story prepared before they were, or one whose round 1 start isn't
    journaled, every declared lens."""
    start = next((e for e in reversed(journal) if e.get("kind") == "review.started" and e.get("subject") == key
                  and e["data"].get("round") == 1), None)
    if start is None or not (meta or {}).get("lensesReason"):
        return list(declared)
    return list(start["data"]["lenses"])


def reuse_lines(item: dict, ids: list[str], granted: list[str] | set[str] = ()) -> list[str]:
    """For each selected check, whether the hand-off's record of it applies at the handed head, as the queue's `applies`
    answers it (a granted id with the grant's own-diff bound), or every reason it doesn't, and its measured median.
    The environment and host facts are the queue's to compare at its own run."""
    try:
        return applies_lines(cfg(), item, ids, granted)
    except Stop as error:  # shown, never a refusal: whatever the queue can't read, the acceptance's own checks say
        return [f"checks: {error}, so whether a hand-off record applies isn't shown"]


def applies_lines(c, item: dict, ids: list[str], granted: list[str] | set[str]) -> list[str]:
    head, lines = item["head"], []
    with queue_reader(c) as runner:
        base_head = git("rev-parse", c.base_ref)
        binding = runner.read_binding(base_head)
        tree = runner.tree_of(head)
        for name in ids:
            entry = next((e for e in item.get("evidence", []) if e.get("check") == name), None)
            median = check_median(c, name)
            if entry is None:
                lines.append(f"check {name}: no record in the hand-off, so it runs; {median}")
                continue
            own = runner.own_paths(base_head, [entry["head"], head]) if name in granted else None
            # The queue refuses a record without its facts, so the lead is told so too, in the queue's words.
            missing = [field for field in ("where", "environment", "host") if field not in entry]
            reasons = ([f"the record is missing its {', '.join(missing)} facts"] if missing else []) + (
                record_reasons(runner, entry, name, tree, binding, own) if tree else ["the handed head isn't here"])
            said = (f"its record at {entry['head'][:10]} applies at the handed head"
                    + (" under the grant" if name in granted else "") + ", unless the queue's facts differ"
                    if not reasons else f"runs: {'; '.join(reasons)}")
            lines.append(f"check {name}: {said}; {median}")
    return lines


def lead_accept(args) -> None:
    c = cfg()
    if not (c.state / "state.json").is_file():
        raise Stop("initialize the delivery record before accepting work")
    with ownership_lock(c):
        accept_story(c, args)


def accept_story(c, args) -> None:
    if args.requeue:
        requeue(c, c.require(args.requeue))
        return
    if not args.key:
        raise Stop("name the story to accept, or --requeue a stopped one")
    key = c.require(args.key)
    review_conf = pr_review_config()  # refused here, before anything else, when review.pr is malformed
    if args.checks is not None and args.full_suite:
        raise Stop("choose one: --checks, the candidate's checks, or --full-suite, the binding's fallback")
    if (args.checks is not None or args.full_suite) and not lead_selects(c):
        raise Stop("the binding doesn't enable lead selection (selection.lead), so the queue selects the checks: "
                   "accept with neither --checks nor --full-suite")
    reuse, why = getattr(args, "reuse", None), getattr(args, "why", None)
    takes = list(dict.fromkeys(getattr(args, "take", None) or []))
    if reuse is not None and args.checks is None:
        raise Stop("--reuse goes with --checks: the grant lives in the lead's selection at the handed head")
    if reuse is not None and not (why or "").strip():
        raise Stop("--reuse needs --why, why that reuse is safe, which select journals as the lead's decision")
    if takes and not (why or "").strip():
        raise Stop("--take needs --why: why the lane takes each file, journalled as the lead's decision")
    if why and reuse is None and not takes:
        raise Stop("--why goes with --reuse or --take")
    if args.full_suite and provider_selects(c):
        raise Stop("the binding names a provider, so a candidate with no lead selection runs the provider's answer, "
                   "and the fallback only when the provider can't give one: --full-suite can't promise the fallback; "
                   "choose the checks with --checks")
    doc = load_state()
    item = next((q for q in doc["state"]["queue"] if q["subject"] == key), None)
    waiting = next((p for p in doc["state"].get("planned", []) if p["subject"] == key and p.get("noChange")), None)
    lane = (item or waiting or {}).get("lane")
    if lane:
        # Before anything is read from the lane or written: a lane's hand-offs are accepted by the seat holding it.
        require_scope(c, f"lane:{lane}", f"accepts {lane}'s hand-offs")
    if not item and waiting:
        if takes:
            raise Stop(f"--take {takes[0]}: {key} has a no-change hand-off, which changes no file, so there is nothing "
                       "to take")
        if args.checks is not None:
            check_ids(c, args.checks, "--checks")  # refused as before; a no-change story runs no checks
        accept_no_change(c, key, waiting)
        return
    if not item:
        raise Stop(f"{key} is not in the queue; the lane has not handed it off")
    merged = item["stage"] == "merged"
    if not merged and item.get("pending"):
        # A hand-off that ends a failed run waits beside the row the queue still checks: what it claims is its own.
        item = _validator().handed_item(doc["state"], doc.get("journal", []), key) or item
    added = handed_additions(c, key, item["head"]) if not merged and lead_selects(c) and not args.full_suite else {}
    chosen = check_ids(c, args.checks, "--checks", added) if args.checks is not None else None
    problems, decisions = [], []
    # Work merged outside the queue skipped the lead's acceptance; its decisions can still be recorded, once.
    if merged and item.get("reportedRounds") is None:
        raise Stop(f"{key} merged with no hand-off, so there are no claims to check: journal your decision on it")
    if merged:
        if any(entry["head"] == item["head"] for entry in read_log("acceptance", key)):
            problems.append("the hand-off was already accepted")
    elif not item.get("pending"):
        problems.append("the hand-off is not waiting for acceptance")
    head = item["head"]
    branch = c.branch(key)
    if not merged and remote_head(branch) != head:
        problems.append(f"{c.remote}/{branch} is not at the handed head {head[:10]}")
    rounds = [e for e in doc["journal"] if e.get("kind") == "review.round" and e.get("subject") == key]
    numbers = [e["data"]["round"] for e in rounds]
    if len(numbers) != len(set(numbers)):
        problems.append(f"round numbers journaled more than once: {sorted(numbers)}")
    if item.get("reportedRounds") != len(set(numbers)):
        problems.append(f"the hand-off reports {item.get('reportedRounds')} rounds; the journal has {len(set(numbers))}")
    last = max(rounds, key=lambda e: e["data"]["round"], default=None)
    first_meta = handed_round_one_meta(c, key)
    story_lenses = accepted_lenses(list(c.lenses), doc["journal"], key, first_meta)
    asked, unrun = accepted_brief(c, key, story_lenses, first_meta)
    print(f"  review lenses: {', '.join(story_lenses)}; reason: "
          f"{(first_meta or {}).get('lensesReason') or 'reason not found'}{asked}")
    problems += unrun
    if not last or set(last["data"]["verdicts"]) != set(story_lenses) or set(last["data"]["verdicts"].values()) != {"approve"}:
        problems.append(f"the last journaled round is not approved by every lens of the story's set, "
                        f"{', '.join(story_lenses)}")
    if last and c.no_deferrals:
        print_evidence_notes(key, last["data"]["round"])
    evidence = [e for e in doc["journal"] if e.get("kind") == "review.recorded" and e.get("subject") == key]
    carried_review = None
    if not evidence or evidence[-1]["data"]["candidateRef"] != head:
        # A hand-off whose journal entry never landed carries nothing, and the evidence is then not for the head.
        hand = next((entry for entry in reversed(doc["journal"])
                     if entry["subject"] == key and entry["kind"] == "candidate.handed"), None)
        carry = hand["data"].get("carry", {}) if hand else {}
        if evidence and carry.get("baseCommits") and carry.get("to") == head and hand["lane"] == item["lane"]:
            validator = _validator()
            try:
                expected = validator.base_merge_evidence(
                    c.state, doc["journal"], key, item["lane"], head, item.get("reportedRounds"),
                    {"reviewed": carry["from"], "baseCommits": carry["baseCommits"]},
                )
                if expected != carry or hand["id"] <= evidence[-1]["id"]:
                    raise validator.StateError("carry_invalid", "the handed carry does not match the captured review")
                carried_review = carry
            except validator.StateError as error:
                problems.append(f"review carry refused: {error}")
        else:
            problems.append("the latest captured review evidence is not for the handed head")
    pr = forge("get", "--url", item.get("changeRequest") or "")
    if pr.get("state") != ("merged" if merged else "open"):
        problems.append(f"the PR is {pr.get('state')}")
    if not same_commit(pr.get("head"), head):
        problems.append(f"the PR is at {str(pr.get('head'))[:10]}, not the handed head")
    if pr.get("destination") != c.base_branch or pr.get("source") != branch:
        problems.append(f"the PR is {pr.get('source')} -> {pr.get('destination')}, not {branch} -> {c.base_branch}")
    conf = review_conf
    lane_blocked = c.lane_checkout(key) / c.work / "review" / key / "blocked.json"
    held = json.loads(lane_blocked.read_text()) if lane_blocked.exists() else {}
    if conf and not conf["legacy"] and held.get("head") == head and PR_REVIEW_BLOCK in held.get("blocked", {}):
        # Blocked on a silent reviewer: while one is still silent, the block below is the lead's decision. Once none is,
        # its review has arrived (or the pipeline moved), and the lane must read and triage it.
        live = read_pr_reviews(item.get("changeRequest") or "", head, conf, None)
        if silent_refusal(live, head, conf["reviewers"]) is None:
            states = ", ".join(f"{rid} {r['state']}" for rid, r in live["reviewers"].items()) or live["status"]
            problems.append(f"the lane blocked on a silent PR reviewer, but none is silent at {head[:10]} now ({states}): "
                            "send the lane back to read and triage its review")
        on_silent = True
    else:
        on_silent = False
    if conf and not conf["legacy"]:
        lane_root_ = c.lane_checkout(key)
        saved = lane_root_ / c.work / "review" / key / "pr-review.json"
        recorded = json.loads(saved.read_text()) if saved.exists() else {}
        found, made = pr_review_acceptance(conf, item.get("changeRequest") or "", head, recorded, on_silent)
        problems += found
        decisions += made
    elif conf:
        status, review, _ = pr_review_state(item.get("changeRequest") or "", head, conf)
        lane_root_ = c.lane_checkout(key)
        saved = lane_root_ / c.work / "review" / key / "pr-review.json"
        recorded = json.loads(saved.read_text()) if saved.exists() else {}
        if status != "current":
            problems.append(f"the PR's pipeline review isn't current at {head[:10]} ({status})")
        elif recorded.get("head") != head or not recorded.get("triage"):
            problems.append("the lane recorded no triage of the PR review at the handed head")
        elif review["at"] != recorded.get("at"):
            problems.append(f"the PR review changed after the lane read it ({recorded.get('at')} -> {review['at']}); "
                            "the lane must read and triage it again")
        else:
            decisions.append(f"PR review by {review['author']} at {review['at'][:16]} triaged: {recorded['triage']}")
    git("fetch", "-q", c.remote, c.base_branch)
    base = git("merge-base", c.base_ref, head)
    if carried_review and not merged:
        try:
            verified = verify_base_merge(c, key, item["lane"], carried_review["from"], head, doc)
            if verified["baseCommits"] != carried_review["baseCommits"]:
                problems.append("the handed base merge history differs from the captured carry")
        except Stop as error:
            problems.append(f"review carry refused: {error}")
    # Once merged, the base holds the head or a squash of it, so a diff against it no longer says what the work changed.
    lane = item["lane"] if "laneOwnership" in doc["state"] else c.lane_of(key, doc["state"])
    # Decision 7: the candidate is judged as if the lane held each file it takes; the grant is written once accepted.
    judged = taken_state(c, key, lane, base, head, doc["state"], takes) if takes and not merged else doc["state"]
    if takes and merged:
        raise Stop(f"{key} has merged: --take grants a file to a candidate waiting for acceptance")
    changed, outside = ([], []) if merged else candidate_ownership(c, lane, base, head, judged)
    if outside:
        problems.append(f"the branch changes files outside {lane}'s: {outside}")
    proposal = None
    if lead_selects(c) and not merged and chosen is None and not args.full_suite:
        # Under lead selection, a candidate accepted with no choice would check on the fallback: the lead says which.
        proposal = proposed_checks(c, changed, item.get("namedChecks") or [], added)
        if provider_selects(c):
            problems.append(f"choose {key}'s checks: the binding enables lead selection, and a candidate accepted with "
                            "none checks on the provider's selection, widened to the fallback "
                            f"({', '.join(fallback_ids(c))}) only when it fails; accept with --checks")
        else:
            problems.append(f"choose {key}'s checks: the binding enables lead selection, and a candidate accepted with "
                            f"none checks on the fallback ({', '.join(fallback_ids(c))}); accept with --checks, or "
                            "with --full-suite to run the fallback")
    lane_root = c.lane_checkout(key)
    accepted_blocked = set(args.accept_blocked or [])
    shown = chosen if chosen is not None else proposal if proposal is not None else (
        fallback_ids(c) if args.full_suite else [])
    if shown and not merged:
        granted = {name.strip() for name in (reuse or "").split(",") if name.strip()}
        for line in reuse_lines(item, shown, granted):
            print(f"  {line}")
    if lane_root.exists():
        for line in guard_lines(key, lane_root, head):  # shown, never run here
            print(f"  {line}")
        _, gate_problems = gates_summary(key, lane_root, head)
        problems += gate_problems
        review = lane_root / c.work / "review" / key
        saved = json.loads((review / "blocked.json").read_text()) if (review / "blocked.json").exists() else {}
        blocked = saved.get("blocked", {}) if saved.get("head") == head else {}
        for label, reason in blocked.items():
            if label in accepted_blocked:
                decisions.append(f"accepted blocked '{label}' ({reason})")
            else:
                problems.append(f"the lane blocked '{label}': {reason} (decide; accept with --accept-blocked '{label}')")
        app_lines, app_problems = in_app_evidence(key, lane_root, head, blocked)
        problems += app_problems
        video_lines, video_problems = video_evidence(key, lane_root, head)
        app_lines += video_lines
        problems += video_problems
        for line in app_lines:
            print(f"  in-app: {line}")
        outcomes = [json.loads(p.read_text()) for p in round_files(review)]
        histories = [f"round {o['round']}: {round_history_text(o)}" for o in outcomes if o.get("restarts")]
        prepares = read_log("prepares", key)
        for o in outcomes:
            count = sum(1 for e in prepares if e["round"] == o["round"])
            if count != 1 + len(o.get("restarts", [])):
                note = (f"round {o['round']} was prepared {count} time(s) but records {len(o.get('restarts', []))} "
                        "restart(s): its files were discarded outside the tool (a recreated checkout, say)")
                if o["round"] in (args.accept_discarded or []):
                    decisions.append(f"accepted {note}")
                else:
                    problems.append(f"{note}; check why, then accept with --accept-discarded {o['round']}")
        if histories and not args.accept_restarts:
            problems.append("review rounds were restarted, discarding results (" + "; ".join(histories) + "); read the "
                            f"discarded results in {review}, then accept with --accept-restarts")
        elif histories:
            decisions.append("accepted review restarts (" + "; ".join(histories) + ")")
    else:
        problems.append(f"can't read the lane's gate, in-app and review evidence: no checkout at {lane_root}")
    selected = False
    before = item.get("leadSelection") if item else None
    if chosen is not None and not merged and not problems:
        # Through the state tool's own select, with its validation, guards and readers (read from this checkout, the
        # one the command runs in): what it refuses, this refuses. A base catalogue id goes as its id, and an entry the
        # candidate adds as the head binding's object, unchanged, in the order chosen.
        reason = args.reason or f"chosen at acceptance from {key}'s diff and its hand-off's checks"
        listed = [added[name] if name in added else name for name in chosen]
        done = state_tool("select", "--subject", key, "--binding", str(c.binding_path), "--head", head, "--checks",
                          json.dumps(listed), "--reason", reason,
                          *(["--reuse", reuse, "--why", why.strip()] if reuse is not None else []),
                          check=False)
        answer = json.loads(done.stdout or "{}") if done.stdout.strip().startswith("{") else {}
        if done.returncode != 0:
            problems.append(f"the selection was refused: {answer.get('error') or (done.stderr or done.stdout).strip()[-400:]}")
        else:
            selected = True
            ids = [check.get("id") for check in (answer.get("item") or {}).get("leadSelection", {}).get("checks", [])]
            decisions.append(f"checks selected at {head[:10]}: {', '.join(map(str, ids or chosen))}")
    if args.full_suite and not merged:
        decisions.append(f"checks: the binding's fallback ({', '.join(fallback_ids(c))}), the lead's decision"
                         + (f": {args.reason}" if args.reason else ""))
    ready = bool(authority().get("readyPullRequests"))
    if ready and not merged and not problems and pr.get("draft") is not False:
        # Before the hand-off is released, so the runner never takes a draft the merge step would refuse.
        try:
            forge("ready", "--url", item.get("changeRequest") or "")
        except Stop as error:
            problems.append(f"the draft pull request couldn't be marked ready, so the hand-off stays pending: {error}")
        else:
            decisions.append(f"marked {item.get('changeRequest')} ready under the delivery's readyPullRequests grant")
    if problems:
        if selected:
            # Not accepted after all: the selection this made is undone, and one that stood before it is put back.
            if before and before.get("head") == head:
                state_tool("select", "--subject", key, "--binding", str(c.binding_path), "--head", head, "--checks",
                           json.dumps(before["checks"]), "--reason", before["reason"], check=False)
            else:
                state_tool("select", "--subject", key, "--clear", check=False)
        print(f"NOT accepted: {key}")
        for p in problems:
            print(f"  - {p}")
        if proposal is not None:
            alternative = "" if provider_selects(c) else (", or" if proposal else "") + " --full-suite"
            print(f"  proposed: lead-accept {key} " + (f"--checks {','.join(proposal)} " if proposal else "")
                  + "--reason \"<why these cover the diff>\"" + alternative)
        sys.exit(1)
    if args.full_suite and not merged and before:
        # A selection still standing would be what the runner runs: the fallback the lead chose wouldn't.
        state_tool("select", "--subject", key, "--clear")
        decisions.append(f"cleared the lead selection recorded at {str(before.get('head'))[:10]}, so the fallback runs")
    for path in takes:
        change_ownership(c, grant_args(path, lane))
    if takes:
        state_tool("journal", "--kind", "decision.recorded", "--subject", key, "--text",
                   f"{lane} takes {', '.join(takes)}, which {key} changes, into its owns at acceptance", "--why",
                   why.strip())
        decisions.append(f"{lane} took {', '.join(takes)} into its owns: {why.strip()}")
    review_note = (f"review captured at {carried_review['from']} and carried to {head}"
                   if carried_review else "review evidence captured at that head")
    # The check is journaled first, naming the hand-off, so the acceptance after it can name the check.
    state_tool("journal", "--kind", "handoff.checked", "--subject", key, "--because", str(handed_entry(load_state(), key)), "--data", json.dumps(
                   {"head": head, "rounds": len(set(numbers)), "afterMerge": merged, "noChange": False,
                    "notes": [review_note, *decisions]}))
    if not merged:
        # Read again after a --take's grants, which the authorization's ownership then holds.
        authorization = _validator().handoff_authorization(load_state()["state"] if takes else doc["state"], item)
        region_paths = {claim["path"] for claim in doc["state"].get("laneRegions", [])}
        state_tool("handoff", "--accept", key, "--authorization", json.dumps(authorization),
                   *(arg for path in changed if path in region_paths for arg in ("--region-path", path)))
    # What the plan's producer proofs are judged by: the accepted head and the in-app items accepted as blocked.
    append_log("acceptance", key, {"head": head, "ready": ready, "blocked": {label: reason for label, reason in
                                                                           blocked.items() if label in accepted_blocked}})
    # Accepted already: a plan its registration can't rebuild now (a story added without its reason) says why, and
    # the next rebuild catches up.
    try:
        rebuild_plan(c)
    except Unreasoned as error:
        print(f"plan: not rebuilt: {error}")
    print(f"accepted {key} after its merge" if merged else f"accepted {key}; the runner may take it")
    print_peer_claims(c, changed)
    if needs_video(key):
        print("  once it merges: lead-evidence page, republish the page (same address), lead-evidence published --url, "
              "and link its section from the story in the tracker")


def taken_state(c, key: str, lane: str, base: str, head: str, state: dict, takes: list[str]) -> dict:
    """Decision 7: the record as acceptance judges it with ``lane`` holding each file ``takes`` names, refused when
    another lane holds one, lanes share it by lines, it is a declared shared output, the lane holds it already, or the
    candidate doesn't change it. Writes nothing."""
    if "laneOwnership" not in state:
        raise Stop("--take grants a claim in the record: seed this record with lead-own --seed first")
    ownership = c.effective_ownership(state)
    regional = {claim["path"] for claim in state.get("laneRegions", [])}
    shared = shared_outputs(c)
    changed = set(filter(None, run(["git", "diff", "--no-renames", "--name-only", "-z", base, head]).stdout.split("\0")))
    for path in takes:
        if Path(path).is_absolute() or any(part in ("", ".", "..") for part in path.split("/")):
            raise Stop(f"--take {path}: name a repository-relative file")
        others = [other for other in owners_of(ownership, path) if other != lane]
        if others:
            raise Stop(f"--take {path}: {path} is {' and '.join(others)}'s; move it with lead-own --move, or plan the "
                       "change on that lane")
        if path in regional:
            raise Stop(f"--take {path}: lanes share {path} by lines; grant a span with lead-own --region")
        if path in shared:
            raise Stop(f"--take {path}: {path} is a declared shared output, which no lane takes")
        if lane in owners_of(ownership, path):
            raise Stop(f"--take {path}: {lane} holds {path} already; accept without --take")
        if path not in changed:
            raise Stop(f"--take {path}: {key} doesn't change {path}, so there is nothing to take")
    return {**state, "laneOwnership": {name: [*patterns, *(takes if name == lane else [])]
                                       for name, patterns in ownership.items()}}


def lead_base_broken(args) -> None:
    """Name the base broken before a base re-run's verdict, through the state tool's base-broken; a re-run at that head
    ends, and the candidate under it stops. --repair names another queued candidate as the repair; --self-repair says
    the candidate under the re-run holds the fix, so its next accepted hand-off at another head is the repair."""
    c = cfg()
    if not (c.state / "state.json").is_file():
        raise Stop("initialize the delivery record first")
    repair = c.require(args.repair) if args.repair else None
    if repair:
        item = next((q for q in load_state()["state"]["queue"] if q["subject"] == repair), None)
        if not item or item["stage"] != "queued" or item.get("pending"):
            raise Stop(f"--repair names a queued candidate the queue may take; {repair} is "
                       f"{'not in the queue' if not item else 'waiting for acceptance' if item.get('pending') else item['stage']}")
    head = git("rev-parse", "--verify", "--quiet", f"{args.head}^{{commit}}")
    done = state_tool("base-broken", "--head", head, "--check", args.check, "--test", args.test, "--why", args.why,
                      *(["--self-repair"] if args.self_repair else []), check=False)
    answer = json.loads(done.stdout) if done.stdout.strip().startswith("{") else {}
    if done.returncode != 0:
        raise Stop(f"base-broken refused: {answer.get('error') or (done.stderr or done.stdout).strip()[-400:]}")
    print(f"journalled base.broken (entry {answer['broken']['id']}) at {head[:10]}: {args.test} in {args.check}")
    if answer.get("superseded"):
        print(f"  ended the base re-run of {answer['stopped']} (check.superseded, entry {answer['superseded']['id']}); "
              f"{answer['stopped']} stopped as base_broken")
    if repair:
        state_tool("repair", "--subject", repair)
        print(f"  named {repair} the repair: serve takes it alone, and its merge journals base.repaired")
    elif args.self_repair:
        print(f"  {answer['stopped']} holds the fix: accept its next hand-off at another head and it becomes the repair")
    else:
        print("  no repair named: name one with the state tool's repair, or journal base.repaired once the base is fixed")


# -- lead: cleanup ---------------------------------------------------------------------------------

def is_ancestor(commit: str, ref: str) -> bool:
    return run(["git", "merge-base", "--is-ancestor", commit, ref], check=False).returncode == 0


def worktrees_under(path: Path) -> list[Path]:
    """Registered worktrees at or inside `path`, deepest first."""
    root = path.resolve()
    found = [Path(line[len("worktree "):]) for line in git("worktree", "list", "--porcelain").splitlines()
             if line.startswith("worktree ")]
    inside = [p for p in found if p.resolve() == root or root in p.resolve().parents]
    return sorted(inside, key=lambda p: len(p.parts), reverse=True)


def evidence_dir(key: str) -> Path:
    """Where a story's lane evidence is kept once its checkout is gone: beside the record."""
    return cfg().flow_log.parent / "evidence" / key


def squash_merged(key: str, tips: dict[str, str]) -> tuple[str | None, list[str]]:
    """For a story with tips off the base: (what merged it, None) when the forge reports its change request merged and
    every tip is that request's head or below it, as a squash merge leaves them; otherwise (None, why not)."""
    item = next((q for q in load_state()["state"]["queue"] if q["subject"] == key), None)
    url = (item or {}).get("changeRequest")
    if not url or not forge_answers("get"):
        return None, []
    try:
        pr = forge("get", "--url", url)
    except Stop as error:
        return None, [f"couldn't read {url}: {error}"]
    if pr.get("state") != "merged":
        return None, [f"{url} is {pr.get('state') or 'in no state the forge names'}, not merged"]
    reported = pr.get("head")
    head = git("rev-parse", "--verify", "--quiet", f"{reported}^{{commit}}", check=False) \
        if isinstance(reported, str) and len(reported) >= 7 else ""
    if not same_commit(reported, head):
        return None, [f"{url}'s merged head {reported or '(none)'} isn't a commit in this repository"]
    past = [f"{name} ({sha[:10]})" for name, sha in tips.items() if not is_ancestor(sha, head)]
    if past:
        return None, [f"{', '.join(past)} {'is' if len(past) == 1 else 'are'} past {url}'s merged head {head[:10]}"]
    return f"{url} merged at {head[:10]}, and every tip of {key} is at or below it", []


def clean_story(key: str) -> tuple[str, list[str], list[str]]:
    """Remove one merged story's checkout and branches. Returns (status, done, left); status is cleaned, nothing,
    unmerged or refused. Nothing is removed unless every tip of the story is already on the delivery base, or its change
    request merged (by squash, say) at a head every tip is at or below: the forge is asked only in that second case."""
    c = cfg()
    branch, checkout = c.branch(key), c.lane_checkout(key)
    git("fetch", "-q", c.remote, c.base_branch)
    tips, left = {}, []
    if checkout.exists():
        dirty = git("status", "--porcelain", "--untracked-files=all", cwd=checkout, check=False)
        if dirty:
            left.append(f"{checkout} has uncommitted or untracked files:\n      " + dirty[:400].replace("\n", "\n      "))
        tips["the checkout's HEAD"] = git("rev-parse", "HEAD", cwd=checkout)
    local = git("rev-parse", "--verify", "--quiet", f"refs/heads/{branch}", check=False)
    if local:
        tips[f"local {branch}"] = local
    remote = remote_head(branch)
    if remote:
        git("fetch", "-q", c.remote, branch, check=False)
        tips[f"{c.remote}/{branch}"] = remote
    if not tips and not left:
        return "nothing", [], []
    off_base = [f"{name} ({sha[:10]})" for name, sha in tips.items() if not is_ancestor(sha, c.base_ref)]
    merged_by = None
    if off_base:
        merged_by, why = squash_merged(key, tips)
        if merged_by is None:
            return "unmerged", [], [f"not on {c.base_ref}: {', '.join(off_base)}"] + why + left
    if left:
        return "refused", [], left
    done = []
    if checkout.exists():
        review = checkout / c.work / "review" / key
        if review.exists():
            keep = evidence_dir(key)
            shutil.copytree(review, keep, dirs_exist_ok=True, ignore=shutil.ignore_patterns("checkout", "dist"))
            done.append(f"kept the lane's review and in-app evidence in {keep}")
        for nested in worktrees_under(checkout):
            if nested.resolve() != checkout.resolve():
                remove_checkout(nested)
                done.append(f"removed the leftover checkout {nested}")
        removed = run(["git", "worktree", "remove", str(checkout)], check=False)
        if removed.returncode != 0:
            return "refused", done, [f"git worktree remove {checkout} failed: {removed.stderr.strip()[-300:]}"]
        done.append(f"removed {checkout}")
    if local:
        git("branch", "-D", branch)  # -D: its tip is on the base or at or below the merged head (checked above)
        done.append(f"deleted the local branch {branch} ({local[:10]})")
    if remote:
        allowed = (c.flow_raw.get("cleanup") or {}).get("deleteRemoteBranches") is True
        pr = forge("find", "--source", branch) if allowed else {}
        if not allowed:
            left.append(f"{c.remote}/{branch} kept ({c.name} cleanup.deleteRemoteBranches is not true)")
        elif pr.get("url"):
            left.append(f"{c.remote}/{branch} kept: its PR {pr['url']} is still open")
        else:
            git("push", "-q", c.remote, "--delete", branch)
            done.append(f"deleted {c.remote}/{branch} ({remote[:10]})")
    if not done:  # already cleaned: nothing new to journal, only what still waits (a PR not yet closed)
        left = [line for line in left if "deleteRemoteBranches is not true" not in line]
        return ("waiting" if left else "nothing"), [], left
    done = ([merged_by] if merged_by else []) + done
    # The facts name the base it was cleaned against, the story's tip that was removed, and the change request whose
    # merge let a squash-merged story go.
    tip = next(iter(tips.values()), None)
    request = (next((q for q in load_state()["state"]["queue"] if q["subject"] == key), {}).get("changeRequest")
               if merged_by else None)
    state_tool("journal", "--kind", "cleanup.done", "--subject", key, "--data", json.dumps({"base": {"ref": c.base_ref, "head": git("rev-parse", c.base_ref)},
                                     **({"head": tip} if tip else {}), **({"changeRequest": request} if request else {})}),
               check=False)
    return "cleaned", done, left


def lead_cleanup(args) -> None:
    c = cfg()
    keys = [c.require(k) for k in args.keys] if args.keys else list(c.stories)
    failed = False
    doc = load_state()
    for key in keys:
        # As the supervisor's cleanup does: lead-accept reads the checkout, and cleaning up journals a decision of its own.
        item = next((entry for entry in doc["state"]["queue"] if entry["subject"] == key), None)
        if item and unaccepted_merge(doc, item):
            print(f"{key}: waits for the lead's decision on its merge")
            failed |= bool(args.keys)
            continue
        if item and item["stage"] == "merged":
            # As the supervisor's cleanup does: a shared record's deferrals are journalled before the checkout goes.
            for line in journal_deferrals(c, doc, key):
                print(line)
        status, done, left = clean_story(key)
        if status == "nothing":
            print(f"{key}: nothing to clean")
            continue
        print(f"{key}: {status}")
        for line in done:
            print(f"  done: {line}")
        for line in left:
            print(f"  left: {line}")
        failed |= status == "refused" or (status == "unmerged" and bool(args.keys))
    if failed:
        sys.exit(1)


def delivery_processes(lead: Path, state: Path, delivery: str, main: Path) -> list[tuple[int, str]]:
    """This delivery's merge queue, live view and reconcile sweep: orchestrate-work's runner or renderer working in
    the lead's checkout or naming its record, or this tool's `lead-reconcile` working there or in the main checkout.
    A sweep that names another delivery is left alone."""
    found = []
    listing = run(["ps", "-axo", "pid=,command="], check=False).stdout
    for line in listing.splitlines():
        pid_text, _, command = line.strip().partition(" ")
        names = "|".join(re.escape(name) for name in TOOL_NAMES)
        if not re.search(rf"(merge_queue|render_state)\.py|(?:^|/|\s)(?:{names})\s.*\blead-(?:reconcile|run)\b", command) \
                or int(pid_text) == os.getpid():
            continue
        named = re.search(r"--delivery[ =](\S+)", command)
        if named and named.group(1) != delivery:
            continue
        cwd = run(["lsof", "-a", "-p", pid_text, "-d", "cwd", "-Fn"], check=False).stdout
        here = next((Path(l[1:]) for l in cwd.splitlines() if l.startswith("n")), None)
        homes = [lead.resolve()] + ([main.resolve()] if re.search(r"\blead-(?:reconcile|run)\b", command) else [])
        if str(state) in command or (here and here.resolve() in homes):
            found.append((int(pid_text), command))
    return found


def archived_record(path: Path) -> Path:
    """The record in an archived copy: the folder itself when it holds state.json, else its one subfolder that does
    (the supervisor's `latest` holds the record beside the flow log)."""
    path = Path(os.path.abspath(os.path.expanduser(str(path))))
    if (path / "state.json").is_file():
        return path
    found = sorted(child for child in path.iterdir() if (child / "state.json").is_file()) if path.is_dir() else []
    if len(found) != 1:
        held = "no record" if not found else "several records (" + ", ".join(child.name for child in found) + ")"
        raise Stop(f"{path} holds {held}: name the folder that holds the record's state.json")
    return found[0]


def view(args) -> None:
    """Serve the live view of the delivery's record, or of an archived copy of it, and print its address. Needs no
    checkout of the delivery: the live record is found from the delivery file at the base, and an archive needs
    nothing but itself. Views only: publishers never run from here."""
    if args.archive:
        # A copy outlives every checkout, so it is shown with the built-in page, which needs none and is drawn from
        # the record in memory: no view is rendered into the copy.
        record, release, root = archived_record(args.archive), GENERATION, None
        config = {"renderers": [], "publishers": []}
    else:
        c = cfg()
        record, release, root = c.state, c.release, c.root
        if not (record / "state.json").is_file():
            raise Stop(f"no record at {record}: it starts at lead-init. With the lead's checkout gone, serve the "
                       "supervisor's copy: view --archive PATH")
        binding = c.root / ".agents/orchestration.json"
        config = json.loads(binding.read_text()).get("state") if binding.exists() else None
    scripts = str(release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    sys.dont_write_bytecode = True  # the release's modules leave no bytecode in the installed generation
    import render_state  # noqa: E402  (the installed release's own live view)
    if config is None:
        config = {"renderers": [dict(entry) for entry in render_state.DEFAULT_RENDERERS], "publishers": []}
    try:
        render_state.parse_config(config)
        render_state.show(record)
    except (render_state.ConfigError, render_state.StateError) as error:
        raise Stop(f"can't serve {record}: {error}")
    if root is not None:
        os.chdir(root)  # the binding's renderers run from the checkout, as the lead's renders do

    def announce(address: str) -> None:
        print(f"http://{address}/", flush=True)
        if (line:=hosted_line(None,archive=record) if args.archive else hosted_line(c)):print(line,flush=True)
        print(f"serving {record}" + (", an archived copy: it changes only when its writer copies the record again"
                                     if args.archive else "") + "; stop with Ctrl-C", flush=True)

    try:
        render_state.serve_live(record, config, host="127.0.0.1", port=args.port, announce=announce)
    except OSError as error:
        raise Stop(f"can't serve the live view on port {args.port}: {error}")
    except KeyboardInterrupt:
        return


def reconcile_once() -> list[str]:
    """Take the binding's forge and tracker snapshots and reconcile the record with each: an open PR moves a planned
    story to review, a started ticket to building. Returns one line per snapshot."""
    c = cfg()
    binding = c.root / ".agents/orchestration.json"
    states = json.loads(binding.read_text()).get("state", {}) if binding.exists() else {}
    folder = c.state.parent / "snapshots"
    folder.mkdir(parents=True, exist_ok=True)
    # First, so a story just added to the delivery is planned work, not a follow-up, when the tracker lists it. A story
    # registration refuses stays unregistered, and the sweep goes on without it.
    refused = None
    try:
        added = register_stories(c)
    except Unreasoned as error:
        added, refused = [], error
    lines = [f"registered {', '.join(added)} as planned work"] if added else []
    if refused:
        lines.append(f"registration refused: {refused}")
    for name in ("forgeSnapshot", "trackerSnapshot"):
        spec = states.get(name)
        if not spec:
            lines.append(f"{name}: the binding declares none")
            continue
        argv = expand_argv(spec["argv"], stateDirectory=str(c.state), parent=c.delivery)
        try:  # stdout alone: the snapshot is JSON, and warnings go to stderr
            taken = run(argv, cwd=c.root, check=False, timeout=int(spec.get("timeoutSeconds", 60)))
        except subprocess.TimeoutExpired:
            lines.append(f"{name}: timed out")
            continue
        if taken.returncode != 0:
            lines.append(f"{name}: failed ({taken.returncode}): {(taken.stderr or taken.stdout).strip()[-200:]}")
            continue
        snapshot = folder / f"{name}.json"
        snapshot.write_text(taken.stdout)
        done = state_tool("reconcile", "--snapshot", str(snapshot), "--binding", str(binding), check=False)
        summary = re.search(r'"summary":\s*"([^"]*)"', done.stdout or "")
        lines.append(f"{name}: " + (summary.group(1) if summary else (done.stderr or done.stdout).strip()[-200:]))
        lines += [f"{name}: {line}" for line in reconcile_report_lines(done.stdout)]
    if (plan_declared(c) or plan_log_path(c).exists()) and not refused:  # its rebuild would refuse the same story
        lines.append(rebuild_plan_quietly(c))
    return lines


def reconcile_report_lines(output: str | None) -> list[str]:
    """What a reconcile reported, from its output; output that isn't its answer reports nothing."""
    try:
        reports = json.loads(output or "").get("reports", [])
    except (ValueError, AttributeError):
        return []
    return [f"{report.get('subject') or 'the record'}: {report['note']}" for report in reports]


def lead_reconcile(args) -> None:
    """One reconcile sweep, by hand: the supervisor's every pass runs it. By hand, a story registration would refuse
    refuses the sweep, before anything is taken."""
    check_registrable(cfg())
    print(now(), "; ".join(reconcile_once()), flush=True)


def lead_close(args) -> None:
    c = cfg()
    settings = [".agents", str(c.binding_path.relative_to(c.root))]
    dirty = git("status", "--porcelain", "--", *settings, cwd=c.root, check=False)
    if dirty:
        raise Stop(f"the lead's settings have uncommitted changes; commit or drop them first:\n{dirty[:600]}")
    # Everything that can refuse is checked before the supervisor, and the serve it keeps, is stopped.
    doc = load_state()
    closed = latest_close(doc["journal"])
    if closed is None:
        raise Stop("journal delivery.closed first (orchestrate-work's close-out): lead-close runs after it")
    state = doc["state"]
    busy = [q["subject"] for q in state["queue"] if q.get("stage") not in ("merged", "stopped")]
    if busy or (state["meta"].get("checking") or {}).get("now"):
        raise Stop(f"the queue still holds work ({busy or 'a check is running'}); let it finish or stop it first")
    skipped = None
    if decision_owed(c, doc):
        if args.without_compounding is None:
            raise Stop(f"{DECISION_HOLD} is not recorded since the delivery last reopened: record it with "
                       f"{flow_command()} lead-compound --required --ref REF, or --not-required --why TEXT, or close "
                       "without it with lead-close --without-compounding WHY")
        skipped = worded(args.without_compounding, "--without-compounding")
    # The run is stopped while the supervisor finishes its pass, which under --once waits on it, and again once the
    # supervisor has stopped, in case that pass started one.
    runs: list[str | None] = []
    stopped = ask_supervisor_to_stop(c, meanwhile=lambda: runs.append(stop_full_health_run(c)), why="held")
    for line in (stopped, *runs, stop_full_health_run(c)):
        if line:
            print(line)
    lead = c.lane_checkout(c.delivery)
    done, left = [], []
    if skipped is not None:
        # Journalled once the supervisor runs no pass, so none closes out beside this close on the decision it frees.
        entry = journal_id(state_tool("journal", "--kind", COMPOUNDING_KIND, "--data",
                                      json.dumps({"outcome": "skipped", "why": skipped})))
        done.append(f"recorded {DECISION_HOLD} as skipped (journal entry {entry}): {skipped.strip()}")
    # Holds nothing: before the final render and the archive, so both carry it.
    try:
        posture = delivery_posture(c)
        if posture["posture"] == "focused":
            done.append(record_focused(c, posture))
        else:
            with plan_lock(c):
                note_posture(c, posture)
    except (Stop, ValueError, OSError, subprocess.SubprocessError) as error:
        left.append(f"the delivery posture wasn't recorded: {error}")
    for key in c.stories:
        status, d, l = clean_story(key)
        done += [f"{key}: {x}" for x in d]
        left += [f"{key}: {x}" for x in l]
    release = c.release / "skills/orchestrate-work/scripts/render_state.py"
    binding = c.root / ".agents/orchestration.json"

    def render(what: str) -> None:
        if not binding.exists():
            return
        rendered = run([sys.executable, "-B", str(release), "--dir", str(c.state), "--binding", str(binding)], check=False)
        if rendered.returncode == 0:
            done.append(what)
        else:
            left.append(f"the final render failed: {(rendered.stderr or rendered.stdout).strip()[-300:]}")
    render("rendered the views one last time")
    owed = tracker_owed(c, load_state(), closed)
    if owed:
        left.append(f"the tracker hasn't had every update: it is still waiting for {owed}. lead-close doesn't wait "
                    "for the tracker; post them, or let the publisher run")
    archive, archived = archive_delivery(c)
    done += archived
    done += finish_close(c, closed, archive)
    c.flow_log.mkdir(parents=True, exist_ok=True)
    lead_file(c, "closed.json").write_text(json.dumps({"archive": str(archive), "said": archived, "by": "lead-close",
                                                       "at": now(), "entry": closed["id"], **closed_full_health(c)},
                                                      indent=2) + "\n")
    said = carry_close(c)
    if said:
        done.append(said)
    render("rendered the views again, with the close marked finished")
    view = recorded_live(c.state).get("pid")
    for pid, command in delivery_processes(lead, c.state, c.delivery, c.main):
        if pid == view or pid in owned_hosted_processes(c):
            continue  # the live view is stopped last, below, by its recorded pid
        try:
            os.kill(pid, signal.SIGTERM)
            done.append(f"stopped {pid}: {command[:120]}")
        except ProcessLookupError:
            pass
    work_root = json.loads(binding.read_text()).get("workRoot") if binding.exists() else None
    if work_root:
        for nested in worktrees_under(lead / work_root):
            remove_checkout(nested)
            done.append(f"removed the runner's checkout {nested}")
    if c.ship:
        branch = expand(c.ship.get("branch", "ship/{delivery}"), delivery=c.delivery)
        path = c.main / Path(expand(c.ship.get("checkout", str(Path(c.lane_pattern).parent / "{branch}")),
                                    branch=branch.replace("/", "-")))
        if path.exists():
            dirty = git("status", "--porcelain", "--untracked-files=all", cwd=path, check=False)
            tip, pushed_tip = git("rev-parse", "HEAD", cwd=path), remote_head(branch)
            if dirty or tip != pushed_tip:
                left.append(f"{path} kept: " + ("it has uncommitted files" if dirty else f"{branch} isn't pushed at its HEAD"))
            else:
                git("worktree", "remove", str(path))
                git("branch", "-D", branch)
                done.append(f"removed {path} and the local {branch} ({c.remote}/{branch} is kept for its PR)")
    video_keys = [k for k in c.stories if needs_video(k)]
    if video_keys:
        current, problems = evidence_status(video_keys)
        if problems:
            left += [f"evidence: {line}" for line in problems]
        else:
            done.append("the evidence page is current")
    if c.in_app:
        lock, port = Path(expand(c.in_app["lock"])), int(c.in_app["port"])
        try:
            Lease(lock, port, "lead-close", 0).close()  # stops whatever a dead holder left running
            done.append(f"the in-app lease {lock} is free")
        except Stop as held:  # a live check's: its server is inside the lease, and isn't the operator's to kill
            left.append(str(held))
        else:
            if port_open(port):
                left.append(port_busy(port))
    said = unregister_delivery(c)
    if said:
        done.append(said)
    aligned, said = align_operator(c)
    (left if aligned is False else done).append(said)
    # The final request is durable before the local view stops. The detached
    # watcher owns retries after this command's bounded wait.
    final=finalize_hosted(c,archive,closed)
    if final.get('state')!='disabled':done.append('hosted: '+final['state'])
    # The live view last, by the pid live.json records: it served the close until now.
    try:
        said = stop_view(c.state)
        if said:
            done.append(said)
    except Stop as error:
        left.append(str(error))
    try:
        retired, kept = retire_lead(c)
    except (Stop, OSError, ValueError) as error:
        retired, kept = [], [f"the lead's checkout wasn't removed: {error}"]
    done += retired
    left += kept
    print(f"{c.delivery}: closed out")
    for line in done:
        print(f"  done: {line}")
    for line in left:
        print(f"  left: {line}")
    print("  lead: end or archive each lane session you started, where your host lets you, and name any you can't to "
          "the operator.")
    if left:
        sys.exit(1)


# -- lead: the supervisor ------------------------------------------------------------------

SUPERVISOR_PASS_SECONDS = 60
# A child restarted this many times within the window won't stay up, and says so in "Needs you".
CHILD_FLAPS, CHILD_FLAP_SECONDS = 3, 600
SUPERVISOR_WAIT_SECONDS = 120
LANE_DONE = ("idle", "done")


def lead_file(c, name: str) -> Path:
    """A lead-side file beside the flow logs, named with the delivery key as every lead-side file is."""
    return c.flow_log / f"{c.delivery}.{name}"


def valid_pid(pid: object) -> bool:
    return isinstance(pid, int) and not isinstance(pid, bool) and pid > 1


def group_of(pid: int) -> int | None:
    try:
        return os.getpgid(pid)
    except (ProcessLookupError, PermissionError):
        return None


# -- lead: the live view's address, and the supervisor's last word -------------------------------
#
# The view runs in a session of its own, so it outlives the supervisor that started it, and serves until the delivery
# closes. `live.json` in the record's folder says where: its port, its pid, the render_state.py it runs and when it
# started. `supervisor.json` beside it says whether the supervisor runs and, once it stopped, who stopped it.

LIVE_FILE, SUPERVISOR_FILE = "live.json", "supervisor.json"
LIVE_HOST = "127.0.0.1"
# The range a delivery's port is derived in: below the ephemeral ports every host hands out for port 0.
LIVE_PORT_BASE, LIVE_PORT_SPAN = 20000, 10000
# What each recorded reason says, in the status line and on the view's banner.
STOPPED_WORDS = {"close": "it closed the delivery", "replaced": "lead-init --replace replaced the record",
                 "held": "lead-close asked it to stop",
                 "upgrade": "it stopped to start again on the newly applied generation; if none runs, its log says why"}
UNRECORDED_STOP = "stopped without recording why"
NOT_STARTED = "not started"


def spawn_live_view(argv: list[str], log: Path, cwd: Path, port: int) -> tuple[subprocess.Popen, int] | None:
    """Start a live view, `argv` asking for `port` (0: a free one), in a session of its own with its output appended
    to `log`, and wait until it says where it serves. None when it couldn't listen on a port it was given, so the
    caller binds a free one instead."""
    offset = log.stat().st_size if log.exists() else 0
    with open(log, "a") as out:
        proc = subprocess.Popen(argv, cwd=cwd, stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
                                start_new_session=True)
    deadline = time.monotonic() + 60
    while time.monotonic() < deadline:
        for line in log.read_text()[offset:].splitlines():
            with contextlib.suppress(ValueError):
                said = json.loads(line)
                if said.get("live") and said.get("ok"):
                    return proc, int(str(said["live"]).rsplit(":", 1)[1])
                if said.get("code") == "live_unavailable" and port:
                    proc.wait()
                    return None
        if proc.poll() is not None:
            raise Stop(f"the live view stopped as it started: {log.read_text()[offset:][-400:].strip()}")
        time.sleep(0.1)
    stop_group(proc)
    raise Stop(f"the live view didn't start within 60s; its log is {log}")


def derived_live_port(top: str, key: str) -> int:
    """The port a delivery's live view asks for when none is recorded: the first eight bytes of the sha256 of
    `<top>\\0<key>`, big-endian, modulo the span, above the base. The same delivery in the same checkout always asks
    for the same port; two deliveries can still derive one port, and the second then binds a free one."""
    hashed = hashlib.sha256(f"{top}\0{key}".encode("utf-8")).digest()
    return int.from_bytes(hashed[:8], "big") % LIVE_PORT_SPAN + LIVE_PORT_BASE


def live_top(c) -> str:
    """The repository's top-level path the port is derived from: the main checkout, symlinks followed, so the lead's
    own checkout and the main one ask for the same port."""
    return str(c.main.resolve())


def valid_port(port: object) -> bool:
    return isinstance(port, int) and not isinstance(port, bool) and 0 < port < 65536


def json_object(path: Path) -> dict:
    """A small JSON file as an object; empty when it is missing, unreadable or not an object."""
    try:
        found = json.loads(path.read_text())
    except (OSError, ValueError):
        return {}
    return found if isinstance(found, dict) else {}


def recorded_live(state: Path) -> dict:
    """What `live.json` records, when it names a usable port and pid; empty otherwise."""
    live = json_object(state / LIVE_FILE)
    return live if valid_port(live.get("port")) and valid_pid(live.get("pid")) else {}


def wanted_live_port(state: Path, top: str, key: str) -> int:
    """The port a starting view asks for: the one `live.json` records, else the derived one."""
    return recorded_live(state).get("port") or derived_live_port(top, key)


def live_port_setting() -> int | None:
    """RUN_DELIVERY_LIVE_PORT=0: a view with no recorded port binds a free one instead of the derived one, and records
    it. Unset, it asks for the derived one."""
    value = os.environ.get("RUN_DELIVERY_LIVE_PORT", "").strip()
    if not value:
        return None
    if value != "0":
        raise Stop(f"RUN_DELIVERY_LIVE_PORT is {value!r}: it takes 0 alone, for a free port; unset it for the recorded "
                   "or derived one")
    return 0


def live_address(port: int) -> str:
    return f"http://{LIVE_HOST}:{port}/"


def port_of_address(address: str | None) -> int:
    with contextlib.suppress(ValueError, AttributeError):
        return int(str(address).rstrip("/").rsplit(":", 1)[1])
    return 0


def pid_runs(pid: int) -> bool:
    return not process_gone(pid)


def listens(pid: int, port: int) -> bool:
    """Whether `pid` is among the processes listening on `port`, as the host names them."""
    return any(holder == pid for holder, _ in port_holders(port))


def port_takers(port: int) -> list[tuple[int | None, str]]:
    """Who holds `port`: its listeners, or one this host can't name when the port answers and none is named."""
    holders: list[tuple[int | None, str]] = list(port_holders(port))
    if not holders and port_open(port):
        holders = [(None, "a process this host can't name")]
    return holders


def held_words(wanted: int, holders: list) -> str:
    named = ", ".join(f"pid {pid} ({short_command(command)})" if pid else command for pid, command in holders)
    return f"it wanted port {wanted}, held by {named or 'a process this host cannot name'}"


def view_serving(state: Path) -> dict | None:
    """`live.json`'s view, while its pid runs and listens on its recorded port; None otherwise."""
    live = recorded_live(state)
    return live if live and pid_runs(live["pid"]) and listens(live["pid"], live["port"]) else None


def is_view(pid: int) -> bool:
    """Whether `pid` runs orchestrate-work's live view, by its command line: a recorded pid the host has since given
    to another process is never signalled."""
    command = run(["ps", "-o", "command=", "-p", str(pid)], check=False).stdout
    return "render_state.py" in command and " live " in f"{command} "


def stop_view(state: Path, proc: subprocess.Popen | None = None) -> str | None:
    """Stop `live.json`'s view by its recorded pid, and its session with it, then confirm it is gone. `proc` is the
    view's handle when this process started it, so it is reaped. Nothing is stopped by pattern."""
    live = recorded_live(state)
    if not live:
        return None
    return stop_view_process(live["pid"], live["port"], proc)


def stop_view_process(pid: int, port: int, proc: subprocess.Popen | None = None) -> str | None:
    """Stop the view running as `pid`, on `port`, and its session with it; None when it no longer runs."""
    if not pid_runs(pid):
        return None
    if proc is None and not is_view(pid):
        return f"left pid {pid} alone: live.json names it, but it no longer runs the live view"
    for sig, wait in ((signal.SIGTERM, 10), (signal.SIGKILL, 5)):
        with contextlib.suppress(ProcessLookupError, PermissionError):
            if group_of(pid) == pid:
                os.killpg(pid, sig)  # it leads its own session: what it started goes with it
            else:
                os.kill(pid, sig)
        deadline = time.monotonic() + wait
        while time.monotonic() < deadline:
            if proc is not None:
                with contextlib.suppress(subprocess.TimeoutExpired):
                    proc.wait(timeout=0.1)
            if process_gone(pid):
                return f"stopped the live view (pid {pid}) on port {port}"
            time.sleep(0.1)
    raise Stop(f"the live view (pid {pid}) is still running after SIGKILL; stop it, then run this again")


def write_supervisor_status(state: Path, pid: object, running: bool, why: str | None = None,
                            signal_name: str | None = None) -> None:
    """`supervisor.json`: the supervisor's pid, `running` or `stopped`, when, why, and the command that restarts it.
    Written whole, so the view never reads half of it. Not written into a record that is gone."""
    if not (state / "state.json").is_file():
        return
    said = f"it received {signal_name}" if why == "signal" else STOPPED_WORDS.get(why or "")
    doc = {"pid": pid, "state": "running" if running else "stopped", "at": now(),
           **({"why": why} if why else {}), **({"signal": signal_name} if signal_name else {}),
           **({"said": said} if said else {}), "restart": f"{flow_command()} lead-run --resume"}
    staging = state / f".{SUPERVISOR_FILE}.{os.getpid()}"
    staging.write_text(json.dumps(doc, indent=2) + "\n")
    os.replace(staging, state / SUPERVISOR_FILE)


def supervisor_down_words(state: Path) -> str:
    """Why the supervisor is down, as `supervisor.json` records it: not started when no supervisor ever wrote it, as
    after lead-init --no-supervisor."""
    if not (state / SUPERVISOR_FILE).exists():
        return NOT_STARTED
    status = json_object(state / SUPERVISOR_FILE)
    if status.get("state") == "stopped":
        return str(status.get("said") or status.get("why") or UNRECORDED_STOP)
    return UNRECORDED_STOP


def waits_on(c) -> str:
    """What the supervisor's last pass found holding the close: its "Needs you", and the close condition's open parts.
    Read from its pass log, where each pass writes it; empty before the first pass, or once nothing holds it. The
    finish lines not met and the compound-learning decision are read from the record as it stands, so a line marked
    or a decision recorded since the pass is not named."""
    unmet_lines = "finish lines not met: "  # as close_holds words that part
    path = lead_file(c, "supervisor.jsonl")
    lines = [line for line in path.read_text().splitlines() if line.strip()] if path.exists() else []
    try:
        last = json.loads(lines[-1]) if lines else {}
    except ValueError:  # a pass still writing its line
        last = {}
    if not last:
        return ""
    held = [str(item) for item in last.get("closeHeldBy") or []]
    at = next((index for index, item in enumerate(held) if item.startswith(unmet_lines)), None)
    if at is None:  # where close_holds puts it: after the stories not handed off or not merged
        at = sum(1 for item in held if item.startswith(("not handed off: ", "not merged: ")))
    held = [item for item in held if not item.startswith(unmet_lines)]
    unmet = [line["id"] for line in (load_json(c.state / "state.json") or {}).get("finish") or []
             if isinstance(line, dict) and not line.get("met")]
    if unmet:
        held.insert(at, unmet_lines + ", ".join(unmet))
    # The compound-learning decision, as the record stands: a decision recorded since the pass drops it.
    try:
        owed = decision_owed(c, shown_record(c.release, c.state))
    except (Stop, ValueError, OSError):
        owed = DECISION_HOLD in held
    at = held.index(DECISION_HOLD) if DECISION_HOLD in held else sum(
        1 for item in held if item.startswith(("not handed off: ", "not merged: ", unmet_lines,
                                               "lanes not idle or done: ", "not cleaned up: ")))
    held = [item for item in held if item != DECISION_HOLD]
    if owed and last.get("closeHeldBy") is not None:
        held.insert(at, DECISION_HOLD)
    if not held:
        return ""
    shown = "; ".join(held[:5]) + (f"; and {len(held) - 5} more" if len(held) > 5 else "")
    return f". The close waits on: {shown}"


def on_fallback(c) -> str:
    """Under selection.lead, the candidates checking on the binding's fallback because the lead selected no checks for
    them, as the runner records it on each row; empty when none is."""
    state = load_json(c.state / "state.json") or {}
    named = [(item.get("subject"), (item.get("checkSelection") or {}).get("fallback"))
             for item in state.get("queue") or [] if isinstance(item, dict)
             and item.get("stage") in ("checking", "checked")]
    named = [(subject, checks) for subject, checks in named if isinstance(checks, list) and checks]
    if not named:
        return ""
    return "; " + "; ".join(f"{subject} checks on the fallback, {', '.join(map(str, checks))}: the lead selected no "
                            "checks" for subject, checks in named)


def supervisor_line(c) -> str | None:
    """What every lead command repeats: the supervisor's state, the live view's address, any candidate checking on the
    fallback, and what the close waits on, or how to restart it."""
    if not (c.state / "state.json").exists():
        return None
    held, recorded = read_lock(supervisor_lock_path(c))
    if held:
        return (f"supervisor: running (pid {recorded.get('pid')}); live view {recorded.get('address') or 'starting'}"
                + live_fallback(c.state) + on_fallback(c) + listener_words(c) + waits_on(c))
    said = closed_status(c)
    if said is not None:
        return "supervisor: " + said
    serving = view_serving(c.state)
    address = f"; live view {live_address(serving['port'])}" if serving else ""
    return (f"supervisor: down ({supervisor_down_words(c.state)}){address}; restart it with {flow_command()} "
            "lead-run --resume" + listener_words(c) + waits_on(c))


def live_fallback(state: Path) -> str:
    """When the view serves on a port other than the one it asked for: which it wanted, and who held it."""
    fallback = recorded_live(state).get("fallback")
    if not isinstance(fallback, dict) or not valid_port(fallback.get("wanted")):
        return ""
    holders = [(item.get("pid"), str(item.get("command") or "")) for item in fallback.get("heldBy") or []
               if isinstance(item, dict)]
    return f"; the live view {held_words(fallback['wanted'], holders)}"


def close_progress(doc: dict) -> str | None:
    """How far this close got, by the record's marks: "finished", "partway", or None when the record has no started
    mark for it (an older record, or a delivery not closed)."""
    closed = latest_close(doc["journal"])
    closing = doc["state"]["meta"].get("closing") or {}
    if closed is None or (closing.get("started") or {}).get("entry") != closed["id"]:
        return None
    return "finished" if (closing.get("finished") or {}).get("entry") == closed["id"] else "partway"


def finishing_command(c, doc: dict) -> str:
    """What finishes a close that stopped partway: a resumed supervisor when the record meets the close condition (no
    planned story, nothing unmerged, every finish line met, no busy lane, as close_holds reads it); otherwise lead-close,
    since a resumed supervisor would hold on what is unmet and never finish it."""
    # A checkout cleanup hasn't removed yet holds only until the resumed supervisor's own next pass cleans it up, and
    # so do the needs a later pass clears by itself: the publisher's lag, and a fullHealth run ending. Every other
    # holding need waits on the lead, so a resumed supervisor would hold on it for good.
    with configured(c):  # doctor reads a delivery's close while its own configuration is the global one
        needs = [item for item in needs_you(c, doc, closing=True) if not clears_by_itself(item)]
    unmet = [hold for hold in close_holds(c, doc, needs) if not hold.startswith("not cleaned up:") and hold != DECISION_HOLD]
    command = "lead-run --resume" if not unmet else "lead-close"
    if decision_owed(c, doc):
        # The close waits on the decision first, whichever finishes it.
        return (f"lead-compound --required --ref REF, or --not-required --why TEXT, then {command}; or lead-close "
                "--without-compounding WHY")
    return command


@contextlib.contextmanager
def configured(c):
    """Run with `c` as the configuration the helpers read, then put the one before it back."""
    global CFG
    before, CFG = CFG, c
    try:
        yield c
    finally:
        CFG = before


def clears_by_itself(item: dict) -> bool:
    """Whether a "Needs you" item clears on the supervisor's own passes, with nothing from the lead."""
    return item["source"] == "tracker publisher" or item["clears"] == FULL_HEALTH_RUNNING_CLEARS


def closed_status(c) -> str | None:
    """What a stopped supervisor says of the close: finished, or stopped partway and what finishes it. A record with no
    marks reads as before, by closed.json alone."""
    doc = shown_record(c.release, c.state)
    closed = kept_close(c, last_close(doc["journal"]))
    progress = close_progress(doc)
    if progress == "partway":
        command = finishing_command(c, doc)
        return (f"stopped partway through the close; finish it with {flow_command()} {command}"
                + ("; lead-close doesn't wait for the tracker" if command.endswith("lead-close") else ""))
    if progress == "finished":
        return "stopped; the delivery is closed. " + (closed_words(closed) if closed else "")
    if closed:
        return "stopped; the delivery is closed. " + closed_words(closed)
    return None


def closed_words(closed: dict) -> str:
    """Where a closed delivery went: its archive, and the friction note archived in it, written up before the close."""
    note = closed.get("friction")
    return f"Archive {closed.get('archive')}" + (f"; its friction note is {note}; the lead archives the lane sessions "
                                                  f"it started and runs {flow_command()} lead-retire" if note else "")


def supervisor_off() -> bool:
    """RUN_DELIVERY_SUPERVISOR=off: lead-init starts no supervisor, as --no-supervisor says."""
    return os.environ.get("RUN_DELIVERY_SUPERVISOR") == "off"


def start_supervisor(c) -> str:
    """Start `lead-run` detached, in a session of its own, and return the live view's address once it holds the lock.
    Its Node is checked here first, so a refusal reaches the lead's shell rather than its log."""
    require_node(c.release, "the supervisor")
    log = lead_file(c, "supervisor.log")
    log.parent.mkdir(parents=True, exist_ok=True)
    argv = [sys.executable, "-B", str(Path(__file__).resolve()), "--delivery", c.delivery, "lead-run"]
    descriptor=hosted_credentials_pipe(c)
    environment=dict(os.environ)
    if descriptor is not None:environment['RUN_DELIVERY_HOSTED_FD']=str(descriptor)
    try:
        with open(log, "a") as out:
            proc = subprocess.Popen(argv, cwd=c.root, stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
                                    start_new_session=True,env=environment,
                                    pass_fds=() if descriptor is None else (descriptor,))
    finally:
        if descriptor is not None:os.close(descriptor)
    deadline = time.monotonic() + SUPERVISOR_WAIT_SECONDS
    try:
        while time.monotonic() < deadline:
            held, recorded = read_lock(supervisor_lock_path(c))
            if held and recorded.get("pid") == proc.pid and recorded.get("address"):
                return recorded["address"]
            if proc.poll() is not None:
                raise Stop(f"the supervisor stopped as it started: {log.read_text()[-600:].strip()}; its log is {log}")
            time.sleep(0.1)
        raise Stop(f"the supervisor didn't start within {SUPERVISOR_WAIT_SECONDS}s; its log is {log}")
    finally:
        # The supervisor is started to outlive this command, which never waits for it, so the handle is let go here:
        # without this, dropping it later warns that the subprocess "is still running".
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", ResourceWarning)
            del proc


def stop_orphans(c) -> list[str]:
    """Stop the children an earlier supervisor left running: each recorded child still in its group, by that group.
    A pid now outside the group belongs to someone else and is left alone."""
    lock = supervisor_lock_path(c)
    held, recorded = read_lock(lock)
    if held:
        raise Stop(f"a supervisor already runs (pid {recorded.get('pid')}); live view {recorded.get('address')}")
    group = recorded.get("pid")
    if not valid_pid(group):
        return []
    left = [child for child in recorded.get("children") or []
            if isinstance(child, dict) and valid_pid(child.get("pid")) and group_of(child["pid"]) == group]
    if not left:
        return []
    for sig, wait in ((signal.SIGTERM, 10), (signal.SIGKILL, 5)):
        with contextlib.suppress(ProcessLookupError):
            os.killpg(group, sig)
        deadline = time.monotonic() + wait
        while time.monotonic() < deadline and any(group_of(child["pid"]) == group for child in left):
            time.sleep(0.1)
        if not any(group_of(child["pid"]) == group for child in left):
            break
    else:
        raise Stop(f"the earlier supervisor's children (group {group}) are still running after SIGKILL; stop them, "
                   "then run lead-run --resume again")
    return [f"stopped {child.get('name')} (pid {child['pid']}), left by the earlier supervisor (pid {group})"
            for child in left]


def ask_supervisor_to_stop(c, meanwhile: Callable[[], None] | None = None, why: str = "held") -> str | None:
    """Ask a running supervisor to stop after its pass, and wait for it to release its lock. The request carries
    `why`, which the supervisor records in supervisor.json as it stops. `meanwhile` runs once the request is written,
    and again while the wait goes on, for what the pass may be waiting on or just starting."""
    lock = supervisor_lock_path(c)
    held, recorded = read_lock(lock)
    if not held:
        return None
    request = lead_file(c, "supervisor.stop")
    request.write_text(json.dumps({"at": now(), "why": why}) + "\n")
    if meanwhile:
        meanwhile()
    deadline = time.monotonic() + SUPERVISOR_WAIT_SECONDS + supervisor_pass_seconds(c)
    while time.monotonic() < deadline:
        if not read_lock(lock)[0]:
            request.unlink(missing_ok=True)
            return f"stopped the supervisor (pid {recorded.get('pid')}) after its pass"
        if meanwhile:
            meanwhile()
        time.sleep(0.2)
    raise Stop(f"the supervisor (pid {recorded.get('pid')}) didn't stop after its pass; see "
               f"{lead_file(c, 'supervisor.log')}")


def supervisor_pass_seconds(c) -> float:
    value = (c.flow_raw.get("supervisor") or {}).get("passSeconds", SUPERVISOR_PASS_SECONDS)
    if not isinstance(value, (int, float)) or isinstance(value, bool) or value <= 0:
        raise Stop(f"{c.name} supervisor.passSeconds must be a positive number of seconds")
    return float(value)


def binding_state(c) -> dict | None:
    binding = c.shelf.json(".agents/orchestration.json")
    return binding.get("state") if binding else None


def base_head(c) -> str:
    return git("rev-parse", c.base_ref, check=False)


# One pass's steps. Each returns what it did, in a line or a few.

LANE_AT_WORK = ("assigned", "working", "reviewing", "blocked")


def lane_words(doc: dict, remembered: dict | None) -> dict:
    """Each lane's last state in its own words, with when it said it: a row the queue wrote doesn't replace it."""
    words = dict(remembered or {})
    for lane in doc["state"]["lanes"]:
        if lane.get("focusBy") != "runner":
            words[lane["id"]] = {"state": lane.get("state"), "at": lane.get("focusAt") or lane.get("since")}
    return words


def lane_moved_off(doc: dict, item: dict, words: dict | None = None) -> bool:
    """A merged story's lane has moved off it: it is idle or done, or was assigned other work after the merge. The
    queue rests a lane with nothing else open once its story merges; that row is the queue's word, so a lane whose own
    last word since its hand-off was that it is at work still stands in its checkout."""
    lane = next((entry for entry in doc["state"]["lanes"] if entry["id"] == item["lane"]), None)
    if lane is None:
        return True
    rested = lane.get("focusBy") == "runner" and lane.get("focus") == f"{item['subject']} merged"
    # The lane's own word the record kept when the queue rested its row first; a pass's memory of it after that.
    said = (lane.get("restedFrom") if rested else None) or (words or {}).get(item["lane"]) or {}
    handed = max((e["at"] for e in doc["journal"] if e["kind"] == "candidate.handed" and e.get("subject") == item["subject"]),
                 default=None)
    at_work = rested and said.get("state") in LANE_AT_WORK and bool(said.get("at")) and handed is not None \
        and said["at"] >= handed
    if lane.get("state") in LANE_DONE and not at_work:
        return True
    merged = max((e["id"] for e in doc["journal"] if e["kind"] == "candidate.merged" and e.get("subject") == item["subject"]),
                 default=None)
    if merged is None and item.get("stage") == "settled":
        # Settled with no change, it never merged: its last hand-off is where the lane left it.
        merged = max((e["id"] for e in doc["journal"] if e["kind"] == "candidate.handed"
                      and e.get("subject") == item["subject"]), default=None)
    later = [e for e in doc["journal"] if e["kind"] == "lane.assigned" and e.get("lane") == item["lane"]
             and merged is not None and e["id"] > merged and e.get("subject") != item["subject"]]
    return bool(later)


# What the lead journals about a story once it settles it: its check or acceptance, its clean-up, its re-queue, or a
# decision about it.
SETTLING_KINDS = ("decision.recorded", "handoff.checked", "handoff.accepted", "cleanup.done", "handoff.requeued")


def skipped_acceptance(entry: dict) -> bool:
    """Whether a candidate.merged was recovered from the forge before the lead accepted it."""
    return entry["data"].get("acceptanceSkipped") is True


def unaccepted_merge(doc: dict, item: dict) -> dict | None:
    """The merge entry of a story recovered from the forge before the lead accepted it, while nothing the lead journals
    to settle the story follows it."""
    subject = item["subject"]
    if item["stage"] != "merged":
        return None
    merges = [e for e in doc["journal"] if e["kind"] == "candidate.merged" and e.get("subject") == subject]
    if not merges or not skipped_acceptance(merges[-1]):
        return None
    if any(e["kind"] in SETTLING_KINDS and e.get("subject") == subject and e["id"] > merges[-1]["id"] for e in doc["journal"]):
        return None
    return None if any(entry.get("head") == item["head"] for entry in read_log("acceptance", subject)) else merges[-1]


def cleanup_merged(c, doc: dict, words: dict | None = None) -> list[str]:
    """What lead-cleanup does, for each merged story whose lane has moved off it. A story already cleaned up, by hand
    or by an earlier pass, has nothing left to clean and journals nothing. On a shared record, only the stories of the
    lanes this seat holds, whose checkouts are on its machine."""
    said = []
    roles = seat_roles(c)
    for item in doc["state"]["queue"]:
        if item["stage"] != "merged" or item["subject"] not in c.stories or not lane_held(roles, item.get("lane")):
            continue
        if not lane_moved_off(doc, item, words):
            said.append(f"{item['subject']}: waits for {item['lane']} to move off it")
            continue
        # lead-accept reads the lane's evidence from its checkout, so the checkout stays until the lead has decided.
        if unaccepted_merge(doc, item):
            said.append(f"{item['subject']}: waits for the lead's decision on its merge")
            continue
        said += journal_deferrals(c, doc, item["subject"])
        status, done, left = clean_story(item["subject"])
        if status not in ("nothing", "waiting"):
            said.append(f"{item['subject']}: {status}" + "".join(f"; {line}" for line in left))
    # A story settled with no change leaves its lane's checkout too, once the lane has moved off it.
    for entry in doc["state"].get("planned", []):
        if entry["stage"] != "settled" or entry["subject"] not in c.stories or not lane_moved_off(doc, entry, words) \
                or not lane_held(roles, entry.get("lane")):
            continue
        status, done, left = clean_story(entry["subject"])
        if status not in ("nothing", "waiting"):
            said.append(f"{entry['subject']}: {status}" + "".join(f"; {line}" for line in left))
    return said


def proof_state(c, plan: dict, doc: dict, unit: dict, kind: str) -> str:
    """A unit's proof, as the line map judges it: a producer proof from the plan's evidence at the queued head; handed,
    merged and review from the record, review as the lead's acceptance at the queued head."""
    subject = unit["subject"]
    if any(entry["subject"] == subject and entry["stage"] == "settled" for entry in doc["state"].get("planned", [])):
        return "done"  # closed with no change needed: every proof it owes is the lead's accepted evidence
    item = next((entry for entry in doc["state"]["queue"] if entry["subject"] == subject), None)
    source = next((k.get("source") for k in plan.get("proofKinds", []) if k.get("id") == kind), None)
    if source == "producer":
        entry = ((plan.get("evidence") or {}).get(subject) or {}).get(kind)
        if not entry or entry.get("state") == "todo":
            return "todo"
        return "stale" if item and entry.get("head") != item.get("head") else entry["state"]
    if kind == "handed":
        # What merged is past waiting, whatever the flag says, as the line map reads it.
        return "done" if item and item["stage"] != "stopped" and (item["stage"] == "merged" or not item.get("pending")) else "open"
    if kind == "merged":
        return "done" if item and item["stage"] == "merged" else "open"
    if kind == "review":
        accepted = read_log("acceptance", subject)
        return "done" if item and accepted and accepted[-1].get("head") == item.get("head") else "open"
    return "open"


def finished_lines(c, plan: dict, doc: dict) -> list[str]:
    """The finish lines whose covered criteria have every covered proof done (a waiver isn't done). A line that names
    no criteria and no proofs has nothing the record proves: it is the lead's, and never among them."""
    units = [unit for unit in plan.get("units", []) if not unit.get("removed")]
    criteria = [(item["id"], unit) for unit in units for item in unit.get("criteria", [])]
    ready = []
    for line in plan.get("finish", []):
        if leads_line(line):
            continue
        covers = plan_covers(line)
        named = covers.get("criteria")
        if named == "all":
            rows = [unit for _, unit in criteria]
        elif not named:
            rows = units
        else:
            rows = [unit for cid, unit in criteria if cid in named]
        kinds = covers.get("proofs") or []

        def settled(unit: dict) -> bool:
            owed = unit.get("proofs", [])
            wanted = kinds or owed
            return all(kind not in owed or proof_state(c, plan, doc, unit, kind) == "done" for kind in wanted)
        if rows and all(settled(unit) for unit in rows):
            ready.append(line["id"])
    return ready


def finish_met_names(entry: dict, line: str) -> bool:
    """Whether a finish.met is about this finish line: by its subject, or its facts' finish."""
    return entry.get("subject") == line or entry["data"].get("finish") == line


def journal_finish_met(c, doc: dict) -> list[str]:
    """Mark and journal each finish line whose criteria and proofs are all done, once: a line the lead already
    marked or journalled by hand is left as it is, and so is one the supervisor marked before and finds unmarked,
    which the lead unmarked. Its marks are kept in the flow log."""
    plan = load_json(c.state / PLAN_FILE)
    if not plan:
        return []
    ready = set(finished_lines(c, plan, doc))
    marked = {entry["line"] for entry in read_log("finish", c.delivery)}
    said = []
    for line in doc["state"]["finish"]:
        if line["id"] not in ready:
            continue
        journalled = [e for e in doc["journal"] if e["kind"] == "finish.met" and finish_met_names(e, line["id"])]
        if line["id"] in marked:
            continue
        if not line.get("met"):
            patch_from(lambda fresh, line=line: {"finish": [{**entry, "met": True} if entry["id"] == line["id"] else entry
                                                            for entry in fresh["state"]["finish"]]},
                       f"finish line {line['id']} met")
        if not journalled:
            state_tool("journal", "--kind", "finish.met", "--subject", line["id"], "--data",
                       json.dumps({"finish": line["id"], "by": "supervisor"}))
            said.append(f"finish line {line['id']} met")
        # Logged last, so a pass whose journal failed leaves the line for the next pass to journal.
        append_log("finish", c.delivery, {"line": line["id"]})
    return said


def lead_finish(args) -> None:
    """Mark a finish line the record can't prove met, with the lead's evidence: the mark and its finish.met, with
    `by: lead`, in one write, so a failure leaves neither. Refused, with nothing written, for a line the record
    doesn't hold, a line the record proves, a line already met, and empty evidence. Then the live view is rendered
    once, as a pass renders it, so the line drops out of the view and the status line at once."""
    c = cfg()
    evidence = args.evidence
    if evidence.startswith("@"):
        try:
            evidence = Path(evidence[1:]).expanduser().read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as error:
            raise Stop(f"--evidence {args.evidence}: the file can't be read: {error}") from None
    evidence = evidence.strip()
    if not evidence:
        raise Stop("--evidence is required: say what shows the line met, or name a file with @FILE, not empty or "
                   "only spaces")
    plan = load_json(c.state / PLAN_FILE) or {}
    declared = {line["id"]: line for line in [*c.finish, *(plan.get("finish") or [])] if isinstance(line, dict)}
    for _ in range(PATCH_ATTEMPTS):
        doc = load_state()
        line = next((entry for entry in doc["state"]["finish"] if entry["id"] == args.line), None)
        if line is None:
            held = ", ".join(entry["id"] for entry in doc["state"]["finish"]) or "none"
            raise Stop(f"the record holds no finish line {args.line}: its lines are {held}")
        if not leads_line(declared.get(args.line, line)):
            raise Stop(f"finish line {args.line}: the record proves this line: the supervisor marks it when its "
                       "criteria and proofs are done")
        if line.get("met"):
            raise Stop(f"finish line {args.line} is already met")
        done = state_tool("journal", "--kind", "finish.met", "--subject", args.line,
                          "--data", json.dumps({"finish": args.line, "evidence": evidence, "by": "lead"}),
                          "--element", f"finish[id={args.line}]", "--patch", json.dumps({"met": True}),
                          "--version", str(doc["state"]["version"]), check=False)
        try:  # the state tool answers with one JSON document, pretty-printed
            answer = json.loads(done.stdout)
        except ValueError:
            answer = {}
        answer = answer if isinstance(answer, dict) else {}
        if done.returncode == 0:
            print(f"finish line {args.line} met (journal entry {answer['entry']['id']}); views: {render_views(c)}")
            return
        if answer.get("code") != "version_stale":
            raise Stop(f"the state tool refused finish line {args.line}: "
                       f"{(answer.get('error') or done.stderr or done.stdout).strip()[-600:]}")
    raise Stop(f"version_stale: the record kept changing while finish line {args.line} was marked; tried "
               f"{PATCH_ATTEMPTS} times, reading it afresh each time. Run it again once the other writer settles")


def render_views(c, only: str | None = None) -> str:
    """Render with the binding's whole `state` member, publishers included, as the runner's writes do; `only`
    "publishers" or "renderers" runs just that half, so a pass can derive "Needs you" between the two."""
    config = binding_state(c)
    if config is None:
        return "no binding: nothing to render"
    if only == "publishers":
        # `liveHome` names a renderer, and this half declares none; the renderers half still answers to it.
        config = {**{key: value for key, value in config.items() if key != "liveHome"}, "renderers": []}
    elif only == "renderers":
        config = {**config, "publishers": []}
    script = c.release / "skills/orchestrate-work/scripts/render_state.py"
    done = run([sys.executable, "-B", str(script), "--dir", str(c.state), "--state-config", json.dumps(config)],
               cwd=c.root, check=False, timeout=300)
    return "rendered" if done.returncode == 0 else f"render failed ({done.returncode}): " \
        f"{(done.stderr or done.stdout).strip()[-300:]}"


def copy_latest(c) -> Path:
    """Copy the record and the flow log, under the state lock, into the archive location's one `latest` folder, so a
    current copy outlives the lead's checkout."""
    target = archive_root(c) / "latest"
    staging = target.with_name(f".latest.{os.getpid()}")
    shutil.rmtree(staging, ignore_errors=True)
    staging.mkdir(parents=True)
    with open(c.state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            shutil.copytree(c.state, staging / c.state.name, ignore=shutil.ignore_patterns("*.lock","hosted-*",".hosted-*"))
            if c.flow_log.exists():
                shutil.copytree(c.flow_log, staging / "flow-log", ignore=shutil.ignore_patterns("*.lock"))
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)
    copy_hosted(c,staging/c.state.name)
    old = target.with_name(f".latest.{os.getpid()}.old")
    if target.exists():
        os.replace(target, old)
    os.replace(staging, target)
    shutil.rmtree(old, ignore_errors=True)
    return target


# The lead's listener. `lead-wait` wraps the state tool's `wait` and keeps a lease in the record while it runs; the
# supervisor's "Needs you", the live view, the status line and the lead commands all read it through lead_listener.

LEAD_WAIT_LEASE = "lead-wait.json"
LEAD_WAIT_REFRESH_SECONDS = 60
LEAD_WAIT_LIVE_SECONDS = 180


def utc_stamp(at: float) -> str:
    return datetime.datetime.fromtimestamp(at, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def stamp_seconds(value: object) -> float | None:
    """A UTC stamp as epoch seconds, with or without its fraction; None for anything else."""
    if not isinstance(value, str):
        return None
    for pattern in ("%Y-%m-%dT%H:%M:%S.%fZ", "%Y-%m-%dT%H:%M:%SZ"):
        try:
            return datetime.datetime.strptime(value, pattern).replace(tzinfo=datetime.timezone.utc).timestamp()
        except ValueError:
            continue
    return None


def lead_listener(state: Path, at: float | None = None) -> dict | None:
    """The live lease, or None: a lease is live while its pid is alive and its `updatedAt` is under
    LEAD_WAIT_LIVE_SECONDS old. A missing, unreadable or malformed lease, or one stamped in the future past a refresh,
    is absent."""
    try:
        lease = json.loads((state / LEAD_WAIT_LEASE).read_text())
    except (OSError, ValueError):
        return None
    if not isinstance(lease, dict) or not valid_pid(lease.get("pid")):
        return None
    updated = stamp_seconds(lease.get("updatedAt"))
    if updated is None:
        return None
    age = (time.time() if at is None else at) - updated
    if not -LEAD_WAIT_REFRESH_SECONDS <= age < LEAD_WAIT_LIVE_SECONDS or process_gone(lease["pid"]):
        return None
    return lease


def write_lease(state: Path, lease: dict) -> None:
    """Rewrite the lease through a temporary file, under the state lock the record's copies take."""
    path = state / LEAD_WAIT_LEASE
    staging = path.with_name(f".{LEAD_WAIT_LEASE}.{os.getpid()}")
    with open(state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            staging.write_text(json.dumps(lease, indent=2) + "\n")
            os.replace(staging, path)
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


def drop_lease(state: Path, pid: int) -> None:
    """Remove the lease if it is still this pid's: a later lead-wait's lease is its own."""
    path = state / LEAD_WAIT_LEASE
    with open(state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            try:
                held = json.loads(path.read_text())
            except (OSError, ValueError):
                return
            if isinstance(held, dict) and held.get("pid") == pid:
                path.unlink(missing_ok=True)
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


def hold_lease(state: Path, proc, *, after: int, checkout: Path, every: float | None = None,
               clock: Callable[[], float] = time.time) -> int:
    """Keep this process's lease while `proc` runs, rewriting it every `every` seconds, and remove it when `proc` ends
    or this process is stopped; returns `proc`'s exit code."""
    every = LEAD_WAIT_REFRESH_SECONDS if every is None else every
    pid = os.getpid()
    started = utc_stamp(clock())
    lease = {"pid": pid, "startedAt": started, "updatedAt": started, "after": after, "checkout": str(checkout)}
    try:
        write_lease(state, lease)
        while True:
            try:
                return proc.wait(timeout=every)
            except subprocess.TimeoutExpired:
                lease["updatedAt"] = utc_stamp(clock())
                write_lease(state, lease)
    finally:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=10)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
        drop_lease(state, pid)


def listener_needed(state: dict) -> list[str]:
    """What needs the lead to listen: each lane that isn't idle or done, and each candidate not yet merged."""
    return ([f"{lane['id']} ({lane.get('state')})" for lane in state.get("lanes", []) if lane.get("state") not in LANE_DONE]
            + [f"{item['subject']} ({item.get('stage')})" for item in state.get("queue", []) if item.get("stage") != "merged"])


def listener_facts(state: dict) -> dict:
    """The same, as a held stop's facts: the lanes still working and the pieces still to land, by name."""
    return {"lanes": [lane["id"] for lane in state.get("lanes", []) if lane.get("state") not in LANE_DONE],
            "pieces": [item["subject"] for item in state.get("queue", []) if item.get("stage") != "merged"]}


def wait_output(c) -> Path:
    """Where lead-wait writes the wait's one result document by default: beside the flow logs, outside the record."""
    return lead_file(c, "wait.json")


def last_restart(c, journal: list[dict]) -> list[str] | None:
    """The `restart` arguments the last wait into the default output printed, while they still fit this journal."""
    try:
        result = json.loads(wait_output(c).read_text())
    except (OSError, ValueError):
        return None
    restart = result.get("restart") if isinstance(result, dict) else None
    if not isinstance(restart, list) or not all(isinstance(word, str) for word in restart) or "--after" not in restart:
        return None
    try:
        after = int(restart[restart.index("--after") + 1])
    except (IndexError, ValueError):
        return None
    through = journal[-1]["id"] if journal else 0
    return restart if 0 <= after <= through else None


def lead_wait_command(c, doc: dict) -> str:
    """The exact lead-wait to start: the last wait's own restart, so nothing journalled since it read is missed, or,
    with none, one starting after the journal's last entry."""
    start = f"{flow_command()} --delivery {c.delivery} lead-wait"
    restart = last_restart(c, doc["journal"])
    if restart is not None:
        return f"{start} {shlex.join(restart)}"
    through = doc["journal"][-1]["id"] if doc["journal"] else 0
    return f"{start} --after {through} --output {shlex.quote(str(wait_output(c)))}"


def listener_lines(c) -> list[str]:
    """What a lead command ends with while a lane works or a candidate is queued: the lead-wait to start in the
    background, or that one listens. Nothing otherwise."""
    if not (c.state / "state.json").exists():
        return []
    doc = shown_record(c.release, c.state)
    needed = listener_needed(doc["state"])
    if not needed:
        return []
    lease = lead_listener(c.state)
    if lease is not None:
        return [f"The lead's wake: {', '.join(needed)}; lead-wait is listening (pid {lease['pid']}, after journal entry "
                f"{lease.get('after')}). When it ends, start it again with the arguments its result's `restart` names."]
    return [f"The lead's wake: {', '.join(needed)}, and no lead-wait is listening. Start this in the background before "
            "you end your turn, and after each wake start it again with the arguments its result's `restart` names:",
            f"  {lead_wait_command(c, doc)}"]


def listener_words(c) -> str:
    """The status line's word on the listener: empty while one listens or nothing needs one."""
    if lead_listener(c.state) is not None:
        return ""
    try:  # read as the record holds it, as on_fallback reads it: a status line never refuses over it
        state = load_json(c.state / "state.json") or {}
    except (OSError, ValueError):
        return ""
    needed = listener_needed(state) if isinstance(state, dict) else []
    return f"; the lead isn't listening: no lead-wait runs while {', '.join(needed)}" if needed else ""


def lead_wait(args) -> None:
    """`delivery_state.py wait`, with a lease in the record while it runs. Takes the wait's own arguments; without
    `--after` it starts after the journal's last entry, and without `--output` it writes the default output."""
    c = cfg()
    if not (c.state / "state.json").exists():
        raise Stop(f"no record at {c.state}: lead-init starts it")
    record_session(c, "lead")
    passed = list(args.wait_args)
    parsed = _validator().wait_arguments(passed)
    after = parsed.after
    if after is None:
        journal = load_state()["journal"]
        after = journal[-1]["id"] if journal else 0
        passed = ["--after", str(after), *passed]
    if parsed.output is None:
        wait_output(c).parent.mkdir(parents=True, exist_ok=True)
        passed.append(f"--output={wait_output(c)}")
    script = c.release / "skills/orchestrate-work/scripts/delivery_state.py"
    proc = subprocess.Popen([sys.executable, "-B", str(script), "--dir", str(c.state), "wait", *passed])
    sys.exit(hold_lease(c.state, proc, after=after, checkout=c.root))


# Host hooks: the decisions behind the hooks this skill declares in hooks.json. Each reads the host's payload on stdin
# and prints one neutral verdict, {"verdict": "allow" | "warn" | "block", "reason"?, "context"?}; the dispatcher alone
# knows the host's own shapes. A session's role comes from the payload's cwd, never from this process's own folder.

HOOK_MODES = ("off", "warn", "enforce")
# Each hook's id in the configuration's `hooks`, and its mode when the key is missing.
HOOK_DEFAULTS = {"lead.may-stop": "warn", "delivery.orient": "enforce"}
HOOK_HELD = "hook.held"
ORIENT_LIMIT = 4000
# The command the lifecycle installs for each event the receipt records: doctor looks for it in the settings file.
HOOK_SETTINGS_EVENTS = {"session-start": "SessionStart", "stop": "Stop"}
HOOK_INSTALLED = 'python3 -B "${{CLAUDE_PROJECT_DIR}}/.agent-skills/current/__main__.py" hook claude-code {event} || exit 1'
HOOK_PYTHON = (3, 11)


def hook_settings_problems(raw: dict) -> list[str]:
    """What is wrong with the configuration's `hooks`: an unknown hook id or mode, each named."""
    if "hooks" not in raw:
        return []
    hooks = raw["hooks"]
    if not isinstance(hooks, dict):
        return [f"`hooks` is {json.dumps(hooks)}, not an object of hook id to mode"]
    problems = []
    for hook_id, mode in hooks.items():
        if hook_id not in HOOK_DEFAULTS:
            problems.append(f"`hooks` names an unknown hook {hook_id!r}: the hooks are {', '.join(HOOK_DEFAULTS)}")
        elif mode not in HOOK_MODES:
            problems.append(f"`hooks.{hook_id}` is {json.dumps(mode)}: a mode is one of {', '.join(HOOK_MODES)}")
    return problems


def hook_mode(raw: dict, hook_id: str) -> str:
    """A hook's mode: the configuration's, or its default when the key is missing or not a mode doctor accepts."""
    hooks = raw.get("hooks") if isinstance(raw.get("hooks"), dict) else {}
    mode = hooks.get(hook_id, HOOK_DEFAULTS[hook_id])
    return mode if mode in HOOK_MODES else HOOK_DEFAULTS[hook_id]


def real(path: str | Path) -> Path:
    return Path(os.path.realpath(path))


def within(path: Path, folder: Path) -> bool:
    """Whether `path` is `folder` or below it; both already resolved."""
    return path == folder or folder in path.parents


def checkouts_of(cwd: Path) -> list[Path]:
    """Every checkout of the repository at `cwd`, resolved, from `git worktree list`; none outside a repository."""
    done = run(["git", "worktree", "list", "--porcelain"], cwd=cwd, check=False, timeout=10)
    if done.returncode != 0:
        return []
    found = [real(line[len("worktree "):]) for line in done.stdout.splitlines() if line.startswith("worktree ")]
    return [path for path in found if path.is_dir()]


def deepest(path: Path, checkouts: list[Path]) -> Path | None:
    """The checkout `path` lies in: the deepest that holds it, so a checkout nested in another is its own."""
    holders = [checkout for checkout in checkouts if within(path, checkout)]
    return max(holders, key=lambda checkout: len(checkout.parts)) if holders else None


class Seat:
    """A session's place in a delivery: `lead` of each delivery open in its checkout, or `lane` on one story."""

    def __init__(self, role: str, configs: list[Config], story: str | None = None):
        self.role, self.configs, self.story = role, configs, story


def seat_of(payload: dict) -> Seat | None:
    """The session's seat. A `session_id` an open delivery's sessions.json holds seats it by the role recorded there,
    whatever its cwd: a lane on its story, matched first, else the lead of each delivery that recorded it. Any other
    session is seated from the payload's cwd: a lane when the cwd lies in the checkout of a story of an open
    delivery, matched first; else the lead of each delivery whose record is open in the cwd's checkout; else none.
    A cwd's checkout is the deepest one holding it, after resolving symlinks, so a lane nested in the lead's
    checkout is a lane, and any other checkout nested there is neither."""
    global OFFLINE
    OFFLINE = True  # a hook reads what this machine has; it never fetches
    cwd_text, session = payload.get("cwd"), payload.get("session_id")
    if not isinstance(cwd_text, str) or not os.path.isabs(cwd_text) or not os.path.isdir(cwd_text):
        return None
    cwd = real(cwd_text)
    checkouts = checkouts_of(cwd)
    owner = deepest(cwd, checkouts)
    if owner is None:
        return None
    configs: dict[Path, Config | None] = {}

    def config_at(root: Path) -> Config | None:
        if root not in configs:
            try:
                configs[root] = Config(root, need_delivery=False, tolerant=True, pick=False)
            except (Stop, ValueError, OSError, KeyError, TypeError, subprocess.SubprocessError):
                configs[root] = None
        return configs[root]

    def loaded(root: Path, key: str) -> Config | None:
        base = config_at(root)
        if base is None:
            return None
        c = copy.copy(base)
        c.sources, c.conflicts = dict(base.sources), []
        try:
            c.load_delivery(key)
        except (Stop, ValueError, OSError, KeyError, TypeError):
            return None
        return c

    here = config_at(owner)
    if here is None:
        return None
    lanes: list[tuple[Path, str, str]] = []
    leads: list[str] = []
    recorded_lanes: list[tuple[Path, str, str]] = []
    recorded_leads: list[tuple[Path, str]] = []
    for key, d in here.delivery_files().items():
        lead_root = deepest(real(here.state_of(key, d)), checkouts)
        lead = config_at(lead_root) if lead_root is not None else None
        if lead is None:
            continue
        files = lead.delivery_files()
        if key not in files or not lead.open_here(key, files[key]):
            continue
        stories = files[key].get("stories") or {}
        entry = recorded_session(lead.state_of(key, files[key]), session)
        if entry is not None and entry.get("role") == "lane" and entry.get("story") in stories:
            recorded_lanes.append((lead_root, key, entry["story"]))
        elif entry is not None and entry.get("role") == "lead":
            recorded_leads.append((lead_root, key))
        for story in stories:
            if real(lead.lane_checkout(story)) == owner:
                lanes.append((lead_root, key, story))
        if lead_root == owner:
            leads.append(key)
    for lead_root, key, story in recorded_lanes:
        c = loaded(lead_root, key)
        if c is not None:
            return Seat("lane", [c], story)
    found = [c for c in (loaded(lead_root, key) for lead_root, key in recorded_leads) if c is not None]
    if found:
        return Seat("lead", found)
    for lead_root, key, story in lanes:
        c = loaded(lead_root, key)
        if c is not None:
            return Seat("lane", [c], story)
    found = [c for c in (loaded(owner, key) for key in leads) if c is not None]
    return Seat("lead", found) if found else None


# The host sessions a delivery's commands ran in, beside its record: {"sessions": {<session id>: {"role": "lane",
# "story": <key>} or {"role": "lead"}}}, so a hook seats a session by its id rather than by the folder its last command
# ran in. A host that exports no session id records none, and its sessions are seated by cwd.
SESSIONS_FILE = "sessions.json"
SESSION_VARIABLE = "CLAUDE_CODE_SESSION_ID"


def read_sessions(path: Path) -> dict:
    """sessions.json's `sessions`, or none when it is missing or unreadable."""
    try:
        doc = json.loads(path.read_text())
    except (OSError, ValueError):
        return {}
    sessions = doc.get("sessions") if isinstance(doc, dict) else None
    return sessions if isinstance(sessions, dict) else {}


def recorded_session(state: Path, session: object) -> dict | None:
    """What the record at `state` holds for the host session `session`, or None."""
    if not isinstance(session, str) or not session:
        return None
    entry = read_sessions(state / SESSIONS_FILE).get(session)
    return entry if isinstance(entry, dict) else None


def record_session(c, role: str, story: str | None = None) -> None:
    """Record the session this command runs in, when the host names it, as `role` (on `story`, for a lane) in the
    record's sessions.json. It reads, changes and replaces the file under the record's state lock, so two sessions
    recording at once both keep their entry, and leaves it untouched when it already says so."""
    session = os.environ.get(SESSION_VARIABLE, "").strip()
    if not session or not c.state.is_dir():
        return
    entry = {"role": role, **({"story": story} if story else {})}
    path = c.state / SESSIONS_FILE
    with open(c.state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            sessions = read_sessions(path)
            if sessions.get(session) == entry:
                return
            sessions[session] = entry
            staging = path.with_name(f".{path.name}.{os.getpid()}")
            try:
                staging.write_text(json.dumps({"sessions": sessions}, indent=2) + "\n")
                os.replace(staging, path)
            finally:
                staging.unlink(missing_ok=True)  # gone once replaced; a failed write leaves the file as it was
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


def record_of(c) -> dict:
    """The record as the state tool shows it: {"state", "journal"}."""
    tool = c.release / "skills/orchestrate-work/scripts/delivery_state.py"
    return json.loads(run([sys.executable, "-B", str(tool), "--dir", str(c.state), "show"], timeout=10).stdout)


def as_lead(c) -> None:
    """Make `c` the configuration the printed commands name (flow_command reads it)."""
    global CFG
    CFG = c


def missing_listener(c) -> tuple[dict, list[str]] | None:
    """The record and what needs the lead to listen, when something does and no lead-wait listens; else None."""
    doc = record_of(c)
    needed = listener_needed(doc["state"])
    return (doc, needed) if needed and lead_listener(c.state) is None else None


def lead_may_stop(payload: dict) -> dict:
    """lead.may-stop: hold a lead's stop while a lane works or a candidate is queued and no lead-wait listens.
    `block` under enforce with one open delivery in the checkout; `warn` under warn, and whenever two or more open
    deliveries share the checkout, since which one this session leads can't be told. A hold the session hasn't
    already been held for journals one hook.held in each delivery it names."""
    seat = seat_of(payload)
    if seat is None or seat.role != "lead":
        return {"verdict": "allow"}
    mode = hook_mode(seat.configs[0].flow_raw, "lead.may-stop")
    if mode == "off":
        return {"verdict": "allow"}
    missing = []
    for c in seat.configs:
        found = missing_listener(c)
        if found is not None:
            missing.append((c, *found))
    if not missing:
        return {"verdict": "allow"}
    shared = len(seat.configs) > 1
    verdict = "block" if mode == "enforce" and not shared else "warn"
    reasons = []
    for c, doc, needed in missing:
        as_lead(c)
        reasons.append(f"Delivery {c.delivery}: the lead isn't listening: no lead-wait runs while {', '.join(needed)}. "
                       "Start this in the background before you stop, and after each wake start it again with the "
                       f"arguments its result's `restart` names: {lead_wait_command(c, doc)}")
    if shared:
        reasons.insert(0, f"{len(seat.configs)} open deliveries share this checkout "
                          f"({', '.join(c.delivery for c in seat.configs)}), so which one this session leads can't be "
                          "told; lead each from its own checkout.")
    if payload.get("stop_hook_active") is not True:
        for c, doc, needed in missing:
            tool = c.release / "skills/orchestrate-work/scripts/delivery_state.py"
            done = run([sys.executable, "-B", str(tool), "--dir", str(c.state), "journal", "--kind", HOOK_HELD,
                        "--data", json.dumps({"hook": "lead.may-stop", "verdict": verdict, **listener_facts(doc["state"])})],
                       check=False, timeout=10)
            if done.returncode != 0:
                print(f"run-delivery: {HOOK_HELD} not journalled in {c.delivery}: "
                      f"{(done.stderr or done.stdout).strip()[-300:]}", file=sys.stderr)
    return {"verdict": verdict, "reason": "\n".join(reasons)}


def delivery_stage(state: dict) -> str:
    """The delivery's stage, from the record's structure alone."""
    work = [*state.get("planned", []), *state.get("queue", [])]
    if (any(lane.get("state") not in LANE_DONE for lane in state.get("lanes", []))
            or any(item.get("stage") not in ("merged", "settled") for item in work)):
        return "delivering"
    return "finishing: every story merged or settled" if work else "starting: no story assigned yet"


def needs_count(c) -> str:
    """How many items "Needs you" holds, from the supervisor's list, or why that isn't known. Never their text."""
    resume = f"{flow_command()} --delivery {c.delivery} lead-run --resume"
    try:
        needs = json.loads((c.state / NEEDS_FILE).read_text())
    except (OSError, ValueError):
        return f"not known: no supervisor has listed it; {resume} starts one"
    items = needs.get("items") if isinstance(needs, dict) else None
    if not isinstance(items, list) or not needs.get("running"):
        return f"not known: the supervisor isn't running; {resume} starts it"
    stale = stamp_seconds(needs.get("staleAfter"))
    if stale is not None and stale < time.time():
        return f"not known: the supervisor's list is out of date; {resume} starts it again"
    return f"{len(items)} item{'' if len(items) == 1 else 's'}"


def lane_next(c, state: dict, story: str) -> str:
    """The next lane command for `story`, from the record's structure alone."""
    start = f"{flow_command()} --delivery {c.delivery}"
    item = next((item for item in state.get("queue", []) if item.get("subject") == story), None)
    if item is not None and item.get("stage") == "merged":
        return "none: the story has merged"
    if item is not None and item.get("stage") != "stopped":
        return f"none while the story is {item.get('stage')} in the merge queue; the lead answers"
    planned = next((entry for entry in state.get("planned", []) if entry.get("subject") == story), None)
    stage = planned.get("stage") if planned else None
    if stage == "settled":
        return "none: the story settled with no change needed"
    if planned and planned.get("noChange"):
        return "none while the story's no-change hand-off waits for the lead to accept it; the lead answers"
    if item is None and stage in (None, "planned"):
        return f"{start} lane-start {story} --base {c.base_branch}"
    return f"{start} gate {story}"


def orientation(seat: Seat) -> str:
    """delivery.orient's context: only structured fields, never free text from the journal, a hand-off or a tracker."""
    lines = []
    for c in seat.configs:
        as_lead(c)
        doc = record_of(c)
        if seat.role == "lane":
            story = seat.story or ""
            lane = c.lane_of(story, doc["state"])
            lines += [f"run-delivery: this session is {lane} of delivery {c.delivery}, on story {story}.",
                      f"- delivery: {c.delivery}", f"- story: {story}", f"- lane brief: {c.lane_brief.as_posix()}",
                      f"- next lane command: {lane_next(c, doc['state'], story)}"]
            continue
        lines += [f"run-delivery: this session leads delivery {c.delivery}.", f"- delivery: {c.delivery}",
                  f"- stage: {delivery_stage(doc['state'])}", f"- Needs you: {needs_count(c)}"]
        needed = listener_needed(doc["state"])
        lease = lead_listener(c.state)
        if needed and lease is None:
            lines.append(f"- lead-wait: none listens while {', '.join(needed)}; start this in the background before "
                         f"you end your turn: {lead_wait_command(c, doc)}")
        elif needed:
            lines.append(f"- lead-wait: listening (pid {lease['pid']})")
    return "\n".join(lines)[:ORIENT_LIMIT]


def delivery_orient(payload: dict) -> dict:
    """delivery.orient: tell a starting, resumed, cleared, compacted or forked session its role and next command.
    It only ever allows; under mode off it says nothing."""
    seat = seat_of(payload)
    if seat is None or hook_mode(seat.configs[0].flow_raw, "delivery.orient") == "off":
        return {"verdict": "allow"}
    return {"verdict": "allow", "context": orientation(seat)}


HOOKS = {"lead-may-stop": lead_may_stop, "delivery-orient": delivery_orient}


def hook(args) -> None:
    """`hook <name>`: one hook's neutral verdict for the host payload on stdin, as one JSON object."""
    try:
        payload = json.loads(sys.stdin.buffer.read().decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        payload = None
    verdict = HOOKS[args.name](payload if isinstance(payload, dict) else {})
    print(json.dumps(verdict, ensure_ascii=False))


# "Needs you": derived each pass from live conditions, never stored.

def full_health_entries(c) -> list[dict]:
    """The full-health log: `result` entries, the lead's `rerun` entries, and what the close-out saw of the posture: a
    `skipped` entry, which has no `result` so nothing can read it as one, and a `posture` entry, for a change or a named
    code. Read by path, since the plan's producer also runs for a delivery that isn't the configured one."""
    path = c.flow_log / f"{c.delivery}.full-health.jsonl"
    entries = [json.loads(line) for line in path.read_text().splitlines() if line.strip()] if path.exists() else []
    return carried_with_peers(Path(c.flow_log), c.delivery, "full-health", entries)


def latest_close_out(entries: list[dict]) -> dict | None:
    """The latest entry that says what the close-out did or saw. A rerun request isn't one."""
    return next((e for e in reversed(entries) if e.get("result") or e.get("skipped") or e.get("posture")), None)


def full_health_skip(c) -> dict | None:
    """The skip the close-out stands on, if its latest word is one."""
    latest = latest_close_out(full_health_entries(c))
    return latest if latest and latest.get("skipped") else None


def full_health_results(c, head: str) -> tuple[dict | None, bool]:
    """(the latest fullHealth result at this base head, whether the lead asked for a rerun after it)."""
    entries = read_log("full-health", c.delivery)
    results = [e for e in entries if e.get("head") == head and e.get("result")]
    last = results[-1] if results else None
    found = shared_seat(c)
    if found is not None:
        # On a shared record the rerun is the journal's, from any seat: it names the `at` of the result it reruns,
        # copied from the carried result, so no clocks of two machines are compared (D21).
        return last, last is not None and any(
            e["kind"] == "fullhealth.rerun" and e["data"].get("head") == head and e["data"].get("at") == last["at"]
            for e in found[1])
    rerun = last is not None and any(e.get("rerun") and e.get("head") == head and e["at"] > last["at"] for e in entries)
    return last, rerun


# What holds the close and asks the lead: a blocker someone recorded, or the queue's hold on serving.
HOLDING_KINDS = ("blocker.recorded", "serving.held", "deferral.breached")


def runner_held(entry: dict) -> bool:
    """Whether an entry is the queue's hold on serving."""
    return entry["kind"] == "serving.held"


def entry_said(entry: dict) -> str:
    """What an entry says, to show: its kind's line in the registry's words, or its head when the line is empty."""
    try:
        made = tracker_publisher.journal_words.words(entry)
    except tracker_publisher.journal_words.WordsError:
        return entry["kind"]
    return made["line"] or made["head"]


def holding_words(entry: dict) -> str:
    """What a holding entry says, from its facts."""
    if entry["kind"] == "deferral.breached":
        return BREACH.format(finding=entry["data"]["finding"], story=entry.get("subject"), title=entry["data"]["title"])
    return entry["data"].get("why" if entry["kind"] == "serving.held" else "text", "")


def blocker_resolved(c, doc: dict, entry: dict, resolutions: set[int]) -> bool:
    if entry["id"] in resolutions:
        return True
    if runner_held(entry):
        repaired = any(e["kind"] == "base.repaired" and e["id"] > entry["id"] for e in doc["journal"])
        return repaired or not doc["state"]["meta"].get("hold")
    return False


# A running fullHealth's need: the run ending clears it, on a pass of its own.
FULL_HEALTH_RUNNING_CLEARS = "the run ending, or lead-close, which stops it"


def tracker_item(item: dict) -> dict:
    """A tracker "Needs you" item with where it comes from and what clears it: the publisher's lag clears when it
    posts; a ledger line is only shown, and stays."""
    if not item["holding"]:
        return {**item, "source": "tracker ledger", "clears": "nothing: it stays listed for the friction note",
                "kind": "trackerLedger", "who": "lead", "fields": {"detail": item["text"]}}
    return {**item, "source": "tracker publisher", "clears": "the publisher posting those entries on a later pass",
            "kind": "trackerLag", "who": "lead", "fields": {"detail": item["text"]}}


def flapping_blockers(c, flapping: tuple[str, ...]) -> set[int]:
    """The blockers the supervisor journalled for children that flap now: each one's "won't stay up" item stands for it.
    Every other blocker, a suite checkout's or a child's that no longer flaps, shows as any unresolved blocker does."""
    return {number for key, number in json_object(lead_file(c, "supervisor.blockers.json")).items()
            if key.startswith("child:") and key.split(":", 1)[1] in flapping}


def needs_you(c, doc: dict, flapping: tuple[str, ...] = (), closing: bool = False) -> list[dict]:
    """What waits on the lead or the operator, each {holding, source, text, clears}: holding items hold the close;
    shown ones are listed in the friction note. The close condition, the supervisor's pass log and the line map read
    this same list."""
    conf = tracker_conf(c)
    items = [tracker_item(item) for item in
             tracker_publisher.needs_you(doc, c.state, c.flow_log, c.delivery, conf, closing=closing)]
    head = base_head(c)
    running = full_health_running(c)
    if running is not None:
        items.append({"holding": True, "source": "fullHealth", "text": f"{running_words(running)}; the close waits "
                      "for its result", "clears": FULL_HEALTH_RUNNING_CLEARS, "kind": "healthRunning", "who": "lead",
                      "since": running.get("startedAt"), "fields": {"head": str(running.get("head", ""))}})
    last, rerun = full_health_results(c, head) if head else (None, False)
    if last and last["result"] == "failed" and not rerun and delivery_posture(c)["posture"] != "focused":
        items.append({"holding": True, "source": "fullHealth",
                      "text": f"fullHealth failed at {head[:10]}: {last.get('output', '')[-300:]}. It "
                      f"runs again at a later base head, or when you judge it flaky: {flow_command()} lead-resolve "
                      "full-health --why TEXT",
                      "clears": f"a pass at a later base head, or {flow_command()} lead-resolve full-health --why TEXT",
                      "kind": "healthFailed", "who": "lead",
                      "fields": {"head": head, "detail": last.get("output", "")[-300:]}})
    if last and last["result"] == "flaky":
        items.append({"holding": False, "source": "fullHealth",
                      "text": f"fullHealth failed at {head[:10]}, and its failing tests passed alone, so the base isn't "
                      f"broken: {', '.join(last.get('tests', []))}. They are flaky: fix them",
                      "clears": "a fullHealth pass at a later base head", "kind": "healthFlaky", "who": "lead",
                      "fields": {"head": head, "tests": list(last.get("tests", []))}})
    events = [e for e in doc["journal"] if e["kind"] in ("base.broken", "base.repaired")]
    if events and events[-1]["kind"] == "base.broken":
        # A break fullHealth found clears with its next pass; the queue's own break waits for the lead. Under focused no
        # run comes to clear fullHealth's, so, like its failed run, it holds nothing, but it stays listed: serve still
        # waits for base.repaired whatever the posture.
        found = only_full_health_breaks(doc["journal"])
        posture = delivery_posture(c) if found else None
        source = f"journal entry {events[-1]['id']} (base.broken)"
        if posture and posture["posture"] == "focused":
            said = posture_said(posture)
            items.append({"holding": False, "source": source,
                          "text": f"The delivery base is broken: {entry_said(events[-1])[:300]}. It holds nothing "
                          f"while the base declares the focused posture on {said['source']} ({said['reason'][:200]}), "
                          "and serve still waits for base.repaired",
                          "clears": "journalling base.repaired, or a fullHealth pass once the base returns to gate",
                          "kind": "baseFocused", "who": "lead", "since": events[-1].get("at"),
                          "fields": {"detail": entry_said(events[-1])[:300], "source": said["source"]}})
        else:
            items.append({"holding": True, "source": source,
                          "text": f"The delivery base is broken: {entry_said(events[-1])[:300]}. "
                          "Repair it: name a queued candidate as its repair with delivery_state.py repair --subject KEY, "
                          "which serve takes first and alone, or land the fix by hand and journal base.repaired; the "
                          "candidates the break stopped resume on base.repaired, with no --requeue",
                          "clears": ("a fullHealth pass at a later base head, or " if found else "")
                          + "journalling base.repaired", "kind": "baseHealth" if found else "baseBroken", "who": "lead",
                          "since": events[-1].get("at"), "fields": {"detail": entry_said(events[-1])[:300]}})
    items += lane_needs(doc["state"])
    items += regrant_needs(doc["state"])
    for item in doc["state"]["queue"]:
        merge = unaccepted_merge(doc, item)
        if merge:
            items.append({"holding": True, "source": f"journal entry {merge['id']} (candidate.merged)",
                          "text": f"{item['subject']} merged before you accepted it, and its checkout is kept until you decide",
                          "clears": f"{flow_command()} lead-accept {item['subject']}, or {flow_command()} lead-decide "
                          f"--subject {item['subject']} if lead-accept can't take it", "kind": "unaccepted",
                          "who": "lead", "subject": item["subject"], "since": merge.get("at")})
    resolutions = {entry.get("journal") for entry in read_log("resolutions", c.delivery)}
    shown = flapping_blockers(c, flapping)
    for entry in doc["journal"]:
        if entry["kind"] in HOLDING_KINDS and entry["id"] not in shown and not blocker_resolved(c, doc, entry, resolutions):
            runners = runner_held(entry)
            items.append({"holding": True, "source": f"journal entry {entry['id']} ({entry['kind']})",
                          "text": f"Blocker {entry['id']}"
                          + (f" ({entry.get('subject') or entry.get('lane')})" if entry.get("subject") or entry.get("lane")
                             else "") + f": {holding_words(entry)[:300]}. Resolve it with {flow_command()} "
                          f"lead-resolve {entry['id']} --why TEXT",
                          "clears": ("the runner's hold clearing, journalling base.repaired, or " if runners else "")
                          + f"{flow_command()} lead-resolve {entry['id']} --why TEXT",
                          "kind": "runnerHold" if runners else "blocker", "who": "lead", "since": entry.get("at"),
                          **({"subject": entry["subject"]} if entry.get("subject") else {}),
                          **({"lane": entry["lane"]} if entry.get("lane") else {}),
                          "fields": {"entry": entry["id"], "detail": holding_words(entry)[:300]}})
    if (doc["state"].get("meta") or {}).get("collab"):
        # On a shared record, feedback that stops approval holds until the holder of its section settles it.
        for entry in plan_sync.blocking_feedback(doc["journal"]):
            anchor, said = entry["data"]["anchor"], entry["data"]["text"][:300]
            settle = (f"{flow_command()} collab feedback resolve --id {entry['id']} --outcome accepted|declined|answered "
                      "--reason TEXT")
            items.append({"holding": True, "source": f"journal entry {entry['id']} (feedback.raised)",
                          "text": f"Feedback {entry['id']} on {anchor} stops approval: {said}. The holder of its section "
                          f"settles it with {settle}", "clears": settle, "kind": "feedback", "who": "lead",
                          "since": entry.get("at"), "fields": {"entry": entry["id"], "anchor": anchor, "detail": said}})
    needed = listener_needed(doc["state"])
    if needed and lead_listener(c.state) is None:
        listening = listening_words(c, doc["state"])
        items.append({"holding": False, "source": f"{LEAD_WAIT_LEASE} in the record", **listening, "kind": "listener",
                      "who": "lead", "fields": {"detail": listening["text"]}})
    for name in flapping:
        items.append({"holding": True, "source": f"the supervisor's {name}", "clears": f"the {name} staying up",
                      "text": f"The supervisor's {name} won't stay up; its log is "
                      f"{lead_file(c, f'supervisor.{name}.log')}", "kind": "flapping", "who": "lead",
                      "fields": {"name": name, "log": str(lead_file(c, f'supervisor.{name}.log'))}})
    if c.forge.get("mergeNeedsReady") and not authority().get("readyPullRequests"):
        drafts = [item["subject"] for item in doc["state"]["queue"] if item["stage"] != "merged" and not item.get("pending")
                  and not any(a.get("ready") for a in read_log("acceptance", item["subject"]))]
        if drafts:
            items.append({"holding": True, "source": "acceptance", "text": f"Accepted as drafts while the merge step "
                          f"refuses drafts: {', '.join(drafts)}. Mark each ready, then lead-accept --requeue it if it "
                          "stopped", "clears": "marking each ready, then lead-accept --requeue for one that stopped",
                          "kind": "drafts", "who": "operator", "fields": {"subjects": drafts}})
    if decision_owed(c, doc) and not open_work(c, doc):
        stub = friction_stub_path(c)
        items.append({"holding": True, "source": COMPOUNDING_SOURCE,
                      "text": f"The compound-learning decision: write up the friction stub {stub} (the supervisor "
                      "writes it once nothing else holds the close), run compound-learning on it, and record its "
                      f"decision with {flow_command()} lead-compound",
                      "clears": f"{flow_command()} lead-compound --required --ref REF, or --not-required --why TEXT",
                      "kind": "compounding", "who": "lead", "fields": {"stub": str(stub)}})
    items += lane_change_needs(c, doc["state"])
    items += record_needs(doc, items)
    return say_needs(c, doc, items + waits_needing(c, doc, items))


COMPOUNDING_SOURCE = "compound-learning"


def lane_named(lane: str) -> str:
    """A lane as a sentence names it: lane-1 is "lane 1"; a lane with another name is called by it."""
    numbered = re.fullmatch(r"lane-([0-9]+)", lane)
    return f"lane {numbered.group(1)}" if numbered else lane


def listening_words(c, state: dict) -> dict:
    """The "Needs you" item's text and what clears it while no lead-wait runs, from the table of wait sentences: the
    lanes still at work, by name. The lead's own status line keeps the command that starts one."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    table = delivery_state.load_wait_words()
    lanes = [lane_named(lane) for lane in listener_facts(state)["lanes"]]
    # The first lane starts the sentence.
    lanes = [lane[:1].upper() + lane[1:] for lane in lanes[:1]] + lanes[1:]
    return {"text": delivery_state.wait_said(table, "listening", "text", {"lanes": lanes, "count": len(lanes)}),
            "clears": delivery_state.wait_said(table, "listening", "clears", {})}


# Who a lane's question can wait on, besides the lead and another lane: the operator, by the names a lane gives them.
OPERATOR_NAMES = ("operator", "user", "you")


def lane_story(state: dict, lane: str) -> dict | None:
    """The story a lane is on: its piece still being built or reviewed, else its latest piece not yet landed."""
    planned = [p for p in state.get("planned", []) if p.get("lane") == lane and p["stage"] in ("building", "review")]
    queued = [q for q in state["queue"] if q["stage"] != "merged"
              and (q.get("assignedLane", q.get("lane")) if q["stage"] == "stopped" else q.get("lane")) == lane]
    found = planned or queued
    return found[-1] if found else None


def lane_needs(state: dict) -> list[dict]:
    """The lanes "Needs you" lists: one blocked on a question, and one waiting on the lead. A lane in the `waiting`
    state waits on a story, which goes on by itself when it lands, so it is not listed. Each names who must act: the
    lead, the operator, or another lane, as the lane's `waitingOn` says."""
    items = []
    lanes = {lane["id"] for lane in state["lanes"]}
    for lane in state["lanes"]:
        on = str(lane.get("waitingOn") or "")
        who = "operator" if on.lower() in OPERATOR_NAMES else on if on in lanes else "lead"
        story = lane_story(state, lane["id"])
        facts = {"who": who, "lane": lane["id"], "since": lane.get("since") or lane.get("focusAt"),
                 **({"subject": story["subject"]} if story else {}), "fields": {"focus": lane.get("focus", "")}}
        if lane.get("state") == "blocked":
            items.append({"holding": True, "source": f"{lane['id']}'s state", "clears": "the lane's state changing",
                          "text": f"{lane['id']} is blocked: {lane.get('focus', '')}", "kind": "laneBlocked", **facts})
        elif lane.get("waitingOn") == "lead":
            items.append({"holding": True, "source": f"{lane['id']}'s state", "clears": "the lane no longer waiting on you",
                          "text": f"{lane['id']} waits on you: {lane.get('focus', '')}", "kind": "laneAsks", **facts})
    return items


def record_needs(doc: dict, named: list[dict]) -> list[dict]:
    """What the record itself shows needs someone, which no item in ``named`` says: serving paused, a stopped piece, a
    source's report, and a source that stopped answering. None of these holds the close."""
    state = doc["state"]
    meta = state.get("meta") or {}
    items = []
    if isinstance(meta.get("hold"), dict) and not any(item.get("kind") == "runnerHold" for item in named):
        reason = str(meta["hold"].get("reason") or "")
        items.append({"holding": False, "source": "the record's hold", "text": f"Serving is paused: {reason}",
                      "clears": "the lead lifting the hold", "kind": "paused", "who": "lead",
                      "since": meta["hold"].get("at"), "fields": {"reason": reason}})
    for item in state["queue"]:
        if item["stage"] != "stopped":
            continue
        stops = [e for e in doc["journal"] if e["kind"] == "candidate.stopped" and e.get("subject") == item["subject"]]
        failed = [f"{check.get('title') or check.get('id')} {'timed out' if check.get('state') == 'timed_out' else 'failed'}"
                  for check in item.get("checks") or [] if isinstance(check, dict)
                  and check.get("state") in ("failed", "timed_out")]
        detail = "; ".join(failed) or (entry_said(stops[-1]) if stops else "")
        items.append({"holding": False, "source": f"journal entry {stops[-1]['id']} (candidate.stopped)" if stops
                      else f"{item['subject']} in the queue", "text": f"{item['subject']} stopped: {detail}",
                      "clears": f"{item['subject']} put back, landing or settling", "kind": "stopped", "who": "lead",
                      "subject": item["subject"], "since": stops[-1].get("at") if stops else None,
                      "fields": {"detail": detail}})
    for report in meta.get("sourceReports") or []:
        if isinstance(report, dict):
            note, about = str(report.get("note") or ""), str(report.get("subject") or "")
            items.append({"holding": False, "source": "a source's report", "text": f"{about or 'For the lead'}: {note}",
                          "clears": "the report leaving the record", "kind": "report", "who": "lead",
                          "since": report.get("at"), "fields": {"about": about, "detail": note}})
    for name, source in sorted((meta.get("sources") or {}).items()):
        if isinstance(source, dict) and source.get("status") == "stale":
            reason = str(source.get("reason") or "")
            items.append({"holding": False, "source": f"the {name} source", "text": f"The {name} is not answering: {reason}",
                          "clears": f"the {name} answering again", "kind": "stale", "who": "lead",
                          "since": source.get("lastReadAt"), "fields": {"name": name, "reason": reason}})
    return items


# What a row of "Needs you" is said in, beside its facts: from the table of wait sentences, by the item's kind.
NEED_WORDS = ("headline", "why", "clears", "who")


def say_needs(c, doc: dict, items: list[dict]) -> list[dict]:
    """Each item with its facts filled from the record and its row's words from the table of wait sentences: the
    lane its story is on, the story's state, the story it waits on with that one's lane and state, and the headline,
    why, what clears it and who acts. An item's `text`, which the close and the friction note read, is unchanged."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    table = delivery_state.load_wait_words()
    state = doc["state"]
    pieces = {item["subject"]: item for item in [*state["queue"], *state.get("planned", [])]}
    lane_of = lambda piece: piece.get("assignedLane", piece.get("lane")) if piece.get("stage") == "stopped" else piece.get("lane")
    found = delivery_state.waits(doc, needing={name for item in items for name in needs_about(doc, item)}, words=table)
    said = []
    for item in items:
        item = {key: value for key, value in item.items() if value is not None}
        # A field with nothing to say is left out, so the bracketed part that names it is too.
        fields = {name: value for name, value in item.pop("fields", {}).items() if value not in ("", None, [])}
        piece = pieces.get(item.get("subject")) or {}
        if piece:
            item.setdefault("lane", lane_of(piece))
            item["state"] = piece["stage"]
        wait = next((w for w in found if w["subject"] == item.get("subject") and w["on"] in pieces), None)
        if wait:
            on = pieces[wait["on"]]
            item["blocker"] = {"subject": wait["on"], "state": on["stage"], **({"lane": lane_of(on)} if lane_of(on) else {})}
        kind, who = item.get("kind", "other"), item.get("who", "lead")
        words = {**fields, **{name: item[name] for name in ("lane", "subject") if item.get(name)}, "kind": kind,
                 "who": who, "whom": delivery_state.wait_said(table, "needsYou", "whom", {"who": who})}
        item["said"] = {name: delivery_state.wait_said(table, "needsYou", name, words) for name in NEED_WORDS}
        if item.get("waiting"):
            count = delivery_state.wait_said(table, "needsYou", "count", {"count": item.pop("waiting")})
            item["said"]["why"] = f"{item['said']['why']} {count}".strip()
        said.append(item)
    return said


def needs_words(c) -> dict:
    """The words "Needs you" is laid out in, beside its rows' own: its heading, a holding row's mark, and the form of a
    row's age, whose {age} the page fills."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    table = delivery_state.load_wait_words()
    return {"heading": delivery_state.wait_said(table, "needsYou", "heading", {}),
            "holding": delivery_state.wait_said(table, "needsYou", "holding", {}),
            "age": table["needsYou"]["templates"]["age"]}


def needs_summary(c, items: list[dict]) -> str:
    """The sentence "Needs you" opens with: how many items wait on whom, the operator first, and how many of them hold
    up the finish, from the table of wait sentences."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    table = delivery_state.load_wait_words()
    if not items:
        return delivery_state.wait_said(table, "needsYou", "summary", {"shape": "empty", "parts": [], "holding": 0})
    whom: dict[str, int] = {}
    for item in sorted(items, key=lambda item: item.get("who") != "operator"):
        whom[item.get("who", "lead")] = whom.get(item.get("who", "lead"), 0) + 1
    parts = [delivery_state.wait_said(table, "needsYou", "part", {
        "count": count, "whom": delivery_state.wait_said(table, "needsYou", "whom", {"who": who})}) for who, count in whom.items()]
    holding = sum(1 for item in items if item["holding"])
    shape = ("none" if not holding else "it" if len(items) == 1 else "all" if holding == len(items)
             else "one" if holding == 1 else "some")
    return delivery_state.wait_said(table, "needsYou", "summary", {"shape": shape, "parts": parts, "holding": holding})


def busy_lanes(state: dict) -> list[str]:
    """The lanes that hold the close: any not idle or done, except one waiting on a story, which goes on by itself."""
    return [lane["id"] for lane in state["lanes"] if lane.get("state") not in (*LANE_DONE, "waiting")]


def needs_about(doc: dict, item: dict) -> set[str]:
    """The lanes and stories a "Needs you" item is about, read from where it comes from."""
    source = item["source"]
    if item.get("subject") and item.get("kind") == "stopped":
        return {item["subject"]}
    if source.endswith("'s state"):
        return {source[:-len("'s state")]}
    found = re.match(r"journal entry ([0-9]+) ", source)
    if not found:
        return set()
    entry = next((e for e in doc["journal"] if e["id"] == int(found.group(1))), None) or {}
    return {name for name in (entry.get("subject"), entry.get("lane")) if name}


def waits_needing(c, doc: dict, items: list[dict]) -> list[dict]:
    """What the record's waits add to "Needs you", only where someone has to act: the item for a piece that others wait
    on and that needs someone gains how many wait on it, a stopped piece no item names gets one, and a planned story
    nothing holds on an idle lane is free to start. None of these holds the close. Changes ``items`` in place, and
    returns the items it adds."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    about = [needs_about(doc, item) for item in items]
    found = delivery_state.waits(doc, needing={name for names in about for name in names})
    table = delivery_state.load_wait_words()
    lanes = {row["id"] for row in doc["state"]["lanes"]}
    pieces = {item["subject"]: item for item in [*doc["state"]["queue"], *doc["state"].get("planned", [])]}
    counted: dict[str, list[str]] = {}
    # A lane's own wait counts; one that repeats its next story's wait doesn't.
    for wait in found:
        mirror = wait["subject"] in lanes and wait["cause"] != "lane"
        if wait["needsSomeone"] and not mirror and wait["subject"] not in counted.get(wait["on"], []):
            counted.setdefault(wait["on"], []).append(wait["subject"])
    added = []
    for on, waiting in counted.items():
        count = delivery_state.wait_said(table, "needsYou", "count", {"count": len(waiting)})
        piece = pieces.get(on) or {}
        lane = piece.get("assignedLane", piece.get("lane")) if piece.get("stage") == "stopped" else piece.get("lane")
        named = next((item for item, names in zip(items, about) if on in names), None) \
            or next((item for item, names in zip(items, about) if lane and lane in names), None)
        if named is not None:
            named["text"] = f"{named['text'].rstrip()} {count}"
            named["waiting"] = len(waiting)
        elif piece.get("stage") == "stopped":
            added.append({"holding": False, "source": f"{on}'s waits", "clears": f"{on} put back, landing or settling",
                          "text": delivery_state.wait_said(table, "needsYou", "stopped", {"subject": on}) + " " + count,
                          "kind": "stopped", "who": "lead", "subject": on, "waiting": len(waiting), "fields": {"detail": ""}})
    for wait in found:
        # An after key that neither a story here nor any sibling holds, with every sibling read fresh: the lead adds the
        # sibling or fixes the key. It names no piece of this record, so no other item can carry it.
        if (wait["cause"] == "sibling" and wait["needsSomeone"] and wait["subject"] not in lanes
                and wait["on"] not in pieces):
            added.append({"holding": False, "source": f"{wait['subject']}'s waits", "text": wait["words"],
                          "clears": f"a sibling listing {wait['on']}, or {wait['subject']}'s after key changing",
                          "kind": "sibling", "who": "lead", "subject": wait["subject"], "fields": {"on": wait["on"]}})
    for free in delivery_state.free_to_start(doc, [*found, *peer_waits_said(c)], words=table):
        # A story free to start is in "Needs you" itself, so what waits on it is counted on its item.
        waiting = list(dict.fromkeys(wait["subject"] for wait in found
                                     if wait["on"] == free["subject"] and (wait["subject"] not in lanes or wait["cause"] == "lane")))
        said = free["words"] + (" " + delivery_state.wait_said(table, "needsYou", "count", {"count": len(waiting)})
                                if waiting else "")
        added.append({"holding": False, "source": f"{free['subject']}'s waits", "text": said,
                      "clears": f"{free['subject']} assigned, held, or waiting again", "kind": "free", "who": "lead",
                      "subject": free["subject"], **({"lane": free["lane"]} if free.get("lane") else {}),
                      **({"waiting": len(waiting)} if waiting else {})})
    return added


# What each lane has pushed. A pass reads every assigned lane's story branch on the remote, as a diff from its merge
# base with the delivery base, and writes what it changed beside the record: "Needs you" names a change outside the
# lane's ground from it, and the line map's files view draws it. It refuses nothing; acceptance still decides.
LANE_CHANGES_FILE = "lane-changes.json"
LANE_CHANGES_SPEC = "delivery-lane-changes/1"
# The diff a branch read takes: the one region_ownership.hunks takes, so a change's old lines are the hunks it checks.
LANE_DIFF = ("diff", "--text", "--no-ext-diff", "--no-textconv", "--no-color", "--no-renames", "--no-indent-heuristic",
             "--inter-hunk-context=0", "--unified=0", "--diff-algorithm=myers")
LANE_HUNK = re.compile(r"^@@ -([0-9]+)(?:,([0-9]+))? \+([0-9]+)(?:,([0-9]+))? @@", re.M)
# The line that names where a change sits, on the new side: the nearest `def` or `class` in Python, `function` or
# `const NAME =` in JavaScript, and a heading in Markdown.
ENCLOSING_NAMES = {
    "python": re.compile(r"^\s*(?:async\s+)?(?:def|class)\s+([A-Za-z_][A-Za-z0-9_]*)"),
    "javascript": re.compile(r"^\s*(?:export\s+(?:default\s+)?)?(?:async\s+)?function\s*\*?\s*([A-Za-z_$][A-Za-z0-9_$]*)"
                             r"|^\s*(?:export\s+)?const\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*="),
    "markdown": re.compile(r"^#{1,6}\s+(.*?)\s*#*\s*$"),
}
ENCLOSING_KINDS = {".py": "python", ".js": "javascript", ".mjs": "javascript", ".cjs": "javascript",
                   ".jsx": "javascript", ".ts": "javascript", ".tsx": "javascript", ".md": "markdown"}
# The files view's own bound: past it the claimed files are cut, and the cut is said.
LANE_FILES_LIMIT = 400


def enclosing_name(path: str, lines: list[str], line: int) -> str | None:
    """The name of the block line `line` (one-based) sits in, on the new side: the line itself when it names one, else
    the nearest one above it. In Python and JavaScript, the nearest one indented less than the code it holds, so a
    sibling's nested function above is passed over; in Markdown, the nearest heading."""
    kind = ENCLOSING_KINDS.get(os.path.splitext(path)[1].lower())
    if kind is None or not lines:
        return None
    pattern = ENCLOSING_NAMES[kind]

    def named(text: str) -> str | None:
        found = pattern.match(text)
        return next((group for group in found.groups() if group), None) if found else None

    index = min(max(line, 1), len(lines)) - 1
    if named(lines[index]):
        return named(lines[index])
    if kind == "markdown":
        return next((named(text) for text in reversed(lines[:index]) if named(text)), None)
    indent = lambda text: len(text) - len(text.lstrip())
    below = indent(lines[index]) if lines[index].strip() else None
    for text in reversed(lines[:index]):
        if not text.strip():
            continue
        if below is None or indent(text) < below:
            if named(text):
                return named(text)
            below = indent(text)
    return None


def read_lane_branch(c, story: str, base: str) -> dict | None:
    """One lane's story branch as the remote holds it, read as a diff from its merge base with `base`: its head, that
    merge base, and per changed file each change's old first line and size, new first line and size, and enclosing
    name. None when the branch isn't pushed. A branch that can't be read says why, with no files."""
    branch = c.branch(story)
    said = {"story": story, "branch": branch}
    listed = run(["git", "ls-remote", c.remote, f"refs/heads/{branch}"], cwd=c.root, check=False)
    if listed.returncode != 0:
        return {**said, "unreadable": f"git ls-remote failed: {(listed.stderr or listed.stdout).strip()[-300:]}"}
    if not listed.stdout.strip():
        return None
    head = listed.stdout.split()[0]
    said.update(head=head, base=base)
    try:
        run(["git", "fetch", "-q", "--no-write-fetch-head", c.remote, f"+refs/heads/{branch}:refs/remotes/{c.remote}/{branch}"],
            cwd=c.root)
        merge_base = git("merge-base", base, head, cwd=c.root)
        paths = list(filter(None, run(["git", "diff", "--name-only", "--no-renames", "-z", merge_base, head],
                                      cwd=c.root).stdout.split("\0")))
        files = []
        for path in paths:
            # Not strictly decoded: a binary or non-UTF-8 file is still a change the read reports, by its hunks.
            patch = run(["git", *LANE_DIFF, merge_base, head, "--", path], cwd=c.root, errors="replace").stdout
            shown = run(["git", "show", f"{head}:{path}"], cwd=c.root, check=False, errors="replace")
            text = shown.stdout.splitlines() if shown.returncode == 0 and "\0" not in shown.stdout else []
            changes = []
            for match in LANE_HUNK.finditer(patch):
                first, removed, start, added = (int(n) if n is not None else 1 for n in match.groups())
                changes.append({"old": first if removed else first + 1, "removed": removed,
                                "start": start if added else start + 1, "added": added,
                                "name": enclosing_name(path, text, start if added else start)})
            files.append({"path": path, "changes": changes})
    except (Stop, UnicodeError) as error:
        return {**said, "unreadable": str(error)[-300:]}
    return {**said, "mergeBase": merge_base, "readAt": now(), "files": files}


def lane_holdings(c, lane: str, read: dict, state: dict) -> dict:
    """The read with what the lane holds of each file, by the ownership acceptance uses: `holds` is "file", "span",
    "shared" or "none", and each change is `inside` the lane's ground or not. On a file the lane holds by span, a change
    outside its spans is outside, with the file still "span"; a file it can't change by span at all is "none"."""
    if "files" not in read:
        return read
    helper = _region_ownership()
    _, outside = candidate_ownership(c, lane, read["mergeBase"], read["head"], state)
    regions = state.get("laneRegions", [])
    shared = shared_outputs(c) if "laneOwnership" in state else set()
    files = []
    for entry in read["files"]:
        path = entry["path"]
        refused = path in outside or any(item.startswith(f"{path}: ") for item in outside)
        changes = [dict(change, inside=not refused) for change in entry["changes"]]
        holds = "shared" if path in shared else "span" if any(claim["path"] == path for claim in regions) else "file"
        if refused and holds == "span" and not any(claim["path"] == path and claim["lane"] == lane for claim in regions):
            holds = "none"  # other lanes share it by span, and this lane holds none of it
            changes = [dict(change, inside=False) for change in changes]
        elif refused and holds == "span":
            spans = []
            for claim in regions:
                if claim["path"] == path and claim["lane"] == lane:
                    with contextlib.suppress(helper.RegionError):
                        spans.append(helper.mapped(c.root, claim, read["mergeBase"]))
            theirs = [claim for claim in regions if claim["path"] == path and claim["lane"] != lane]
            known: list = []
            foreign = lambda: known or known.extend(helper.foreign_spans(c.root, theirs, read["mergeBase"])) or known
            try:
                # What no span can hold, as acceptance's check refuses it: a creation, a deletion, a type, mode or
                # binary change.
                old_mode, _ = helper.entry(c.root, read["mergeBase"], path)
                new_mode, _ = helper.entry(c.root, read["head"], path)
                helper.require_text(c.root, read["head"], path)
                whole = old_mode != new_mode
                size = len(helper.text_lines(c.root, read["mergeBase"], path))
            except helper.RegionError:
                whole, size = True, 0
            for change in changes:
                # Decision 4: an insertion at a span's edge is the span's unless another lane claims the far side.
                held, _ = helper.held_by(change["old"], change["removed"], spans, size, foreign)
                change["inside"] = held is not None
            # Refused for the file itself, or with no span that maps (a claim needing a regrant), or with every
            # change inside: the lane can't change this file by span, so it is held as no file is.
            if whole or not spans or not changes or all(change["inside"] for change in changes):
                holds = "none"
                changes = [dict(change, inside=False) for change in changes]
        elif refused:
            holds = "none"
        files.append({"path": path, "holds": holds, "changes": changes})
    return {**read, "files": files}


def claimed_files(c, state: dict, base: str) -> dict:
    """The delivery's claimed files at `base`, for the files view: each tracked file a lane's whole-file claim names,
    and each file region claims share, with every claim's span mapped to `base` and the file's length there. A span
    that no longer maps keeps its granted lines and says it needs a regrant."""
    helper = _region_ownership()
    ownership = c.effective_ownership(state)
    regions = state.get("laneRegions", [])
    tracked = git("ls-tree", "-r", "--name-only", base, cwd=c.root, check=False).splitlines()
    regional = sorted({claim["path"] for claim in regions})
    whole = [path for path in tracked if path not in regional and owners_of(ownership, path)]
    files = []
    for path in regional + whole:
        if len(files) >= LANE_FILES_LIMIT:
            break
        shown = run(["git", "show", f"{base}:{path}"], cwd=c.root, check=False)
        length = len(shown.stdout.splitlines()) if shown.returncode == 0 else 0
        if path in regional:
            spans = []
            for claim in regions:
                if claim["path"] != path:
                    continue
                try:
                    start, end = helper.mapped(c.root, claim, base)
                    spans.append({"lane": claim["lane"], "start": start, "end": end})
                except helper.RegionError:
                    spans.append({"lane": claim["lane"], "start": claim["start"], "end": claim["end"], "regrant": True})
            files.append({"path": path, "lines": length, "spans": sorted(spans, key=lambda span: span["start"])})
        else:
            files.append({"path": path, "lines": length, "lanes": owners_of(ownership, path)})
    return {"files": files, **({"more": len(regional) + len(whole) - len(files)}
                               if len(regional) + len(whole) > len(files) else {})}


def read_lane_changes(folder: Path) -> dict | None:
    """The last pass's lane-changes.json, or None when there is none or it can't be read."""
    try:
        written = json.loads((folder / LANE_CHANGES_FILE).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return None
    return written if isinstance(written, dict) and written.get("spec") == LANE_CHANGES_SPEC else None


def write_lane_changes(c) -> str:
    """Read every assigned lane's pushed story branch and write lane-changes.json beside the record. A branch at the
    same base and head as the last pass's read is not read again: its read, with its read time, is kept, and only
    what the lane holds is judged afresh, so a grant shows at once."""
    doc = load_state()
    state = doc["state"]
    base = git("rev-parse", "--verify", f"{c.base_ref}^{{commit}}", cwd=c.root)
    last = (read_lane_changes(c.state) or {}).get("lanes") or {}
    lanes = {}
    for lane in state["lanes"]:
        story = lane_story(state, lane["id"])
        if story is None:
            continue
        earlier = last.get(lane["id"]) if isinstance(last.get(lane["id"]), dict) else {}
        read = None
        if earlier.get("story") == story["subject"] and earlier.get("base") == base and "files" in earlier:
            listed = run(["git", "ls-remote", c.remote, f"refs/heads/{earlier['branch']}"], cwd=c.root, check=False)
            if listed.returncode == 0 and listed.stdout.split()[:1] == [earlier.get("head")]:
                with contextlib.suppress(KeyError, TypeError):  # a read this release can't take is read again
                    kept = {name: earlier[name] for name in ("story", "branch", "head", "base", "mergeBase", "readAt")}
                    kept["files"] = [{"path": f["path"], "changes": [{name: change[name] for name in
                                                                      ("old", "removed", "start", "added", "name")}
                                                                     for change in f["changes"]]} for f in earlier["files"]]
                    read = kept
        if read is None:
            read = read_lane_branch(c, story["subject"], base)
        if read is None:
            continue
        try:
            lanes[lane["id"]] = lane_holdings(c, lane["id"], read, state)
        except Stop as error:
            lanes[lane["id"]] = {name: read[name] for name in ("story", "branch", "head", "base") if name in read} | {
                "unreadable": str(error)[-300:]}
    written = {"spec": LANE_CHANGES_SPEC, "at": now(), "base": base, "lanes": lanes,
               **(claimed_files(c, state, base) if state.get("laneRegions") else {})}
    path = c.state / LANE_CHANGES_FILE
    staging = path.with_name(f".{LANE_CHANGES_FILE}.{os.getpid()}")
    staging.write_text(json.dumps(written, indent=2) + "\n")
    with open(c.state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            os.replace(staging, path)
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)
    return f"{len(lanes)} branch(es)"


def lines_said(first: int, count: int) -> str:
    return f"line {first}" if count <= 1 else f"lines {first}-{first + count - 1}"


def lane_change_needs(c, state: dict) -> list[dict]:
    """The "Needs you" items the last branch read raises, none of them holding the close: a changed file its lane
    doesn't hold, each change outside the spans of a file it holds by span, naming the lines, and a branch that can't
    be read, in place of that lane's items. A declared shared output, and a change inside a span, raise nothing."""
    written = read_lane_changes(c.state)
    if written is None:
        return []
    assigned = {lane["id"] for lane in state["lanes"]}
    items = []
    for lane, read in sorted((written.get("lanes") or {}).items()):
        if lane not in assigned or not isinstance(read, dict):
            continue
        named = lane_named(lane)
        named = named[:1].upper() + named[1:]
        facts = {"holding": False, "who": "lead", "lane": lane, "subject": read.get("story")}
        if "unreadable" in read:
            items.append({**facts, "source": f"{lane}'s branch {read.get('branch')}", "kind": "laneUnreadable",
                          "text": f"{named}'s branch `{read.get('branch')}` can't be read: {str(read['unreadable'])[:300]}",
                          "clears": "a pass that reads the branch",
                          "fields": {"branch": read.get("branch"), "detail": str(read["unreadable"])[:300]}})
            continue
        for entry in read.get("files") or []:
            path, changes = entry["path"], entry.get("changes") or []
            source = f"{lane}'s branch {read.get('branch')} at {str(read.get('head'))[:10]}"
            if entry.get("holds") == "none":
                items.append({**facts, "source": source, "kind": "laneOutside",
                              "text": f"{named} changed `{path}`, which it doesn't hold.",
                              "clears": "the branch no longer changing it, or the lead granting the file",
                              "fields": {"path": path, "detail": "It doesn't hold the file."}})
                continue
            for change in changes:
                if change.get("inside", True):
                    continue
                # Named by the merge base's lines, which the span check judged and a grant names.
                lines = (lines_said(change["old"], change["removed"]) if change["removed"]
                         else f"before line {change['old']}")
                said = (f"changed {lines}" if change["removed"]
                        else f"added {change['added']} line{'s' if change['added'] != 1 else ''} {lines}")
                items.append({**facts, "source": source, "kind": "laneOutside",
                              "text": f"{named} {said} of `{path}`, outside its span.",
                              "clears": "the branch no longer changing those lines, or the lead granting them",
                              "fields": {"path": path, "lines": lines, "detail": f"It {said}, outside its span."}})
    return items


NEEDS_FILE = "needs-you.json"


def write_needs(c, items: list[dict] | None, number: int, started: float) -> None:
    """Replace the record's "Needs you" list, which renderers read: this pass's items, or, with None, the word that
    the supervisor isn't running. A running list is stale once one pass is overdue: after the pass interval and once
    more the longer of that interval and this pass's own time so far."""
    at = datetime.datetime.now(datetime.timezone.utc)
    written: dict = {"spec": "delivery-needs-you/1", "running": items is not None, "pass": number,
                     "at": at.strftime("%Y-%m-%dT%H:%M:%SZ"), "items": items or []}
    if items is not None:
        # The list's own words, from the table of wait sentences: its heading, the sentence it opens with, the mark a
        # holding row carries, and the age column's form, whose {age} the page fills as it ticks.
        written["summary"] = needs_summary(c, items)
        written["words"] = needs_words(c)
        interval = supervisor_pass_seconds(c)
        stale = at + datetime.timedelta(seconds=interval + max(interval, time.monotonic() - started))
        written["staleAfter"] = stale.strftime("%Y-%m-%dT%H:%M:%SZ")
    path = c.state / NEEDS_FILE
    staging = path.with_name(f".{NEEDS_FILE}.{os.getpid()}")
    staging.write_text(json.dumps(written, indent=2) + "\n")
    with open(c.state / "state.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            os.replace(staging, path)
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


PEER_WAITS_FILE = "peer-waits.json"


def peer_waits_said(c) -> list[dict]:
    """This delivery's waits on its peers as the views say them: the last write's, while it is fresh. A pass writes
    them before it derives "Needs you", so a story the views say waits on another delivery is never free to start. A
    context with no record folder has none."""
    if getattr(c, "state", None) is None:
        return []
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import render_state
    said = render_state.fresh_peer_waits(c.state)
    return said["waits"] if said else []


def write_peer_waits(c, lasting: float = 0) -> str:
    """Replace the record's waits on the other deliveries on its base, and theirs on it, which renderers add to the
    record's own while the file is fresh: from the registry, each peer's claims and planned files, and the merge
    slot's holder and waiter files, as `delivery_state.peer_waits` derives them. Stale, like "Needs you", once one
    pass is overdue, or ``lasting`` seconds on when that is later."""
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    peers = [{"key": peer["key"], "state": json_object(Path(peer["state"]) / "state.json")}
             for peer in peer_deliveries(c) if peer["status"] != "unreadable"]
    try:
        slot = delivery_state.slot_parties(delivery_state.merge_slot_path(c.root, c.base_branch))
    except delivery_state.StateError:
        slot = {"holder": None, "waiters": []}
    document = load_state()
    if not isinstance(document.get("state"), dict):
        return "skipped: the record has no state to derive from"
    found = delivery_state.peer_waits(document, c.delivery, peers, slot)
    at = datetime.datetime.now(datetime.timezone.utc)
    interval = supervisor_pass_seconds(c)
    written = {"spec": "delivery-peer-waits/1", "at": at.strftime("%Y-%m-%dT%H:%M:%SZ"),
               "staleAfter": (at + datetime.timedelta(seconds=max(2 * interval, lasting))).strftime(
                   "%Y-%m-%dT%H:%M:%SZ"), **found}
    path = c.state / PEER_WAITS_FILE
    staging = path.with_name(f".{PEER_WAITS_FILE}.{os.getpid()}")
    staging.write_text(json.dumps(written, indent=2) + "\n")
    os.replace(staging, path)
    return f"{len(found['waits'])} wait(s) on other deliveries, {len(found['waitedOn'])} on this one"


def say_peer_waits(c, lasting: float) -> None:
    """Write this delivery's waits on its peers for a lead command that parks the supervisor and then waits for the
    merge slot: no pass runs while it waits, so the command says its own wait as it starts, fresh for as long as it may
    wait, and again once it takes the slot, fresh then only until a pass is overdue. A write that fails stops
    nothing."""
    with contextlib.suppress(Stop, ValueError, OSError, KeyError, TypeError, subprocess.SubprocessError):
        write_peer_waits(c, lasting)


def removed_subjects(c) -> set[str]:
    return {key for entry in read_plan_log(c) if entry.get("type") == "change" and entry.get("kind") == "removed"
            and not entry.get("criteria") for key in entry.get("subjects", [])}  # a dropped criterion keeps its story


def close_holds(c, doc: dict, needs: list[dict]) -> list[str]:
    """What holds the close: the close condition, read as the reasons it doesn't hold yet."""
    state = doc["state"]
    holds = open_work(c, doc)
    unmet = [line["id"] for line in state["finish"] if not line.get("met")]
    if unmet:
        holds.append(f"finish lines not met: {', '.join(unmet)}")
    busy = busy_lanes(state)
    if busy:
        holds.append(f"lanes not idle or done: {', '.join(busy)}")
    # A merge can land after the pass's cleanup read the record, and the close ends the passes: it waits for the next
    # pass's cleanup, as it does for a checkout cleanup couldn't remove.
    left = [q["subject"] for q in state["queue"] if q["stage"] == "merged" and q["subject"] in c.stories
            and c.lane_checkout(q["subject"]).exists()]
    # On a shared record a peer's machine keeps its lanes' checkouts, which only it can clean up (D21).
    left += [key for key in peer_checkouts_left(c) if key not in left]
    if left:
        holds.append(f"not cleaned up: {', '.join(left)}")
    if decision_owed(c, doc):
        holds.append(DECISION_HOLD)
    holds += [item["text"] for item in needs if item["holding"] and item["source"] != COMPOUNDING_SOURCE]
    return holds


# The close-out (C6): each step must succeed before the next, and each is skipped once done.

def append_full_health(c, entry: dict) -> str:
    """Append to the full-health log, which is an input of plan.json, and rebuild it. One line on the rebuild."""
    append_log("full-health", c.delivery, entry)
    return rebuild_plan_quietly(c)


def journal_posture(c, kind: str, facts: dict) -> None:
    """A note of the close-out's posture: posture.changed, or fullhealth.skipped, which the registry posts on the epic.
    On a shared record the journal dedupes it, whichever seat wrote the earlier note (D21): a posture.changed is skipped
    when the latest one has the same from, to and source, and a fullhealth.skipped when one stands at the same head."""
    found = shared_seat(c)
    if found is not None:
        same = [e for e in found[1] if e["kind"] == kind]
        if kind == "posture.changed" and same and all(same[-1]["data"].get(field) == facts.get(field)
                                                     for field in ("from", "to", "source")):
            return
        if kind == "fullhealth.skipped" and any(e["data"].get("head") == facts.get("head") for e in same):
            return
    state_tool("journal", "--kind", kind, "--data", json.dumps(facts))


def note_posture(c, posture: dict) -> str | None:
    """Journal what is new about the posture at close-out, once however many passes see it: a change, and a declaration
    that didn't take. Nothing is written for a repository whose gate has nothing to say. Returns the plan's line."""
    code, said = posture["code"], posture_said(posture)
    seen = latest_close_out(full_health_entries(c))
    before = (seen.get("posture") or "gate") if seen else None
    moved = before is not None and before != posture["posture"]
    named = code in ("posture_malformed", "posture_unreadable") and (seen or {}).get("code") != code
    if not (moved or named):
        return None
    if moved:
        journal_posture(c, "posture.changed", {"from": before, "to": posture["posture"], "source": said["source"],
                                              "why": said["reason"]})
    if named:
        # A declaration that didn't take: fullHealth runs as under gate, whatever was declared.
        journal_posture(c, "posture.changed", {"from": before or "gate", "to": "gate", "source": said["source"], "why": f"{code}: {said['reason']}"})
    return append_full_health(c, {"head": posture["baseTipSha"], "code": code, **said})


def record_focused(c, posture: dict) -> str:
    """The close-out under `focused`: no run, and a skip in the log unless a real pass already stands at this head. Once
    per head, source and reason. The first skip is journalled; each later one is the posture change's to say."""
    head, said = posture["baseTipSha"], posture_said(posture)
    with plan_lock(c):
        note_posture(c, posture)
        last, _ = full_health_results(c, head)
        if last and last["result"] == "passed":
            return f"fullHealth passed at {head[:10]}"
        words = (f"fullHealth skipped at {head[:10]} under the {said['posture']} posture declared on {said['source']}, and "
                 f"no run started: {said['reason']}")
        entries = full_health_entries(c)
        latest = latest_close_out(entries)
        rebuilt = ""
        if not (latest and latest.get("skipped") and latest.get("head") == head
                and all(latest.get(key) == said[key] for key in said)):
            if not any(e.get("skipped") for e in entries):
                journal_posture(c, "fullhealth.skipped", {"head": head, "posture": said["posture"],
                                                                 "source": said["source"], "why": said["reason"]})
            rebuilt = append_full_health(c, {"head": head, "skipped": True, **said})
    return words + (f"; {rebuilt}" if "not rebuilt" in rebuilt else "")


def full_health_timeout(binding: dict) -> int:
    """The seconds one fullHealth run may take: the binding's fullHealthTimeoutSeconds, or its checkTimeoutSeconds when
    it sets none. Never checkTimeoutCeiling, which bounds the queue's checks: the post-merge tier is not one of them."""
    return int(binding.get("fullHealthTimeoutSeconds", binding.get("checkTimeoutSeconds", 1800)))


def full_health_break(entry: dict) -> bool:
    """Whether a base.broken is the one a fullHealth run journalled, which a later pass of it repairs, by its source."""
    return entry["kind"] == "base.broken" and entry["data"].get("source") == "fullHealth"


def base_breaks_standing(journal: list[dict]) -> list[dict]:
    """The base.broken entries since the latest base.repaired: what a base.repaired would answer."""
    repaired = max((e["id"] for e in journal if e["kind"] == "base.repaired"), default=0)
    return [e for e in journal if e["kind"] == "base.broken" and e["id"] > repaired]


def only_full_health_breaks(journal: list[dict]) -> bool:
    """Whether every base.broken since the latest base.repaired is fullHealth's own: a pass may repair those, never a
    break the queue found, which the lead confirms however many breaks of fullHealth's follow it."""
    repaired = max((e["id"] for e in journal if e["kind"] == "base.repaired"), default=0)
    return all(full_health_break(e) for e in journal if e["kind"] == "base.broken" and e["id"] > repaired)


def merge_words(c, doc: dict, head: str, since: int) -> tuple[dict | None, str]:
    """The merge a run at this head follows, as {subject, journal} and in words: the latest candidate.merged, with any
    others since the run before it (a batch), and whether the head moved past the queue's last merge outside it."""
    merges = [e for e in doc["journal"] if e["kind"] == "candidate.merged"]
    if not merges:
        return None, "with nothing merged"
    last = merges[-1]
    words = f"after {last.get('subject') or 'a candidate'}'s merge (journal entry {last['id']})"
    batch = [e.get("subject") for e in merges[:-1] if e["id"] > since and e.get("subject")]
    if batch:
        words += f", which landed with {', '.join(batch)}"
    if doc["state"]["meta"].get("baseHead") not in (None, head):
        words += f", and {head[:10]}, which landed outside the queue"
    return {"subject": last.get("subject"), "journal": last["id"]}, words


def flaky_tests(rerun: dict | None, out: str, checkout: Path, timeout: int,
                started: Callable[[int], None] | None = None) -> list[str] | None:
    """The tests a failed fullHealth names, when they pass alone: the binding's fullHealthRerun declared, nothing in the
    run's whole output its unrecheckedPattern matches, at least one test its failurePattern's first group names, and
    one run of its argv with those tests, in the failed run's checkout, that exits 0 with output its ranPattern
    matches. None in every other case, so the failure stands."""
    if not rerun:
        return None
    unrechecked = rerun.get("unrecheckedPattern")
    if unrechecked and re.search(unrechecked, out):
        return None
    tests = list(dict.fromkeys(match.group(1) for match in re.finditer(rerun["failurePattern"], out) if match.group(1)))
    if not tests:
        return None
    argv = [arg for element in rerun["argv"] for arg in (tests if element == "{tests}" else [element])]
    try:
        code, said = run_group(argv, checkout, timeout, started=started)
    except Stop:
        return None
    return tests if code == 0 and re.search(rerun["ranPattern"], said) else None


def in_detached_checkout(c, commit: str, checkout: Path, work: Callable[[Path], object], timeout: int):
    """Make a fresh detached checkout of a commit at `checkout`, run the repository's prepare steps in it, each in a
    process group of its own within `timeout`, and return what `work` makes of it. The checkout, and the folder it sits
    in, are removed however that ends: a stop runs the removal too, once what a step or the run started has been
    stopped with its group."""
    try:
        git("worktree", "add", "--detach", "-q", str(checkout), commit, cwd=c.root)
        for step in prepare_commands():
            code, said = run_group(step, checkout, timeout)
            if code != 0:
                raise Stop(f"the prepare step {shlex.join(step)} failed (exit {code}): {said.strip()[-600:]}")
        return work(checkout)
    finally:
        run(["git", "worktree", "remove", "--force", str(checkout)], cwd=c.root, check=False)
        shutil.rmtree(checkout.parent, ignore_errors=True)


def run_full_health(c, binding: dict, head: str, posture: dict, named: str,
                    started: Callable[[int], None] | None = None, checkout: Path | None = None) -> tuple[bool, str]:
    """One gate run of fullHealth at this base head, in a fresh checkout of it. Its result goes to the full-health log,
    and the journal says what it means for the base, naming the merge it follows: base.verified on a pass,
    base.broken on a failure, and base.repaired on the first pass after a failed run. The result and its journal entry
    are written with SIGTERM held off, so a stop never leaves one without the other."""
    doc = load_state()
    before = [e for e in read_log("full-health", c.delivery) if e.get("result")]
    merge, after = merge_words(c, doc, head, before[-1].get("journalThrough", 0) if before else 0)
    checkout = checkout or Path(tempfile.mkdtemp(prefix="run-delivery-full-health-")) / "base"

    def gate(checkout: Path) -> tuple[int, str, list[str] | None]:
        code, out = run_group(list(binding["fullHealth"]), checkout, full_health_timeout(binding), started=started)
        # A failure is re-checked once, in this same checkout, before it can break the base.
        flaky = None if code == 0 else flaky_tests(binding.get("fullHealthRerun"), out, checkout,
                                                   full_health_timeout(binding), started=started)
        return code, out, flaky
    try:
        code, out, flaky = in_detached_checkout(c, head, checkout, gate, full_health_timeout(binding))
    except Stop as error:
        code, out, flaky = 1, str(error), None
    result = "passed" if code == 0 else "flaky" if flaky else "failed"
    through = max((e["id"] for e in doc["journal"]), default=0)
    # Held off through the journal entry, and in the state tool it starts, which inherits the mask.
    signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM})
    try:
        return record_full_health(c, head, result, out, posture, merge, after, through, before, doc, named, flaky)
    finally:
        signal.pthread_sigmask(signal.SIG_UNBLOCK, {signal.SIGTERM})


def record_full_health(c, head: str, result: str, out: str, posture: dict, merge: dict | None, after: str,
                       through: int, before: list[dict], doc: dict, named: str,
                       flaky: list[str] | None = None) -> tuple[bool, str]:
    """A run's result in the full-health log, and the journal entry that says what it means for the base. A flaky run,
    whose failing tests passed alone, is the head's result and journals base.flaky: it breaks nothing and repairs
    nothing."""
    with plan_lock(c):
        append_full_health(c, {"head": head, "result": result, "output": out[-2000:], "posture": "gate",
                               "code": posture["code"], "merge": merge, "journalThrough": through,
                               **({"tests": flaky} if flaky else {})})
    # The facts name the full head and the merge the run follows.
    facts: dict = {"source": "fullHealth", "head": head, **({"after": merge["subject"]} if merge and merge.get("subject") else {})}
    answers: list[int] = []
    if result == "failed":
        kind = "base.broken"
        facts["detail"] = out.strip()[-300:] or "no output"
    elif result == "flaky":
        kind = "base.flaky"
        facts["failing"] = list(flaky or [])
    else:
        # A repair only of a break fullHealth found: a pass never confirms a break the queue found, which the lead does.
        # After a flaky run, which repairs nothing, a pass repairs the fullHealth break that still stands, if one does.
        latest = before[-1]["result"] if before else None
        standing = latest == "flaky" and base_breaks_standing(doc["journal"])
        repairs = (latest == "failed" or standing) and only_full_health_breaks(doc["journal"])
        kind = "base.repaired" if repairs else "base.verified"
        if repairs:
            # A repair answers every break standing, so each setback closes at it.
            answers = [e["id"] for e in base_breaks_standing(doc["journal"])]
            facts.pop("after", None)
    state_tool("journal", "--kind", kind, "--data", json.dumps(facts),
               *(["--answers", ",".join(map(str, answers))] if answers else []),
               *(["--subject", merge["subject"]] if merge and merge.get("subject") else []))
    return result == "passed", f"fullHealth {result} at {head[:10]}{named}"


def declared_words(posture: dict) -> str:
    """What a gate run adds to its report: only a declaration that didn't take."""
    return f" ({posture['code']}: {posture_said(posture)['reason']})" if posture["code"] in (
        "posture_malformed", "posture_unreadable") else ""


# A fullHealth run leads a session of its own and holds its lock while it runs, recording its pid, head and start, its
# checkout, and its command's pid, each pid with the time its process started. A pass starts one and polls it, so the
# supervisor keeps passing beside it; one killed with its supervisor alive is adopted by the next, since the lock still
# says it runs; a start that finds the lock held runs nothing. A pid is signalled only while its process is the one
# recorded, by its start time, never a process that came to reuse it.
FULL_HEALTH_STARTS: list[subprocess.Popen] = []  # the children this process started, reaped once they exit
FULL_HEALTH_LOCK_SECONDS = 2  # how long a start retries the lock, which a pass's probe holds for an instant


def full_health_lock_path(c) -> Path:
    return lead_file(c, "full-health.lock")


def full_health_running(c) -> dict | None:
    """The fullHealth run holding its lock, as its lock records it, or None when none runs."""
    held, recorded = read_lock(full_health_lock_path(c))
    return recorded if held else None


def running_words(run: dict) -> str:
    waiting = " (waiting for the machine)" if claim_waiting(run.get("claim")) else ""
    return (f"fullHealth running at {str(run.get('head', ''))[:10]} since {run.get('startedAt', 'its start')} "
            f"(pid {run.get('pid')}){waiting}")


def claim_waiting(claim_id: object) -> bool:
    """Whether the machine's ledger holds this claim, waiting to be admitted. A ledger that can't be read says no."""
    if not isinstance(claim_id, str) or not claim_id:
        return False
    try:
        reading = machine_ledger().reading()
    except Exception:  # noqa: BLE001  (what the run's words add, never what stops them)
        return False
    return any(claim.get("id") == claim_id for claim in reading.get("waiting") or [])


def process_started(pid: int) -> str | None:
    """When the process with this pid started, as ps says it, or None when none has it. In UTC and the C locale, so the
    supervisor that records it and the lead's shell that checks it read the same words."""
    done = subprocess.run(["ps", "-o", "lstart=", "-p", str(pid)], capture_output=True, text=True, check=False,
                          env={**os.environ, "LC_ALL": "C", "TZ": "UTC"})
    return done.stdout.strip() or None


def same_group(pid: object, started: object) -> bool:
    """Whether pid still leads the group of the process recorded as started then."""
    return valid_pid(pid) and isinstance(started, str) and group_of(pid) == pid and process_started(pid) == started


def reap_full_health_starts() -> None:
    for proc in list(FULL_HEALTH_STARTS):
        if proc.poll() is not None:
            FULL_HEALTH_STARTS.remove(proc)


def record_identity(c) -> str:
    """What names this record to a run started for it: its first journal entry's time, which lead-init --replace
    changes, so a run that starts after the record is replaced runs nothing."""
    journal = load_state()["journal"]
    return journal[0]["at"] if journal else ""


def start_full_health(c, head: str, wait: bool) -> dict | None:
    """Start a fullHealth run at this head in a session of its own. With wait, as lead-run --once does, return once it
    has ended; otherwise once it holds its lock, returning what the lock records, or None when it ended first."""
    reap_full_health_starts()
    argv = [sys.executable, "-B", str(Path(__file__).resolve()), "--delivery", c.delivery, "full-health-run",
            "--head", head, "--record", record_identity(c)]
    log = lead_file(c, "full-health.log")
    log.parent.mkdir(parents=True, exist_ok=True)
    with open(log, "a") as out:
        proc = subprocess.Popen(argv, cwd=c.root, stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
                                start_new_session=True)
    if wait:
        proc.wait()
        return None
    FULL_HEALTH_STARTS.append(proc)
    deadline = time.monotonic() + SUPERVISOR_WAIT_SECONDS
    while time.monotonic() < deadline:
        running = full_health_running(c)
        if running and running.get("pid") == proc.pid:
            return running
        if proc.poll() is not None:
            return None
        time.sleep(0.05)
    return full_health_running(c)


def launch_full_health(c, head: str, named: str, wait: bool) -> str:
    """Start a run at this head and say what it is doing, or, once it has ended, what it found. None starts once the
    supervisor is asked to stop: lead-close stops the run it finds, and must not find another."""
    if lead_file(c, "supervisor.stop").exists():
        return f"fullHealth not started at {head[:10]}: the supervisor is asked to stop"
    started = start_full_health(c, head, wait)
    if started is not None:
        return running_words(started)
    last, _ = full_health_results(c, head)
    if last:
        return f"fullHealth {last['result']} at {head[:10]}{named}"
    return f"fullHealth at {head[:10]} ended with no result; its log is {lead_file(c, 'full-health.log')}"


def post_merge_step(c, wait: bool = False) -> str:
    """The post-merge tier: under gate, fullHealth runs at each base head the delivery's merges reach, once a merge has
    landed, and not again at that head until lead-resolve asks. It runs beside the passes, in a child of its own, and a
    pass that finds it running waits for it to end. Close-out runs it only at a head with no run."""
    binding = c.shelf.json(".agents/orchestration.json") or {}
    if not binding.get("fullHealth"):
        return "fullHealth: the binding declares none"
    doc = load_state()
    if not any(e["kind"] == "candidate.merged" for e in doc["journal"]) and not (
            shared_seat(c) is not None
            and all(any(e["kind"] == "finish.met" and e.get("data", {}).get("finish") == line["id"] for e in doc["journal"])
                    for line in doc["state"]["finish"])):
        # On a shared record the close's result comes from here, the queue holder's machine, so a delivery that
        # merged nothing is run once every finish line is met.
        return "fullHealth: nothing merged yet"
    posture = delivery_posture(c)
    if posture["posture"] == "focused":
        return "fullHealth: not run after merges under the focused posture"
    with plan_lock(c):
        note_posture(c, posture)
    named = declared_words(posture)
    reap_full_health_starts()
    running = full_health_running(c)
    if running is not None:
        return running_words(running)
    git("fetch", "-q", c.remote, c.base_branch, check=False)
    head = base_head(c)
    last, rerun = full_health_results(c, head)
    if last and not rerun:
        return f"fullHealth {last['result']} at {head[:10]}{named}"
    return launch_full_health(c, head, named, wait)


def full_health_step(c, wait: bool = False) -> tuple[bool, str]:
    binding = c.shelf.json(".agents/orchestration.json") or {}
    argv = binding.get("fullHealth")
    if not argv:
        return True, "fullHealth: the binding declares none"
    posture = delivery_posture(c)
    if posture["posture"] == "focused":
        return True, record_focused(c, posture)
    with plan_lock(c):
        note_posture(c, posture)
    named = declared_words(posture)
    running = full_health_running(c)
    if running is not None:
        return False, running_words(running)
    git("fetch", "-q", c.remote, c.base_branch, check=False)
    head = base_head(c)
    last, rerun = full_health_results(c, head)
    # A flaky run is the head's result, which holds nothing at the close by itself.
    if last and last["result"] in ("passed", "flaky"):
        return True, f"fullHealth {last['result']} at {head[:10]}{named}"
    if last and not rerun:
        return False, f"fullHealth failed at {head[:10]}{named}; it runs again at a later head, or on lead-resolve full-health"
    found = shared_seat(c)
    if found is not None and not found[0].holds(found[1], found[2], "queue"):
        # Full health runs once a head, on the queue holder's machine: its result is carried here (D12).
        holder = found[0].holder(found[1], "queue")
        return False, f"fullHealth: waiting for seat {holder}, which holds the queue, to run it at {head[:10]}{named}"
    # No run at this head: after a merge the post-merge step has run, so this is a delivery that merged nothing.
    line = launch_full_health(c, head, named, wait)
    last, _ = full_health_results(c, head)
    return bool(last and last["result"] in ("passed", "flaky")
                and line.startswith(("fullHealth passed", "fullHealth flaky"))), line


def full_health_run(args) -> None:
    """One fullHealth run at --head, as a pass starts it, in a session of its own, for the record --record names. It
    holds the run's lock while it runs, so a second start runs nothing, and checks again under the lock that no result
    stands at the head. A run killed outright left its command running and its checkout behind: this start stops the
    one and removes the other first. Stopped, it stops its own command's group, removes its checkout and records
    nothing, unless it was writing its result, which it finishes."""
    c = cfg()
    # Its log is a file: each line is flushed as it's said, so a reader sees it while the run goes on.
    sys.stdout.reconfigure(line_buffering=True)
    path = full_health_lock_path(c)
    path.parent.mkdir(parents=True, exist_ok=True)
    handle = open(path, "a+")
    deadline = time.monotonic() + FULL_HEALTH_LOCK_SECONDS
    while True:
        try:
            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
            break
        except BlockingIOError:
            if time.monotonic() < deadline:
                time.sleep(0.05)
                continue
            handle.close()
            _, recorded = read_lock(path)
            print(f"a fullHealth run already runs at {str(recorded.get('head', ''))[:10]} (pid {recorded.get('pid')}); "
                  "this start runs nothing")
            return
    try:
        handle.seek(0)
        try:
            earlier = json.loads(handle.read() or "{}")
        except ValueError:
            earlier = {}
        earlier = earlier if isinstance(earlier, dict) else {}
        said = {"pid": os.getpid(), "pidStarted": process_started(os.getpid()), "head": args.head, "startedAt": now()}

        def record(fields: dict) -> None:
            said.update(fields)
            handle.seek(0)
            handle.truncate()
            handle.write(json.dumps(said))
            handle.flush()

        record({})
        signal.signal(signal.SIGTERM, lambda *_: (_ for _ in ()).throw(SystemExit(143)))
        if same_group(earlier.get("command"), earlier.get("commandStarted")):
            with contextlib.suppress(ProcessLookupError, PermissionError):
                os.killpg(earlier["command"], signal.SIGKILL)
            print(f"stopped the command (pid {earlier['command']}) of a fullHealth run killed at "
                  f"{str(earlier.get('head', ''))[:10]}")
        left = earlier.get("checkout")
        if isinstance(left, str) and Path(left).name == "base" and Path(left).parent.name.startswith(
                "run-delivery-full-health-"):
            forget_checkout(c, Path(left))
        if record_identity(c) != args.record:
            print("the record was replaced since this run was started; it runs nothing")
            return
        binding = c.shelf.json(".agents/orchestration.json") or {}
        if not binding.get("fullHealth"):
            print("fullHealth: the binding declares none")
            return
        posture = delivery_posture(c)
        if posture["posture"] == "focused":
            print("fullHealth: not run under the focused posture")
            return
        last, rerun = full_health_results(c, args.head)
        if last and not rerun:
            print(f"fullHealth {last['result']} at {args.head[:10]} already; this start runs nothing")
            return
        # Its claim comes only now, under the run's lock and with no result standing, and its id goes in the lock, so
        # the waiting run is what full_health_running reports and a second start runs nothing. Its wait has no cap.
        held = claim_full_health(c, args.head, record)
        with held, claimed_environment(held):
            checkout = Path(tempfile.mkdtemp(prefix="run-delivery-full-health-")) / "base"
            record({"checkout": str(checkout)})
            began, cpu = time.monotonic(), cpu_mark()
            passed = False
            try:
                passed, line = run_full_health(c, binding, args.head, posture, declared_words(posture),
                                               started=lambda pid: record({"command": pid,
                                                                           "commandStarted": process_started(pid)}),
                                               checkout=checkout)
                print(line)
            finally:
                # Stopped with its run, by run_group, and its checkout removed by run_full_health.
                record({"command": None, "commandStarted": None, "checkout": None})
            held.record_cost(measured_since(machine_module(), 0 if passed else 1, began, cpu, passed))
    finally:
        fcntl.flock(handle, fcntl.LOCK_UN)
        handle.close()


def claim_full_health(c, head: str, record: Callable[[dict], None]):
    """fullHealth's machine claim, held by its full-health-run process: in the ledger before any wait, its id recorded
    in the run's lock as it enters, and waited for with no cap, however long the machine stays full. A supervisor
    restart neither releases it nor blocks on it."""
    def enqueued(claim) -> None:
        record({"claim": claim.id})
        if not claim.admitted:
            print(f"fullHealth at {head[:10]} waits for the machine (claim {claim.id})")
    return heavy_claim("fullHealth", "fullHealth", label=f"fullHealth {c.delivery}", repository=machine_repository(),
                       delivery=c.delivery, enqueued=enqueued)


def forget_checkout(c, checkout: Path) -> None:
    """Remove a killed run's checkout and its entry in the repository's worktrees, and no other: a prune would also drop
    any other checkout whose folder is away just then."""
    run(["git", "worktree", "remove", "--force", str(checkout)], cwd=c.root, check=False)
    shutil.rmtree(checkout.parent, ignore_errors=True)
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir", cwd=c.root))
    for entry in (common / "worktrees").glob("*/gitdir") if (common / "worktrees").is_dir() else []:
        with contextlib.suppress(OSError):
            # Git records the resolved folder: /private/var for a checkout under /var.
            if Path(entry.read_text().strip()).parent.resolve() == checkout.resolve():
                shutil.rmtree(entry.parent, ignore_errors=True)


def stop_full_health_run(c) -> str | None:
    """Stop the fullHealth run holding its lock, by the group its recorded pid leads, once the lock names the process
    that holds it, and confirm it let the lock go. Says whether it recorded its result first."""
    path = full_health_lock_path(c)
    deadline = time.monotonic() + FULL_HEALTH_LOCK_SECONDS * 5
    while True:
        held, recorded = read_lock(path)
        if not held:
            return None
        pid = recorded.get("pid")
        if same_group(pid, recorded.get("pidStarted")):
            break
        # A start that has only just taken the lock still shows the last run's record: wait for its own.
        if time.monotonic() > deadline:
            raise Stop(f"{path} is held by a process its record doesn't name; stop the fullHealth run yourself, then "
                       "run this again")
        time.sleep(0.1)
    for sig, wait in ((signal.SIGTERM, 30), (signal.SIGKILL, 5)):
        with contextlib.suppress(ProcessLookupError):
            os.killpg(pid, sig)
        deadline = time.monotonic() + wait
        while time.monotonic() < deadline and read_lock(path)[0]:
            time.sleep(0.1)
        if not read_lock(path)[0]:
            break
    else:
        raise Stop(f"the fullHealth run (pid {pid}) still holds {path} after SIGKILL; stop it, then run this again")
    # A run stopped by SIGKILL can't stop its command's group itself.
    if same_group(recorded.get("command"), recorded.get("commandStarted")):
        with contextlib.suppress(ProcessLookupError, PermissionError):
            os.killpg(recorded["command"], signal.SIGKILL)
    head = str(recorded.get("head", ""))
    recorded_first = any(e.get("result") and e.get("head") == head and e["at"] >= recorded.get("startedAt", "")
                         for e in read_log("full-health", c.delivery))
    return (f"stopped the fullHealth run at {head[:10]} (pid {pid}); "
            + ("it had recorded its result" if recorded_first else "it recorded no result"))


# The states in which a later round of the lens that deferred a finding records it fixed.
DEFERRAL_FIXED = ("closed", "fixed", "withdrawn")


def held_deferrals(journal: list[dict]) -> list[dict]:
    """The deferred findings a shared record's lane holders journalled as `deferral.held`, {story, finding, title}."""
    found = {(e.get("subject"), e["data"]["finding"]): {"story": e.get("subject"), "finding": e["data"]["finding"],
                                                        "title": e["data"]["title"]}
             for e in journal if e["kind"] == "deferral.held"}
    return list(found.values())


def journal_deferrals(c, doc: dict, key: str) -> list[str]:
    """On a shared record, before a merged story's checkout goes: each finding its review still holds deferred,
    journalled once as `deferral.held` by the lane holder, whose machine has the rounds, for the close's follow-ups."""
    if shared_seat(c) is None:
        return []
    have = {(e.get("subject"), e["data"]["finding"]) for e in doc["journal"] if e["kind"] == "deferral.held"}
    said = []
    for finding in deferred_findings(c):
        if finding["story"] == key and (key, finding["finding"]) not in have:
            state_tool("journal", "--kind", "deferral.held", "--subject", key, "--data",
                       json.dumps({"finding": finding["finding"], "title": finding["title"]}))
            said.append(f"{key}: {finding['finding']} held deferred")
    return said


def deferred_findings(c) -> list[dict]:
    """Every finding a story's review deferred and still holds deferred, {story, finding, title}: from the lane's review
    folder, or the evidence kept beside the record once its checkout is gone. A deferral is fixed only when a later
    round of the lens that filed it lists it in `resolvedFindings` as closed, fixed or withdrawn; one listed as open or
    deferred, listed by another lens, or not listed stays deferred."""
    found: dict[tuple[str, str], dict] = {}
    for key in c.stories:
        rounds: dict[int, dict] = {}
        for folder in (c.lane_checkout(key) / c.work / "review" / key, evidence_dir(key)):
            for path in round_files(folder) if folder.is_dir() else []:
                rounds[int(path.stem.split("-")[1])] = json.loads(path.read_text())
        held: dict[str, tuple[str, dict]] = {}  # finding id: (the lens that deferred it, the finding)
        for n in sorted(rounds):
            for entry in rounds[n].get("entries", []):
                result = entry.get("result") or {}
                lens = entry.get("lens") or result.get("lensId")
                for listed in result.get("resolvedFindings", []):
                    if listed.get("state") in DEFERRAL_FIXED and held.get(listed.get("id"), ("",))[0] == lens:
                        del held[listed["id"]]
                for finding in result.get("findings", []):
                    if finding.get("state") == "deferred":
                        held[finding["id"]] = (lens, finding)
        for ident, (_, finding) in held.items():
            found[(key, ident)] = {"story": key, "finding": ident, "title": str(finding.get("deferredIssue", ""))[:200]}
    return list(found.values())


BREACH = "Deferred finding {finding} of {story} is still deferred at merge, and this delivery takes no deferrals: {title}"


def breach_of(entry: dict, finding: dict) -> bool:
    """Whether an entry is the breach journalled for this deferred finding: a deferral.breached naming it."""
    return (entry.get("subject") == finding["story"] and entry["kind"] == "deferral.breached"
            and entry["data"]["finding"] == finding["finding"])


def deferral_breaches(c, doc: dict) -> list[str]:
    """Under noDeferrals, journal a deferral.breached for each finding a merged story's review still holds deferred, once each:
    the lead resolves it with lead-resolve, and no follow-up is filed for it."""
    if not c.no_deferrals:
        return []
    roles = seat_roles(c)
    # On a shared record, only the stories of the lanes this seat holds, whose review rounds are on its machine.
    merged = {item["subject"] for item in doc["state"]["queue"] if item["stage"] == "merged"
              and lane_held(roles, item.get("lane"))}
    said = []
    for finding in deferred_findings(c):
        if finding["story"] not in merged:
            continue
        if any(breach_of(e, finding) for e in doc["journal"]):
            continue
        state_tool("journal", "--kind", "deferral.breached", "--subject", finding["story"],
                   "--data", json.dumps({"finding": finding["finding"], "title": finding["title"].strip() or "no title given"}))
        said.append(f"blocker: deferred finding {finding['finding']} of {finding['story']}")
    return said


FOLLOWUP = "Deferred finding {finding} of {story} becomes follow-up {story}-{finding}: {title}"


def followups_step(c, doc: dict) -> tuple[bool, str]:
    """One follow-up item per deferred finding, and per repo gap (its finding gap-<journal id>), keyed by story and
    finding id, which is also its followups[] id.
    Each is journalled as a decision marked for the tracker publisher to file; the step holds until the publisher's
    ledger covers every one: a transient failure is retried by its next run, and a permanent one is shown. By hand,
    the record's followups are all there is."""
    have = {item["id"] for item in doc["state"]["followups"]}
    if c.no_deferrals:
        # A finding still deferred is a blocker, never a follow-up. The close-out journals any the pass step missed,
        # by a failure or a merge after it read the queue, and holds the close for it.
        said = deferral_breaches(c, doc)
        if said:
            return False, f"{'; '.join(said)} (the close waits for lead-resolve)"
        missing = []
    else:
        # On a shared record a lane's deferrals are journalled by its holder, whose machine has its review rounds.
        deferred = held_deferrals(doc["journal"]) if shared_seat(c) is not None else deferred_findings(c)
        missing = [f for f in deferred if f"{f['story']}-{f['finding']}" not in have]
    # Each repo gap noted since the last close is a follow-up too, filed the same way: a gap is no review finding, so
    # noDeferrals leaves it one.
    found = gaps.gaps(doc["journal"], REOPENING)
    if found:
        missing += [f for f in gaps.followups(found, c.delivery) if f"{f['story']}-{f['finding']}" not in have]
    for finding in missing:
        with marked_decision(c, followup=finding) as written:
            written.append(journal_id(state_tool("journal", "--kind", "followup.filed", "--subject",
                                                 finding["story"], "--data", json.dumps({"finding": finding["finding"], "followup":
                                                                       f"{finding['story']}-{finding['finding']}",
                                                                       "title": finding["title"]}))))
    if missing:
        patch_from(lambda fresh: {"followups": [*fresh["state"]["followups"],
                                                *({"id": f"{f['story']}-{f['finding']}", "title": f["title"],
                                                   "reference": None} for f in missing)]},
                   "the deferred findings' follow-ups")
        render_views(c)
        doc = load_state()
    if tracker_conf(c)["mode"] != "publisher":
        return True, f"follow-ups: {len(doc['state']['followups'])} recorded"
    marks = {entry["journal"] for entry in tracker_publisher.read_flow(c.flow_log, c.delivery, tracker_publisher.MARKS)
             if entry.get("followup")}
    journal = sorted(doc["journal"], key=lambda e: e["id"])
    done = tracker_publisher.covered(tracker_publisher.read_ledger(c.state), tracker_publisher.init_id(journal))
    waiting = sorted(marks - done)
    if waiting:
        return False, f"follow-ups: waiting for the tracker publisher to file journal entries {', '.join(map(str, waiting))}"
    return True, f"follow-ups: {len(marks)} filed or refused"


def gap_writer(c) -> tuple[str, str | None]:
    """Who notes a gap from this checkout: ("lead", None) in the lead checkout, else (the lane's id, its story) in a
    story's own checkout, read from its branch."""
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=c.root, check=False)
    if is_lead_checkout(c, branch):
        return "lead", None
    key = next((key for key in c.stories if c.branch(key) == branch), None)
    if key is None:
        raise Stop(f"run note-gap in the lead checkout, or in a story's own checkout on its branch: {branch} is neither")
    return c.lane_of(key), key


def running_release(c) -> tuple[str, str]:
    """The release id and generation of the generation running, from its own entry in the receipt, as the round brief
    reads them."""
    return release_tuple()["releaseId"], c.release.resolve().name


def note_gap(args) -> None:
    """Journal gap.noted, as a new gap or as an occurrence of an open one, after listing the open
    gaps of the same class it could repeat. A lane notes under its own writer, on its current story."""
    c = cfg()
    text, why = worded(args.text, "--text"), worded(args.why, "--why")
    if args.gap_command is not None:
        worded(args.gap_command, "--command")
    by, story = gap_writer(c)
    subject = args.subject or (c.delivery if by == "lead" else story)
    evidence = Path(args.evidence).resolve() if args.evidence else None
    if args.cls == "workflow" and evidence is None:
        raise Stop("a workflow gap needs --evidence: the command's output, or the script you wrote to get the "
                   "behaviour the workflow should give")
    if evidence is not None and not evidence.is_file():
        raise Stop(f"--evidence {args.evidence}: no such file")
    release = generation = None
    try:
        release, generation = running_release(c)
    except Stop:
        if args.cls == "workflow":
            raise
    journal = load_state()["journal"]
    try:
        occurrence = gaps.occurrence_of(journal, args.cls, text, release, args.same_as)
    except gaps.Refused as error:
        raise Stop(str(error)) from None
    listed = gaps.listing(journal, args.cls, release)
    print(f"open {args.cls} gaps{' on ' + release if args.cls == 'workflow' else ''}, by journal id"
          f"{' (name one with --same-as N)' if listed else ''}:")
    print("\n".join(listed) or "  (none)")
    data = {"class": args.cls, "text": text, "why": why, "by": by,
            **({"release": release, "generation": generation} if release else {}),
            **({"command": args.gap_command} if args.gap_command is not None else {}),
            **({"occurrenceOf": occurrence} if occurrence is not None else {})}
    entry_id = gaps.next_id(journal)
    if evidence is not None:
        try:
            data["evidence"] = gaps.copy_evidence(c.state, entry_id, evidence)
        except gaps.Refused as error:
            raise Stop(str(error)) from None
    writer = [] if by == "lead" else ["--writer", "lane", "--lane", by]
    done = state_tool("journal", *writer, "--kind", "gap.noted", "--subject", subject, "--data", json.dumps(data),
                      check=False)
    if done.returncode != 0:
        if evidence is not None:
            gaps.drop_evidence(c.state, entry_id)
        raise Stop(f"journal {gaps.KIND} failed: {(done.stderr or done.stdout).strip()[-600:]}")
    number = journal_id(done)
    if number != entry_id and evidence is not None:
        raise Stop(f"gap.noted is journal entry {number}, but its evidence was copied under {entry_id}: another entry "
                   f"was journalled at the same time; the evidence is at {c.state / data['evidence']['path']}")
    print(f"noted {args.cls} gap {number} on {subject}" + (f", an occurrence of gap {occurrence}" if occurrence else "")
          + (f"; evidence copied to {c.state / data['evidence']['path']}" if evidence is not None else ""))


# New work after a close reopens the delivery, as the line map reads it.
REOPENING = ("lane.assigned", "candidate.handed", "check.started")


def latest_close(journal: list[dict]) -> dict | None:
    """The delivery.closed entry that closes the delivery now: the latest one, unless work resumed after it."""
    closed = None
    for entry in sorted(journal, key=lambda e: e["id"]):
        if entry["kind"] == "delivery.closed":
            closed = entry
        elif entry["kind"] in REOPENING:
            closed = None
    return closed


def last_close(journal: list[dict]) -> dict | None:
    """The latest delivery.closed entry, reopened since or not."""
    return next((e for e in sorted(journal, key=lambda e: e["id"], reverse=True) if e["kind"] == "delivery.closed"), None)


COMPOUNDING_KIND = "compounding.recorded"
# How the close condition names the compound-learning decision while it is owed.
DECISION_HOLD = "the compound-learning decision"


def reopened_at(journal: list[dict]) -> int:
    """The id of the entry that last reopened the delivery after a close, or 0 when it never was."""
    at, closed = 0, False
    for entry in sorted(journal, key=lambda e: e["id"]):
        if entry["kind"] == "delivery.closed":
            closed = True
        elif entry["kind"] in REOPENING and closed:
            at, closed = entry["id"], False
    return at


def compounding_decision(journal: list[dict]) -> dict | None:
    """The latest compound-learning decision recorded since the delivery last reopened, or None."""
    since = reopened_at(journal)
    return next((e for e in sorted(journal, key=lambda e: e["id"], reverse=True)
                 if e["kind"] == COMPOUNDING_KIND and e["id"] > since), None)


def close_finished(c, doc: dict) -> bool:
    """Whether the delivery's close has finished: its delivery.closed entry is named by a finished mark or by
    closed.json. Such a close stands as it is, with or without a decision, as a record kept before decisions does."""
    closed = latest_close(doc["journal"])
    return closed is not None and (close_progress(doc) == "finished" or kept_close(c, closed) is not None)


def decision_owed(c, doc: dict) -> bool:
    """Whether the close waits on the compound-learning decision: none recorded since the latest reopening, and no
    finished close to exempt it. A planning record has no close, so it owes none."""
    if (doc["state"].get("meta") or {}).get("phase") == "planning":
        return False
    return compounding_decision(doc["journal"]) is None and not close_finished(c, doc)


def open_work(c, doc: dict) -> list[str]:
    """The work still open, as the close condition words it: a planned story not settled, and a queued one not
    merged, each leaving out the subjects a plan change removed."""
    state, removed = doc["state"], removed_subjects(c)
    holds = []
    planned = [p["subject"] for p in state.get("planned", []) if p["subject"] not in removed and p["stage"] != "settled"]
    if planned:
        holds.append(f"not handed off: {', '.join(planned)}")
    unmerged = [q["subject"] for q in state["queue"] if q["stage"] != "merged" and q["subject"] not in removed]
    if unmerged:
        holds.append(f"not merged: {', '.join(unmerged)}")
    return holds


def tracker_owed(c, doc: dict, closed: dict) -> str | None:
    """What the tracker hasn't had yet through the closing entry, or None when it has every update."""
    mode = tracker_conf(c)["mode"]
    if mode == "publisher":
        journal = sorted(doc["journal"], key=lambda e: e["id"])
        done = tracker_publisher.covered(tracker_publisher.read_ledger(c.state), tracker_publisher.init_id(journal))
        owed = [e["id"] for e in journal if e["id"] <= closed["id"] and e["id"] not in done]
        if owed:
            return f"the tracker publisher to cover journal entries {', '.join(map(str, owed[:10]))}"
    return None


def closed_step(c) -> tuple[bool, str]:
    """Journal delivery.closed once for this close, render, then wait until the tracker has every entry through it.
    A delivery closed, reopened by new work and closed again is closed by a new entry."""
    doc = load_state()
    closed = latest_close(doc["journal"])
    if closed is None:
        skip = full_health_skip(c)
        state_tool("journal", "--kind", "delivery.closed", "--data", json.dumps({"skipped": True} if skip else {}))
        render_views(c)
        doc = load_state()
        closed = latest_close(doc["journal"])
    owed = tracker_owed(c, doc, closed)
    if owed:
        return False, f"waiting for {owed}"
    return True, f"delivery.closed is journal entry {closed['id']}"


def new_archive_folder(root: Path) -> Path:
    """A new, empty folder under `root`, named by the time to the microsecond as replace_record's are, so two close-outs
    in one second don't collide. A name already taken, by a clock that didn't move or another process, gets the next
    free -002, -003 suffix. Every name sorts in the order the folders were made."""
    stamp = datetime.datetime.now().strftime("%Y%m%dT%H%M%S.%f")
    root.mkdir(parents=True, exist_ok=True)
    for n in range(1, 1000):
        folder = root / (stamp if n == 1 else f"{stamp}-{n:03d}")
        try:
            folder.mkdir()
            return folder
        except FileExistsError:
            continue
    raise Stop(f"{root} already holds 999 archives stamped {stamp}; remove some, then run it again")


def archive_delivery(c) -> tuple[Path, list[str]]:
    """Copy the record, the lead-side logs, the lanes' evidence and the plan review into a new archive folder."""
    archive = new_archive_folder(archive_root(c))
    for source in (c.state, c.flow_log, c.flow_log.parent / "evidence"):
        if source.exists():
            shutil.copytree(source, archive / source.name,
                            ignore=shutil.ignore_patterns('hosted-*','.hosted-*') if source==c.state else None)
    copy_hosted(c,archive/c.state.name)
    state = load_json(archive / c.state.name / "state.json") or {}
    archived = copy.deepcopy(c.raw)
    for lane, owns in c.effective_ownership(state).items():
        archived["lanes"].setdefault(lane, {})["owns"] = owns
    for key in c.stories:
        archived["stories"][key]["lane"] = c.lane_of(key, state)
    (archive / c.delivery_path.name).write_text(json.dumps(archived, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    reviewed = archive_plan_review(archive)
    return archive, [f"archived the record, the lead-side logs{', the plan review' if reviewed else ''} and the lanes' "
                     f"evidence in {archive}"]


def closed_full_health(c) -> dict:
    """What closed.json says of a skipped run: nothing at all when a real result stands."""
    skip = full_health_skip(c)
    return {"fullHealth": {"state": "skipped", **{key: skip[key] for key in ("posture", "source", "reason", "head")}}} if skip else {}


def kept_close(c, closed: dict | None) -> dict | None:
    """closed.json, when it is this close's: it names the closing entry, or is an older one that names none."""
    kept = load_json(lead_file(c, "closed.json"))
    if not kept:
        return None
    return kept if kept.get("entry") is None or (closed is not None and kept["entry"] == closed["id"]) else None


def finish_close(c, closed: dict, archive: Path) -> list[str]:
    """The close's finished mark, once its archive has landed: in the live record, and in the archived copy and its
    views. Writing it again changes nothing. A record with no started mark for this close, journaled by a tool that
    wrote no marks, closes as before: unmarked."""
    if close_progress(load_state()) is None:
        return []
    state_tool("close-finished", "--entry", str(closed["id"]))
    copy = archive / c.state.name
    if not (copy / "state.json").exists():
        return ["marked the close finished in the record"]
    tool = c.release / STATE_TOOL
    run([sys.executable, "-B", str(tool), "--dir", str(copy), "close-finished", "--entry", str(closed["id"])])
    config = binding_state(c)
    if config is not None:
        script = c.release / "skills/orchestrate-work/scripts/render_state.py"
        run([sys.executable, "-B", str(script), "--dir", str(copy), "--state-config",
             json.dumps({**{key: value for key, value in config.items() if key != "liveHome"}, "publishers": []})],
            cwd=c.root, check=False, timeout=300)
    return ["marked the close finished in the record and its archive"]


def align_operator(c) -> tuple[bool | None, str]:
    """Fast-forward the operator's checkout to its branch's remote tip, when it is clean and on the delivery's base or
    its integration target, so the operator's main checkout holds what the delivery landed. Returns True when it is
    aligned, None when the operator's own work holds it, another branch or uncommitted changes, which are theirs to
    keep, and False when it can't fast-forward, with the line that says which."""
    operator = c.main
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=operator, check=False)
    dirty = git("status", "--porcelain", cwd=operator, check=False)
    if branch not in {c.base_branch, c.raw.get("integrationTarget")} - {None}:
        return None, f"left {operator} where it is: it is on {branch}"
    ref = f"{c.remote}/{branch}"
    if dirty:
        return None, f"left {operator} where it is: it has uncommitted changes; align it with {ref} once they're settled"
    fetched = run(["git", "fetch", "-q", c.remote, branch], cwd=operator, check=False)
    if fetched.returncode != 0:
        return False, f"left {operator} where it is: {c.remote}/{branch} couldn't be fetched"
    moved = run(["git", "merge", "--ff-only", "-q", ref], cwd=operator, check=False)
    if moved.returncode == 0:
        return True, f"fast-forwarded {operator} to {ref}"
    return False, f"left {operator} where it is: it can't fast-forward to {ref}"


def retire_lead(c) -> tuple[list[str], list[str]]:
    """Remove the lead's checkout once the close's archive holds everything in it: the delivery closed with its archive
    landed, nothing of the delivery still runs from it, the record has nothing the archive lacks, no other checkout sits
    inside it, and it has no change and its head is pushed. Never the operator's main checkout. What the close wrote
    beside the record after the archive, its closed.json and the hosted sidecars, is copied into the archive first. The
    command runs from that checkout, so it moves to the main checkout before removing it. Returns (what it did, why it
    kept it)."""
    lead = c.lane_checkout(c.delivery)
    if not lead.exists() or lead.resolve() == c.main.resolve():
        return [], []
    doc = load_state()
    kept = kept_close(c, latest_close(doc["journal"]))
    if kept is None:
        return [], [f"{lead} kept: the delivery's close hasn't archived the record yet"]
    archive = Path(kept["archive"])
    archived_ids, unreadable = set(), False
    journal = archive / c.state.name / "journal.jsonl"
    try:
        for line in journal.read_text().splitlines():
            if line.strip():
                entry = json.loads(line)
                archived_ids.add(entry.get("id") if isinstance(entry, dict) else None)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        unreadable = True
    if unreadable:
        return [], [f"{lead} kept: the archived journal {journal} can't be read"]
    since = [entry["id"] for entry in doc["journal"] if entry.get("id") not in archived_ids]
    if since:
        return [], [f"{lead} kept: the record has {len(since)} journal entr{'y' if len(since) == 1 else 'ies'} the "
                    f"archive lacks ({', '.join(map(str, since[:5]))}); close it again so the archive holds them"]
    running = [pid for pid, _ in delivery_processes(lead, c.state, c.delivery, c.main)] + \
        sorted(owned_hosted_processes(c))
    if running:
        return [], [f"{lead} kept: the delivery still runs from it (pid {', '.join(map(str, running))}); run "
                    f"{flow_command()} lead-retire once they have stopped"]
    nested = [path for path in worktrees_under(lead) if path.resolve() != lead.resolve()]
    if nested:
        return [], [f"{lead} kept: other checkouts sit inside it ({', '.join(map(str, nested[:3]))})"]
    dirty = git("status", "--porcelain", "--untracked-files=all", cwd=lead, check=False)
    if dirty:
        return [], [f"{lead} kept: it has uncommitted or untracked files:\n      " + dirty[:400].replace("\n", "\n      ")]
    head = git("rev-parse", "HEAD", cwd=lead)
    if not git("branch", "-r", "--contains", head, cwd=lead, check=False):
        return [], [f"{lead} kept: its head {head[:12]} is on no remote branch"]
    branch = git("rev-parse", "--abbrev-ref", "HEAD", cwd=lead, check=False)
    pushed_tip = remote_head(branch) if branch and branch != "HEAD" else ""
    # The record's folder and flow log as they stand now, hosted sidecars included, since the archive was taken before
    # the close wrote its last files beside them; ignored files leave with the checkout.
    retired = archive / "at-retire"
    for source in (c.state, c.flow_log):
        if source.exists():
            shutil.copytree(source, retired / source.name, dirs_exist_ok=True)
    os.chdir(c.main)
    removed = run(["git", "worktree", "remove", str(lead)], cwd=c.main, check=False)
    if removed.returncode != 0:
        return [], [f"{lead} kept: git worktree remove failed: {(removed.stderr or removed.stdout).strip()[-300:]}"]
    done = [f"removed the lead's checkout {lead} (its record is in {archive}, the files written after the archive in "
            f"{retired})"]
    if pushed_tip == head:
        run(["git", "branch", "-D", branch], cwd=c.main, check=False)
        done.append(f"deleted the local {branch} ({c.remote}/{branch} is kept)")
    return done, []


def lead_retire(args) -> None:
    c = cfg()
    done, kept = retire_lead(c)
    for line in done:
        print(f"  done: {line}")
    for line in kept:
        print(f"  left: {line}")
    if not done and not kept:
        print(f"{c.delivery}: the lead has no checkout of its own to remove")
    if kept:
        sys.exit(1)


def archive_step(c, closed: dict) -> tuple[Path, list[str]]:
    """Release every lease the lead holds, archive the record, and fast-forward the operator's checkout when it is
    clean and on the final base. Done once for each close: a resumed close-out finds its archive."""
    marker = lead_file(c, "closed.json")
    kept = kept_close(c, closed)
    if kept:
        return Path(kept["archive"]), kept["said"]
    held: list[dict] = []

    def release(doc: dict) -> dict | None:
        leases = doc["state"]["leases"]
        held[:] = [lease for lease in leases if lease.get("holder") == "lead"]
        return {"leases": [lease for lease in leases if lease.get("holder") != "lead"]} if held else None
    said = []
    if patch_from(release, "the lead's released leases") is not None:
        said.append(f"released the lead's leases: {', '.join(str(lease.get('id')) for lease in held)}")
    archive, archived = archive_delivery(c)
    said += archived
    said.append(align_operator(c)[1])
    marker.write_text(json.dumps({"archive": str(archive), "said": said, "at": now(), "entry": closed["id"],
                                  **closed_full_health(c)}, indent=2) + "\n")
    return archive, said


def workflow_gaps_step(c, archive: Path, found: list[dict]) -> Path | None:
    """The workflow gaps beside the archive, grouped by release, for the workflow's maintainers; the archive holds
    their evidence. None when no workflow gap was noted."""
    report = gaps.workflow_report(found, c.delivery, archive, c.state.name)
    if report is None:
        return None
    path = archive.parent / f"{archive.name}.workflow-gaps.md"
    if not path.exists():
        path.write_text(report)
    return path


HARD = "## What was hard"
LEFT = "## What the close-out left to you"
# The stub's sections the supervisor writes, which end what the lead wrote under HARD.
GENERATED = ("## Shown, never holding", "## Gaps noted", LEFT)


def friction_stub_path(c) -> Path:
    """Where the friction stub is kept until the close-out archives it: among the lead-side files."""
    return lead_file(c, "friction.md")


def write_friction_stub(c, shown: list[str], found: list[dict]) -> Path:
    """Write the friction stub's generated sections, "Shown, never holding" and "Gaps noted", as known now, keeping
    whatever the lead wrote under "What was hard". The supervisor writes it once nothing but the compound-learning
    decision holds the close, and again on each later pass until the close-out archives it."""
    stub = friction_stub_path(c)
    hard = ["- (yours: what was hard, and why)", ""]
    if stub.exists():
        lines = stub.read_text().splitlines()
        if HARD in lines:
            body = lines[lines.index(HARD) + 1:]
            # The lead's text runs to the first generated section, its own "## " sections included.
            end = next((n for n, line in enumerate(body) if line in GENERATED), len(body))
            kept = body[:end]
            while kept and not kept[0].strip():
                kept = kept[1:]
            hard = [*kept] if kept else hard
            if hard[-1].strip():
                hard.append("")
    lines = [f"# {c.delivery}: friction", "", "Written by the supervisor once the work was done. Write what was hard, "
             "and why, under \"What was hard\", run compound-learning on this note, and record its decision with "
             f"{flow_command()} lead-compound. The other sections are rewritten on each pass until the close-out "
             "archives the note.", "", HARD, "", *hard, "## Shown, never holding", ""]
    lines += [f"- {text}" for text in shown] or ["- (none)"]
    lines += ["", *gaps.friction_section(list(found))]
    stub.parent.mkdir(parents=True, exist_ok=True)
    staging = stub.with_name(f".{stub.name}.{os.getpid()}")
    staging.write_text("\n".join(lines))
    os.replace(staging, stub)
    return stub


def archived_stub(c, archive: Path, said: list[str]) -> Path:
    """The friction stub's archived copy, with "What the close-out left to you" written after the archive, once."""
    note = archive / c.flow_log.name / friction_stub_path(c).name
    text = note.read_text() if note.exists() else ""
    if LEFT not in text.splitlines():
        lines = [LEFT, ""]
        lines += [f"- {line}" for line in said if line.startswith("left ")]
        lines += [f"- The lead runs `lead-retire`, which removes its checkout {c.lane_checkout(c.delivery)} once "
                  "nothing of the delivery runs from it and the archive holds its record, and names what keeps it.",
                  "- The lead ends or archives each lane session it started, where its host lets it, and names any it "
                  "can't to you.", ""]
        note.parent.mkdir(parents=True, exist_ok=True)
        note.write_text(text + ("" if not text or text.endswith("\n") else "\n") + "\n".join(lines))
    return note


def close_out(c, flapping: tuple[str, ...] = (), wait: bool = False) -> tuple[list[str], bool]:
    """C6, in order. Returns (what it did, whether the delivery is closed and the supervisor may stop)."""
    said = []
    for step in (lambda c: full_health_step(c, wait), lambda c: followups_step(c, load_state()), closed_step):
        ok, line = step(c)
        said.append(line)
        if not ok:
            return said, False
    doc = load_state()
    closed = latest_close(doc["journal"])
    if kept_close(c, closed) is None:
        if decision_owed(c, doc):
            # A delivery.closed journalled by hand: the archive waits for the decision, as lead-close does.
            said.append(f"held before the archive: {DECISION_HOLD} is not recorded; record it with "
                        f"{flow_command()} lead-compound")
            return said, False
        # The stub as known now, written first when no pass wrote it, so every supervised close archives one.
        # Read once the steps above ran, so a filing the publisher refused for good during them is listed.
        shown = [item["text"] for item in needs_you(c, doc, flapping, closing=True) if not item["holding"]]
        write_friction_stub(c, shown, gaps.gaps(doc["journal"], REOPENING))
    archive, archived = archive_step(c, closed)
    said += archived
    said += finish_close(c, closed, archive)
    doc = load_state()
    found = gaps.gaps(doc["journal"], REOPENING)
    report = workflow_gaps_step(c, archive, found)
    note = archived_stub(c, archive, archived)
    marker = lead_file(c, "closed.json")
    marker.write_text(json.dumps({**load_json(marker), "friction": str(note),
                                  **({"workflowGaps": str(report)} if report else {})}, indent=2) + "\n")
    if report:
        said.append(f"wrote the workflow gaps {report}: sending it on is your call")
    said.append(f"archived the friction note {note}; the lead archives the lane sessions it started and runs "
                f"{flow_command()} lead-retire")
    return said, True


SUITE_OWNER = "owner.json"


def suite_folder(c) -> Path:
    """Where lead-suite makes its checkouts: the binding's work folder's `suite/`."""
    binding = c.shelf.json(".agents/orchestration.json") or {}
    return c.root / (binding.get("workRoot") or f"{c.work}/work") / "suite"


def cwd_holders(path: Path) -> list[int]:
    """The processes whose working directory is `path` or inside it, as lsof names them."""
    listing = run(["lsof", "-nP", "-d", "cwd", "-Fpn"], check=False).stdout
    found, pid = [], None
    root = path.resolve()
    for line in listing.splitlines():
        if line.startswith("p"):
            pid = int(line[1:]) if line[1:].isdigit() else None
        elif line.startswith("n") and pid is not None:
            here = Path(line[1:])
            if here == root or root in here.parents:
                found.append(pid)
    return sorted(set(found))


def stale_suite_checkout(checkout: Path) -> tuple[str | None, str]:
    """What keeps a lead-suite checkout from being removed safely, or None, and the commit it holds. It is removed only
    when its run has ended (the pid its folder names is gone), no process works inside it, it is detached and it holds
    no change."""
    owner = json_object(checkout.parent / SUITE_OWNER)
    commit = str(owner.get("commit") or checkout.parent.name.split("-", 1)[0])
    if valid_pid(owner.get("pid")) and pid_runs(owner["pid"]):
        return f"its run (pid {owner['pid']}) is still going", commit
    held = cwd_holders(checkout)
    if held:
        return f"process {', '.join(map(str, held))} works inside it", commit
    if run(["git", "symbolic-ref", "-q", "HEAD"], cwd=checkout, check=False).returncode == 0:
        return "it is on a branch, not detached", commit
    status = run(["git", "status", "--porcelain"], cwd=checkout, check=False)
    if status.returncode != 0:
        return f"git can't read it: {(status.stderr or status.stdout).strip()[-200:]}", commit
    if status.stdout.strip():
        return "it holds uncommitted changes", commit
    return None, commit


def clear_suite_checkouts(c) -> tuple[list[str], dict[str, str]]:
    """Remove each checkout an interrupted lead-suite left under the work folder, which the merge queue's serve refuses
    to run beside, when that is safe: what was removed, and each one kept with why and how to remove it."""
    folder = suite_folder(c)
    removed, kept = [], {}
    for checkout in sorted(folder.glob("*/checkout")) if folder.is_dir() else []:
        why, commit = stale_suite_checkout(checkout)
        if why is None:
            run(["git", "worktree", "remove", "--force", str(checkout)], cwd=c.root, check=False)
            shutil.rmtree(checkout.parent, ignore_errors=True)
            run(["git", "worktree", "prune"], cwd=c.root, check=False)
            removed.append(f"removed the lead-suite checkout of {commit[:12]} that a run left at {checkout}")
        else:
            kept[str(checkout)] = (f"A lead-suite checkout of {commit[:12]} is left at {checkout}, and the merge queue's "
                                   f"serve refuses to run while it is under the work folder, but {why}. Once no run "
                                   f"uses it, remove it: git worktree remove --force {checkout}")
    return removed, kept


def last_line(path: Path) -> str:
    try:
        lines = [line for line in path.read_text(errors="replace").splitlines() if line.strip()]
    except OSError:
        return ""
    return lines[-1].strip()[-300:] if lines else ""


def running_pointer(c) -> Path | None:
    """The repository's `.agent-skills/current`, when it resolves to the generation this tool runs from; else None."""
    pointer = c.root / ".agent-skills/current"
    try:
        return pointer if pointer.resolve() == GENERATION else None
    except (OSError, RuntimeError):
        return None


class Supervisor:
    """lead-run: one process per record. It holds the flow log's supervisor lock, recording its pid, start time,
    children and the live view's address; keeps `serve` and the live view running; and runs one pass after another
    until the delivery closes or lead-close asks it to stop. The view runs in a session of its own and outlives it:
    a starting supervisor adopts the view `live.json` names while it serves, and the delivery's close stops it."""

    def __init__(self, c, once: bool):
        self.c, self.once = c, once
        self.children: dict[str, subprocess.Popen] = {}
        # The live view: its pid, and its handle when this supervisor started it rather than adopting it.
        self.view_pid: int | None = None
        self.view: subprocess.Popen | None = None
        # What it says before its first line, the address, is printed: held until then.
        self.held_lines: list[str] | None = []
        # The handlers its own signal handler stands in front of.
        self.before_signals: dict[int, object] = {}
        self.signalled: int | None = None
        self.restarts: dict[str, list[float]] = {}
        # When each child last started, so a flapping child reads as cleared only once it has stayed up for a pass.
        self.started_at: dict[str, float] = {}
        self.address: str | None = None
        self.handle = None
        self.started = now()
        # The Node its children run, as it started: recorded in its lock for doctor --delivery to judge.
        found = node_on_path()
        self.node = {"path": found[0], "version": dotted(found[1]) if found[1] else None} if found else None
        # Why it stopped serving, once what it serves is gone: then it exits instead of passing on over nothing.
        self.lost: str | None = None
        # The applied generation's pointer it watches, when it runs from the generation that pointer resolves to; and
        # the generation the pointer has moved to since, once it has: then it stops and starts again on that one.
        self.watched: Path | None = running_pointer(c)
        self.moved_to: Path | None = None
        # The `caffeinate` that keeps the machine awake while it runs, on macOS.
        self.awake: subprocess.Popen | None = None

    def gone(self) -> str | None:
        """What it serves that is no longer there: its record (the record's state file, which the state tool only ever
        replaces whole, so a folder a removal left behind, or one a writer made again, doesn't count), or the install
        it runs from (this file, inside the generation)."""
        if not (self.c.state / "state.json").is_file():
            return f"its record {self.c.state} is gone"
        if not Path(__file__).exists():
            return f"its install {GENERATION} is gone"
        return None

    def moved(self) -> Path | None:
        """The generation `.agent-skills/current` resolves to now, once that is no longer the one it runs, holds this
        tool and is the one the receipt names, which the lifecycle writes just after it moves the pointer: a release
        applied while it runs. It says so in its log the first time. Never for --once."""
        if self.moved_to is None and self.watched is not None and not self.once:
            with contextlib.suppress(OSError, RuntimeError, ValueError):
                target = self.watched.resolve()
                if (target != GENERATION and (target / GENERATION_TOOL).is_file()
                        and json_object(receipt_path(self.c)).get("generation") == target.name):
                    self.moved_to = target
                    print(f"{now()} supervisor: {self.watched} now resolves to {target.name}, not {GENERATION.name}: "
                          "stopping to start again on it", flush=True)
        return self.moved_to

    def keep_awake(self) -> None:
        """On macOS, hold `caffeinate -i -w <its pid>`, which keeps the machine from idle sleep until this process
        exits, however it exits. Elsewhere, or with no caffeinate on PATH, nothing; doctor says so."""
        program = shutil.which("caffeinate") if sys.platform == "darwin" else None
        if not program:
            return
        try:
            self.awake = subprocess.Popen([program, "-i", "-w", str(os.getpid())], stdin=subprocess.DEVNULL,
                                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except OSError as error:
            self.say(f"couldn't keep the machine awake: {program} didn't start: {error}")
            return
        self.say(f"keeping the machine awake while it runs: {program} -i -w {os.getpid()} (pid {self.awake.pid})")

    def lose(self) -> bool:
        """Whether it has lost what it serves, or a newly applied generation should serve it instead; the first time
        it loses what it serves, it says so in its log, which stays open."""
        if self.moved():
            return True
        if self.lost is None:
            self.lost = self.gone()
            if self.lost:
                print(f"{now()} supervisor: stopping: {self.lost}", flush=True)
        return self.lost is not None

    def write_lock(self) -> None:
        self.handle.seek(0)
        self.handle.truncate()
        self.handle.write(json.dumps({"pid": os.getpid(), "startedAt": self.started, "address": self.address,
                                      "node": self.node,
                                      "children": [{"name": name, "pid": proc.pid} for name, proc in self.children.items()]
                                      + ([{"name": "live", "pid": self.view_pid}] if self.view_pid else [])}))
        self.handle.flush()

    def child_argv(self, name: str) -> list[str] | None:
        c = self.c
        if name == "collab":
            # The sync loop of a shared record: pushes this seat's partition and ingests its peers'.
            return [sys.executable, "-B", str(c.release / "skills/orchestrate-work/scripts/collab.py"), "serve",
                    "--dir", str(c.state), "--remote", c.remote, "--poll", str(collab_settings(c)["pollSeconds"])]
        scripts = c.release / "skills/orchestrate-work/scripts"
        config = binding_state(c)
        if name == "live":
            return [sys.executable, "-B", str(scripts / "render_state.py"), "live", "--dir", str(c.state),
                    "--repo", str(c.root), *(["--state-config", json.dumps(config)] if config is not None else [])]
        if config is None:
            return None  # the queue needs a binding
        if str(scripts) not in sys.path:
            sys.path.insert(0, str(scripts))
        import delivery_state
        with contextlib.suppress(delivery_state.StateError, OSError):
            # On a shared record the queue is served only where this checkout's seat holds it.
            shared = delivery_state.collab_of(delivery_state.read_state(c.state))
            if shared is not None and not delivery_state.holds(
                    delivery_state.read_journal(c.state), delivery_state.local_seat(c.state, shared["key"]), "queue"):
                return None
        return [sys.executable, "-B", str(scripts / "merge_queue.py"), "--repo", str(c.root), "--state", str(c.state),
                "--remote", c.remote, "--base", c.base_branch, "serve", "--poll",
                str(min(30.0, supervisor_pass_seconds(c)))]

    def wanted_children(self) -> list[str]:
        """The children this machine serves: a planning record's sync loop; the queue, on an unshared record; on a
        shared one the sync loop, and the queue only where this seat holds it, so a seat given the queue starts it on
        the pass after it ingests the transfer."""
        if planning_phase(self.c):
            return ["collab"]
        shared = seat_roles(self.c) is not None
        return [*(["collab"] if shared else []), *(["serve"] if self.child_argv("serve") is not None else [])]

    def align_children(self) -> None:
        """Start each wanted child that isn't running; one that exited is keep_alive's."""
        for name in self.wanted_children():
            if name not in self.children:
                self.start(name)

    def start(self, name: str) -> None:
        argv = self.child_argv(name)
        if argv is None:
            return
        log = lead_file(self.c, f"supervisor.{name}.log")
        with open(log, "a") as out:
            # In the supervisor's own group, so stopping the group stops them; signals are the defaults it set.
            self.children[name] = subprocess.Popen(argv, cwd=self.c.root, stdin=subprocess.DEVNULL, stdout=out,
                                                   stderr=subprocess.STDOUT)
        self.started_at[name] = time.monotonic()
        self.write_lock()

    def start_live(self) -> None:
        """Adopt the view `live.json` names while it serves from this generation's render_state.py; otherwise start
        one, on the recorded port, else the derived one, else, when another process holds that, a free one. A view
        of another generation is stopped by its pid and replaced on its port; a recorded pid that runs but doesn't
        listen on its port is left alone."""
        c = self.c
        script = str((c.release / "skills/orchestrate-work/scripts/render_state.py").resolve())
        live = recorded_live(c.state)
        setting = live_port_setting()
        if live and pid_runs(live["pid"]) and listens(live["pid"], live["port"]):
            if live.get("renderState") == script:
                self.view_pid, self.view = live["pid"], None
                self.started_at["live"] = time.monotonic()
                self.address = live_address(live["port"])
                self.write_lock()
                self.say(f"adopted the live view (pid {live['pid']}) on {self.address}")
                return
            self.say(f"the live view (pid {live['pid']}) runs {live.get('renderState')}, not this generation's "
                     f"{script}: {stop_view(c.state)}")
            free = time.monotonic() + 10
            while port_open(live["port"]) and time.monotonic() < free:
                time.sleep(0.1)
        elif live and pid_runs(live["pid"]):
            self.say(f"live.json's pid {live['pid']} runs but doesn't listen on port {live['port']}; it is left alone "
                     "and a new view started")
        # A recorded port first, so the address survives; RUN_DELIVERY_LIVE_PORT=0 stands in for the derived one.
        wanted = (live["port"] if live else 0) if setting == 0 else wanted_live_port(c.state, live_top(c), c.delivery)
        fallback = None
        holders = port_takers(wanted) if wanted else []
        if holders:
            fallback, port = (wanted, holders), 0
        else:
            port = wanted
        started = self.spawn_view(port)
        if started is None:  # the port was taken between the look and the bind
            fallback = (port, port_takers(port))
            started = self.spawn_view(0)
        proc, bound = started
        self.view, self.view_pid, self.address = proc, proc.pid, live_address(bound)
        self.started_at["live"] = time.monotonic()
        record = {"port": bound, "pid": proc.pid, "renderState": script, "startedAt": now(), "address": self.address}
        if fallback:
            record["fallback"] = {"wanted": fallback[0],
                                  "heldBy": [{"pid": pid, "command": command} for pid, command in fallback[1]]}
            self.say(f"the live view serves on {self.address}: {held_words(*fallback)}")
        staging = c.state / f".{LIVE_FILE}.{os.getpid()}"
        staging.write_text(json.dumps(record, indent=2) + "\n")
        os.replace(staging, c.state / LIVE_FILE)
        self.write_lock()

    def spawn_view(self, port: int) -> tuple[subprocess.Popen, int] | None:
        """Start the view on `port` (0: a free one) in a session of its own, and wait until it says where it serves.
        None when it couldn't listen on a port it was given, so the caller binds a free one instead."""
        c = self.c
        argv = [*self.child_argv("live"), "--port", str(port), "--status-file", str(c.state / SUPERVISOR_FILE)]
        return spawn_live_view(argv, lead_file(c, "supervisor.live.log"), c.root, port)

    def say(self, line: str) -> None:
        """A line on the supervisor's output: held until the address is printed, so that stays its first line."""
        if self.held_lines is None:
            print(f"{now()} supervisor: {line}", flush=True)
        else:
            self.held_lines.append(line)

    def view_down(self) -> bool:
        if self.view is not None:
            return self.view.poll() is not None
        return self.view_pid is not None and process_gone(self.view_pid)

    def flapping(self) -> tuple[str, ...]:
        horizon = time.monotonic() - CHILD_FLAP_SECONDS
        return tuple(name for name, times in self.restarts.items()
                     if len([t for t in times if t > horizon]) >= CHILD_FLAPS)

    def blockers(self) -> str:
        """Journal what the supervisor finds holding the delivery, so the lead's wait hears it: a blocker.recorded when a
        child first won't stay up, and when a stale lead-suite checkout can't be removed safely; a blocker.resolved,
        with its reason in the resolutions log, when the child has stayed up for a pass or the checkout has gone. Each
        is recorded once, keyed in the flow log's supervisor.blockers.json."""
        c = self.c
        path = lead_file(c, "supervisor.blockers.json")
        open_ = {k: v for k, v in json_object(path).items() if type(v) is int}
        removed, kept = clear_suite_checkouts(c)
        said = list(removed)
        holding: dict[str, str] = {f"suite:{where}": text for where, text in kept.items()}
        flapping = self.flapping()
        for name in flapping:
            log = lead_file(c, f"supervisor.{name}.log")
            line = last_line(log)
            holding[f"child:{name}"] = (f"The supervisor's {name} won't stay up; its log is {log}"
                                        + (f", whose last line is: {line}" if line else ""))
        settled = {}
        for key in open_:
            if key in holding:
                continue
            if key.startswith("child:"):
                name = key.split(":", 1)[1]
                # The live view is held apart from the children, adopted or started; every other child is one of them.
                proc = self.children.get(name)
                running = (self.view_pid is not None and not self.view_down()) if name == "live" else \
                    proc is not None and proc.poll() is None
                up = running and \
                    time.monotonic() - self.started_at.get(name, time.monotonic()) >= supervisor_pass_seconds(c)
                if not up:
                    holding[key] = ""  # still down, or not up long enough: kept open, not recorded again
                    continue
                settled[key] = f"the supervisor's {name} has stayed up for a pass"
            else:
                settled[key] = f"the lead-suite checkout {key.split(':', 1)[1]} is gone"
        doc = load_state() if settled or any(k not in open_ for k in holding) else None
        resolutions = {r.get("journal") for r in read_log("resolutions", c.delivery)}
        for key, why in settled.items():
            number = open_.pop(key)
            entry = next((e for e in doc["journal"] if e["id"] == number), None)
            if entry is not None and not blocker_resolved(c, doc, entry, resolutions):
                append_log("resolutions", c.delivery, {"journal": number, "why": why})
                state_tool("journal", "--kind", "blocker.resolved", "--data", json.dumps({"why": why}),
                           "--answers", str(number))
                said.append(f"resolved blocker {number}: {why}")
        for key, text in holding.items():
            if key in open_ or not text:
                continue
            open_[key] = journal_id(state_tool("journal", "--kind", "blocker.recorded", "--text", text))
            said.append(f"recorded blocker {open_[key]}: {text[:120]}")
        path.write_text(json.dumps(open_, indent=2) + "\n")
        return "; ".join(said) or "none"

    def keep_alive(self) -> None:
        """Restart a child that exited, at most once a pass once it has exited CHILD_FLAPS times in the window: a
        child that won't stay up is shown in "Needs you", and a restart that fails never ends the supervisor."""
        down = [name for name, proc in self.children.items() if proc.poll() is not None]
        for name in [name for name in down if self.child_argv(name) is None]:
            # No longer this machine's to serve, as the queue once handed to another seat: dropped, never restarted,
            # so its exit is no blocker.
            del self.children[name]
            self.restarts.pop(name, None)
            down.remove(name)
            self.write_lock()
        for name in down + (["live"] if self.view_pid and self.view_down() else []):
            times = self.restarts.setdefault(name, [])
            if name in self.flapping() and times and time.monotonic() - times[-1] < supervisor_pass_seconds(self.c):
                continue
            times.append(time.monotonic())
            try:
                self.start_live() if name == "live" else self.start(name)
            except (Stop, OSError) as error:
                with open(lead_file(self.c, f"supervisor.{name}.log"), "a") as log:
                    log.write(f"{now()} restart failed: {error}\n")

    def stop_asked(self) -> bool:
        return lead_file(self.c, "supervisor.stop").exists()

    def stop_reason(self) -> str:
        """The reason the stop request carries; lead-close's `held` when it names none."""
        why = json_object(lead_file(self.c, "supervisor.stop")).get("why")
        return why if isinstance(why, str) and why else "held"

    def on_signal(self, number: int, frame) -> None:
        """Record the signal in supervisor.json, unless whoever sent it recorded why first, then do what the signal
        did before: the tool's own handler, which unwinds through `finally`, or the default."""
        status = json_object(self.c.state / SUPERVISOR_FILE)
        if not (status.get("pid") == os.getpid() and status.get("state") == "stopped"):
            with contextlib.suppress(OSError):
                write_supervisor_status(self.c.state, os.getpid(), False, "signal", signal.Signals(number).name)
        self.signalled = number
        before = self.before_signals.get(number, signal.SIG_DFL)
        if callable(before):
            before(number, frame)
            return
        signal.signal(number, signal.SIG_DFL)
        os.kill(os.getpid(), number)

    def honour_signal(self) -> None:
        """A signal's raise can be lost where Python cannot raise, as while it compiles a module a pass imports:
        CPython before 3.14 drops it there. The recorded signal is honoured at the pass's next step or wait."""
        if self.signalled is not None:
            self.on_signal(self.signalled, None)

    def stop_children(self) -> None:
        for proc in self.children.values():
            if proc.poll() is None:
                proc.terminate()
        deadline = time.monotonic() + 10
        for proc in self.children.values():
            with contextlib.suppress(subprocess.TimeoutExpired):
                proc.wait(timeout=max(0.1, deadline - time.monotonic()))
            if proc.poll() is None:
                proc.kill()
                proc.wait()

    def one_pass(self, number: int) -> bool:
        c = self.c
        started = time.monotonic()
        entry: dict = {"pass": number, "startedAt": now()}
        try:
            c.load_delivery(c.delivery)
        except (Stop, ValueError) as error:  # a delivery file saved mid-edit
            entry["delivery"] = f"not reread: {error}"
        derived: dict = {}

        def derive() -> str:
            # After the publishers, so their ledger is current; before the views, so the line map shows this list.
            derived["doc"] = load_state()
            derived["needs"] = needs_you(c, derived["doc"], self.flapping())
            write_needs(c, derived["needs"], number, started)
            return f"{len(derived['needs'])} item(s)"

        earlier = read_log("supervisor", c.delivery)
        remembered = (earlier[-1].get("laneWords") if earlier else None) or {}

        def cleanup() -> list[str]:
            doc = load_state()
            entry["laneWords"] = lane_words(doc, remembered)
            return cleanup_merged(c, doc, entry["laneWords"])

        planning = planning_phase(c)
        roles = seat_roles(c)
        if roles is not None and roles["delivery"]:
            # Before any step publishes: what the seat that gave this one delivery carried becomes this machine's.
            with contextlib.suppress(Stop, OSError, ValueError, subprocess.SubprocessError):
                taken = take_delivery(c)
                if taken:
                    entry["delivery"] = taken
        steps = (("inputs", lambda: inputs_step(c)), ("reconcile", reconcile_once), ("regions", lambda: settle_landings(c)), ("cleanup", cleanup), ("fullHealth", lambda: post_merge_step(c, self.once)),
                 ("peers", lambda: self.peer_merges(entry)), ("grants", lambda: auto_grant_step(c)),
                 ("planView", lambda: planning_plan_step(c)),
                 ("lenses", lambda: journal_lens_returns(c)),
                 ("finish", lambda: journal_finish_met(c, load_state())),
                 ("deferrals", lambda: deferral_breaches(c, load_state())),
                 ("peerWaits", lambda: write_peer_waits(c)), ("laneChanges", lambda: write_lane_changes(c)),
                 ("publish", lambda: render_views(c, only="publishers")),
                 ("blockers", self.blockers), ("needs", derive),
                 ("render", lambda: render_views(c, only="renderers")), ("latest", lambda: str(copy_latest(c))))
        if planning:
            # While the plan is drafted: its plan, section grants, the views and the record's copy only; no queue,
            # tracker or full health.
            steps = tuple((name, step) for name, step in steps if name in PLANNING_STEPS)
        else:
            # A delivery's plan is built by the commands that change it.
            steps = tuple((name, step) for name, step in steps if name != "planView")
        for name, _ in steps:
            if not step_runs(roles, name):
                entry[name] = f"held by another seat: {SHARED_STEPS[name]}"
        steps = tuple((name, step) for name, step in steps if step_runs(roles, name))
        for name, step in steps:
            self.honour_signal()
            if self.lose():
                return False
            try:
                entry[name] = step()
            except (Stop, ValueError, OSError, subprocess.SubprocessError) as error:
                entry[name] = f"failed: {error}"
        closed = False
        try:
            if planning:
                # Nothing to close, and its list is what the pass found: blocking feedback holds approval, not a close.
                entry["needsYou"] = derived.get("needs", [])
                raise Planning
            if not step_runs(roles, "closeOut"):
                # The delivery holder's machine closes; this one's list is what the pass found. Once that machine has
                # archived the close, this one counts the delivery closed too, and its supervisor stops.
                entry["needsYou"] = derived.get("needs", [])
                closed = closed_by_holder(c)
                raise HeldElsewhere
            doc = derived.get("doc") or load_state()
            needs = derived["needs"] if "needs" in derived else needs_you(c, doc, self.flapping())
            holds = close_holds(c, doc, needs)
            if all(hold.startswith("not cleaned up: ") for hold in holds):
                # A lane may have moved off its story since this pass's cleanup, as its last word: clean up again, so
                # the close never outruns the checkout it leaves, then read the holds again. A checkout this cleanup
                # still can't remove keeps holding the close until a later pass removes it.
                entry["cleanupBeforeClose"] = cleanup()
                holds = close_holds(c, load_state(), needs)
            entry["needsYou"], entry["closeHeldBy"] = needs, holds
            # The friction stub, first written once only the decision holds the close, then kept current until the
            # close-out archives it.
            if holds == [DECISION_HOLD] or (holds and friction_stub_path(c).exists()
                                            and kept_close(c, latest_close(doc["journal"])) is None):
                fresh = load_state()
                entry["friction"] = str(write_friction_stub(
                    c, [item["text"] for item in needs if not item["holding"]], gaps.gaps(fresh["journal"], REOPENING)))
            if not holds:
                entry["closeOut"], closed = close_out(c, self.flapping(), self.once)
                if closed:
                    entry["carried"] = carry_close(c)
                render_views(c)
        except Planning:
            entry["close"] = "planning: nothing to close"
        except HeldElsewhere:
            entry["close"] = ("closed and archived by the delivery holder's machine" if closed
                              else "closed by the delivery holder's machine")
        except (Stop, ValueError, OSError, subprocess.SubprocessError) as error:
            entry["close"] = f"failed: {error}"
        if self.lose():
            return False
        entry["finishedAt"] = now()
        append_log("supervisor", c.delivery, entry)
        return closed

    def peer_merges(self, entry: dict) -> str:
        """Journal `peer.merged` for each `candidate.merged` of a peer on this base, since this record began, that it
        hasn't handled and whose merge changed a file one of this delivery's open stories names: one entry a story,
        naming the peer, its story and the files. How far it has read each peer's journal is kept in the flow log's
        `peers` log, written as soon as each entry is journalled, and shown as the pass's `peerReads`, so a supervisor
        started again journals nothing twice; a merge whose commit isn't on the base here yet is read again later."""
        c = self.c
        reads: dict[str, int] = {}
        for read in read_log("peers", c.delivery):
            if isinstance(read.get("peer"), str) and type(read.get("through")) is int:
                reads[read["peer"]] = max(read["through"], reads.get(read["peer"], 0))
        entry["peerReads"] = reads
        peers = [peer for peer in peer_deliveries(c) if peer["status"] != "unreadable"]
        if not peers:
            return "no peers"
        scripts = str(c.release / "skills/orchestrate-work/scripts")
        if scripts not in sys.path:
            sys.path.insert(0, scripts)
        import delivery_state
        doc = load_state()
        state, journal = doc["state"], doc["journal"]
        began = journal[0]["at"] if journal else now()
        done = ({item["subject"] for item in state["queue"] if item.get("stage") == "merged"}
                | {item["subject"] for item in state.get("planned", []) if item.get("stage") == "settled"})
        tracked = tracked_at_base(c)
        named = {key: set(story_named_files(c, key, tracked)) for key in c.stories if key not in done}
        said = []
        for peer in peers:
            try:
                theirs = delivery_state.read_journal(Path(peer["state"]))
            except (delivery_state.StateError, OSError, ValueError):
                said.append(f"{peer['key']}: its journal can't be read")
                continue
            through = start = reads.get(peer["key"], 0)
            for merged in theirs:
                if merged["id"] <= through:
                    continue
                if merged["kind"] == "candidate.merged" and merged["at"] >= began:
                    found = self.peer_merge_files(peer, merged)
                    if found is None:
                        said.append(f"{peer['key']}: {merged['subject']}'s merge isn't on {c.base_ref} yet")
                        break
                    commit, files = found
                    for key, names in named.items():
                        hit = sorted(files & names)
                        summary = (f"{peer['key']}, a delivery on {c.base_branch}, merged {merged['subject']} at "
                                   f"{commit[:10]}, changing {', '.join(hit)}, which {key} names")
                        if hit:
                            lane = c.lane_of(key, state)
                            state_tool("journal", "--kind", "peer.merged", "--subject", key,
                                       *(["--lane", lane] if lane else []), "--data",
                                       json.dumps({"peer": peer["key"], "head": commit, "files": hit}))
                            said.append(summary)
                    # Kept at once, so a supervisor stopped mid-pass doesn't journal this merge again.
                    append_log("peers", c.delivery, {"peer": peer["key"], "through": merged["id"]})
                through = reads[peer["key"]] = merged["id"]
            if through != start:
                append_log("peers", c.delivery, {"peer": peer["key"], "through": through})
        return "; ".join(said) or "nothing new"

    def peer_merge_files(self, peer: dict, merged: dict) -> tuple[str, set[str]] | None:
        """The commit a peer's merge made and the files it changed. The head comes from the entry's facts, the runner's or one
        recovered from a forge snapshot, else from the peer's queue. The commit is the base's
        first-parent commit whose tree is that head's, diffed against its first parent. For a merge no such commit
        matches, even once the base is fetched (a merge commit, a squash of a head behind the base, or one too far
        back), it is the head, diffed against its merge base with the base. The fetch comes first because nothing else
        in a pass is sure to: a peer's runner fetches into a ref of its own, and the post-merge step fetches only when
        it runs a check. An entry that names no head changed nothing this can see. None while the head isn't in this
        repository, even after the fetch, so a later pass reads it again."""
        c = self.c
        head = merged["data"].get("head")
        item = next((q for q in json_object(Path(peer["state"]) / "state.json").get("queue") or []
                     if isinstance(q, dict) and q.get("subject") == merged.get("subject")), {})
        synced = head or item.get("syncedHead") or item.get("head")
        if not isinstance(synced, str) or not synced:
            return "", set()
        def on_base() -> str | None:
            tree = git("rev-parse", f"{synced}^{{tree}}", check=False)
            rows = git("log", "--first-parent", "-n", "500", "--format=%H %T", c.base_ref, check=False).splitlines()
            return next((row.split()[0] for row in rows if tree and row.endswith(f" {tree}")), None)

        known = lambda: git("rev-parse", "--verify", "-q", f"{synced}^{{commit}}", check=False)
        commit = on_base() if known() else None
        if commit is None:
            git("fetch", "-q", c.remote, c.base_branch, check=False)
            if not known():
                return None
            commit = on_base()
        if commit:
            return commit, set(git("diff", "--name-only", f"{commit}^1", commit, check=False).splitlines())
        since = git("merge-base", c.base_ref, synced, check=False)
        return synced, set(git("diff", "--name-only", since, synced, check=False).splitlines()) if since else set()

    def run(self) -> None:
        c = self.c
        # Detached by its own session, never by ignoring signals: its children start with the defaults.
        for number in (signal.SIGINT, signal.SIGQUIT):
            signal.signal(number, signal.SIG_DFL)
        lock = supervisor_lock_path(c)
        lock.parent.mkdir(parents=True, exist_ok=True)
        held, recorded = read_lock(lock)
        if held:
            raise Stop(f"a supervisor already runs (pid {recorded.get('pid')}); live view {recorded.get('address')}")
        orphans = [child for child in recorded.get("children") or [] if isinstance(child, dict)
                   and valid_pid(child.get("pid")) and group_of(child["pid"]) == recorded.get("pid")]
        if orphans:
            raise Stop(f"the earlier supervisor (pid {recorded.get('pid')}) left children running; "
                       f"{flow_command()} lead-run --resume stops them and starts it again")
        self.handle = open(lock, "a+")
        try:
            fcntl.flock(self.handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            self.handle.close()
            raise Stop("another supervisor took the lock first")
        try:
            require_no_base_move(c)
        except Stop:
            self.handle.close()
            raise
        lead_file(c, "supervisor.stop").unlink(missing_ok=True)
        closed, stopped_by = False, None
        try:
            self.write_lock()
            with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                register_delivery(c, os.getpid())
            start_hosted(c)
            if not self.once:
                # Who stops it says why in supervisor.json; a signal nobody explained is recorded by the supervisor.
                write_supervisor_status(c.state, os.getpid(), True)
                for number in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
                    self.before_signals[number] = signal.signal(number, self.on_signal)
                self.keep_awake()
                self.start_live()
                with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                    for line in clear_suite_checkouts(c)[0]:
                        self.say(line)
                # A planning record has no queue yet: its one child beside the view is the sync loop.
                self.align_children()
                print(self.address, flush=True)  # the first line: where the delivery is watched
                lines, self.held_lines = self.held_lines or [], None
                for line in lines:
                    self.say(line)
            number = len(read_log("supervisor", c.delivery))
            while True:
                number += 1
                if not self.once:
                    self.align_children()
                closed = self.one_pass(number)
                self.honour_signal()
                if closed or self.once or self.stop_asked() or self.lose():
                    break
                deadline = time.monotonic() + supervisor_pass_seconds(c)
                while time.monotonic() < deadline and not self.stop_asked():
                    self.honour_signal()
                    if self.lose():
                        break
                    self.keep_alive()
                    time.sleep(0.2)
                if self.stop_asked() or self.lost or self.moved_to:
                    break
            if not closed and self.stop_asked():
                stopped_by = self.stop_reason()
            elif not closed and self.moved_to:
                stopped_by = "upgrade"
        finally:
            self.stop_children()
            if self.awake is not None and not self.moved_to:
                # Its caffeinate ends with it anyway; stopped here so none outlives a supervisor that returns. One
                # that starts again on a new generation keeps it, and the pid it watches, until that one starts.
                self.awake.terminate()
                with contextlib.suppress(subprocess.TimeoutExpired):
                    self.awake.wait(timeout=5)
            # Drawn and copied once more, so neither the line map nor `latest` keeps the last running list; not when
            # the record or install is gone, which would only write a record back that no one is serving.
            if not self.lost:
                with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                    write_needs(c, None, len(read_log("supervisor", c.delivery)), time.monotonic())
                    render_views(c, only="renderers")
                    copy_latest(c)
                    if closed:
                        print(f"{now()} supervisor: drew the views and copied the record one last time", flush=True)
            if closed and not self.lost:
                closing=last_close(load_state()['journal'])
                kept=kept_close(c,closing)
                if kept and closing:
                    final=finalize_hosted(c,Path(kept['archive']),closing)
                    if final.get('state')!='disabled':self.say('hosted: '+final['state'])
                # The delivery's own close: recorded, then the view stopped last, by its recorded pid.
                with contextlib.suppress(OSError):
                    write_supervisor_status(c.state, os.getpid(), False, "close")
                with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                    said = stop_view(c.state, self.view)
                    if said:
                        print(f"{now()} supervisor: {said}", flush=True)
            elif stopped_by and not self.once and not self.lost:
                with contextlib.suppress(OSError):
                    write_supervisor_status(c.state, os.getpid(), False, stopped_by)
            if self.moved_to and self.view is not None:
                # A view it started is its child, which the process it becomes would never reap: stopped here, as the
                # new generation's supervisor would stop it anyway, leaving live.json's port for that one's view.
                with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                    said = stop_view(c.state, self.view)
                    if said:
                        print(f"{now()} supervisor: {said}", flush=True)
            if self.lost and self.view_pid:
                # What it served is gone: so is what its view serves. Stopped by the pid it holds, as live.json may
                # have gone with the record.
                with contextlib.suppress(OSError, Stop, subprocess.SubprocessError):
                    said = stop_view_process(self.view_pid, port_of_address(self.address), self.view)
                    if said:
                        print(f"{now()} supervisor: {said}", flush=True)
            fcntl.flock(self.handle, fcntl.LOCK_UN)
            self.handle.close()


class Planning(Exception):
    """A pass over a planning record, which has nothing to close."""


class HeldElsewhere(Exception):
    """A pass on a seat of a shared record that doesn't hold delivery, whose machine closes nothing."""


# The pass steps a planning record runs.
PLANNING_STEPS = ("inputs", "grants", "planView", "needs", "render", "latest")


def planning_phase(c) -> bool:
    """Whether the delivery's record is a planning record: shared, not yet taken over by lead-init. It reads the record's
    state.json in its folder, as the pass's steps do, so a config with no record, or none shared, reads as not planning."""
    state = getattr(c, "state", None)
    record = load_json(Path(state) / "state.json") if state else None
    return isinstance(record, dict) and (record.get("meta") or {}).get("phase") == "planning"


def lead_run(args) -> None:
    """The delivery's supervisor: lead-init starts it; --resume stops what an earlier one left and starts it again;
    --once runs one pass in the foreground."""
    c = cfg()
    require_no_base_move(c)
    if not (c.state / "state.json").exists():
        raise Stop(f"no record at {c.state}: lead-init starts it, and its supervisor")
    closed = kept_close(c, last_close(load_state()["journal"]))
    if closed and closed.get("by") == "lead-close":
        raise Stop("the delivery is closed: lead-close closed it. " + closed_words(closed))
    # Before the lock, the orphan sweep or any child: the supervisor's children run the Node first on its PATH.
    require_node(c.release, "lead-run --resume" if args.resume else "lead-run")
    if args.resume:
        record_session(c, "lead")
        for line in stop_orphans(c):
            print(line)
        start_hosted(c,resume=True)
        address = start_supervisor(c)
        print(f"supervisor: running; live view {address}{live_fallback(c.state)}" + listener_words(c))
        return
    supervisor = Supervisor(c, once=args.once)
    supervisor.run()
    if supervisor.moved_to is not None:
        restart_on_generation(c, supervisor.watched)


def restart_on_generation(c, pointer: Path) -> None:
    """Replace this supervisor, its lock released and its children stopped, with the newly applied generation's own
    restart, run from `pointer`: `lead-upgrade-writer` when the record pins its writer generation, which moves the pin
    to the applied archive (leaving a pin that already names it as it is) and resumes the supervisor from it, or
    `lead-run --resume` for a record that pins none. Either stops what this one left and starts the supervisor on the
    new generation, which carries on from the record and the flow log, so nothing done is done twice. The hosted
    token, which only this process holds, goes along through the pipe start_supervisor uses."""
    tool = pointer / GENERATION_TOOL
    pinned = (json_object(c.state / "state.json").get("meta") or {}).get("writerGeneration")
    if isinstance(pinned, dict) and isinstance(pinned.get("archiveSha256"), str):
        command = ["lead-upgrade-writer", "--expected", pinned["archiveSha256"], "--reason",
                   f"the supervisor found {pointer.resolve().name} applied at {pointer} and started again on it"]
    else:
        command = ["lead-run", "--resume"]
    argv = [sys.executable, "-B", str(tool), "--delivery", c.delivery, *command]
    print(f"{now()} supervisor: starting again on {pointer.resolve().name}: {shlex.join(argv[2:])}", flush=True)
    environment = dict(os.environ)
    descriptor = hosted_credentials_pipe(c)
    if descriptor is not None:
        os.set_inheritable(descriptor, True)
        environment["RUN_DELIVERY_HOSTED_FD"] = str(descriptor)
    sys.stdout.flush()
    sys.stderr.flush()
    os.chdir(c.root)
    try:
        os.execve(sys.executable, argv, environment)
    except OSError as error:
        raise Stop(f"the supervisor couldn't start again on {pointer.resolve().name}: {error}; run "
                   f"{flow_command()} lead-run --resume") from None


def program_version(program: str, checkout: Path) -> tuple[str | None, str | None]:
    """(the version `program --version` prints in the checkout, or None, and why it could not be read)."""
    try:
        done = subprocess.run([program, "--version"], cwd=checkout, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError) as error:
        return None, f"{program} --version could not run: {error}"
    said = (done.stdout or done.stderr).strip().splitlines()
    if done.returncode != 0 or not said:
        return None, f"{program} --version printed no version" + (f" (exit {done.returncode})" if done.returncode else "")
    return said[0], None


def lead_suite(args) -> None:
    """The lead's own run of the binding's fullHealth, under any posture, at --at or the base head on the remote: in a
    detached checkout of that commit under the binding's work folder, prepared first and removed after, so nothing the
    lead does in its own checkout reaches the run. Its result is one line of the flow log's suite.jsonl, which the lead
    cites when marking a finish line, and, on a record with an integration step, an integration.suite entry."""
    c = cfg()
    binding = c.shelf.json(".agents/orchestration.json") or {}
    if not binding.get("fullHealth"):
        raise Stop("the binding declares no fullHealth, so there is no suite to run")
    git("fetch", "-q", c.remote, c.base_branch, check=False)
    if args.at:
        commit = git("rev-parse", "--verify", "--quiet", f"{args.at}^{{commit}}", check=False)
        if not commit:
            raise Stop(f"{args.at} is no commit in this repository; fetch it, or name another")
    else:
        commit = base_head(c)
    argv = [*binding["fullHealth"], *(args.extra[1:] if args.extra[:1] == ["--"] else args.extra)]
    why = now_and_why(args)
    machine = machine_module()
    # The run's claim comes before its checkout is made and prepared, and is held until both are gone.
    held = heavy_claim("suite", "lead-suite", label=f"lead-suite {c.delivery}", now_why=why,
                       repository=machine_repository(), delivery=c.delivery)
    with held, claimed_environment(held):
        if why is not None and stepped_off(held):
            journal_override(c, c.delivery, f"ran lead-suite at {commit[:10]} at once, stepping off the machine's wait",
                             why)
        began, cpu = time.monotonic(), cpu_mark()
        code = 1
        try:
            code = suite_run(c, binding, commit, argv)
        finally:
            held.record_cost(measured_since(machine, code, began, cpu, code == 0))
    if code:
        raise SystemExit(code if 0 < code < 256 else 1)


def suite_run(c, binding: dict, commit: str, argv: list[str]) -> int:
    """lead-suite's run of argv at commit, in a detached checkout of its own, recorded in the flow log and, on a
    record with an integration step, the journal. Returns its exit."""
    folder = c.root / (binding.get("workRoot") or f"{c.work}/work") / "suite"
    folder.mkdir(parents=True, exist_ok=True)
    checkout = Path(tempfile.mkdtemp(prefix=f"{commit[:12]}-", dir=folder)) / "checkout"
    # Whose run the folder is: a checkout an interrupted run leaves is the supervisor's to remove once this pid is gone.
    (checkout.parent / SUITE_OWNER).write_text(json.dumps({"pid": os.getpid(), "commit": commit, "startedAt": now()}))
    # A stop ends the run through main's handler, as an interruption does: its command's group is stopped, by
    # run_group, and its checkout removed, by in_detached_checkout.
    began = time.monotonic()
    integration = record_integration()
    if integration:
        suite_started(c, commit, argv)

    def suite(checkout: Path) -> tuple[int, str, tuple[str | None, str | None], float | None]:
        asked = program_version(argv[0], checkout)
        try:
            code, out = run_group(argv, checkout, full_health_timeout(binding))
        except Stop as error:  # its timeout: a failure, with the version already read
            code, out = 1, str(error)
        return code, out, asked, suite_budget(argv, checkout)
    print(f"lead-suite: running {shlex.join(argv)} at {commit[:10]} in {checkout}", flush=True)
    started = True
    try:
        code, out, (version, unread), budget = in_detached_checkout(c, commit, checkout, suite,
                                                                    full_health_timeout(binding))
    except Stop as error:  # the checkout or a prepare step failed, before the interpreter was asked
        code, out, version, unread, budget = 1, str(error), None, "the run ended before its interpreter was asked", None
        started = False
    except (KeyboardInterrupt, Terminated):
        # A run stopped part way ends its start entry as a failure, so the record never shows it running on.
        if integration:
            state_tool("journal", "--kind", "integration.suite", "--subject", c.delivery, "--data", json.dumps(
                {"head": commit, "result": "failed", "seconds": round(time.monotonic() - began, 1), "stopped": True}),
                       check=False)
        raise
    seconds = round(time.monotonic() - began, 1)
    # Exit 3 is over its budget only where the run itself was held to a suite-budget/1 file; elsewhere it is a failure.
    result = ("unreadable" if not started else "passed" if code == 0 else
              "over-budget" if code == 3 and budget is not None else "failed")
    append_log("suite", c.delivery, {"commit": commit, "result": result, "exit": code, "argv": argv, "seconds": seconds,
                                     "output": out[-2000:], "platform": platform.platform(), "interpreter": version,
                                     **({"interpreterUnread": unread} if unread else {})})
    if integration:
        state_tool("journal", "--kind", "integration.suite", "--subject", c.delivery, "--data", json.dumps(
            {"head": commit, "result": result, "seconds": seconds,
             **({"budgetSeconds": budget} if budget is not None else {})}))
    print(out[-2000:].rstrip())
    print(f"lead-suite: {result} at {commit[:10]} (exit {code}, {seconds}s); "
          f"recorded in {flow_log('suite', c.delivery)}" + ("" if not integration else " and the journal"))
    return code
# The run's budget: the file a --budget argument names, read in the run's own checkout at the head it ran, as its
# wall seconds when it reads as suite-budget/1, and None otherwise.
def suite_budget(argv: list[str], checkout: Path) -> float | None:
    named = budget_named(argv)
    if not named:
        return None
    try:
        return budget_seconds((checkout / named).read_text(encoding="utf-8"))
    except OSError:
        return None
# The path a --budget argument names, or None.
def budget_named(argv: list[str]) -> str | None:
    return next((argv[i + 1] for i, arg in enumerate(argv[:-1]) if arg == "--budget"),
                next((arg.split("=", 1)[1] for arg in argv if arg.startswith("--budget=")), None))
# A budget file's wall seconds when it reads as suite-budget/1, and None otherwise.
def budget_seconds(text: str) -> float | None:
    try:
        budget = json.loads(text)
    except ValueError:
        return None
    if not isinstance(budget, dict) or budget.get("schemaVersion") != "suite-budget/1":
        return None
    wall = budget.get("wallSeconds")
    return wall if isinstance(wall, (int, float)) and not isinstance(wall, bool) and wall >= 0 else None
# The start of lead-suite's run at commit, journalled before its checkout is made: when it began and, from the last
# run of the integration suite that finished under the same budget, how long it usually takes. A run that never
# started, or one stopped part way, did not finish. The budget is read
# from the commit itself, as the run will read it in its checkout. A start the journal refuses never holds the run.
SUITE_FINISHED = ("passed", "over-budget", "failed")


def suite_started(c, commit: str, argv: list[str]) -> None:
    named = budget_named(argv)
    shown = git("show", f"{commit}:{named}", check=False) if named else None
    budget = budget_seconds(shown) if shown else None
    try:
        earlier = journal_entries("integration.suite", c.delivery)
    except (Stop, OSError, ValueError, KeyError):
        earlier = []
    usual = next((entry["data"]["seconds"] for entry in reversed(earlier) if isinstance(entry.get("data"), dict)
                  and entry["data"].get("result") in SUITE_FINISHED and not entry["data"].get("stopped")
                  and entry["data"].get("budgetSeconds") == budget
                  and isinstance(entry["data"].get("seconds"), (int, float))
                  and not isinstance(entry["data"].get("seconds"), bool)), None)
    done = state_tool("journal", "--kind", "integration.suite.started", "--subject", c.delivery, "--data", json.dumps(
        {"head": commit, "startedAt": now(), **({"expectedSeconds": usual} if usual is not None else {}),
         **({"budgetSeconds": budget} if budget is not None else {})}), check=False)
    if done.returncode:
        print(f"lead-suite: the journal refused the run's start, so the live view shows it only once it finishes: "
              f"{(done.stderr or done.stdout).strip()}", file=sys.stderr, flush=True)


# The record's integration step, {base, target, remote}, or None for a delivery without one or with no record yet.
def record_integration() -> dict | None:
    if not (cfg().state / "state.json").exists():
        return None
    integration = load_state()["state"]["meta"].get("integration")
    return integration if isinstance(integration, dict) else None
# The lead's record of the integration step: each fact under the delivery's own key, at a head the lead checkout has.
def lead_integrate(args) -> None:
    """Journal one fact of the integration step: the target merged in, an integration review round, the change request
    into the target, or its merge. Refused, with nothing journalled, on a record without an integration step and for a
    head that isn't a commit here, once the target is fetched."""
    c = cfg()
    integration = record_integration()
    if not integration:
        raise Stop("the record has no integration step: lead-init writes one only for a delivery with an "
                   "integrationTarget")
    target, remote = integration["target"], integration["remote"]
    git("fetch", "-q", remote, target, check=False)
    head = git("rev-parse", "--verify", "--quiet", f"{args.head}^{{commit}}", check=False)
    if not head:
        raise Stop(f"{args.head} is no commit in this repository; fetch it, or name another")
    if args.fact == "merged":
        parents = git("rev-list", "--parents", "-n", "1", head).split()[1:]
        if len(parents) != 2:
            raise Stop(f"{args.head} is no merge of {target}: it has {len(parents)} parents, and a merge has two")
        done = state_tool("journal", "--kind", "integration.merged", "--subject", c.delivery, "--data", json.dumps(
            {"target": target, "targetHead": parents[1], "head": head, "conflicts": list(args.conflict or [])}))
    elif args.fact == "round":
        verdicts = {}
        for said in args.verdict:
            lens, _, verdict = said.partition("=")
            if not lens or verdict not in ("approve", "changes"):
                raise Stop(f"--verdict {said} is not LENS=approve or LENS=changes")
            verdicts[lens] = verdict
        counts = args.findings.split(",")
        if len(counts) != 4 or not all(n.isdigit() for n in counts):
            raise Stop(f"--findings {args.findings} is not four counts, P0,P1,P2,P3")
        moment = now()
        done = state_tool("journal", "--kind", "review.round", "--subject", c.delivery, "--data", json.dumps(
            {"round": args.round, "head": head, "verdicts": verdicts,
             "findings": dict(zip(("P0", "P1", "P2", "P3"), map(int, counts))),
             "startedAt": args.started or moment, "finishedAt": args.finished or moment}))
    elif args.fact == "requested":
        done = state_tool("journal", "--kind", "integration.requested", "--subject", c.delivery, "--data", json.dumps(
            {"changeRequest": args.change_request, "head": head}))
    else:
        done = state_tool("journal", "--kind", "integration.landed", "--subject", c.delivery, "--data", json.dumps(
            {"target": target, "head": head}))
    print(f"recorded {args.fact} as entry {journal_id(done)} at {head[:10]}")


def moved_head_stands(c, doc: dict, head: str, last: dict | None) -> str:
    """What stands at a base head past a failed fullHealth's: a run running there, a run due there, a base.broken that
    still awaits base.repaired, or none of these."""
    stands = []
    running = full_health_running(c)
    if running is not None and running.get("head") == head:
        stands.append(f"a run is running ({running_words(running)}): wait for its result")
    elif last is None and delivery_posture(c)["posture"] != "focused":
        stands.append("a run is due on the supervisor's next pass: wait for its result")
    breaks = base_breaks_standing(doc["journal"])
    if breaks:
        # A pass repairs only a break fullHealth found; the queue's own waits for the lead.
        by_pass = "a fullHealth pass there journals it, or, " if only_full_health_breaks(doc["journal"]) else ""
        stands.append(f"base.broken (journal entry {breaks[-1]['id']}) still awaits base.repaired: {by_pass}once you "
                      "have checked the base, journal base.repaired with your reason")
    return "; ".join(stands) if stands else "nothing stands: no run is running or due, and no base.broken awaits repair"


def worded(value: str | None, name: str) -> str:
    """A person's words for a decision or a blocker: refused when absent, empty or only spaces."""
    if value is None or not value.strip():
        raise Stop(f"{name} is required: say it in words, not empty or only spaces")
    return value


def causes(value: str | None) -> list[str]:
    """The `--because` ids, passed on as the state tool takes them, or nothing when none are given."""
    return ["--because", value] if value else []


def lead_decide(args) -> None:
    """Record what the lead decided and why, as decision.recorded, naming the entries it was decided because of."""
    text, why = worded(args.text, "--text"), worded(args.why, "--why")
    done = state_tool("journal", "--kind", "decision.recorded", "--text", text, "--why", why, *causes(args.because), *(["--subject", args.subject] if args.subject else []))
    print(f"recorded decision {journal_id(done)}")


def lead_compound(args) -> None:
    """Record the delivery's compound-learning decision, which its close waits on: a learning preserved, with where it
    is, or none needed, with why. Refused, with nothing journalled, for a missing or empty reference or reason, and
    while work stands open, read as the close condition reads it, so the decision follows the work."""
    c = cfg()
    if args.required:
        data = {"outcome": "required", "reference": worded(args.ref, "--ref").strip()}
    else:
        data = {"outcome": "not-required", "why": worded(args.why, "--why")}
    doc = load_state()
    standing = open_work(c, doc)
    if standing:
        raise Stop(f"work is still open ({'; '.join(standing)}): record {DECISION_HOLD} once it is done, with every "
                   "gap noted")
    done = state_tool("journal", "--kind", COMPOUNDING_KIND, "--data", json.dumps(data))
    print(f"recorded {DECISION_HOLD}, {data['outcome']} (journal entry {journal_id(done)})")


def lead_block(args) -> None:
    """Record what blocks the work, as blocker.recorded, naming the entries it was blocked because of; lead-resolve
    resolves it."""
    text = worded(args.text, "--text")
    done = state_tool("journal", "--kind", "blocker.recorded", "--text", text, *causes(args.because),
                      *(["--subject", args.subject] if args.subject else []))
    number = journal_id(done)
    print(f"recorded blocker {number}; resolve it with {flow_command()} lead-resolve {number} --why TEXT")


def lead_hold(args) -> None:
    """Record why the lead holds a planned story, as story.held, or clear the hold, as story.unheld. A hold also ends
    when the story is assigned, with nothing more journalled. Refused, with nothing written, for a story the record
    doesn't hold or that has landed or settled, a hold on a story already started, and an empty or space-only
    reason."""
    c = cfg()
    doc = load_state()
    state = doc["state"]
    queued = next((item for item in state["queue"] if item["subject"] == args.key), None)
    planned = next((item for item in state.get("planned", []) if item["subject"] == args.key), None)
    if queued is None and planned is None:
        raise Stop(f"{args.key} is not in the record: there is nothing to hold")
    if (queued or {}).get("stage") == "merged":
        raise Stop(f"{args.key} has landed: there is nothing to hold")
    if (planned or {}).get("stage") == "settled":
        raise Stop(f"{args.key} has settled with no change: there is nothing to hold")
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    standing = delivery_state._holds(doc["journal"]).get(args.key)
    if args.clear:
        if standing is None:
            raise Stop(f"the lead holds no hold on {args.key}: there is nothing to clear")
        done = state_tool("journal", "--kind", "story.unheld", "--subject", args.key, "--data", "{}",
                          "--answers", str(standing["id"]))
        print(f"cleared the hold on {args.key} (journal entry {journal_id(done)})")
        return
    if planned is None or planned["stage"] != "planned":
        # Only a story not yet started waits on the lead's reason, so a hold is shown only there; a clear is still taken.
        raise Stop(f"{args.key} has started: there is nothing to hold back")
    text = worded(args.text, "--text")
    done = state_tool("journal", "--kind", "story.held", "--subject", args.key, "--data", json.dumps({"text": text}))
    print(f"recorded the hold on {args.key} (journal entry {journal_id(done)}); it ends when {args.key} is assigned, "
          f"or with {flow_command()} lead-hold {args.key} --clear")


# A sibling's hosted live view is read over HTTPS; plain http only from a loopback receiver, as hosted.py allows tests.
SIBLING_SCHEME = re.compile(r"^(?:https://|http://127\.0\.0\.1:[0-9]{1,5}/)")


def lead_sibling(args) -> None:
    """Name a sibling delivery of the same epic by its hosted live view's link, as sibling.added, or remove one, as
    sibling.removed. serve's refresh reads each one the record names through the binding's state.siblingSnapshot.
    Refused, with nothing written, for a record with no tracker parent, a link that isn't a hosted live view, or a
    name the record already holds or, for a removal, doesn't."""
    if args.action == "add" and not SIBLING_SCHEME.match(args.link or ""):
        raise Stop("a sibling is named by its hosted live view over HTTPS, https://<origin>/d/<64 hex>; plain http is "
                   "taken only from http://127.0.0.1:<port>, a loopback test receiver")
    c = cfg()
    scripts = str(c.release / "skills/orchestrate-work/scripts")
    if scripts not in sys.path:
        sys.path.insert(0, scripts)
    import delivery_state
    try:
        if args.action == "remove":
            done = delivery_state.set_sibling(c.state, name=args.name, remove=True)
            print(f"removed the sibling {args.name} (journal entry {done['entry']})")
            return
        done = delivery_state.set_sibling(c.state, name=args.name, link=args.link)
    except delivery_state.StateError as error:
        raise Stop(str(error)) from None
    print(f"named {args.name} as a sibling delivery (journal entry {done['entry']}); serve's refresh reads it through "
          f"the binding's state.siblingSnapshot")


def lead_resolve(args) -> None:
    """Resolve the blocker a journal entry records, or ask the next pass to rerun a failed fullHealth, with the lead's
    reason. The resolution is the flow log's; the journal says so."""
    c = cfg()
    # Refused before anything is written, so a reason the journal would refuse never leaves a resolution or a rerun in
    # the flow log without its entry.
    args.why = worded(args.why, "--why")
    doc = load_state()
    if args.id == "full-health":
        # The base head as the remote has it, so a failed head the base has moved past reads as moved.
        git("fetch", "-q", c.remote, c.base_branch, check=False)
        head = base_head(c)
        last, rerun = full_health_results(c, head)
        if not last or last["result"] != "failed":
            failed = next((e for e in reversed(read_log("full-health", c.delivery)) if e.get("result") == "failed"), None)
            if failed and failed["head"] != head:
                raise Stop(f"fullHealth failed at {failed['head'][:10]}, which is no longer the base head; the base is at "
                           f"{head[:10]}, where {moved_head_stands(c, doc, head, last)}")
            raise Stop(f"fullHealth hasn't failed at the base head {head[:10]}; there is nothing to rerun")
        # Under focused no run starts, so the rerun waits on the base returning to gate.
        when = ("if the base returns to gate" if delivery_posture(c)["posture"] == "focused"
                else "on the supervisor's next pass")
        if rerun:
            raise Stop(f"a rerun of fullHealth at {head[:10]} is already asked for; it runs {when}")
        shared = shared_seat(c) is not None
        if not shared:
            with plan_lock(c):
                append_full_health(c, {"rerun": True, "head": head, "why": args.why})
        # The request names the break it would repair, when one stands, and answers nothing: only the pass repairs. On a
        # shared record it is the rerun itself, naming the failed result's `at`, so it is asked for from any seat.
        standing = [e["id"] for e in base_breaks_standing(doc["journal"]) if full_health_break(e)]
        state_tool("journal", "--kind", "fullhealth.rerun", "--data",
                   json.dumps({"head": head, "why": args.why, **({"at": last["at"]} if shared else {})}),
                   *(["--because", ",".join(map(str, standing))] if standing else []))
        print(f"asked for a rerun of fullHealth at {head[:10]}, which runs {when}")
        return
    try:
        number = int(args.id)
    except ValueError:
        raise Stop(f"lead-resolve takes a journal id or full-health, not {args.id!r}")
    entry = next((e for e in doc["journal"] if e["id"] == number), None)
    if entry is None or entry["kind"] not in HOLDING_KINDS:
        raise Stop(f"journal entry {number} isn't a blocker.recorded, serving.held or deferral.breached"
                   + (f" ({entry['kind']})" if entry else ""))
    resolutions = {r.get("journal") for r in read_log("resolutions", c.delivery)}
    if blocker_resolved(c, doc, entry, resolutions):
        raise Stop(f"blocker {number} is already resolved")
    append_log("resolutions", c.delivery, {"journal": number, "why": args.why})
    # The resolution answers the blocker it names, and no other entry. The queue's hold is a serving.held, which no
    # entry may answer: the resolution then names it as its cause instead.
    link = "--because" if entry["kind"] == "serving.held" else "--answers"
    state_tool("journal", "--kind", "blocker.resolved", "--data", json.dumps({"why": args.why}), link, str(number),
               *(["--subject", entry["subject"]] if entry.get("subject") else []))
    print(f"resolved blocker {number}")


def requeue(c, key: str) -> None:
    """Put a stopped candidate the lead has resolved back to queued at its handed head, with no new hand-off. The
    stage is the runner's, so the write is the runner's, exactly as the queue puts back what it takes again."""
    found: list[dict] = []

    def back_to_queued(doc: dict) -> list[str]:
        # Checked against each fresh read: a write in between may have taken the candidate past stopped.
        item = next((q for q in doc["state"]["queue"] if q["subject"] == key), None)
        if item is None or item["stage"] != "stopped":
            raise Stop(f"{key} isn't stopped ({item['stage'] if item else 'not queued'}); --requeue takes back a "
                       "stopped candidate")
        if item.get("pending"):
            raise Stop(f"{key}'s hand-off still waits for acceptance; accept it instead")
        if remote_head(c.branch(key)) not in (item["head"], item.get("syncedHead")):
            raise Stop(f"{c.remote}/{c.branch(key)} moved from the handed head {item['head'][:10]}"
                       + (f" and the queue's synced head {item['syncedHead'][:10]}" if item.get("syncedHead") else "")
                       + ": the lane hands it off again")
        found[:] = [item]
        return ["--element", f"queue[subject={key}]", "--set", json.dumps({"/stage": "queued", "/checks": []})]
    patch_from(back_to_queued, f"{key}'s re-queue", writer="runner")
    item = found[0]
    # The re-queue answers the stop it resolves, which closes that setback.
    stops = [e["id"] for e in load_state()["journal"] if e["kind"] == "candidate.stopped" and e.get("subject") == key]
    state_tool("journal", "--kind", "handoff.requeued", "--subject", key, "--data", json.dumps({"head": item["head"]}), *(["--answers", str(stops[-1])] if stops else []))
    print(f"re-queued {key}; the runner takes it again")



def apply_patch(diff: str, cwd: Path) -> subprocess.CompletedProcess:
    """Apply a diff exactly as git printed it: stripping its trailing newline corrupts a final blank context line."""
    return subprocess.run(["git", "apply", "--3way", "--index"], cwd=cwd, input=diff, text=True, capture_output=True)


def ship(args) -> None:
    c = cfg()
    if not c.ship:
        raise Stop(f"{c.delivery_where} declares no `ship`")
    s = c.ship
    unknown = [g["id"] for g in c.gates if g.get("unknown")]
    if unknown and not args.no_gates:  # before anything is made: the ship's gates couldn't run
        raise Stop(f"the gates name checks the binding doesn't define: {', '.join(unknown)}; run {flow_command()} doctor")
    git("fetch", "-q", c.remote)
    branch = expand(s.get("branch", "ship/{delivery}"), delivery=c.delivery)
    checkouts = Path(expand(s.get("checkout", str(Path(c.lane_pattern).parent / "{branch}")), branch=branch.replace("/", "-")))
    path = c.main / checkouts
    if path.exists() or git("rev-parse", "--verify", "--quiet", f"refs/heads/{branch}", check=False):
        raise Stop(f"{path} or the branch {branch} already exists; remove both first if you mean to rebuild")
    if run(["git", "merge-base", "--is-ancestor", s["toolingCommit"], c.base_ref], check=False).returncode != 0:
        raise Stop(f"the tooling commit {s['toolingCommit']} is not an ancestor of {c.base_ref}")
    diff, tooling = ship_diff(c, s)
    if not diff:
        raise Stop(f"nothing under {s['paths']} to ship")
    git("worktree", "add", "-q", "--no-track", "-b", branch, str(path), s["from"])
    applied = apply_patch(diff, path)
    files = git("diff", "--cached", "--name-only", cwd=path).splitlines()
    outside = [f for f in files if not any(f == p.rstrip("/") or f.startswith(p.rstrip("/") + "/") or p in (".", "./")
                                           for p in s["paths"])]
    print(f"{branch} at {path}, from {s['from']} ({git('rev-parse', '--short', s['from'])})")
    print(f"  left out the delivery's tooling: {', '.join(tooling[:10])}" + (f" and {len(tooling) - 10} more" if len(tooling) > 10 else ""))
    # A tooling file the delivery changed again later is left out too: name every one, so a product change to a file
    # the tooling commit also touched can't go missing unnoticed.
    committed = set(git("diff", "--name-only", git("merge-base", s["from"], s["toolingCommit"]), s["toolingCommit"]).splitlines())
    later = sorted(f for f in git("diff", "--name-only", s["toolingCommit"], c.base_ref, "--", *s["paths"]).splitlines()
                   if f in committed and not f.startswith((".agents/", ".agent-skills/")))
    if later:
        print(f"  changed after the tooling commit and left out: {', '.join(later)}; a product change there doesn't ship")
    print(f"  {len(files)} file(s) staged; outside {s['paths']}: {outside or 'none'}")
    if applied.returncode == 0 and not files:  # a clean apply that changed nothing is no product branch
        git("worktree", "remove", "--force", str(path))
        git("branch", "-D", branch)
        raise Stop(f"nothing to ship: {s['from']} already has every change the delivery made under {s['paths']}; "
                   f"removed {path} and {branch}")
    if applied.returncode != 0:
        unmerged = git("diff", "--name-only", "--diff-filter=U", cwd=path)
        raise Stop("git apply failed" + (f"; resolve the conflicts in {path}: {unmerged}" if unmerged else f": {applied.stderr.strip()}"))
    if outside:
        raise Stop("files outside the ship paths were staged; this must not happen")
    # The lead's own integration is reviewed like a lane's unit before it reaches the default branch: the
    # orchestration guide's close-out, "Review the integration".
    review = ("then review the integration with `$review-work` before it reaches the default branch, as the "
              "orchestration guide's close-out says")
    if args.no_gates or not c.gates:
        print(f"  next: prepare the checkout, run the gates there, then commit as one change, {review}. "
              "Its PR waits for the user.")
        return
    ship_gates(c, path, s)
    print(f"  next: commit the staged change as one commit, {review}. Its PR waits for the user.")


def ship_diff(c, s: dict) -> tuple[str, list[str]]:
    """The delivery's product changes under the ship paths, as one diff to apply onto `ship.from`, and the tooling it
    leaves out. The diff starts where the base and `ship.from` last met, so changes the base merged from the default
    branch aren't shipped again. Tooling never ships, whenever it changed: every file the tooling commits touched
    (from that meeting point to `ship.toolingCommit`), run-delivery's own `.agents/` settings, the installed generation
    and `ship.gateTooling`."""
    since = git("merge-base", s["from"], c.base_ref)
    fork = git("merge-base", s["from"], s["toolingCommit"])
    tooling = sorted(set(git("diff", "--name-only", fork, s["toolingCommit"]).splitlines())
                     | {".agents", ".agent-skills", *s.get("gateTooling", [])})
    left_out = [f":(top,exclude,literal){rel.rstrip('/')}" for rel in tooling]
    diff = run(["git", "diff", "--binary", since, c.base_ref, "--", *s["paths"], *left_out]).stdout  # unstripped
    return diff, tooling


def ship_tooling(c, path: Path, s: dict) -> list[str]:
    """The delivery base's gate tooling that the ship tree lacks: for each file a gate or prepare step names that only
    the base has, every file beside it that only the base has (a gate script's helpers), plus `ship.gateTooling`.
    The ship's own files are never replaced, so the gates check what ships with the delivery's harness."""
    def base_files(spec: str, recursive: bool) -> list[tuple[str, str]]:
        out = git("ls-tree", *(["-r"] if recursive else []), c.base_ref, "--", spec, check=False)
        return [(line.split()[0], line.split("\t", 1)[1]) for line in out.splitlines() if line.split()[1] == "blob"]

    named = set()
    for argv in [g["argv"] for g in c.gates] + prepare_commands():
        for arg in argv:
            for token in shlex.split(arg) if " " in arg else [arg]:
                if "/" in token and not token.startswith(("-", "/", "{")) and not (path / token).exists():
                    named.add(token)
    wanted = {}
    for token in named:
        if base_files(token, False):
            parent = str(Path(token).parent)
            wanted.update({p: m for m, p in base_files(parent + "/", False)} if parent != "." else {})
            wanted.update({p: m for m, p in base_files(token, False)})
    for spec in s.get("gateTooling", []):
        wanted.update({p: m for m, p in base_files(spec, True)})
    copied = []
    for rel, mode in sorted(wanted.items()):
        target = path / rel
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(subprocess.run(["git", "show", f"{c.base_ref}:{rel}"], cwd=c.main, capture_output=True,
                                          check=True).stdout)
        target.chmod(0o755 if mode == "100755" else 0o644)
        copied.append(rel)
    return copied


def ship_gates(c, path: Path, s: dict) -> None:
    """Prepares the ship checkout and runs the delivery's gates in it, with `{base}` as the ship's own base. The base's
    gate tooling is lent for the run and removed after, so nothing but the staged change is left to commit."""
    copied = ship_tooling(c, path, s)
    if copied:
        print(f"  lent the base's gate tooling for the run: {', '.join(copied)}")
    results, passed = [], True
    try:
        for argv in prepare_commands():
            code, out = run_group(argv, path, 1800)
            if code != 0:
                raise Stop(f"prepare {' '.join(argv)} failed ({code}): {out.strip()[-300:]}")
        for g in c.gates:
            # A gate named by id runs its definition here: the ship's staged change is no commit run-checks could take.
            argv = expand_argv(g["argv"], base=s["from"], key=c.delivery, delivery=c.delivery)
            started = time.time()
            print(f"  gate {g['id']}: {' '.join(shlex.quote(a) for a in argv)}", flush=True)
            code, out = run_group(argv, path / g.get("cwd", "."), g.get("timeoutSeconds", 1800))
            seconds = round(time.time() - started)
            tail = out.strip().splitlines()[-15:]
            results.append({"id": g["id"], "exit": code, "seconds": seconds, "tail": tail})
            print(f"    {'ok' if code == 0 else 'FAILED'} in {seconds}s" + ("" if code == 0 else "\n      " + "\n      ".join(tail)))
            if code != 0:
                passed = False
                break
    finally:
        for rel in copied:
            (path / rel).unlink(missing_ok=True)
    staged = git("diff", "--cached", "--binary", cwd=path)
    append_log("ship-gates", c.delivery, {"from": git("rev-parse", s["from"]), "base": git("rev-parse", c.base_ref),
                                          "staged": hashlib.sha256(staged.encode()).hexdigest(), "passed": passed,
                                          "results": results, "lent": copied})
    if not passed:
        raise Stop(f"a gate failed in {path}; fix it on the delivery base and rebuild the ship branch")
    print(f"  gates passed in {path}")


def show_config(args) -> None:
    """Every resolved setting and the file it came from."""
    c = Config(repo(), DELIVERY_ARG, need_delivery=False, tolerant=True)
    rows = [
        ("remote", c.remote), ("workDirectory", c.work), ("stateDirectory (in the lead's checkout)", c.state_rel),
        ("branchPattern", c.branch_pattern), ("laneCheckout", c.lane_pattern), ("deliveries", c.deliveries),
        ("tracker.issueUrl", c.issue_url), ("forge", json.dumps(c.forge)), ("review.bound", c.bound),
        ("review.lenses", ", ".join(f"{k} ({v[1]}; use: {' and '.join(c.lens_use[k])})" for k, v in c.lenses.items())),
        *([("review.lenses on request", on_request_text(c))] if c.on_request else []),
        ("review.prepare", json.dumps(c.prepare)),
        ("gates", "; ".join(f"{g['id']}: {' '.join(g['argv'])}" for g in c.gates)),
        ("neverTouch", ", ".join(c.never_touch)), ("inApp", "declared" if c.in_app else "none"),
    ]
    keys = ["remote", "workDirectory", "stateDirectory", "branchPattern", "laneCheckout", "deliveries", "tracker.issueUrl",
            "forge", "review.bound", "review.lenses", *(["review.lenses"] if c.on_request else []), "review.prepare",
            "gates", "neverTouch", "inApp"]
    if c.delivery:
        rows += [("delivery", c.delivery), ("baseBranch", c.base_branch), ("state", c.state),
                 ("stories", len(c.stories)), ("lanes", len(c.lanes))]
        keys += ["delivery", "baseBranch", "state", "stories", "lanes"]
    for (label, value), key in zip(rows, keys):
        source = c.sources.get(key, c.delivery_path.name if c.delivery and key in ("delivery", "stories", "lanes") else "")
        print(f"{label:42} {value}\n{'':42} <- {source}")
    print(f"\nharness config: {c.harness_note}")


def adapter_test(args) -> None:
    """Prove the repository's in-app serve and check adapters keep the contract, on a fixture page: no app needed."""
    c = Config(repo(), need_delivery=False)
    global CFG
    CFG = c
    ia = need_in_app()
    lease = Lease(Path(expand(ia["lock"])), ia["port"], "adapter-test", ia.get("lockWaitSeconds", 480))
    failures = adapter_contract(ia, lease, print)
    if failures:
        raise Stop("the in-app adapters break the contract:\n  " + "\n  ".join(failures))
    print("the in-app adapters keep the contract")


def adapter_contract(ia: dict, lease: "Lease", say) -> list[str]:
    """Run the fixture page's cases through the serve and check adapters under a lease already held, then release it.
    Returns one line per broken case."""
    with tempfile.TemporaryDirectory() as tmp:
        site = Path(tmp) / "site"
        shutil.copytree(TOOL / "assets/adapter-fixture", site)
        write_stamp(site, "f" * 40, "e" * 40)
        server = None
        failures = []
        try:
            if port_open(ia["port"]):
                raise Stop(port_busy(ia["port"]))
            server = start_serve(ia, site, ia["port"], lease)
            busy = '[aria-busy="true"]'
            loaded = "document.querySelector('#state').textContent === 'loaded'"
            hold = {"holds": ["/api/one$"], "fails": [], "clicks": [], "for": busy, "wait": 300,
                    "evals": ['!!document.querySelector(\'[aria-busy="true"]\')'], "afterEvals": [loaded], "afterFor": "#state"}
            # (name, mode, spec, adapter args, expected verdict, extra checks on the report)
            cases = [
                ("hold", "hold", {**hold, "path": "/"}, ["--fail", "/api/one$"], True,
                 lambda rep: [] if not rep.get("failed") else ["an adapter --fail after -- overrode the spec"]),
                ("hold-refetch", "hold", {**hold, "path": "/?refetch"}, [], True,
                 lambda rep: [] if any(e.get("afterRelease") for e in rep.get("held", []))
                 else ["a request after the release wasn't reported with afterRelease"]),
                ("hold-flash", "hold", {**hold, "path": "/?flash", "afterEvals": [loaded],
                                        "evals": ['!!document.querySelector(\'[aria-busy="true"]\')']}, [], False,
                 lambda rep: [] if "transient" in (rep.get("alertsSeen") or []) else ["a flashed alert wasn't reported in alertsSeen"]),
                ("hold-flash-attr", "hold", {**hold, "path": "/?flash-attr"}, [], False,
                 lambda rep: [] if "became an alert" in (rep.get("alertsSeen") or [])
                 else ["an element that became an alert wasn't reported"]),
                ("hold-flash-text", "hold", {**hold, "path": "/?flash-text"}, [], False,
                 lambda rep: [] if "live text" in (rep.get("alertsSeen") or [])
                 else ["text that appeared in an alert wasn't reported"]),
                ("fail", "fail", {"path": "/", "holds": [], "fails": ["/api/one$"], "clicks": [], "afterEvals": [],
                                  "evals": ["[...document.querySelectorAll('[role=alert]')].some(a => a.textContent === 'failed')"], "wait": 800}, [], True,
                 lambda rep: [] if all(e.get("at") for e in rep.get("failed", [])) and rep.get("failed")
                 else ["failed entries lack their time"]),
                ("loaded", "loaded", {"path": "/", "holds": [], "fails": [], "clicks": [], "afterEvals": [], "wait": 800,
                                      "evals": [loaded]}, [], True, lambda rep: []),
            ]
            for name, mode, spec, extra, expected, more in cases:
                spec_file = Path(tmp) / f"{name}.json"
                spec_file.write_text(json.dumps(spec))
                code, out = run_group(expand_argv(ia["check"]["argv"], spec=str(spec_file), port=str(ia["port"]), args=extra),
                                      repo(), ia.get("checkTimeoutSeconds", 300))
                try:
                    report = json.loads(out[out.index("{"):])
                except ValueError:
                    failures.append(f"{name}: no JSON report ({out.strip()[-200:]})")
                    continue
                verdict = rules(report, mode=mode, spec=spec, pinned=["/api/one$"], build_head="f" * 40,
                                allowed_errors=set(), error_pattern=r"^(?!Failed to load resource)")
                bad = [] if all(verdict.values()) == expected else [
                    f"expected the rules to {'pass' if expected else 'fail'}: " + str([k for k, ok in verdict.items() if not ok])]
                bad += more(report)
                if "alertsSeen" not in report:
                    bad.append("the report has no alertsSeen")
                if any(not isinstance(e.get("result"), bool) for e in report.get("evals", [])):
                    bad.append("eval results aren't JSON booleans")
                say(f"{'ok ' if not bad else 'FAIL'} {name}" + (f": {bad}" if bad else ""))
                if bad:
                    failures.append(f"{name}: {bad} (report: {json.dumps(report)[:600]})")
        finally:
            stop_group(server)
            lease.close()
    return failures




# -- the setup check -----------------------------------------------------------------------------

GUIDE = "the adoption guide, references/adopting.md"
# The knowledge library's properties, as the adopting repository writes them: the hive knowledge adapter reads them,
# and doctor checks their shape. Nothing here writes the document or derives a property from anywhere else.
KNOWLEDGE_PROPERTIES = ".agents/knowledge-properties.json"
KNOWLEDGE_SCHEMA = "knowledge-properties/1"
KNOWLEDGE_FIELDS = ("schemaVersion", "server", "name", "project", "tags")
KNOWLEDGE_SERVERS = ("plugin", "read-only")
KNOWLEDGE_MAX_TAGS = 5
KNOWLEDGE_NAME = re.compile(r"[^\s,]+")


def knowledge_properties_problem(document) -> str | None:
    """The first field of a knowledge-properties document that isn't valid, said as doctor's line says it, or None."""
    def is_name(value) -> bool:
        return isinstance(value, str) and KNOWLEDGE_NAME.fullmatch(value) is not None
    if not isinstance(document, dict):
        return "the document must be a JSON object"
    unknown = sorted(set(document) - set(KNOWLEDGE_FIELDS))
    if unknown:
        return f"`{unknown[0]}` isn't one of its fields ({', '.join(f'`{f}`' for f in KNOWLEDGE_FIELDS)})"
    if document.get("schemaVersion") != KNOWLEDGE_SCHEMA:
        return f"`schemaVersion` must be `{KNOWLEDGE_SCHEMA}`"
    server = document.get("server")
    if server not in KNOWLEDGE_SERVERS:
        return "`server` must be `plugin` or `read-only`"
    if server == "read-only" and not is_name(document.get("name")):
        return "a `read-only` server needs its `name`, one name with no spaces or commas"
    if server == "plugin" and "name" in document:
        return "`name` names a `read-only` server only; remove it for `plugin`"
    if not is_name(document.get("project")):
        return "`project` must be one name, with no spaces or commas"
    if "tags" in document:
        tags = document["tags"]
        if not isinstance(tags, list):
            return "`tags` must be a list of names"
        if len(tags) > KNOWLEDGE_MAX_TAGS:
            return f"`tags` holds {len(tags)} names, more than {KNOWLEDGE_MAX_TAGS}"
        if not all(is_name(tag) for tag in tags):
            return "`tags` must hold only names, each with no spaces or commas"
        if len(set(tags)) != len(tags):
            return "`tags` names a tag twice"
    return None


# Filters and the encoder the before/after clips use; drawtext is optional (labels are burned in only where it exists).
VIDEO_FILTERS = ("lutyuv", "cropdetect", "crop", "scale", "tpad", "pad", "hstack")


def video_tools_problem() -> str | None:
    """Why video evidence can't be recorded here, as the setup check says it, or None."""
    missing = [tool for tool in ("ffmpeg", "ffprobe") if not shutil.which(tool)]
    if missing:
        return (f"missing: {' and '.join(missing)} {'is' if len(missing) == 1 else 'are'} not installed, and video "
                "evidence needs both; fix: install ffmpeg (it brings ffprobe)")
    filters = run(["ffmpeg", "-hide_banner", "-filters"], check=False).stdout
    names = {line.split()[1] for line in filters.splitlines() if len(line.split()) > 2 and line.startswith(" ")}
    lacking = [name for name in VIDEO_FILTERS if name not in names]
    encoders = run(["ffmpeg", "-hide_banner", "-encoders"], check=False).stdout
    if "libx264" not in encoders:
        lacking.append("the libx264 encoder")
    if lacking:
        return (f"wrong: this ffmpeg lacks {', '.join(lacking)}, which video evidence uses; fix: install an ffmpeg "
                "build with them (most distributions' full build has them)")
    return None


def version_of(argv: list[str]) -> tuple[int, ...] | None:
    done = run(argv, check=False)
    found = re.search(r"(\d+)\.(\d+)(?:\.(\d+))?", done.stdout or "")
    return tuple(int(n) for n in found.groups() if n is not None) if done.returncode == 0 and found else None


def resolves(argv0: str, root: Path, cwd: str = ".") -> bool:
    """An argv's program: on PATH, or a file in the repository (from the command's own folder)."""
    if not argv0:
        return False
    path = Path(os.path.expanduser(argv0))
    if "/" in argv0:
        return (path if path.is_absolute() else root / cwd / path).exists()
    return shutil.which(argv0) is not None


def writable(folder: Path) -> str | None:
    """Create and remove one temporary file in the folder (or the nearest folder that exists); why not, or None."""
    probe = folder
    while not probe.exists() and probe != probe.parent:
        probe = probe.parent
    try:
        with tempfile.NamedTemporaryFile(dir=probe, prefix=".run-delivery-doctor-"):
            pass
    except OSError as error:
        return f"{folder} isn't writable ({error.strerror})"
    return None


class Doctor:
    """The setup check: one line per check, `ok`, `missing`, `wrong` or `skipped`. A check whose prerequisite failed
    is skipped, naming it, so one missing prerequisite yields one line that is neither ok nor skipped."""

    def __init__(self, args):
        self.args, self.root = args, Path(git("rev-parse", "--show-toplevel", check=False) or os.getcwd())
        self.results: dict[str, tuple[str, str]] = {}
        self.c: Config | None = None
        self.binding: dict | None = None
        self.delivery: Config | None = None

    # (id, label, prerequisites, check); a check returns ("ok" | "missing" | "wrong" | "skipped", detail).
    def rows(self):
        return [
            ("platform", "host and tools", (), self.platform),
            ("binding", "orchestration binding", ("platform",), self.check_binding),
            ("candidate", "merge queue candidate step", ("binding",), self.candidate_step),
            ("config", "configuration", ("platform",), self.config),
            ("lenses", "review lenses", ("config",), self.review_lenses),
            ("generation", "release generation", ("platform",), self.generation),
            ("hooks", "host hooks", ("config",), self.hooks),
            ("committed", "release on the delivery base", ("config", "binding", "generation"), self.committed),
            ("gates", "gates", ("config", "binding"), self.gates),
            ("lanes", "lane checkouts ignored", ("config",), self.lanes),
            ("tracker", "tracker issue URL", ("config",), self.tracker),
            ("review-pr", "pipeline PR review", ("config",), self.review_pr),
            ("gh", "gh", ("config",), self.gh),
            ("forge", "forge find", ("config", "gh"), self.forge),
            ("forge-write", "forge write access", ("config",), self.forge_write),
            ("tracker-scope", "tracker snapshot scope", ("config", "binding"), self.tracker_scope),
            ("tracker-token", "tracker snapshot token", ("binding",), self.tracker_token),
            ("publishing", "snapshots and publishers", ("config", "binding"), self.publishing),
            ("hosted", "hosted delivery", ("config",), self.hosted),
            ("in-app", "in-app adapters", ("config",), self.in_app),
            ("adapters", "in-app adapter contract", ("in-app",), self.adapters),
            ("video", "video evidence tools", ("config",), self.video),
            ("node", "Node", ("platform",), self.node),
            ("awake", "keep awake", ("platform",), self.awake),
            ("harness", "harness configuration", ("config", "generation", "node"), self.harness),
            ("knowledge", "knowledge library properties", ("platform",), self.knowledge),
            ("delivery", "delivery file", ("config", "binding"), self.check_delivery),
            ("record", "delivery record folder", ("delivery",), self.record_folder),
            ("plan", "plan chapter", ("delivery",), self.check_plan),
            ("plan-reasons", "added stories' reasons", ("delivery",), self.plan_reasons),
            ("plan-sections", "plan sections", ("delivery",), self.stories_planned),
            ("story-files", "story files", ("plan-sections",), self.story_files),
            ("readiness", "story readiness", ("delivery",), self.story_readiness),
            ("summaries", "story summaries", ("delivery",), self.story_summaries),
            ("context-sections", "context sections", ("delivery",), self.context_planned),
            ("finish-lines", "finish lines", ("delivery",), self.finish_lines),
            ("remote-base", "configuration on the remote base", ("delivery",), self.remote_base),
            ("ready", "pull requests marked ready", ("delivery",), self.ready),
            ("supervisor", "delivery supervisor", ("delivery",), self.supervisor),
            ("peers", "deliveries on this base", ("delivery",), self.peers),
            ("merge-slot", "merge slot", ("delivery",), self.merge_slot),
            ("base-gates", "gates on the base", ("gates", "committed"), self.base_gates),
        ]

    def run(self) -> bool:
        failed = False
        for row, label, needs, check in self.rows():
            blocked = [n for n in needs if self.results.get(n, ("skipped",))[0] not in ("ok", "skipped-ok")]
            if blocked:
                status, detail = "skipped", f"(needs {', '.join(blocked)})"
            else:
                try:
                    status, detail = check()
                except (Stop, ValueError) as error:  # a refusal, or a file that isn't JSON
                    status, detail = "wrong", f"{error}; fix: see the troubleshooting section of {GUIDE}"
            shown = "skipped" if status == "skipped-ok" else status
            if isinstance(detail, list):  # one line per item: (label, detail)
                for item, said in detail:
                    print(f"{shown:8} {item}: {' '.join(said.split())}".rstrip())
                detail = "; ".join(f"{item}: {said}" for item, said in detail)
            else:
                detail = " ".join(detail.split())  # one line per check
                print(f"{shown:8} {label}: {detail}".rstrip())
            self.results[row] = (status, detail)
            failed |= status in ("missing", "wrong")
        return not failed

    # A check that doesn't apply here is skipped-ok: skipped, and no prerequisite of anything.
    @staticmethod
    def not_applicable(why: str) -> tuple[str, str]:
        return "skipped-ok", f"({why})"

    def platform(self):
        problems = []
        git_version = version_of(["git", "--version"]) if shutil.which("git") else None
        if not git_version or not meets(git_version, (2, 31)):
            problems.append("git 2.31 or newer")
        if not meets(interpreter_version(), PYTHON_MINIMUM):
            problems.append(f"Python {dotted(PYTHON_MINIMUM)} or newer")
        problems += [tool for tool in ("ps", "lsof") if not shutil.which(tool)]
        if problems:
            return "missing", f"this host lacks {', '.join(problems)}; fix: install {', '.join(problems)}"
        return "ok", (f"POSIX, git {'.'.join(map(str, git_version))}, Python {sys.version_info.major}."
                      f"{sys.version_info.minor}, ps, lsof")

    def config(self):
        if self.results.get("binding", ("ok",))[0] == "wrong":
            return "skipped", "(needs binding: the configuration reads it)"  # a missing binding is read as empty
        explicit = setting("RUN_DELIVERY_CONFIG")
        if explicit and not Path(explicit).exists():
            return "missing", (f"no {explicit}, which RUN_DELIVERY_CONFIG names; fix: point RUN_DELIVERY_CONFIG at the "
                               "configuration file, or unset it")
        if not explicit and not (self.root / CONFIG).exists() and not (self.root / LEGACY_NAMES[0][0]).exists():
            return "missing", f"no {CONFIG}; fix: write it (see {GUIDE})"
        try:
            self.c = Config(self.root, need_delivery=False, tolerant=True, pick=False)
        except ValueError as error:
            return "wrong", f"the configuration isn't JSON ({error}); fix: correct it"
        except Stop as error:
            return "wrong", f"{error}; fix: correct {CONFIG} (run_delivery.py config shows every source)"
        global CFG
        CFG = self.c
        for old, new in LEGACY_NAMES[1:]:  # set in the environment, whether or not this run consulted it
            if os.environ.get(old) and (old, new) not in LEGACY_USED:
                LEGACY_USED.append((old, new))
        if LEGACY_USED:
            renames = ", ".join(f"{old} -> {new}" for old, new in LEGACY_USED)
            return "wrong", f"earlier names in use: {renames}; fix: rename them (the earlier names still work for now)"
        return "ok", f"{self.c.path} resolves with no conflicts"

    def review_lenses(self):
        """Each declared lens on its own line: its use and where it was declared."""
        # With --delivery, each story's brief lenses too: a story entry naming any other lens is wrong here, by name.
        key = self.args.doctor_delivery or self.args.delivery
        path = self.c.deliveries / f"{key}.json" if key else None
        if path is not None and path.is_file():
            try:
                for story_key, story in (json.loads(path.read_text()).get("stories") or {}).items():
                    story_brief_lenses(self.c.story_lenses, story_key, story)
            except (ValueError, AttributeError):
                pass  # the delivery file's own row says what is wrong with it
            except Stop as error:
                return "wrong", f"{error}; fix: name only declared story lenses in its lenses"
        asked = lambda lens: ", on request" if lens in self.c.on_request else ""
        return "ok", [*((f"lens {lens}", f"{', '.join(self.c.lens_use[lens])}{asked(lens)}, from {self.c.lens_origin[lens]}")
                        for lens in self.c.lenses),
                      *([("lenses on request", on_request_text(self.c))] if self.c.on_request else [])]

    def release(self) -> Path:
        """The generation the checks read: the configured release, or the one this tool runs from."""
        return self.c.release if self.c else GENERATION

    def generation(self):
        path = receipt_path(self.c) if self.c else self.root / RECEIPT
        running = self.release().resolve().name
        problem = generation_problem_at(path, running)
        if problem:
            status, _, rest = problem.partition(": ")
            return status, rest
        receipt = json.loads(path.read_text())
        if receipt.get("generation") != running:
            return "wrong", (f"the running generation {running} is the receipt's previous one, not its current "
                             f"{receipt.get('generation')}; fix: run the tool as {TOOL_PATH}")
        return "ok", f"{running[:12]} is the current generation in {path.name} ({receipt['release']['releaseId']})"

    def hooks(self):
        """The configuration's hook modes, refused when one names an unknown hook or mode. Reported, never refused:
        a settings file lacking an entry the receipt records, and a python3 on PATH below the hooks' minimum."""
        raw = self.c.flow_raw if self.c else {}
        problems = hook_settings_problems(raw)
        if problems:
            return "wrong", (f"{'; '.join(problems)}; fix: in {CONFIG}, set `hooks` to an object whose keys are among "
                             f"{', '.join(HOOK_DEFAULTS)} and whose values are among {', '.join(HOOK_MODES)}, or "
                             "remove the key")
        modes = ", ".join(f"{hook_id} {hook_mode(raw, hook_id)}" for hook_id in HOOK_DEFAULTS)
        notes = [note for note in (self.hook_entries_note(), self.hook_python_note()) if note]
        return ("warn", f"{modes}; {'; '.join(notes)}") if notes else ("ok", modes)

    def hook_entries_note(self) -> str | None:
        """When the installed generation's receipt records hook entries that its settings file lacks."""
        try:  # an unreadable receipt is the release generation row's to report
            receipt = load_json(receipt_path(self.c) if self.c else self.root / RECEIPT)
        except (OSError, ValueError):
            return None
        recorded = receipt.get("hooks") if isinstance(receipt, dict) else None
        if (not isinstance(recorded, dict) or not isinstance(recorded.get("events"), list)
                or not isinstance(recorded.get("file"), str)):
            return None
        rel = recorded["file"]
        try:
            settings = json.loads((self.root / rel).read_text())
        except (OSError, ValueError):
            settings = None
        lists = settings.get("hooks") if isinstance(settings, dict) and isinstance(settings.get("hooks"), dict) else {}

        def present(event: str) -> bool:
            entries = lists.get(HOOK_SETTINGS_EVENTS.get(event, event))
            return isinstance(entries, list) and any(
                isinstance(entry, dict) and isinstance(entry.get("hooks"), list)
                and any(isinstance(h, dict) and h.get("command") == HOOK_INSTALLED.format(event=event)
                        for h in entry["hooks"]) for entry in entries)
        lacking = [event for event in recorded["events"] if not present(event)]
        if not lacking:
            return None
        # Named by the receipt's member, not its path: run-delivery's output names no host's own folders.
        return (f"the settings file the receipt's hooks.file names lacks the hook entries the receipt records for "
                f"{', '.join(lacking)}, so those hooks don't run; fix: apply the generation again, which writes them, "
                "or restore that file from version control")

    def hook_python_note(self) -> str | None:
        """When the python3 on PATH, which the installed hook command runs, is below the hooks' minimum."""
        found = shutil.which("python3")
        if not found:
            return "no python3 on PATH, so the installed hook command can't start; fix: put Python 3.11 or newer on PATH"
        done = run([found, "-c", "import sys; print('%d.%d' % sys.version_info[:2])"], check=False, timeout=10)
        try:
            version = tuple(int(part) for part in done.stdout.strip().split("."))
        except ValueError:
            return f"python3 on PATH ({found}) didn't report its version; fix: put Python 3.11 or newer first on PATH"
        if version < HOOK_PYTHON:
            return (f"python3 on PATH ({found}) is {'.'.join(map(str, version))}, below 3.11, and the installed hook "
                    "command runs it; fix: put Python 3.11 or newer first on PATH")
        return None

    def check_binding(self):
        path = self.root / ".agents/orchestration.json"
        if not path.exists():
            return "missing", f"no {path.relative_to(self.root)}; fix: write the orchestrate-work binding (see {GUIDE})"
        try:
            binding = json.loads(path.read_text())
        except json.JSONDecodeError as error:
            return "wrong", f"{path.name} isn't JSON ({error}); fix: correct it"
        scripts = str(self.release() / "skills/orchestrate-work/scripts")
        if scripts not in sys.path:
            sys.path.insert(0, scripts)
        sys.dont_write_bytecode = True  # the release's modules leave no bytecode in the installed generation
        import merge_queue  # noqa: E402  (the installed release's own binding check)
        errors = merge_queue.binding_errors(binding)
        unrunnable = tracker_publisher.settings(self.root, self.c.flow_raw if self.c else None, binding)
        if errors and unrunnable["unrunnable"]:
            # The schema refuses it too, but only this says what replaces it.
            return "wrong", f"{path.name} doesn't validate: {tracker_publisher.refusal(unrunnable)}"
        if errors:
            return "wrong", (f"{path.name} doesn't validate: {'; '.join(errors[:3])}"
                             f"{f' (and {len(errors) - 3} more)' if len(errors) > 3 else ''}; fix: correct it against "
                             "orchestration-binding/1")
        self.binding = binding
        return "ok", f"{path.name} validates against orchestration-binding/1"

    def candidate_step(self):
        import merge_queue  # noqa: E402  (the installed release's own, which check_binding put on the path)
        argv = self.binding["candidate"]
        problems = merge_queue.candidate_problems(argv, lambda relative: (self.root / relative).is_file(),
                                                  os.environ.get("PATH"))
        if problems:
            return "wrong", (f"the binding's candidate step can't run: {'; '.join(problems)}; fix: correct its argv in "
                             ".agents/orchestration.json, then run it once by hand with a branch that exists")
        return "ok", f"{' '.join(argv)} resolves"

    def base(self) -> str | None:
        """The delivery base: the named delivery file's baseBranch, or the binding's base.ref (also when the file
        can't be read, which the delivery row reports)."""
        key = self.args.doctor_delivery or self.args.delivery or setting("RUN_DELIVERY_DELIVERY")
        try:
            d = self.c.shelf.json(f"{self.c.deliveries_rel}/{key}.json") if key else None
        except ValueError:
            d = None
        return (d if isinstance(d, dict) else {}).get("baseBranch") or self.c.binding_base

    def base_ref(self) -> str | None:
        base = self.base()
        return f"{self.c.remote}/{base}" if base else None

    def committed(self):
        ref = self.base_ref()
        if not ref:
            return "wrong", "no delivery base; fix: set base.ref in the binding"
        if not OFFLINE:  # what lanes will check out; --offline reads the local remote-tracking ref instead
            run(["git", "fetch", "-q", self.c.remote, self.base()], cwd=self.root, check=False)
        if run(["git", "rev-parse", "--verify", "--quiet", ref], cwd=self.root, check=False).returncode != 0:
            return "wrong", (f"the delivery base {ref} doesn't exist{' locally' if OFFLINE else ''}; fix: push the "
                             "delivery base")
        shown = run(["git", "show", f"{ref}:.agents/orchestration.json"], cwd=self.root, check=False)
        try:
            theirs = json.loads(shown.stdout) if shown.returncode == 0 else None
        except json.JSONDecodeError:
            theirs = None
        if isinstance(theirs, dict) and isinstance(theirs.get("base"), dict) and not serves(theirs, self.base()):
            # Lanes and the merge queue read the binding from the base itself.
            return "wrong", (f"{ref}'s binding doesn't serve the base {self.base()}, as a base cut before its binding "
                             f"gained bases doesn't; fix: commit the binding with its bases on {self.base()} and push "
                             f"it (see {BASE_MISMATCH})")
        entry = git("ls-tree", ref, ".agent-skills/current", cwd=self.root, check=False)
        fix = f"commit the installed release (.agent-skills) on {ref} and push it, so every lane resolves {TOOL_PATH}"
        if not entry:
            return "wrong", f"{ref} has no .agent-skills/current; fix: {fix}"
        target = git("cat-file", "-p", entry.split()[2], cwd=self.root, check=False)
        if not entry.startswith("120000") or target.startswith("/"):
            return "wrong", f".agent-skills/current on {ref} isn't a link inside the repository; fix: {fix}"
        tool = (Path(".agent-skills") / target / "skills/run-delivery/scripts/run_delivery.py").as_posix()
        if not git("ls-tree", ref, tool, cwd=self.root, check=False):
            return "wrong", f"{ref} doesn't carry {tool}; fix: {fix}"
        running = self.c.release.resolve().name
        if Path(target).name != running and not self.c.release_override:
            return "wrong", f"{ref} carries generation {Path(target).name[:12]}, not the running {running[:12]}; fix: {fix}"
        return "ok", f"{ref} carries the installed generation, so lanes resolve {TOOL_PATH}"

    def gates(self):
        c = self.c
        if not c.gates and c.flow_raw.get("gates") != "none":
            return "wrong", ("no gates are declared; fix: declare the binding's fallback checks, or set "
                             f"\"gates\": \"none\" in {c.name} if the repository has none")
        unknown = [g["id"] for g in c.gates if g.get("unknown")]
        if unknown:
            return "wrong", (f"the gates name checks the binding doesn't define: {', '.join(unknown)}; fix: name a "
                             f"selection.catalogue, alwaysRun or fallback id, or correct {c.name} gates")
        prepare = prepare_commands()
        made = []

        def found(argv0: str, cwd: str = ".") -> bool:
            # A relative program no commit tracks, such as .venv/bin/python, is one the prepare steps make: a fresh
            # clone lacks it until they run, and the gates run after them.
            if prepare and "/" in argv0 and not Path(os.path.expanduser(argv0)).is_absolute() and not git(
                    "ls-files", "--", (Path(cwd) / argv0).as_posix(), cwd=self.root, check=False):
                made.append(argv0)
                return True
            return resolves(argv0, self.root, cwd)

        lost = [f"gate {g['id']} ({g['argv'][0]})" for g in c.gates if not found(g["argv"][0], g.get("cwd", "."))]
        lost += [f"prepare step {argv[0]}" for argv in prepare if not resolves(argv[0], self.root)]
        if lost:
            return "wrong", f"these don't resolve: {', '.join(lost)}; fix: install them, or correct the binding"
        named = [g["id"] for g in c.gates if g.get("check")]
        return "ok", ((f"{len(c.gates)} gate(s): {', '.join(g['id'] for g in c.gates)}" if c.gates
                       else f"none ({c.name} says so)")
                      + (f"; run through run-checks: {', '.join(named)}" if named else "")
                      + (f"; made by the prepare steps: {', '.join(sorted(set(made)))}" if made else ""))

    def lanes(self):
        c = self.c
        probe = c.lane_checkout("doctor-probe")
        try:
            relative = probe.relative_to(c.main)
        except ValueError:
            return "ok", f"lane checkouts live outside the repository ({c.lane_pattern})"
        if run(["git", "check-ignore", "-q", str(relative)], cwd=c.main, check=False).returncode != 0:
            return "wrong", (f"{relative.parent}/ isn't ignored by git, so lane checkouts would show as untracked; "
                             f"fix: add {relative.parent}/ to .gitignore")
        return "ok", f"{c.lane_pattern} is ignored by git"

    def tracker(self):
        url = self.c.issue_url
        if not url or url == "{key}" or "{key}" not in url:
            return "missing", ("no tracker issue URL; fix: set tracker.issueUrl (with {key}) in "
                               f"{self.c.name} or .agents/delivery-views.json")
        return "ok", f"{url} ({self.c.sources.get('tracker.issueUrl')})"

    def review_pr(self):
        try:
            conf = pr_review_config()
        except Stop as error:
            return "wrong", f"{error}; fix: correct review.pr (see references/config.md)"
        if not conf:
            return self.not_applicable("no review.pr configured")
        if not forge_answers("reviews"):
            return "wrong", (f"review.pr is configured, but the {self.c.forge.get('adapter')} adapter has no `reviews` "
                             "command, so hand-offs would wait on a review that never comes; fix: remove review.pr, "
                             "or use an adapter that answers `reviews`")
        warnings_ = []
        if not conf["legacy"]:
            refused = pr_review_gates.forge_refusal(conf["reviewers"], self.c.forge.get("adapter"))
            if refused:
                return "wrong", refused
            unsigned = [r for r in conf["reviewers"] if not r.get("signature")]
            alone = [r["id"] for r in unsigned if not r.get("account")]
            if alone:
                warnings_.append(f"{', '.join(alone)} {'is' if len(alone) == 1 else 'are'} matched by display name "
                                 "alone, which another bot posting under that name also matches; fix: give each an "
                                 "`account` or a `signature`")
            for member in ("account", "author"):
                by: dict[str, list[str]] = {}
                for r in unsigned:
                    if r.get(member):
                        by.setdefault(r[member], []).append(r["id"])
                for value, ids in by.items():
                    if len(ids) > 1:
                        warnings_.append(f"{' and '.join(ids)} share the {member} {value!r} with no `signature`, so "
                                         "each matches the other's comments; fix: give each a `signature`")
        if warnings_:
            return "warn", "; ".join(warnings_)
        return "ok", "the forge adapter answers `reviews`"

    def gh(self):
        if self.c.forge.get("argv") or self.c.forge.get("adapter") != "github":
            return self.not_applicable("the GitHub adapter isn't configured")
        if not shutil.which("gh"):
            return "missing", "gh isn't installed, and the GitHub adapter uses it; fix: install gh"
        if OFFLINE:
            return "ok", "gh is installed (its sign-in isn't checked with --offline)"
        if run(["gh", "auth", "status"], check=False).returncode != 0:
            return "wrong", "gh isn't signed in; fix: gh auth login"
        return "ok", "gh is installed and signed in"

    def forge(self):
        f = self.c.forge
        if not f.get("argv") and not f.get("adapter"):
            return self.not_applicable("no forge configured")
        if OFFLINE:
            return "skipped", "(--offline)"
        if not f.get("argv") and f.get("adapter") == "bitbucket":
            name = f.get("tokenEnv")
            if not name:
                return "missing", ("no token variable for the Bitbucket adapter; fix: name it as forge.tokenEnv, or "
                                   "in the binding's forgeSnapshot --token-env")
            if not os.environ.get(name):
                return "missing", f"{name} is unset, and the Bitbucket adapter reads its token from it; fix: export {name}"
        try:
            forge("find", "--source", self.c.branch("doctor-probe"))
        except Stop as error:
            return "wrong", (f"{error}; fix: check the forge adapter's settings and that the forge is reachable, or "
                             "run doctor with --offline")
        return "ok", f"the {f.get('adapter') or 'configured'} adapter answers `find`"

    def forge_write(self):
        f = self.c.forge
        if not f.get("argv") and not f.get("adapter"):
            return self.not_applicable("no forge configured")
        return "skipped-ok", "(not verified: doctor never writes to a forge; open-pr is the first write)"

    def tracker_token(self):
        argv = (((self.binding or {}).get("state") or {}).get("trackerSnapshot") or {}).get("argv") or []
        # Without a readable configuration there is no adapter, only the snapshot's variables.
        adapter = (tracker_publisher.settings(self.root, self.c.flow_raw, self.binding or {}).get("adapter")
                   if self.c else None) or {}
        own = [adapter[field] for field in ("tokenEnv", "userEnv") if adapter.get(field)]
        if not argv and not own:
            return self.not_applicable("the binding declares no tracker snapshot")
        names = [argv[i + 1] for i, a in enumerate(argv[:-1]) if a in ("--token-env", "--user-env")]
        names += [name for name in own if name not in names]
        unset = [name for name in names if not os.environ.get(name)]
        if unset:
            return "missing", (f"{', '.join(unset)} {'is' if len(unset) == 1 else 'are'} unset, and the tracker "
                               f"snapshot or adapter reads {'it' if len(unset) == 1 else 'them'}; fix: export "
                               f"{', '.join(unset)}")
        return "ok", f"{', '.join(names) or 'no variables'} set"

    def tracker_scope(self):
        """The Jira snapshot's --scope and --status-state, against the project: run with --check, it names each
        component, label or status the project doesn't know, the In Progress statuses left to their category, and the
        in-scope children that carry no value of a scoped kind."""
        spec = ((self.binding or {}).get("state") or {}).get("trackerSnapshot") or {}
        argv = list(spec.get("argv") or [])
        if not any(part in ("--scope", "--status-state") for part in argv):
            return self.not_applicable("the tracker snapshot sets no --scope or --status-state")
        if self.tracker_token()[0] != "ok":  # Its own row, next, says which variable to export.
            return "skipped", "(needs tracker-token)"
        state = getattr(self.c, "state", None) or self.c.main / self.c.state_rel
        try:
            parent = json.loads((Path(state) / "state.json").read_text())["meta"].get("trackerParent")
        except (OSError, ValueError, KeyError, TypeError):
            parent = None
        parent = parent or getattr(self.c, "delivery", None)
        if not parent:
            return self.not_applicable("no delivery's tracker parent to check against")
        try:
            taken = run(expand_argv(argv, stateDirectory=str(state), parent=parent) + ["--check"], cwd=self.root,
                        check=False, timeout=int(spec.get("timeoutSeconds", 60)))
        except subprocess.TimeoutExpired:
            return "wrong", "the tracker snapshot's --check timed out"
        try:
            found = json.loads(taken.stdout) if taken.returncode == 0 else None
        except ValueError:
            found = None
        if not isinstance(found, dict) or found.get("check") != "tracker-scope/1":
            return "wrong", f"the tracker snapshot's --check failed: {(taken.stderr or taken.stdout).strip()[-200:]}"
        lines = []
        if "--scope" in argv and "--state-dir" not in argv:
            lines.append("it sets --scope without --state-dir {stateDirectory}, so the delivery file's stories aren't "
                         "kept in scope; fix: add --state-dir {stateDirectory}")
        if found["unknown"]:
            lines.append(f"the project has no {', '.join(found['unknown'])}; fix: correct the binding's trackerSnapshot")
        if found["unmapped"]:
            lines.append(f"In Progress statuses with no --status-state: {', '.join(found['unmapped'])}; map each, or "
                         "leave it to its category")
        if found["unmarked"]:
            lines.append(f"in scope with no scoped value: {', '.join(found['unmarked'])}; tag each in the tracker")
        if found["unknown"]:
            return "wrong", "; ".join(lines)
        return ("warn", "; ".join(lines)) if lines else ("ok", "every scope value and mapped status is known")

    def hosted(self):
        try:
            settings=hosted_settings(self.c)
            if settings is None:return self.not_applicable('hosted publishing is disabled')
            _,member=settings
            token=HOSTED_TOKENS.get((member['tokenEnv'],member['origin'],member['repositoryId']))
            said=hosted_line(self.c) or 'hosted: pending'
            if not token:return 'warn',said+'; '+member['tokenEnv']+' is unset; export it to start or retry publishing'
            return 'ok',said
        except (Stop,ValueError,OSError):return 'wrong','hosted configuration is invalid; correct .agents/delivery-views.json'

    def publishing(self):
        problems = publishing_problems(self.c, self.binding)
        # Siblings are a snapshot source too: a record that names them, with nothing in the binding to read them.
        sibling_status, sibling_said = self.siblings()
        if sibling_status == "wrong":
            problems.append(sibling_said)
        if problems:
            return "wrong", "; ".join(problems)
        state = self.binding.get("state") or {}
        conf = tracker_publisher.settings(self.root, self.c.flow_raw, self.binding or {})
        updates = {"publisher": f"the {conf['publisher']} tracker publisher posts tracker updates",
                   "manual": f"the lead posts tracker updates by hand ({self.c.name} sets tracker.updates to manual)"}
        said = [*(["a forge snapshot"] if state.get("forgeSnapshot") else []),
                *([f"sibling deliveries ({sibling_said})"] if sibling_status == "ok" else []),
                *([updates[conf["mode"]]] if conf["mode"] in updates else [])]
        loose = tracker_publisher.untargeted(conf) if conf["mode"] == "publisher" else []
        if conf["transitions"].get("review"):
            when = conf["transitions"].get("reviewWhen")
            said.append(f"tracker.transitions.reviewWhen is {when}" if when else
                        "tracker.transitions.reviewWhen is unset, so lanes make the review move by hand")
        return "ok", ("; ".join(said) or "the binding has neither a forge snapshot nor a tracker publisher, and needs "
                      "neither") + (f"; these moves name no status in tracker.transitions.targets, so one a person "
                                    f"already made shows as not offered: {', '.join(loose)}" if loose else "")

    def siblings(self):
        """Each sibling delivery the record names, with its last read's outcome, and a binding that never reads them:
        part of the snapshots and publishers check."""
        # A configuration resolves its state directory only once a delivery is selected.
        state = getattr(self.c, "state", None)
        if state is None:
            return self.not_applicable("no delivery selected")
        try:
            record = json.loads((Path(state) / "state.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return self.not_applicable("no record yet")
        named = [row for row in (record.get("siblings") or []) if isinstance(row, dict)] if isinstance(record, dict) else []
        if not named:
            return self.not_applicable("the record names no sibling delivery")
        said = "; ".join(f"{row.get('name')}: {row.get('lastOutcome') or 'never read'}" for row in named)
        if not ((self.binding or {}).get("state") or {}).get("siblingSnapshot"):
            return "wrong", (f"the record names sibling deliveries ({said}), but the binding has no "
                             f"state.siblingSnapshot, so they are never read; fix: add state.siblingSnapshot to the "
                             f"binding (delivery-views' hosted.py siblings --state-dir {{stateDirectory}} prints one)")
        return "ok", said

    def node(self):
        problem = node_problem(self.release())
        if problem:
            return problem
        wanted = node_minimum(self.release())
        if not wanted:
            return self.not_applicable("the generation carries no runtime")
        if ADOPTED_NODE:
            return "ok", (f"{ADOPTED_NODE['path']}, nvm's Node {ADOPTED_NODE['version']}, meets the runtime's "
                          f"nodeMinimum {wanted}; the tool puts it first on PATH for itself and every process it starts, "
                          f"since {replaced_words(ADOPTED_NODE, wanted)}")
        return "ok", f"{node_on_path()[0]} meets the runtime's nodeMinimum {wanted}"

    def awake(self):
        if sys.platform != "darwin":
            return self.not_applicable("not macOS: lead-run keeps nothing awake here, so keep the machine from "
                                       "sleeping while a delivery runs")
        program = shutil.which("caffeinate")
        if not program:
            return "warn", ("no caffeinate on PATH, so lead-run can't keep the machine awake while it runs; fix: put "
                            "/usr/bin back on PATH")
        return "ok", f"lead-run holds {program} -i -w <its pid> while it runs, so the machine doesn't idle-sleep under it"

    def in_app(self):
        ia = self.c.in_app
        if not ia:
            return self.not_applicable("no in-app checks declared")
        program = lambda part: ((ia.get(part) or {}).get("argv") or [""])[0]
        lost = [f"{part} ({program(part) or 'not declared'})" for part in ("build", "serve", "check")
                if not resolves(program(part), self.root)]
        if lost:
            return "wrong", f"these in-app adapters don't resolve: {', '.join(lost)}; fix: install them, or correct inApp"
        folders = [Path(expand(ia["lock"])).parent] + ([Path(expand(ia["baseline"]))] if ia.get("baseline") else [])
        unwritable = [problem for problem in map(writable, folders) if problem]
        if unwritable:
            return "wrong", f"{'; '.join(unwritable)}; fix: make it writable, or point inApp elsewhere"
        return "ok", "build, serve and check resolve; the lease and baseline folders are writable"

    def adapters(self):
        ia = self.c.in_app
        if not ia:
            return self.not_applicable("no in-app checks declared")
        if not self.args.run_adapters:
            return "skipped", "(needs --run-adapters)"
        try:
            lease = Lease(Path(expand(ia["lock"])), ia["port"], "doctor", 0)
        except Stop as held:
            holder = re.search(r"held \((.*)\); gave up", str(held))
            return "skipped", f"(lease held by {holder.group(1) if holder else 'another holder'})"
        failures = adapter_contract(ia, lease, lambda line: None)
        if failures:
            return "wrong", f"the in-app adapters break the contract: {'; '.join(failures)[:600]}; fix: see {GUIDE}"
        return "ok", "the in-app adapters keep the contract on the fixture page"

    def video(self):
        c = self.c
        def stories(key: str) -> dict:
            try:  # an unreadable delivery file is the delivery check's to report
                return (c.shelf.json(f"{c.deliveries_rel}/{key}.json") or {}).get("stories") or {}
            except ValueError:
                return {}
        marked = [k for key in c.delivery_keys() for k, s in stories(key).items() if s.get("evidence") == "video"]
        if not marked:
            return self.not_applicable("no story is marked for video evidence")
        problem = video_tools_problem()
        if problem:
            status, _, rest = problem.partition(": ")
            return status, rest
        return "ok", f"ffmpeg and ffprobe have what video evidence uses ({', '.join(marked)} marked)"

    def harness(self):
        c = self.c
        if not (self.root / "harness.config.ts").exists():
            return self.not_applicable("no harness.config.ts")
        if c.flow_raw.get("harness") == "ignore":
            return self.not_applicable(f"{c.name} ignores harness.config.ts")
        if not find_node22():
            return "missing", "harness.config.ts needs Node 22.6 or newer to read; fix: install Node 22.6 or newer"
        if not (c.release / "runtime/loader.mjs").exists():
            return "wrong", ("the generation carries no runtime loader (runtime/loader.mjs); fix: install a product "
                             "release, which carries the runtime")
        settings, how = load_harness(self.root, c.release)
        if settings is None:
            return "wrong", f"{how}; fix: correct harness.config.ts"
        return "ok", "Node reads harness.config.ts through the generation's runtime loader"

    def knowledge(self):
        """The adopting repository's knowledge-properties document, read only and checked for shape: whether the
        library holds its project is the first search's to show. With no document the optional library is available,
        not configured, and nothing stands in for the document."""
        rel = KNOWLEDGE_PROPERTIES
        path = self.root / rel
        if not path.exists():
            return "ok", (f"no {rel} found, so the knowledge library is available, not configured, and isn't "
                          f"consulted; to consult it, write that file (see {GUIDE})")
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            return "wrong", f"{rel} isn't JSON ({error}); fix: correct it (see {GUIDE})"
        problem = knowledge_properties_problem(document)
        if problem:
            return "wrong", f"{rel} isn't a valid {KNOWLEDGE_SCHEMA}: {problem}; fix: correct it (see {GUIDE})"
        server = "read-only " + document["name"] if document["server"] == "read-only" else "plugin"
        tags = f", tags {', '.join(document['tags'])}" if document.get("tags") else ""
        return "ok", (f"{rel} is valid: server {server}, project {document['project']}{tags}; the first search shows "
                      f"whether the library holds that project (see {GUIDE})")

    def check_delivery(self):
        key = self.args.doctor_delivery or self.args.delivery
        if not key:
            return "skipped", "(needs --delivery)"
        try:
            d = Config(self.root, key, tolerant=True)
        except ValueError as error:
            return "wrong", f"the delivery file isn't JSON ({error}); fix: correct it"
        except Stop as error:
            return "missing" if "is missing" in str(error) else "wrong", f"{error}; fix: see {GUIDE}"
        unassigned = [k for k, s in d.stories.items() if s.get("lane") not in d.lanes]
        if unassigned:
            return "wrong", f"stories without a lane: {', '.join(unassigned)}; fix: give each a lane in `lanes`"
        files = git("ls-tree", "-r", "--name-only", d.base_ref if self.base_ref() else "HEAD", cwd=self.root,
                    check=False).splitlines()
        overlaps = ownership_overlaps(d.effective_ownership(d.record_state()), files, shared_outputs(d))
        if overlaps:
            return "wrong", f"lanes own the same files: {'; '.join(overlaps)}; fix: make each lane's `owns` disjoint"
        self.delivery = d
        return "ok", f"{key}: {len(d.stories)} stories across {len(d.lanes)} lanes, each owning its own files"

    def record_folder(self):
        d = self.delivery
        note, kept = d.record_apart_note(), f"{d.state} ({d.sources.get('state')})"
        if d.state != d.record_apart(d.delivery):
            return "ok", kept
        # A record kept apart is checked for git's ignore while its key collides and after its story is removed.
        try:
            relative = d.state.relative_to(d.main)
        except ValueError:
            return ("warn", note) if note else ("ok", kept)
        if run(["git", "check-ignore", "-q", str(relative)], cwd=d.main, check=False).returncode != 0:
            return "wrong", (f"{relative}/ isn't ignored by git, so the record would show as untracked; fix: add "
                             f"{d.work}/ to .gitignore, or set stateDirectory in {d.delivery_where}")
        return ("warn", note) if note else ("ok", kept)

    def check_plan(self):
        d = Config(self.root, self.args.doctor_delivery or self.args.delivery, tolerant=True)
        if not plan_declared(d):
            return self.not_applicable("no criteria declared; the plan chapter is off")
        log = read_plan_log(d) if d.flow_log.exists() else []
        if not any(entry["type"] == "snapshot" for entry in log):
            log = [snapshot_entry(d, late=(d.state / "state.json").exists())]
        plan = build_plan(d, log)
        check_plan(plan, d)
        criteria = sum(len(unit["criteria"]) for unit in plan["units"] if not unit.get("removed"))
        return "ok", (f"{criteria} criteria across {len(d.stories)} stories; the plan they make passes "
                      "delivery-views check-plan")

    def plan_reasons(self):
        """Every story the record holds as an `added` change has its reason, and none is waiting to be registered
        without one."""
        d = self.delivery
        log = read_plan_log(d) if d.flow_log.exists() else []
        whys = {entry["change"] for entry in log if entry["type"] == "why"}
        # A story-level addition: a criterion added to a story carries its criteria, and is the plan chapter's own flag.
        bare = [entry for entry in log if entry["type"] == "change" and entry["kind"] == "added"
                and not entry.get("criteria") and not entry.get("why") and entry["id"] not in whys
                and any(key in d.stories for key in entry["subjects"])]
        waiting = []
        if (d.state / "state.json").exists():
            doc = shown_record(d.release, d.state)
            waiting = unreasoned_problems(d, unregistered(d, doc["state"]))
        problems = []
        if bare:
            problems.append("the record holds an `added` change with no reason: "
                            + ", ".join(f"{entry['id']} adds {', '.join(entry['subjects'])}" for entry in bare) + "; fix: "
                            + "; ".join(f"{flow_command()} lead-plan why {entry['id']} --why TEXT" for entry in bare))
        if waiting:
            problems.append(f"{'; '.join(waiting)}, so registration refuses it; fix: give it a `why` in "
                            f"{d.delivery_where}, then commit and push it")
        if problems:
            return "wrong", "; ".join(problems)
        if not log and not waiting and not plan_declared(d):
            return self.not_applicable("no plan chapter, so no story is recorded as an added change")
        return "ok", "every story added to the plan has its reason"

    def stories_planned(self):
        d = self.delivery
        problems = plan_problems(d, list(d.stories))
        return ("wrong", problems[0]) if problems else ("ok", f"each of the {len(d.stories)} stories has a section in {d.plan}")

    def story_files(self):
        d = self.delivery
        problems = story_file_problems(d, list(d.stories), tracked_at_base(d))
        if not problems:
            return "ok", "every file a story's plan section names is its lane's"
        # A warning, not a failure: a plan may move a file between lanes as its stories merge.
        return "warn", ("; ".join(problems) + "; fix: move each to the story's lane's owns before it starts, or plan the "
                        "story on the lane that owns it")

    def story_readiness(self):
        d = self.delivery
        if not tracker_conf(d)["transitions"].get("start"):
            refining = [] if (d.state / "state.json").exists() else [
                line for key in d.stories if (line := refine_outcome(d, key)) is not None]
            return "ok", ("lanes make no start move, so there is no readiness to check"
                          + (f"; at the plan's approval: {'; '.join(refining)}" if refining else ""))
        if (d.state / "state.json").exists():
            doc = shown_record(d.release, d.state)
            waiting = [e["subject"] for e in doc["state"].get("planned", []) if e.get("stage") == "planned"]
        else:  # Before lead-init, every story is still to start.
            waiting = list(d.stories)
        found = {key: story_readiness(d, key) for key in waiting if key in d.stories}
        unready = [line for state, line in found.values() if state == "not-ready"]
        unchecked = [line for state, line in found.values() if state == "not-checked"]
        # Before lead-init, what its plan's approval will do to each story, as lead-init says it.
        refining = [] if (d.state / "state.json").exists() else [
            line for key in waiting if key in d.stories and (line := refine_outcome(d, key)) is not None]
        said = f"; at the plan's approval: {'; '.join(refining)}" if refining else ""
        if unready:
            # A warning: lead-assign refuses these, and --force overrides it.
            return "warn", ("; ".join(unready + unchecked) + "; fix: have each item made ready before its lane starts"
                            + said)
        if unchecked:
            return self.not_applicable("; ".join(unchecked) + said)
        return "ok", (f"each of the {len(found)} stories still planned is ready for its next start move"
                      if found else "no story is still waiting to start") + said

    def story_summaries(self):
        d = self.delivery
        items = tracker_snapshot_items(d)
        if items is None:
            return self.not_applicable("there is no tracker snapshot")
        bare = [key for key in d.stories if key in items and not items[key].get("summary")]
        if bare:
            # A warning, not a failure: a story with no summary still delivers; only its card shows none.
            return "warn", ("; ".join(no_summary(key) for key in bare)
                            + "; fix: add a one-paragraph `## Summary` to each ticket")
        listed = sum(1 for key in d.stories if key in items)
        return "ok", f"each of the {listed} stories the tracker snapshot lists has a summary"

    def context_planned(self):
        d = self.delivery
        if not d.context_sections:
            return self.not_applicable("no context.sections declared")
        problems = context_problems(d)
        return ("wrong", problems[0]) if problems else ("ok", f"{d.plan} has each of {', '.join(map(repr, d.context_sections))}")

    def finish_lines(self):
        d = self.delivery
        if not d.finish:
            return self.not_applicable("no finish lines declared")
        bare = [line.get("id", "?") for line in d.finish if "covers" not in line]
        if bare:
            # A warning, not a failure: a line with no `covers` is still read as covering every criterion.
            return "warn", (f"{', '.join(bare)} {'declares' if len(bare) == 1 else 'declare'} no `covers`, so the "
                            "supervisor reads each as covering every criterion and marks it met once every story's "
                            "proofs are done; fix: give each its `covers`, `{\"criteria\": [], \"proofs\": []}` for a "
                            "line you check and mark yourself")
        lead = sum(1 for line in d.finish if leads_line(line))
        return "ok", (f"each of the {len(d.finish)} finish lines declares its `covers`; "
                      f"{lead} {'is' if lead == 1 else 'are'} yours to check and mark")

    def remote_base(self):
        d = self.delivery
        if setting("RUN_DELIVERY_LOCAL") == "1" or setting("RUN_DELIVERY_CONFIG"):
            return self.not_applicable("a local setup: lanes read their own working tree")
        problem = remote_base_problem(d)
        return ("wrong", problem) if problem else ("ok", f"{d.base_ref} carries the configuration and the delivery file")

    def ready(self):
        problem = ready_problem(self.delivery)
        if problem:
            return "wrong", problem
        if not self.delivery.forge.get("mergeNeedsReady"):
            return self.not_applicable("the merge step takes a draft (no forge.mergeNeedsReady)")
        return "ok", "lead-accept marks each draft ready under the readyPullRequests grant"

    def supervisor(self):
        d = self.delivery
        if not (d.state / "state.json").exists():
            return self.not_applicable("no record yet: lead-init starts it, and its supervisor")
        held, recorded = read_lock(supervisor_lock_path(d))
        if not held:
            said = closed_status(d)
            if said is not None:
                return ("wrong" if said.startswith("stopped partway") else "ok"), said
            return "wrong", f"the supervisor is down; fix: {flow_command()} lead-run --resume"
        status, node = self.supervisor_node(recorded)
        running = f"running (pid {recorded.get('pid')}); live view {recorded.get('address')}"
        # A Node it can't keep is the row's last words, so its fix ends the line.
        said = lambda more="": (f"{running}; {node}{more}{waits_on(d)}" if status == "ok" else
                                f"{running}{more}{waits_on(d)}; {node}")
        if not Path("/proc/self/status").exists():
            return status, said(". Its children's signal dispositions can't be read on this host (no /proc); it starts "
                                "them with the defaults")
        ignored = []
        for child in recorded.get("children") or []:
            status_file = Path(f"/proc/{child.get('pid')}/status")
            mask = next((int(line.split()[1], 16) for line in status_file.read_text().splitlines()
                         if line.startswith("SigIgn:")), 0) if status_file.exists() else 0
            names = [name for name, number in (("SIGINT", 2), ("SIGHUP", 1), ("SIGQUIT", 3)) if mask >> (number - 1) & 1]
            if names:
                ignored.append(f"{child.get('name')} (pid {child.get('pid')}) ignores {', '.join(names)}")
        if ignored:
            return "wrong", (f"the supervisor's children don't have the default signal dispositions: "
                             f"{'; '.join(ignored)}, so their checks fail as a broken base"
                             + (f"; and {node.split('; fix: ')[0]}" if status != "ok" else "")
                             + f"; fix: lead-close or stop them, then {flow_command()} lead-run --resume")
        return status, said()

    def peers(self):
        """The other deliveries registered on this base, each with what its queue is checking and has queued; an
        entry that can't be read is named, and fails nothing."""
        found = peer_deliveries(self.delivery)
        if not found:
            return "ok", f"no other delivery is registered on {self.delivery.base_branch}"
        return "ok", " | ".join(peer_line(peer) for peer in found)

    def merge_slot(self):
        return "ok", slot_line(self.delivery)

    def supervisor_node(self, recorded: dict) -> tuple[str, str]:
        """The Node the running supervisor recorded in its lock as it started, which its queue's checks run unless
        their profile says otherwise, judged against the runtime's nodeMinimum: (status, words)."""
        wanted = node_minimum(self.delivery.release)
        restart = (f"stop it (pid {recorded.get('pid')}), then run {flow_command()} lead-run --resume"
                   + (f" with Node {wanted} or newer first on PATH or in nvm" if wanted else ""))
        if "node" not in recorded:
            return "warn", f"it recorded no Node, as an older generation's supervisor doesn't; fix: {restart}, which records it"
        node = recorded["node"]
        if not isinstance(node, dict):
            if wanted:
                return "wrong", f"it runs with no node on its PATH, and the runtime needs Node {wanted}; fix: {restart}"
            return "ok", "no node on its PATH"
        version = node.get("version")
        said = f"Node {version or 'of no readable version'} at {node.get('path')}"
        if wanted and not meets(numbers(version or "") or (0,), numbers(wanted) or ()):
            return "wrong", f"it runs {said}, below the runtime's nodeMinimum {wanted}; fix: {restart}"
        return "ok", said

    def base_gates(self):
        if not self.args.run_gates:
            return "skipped", "(needs --run-gates)"
        ref = self.base_ref()
        checkout = Path(tempfile.mkdtemp(prefix="run-delivery-doctor-")) / "base"
        try:
            git("worktree", "add", "--detach", "-q", str(checkout), ref, cwd=self.root)
            for argv in prepare_commands():
                run(argv, cwd=checkout)
            for g in self.c.gates:
                argv = expand_argv(g["argv"], base=ref, key="doctor", delivery=self.c.delivery or "")
                code, out = run_group(argv, checkout / g.get("cwd", "."), int(g.get("timeoutSeconds", 1800)))
                if code != 0:
                    return "wrong", f"gate {g['id']} fails on {ref}: {out.strip()[-300:]}; fix: repair the base first"
        finally:
            run(["git", "worktree", "remove", "--force", str(checkout)], cwd=self.root, check=False)
            shutil.rmtree(checkout.parent, ignore_errors=True)
        return "ok", f"every gate passes on {ref}, in a fresh prepared checkout (removed)"


# -- co-authored plan text -------------------------------------------------------------------------------------
# Before a delivery adopts it, a plan two engineers write together lives on plan/<reviewSlug>; once a delivery file
# names it, on lead/<key>. Both are pushed to the base remote. plan-sync composes the working copy's plan with the
# remote branch section by section (plan_sync.py) and pushes it; plan-watch prints one line per peer push. Neither
# needs a record.

COLLAB_POLL_SECONDS = 5
COLLAB_POLL_FLOOR = 2


# -- the co-lead runtime: which machine runs what on a shared record ------------------------------------------------

# Each supervisor pass step, and the close-out's, by what this checkout's seat must hold for it to run on a shared
# record: "delivery" and "queue" run only where the seat holds that scope; "lane" runs on every seat, for the stories of
# the lanes it holds, whose checkouts and review rounds are on its machine; "every" runs on every seat. The
# orchestration guide's "Which machine runs what" table says the same.
SHARED_STEPS = {"reconcile": "delivery", "regions": "delivery", "peers": "delivery", "grants": "delivery", "planView": "delivery",
                "finish": "delivery",
                "publish": "delivery", "cleanupBeforeClose": "delivery", "friction": "delivery", "closeOut": "delivery",
                "fullHealth": "queue", "lenses": "lane", "cleanup": "lane", "deferrals": "lane", "blockers": "every", "inputs": "every",
                "peerWaits": "every", "laneChanges": "every", "needs": "every", "render": "every", "latest": "every"}


def seat_roles(c) -> dict | None:
    """On a shared record: this checkout's seat, and whether it holds delivery and the queue, and the lanes it holds;
    None on an unshared record, or one that can't be read."""
    if getattr(c, "state", None) is None or not (json_object(Path(c.state) / "state.json").get("meta") or {}).get("collab"):
        return None
    tool = _validator(c.release)
    try:
        state = tool.read_state(c.state)
        collab = tool.collab_of(state)
        if collab is None:
            return None
        journal = tool.read_journal(c.state)
    except (tool.StateError, OSError, ValueError):
        return None
    seat = tool.local_seat(c.state, collab["key"])
    named = {row["id"] for row in state.get("lanes", [])} | set(state.get("laneOwnership") or {}) \
        | {item["lane"] for name in ("planned", "queue") for item in state.get(name, []) if item.get("lane")}
    return {"seat": seat, "delivery": tool.holds(journal, seat, "delivery"), "queue": tool.holds(journal, seat, "queue"),
            "lanes": {lane for lane in named if tool.holds(journal, seat, f"lane:{lane}")}}


def step_runs(roles: dict | None, name: str) -> bool:
    """Whether a pass step runs on this machine: every step on an unshared record; on a shared one, by SHARED_STEPS."""
    rule = SHARED_STEPS.get(name, "every")
    return roles is None or rule not in ("delivery", "queue") or roles[rule]


def lane_held(roles: dict | None, lane: str | None) -> bool:
    """Whether a lane's stories are this machine's to clean up, review and defer: every lane's on an unshared record."""
    return roles is None or lane in roles["lanes"]


def require_scope(c, scope: str, doing: str) -> None:
    """On a shared record, refuse a lead command this checkout's seat doesn't hold `scope` for, before it writes
    anything, naming the seat that holds it."""
    tool = _validator(c.release)
    state = json_object(c.state / "state.json")
    collab = (state.get("meta") or {}).get("collab")
    if not collab:
        return
    journal = tool.read_journal(c.state)
    seat = tool.local_seat(c.state, collab["key"])
    if seat is None:
        raise Stop(f"collab.seat_missing: this checkout has no seat for the shared record {collab['key']}; collab join "
                   "gives it one")
    if not tool.holds(journal, seat, scope):
        holder = tool.holder(journal, scope)
        label = (tool.derived_seats(journal).get(holder) or {}).get("label")
        raise Stop(f"scope.not_held: only the holder of {scope}, seat {holder}" + (f" ({label})" if label else "")
                   + f", {doing}; {flow_command()} collab request --scope {scope} --reason TEXT asks for it")


def take_delivery(c) -> str | None:
    """Where this seat was just given delivery: write what the seat that gave it carried as this machine's own, its
    hosted identity and how far its tracker ledger had posted, before this machine publishes anything, then resume the
    hosted session with that identity, so the public link stays. None when there is nothing to take."""
    tool = _validator(c.release)
    link = tool._collab()
    try:
        collab = tool.collab_of(tool.read_state(c.state))
        journal = tool.read_journal(c.state) if collab else []
    except (tool.StateError, OSError, ValueError):
        return None
    transfer = link.delivery_transfer(journal, tool.local_seat(c.state, collab["key"])) if collab else None
    if transfer is None or link.delivery_taken(c.state, journal):
        return None
    giver = transfer["data"]["from"]
    carried = link.peer_carried(c.state, giver)
    if carried is None:
        return None  # the giver's partition can't be read yet: taken on a later pass
    with tracker_publisher.ledger_lock(c.state, wait=True):
        if carried.get("hostedIdentity"):
            take_hosted(c, carried["hostedIdentity"])
        posted = tracker_publisher.take_through(c.state, sorted(journal, key=lambda e: e["id"]),
                                                carried.get("trackerThrough") or {}, giver)
        take_evidence(c, transfer, carried)
        link.take_delivery(c.state, transfer)
    # With an identity, its session resumes; without one, this machine's publisher starts its own.
    start_hosted(c, resume=bool(carried.get("hostedIdentity")))
    return (f"took delivery from seat {giver}: {posted} tracker update(s) it had posted, "
            + ("its hosted identity" if carried.get("hostedIdentity") else "no hosted identity"))


def take_evidence(c, transfer: dict, carried: dict) -> None:
    """D22, on taking delivery: this machine's own earlier evidence page and merged-base recordings are moved aside,
    so nothing judges against a page from before, and the giver's evidence notes and friction stub become its own."""
    aside = f"before-{transfer['origin']['seat']}.{transfer['origin']['seq']}"
    page = Path(c.state).parent / EVIDENCE_PAGE
    if page.exists():
        os.replace(page, page.with_name(f"{EVIDENCE_PAGE}.{aside}"))
    for key in c.stories:
        videos = Path(c.root) / c.work / "review" / key / "videos"
        if videos.is_dir():
            os.replace(videos, videos.with_name(f"videos.{aside}"))
    notes = Path(c.state).parent / EVIDENCE_NOTES
    if carried.get("evidenceNotes") is not None:
        replace_file(notes, json.dumps(carried["evidenceNotes"], indent=2) + "\n")
    else:
        notes.unlink(missing_ok=True)
    if carried.get("friction") is not None:
        stub = friction_stub_path(c)
        stub.parent.mkdir(parents=True, exist_ok=True)
        replace_file(stub, carried["friction"])


def lane_seat_words(c, lane: str) -> str | None:
    """On a shared record, the seat a lane reports to: the one holding its scope, by its label, whose session accepts
    the lane's hand-offs."""
    state = json_object(c.state / "state.json")
    if not (state.get("meta") or {}).get("collab"):
        return None
    tool = _validator(c.release)
    journal = tool.read_journal(c.state)
    holder = tool.holder(journal, f"lane:{lane}")
    label = (tool.derived_seats(journal).get(holder) or {}).get("label") or holder
    return (f"You report to {label} (seat {holder}), which holds {lane} on this shared record: its session accepts "
            "your hand-offs.")


def lane_checkouts_left(c, folder: Path, lane: str) -> list[str]:
    """The lane's merged or settled stories whose checkout is still on this machine: a lane is handed over only once its
    outgoing seat has cleaned them up, since no other machine can."""
    state = json_object(folder / "state.json")
    done = [item["subject"] for item in state.get("queue", []) if item.get("lane") == lane and item.get("stage") == "merged"]
    done += [item["subject"] for item in state.get("planned", []) if item.get("lane") == lane
             and item.get("stage") == "settled"]
    return [subject for subject in done if c.lane_checkout(subject).exists()]


def give_delivery(c, key: str, folder: Path, to: str, wait: float) -> dict:
    """Pass delivery to seat `to` as a parked transition: once no tracker post is in flight and no hosted publication
    is pending, holding the tracker ledger's lock so no post starts, stop this machine's hosted publisher, keep its
    identity and the ledger's position in this seat's partition, and journal the transfer. Busy past `wait` seconds,
    refuse with scope.handover_busy, naming what is busy, having written nothing."""
    tool = _validator(c.release)

    @contextlib.contextmanager
    def park(wait: float):
        deadline = time.monotonic() + wait
        while True:
            with tracker_publisher.ledger_lock(folder, wait=False) as free:
                busy = None if free else "a tracker post is in flight"
                if busy is None:
                    busy = hosted_pending(c, folder)
                if busy is None:
                    hosted_call(c, "stop", folder, key, archive=False)
                    busy = hosted_pending(c, folder)
                    if busy is None:
                        journal = sorted(tool.read_journal(folder), key=lambda e: e["id"])
                        friction = friction_stub_path(c)
                        yield {"hostedIdentity": carried_identity(c, folder),
                               "trackerThrough": tracker_publisher.through_by_seat(
                                   journal, tracker_publisher.read_ledger(folder)),
                               "evidenceNotes": load_json(folder.parent / EVIDENCE_NOTES),
                               "friction": friction.read_text(encoding="utf-8") if friction.is_file() else None}
                        return
                    with contextlib.suppress(Stop, OSError, ValueError, subprocess.SubprocessError):
                        hosted_call(c, "start", folder, key, archive=False)  # stopped mid-publication: it finishes it first
            if time.monotonic() >= deadline:
                raise Stop(f"scope.handover_busy: delivery is not idle on this machine: {busy}; hand it over once it "
                           "is, or wait longer")
            time.sleep(min(0.5, max(0.0, deadline - time.monotonic())))

    try:
        return tool._collab().give_scope(folder, "delivery", to, wait=wait, park=park)
    except tool.StateError as error:
        raise Stop(f"{error.code}: {error}") from None


def collab_settings(c) -> dict:
    """`collab.pollSeconds` (default 5, at least 2: each tick is one git fetch) and `collab.autoGrant` (default
    false), refused when out of range."""
    raw = c.flow_raw.get("collab", {})
    if not isinstance(raw, dict):
        raise Stop(f"{c.name} collab must be an object, not {raw!r}")
    poll = raw.get("pollSeconds", COLLAB_POLL_SECONDS)
    if isinstance(poll, bool) or not isinstance(poll, (int, float)) or poll < COLLAB_POLL_FLOOR:
        raise Stop(f"{c.name} collab.pollSeconds must be a number of seconds, at least {COLLAB_POLL_FLOOR}, not {poll!r}")
    grant = raw.get("autoGrant", False)
    if not isinstance(grant, bool):
        raise Stop(f"{c.name} collab.autoGrant must be true or false, not {grant!r}")
    return {"pollSeconds": poll, "autoGrant": grant}


def plan_branch(c, plan: Path) -> str:
    """lead/<key> when a delivery file names the plan, otherwise plan/<reviewSlug>."""
    path = c.root / plan
    if not path.is_file():
        raise Stop(f"no plan at {path}")
    slug = review_slug(plan, path.read_text(encoding="utf-8"))
    if slug is None:
        raise Stop(f"plan.no_review_slug: {plan} has no reviewSlug in its front matter, which names its branch, "
                   f"plan/<reviewSlug>; add one and commit it")
    named = os.path.normpath(plan)
    keys = sorted(d["delivery"] for d in (load_json(f) or {} for f in sorted(c.deliveries.glob("*.json")))
                  if isinstance(d.get("plan"), str) and os.path.normpath(d["plan"]) == named and d.get("delivery"))
    if len(keys) > 1:
        raise Stop(f"{len(keys)} delivery files name {plan}: {', '.join(keys)}; keep the plan in one")
    return f"lead/{keys[0]}" if keys else f"plan/{slug}"


def plan_collab_config(args):
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    settings = collab_settings(c)
    return c, Path(args.plan), plan_branch(c, Path(args.plan)), settings


def plan_sync_command(args) -> None:
    c, plan, branch, _ = plan_collab_config(args)
    scope = plan_scope_of(c, plan)
    try:
        for line in plan_sync.sync(c.root, plan.as_posix(), branch, c.remote, _region_ownership(), message=args.message,
                                   scope=scope):
            print(line)
    except plan_sync.Refused as error:
        raise Stop(str(error)) from None
    # The plan as it landed, on the one view the plan has. A view that can't be built never fails the sync.
    try:
        said = rebuild_plan_view(c, plan)
    except (Stop, OSError, ValueError, subprocess.SubprocessError) as error:
        said = f"not rebuilt: {error}"
    if said:
        print(f"plan view: {said}")


def plan_watch_command(args) -> None:
    c, plan, branch, settings = plan_collab_config(args)
    try:
        re.compile(args.until or "")
    except re.error as error:
        raise Stop(f"--until {args.until!r} isn't a regular expression: {error}") from None
    if args.timeout < 0:
        raise Stop(f"--timeout must be zero or more seconds, not {args.timeout:g}")
    try:
        code = plan_sync.watch(c.root, plan.as_posix(), branch, c.remote, _region_ownership(),
                               poll=settings["pollSeconds"], timeout=args.timeout, until=args.until,
                               write=lambda line: print(line, flush=True))
    except plan_sync.Refused as error:
        raise Stop(str(error)) from None
    if code:
        sys.exit(code)


# -- the planning record --------------------------------------------------------------------------------------------

def planning_records(c) -> list[tuple[str, Path, dict]]:
    """Every shared record kept under the work directory's deliveries/, where plan-open opens one and a seat that
    joins ingests it: each as its key, folder and state."""
    found = []
    for state in sorted((c.main / c.work / "deliveries").glob(f"*/{c.state_rel}/state.json")):
        record = json_object(state)
        collab = (record.get("meta") or {}).get("collab") or {}
        if isinstance(collab.get("key"), str):
            found.append((collab["key"], state.parent, record))
    return found


def planning_record_of(c, plan: Path) -> tuple[str, Path] | None:
    """The shared record plan-open opened for `plan`, by the plan file its record names."""
    named = os.path.normpath(plan)
    return next(((key, folder) for key, folder, record in planning_records(c)
                 if os.path.normpath(str(record["meta"].get("planFile") or "")) == named), None)


def open_planning_record(c, plan: Path) -> tuple[str, Path] | None:
    """The planning record opened for `plan` while it is still planning: once lead-init has taken it over, its plan is
    the delivery's, which the delivery builds, and nothing rebuilds it as a preview."""
    named = os.path.normpath(plan)
    return next(((key, folder) for key, folder, record in planning_records(c)
                 if os.path.normpath(str(record["meta"].get("planFile") or "")) == named
                 and record["meta"].get("phase") == "planning"), None)


def shared_record(c, plan: Path) -> tuple[str, Path] | None:
    """The key and folder of the shared record a plan is edited and approved under: that of the delivery whose file
    names the plan, else the planning record opened for it; None when neither is shared."""
    named = os.path.normpath(plan)
    found = [(d["delivery"], d) for d in c.delivery_files().values()
             if isinstance(d.get("plan"), str) and os.path.normpath(d["plan"]) == named and d.get("delivery")]
    if not found:
        return planning_record_of(c, plan)
    key, d = found[0]
    folder = c.state_of(key, d)
    return (key, folder) if (json_object(folder / "state.json").get("meta") or {}).get("collab") else None


def record_seat(c, key: str, folder: Path) -> tuple[object, list[dict], str]:
    """The state tool, the shared record's journal, and this checkout's seat on it, refused without one."""
    tool = _validator()
    seat = tool.local_seat(folder, key)
    if seat is None:
        raise Stop(f"collab.seat_missing: this checkout has no seat for the shared record {key}; collab join gives it one")
    return tool, tool.read_journal(folder), seat


def plan_scope(c, key: str, folder: Path) -> plan_sync.Held:
    """What this checkout's seat may change in the plan of the shared record `key`: the sections it holds."""
    tool, journal, seat = record_seat(c, key, folder)
    script = shlex.join([sys.executable, "-B", str(c.release / STATE_TOOL), "--dir", str(folder)])
    ask = lambda names: " and ".join(f"{script} scope request --scope {shlex.quote('plan:' + name)} --reason TEXT"
                                     for name in names)
    rekeys = [entry["data"] for entry in journal if entry["kind"] == "plan.rekeyed"]
    return plan_sync.Held(lambda text: tool.held_sections(journal, seat, text), rekeys, ask)


def plan_scope_of(c, plan: Path) -> plan_sync.Held | None:
    shared = shared_record(c, plan)
    return plan_scope(c, *shared) if shared else None


def committed_plan(c, plan: Path) -> None:
    """Refuse a plan that isn't committed as it stands: missing, untracked, or edited since its last commit."""
    path = c.root / plan
    tracked = run(["git", "ls-files", "--error-unmatch", "--", plan.as_posix()], cwd=c.root, check=False).returncode == 0
    if not path.is_file() or not tracked or git("status", "--porcelain", "--", plan.as_posix(), cwd=c.root):
        raise Stop(f"plan.uncommitted: {plan} isn't committed as it stands; commit it (plan-sync commits and pushes "
                   "an edit), then run this again")


def plan_commit(c, plan: Path) -> str:
    """The plan's current commit: the last commit on HEAD that changed it."""
    commit = git("rev-list", "-1", "HEAD", "--", plan.as_posix(), cwd=c.root)
    if not commit:
        raise Stop(f"plan.uncommitted: no commit on HEAD holds {plan}")
    return commit


def plan_open(args) -> None:
    """Open a planning record: the shared record of a delivery from its plan's first draft, whose first seat, this
    checkout's, holds every scope. lead-setup and lead-init take it over in place."""
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    plan = Path(args.plan)
    committed_plan(c, plan)
    slug = review_slug(plan, (c.root / plan).read_text(encoding="utf-8"))
    if slug is None:
        raise Stop(f"plan.no_review_slug: {plan} has no reviewSlug in its front matter, which names its planning "
                   "record's plan branch, plan/<reviewSlug>; add one, commit it, then run this again")
    if not re.fullmatch(PLAN_KEY, args.key):
        raise Stop(f"collab.key_invalid: {args.key!r} isn't a delivery key such as WORK-123")
    existing = [folder for folder in (c.lane_checkout(args.key) / c.state_rel, c.record_apart(args.key))
                if (folder / "state.json").exists()]
    if existing:
        raise Stop(f"collab.record_exists: {args.key} already has a record at {existing[0]}; it is left as it is")
    opened = planning_record_of(c, plan)
    if opened:
        raise Stop(f"collab.record_exists: {plan} already has the planning record {opened[0]} at {opened[1]}")
    folder = c.record_apart(args.key)
    tool = _validator()
    collab = tool._collab()
    ref = f"{c.remote}/{c.binding_base}" if c.binding_base else git("rev-parse", "--abbrev-ref", "HEAD", cwd=c.root)
    head = git("rev-parse", ref, cwd=c.root)
    try:
        collab.open_record(folder, key=args.key, headline=args.headline or args.key, base={"ref": ref, "head": head},
                           label=args.label)
        state = tool.read_state(folder)
        tool.patch(folder, writer="lead", version=state["version"], changes={"meta": {"planFile": plan.as_posix()}})
    except tool.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    seat = tool.local_seat(folder, args.key)
    label = tool.read_state(folder)["meta"]["collab"]["seats"][seat]["label"]
    print(f"opened the planning record of {args.key} at {folder}: seat {seat} ({label}) holds every scope; the plan "
          f"syncs on plan/{slug} with {flow_command()} plan-sync --plan {shlex.quote(plan.as_posix())}")
    # One plan view: a preview the plan has is handed to the planning record, which builds the plan from here on.
    preview = preview_folder(c, slug)
    if (preview / PREVIEW_FILE).is_file() and not (preview / PREVIEW_HANDED).exists():
        print(preview_handed_finish(c, preview, plan, {"delivery": args.key}).replace(
            f"handed to delivery {args.key}", f"handed to the planning record of {args.key}"))
    try:
        rebuild_planning_plan(c, plan, args.key, folder)
    except (Stop, OSError, ValueError, subprocess.SubprocessError) as error:
        print(f"plan: not built: {error}")
    # The planning record's supervisor: its live view, the sync loop and hosted publishing, under the record's key.
    c = CFG = Config(repo(), args.key)
    start_hosted(c)
    if (line := hosted_line(c)):
        print(line)
    if supervisor_off():
        register_delivery(c, None)
        print(f"supervisor: not started; start it with {flow_command()} --delivery {args.key} lead-run --resume")
    else:
        require_node(c.release, "plan-open")
        print(f"supervisor: running; live view {start_supervisor(c)}{live_fallback(c.state)}")


def lead_plan_endorse(args) -> None:
    """This checkout's seat endorses the plan at its current commit: plan.endorsed, which lead-init's joint approval
    counts from every admitted approver seat."""
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False) if args.plan else cfg()
    plan = Path(args.plan) if args.plan else c.plan
    shared = shared_record(c, plan)
    if shared is None:
        raise Stop(f"plan.not_shared: {plan} has no shared record; plan-open opens one, and an unshared plan is "
                   "approved as before")
    committed_plan(c, plan)
    record_seat(c, *shared)
    commit = plan_commit(c, plan)
    entry = state_tool_at(c, shared[1], "journal", "--kind", "plan.endorsed", "--data", json.dumps({"commit": commit}))
    print(f"endorsed {plan} at {commit[:12]} (entry {entry['id']})")
    # The planning record's plan shows the endorsement at once; one that can't be rebuilt never undoes it.
    if open_planning_record(c, plan) == shared:
        try:
            said = rebuild_planning_plan(c, plan, *shared)
        except (Stop, OSError, ValueError, subprocess.SubprocessError) as error:
            said = f"not rebuilt: {error}"
        if said:
            print(f"plan view: the planning record of {shared[0]}: {said}")


def state_tool_at(c, folder: Path, *args: str) -> dict:
    """Run the state tool on the record in `folder`; its refusal is this command's, by its code."""
    done = run([sys.executable, "-B", str(c.release / STATE_TOOL), "--dir", str(folder), *args], cwd=c.root,
               check=False)
    said = json.loads(done.stdout) if done.stdout.strip().startswith("{") else {}
    if done.returncode:
        raise Stop(f"{said.get('code', 'state.refused')}: {said.get('error') or done.stderr.strip()[-400:]}")
    return said.get("entry") or said


def key_map(text: str) -> dict[str, str]:
    mapping = {}
    for pair in text.split(","):
        old, equals, new = (part.strip() for part in pair.partition("="))
        if not equals or not old or not new or old in mapping:
            raise Stop(f"plan.map_invalid: --map is OLD=NEW[,OLD=NEW...], each placeholder key once: {text!r}")
        mapping[old] = new
    return mapping


def plan_rekey(args) -> None:
    """The delivery holder replaces the plan's placeholder story keys with tracker keys in one commit, journals
    plan.rekeyed, and syncs it. The re-keying commit may change sections other seats hold; nothing else may."""
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    plan, mapping = Path(args.plan), key_map(args.map)
    shared = shared_record(c, plan)
    if shared is None:
        raise Stop(f"plan.not_shared: {plan} has no shared record; edit an unshared plan's keys as any edit")
    key, folder = shared
    tool, journal, seat = record_seat(c, key, folder)
    if not tool.holds(journal, seat, "delivery"):
        raise Stop(f"scope.not_held: only the holder of delivery, seat {tool.holder(journal, 'delivery')}, re-keys the "
                   f"plan; scope request --scope delivery asks for it")
    committed_plan(c, plan)
    branch = plan_branch(c, plan)
    markdown = _region_ownership()
    try:
        # From the remote's plan, so the re-keying starts from the text peers and plan review have.
        for line in plan_sync.sync(c.root, plan.as_posix(), branch, c.remote, markdown, scope=plan_scope(c, key, folder)):
            print(line)
    except plan_sync.Refused as error:
        raise Stop(str(error)) from None
    before = git("rev-parse", "HEAD", cwd=c.root)
    text = (c.root / plan).read_text(encoding="utf-8")
    changed = plan_sync.rekeyed(text, mapping)
    if changed == text:
        raise Stop(f"plan.rekey_unchanged: {plan} names none of {', '.join(mapping)}")
    (c.root / plan).write_text(changed, encoding="utf-8")
    tool_commit("commit", "-q", "-m", "Re-key the plan's stories: " + ", ".join(f"{old} to {new}" for old, new in mapping.items()),
        "--", plan.as_posix(), cwd=c.root)
    after = git("rev-parse", "HEAD", cwd=c.root)
    rekeying = {"from": before, "to": after, "map": mapping}
    scope = plan_scope(c, key, folder)
    scope.rekeys.append(rekeying)
    try:
        said = plan_sync.sync(c.root, plan.as_posix(), branch, c.remote, markdown, scope=scope)
    except plan_sync.Refused as error:
        # Nothing landed: the branch goes back to where the re-keying started, and nothing is journalled.
        git("reset", "-q", "--keep", before, cwd=c.root)
        raise Stop(f"{error}; the re-keying was undone, so run plan-rekey again") from None
    # Journalled once its commit has landed, so every entry names a re-keying peers have.
    entry = state_tool_at(c, folder, "journal", "--kind", "plan.rekeyed", "--data", json.dumps(rekeying))
    for line in said:
        print(line)
    print(f"re-keyed {plan} at {after[:12]} (entry {entry['id']})")


def joint_approval(c, adoptable: Path | None) -> None:
    """lead-init on a shared record: refused, before anything is written, by the first of D11's rules the plan fails."""
    shared = shared_record(c, c.plan)
    if shared is None:
        return
    tool = _validator()
    journal = tool.read_journal(shared[1])
    rounds = [json.loads(path.read_text()) for path in round_files(adoptable or plan_review_dir(c))] \
        if (adoptable or plan_review_dir(c)).is_dir() else []
    aligned = rounds[-1]["candidate"] if rounds and rounds[-1]["outcome"] == "aligned" else None
    refusal = plan_sync.approval_refusal(journal, tool.derived_seats(journal), plan_commit(c, c.plan), aligned,
                                         lambda commit: plan_sync.shown(c.root, commit, c.plan.as_posix()))
    if refusal is not None:
        raise Stop(str(refusal))


def planning_record(c) -> dict | None:
    """The planning record lead-init adopts in place: this delivery's record, shared, still planning. One opened for
    its plan somewhere the delivery's record isn't is refused: a stateDirectory set elsewhere would start another."""
    opened = planning_record_of(c, c.plan)
    if opened and opened[0] == c.delivery and opened[1].resolve() != c.state.resolve():
        raise Stop(f"collab.record_elsewhere: {c.delivery}'s planning record is at {opened[1]}, but {c.delivery_where} "
                   f"keeps its record at {c.state}; remove its stateDirectory, so lead-init takes the planning record "
                   "over in place")
    record = json_object(c.state / "state.json")
    meta = record.get("meta") or {}
    collab = meta.get("collab") or {}
    return record if collab.get("key") == c.delivery and meta.get("phase") == "planning" else None


# -- joining, feedback and the shared watch stream ------------------------------------------------------------------

# Where a seat keeps what its last join showed: the last journal entry and the plan commit, in its clone's own config.
JOIN_MARK = "agent-skills.joined.{key}"
FEEDBACK_OUTCOMES = ("accepted", "declined", "answered")


def collab_folder(c, key: str) -> Path:
    """Where this checkout keeps the shared record of `key`: where its delivery's record is, once there is one, and
    otherwise apart under the work directory, where plan-open opens a planning record and a seat that joins builds it."""
    d = next((d for d in c.delivery_files().values() if d.get("delivery") == key), None)
    if d is not None:
        found = c.state_of(key, d)
        if os.environ.get("DELIVERY_STATE") or d.get("stateDirectory") or (found / "state.json").is_file():
            return found
    return c.record_apart(key)


def collab_record(c, key: str | None) -> tuple[str, Path]:
    """The shared record a collab command acts on: `key`'s, or the one shared record this checkout keeps."""
    if key is None:
        keys = sorted({k for k, _, _ in planning_records(c)}
                      | {d["delivery"] for d in c.delivery_files().values() if isinstance(d.get("delivery"), str)
                         and (json_object(collab_folder(c, d["delivery"]) / "state.json").get("meta") or {}).get("collab")})
        if len(keys) != 1:
            raise Stop(f"collab.key_needed: this checkout keeps {len(keys)} shared records"
                       + (f" ({', '.join(keys)})" if keys else "") + "; name one with --key")
        key = keys[0]
    folder = collab_folder(c, key)
    if not (folder / "state.json").is_file():
        raise Stop(f"collab.not_joined: this checkout keeps no record of {key}; {flow_command()} collab join --key "
                   f"{key} builds it from the seats' partitions")
    if not (json_object(folder / "state.json").get("meta") or {}).get("collab"):
        raise Stop(f"collab.not_shared: the record of {key} at {folder} is not shared")
    return key, folder


def collab_config(args) -> tuple[object, str, Path]:
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    return (c, *collab_record(c, args.key))


def record_plan(c, key: str, folder: Path) -> Path | None:
    """The plan a shared record is about: its delivery file's, else the one its planning record names."""
    d = next((d for d in c.delivery_files().values() if d.get("delivery") == key), None)
    named = d.get("plan") if d else None
    named = named if isinstance(named, str) else (json_object(folder / "state.json").get("meta") or {}).get("planFile")
    return Path(named) if isinstance(named, str) and named else None


def plan_anchors(c, plan: Path) -> list[str]:
    """The plan's sections, by name as the scope check names them: (preamble), then each heading."""
    lines = (c.root / plan).read_text(encoding="utf-8").splitlines() if (c.root / plan).is_file() else []
    return list(dict.fromkeys(["(preamble)", *(lines[line - 1].strip()
                                               for line in sorted(_region_ownership().markdown_headings(lines)))]))


def seat_labels(journal: list[dict]) -> dict[str, str]:
    return {seat: held["label"] for seat, held in _validator().derived_seats(journal).items()}


def collab_join(args) -> None:
    """D2's join: build this checkout's record from the admitted seats' partitions, start its supervisor, then give
    it a seat that asks to be admitted. Every join prints what is new since this seat's last: the story, the plan's
    change, open feedback, and the scopes it holds."""
    global CFG
    c = CFG = Config(repo(), need_delivery=False, pick=False)
    key = args.key
    if not re.fullmatch(PLAN_KEY, key):
        raise Stop(f"collab.key_invalid: {key!r} isn't a delivery key such as WORK-123")
    folder = collab_folder(c, key)
    tool = _validator()
    link = tool._collab()
    try:
        link.fetch(folder, remote=c.remote, key=key)
        link.ingest(folder, key=None if (folder / "state.json").is_file() else key)
    except tool.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    if not (json_object(folder / "state.json").get("meta") or {}).get("collab"):
        raise Stop(f"collab.not_shared: the record of {key} at {folder} is not shared")
    # The supervisor's sync loop carries what this checkout writes from here on, its request among it.
    c = CFG = Config(repo(), key)
    held, running = read_lock(supervisor_lock_path(c))
    if held:
        print(f"supervisor: running (pid {running.get('pid')})")
    elif supervisor_off():
        register_delivery(c, None)
        print(f"supervisor: not started; start it with {flow_command()} --delivery {key} lead-run --resume")
    else:
        require_node(c.release, "collab join")
        print(f"supervisor: running; live view {start_supervisor(c)}{live_fallback(c.state)}")
    journal = tool.read_journal(folder)
    seat = tool.local_seat(folder, key)
    if not (tool.derived_seats(journal).get(seat or "") or {}).get("admitted"):
        try:
            link.request_seat(folder, label=args.label)
        except tool.StateError as error:
            raise Stop(f"{error.code}: {error}") from None
        seat = tool.local_seat(folder, key)
        journal = tool.read_journal(folder)
        print(f"joined {key} as seat {seat} ({seat_labels(journal).get(seat, seat)}): it waits to be admitted; the "
              f"delivery holder, seat {tool.holder(journal, 'delivery')}, admits it with {flow_command()} collab admit "
              f"--seat {seat} --key {key}")
    else:
        print(f"joined {key} as seat {seat} ({seat_labels(journal).get(seat, seat)}), admitted")
    mark = git("config", "--local", "--get", JOIN_MARK.format(key=key), cwd=c.root, check=False).split()
    after = int(mark[0]) if mark and mark[0].isdigit() else 0
    lines, current = catch_up(c, key, folder, journal, seat, after, mark[1] if len(mark) > 1 else None)
    for line in lines:
        print(line)
    # What was shown, and only that: an entry the sync loop ingests meanwhile, or a plan commit pushed meanwhile, is new
    # to the next join.
    if current and (tool.derived_seats(journal).get(seat) or {}).get("admitted") and current != last_seen(journal, seat):
        state_tool_at(c, folder, "journal", "--kind", "plan.seen", "--data", json.dumps({"commit": current}))
    git("config", "--local", JOIN_MARK.format(key=key), f"{journal[-1]['id'] if journal else 0} {current or '-'}",
        cwd=c.root)


def last_seen(journal: list[dict], seat: str | None) -> str | None:
    """The plan commit this seat last journalled reading."""
    return next((entry["data"]["commit"] for entry in reversed(journal) if entry["kind"] == "plan.seen"
                 and (entry.get("origin") or {}).get("seat") == seat), None)


def shared_plan_commit(c, key: str, plan: Path) -> str | None:
    """The plan's current commit on its shared branch, fetched, or on HEAD where the remote has no such branch."""
    try:
        branch = plan_branch(c, plan)
    except Stop:
        return None
    if run(["git", "fetch", "-q", c.remote, branch], cwd=c.root, check=False).returncode == 0:
        found = git("rev-list", "-1", "FETCH_HEAD", "--", plan.as_posix(), cwd=c.root, check=False)
        if found:
            return found
    return git("rev-list", "-1", "HEAD", "--", plan.as_posix(), cwd=c.root, check=False) or None


def catch_up(c, key: str, folder: Path, journal: list[dict], seat: str | None, after: int,
             marked: str | None) -> tuple[list[str], str | None]:
    """What a join prints, in this order: the story since entry `after`, the plan's change since this seat last read
    it, the feedback still open that was raised since, and the scopes this seat holds; with the plan commit shown."""
    tool = _validator()
    import narrator
    labels = seat_labels(journal)
    story = narrator.narrate(journal, tool.read_state(folder))
    lines, by_id = [], {entry["id"]: entry for entry in journal}
    for beat in story["beats"]:
        # Each entry once, in its own beat's words or, in a run of bookkeeping, its item's; a thread's beat retells.
        if beat["form"] == "thread":
            continue
        told = [(item["entry"], item["words"]) for item in beat["items"]] or [(beat["entries"][0], beat["words"])]
        lines += [f"  #{entry} {narrator._sentence(words['head'])}" + (f" {narrator._sentence(words['line'])}"
                                                                        if words["line"] else "")
                  for entry, words in told if entry > after and not own_reading(by_id[entry], seat)]
    said = ["story:" + ("" if lines else " nothing new"), *lines]
    plan = record_plan(c, key, folder)
    current = None
    if plan is None:
        said.append("plan: none named yet")
    else:
        current = shared_plan_commit(c, key, plan)
        base = last_seen(journal, seat) or (marked if marked and marked != "-" else None)
        if current is None:
            said.append(f"plan: {plan} has no commit here yet")
        elif base is None:
            text = git("show", f"{current}:{plan.as_posix()}", cwd=c.root, check=False)
            said.append(f"plan: {plan} at {current[:12]}, new to this seat ({len(text.splitlines())} lines)")
        elif base == current:
            said.append(f"plan: {plan} unchanged since {base[:12]}")
        else:
            diff = git("diff", base, current, "--", plan.as_posix(), cwd=c.root, check=False)
            said += [f"plan: {plan} changed since {base[:12]}, now at {current[:12]}:",
                     *(f"  {line}" for line in diff.splitlines())]
    still = plan_sync.open_feedback(journal)
    fresh = [entry for entry in still if entry["id"] > after]
    said.append("open feedback:" + ("" if fresh else " none" if not still else f" none new ({len(still)} still open)"))
    for entry in fresh:
        writer = labels.get((entry.get("origin") or {}).get("seat"), "a seat")
        said.append(f"  #{entry['id']} on {entry['data']['anchor']}"
                    + (", stopping approval" if entry["data"].get("blocking") else "")
                    + f", by {writer}: {entry['data']['text']}")
    said.append(f"scopes held: {held_scopes(journal, seat)}")
    return said, current


def own_reading(entry: dict, seat: str | None) -> bool:
    """A seat's own plan.seen, which records a join's reading rather than telling it anything new."""
    return entry["kind"] == "plan.seen" and (entry.get("origin") or {}).get("seat") == seat


def held_scopes(journal: list[dict], seat: str | None) -> str:
    """The scopes `seat` holds, in words."""
    tool = _validator()
    _, passed = tool.scope_register(journal)
    names = [name for name in ("delivery", "queue") if tool.holds(journal, seat, name)]
    names += sorted(name for name, holder in passed.items() if holder == seat and name not in names)
    if not names:
        return "none"
    return ", ".join(names) + (", and every plan section not passed on" if "delivery" in names else "")


def collab_feedback(args) -> None:
    """Feedback on the plan, a fact every seat sees: raised on one of its sections, and settled only by the holder of
    that section."""
    c, key, folder = collab_config(args)
    tool, journal, seat = record_seat(c, key, folder)
    if args.feedback_action == "add":
        plan = record_plan(c, key, folder)
        sections = plan_anchors(c, plan) if plan else []
        if args.anchor not in sections:
            raise Stop(f"feedback.anchor_unknown: {args.anchor!r} isn't a section of {plan or 'the plan'}; feedback is "
                       f"on one of: {', '.join(sections) or 'none'}")
        entry = state_tool_at(c, folder, "journal", "--kind", "feedback.raised", "--data",
                              json.dumps({"anchor": args.anchor, "text": args.text, "blocking": args.blocking}))
        print(f"feedback {entry['id']} on {args.anchor}" + (", stopping approval" if args.blocking else ""))
        return
    raised = next((entry for entry in journal if entry["id"] == args.id and entry["kind"] == "feedback.raised"), None)
    if raised is None:
        raise Stop(f"feedback.unknown: journal entry {args.id} is not a feedback.raised")
    settled = next((entry for entry in journal if entry["kind"] == "feedback.resolved"
                    and args.id in entry.get("answers", [])), None)
    if settled is not None:
        raise Stop(f"feedback.settled: feedback {args.id} was settled by entry {settled['id']} "
                   f"({settled['data']['outcome']})")
    scope = f"plan:{raised['data']['anchor']}"
    if not tool.holds(journal, seat, scope):
        holder = tool.holder(journal, scope)
        raise Stop(f"scope.not_held: only the holder of {scope}, seat {holder} ({seat_labels(journal).get(holder, holder)}), "
                   f"settles feedback on it; {flow_command()} collab request --scope {shlex.quote(scope)} --reason TEXT "
                   "asks for it")
    entry = state_tool_at(c, folder, "journal", "--kind", "feedback.resolved", "--answers", str(args.id), "--data",
                          json.dumps({"outcome": args.outcome, "reason": args.reason}))
    print(f"feedback {args.id} settled ({args.outcome}) by entry {entry['id']}")


def collab_scope(args) -> None:
    """The state tool's scope and seat commands, on this checkout's shared record."""
    c, key, folder = collab_config(args)
    if args.collab_action == "give" and args.scope.startswith("lane:"):
        left = lane_checkouts_left(c, folder, args.scope[len("lane:"):])
        tool = _validator(c.release)
        if left and tool.holds(tool.read_journal(folder), tool.local_seat(folder, key), args.scope):
            raise Stop(f"scope.handover_busy: {args.scope} still has the checkout of {', '.join(left)} on this machine, "
                       f"merged or settled; {flow_command()} lead-cleanup removes it, then hand the lane over")
    if args.collab_action == "give" and args.scope == "delivery":
        entry = give_delivery(c, key, folder, args.to, args.wait)
        print(f"{entry['kind']} (entry {entry['id']}): {json.dumps(entry['data'], sort_keys=True)}")
        return
    if args.collab_action == "give":
        argv = ["scope", "give", "--scope", args.scope, "--to", args.to, "--wait", str(args.wait)]
    elif args.collab_action == "request":
        argv = ["scope", "request", "--scope", args.scope, "--reason", args.reason]
    else:
        argv = ["seat", "admit", "--seat", args.seat, *(["--no-approver"] if args.no_approver else [])]
    entry = state_tool_at(c, folder, *argv)
    print(f"{entry['kind']} (entry {entry['id']}): {json.dumps(entry['data'], sort_keys=True)}")


def collab_label(args) -> None:
    """Change the label this checkout's seat shows; display only."""
    c, key, folder = collab_config(args)
    tool = _validator()
    try:
        entry = tool._collab().label_seat(folder, args.label)
    except tool.StateError as error:
        raise Stop(f"{error.code}: {error}") from None
    print(f"seat {entry['data']['seat']} is now shown as {entry['data']['label']} (entry {entry['id']})")


def collab_watch(args) -> None:
    """D9 over the shared record: one flushed line per peer entry the sync loop ingests, and nothing else. It reads
    the local record and writes nothing."""
    c, key, folder = collab_config(args)
    settings = collab_settings(c)
    try:
        until = re.compile(args.until) if args.until is not None else None
    except re.error as error:
        raise Stop(f"--until {args.until!r} isn't a regular expression: {error}") from None
    if args.timeout < 0:
        raise Stop(f"--timeout must be zero or more seconds, not {args.timeout:g}")
    tool = _validator()
    import journal_words
    registry = journal_words.load_registry()
    seat = tool.local_seat(folder, key)
    journal = tool.read_journal(folder)
    through = journal[-1]["id"] if journal else 0
    deadline = time.monotonic() + args.timeout
    while True:
        journal = tool.read_journal(folder)
        labels = seat_labels(journal)
        for entry in journal:
            if entry["id"] <= through:
                continue
            through = entry["id"]
            writer = (entry.get("origin") or {}).get("seat")
            if writer is None or writer == seat:
                continue
            words = journal_words.words(entry, registry)
            head = words["head"].rstrip()
            line = (f"#{entry['id']} {entry['kind']} by {labels.get(writer, writer)}: "
                    f"{head if head[-1:] in '.!?' else head + '.'}" + (f" {words['line']}" if words["line"] else ""))
            print(line, flush=True)
            if until is not None and until.search(line):
                return
        left = deadline - time.monotonic()
        if left <= 0:
            if until is not None:
                sys.exit(3)
            return
        time.sleep(min(settings["pollSeconds"], left))


def doctor(args) -> None:
    """Check this repository's setup for a delivery: every missing prerequisite, and how to fix it."""
    global OFFLINE
    OFFLINE = args.offline
    sys.exit(0 if Doctor(args).run() else 1)


